static bool RunLogPrivacyDiagnostics()
{
    Console.WriteLine("User log privacy diagnostics");

    var log = new RuntimeLogService();
    var viewModel = new LogPanelViewModel(log);

    log.Warn(
        "RoleSession",
        @"Command failed: C:\Program Files\TLBB Agent\models\combat.onnx PID=4412 HWND=0xCAFE token=private-value",
        "0xCAFE");
    log.Info(
        "按键打怪",
        "目标=测试怪物 人物血=87 宠物血=64 样本=monster/template score=0.934 坐标 812,1038",
        "0xCAFE");
    log.Info("Profile", "方案已加载：日常挂机。");
    log.Info("Profile", "已加载配置方案：shout-方案-0621-0916");
    log.Log(new LogEntry
    {
        Level = LogLevel.Warn,
        Module = "CustomInternalModule",
        Window = "HWND=0xBEEF",
        Message = @"读取 \\server\share\model.json 失败，APIKey=super-secret，位置 [12,34,56,78]。",
        Audience = LogAudience.User,
        UserSummary = @"读取 \\server\share\model.json 失败，APIKey=super-secret，位置 [12,34,56,78]。"
    });
    log.Warn("喊话", "喊话队列异常：Object reference not set to an instance of an object.");
    log.Trace("VisionV2", "frame latency=12ms confidence=0.998 model version=v2");

    var entries = log.Entries;
    var visible = viewModel.Entries.ToArray();
    var panelExport = viewModel.BuildVisibleExportText();
    var coreExport = log.ExportToText();
    var combined = string.Join('\n', visible.Select(entry => entry.Message)) + "\n" + panelExport + "\n" + coreExport;
    var forbidden = new[]
    {
        "C:\\", "\\\\server", ".onnx", ".json", "RoleSession", "CustomInternalModule",
        "PID", "HWND", "0xCAFE", "0xBEEF", "token", "private-value", "APIKey", "super-secret",
        "812,1038", "[12,34,56,78]", "样本=", "score=", "confidence=", "VisionV2",
        "shout-方案", "_app-state", "TlbbAgent.App.ViewModels", "Object reference"
    };
    var leaked = forbidden.Where(token => combined.Contains(token, StringComparison.OrdinalIgnoreCase)).ToArray();

    var warningProjected = entries[0].Audience == LogAudience.User
                           && !string.IsNullOrWhiteSpace(entries[0].UserSummary)
                           && !string.IsNullOrWhiteSpace(entries[0].DebugDetails);
    var technicalInfoHidden = entries[1].Audience == LogAudience.Diagnostic
                              && visible.All(entry => !entry.Message.Contains("测试怪物", StringComparison.Ordinal));
    var safeEventPreserved = visible.Any(entry => entry.Message == "方案已加载：日常挂机。");
    var internalProfileHidden = entries[3].Audience == LogAudience.Diagnostic;
    var explicitUserRechecked = entries[4].Audience == LogAudience.User
                                && entries[4].UserSummary == "当前操作未完成，请稍后重试。";
    var exceptionMessageHidden = entries[5].Audience == LogAudience.User
                                 && entries[5].UserSummary == "喊话任务未完成，请稍后重试。";
    var exportMatchesVisible = panelExport == string.Concat(visible.Select(entry => entry.ToExportLine() + Environment.NewLine));
    var noRawAudienceFallback = visible.Length == 4 && leaked.Length == 0;

    Console.WriteLine($"warning projected={warningProjected}");
    Console.WriteLine($"technical info hidden={technicalInfoHidden}");
    Console.WriteLine($"safe event preserved={safeEventPreserved}");
    Console.WriteLine($"internal profile hidden={internalProfileHidden}");
    Console.WriteLine($"explicit user rechecked={explicitUserRechecked}");
    Console.WriteLine($"exception message hidden={exceptionMessageHidden}");
    Console.WriteLine($"visible export bounded={exportMatchesVisible}");
    Console.WriteLine($"leaks={(leaked.Length == 0 ? "none" : string.Join(',', leaked))}");

    var ok = warningProjected
             && technicalInfoHidden
             && safeEventPreserved
             && internalProfileHidden
             && explicitUserRechecked
             && exceptionMessageHidden
             && exportMatchesVisible
             && noRawAudienceFallback;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunCombatLoopLogDiagnostics(string[] args)
{
    Console.WriteLine("Combat loop log diagnostics");

    var path = GetOption(args, "--path");
    var tailText = GetOption(args, "--tail");
    var includeLegacy = HasFlag(args, "--include-legacy");
    var tail = int.TryParse(tailText, out var parsedTail) ? Math.Clamp(parsedTail, 1, 200000) : 1000;

    if (string.IsNullOrWhiteSpace(path))
    {
        var appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
        var logDirs = new[]
        {
            Path.Combine(appData, ProductIdentity.DataFolderName, "logs"),
            Path.Combine(appData, ProductIdentity.LegacyDataFolderName, "logs")
        };
        path = logDirs
            .Where(Directory.Exists)
            .SelectMany(logDir => Directory.GetFiles(logDir, "combat-loop-*.jsonl"))
            .OrderByDescending(File.GetLastWriteTime)
            .FirstOrDefault();
    }

    if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
    {
        Console.Error.WriteLine("FAIL: 未找到 combat-loop jsonl。请先运行一次打怪，或使用 --path 指定文件。");
        return false;
    }

    var lines = File.ReadLines(path)
        .Where(line => !string.IsNullOrWhiteSpace(line))
        .TakeLast(tail)
        .ToArray();

    var parsedRows = new List<(JsonObject Row, CombatLoopTelemetryEntry Entry)>();
    var telemetryJsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        PropertyNameCaseInsensitive = true
    };
    foreach (var line in lines)
    {
        try
        {
            if (JsonNode.Parse(line) is JsonObject obj)
            {
                var entry = System.Text.Json.JsonSerializer.Deserialize<CombatLoopTelemetryEntry>(line, telemetryJsonOptions);
                if (entry is not null)
                    parsedRows.Add((obj, entry));
            }
        }
        catch
        {
            // Skip malformed partial lines from a concurrently written file.
        }
    }

    if (parsedRows.Count == 0)
    {
        Console.Error.WriteLine($"FAIL: 文件没有可解析遥测行：{path}");
        return false;
    }

    var currentRows = parsedRows
        .Where(row => row.Entry.SchemaVersion >= 2)
        .ToArray();
    var selectedRows = !includeLegacy && currentRows.Length > 0
        ? currentRows
        : parsedRows.ToArray();
    var rows = selectedRows.Select(row => row.Row).ToList();
    var entries = selectedRows.Select(row => row.Entry).ToList();
    var legacyRows = parsedRows.Count(row => row.Entry.SchemaVersion < 2);

    Console.WriteLine($"File: {path}");
    Console.WriteLine($"Rows: {rows.Count} analyzed (tail={tail}, parsed={parsedRows.Count})");
    if (!includeLegacy && currentRows.Length > 0 && currentRows.Length < parsedRows.Count)
        Console.WriteLine($"Schema filter: using current schema rows {currentRows.Length}/{parsedRows.Count}; legacy rows ignored by default. Pass --include-legacy to include history.");
    else if (includeLegacy)
        Console.WriteLine($"Schema filter: disabled by --include-legacy; legacy rows in scope={legacyRows}.");
    Console.WriteLine($"Time: {RowValue(rows.First(), "Time")} -> {RowValue(rows.Last(), "Time")}");
    Console.WriteLine();

    var health = CombatLoopHealthAnalyzer.Analyze(entries);
    PrintTop("Decision", health.DecisionCounts);
    PrintTop("AttackResult", health.AttackResultCounts);
    PrintTop("TargetSampleKind", health.TargetSampleKindCounts);
    PrintTop("TargetStructure", health.TargetStructureCounts);
    PrintTop("Event", health.EventCounts);

    Console.WriteLine("Signals");
    Console.WriteLine($"  rows={health.TotalRows}, legacySchema={health.LegacySchemaCount}");
    Console.WriteLine($"  decisions={health.DecisionCount}, actions={health.ActionCount}");
    Console.WriteLine($"  sentAttack={health.SentAttackCount}, waiting={health.WaitingCount}, sendFailed={health.SendFailedCount}, noAttackAction={health.NoAttackActionCount}");
    Console.WriteLine($"  protection={health.ProtectionCount}, ambiguousProtection={health.AmbiguousProtectionCount}, protectionWithoutSample={health.ProtectionWithoutSampleCount}");
    Console.WriteLine($"  weakOnly={health.WeakOnlyCount}, weakNoStructure={health.WeakNoStructureCount}, sampleEmpty={health.SampleEmptyCount}");
    Console.WriteLine();

    Console.WriteLine("Diagnosis");
    foreach (var item in health.Findings)
        Console.WriteLine($"  - [{item.Severity}] {item.Code}: {item.Message}");
    Console.WriteLine();

    Console.WriteLine("Recent");
    foreach (var row in rows.TakeLast(12))
    {
        var eventName = RowValue(row, "Event");
        var decision = RowValue(row, "Decision");
        var attack = RowValue(row, "AttackResult");
        var target = RowValue(row, "TargetName");
        var hp = RowValue(row, "TargetHp");
        var sample = RowValue(row, "TargetSampleKind");
        var structure = StructureValue(row);
        var player = BoolValue(row, "TargetLooksLikePlayer") ? " player" : "";
        var pet = BoolValue(row, "TargetLooksLikePet") ? " pet" : "";
        var ambiguous = BoolValue(row, "TargetProtectionAmbiguous") ? " ambiguous" : "";
        Console.WriteLine($"  {RowValue(row, "Time")} {eventName} decision={Blank(decision)} attack={Blank(attack)} target={Blank(target)} hp={Blank(hp)} sample={Blank(sample)} structure={structure}{player}{pet}{ambiguous}");
    }

    return true;
}

static bool RunSkillCooldownDiagnostics()
{
    Console.WriteLine("Skill cooldown diagnostics");

    var window = DiagnosticWindow(new nint(4210), "diagnostic-skill-cooldown", 1920, 1080);
    var config = new GlobalConfig
    {
        SkillCooldownRecognitionEnabled = true,
        SkillCooldownProbeIntervalMs = 100,
        SkillCooldownReadyDebounceMs = 350
    };
    var skill = new SkillPreset
    {
        Name = "cooldown-diagnostic",
        Hotkey = "Q",
        Enabled = true,
        IntervalMs = 0,
        Cooldown = new SkillCooldownSlotConfig
        {
            Enabled = true,
            Width = 36,
            Height = 36,
            ReadyTemplateThreshold = 0.90
        }
    };

    var readyService = new SkillCooldownRecognitionService(
        new StaticSkillCooldownPerceptionHub(VisionCooldownState.Ready, 0.98, "ready"));
    var captured = readyService.TryCaptureReadyTemplate(window, skill, config, out var captureInspection, out var captureError);
    var ready = readyService.Inspect(window, skill, config);

    var cooldownService = new SkillCooldownRecognitionService(
        new StaticSkillCooldownPerceptionHub(VisionCooldownState.Cooling, 0.97, "cooling"));
    var cooldown = cooldownService.Inspect(window, skill, config);

    var changedService = new SkillCooldownRecognitionService(
        new StaticSkillCooldownPerceptionHub(VisionCooldownState.Unknown, 0.42, "uncertain"));
    var changed = changedService.Inspect(window, skill, config);

    Console.WriteLine($"Captured={captured}, error={Blank(captureError)}, capture={captureInspection.Readiness}/{captureInspection.Reason}");
    Console.WriteLine($"Ready={ready.Readiness}/{ready.Reason}, confidence={ready.TemplateSimilarity:0.000}, slot={ready.X},{ready.Y},{ready.Width}x{ready.Height}");
    Console.WriteLine($"Cooldown={cooldown.Readiness}/{cooldown.Reason}, confidence={cooldown.TemplateSimilarity:0.000}");
    Console.WriteLine($"Unknown={changed.Readiness}/{changed.Reason}, confidence={changed.TemplateSimilarity:0.000}");

    var ok = captured
             && string.IsNullOrEmpty(captureError)
             && ready.Readiness == SkillCooldownReadiness.Ready
             && ready.TemplateSimilarity >= 0.9
             && ready.Width == 36
             && ready.Height == 36
             && cooldown.Readiness == SkillCooldownReadiness.Cooldown
             && cooldown.TemplateSimilarity >= 0.9
             && changed.Readiness == SkillCooldownReadiness.Unknown;
    if (!ok)
    {
        Console.Error.WriteLine("FAIL: 技能 CD 适配器必须正确映射 Vision V2 的 Ready、Cooling 和 Unknown 槽位状态。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static void PrintTop(string title, IReadOnlyDictionary<string, int> values)
{
    Console.WriteLine(title);
    if (values.Count == 0)
    {
        Console.WriteLine("  (none)");
        Console.WriteLine();
        return;
    }

    foreach (var item in values.Take(8))
        Console.WriteLine($"  {item.Value,5}  {item.Key}");
    Console.WriteLine();
}

static string? GetOption(string[] args, string name)
{
    for (var i = 0; i < args.Length; i++)
    {
        if (!string.Equals(args[i], name, StringComparison.OrdinalIgnoreCase))
            continue;

        return i + 1 < args.Length ? args[i + 1] : "";
    }

    return null;
}

static string RowValue(JsonObject row, string name)
{
    if (!row.TryGetPropertyValue(name, out var node) || node is null)
        return string.Empty;

    return node.GetValueKind() switch
    {
        JsonValueKind.String => node.GetValue<string>() ?? string.Empty,
        JsonValueKind.Number => node.ToJsonString(),
        JsonValueKind.True => "true",
        JsonValueKind.False => "false",
        _ => node.ToJsonString()
    };
}

static bool BoolValue(JsonObject row, string name) =>
    bool.TryParse(RowValue(row, name), out var value) && value;

static string Blank(string value) => string.IsNullOrWhiteSpace(value) ? "-" : value;

static string StructureValue(JsonObject row)
{
    var parts = new List<string>();
    if (BoolValue(row, "TargetHasSchoolMarker"))
        parts.Add("school");
    if (BoolValue(row, "TargetHasPlayerPortrait"))
        parts.Add("portrait");
    if (BoolValue(row, "TargetHasPlayerStatusBars"))
        parts.Add("bars");
    return parts.Count == 0 ? "none" : string.Join("+", parts);
}

static string TargetStructureText(CombatRecognitionResult combat)
{
    var parts = new List<string>();
    if (combat.TargetHasSchoolMarker)
        parts.Add("school");
    if (combat.TargetHasPlayerPortrait)
        parts.Add("portrait");
    if (combat.TargetHasPlayerStatusBars)
        parts.Add("bars");
    return parts.Count == 0 ? "none" : string.Join("+", parts);
}

