static async Task<bool> RunRecoveryModeDiagnostics()
{
    Console.WriteLine("Recovery mode diagnostics");

    var persistenceProfiles = new MemoryProfileService();
    var persistenceLog = new RuntimeLogService();
    var defaultConfig = new GlobalConfigService(persistenceProfiles, persistenceLog);
    var defaultsOk = defaultConfig.Current.HealthRecoveryMode == PlayerHealthRecoveryMode.Symbiosis
                     && defaultConfig.Current.ManaRecoveryMode == PlayerManaRecoveryMode.BloodSacrifice;
    defaultConfig.Save("recovery-defaults");

    var defaultReload = new GlobalConfigService(persistenceProfiles, persistenceLog);
    var defaultReloaded = defaultReload.Load("recovery-defaults");
    defaultsOk = defaultsOk
                 && defaultReloaded
                 && defaultReload.Current.HealthRecoveryMode == PlayerHealthRecoveryMode.Symbiosis
                 && defaultReload.Current.ManaRecoveryMode == PlayerManaRecoveryMode.BloodSacrifice;
    Console.WriteLine($"Default/reload health={defaultReload.Current.HealthRecoveryMode}, mana={defaultReload.Current.ManaRecoveryMode} => {(defaultsOk ? "PASS" : "FAIL")}");

    defaultReload.Current.HealthRecoveryMode = PlayerHealthRecoveryMode.Medicine;
    defaultReload.Current.ManaRecoveryMode = PlayerManaRecoveryMode.Medicine;
    defaultReload.Current.RecoveryModesExplicitlyConfigured = true;
    defaultReload.Save("recovery-user-choice");

    var userChoiceReload = new GlobalConfigService(persistenceProfiles, persistenceLog);
    var userChoiceLoaded = userChoiceReload.Load("recovery-user-choice");
    var userChoiceOk = userChoiceLoaded
                       && userChoiceReload.Current.HealthRecoveryMode == PlayerHealthRecoveryMode.Medicine
                       && userChoiceReload.Current.ManaRecoveryMode == PlayerManaRecoveryMode.Medicine
                       && userChoiceReload.Current.RecoveryModesExplicitlyConfigured;
    Console.WriteLine($"Explicit user choice health={userChoiceReload.Current.HealthRecoveryMode}, mana={userChoiceReload.Current.ManaRecoveryMode} => {(userChoiceOk ? "PASS" : "FAIL")}");

    var medicineLog = new RuntimeLogService();
    var medicineGlobal = new TestGlobalConfigService();
    var medicineInput = new CountingInputService();
    medicineGlobal.Current.AttackHotkey = "F1";
    medicineGlobal.Current.PublicCooldownMs = 0;
    medicineGlobal.Current.Targeting.ScanIntervalMs = 50;
    medicineGlobal.Current.HealthRecoveryMode = PlayerHealthRecoveryMode.Medicine;
    medicineGlobal.Current.ManaRecoveryMode = PlayerManaRecoveryMode.Medicine;
    medicineGlobal.Current.HealHotkey = "F4";
    medicineGlobal.Current.ManaHotkey = "F5";
    medicineGlobal.Current.PetFoodHotkey = "F6";
    medicineGlobal.Current.HpThresholdPct = 70;
    medicineGlobal.Current.MpThresholdPct = 70;
    medicineGlobal.Current.PetFoodThresholdPct = 50;
    medicineGlobal.Current.Skills.Clear();
    var medicineRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "40", "30", "90", 80, 40, 30, 90));
    var medicineController = new NormalHangController(
        medicineLog,
        medicineGlobal,
        CreateCombatBackendSelector(medicineLog, medicineInput, medicineRecognition),
        new StaticReturnPointRuntimeService(),
        new StateMachineEngine(medicineLog));
    medicineController.Attach(DiagnosticWindow(new nint(8101), "recovery-medicine", 1920, 1080));
    medicineController.Start();
    await Task.Delay(420);
    medicineController.Stop();

    var medicineHp = medicineInput.SentHotkeys.Count(h => h == "F4");
    var medicineMp = medicineInput.SentHotkeys.Count(h => h == "F5");
    var petFood = medicineInput.SentHotkeys.Count(h => h == "F6");
    var medicineOk = medicineHp == 1 && medicineMp == 0 && petFood == 0;
    Console.WriteLine($"Medicine HP/MP/PetFood={medicineHp}/{medicineMp}/{petFood} => {(medicineOk ? "PASS" : "FAIL")}");

    var petSkillLog = new RuntimeLogService();
    var petSkillGlobal = new TestGlobalConfigService();
    var petSkillInput = new CountingInputService();
    petSkillGlobal.Current.AttackHotkey = "F1";
    petSkillGlobal.Current.PublicCooldownMs = 0;
