    var petSkillController = new NormalHangController(
        petSkillLog,
        petSkillGlobal,
        CreateCombatBackendSelector(petSkillLog, petSkillInput, petSkillRecognition),
        new StaticReturnPointRuntimeService(),
        new StateMachineEngine(petSkillLog));
    petSkillController.Attach(DiagnosticWindow(new nint(8102), "recovery-pet-skills", 1920, 1080));
    petSkillController.Start();
    await Task.Delay(420);
    petSkillController.Stop();

    var forbiddenMedicine = petSkillInput.SentHotkeys.Count(h => h is "F4" or "F5");
    var symbiosisLogs = petSkillLog.Entries.Count(e => e.Message.Contains("共生回血触发", StringComparison.Ordinal));
    var bloodLogs = petSkillLog.Entries.Count(e => e.Message.Contains("血迹回蓝触发", StringComparison.Ordinal));
