                      && petSkillInput.ClickCount == 2
                      && symbiosisLogs == 1
                      && bloodLogs == 1;
    Console.WriteLine($"PetSkill forbiddenMedicine/clicks/symbiosis/blood={forbiddenMedicine}/{petSkillInput.ClickCount}/{symbiosisLogs}/{bloodLogs} => {(petSkillsOk ? "PASS" : "FAIL")}");

    var latchLog = new RuntimeLogService();
    var latchGlobal = new TestGlobalConfigService();
    var latchInput = new CountingInputService();
    latchGlobal.Current.AttackHotkey = "F1";
    latchGlobal.Current.PublicCooldownMs = 0;
    latchGlobal.Current.Targeting.ScanIntervalMs = 50;
    latchGlobal.Current.HealHotkey = "";
    latchGlobal.Current.ManaHotkey = "";
    latchGlobal.Current.PetFoodHotkey = "F6";
    latchGlobal.Current.PetFoodThresholdPct = 50;
    latchGlobal.Current.Skills.Clear();
    var latchRecognition = new QueuedCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "90", "90", "20", 80, 90, 90, 20),
        new CombatRecognitionResult("木桩", "78", "90", "90", "30", 78, 90, 90, 30),
        new CombatRecognitionResult("木桩", "76", "90", "90", "40", 76, 90, 90, 40),
        new CombatRecognitionResult("木桩", "74", "90", "90", "55", 74, 90, 90, 55),
        new CombatRecognitionResult("木桩", "72", "90", "90", "70", 72, 90, 90, 70),
        new CombatRecognitionResult("木桩", "70", "90", "90", "85", 70, 90, 90, 85),
        new CombatRecognitionResult("木桩", "68", "90", "90", "99", 68, 90, 90, 99));
    var latchController = new NormalHangController(
        latchLog,
        latchGlobal,
        CreateCombatBackendSelector(latchLog, latchInput, latchRecognition),
        new StaticReturnPointRuntimeService(),
        new StateMachineEngine(latchLog));
    latchController.Attach(DiagnosticWindow(new nint(8103), "recovery-pet-food-latch", 1920, 1080));
    latchController.Start();
    await Task.Delay(900);
    latchController.Stop();

    var latchStart = latchLog.Entries.Count(e => e.Message.Contains("宠物恢复开始", StringComparison.Ordinal));
    var latchComplete = latchLog.Entries.Count(e => e.Message.Contains("宠物恢复完成", StringComparison.Ordinal));
    var latchFood = latchInput.SentHotkeys.Count(h => h == "F6");
    var latchOk = latchStart == 1 && latchComplete == 1 && latchFood >= 2;
    Console.WriteLine($"PetFood latch start/complete/hotkeys={latchStart}/{latchComplete}/{latchFood} => {(latchOk ? "PASS" : "FAIL")}");

    return defaultsOk && userChoiceOk && medicineOk && petSkillsOk && latchOk;
}

static bool RunHotkeyRecorderDiagnostics()
{
    Console.WriteLine("HotkeyRecorder diagnostics");

    var checks = new (string Name, bool Ok)[]
    {
        ("plain F8", HotkeyRecorder.FormatHotkey(Key.F8, ModifierKeys.None) == "F8"),
        ("ctrl F8", HotkeyRecorder.FormatHotkey(Key.F8, ModifierKeys.Control) == "Ctrl+F8"),
        ("alt shift F8", HotkeyRecorder.FormatHotkey(Key.F8, ModifierKeys.Alt | ModifierKeys.Shift) == "Alt+Shift+F8"),
        ("ime processed F8", HotkeyRecorder.ResolveKey(Key.ImeProcessed, Key.None, Key.F8, Key.None) == Key.F8),
        ("system F8", HotkeyRecorder.ResolveKey(Key.System, Key.F8, Key.None, Key.None) == Key.F8),
        ("none ime fallback F8", HotkeyRecorder.ResolveKey(Key.None, Key.None, Key.F8, Key.None) == Key.F8),
        ("numpad 8", HotkeyRecorder.FormatHotkey(Key.NumPad8, ModifierKeys.None) == "Num8")
    };

    foreach (var (name, ok) in checks)
        Console.WriteLine($"{name}: {(ok ? "PASS" : "FAIL")}");

    var input = new InputService(new RuntimeLogService());
    var parseOk = input.TryParseHotkey("F8", out var parseError);
    Console.WriteLine($"input parses F8: {(parseOk ? "PASS" : "FAIL")} {parseError}");

    return checks.All(c => c.Ok) && parseOk;
}

