static bool ScanFrontendClean(out List<string> hits)
{
    var patterns = new[]
    {
        "旧软件", "旧客户端", "旧版", "老版", "BlueDiamond", "蓝钻", "授权数据",
        "xx" + ".dll", "来源路径", "导入自", "C:\\Codex", "C:\\sys", "检测到待转换样本",
        "DVM", "易语言"
    };

    return ScanSourcePatterns(new[] { Path.Combine("src", "TlbbAgent.App") }, patterns, out hits);
}

static bool ScanSourcePatterns(IEnumerable<string> roots, IReadOnlyList<string> patterns, out List<string> hits)
{
    hits = new List<string>();
    foreach (var root in roots.Where(Directory.Exists))
    {
        foreach (var file in Directory.EnumerateFiles(root, "*.*", SearchOption.AllDirectories))
        {
            if (file.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase)
                || file.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase))
                continue;

            var ext = Path.GetExtension(file);
            if (ext is not ".cs" and not ".xaml" and not ".json")
                continue;

            string text;
            try { text = File.ReadAllText(file); }
            catch { continue; }

            foreach (var pattern in patterns)
            {
                if (text.Contains(pattern, StringComparison.OrdinalIgnoreCase))
                    hits.Add($"{file}: {pattern}");
            }
        }
    }

    return hits.Count == 0;
}

static bool CheckPublicDataIndex(out string message)
{
    var index = Path.Combine(Environment.CurrentDirectory, "data", "imported", "index.json");
    if (!File.Exists(index))
    {
        message = "index.json missing";
        return false;
    }

    var text = File.ReadAllText(index);
    var jsonOptions = new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true };
    var items = System.Text.Json.JsonSerializer.Deserialize<List<LegacyImportIndexItem>>(text, jsonOptions) ?? new();
    var clean = !text.Contains("C:\\", StringComparison.OrdinalIgnoreCase)
                && !text.Contains("蓝钻", StringComparison.OrdinalIgnoreCase)
                && !text.Contains("UU", StringComparison.OrdinalIgnoreCase)
                && !text.Contains("授权数据", StringComparison.OrdinalIgnoreCase)
                && !text.Contains("xx" + ".dll", StringComparison.OrdinalIgnoreCase)
                && items.All(i => string.IsNullOrWhiteSpace(i.SourcePath));
    var useful = items.Count > 0 && items.Any(i => i.Status == "available") && items.Any(i => i.DataType.Contains("ocr", StringComparison.OrdinalIgnoreCase));

    message = $"items={items.Count}, clean={clean}, useful={useful}";
    return clean && useful;
}

