        && !string.IsNullOrWhiteSpace(schoolPage.ReadySummary);
    var guildMode = taskTab?.Modes.FirstOrDefault(m => m.Key == "task.guild");
    vm.SelectedTab = taskTab;
    vm.SelectedMode = guildMode;
    var guildPage = vm.CurrentDetail as GuildContributionPageViewModel;
    var guildSummaryReady =
        guildPage is not null
        && !string.IsNullOrWhiteSpace(guildPage.PlanSummary)
        && !string.IsNullOrWhiteSpace(guildPage.RunSummary)
        && !string.IsNullOrWhiteSpace(guildPage.TimingSummary)
        && !string.IsNullOrWhiteSpace(guildPage.CleanupSummary)
        && !string.IsNullOrWhiteSpace(guildPage.ItemSummary)
        && !string.IsNullOrWhiteSpace(guildPage.ReadySummary);
    var quizMode = taskTab?.Modes.FirstOrDefault(m => m.Key == "task.quiz");
    vm.SelectedTab = taskTab;
    vm.SelectedMode = quizMode;
    var quizPage = vm.CurrentDetail as QuestionBankPageViewModel;
    var quizSummaryReady =
        quizPage is not null
        && !string.IsNullOrWhiteSpace(quizPage.BankSummary)
        && !string.IsNullOrWhiteSpace(quizPage.ImportSummary)
        && !string.IsNullOrWhiteSpace(quizPage.EditSummary)
        && !string.IsNullOrWhiteSpace(quizPage.ReadySummary);
    var canStartReturnPointDirectly = vm.Tabs.SelectMany(t => t.Modes).Any(m => m.Key == "hang.return");

    Console.WriteLine($"Tabs={string.Join(",", tabTitles)}");
    Console.WriteLine($"Hang tags={string.Join(",", hangModeKeys)}");
    Console.WriteLine($"Return point hidden={returnPointHidden}");
    Console.WriteLine($"Normal detail={normalDetailName}");
    Console.WriteLine($"Binding details={bindingPanelShowsWindowDetails}");
    Console.WriteLine($"Hang summary={hangSummaryReady}, ready={normalPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Horse summary={horseSummaryReady}, ready={horsePage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Dungeon summary={dungeonSummaryReady}, ready={dungeonPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Npc grab summary={npcSummaryReady}, ready={npcPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Auto rebel summary={rebelSummaryReady}, ready={rebelPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Auto monk summary={monkSummaryReady}, ready={monkPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Trade summary={tradeSummaryReady}, ready={tradePage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Craft summary={craftSummaryReady}, ready={craftPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Treasure map summary={treasureSummaryReady}, ready={treasurePage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Life collect summary={lifeCollectSummaryReady}, ready={lifeCollectPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"School task summary={schoolSummaryReady}, ready={schoolPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Guild contribution summary={guildSummaryReady}, ready={guildPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Question bank summary={quizSummaryReady}, ready={quizPage?.ReadySummary ?? "-"}");
    Console.WriteLine($"Open global works={globalNavigationWorks}");
    Console.WriteLine($"Controller state sync={hasControllerStateSync}");

    var ok = hasExpectedTabs
             && returnPointHidden
             && normalUsesIntegratedPage
             && !canStartReturnPointDirectly
             && bindingPanelShowsWindowDetails
             && hangSummaryReady
             && horseSummaryReady
             && dungeonSummaryReady
             && npcSummaryReady
             && rebelSummaryReady
             && monkSummaryReady
             && tradeSummaryReady
             && craftSummaryReady
             && treasureSummaryReady
             && lifeCollectSummaryReady
             && schoolSummaryReady
             && guildSummaryReady
             && quizSummaryReady
             && globalNavigationWorks
             && hasControllerStateSync;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static async Task<bool> RunNormalHangDiagnostics()
{
    Console.WriteLine("NormalHangController diagnostics");

    var log = new RuntimeLogService();
    var global = new TestGlobalConfigService();
    var input = new InputService(log) { DefaultDispatchMode = InputDispatchMode.PostMessage };
    var recognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("", "", "", "", "", null, null, null, null));
    var controller = new NormalHangController(log, global, CreateCombatBackendSelector(log, input, recognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(log));

    global.Current.AttackHotkey = "F1";
    global.Current.InputDispatchMode = InputDispatchMode.SendInput;
    global.Current.PublicCooldownMs = 50;
    global.Current.Targeting.ScanIntervalMs = 50;
    global.Current.Targeting.AcquireIntervalMs = 50;
    global.Current.Targeting.AutoAcquireWhenNoTarget = true;
    global.Current.YieldToManualInput = true;
    global.Current.ManualInputYieldMs = 1800;

    controller.Attach(DiagnosticWindow(nint.Zero, "diagnostic-invalid-window"));
    controller.Start();
    await Task.Delay(350);
    controller.Stop();

    var inputGuardCount = log.Entries.Count(e => e.Module == "Input" && e.Message.Contains("invalid target window", StringComparison.OrdinalIgnoreCase));
    var acquireCount = log.Entries.Count(e => e.Message.Contains("发送选怪/普攻热键", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Configured input mode={global.Current.InputDispatchMode}");
    Console.WriteLine($"Applied input mode={input.DefaultDispatchMode}");
    Console.WriteLine($"Applied manual-yield={input.YieldToUserInput}, yieldMs={input.UserInputYieldMs}");
    Console.WriteLine($"Input invalid-window guards={inputGuardCount}");
    Console.WriteLine($"Acquire attempts={acquireCount}");

    if (input.DefaultDispatchMode != InputDispatchMode.SendInput
        || !input.YieldToUserInput
        || input.UserInputYieldMs != 1800
        || inputGuardCount == 0
        || acquireCount == 0)
    {
        Console.Error.WriteLine("FAIL: 无目标时应尝试选怪，并应用用户选择的输入通道和手动操作让控配置。");
        return false;
    }

    var splitLog = new RuntimeLogService();
    var splitGlobal = new TestGlobalConfigService();
    var splitInput = new CountingInputService();
    splitGlobal.Current.AttackHotkey = "F1";
    splitGlobal.Current.Targeting.AcquireHotkey = "";
    splitGlobal.Current.PublicCooldownMs = 0;
    splitGlobal.Current.Targeting.ScanIntervalMs = 50;
    splitGlobal.Current.Targeting.AutoAcquireWhenNoTarget = true;
    var splitController = new NormalHangController(splitLog, splitGlobal, CreateCombatBackendSelector(splitLog, splitInput, recognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(splitLog));
    splitController.Attach(DiagnosticWindow(new nint(2467), "diagnostic-split-attack-acquire"));
    splitController.Start();
    await Task.Delay(160);
    splitController.Stop();

    var fallbackAttackAsAcquire = splitInput.SentHotkeys.Count(h => h == "F1");
    var emptyAcquireWarnings = splitLog.Entries.Count(e => e.Message.Contains("选怪热键为空", StringComparison.Ordinal));
    Console.WriteLine($"Blank-acquire sent F1 as acquire={fallbackAttackAsAcquire}");
    Console.WriteLine($"Blank-acquire warnings={emptyAcquireWarnings}");
    if (fallbackAttackAsAcquire != 0 || emptyAcquireWarnings == 0)
    {
        Console.Error.WriteLine("FAIL: 普通攻击和选怪/切怪必须分离，选怪为空时不能用攻击键兜底。");
        return false;
    }

    var preOpeningLog = new RuntimeLogService();
    var preOpeningGlobal = new TestGlobalConfigService();
    var preOpeningInput = new CountingInputService();
    preOpeningGlobal.Current.AttackHotkey = "F1";
    preOpeningGlobal.Current.Targeting.AcquireHotkey = "Tab";
    preOpeningGlobal.Current.PublicCooldownMs = 0;
    preOpeningGlobal.Current.AttackIntervalMs = 5000;
    preOpeningGlobal.Current.Targeting.TargetLostDelayMs = 0;
    preOpeningGlobal.Current.Targeting.ScanIntervalMs = 50;
    preOpeningGlobal.Current.Targeting.AcquireIntervalMs = 0;
    preOpeningGlobal.Current.Skills.Clear();
    preOpeningGlobal.Current.Skills.Add(new SkillPreset
    {
        Name = "opening-preflight-skill",
        Hotkey = "F2",
        IntervalMs = 80,
        Priority = 1,
        Kind = SkillKind.Damage,
        Condition = SkillCondition.TargetExists
    });
    var preOpeningRecognition = new QueuedCombatRecognitionService(
        new CombatRecognitionResult("怪物一", "80", "90", "90", "90", 80, 90, 90, 90),
        new CombatRecognitionResult("怪物一", "0", "90", "90", "90", 0, 90, 90, 90),
        new CombatRecognitionResult("怪物二", "95", "90", "90", "90", 95, 90, 90, 90),
        new CombatRecognitionResult("怪物二", "92", "90", "90", "90", 92, 90, 90, 90));
    var preOpeningController = new NormalHangController(
        preOpeningLog,
        preOpeningGlobal,
        CreateCombatBackendSelector(preOpeningLog, preOpeningInput, preOpeningRecognition),
        new StaticReturnPointRuntimeService(),
        new StateMachineEngine(preOpeningLog));
    preOpeningController.Attach(DiagnosticWindow(new nint(2468), "diagnostic-opening-attack-preflight"));
    preOpeningController.Start();
    await Task.Delay(420);
    preOpeningController.Stop();

    var preOpeningAttackHotkeys = preOpeningInput.SentHotkeys.Count(h => h == "F1");
    var preOpeningAcquireHotkeys = preOpeningInput.SentHotkeys.Count(h => h == "Tab");
    Console.WriteLine($"Opening-preflight attack/acquire={preOpeningAttackHotkeys}/{preOpeningAcquireHotkeys}");
    if (preOpeningAttackHotkeys != 2 || preOpeningAcquireHotkeys == 0)
    {
        foreach (var entry in preOpeningLog.Entries)
            Console.WriteLine($"  opening-preflight-log {entry.Level} {entry.Module}: {entry.Message}");
        Console.Error.WriteLine("FAIL: 切换到新目标后必须立即发送一次首普攻，不能被上一只怪的普攻间隔挡住。");
        return false;
    }

    var combatLog = new RuntimeLogService();
    var combatGlobal = new TestGlobalConfigService();
    var combatInput = new CountingInputService { DefaultDispatchMode = InputDispatchMode.PostMessage };
    combatGlobal.Current.AttackHotkey = "F1";
    combatGlobal.Current.PublicCooldownMs = 0;
    combatGlobal.Current.EnableEmHeal = true;
    combatGlobal.Current.EmHealHotkey = "F3";
    combatGlobal.Current.EmHealThresholdPct = 50;
    combatGlobal.Current.HealHotkey = "F4";
    combatGlobal.Current.HpThresholdPct = 50;
    combatGlobal.Current.ManaHotkey = "F5";
    combatGlobal.Current.MpThresholdPct = 50;
    combatGlobal.Current.PetFoodHotkey = "F6";
    combatGlobal.Current.PetFoodThresholdPct = 50;
    combatGlobal.Current.Skills.Clear();
    combatGlobal.Current.Skills.Add(new SkillPreset { Name = "diagnostic-skill", Hotkey = "F2", IntervalMs = 0, Priority = 1, Condition = SkillCondition.TargetExists });

    var combatRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "40", "30", "20", 80, 40, 30, 20));
    var combatController = new NormalHangController(combatLog, combatGlobal, CreateCombatBackendSelector(combatLog, combatInput, combatRecognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(combatLog));
    combatController.Attach(DiagnosticWindow(new nint(2469), "diagnostic-combat-window"));
    combatController.Start();
    await Task.Delay(250);
    combatController.Stop();

    var emHealCount = combatLog.Entries.Count(e => e.Message.Contains("峨眉加血触发", StringComparison.OrdinalIgnoreCase));
    var healCount = combatLog.Entries.Count(e => e.Message.Contains("吃药回血触发", StringComparison.OrdinalIgnoreCase));
    var manaCount = combatLog.Entries.Count(e => e.Message.Contains("吃药回蓝触发", StringComparison.OrdinalIgnoreCase));
    var petHealCount = combatLog.Entries.Count(e => e.Message.Contains("宠粮回血触发", StringComparison.OrdinalIgnoreCase));
    var skillCount = combatLog.Entries.Count(e => e.Message.Contains("释放技能：diagnostic-skill", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Combat-path em-heal logs={emHealCount}");
    Console.WriteLine($"Combat-path self-heal logs={healCount}");
    Console.WriteLine($"Combat-path mana logs={manaCount}");
    Console.WriteLine($"Combat-path pet-heal logs={petHealCount}");
    Console.WriteLine($"Combat-path skill logs={skillCount}");

    if (emHealCount == 0 || healCount == 0 || manaCount != 0 || petHealCount != 1 || skillCount == 0)
    {
        Console.Error.WriteLine("FAIL: 战斗路径应触发回血、峨眉加血、宠粮和技能循环；回血/回蓝药品共用 CD，同一冷却内不能双发，宠粮最低 10 秒 CD 不能连发。");
        return false;
    }

    var manaOnlyLog = new RuntimeLogService();
    var manaOnlyGlobal = new TestGlobalConfigService();
    var manaOnlyInput = new CountingInputService { DefaultDispatchMode = InputDispatchMode.PostMessage };
    manaOnlyGlobal.Current.AttackHotkey = "F1";
    manaOnlyGlobal.Current.PublicCooldownMs = 0;
    manaOnlyGlobal.Current.HealHotkey = "F4";
    manaOnlyGlobal.Current.HpThresholdPct = 50;
    manaOnlyGlobal.Current.ManaHotkey = "F5";
    manaOnlyGlobal.Current.MpThresholdPct = 70;
    manaOnlyGlobal.Current.BloodManaThresholdPct = 10;
    manaOnlyGlobal.Current.SymbiosisHealThresholdPct = 10;
    manaOnlyGlobal.Current.PetFoodThresholdPct = 10;
    manaOnlyGlobal.Current.Skills.Clear();
    var manaOnlyRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "90", "30", "90", 80, 90, 30, 90));
    var manaOnlyController = new NormalHangController(manaOnlyLog, manaOnlyGlobal, CreateCombatBackendSelector(manaOnlyLog, manaOnlyInput, manaOnlyRecognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(manaOnlyLog));
    manaOnlyController.Attach(DiagnosticWindow(new nint(2468), "diagnostic-mana-only"));
    manaOnlyController.Start();
    await Task.Delay(220);
    manaOnlyController.Stop();

    var manaOnlyHealCount = manaOnlyLog.Entries.Count(e => e.Message.Contains("吃药回血触发", StringComparison.OrdinalIgnoreCase));
    var manaOnlyManaCount = manaOnlyLog.Entries.Count(e => e.Message.Contains("吃药回蓝触发", StringComparison.OrdinalIgnoreCase));
    var manaOnlyHotkeys = manaOnlyInput.SentHotkeys.Count(h => h == "F5");
    Console.WriteLine($"Mana-only self-heal logs={manaOnlyHealCount}");
    Console.WriteLine($"Mana-only mana logs={manaOnlyManaCount}");
    Console.WriteLine($"Mana-only F5 hotkeys={manaOnlyHotkeys}");
    if (manaOnlyHealCount != 0 || manaOnlyManaCount == 0 || manaOnlyHotkeys == 0)
    {
        Console.Error.WriteLine("FAIL: 血量不低且蓝量低时，应能单独触发吃药回蓝。");
        return false;
    }

    var snapshotLog = new RuntimeLogService();
    var snapshotGlobal = new TestGlobalConfigService();
    var snapshotInput = new CountingInputService();
    snapshotGlobal.Current.AttackHotkey = "F1";
    snapshotGlobal.Current.PublicCooldownMs = 0;
    snapshotGlobal.Current.Targeting.ScanIntervalMs = 50;
    snapshotGlobal.Current.Targeting.AutoAcquireWhenNoTarget = false;
    snapshotGlobal.Current.Skills.Clear();
    var emptyRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("", "", "", "", "", null, null, null, null));
    var snapshotService = new StaticRuntimeSnapshotService(new RuntimeSnapshot
    {
        Provider = RuntimeStateProviderKind.ScreenshotOcr,
        Quality = RuntimeSnapshotQuality.Reliable,
        Source = "diagnostic-runtime-snapshot",
        ConfidencePercent = 90,
        Player = new PlayerRuntimeSnapshot
        {
            Quality = RuntimeSnapshotQuality.Reliable,
            Source = "diagnostic-runtime-snapshot",
            ConfidencePercent = 90,
            HpPercent = 90,
            MpPercent = 90,
            IsDead = false
        },
        Target = new TargetRuntimeSnapshot
        {
            Quality = RuntimeSnapshotQuality.Reliable,
            Source = "diagnostic-runtime-snapshot",
            ConfidencePercent = 90,
            Name = "快照目标",
            HpPercent = 80,
            IsPlayer = false,
            IsAttackable = true,
            IsLost = false
        },
        Pet = new PetRuntimeSnapshot
        {
            Quality = RuntimeSnapshotQuality.Reliable,
            Source = "diagnostic-runtime-snapshot",
            ConfidencePercent = 80,
            HpPercent = 80,
            IsSummoned = true
        }
    });
    var snapshotController = new NormalHangController(
        snapshotLog,
        snapshotGlobal,
        CreateCombatBackendSelector(snapshotLog, snapshotInput, emptyRecognition, snapshotService),
        new StaticReturnPointRuntimeService(),
        new StateMachineEngine(snapshotLog));
    snapshotController.Attach(DiagnosticWindow(new nint(2501), "diagnostic-runtime-snapshot-combat"));
    snapshotController.Start();
    await Task.Delay(160);
    snapshotController.Stop();

    var snapshotAttackHotkeys = snapshotInput.SentHotkeys.Count(h => h == "F1");
    Console.WriteLine($"Runtime-snapshot attack hotkeys={snapshotAttackHotkeys}");
    if (snapshotAttackHotkeys == 0)
    {
        Console.Error.WriteLine("FAIL: 普通挂机应通过 RuntimeSnapshot 入口读取目标状态并执行基础攻击。");
        return false;
    }

    var emptyReturnLog = new RuntimeLogService();
    var emptyReturnGlobal = new TestGlobalConfigService();
    var emptyReturnInput = new CountingInputService();
    emptyReturnGlobal.Current.AttackHotkey = "F1";
    emptyReturnGlobal.Current.PublicCooldownMs = 0;
    emptyReturnGlobal.Current.Targeting.ScanIntervalMs = 50;
    emptyReturnGlobal.Current.Targeting.AutoAcquireWhenNoTarget = false;
    emptyReturnGlobal.Current.Skills.Clear();
    var emptyReturnPoints = new ReturnPointService(new MemoryProfileService(), emptyReturnLog);
    emptyReturnPoints.Current.EnableFixedFarmReturn = true;
    emptyReturnPoints.Current.EnableStuckRecovery = true;
    emptyReturnPoints.Current.EnableDeathReturn = false;
    emptyReturnPoints.Current.EnableEarthSpiritReturn = false;
    emptyReturnPoints.Current.Points.Clear();
    var emptyReturnRuntime = new ReturnPointRuntimeService(
        emptyReturnPoints,
        new StaticSceneStateService(new NavigationRecognitionResult("昆仑山", "186,44", 186, 44)),
        new StaticDeathRecognitionService(new DeathRecognitionResult(false, "", "")),
        new ReturnNavigationService(emptyReturnInput, emptyReturnLog),
        emptyReturnLog);
    var emptyReturnRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "90", "90", "90", 80, 90, 90, 90));
    var emptyReturnController = new NormalHangController(
        emptyReturnLog,
        emptyReturnGlobal,
        CreateCombatBackendSelector(emptyReturnLog, emptyReturnInput, emptyReturnRecognition),
        emptyReturnRuntime,
        new StateMachineEngine(emptyReturnLog));
    emptyReturnController.Attach(DiagnosticWindow(new nint(2502), "diagnostic-empty-return-points"));
    emptyReturnController.Start();
    await Task.Delay(220);
    emptyReturnController.Stop();

    var emptyReturnAttackHotkeys = emptyReturnInput.SentHotkeys.Count(h => h == "F1");
    var emptyReturnWarnings = emptyReturnLog.Entries.Count(e => e.Module == "ReturnPoint" && e.Level == LogLevel.Warn);
    Console.WriteLine($"Empty-return attack hotkeys={emptyReturnAttackHotkeys}");
    Console.WriteLine($"Empty-return warnings={emptyReturnWarnings}");
    if (emptyReturnAttackHotkeys == 0)
    {
        Console.Error.WriteLine("FAIL: 回点已启用但没有返点坐标时，普通挂机应继续打怪，不能卡在回点检查。");
        return false;
    }

    var petSkillLog = new RuntimeLogService();
    var petSkillGlobal = new TestGlobalConfigService();
    var petSkillInput = new CountingInputService();
    petSkillGlobal.Current.AttackHotkey = "F1";
    petSkillGlobal.Current.PublicCooldownMs = 0;
    petSkillGlobal.Current.Targeting.ScanIntervalMs = 50;
    petSkillGlobal.Current.BloodManaActivationMode = PetSkillActivationMode.ClientClick;
    petSkillGlobal.Current.BloodManaCooldownMs = 30000;
    petSkillGlobal.Current.BloodManaThresholdPct = 70;
    petSkillGlobal.Current.SymbiosisHealThresholdPct = 10;
    petSkillGlobal.Current.PetFoodThresholdPct = 10;
    petSkillGlobal.Current.Skills.Clear();
    var petSkillRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "90", "30", "90", 80, 90, 30, 90));
    var petSkillController = new NormalHangController(petSkillLog, petSkillGlobal, CreateCombatBackendSelector(petSkillLog, petSkillInput, petSkillRecognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(petSkillLog));
    petSkillController.Attach(DiagnosticWindow(new nint(2488), "diagnostic-pet-skill-cooldown"));
    petSkillController.Start();
    await Task.Delay(260);
    petSkillController.Stop();

    var bloodManaLogs = petSkillLog.Entries.Count(e => e.Message.Contains("血迹回蓝触发", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Blood-mana click count={petSkillInput.ClickCount}");
    if (petSkillInput.Clicks.Count > 0)
        Console.WriteLine($"Blood-mana click point={petSkillInput.Clicks[0].X},{petSkillInput.Clicks[0].Y}");
    Console.WriteLine($"Blood-mana logs={bloodManaLogs}");
    var clickPointOk = petSkillInput.Clicks.Count == 1
                       && petSkillInput.Clicks[0].X >= 350
                       && petSkillInput.Clicks[0].Y >= 680;
    if (petSkillInput.ClickCount != 1 || bloodManaLogs != 1 || !clickPointOk)
    {
        foreach (var entry in petSkillLog.Entries)
            Console.WriteLine($"  pet-skill-log {entry.Level} {entry.Module}: {entry.Message}");
        Console.Error.WriteLine("FAIL: 血迹回蓝应走宠物技能栏点击，点击点需按窗口尺寸解析，并受独立 CD 限制，不能循环连点。");
        return false;
    }

    var symbiosisLog = new RuntimeLogService();
    var symbiosisGlobal = new TestGlobalConfigService();
    var symbiosisInput = new CountingInputService();
    symbiosisGlobal.Current.AttackHotkey = "F1";
    symbiosisGlobal.Current.PublicCooldownMs = 0;
    symbiosisGlobal.Current.Targeting.ScanIntervalMs = 50;
    symbiosisGlobal.Current.BloodManaThresholdPct = 10;
    symbiosisGlobal.Current.SymbiosisHealActivationMode = PetSkillActivationMode.ClientClick;
    symbiosisGlobal.Current.SymbiosisHealCooldownMs = 30000;
    symbiosisGlobal.Current.SymbiosisHealThresholdPct = 70;
    symbiosisGlobal.Current.PetFoodThresholdPct = 10;
    symbiosisGlobal.Current.Skills.Clear();
    var symbiosisRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "40", "90", "90", 80, 40, 90, 90));
    var symbiosisController = new NormalHangController(symbiosisLog, symbiosisGlobal, CreateCombatBackendSelector(symbiosisLog, symbiosisInput, symbiosisRecognition), new StaticReturnPointRuntimeService(), new StateMachineEngine(symbiosisLog));
    symbiosisController.Attach(DiagnosticWindow(new nint(2490), "diagnostic-symbiosis-cooldown"));
    symbiosisController.Start();
    await Task.Delay(260);
    symbiosisController.Stop();

    var symbiosisLogs = symbiosisLog.Entries.Count(e => e.Message.Contains("共生回血触发", StringComparison.OrdinalIgnoreCase));
    var unexpectedBloodManaLogs = symbiosisLog.Entries.Count(e => e.Message.Contains("血迹回蓝触发", StringComparison.OrdinalIgnoreCase));
    Console.WriteLine($"Symbiosis click count={symbiosisInput.ClickCount}");
    if (symbiosisInput.Clicks.Count > 0)
        Console.WriteLine($"Symbiosis click point={symbiosisInput.Clicks[0].X},{symbiosisInput.Clicks[0].Y}");
    Console.WriteLine($"Symbiosis logs={symbiosisLogs}");
    Console.WriteLine($"Symbiosis-path blood-mana logs={unexpectedBloodManaLogs}");
    var symbiosisPointOk = symbiosisInput.Clicks.Count == 1
                           && symbiosisInput.Clicks[0].X >= 320
                           && symbiosisInput.Clicks[0].Y >= 680;
    if (symbiosisInput.ClickCount != 1 || symbiosisLogs != 1 || unexpectedBloodManaLogs != 0 || !symbiosisPointOk)
    {
        foreach (var entry in symbiosisLog.Entries)
            Console.WriteLine($"  symbiosis-log {entry.Level} {entry.Module}: {entry.Message}");
        Console.Error.WriteLine("FAIL: 共生回血应走宠物技能栏点击，且受独立 30 秒 CD 限制；蓝量不低时不能误触发血迹。");
        return false;
    }

    var petSkillGuardLog = new RuntimeLogService();
    var petSkillGuardGlobal = new TestGlobalConfigService();
    var petSkillGuardInput = new CountingInputService();
    petSkillGuardGlobal.Current.AttackHotkey = "F1";
    petSkillGuardGlobal.Current.PublicCooldownMs = 0;
    petSkillGuardGlobal.Current.Targeting.ScanIntervalMs = 50;
    petSkillGuardGlobal.Current.BloodManaActivationMode = PetSkillActivationMode.ClientClick;
    petSkillGuardGlobal.Current.BloodManaClickX = 440;
    petSkillGuardGlobal.Current.BloodManaClickBottomOffset = 720;
    petSkillGuardGlobal.Current.BloodManaThresholdPct = 70;
    petSkillGuardGlobal.Current.SymbiosisHealThresholdPct = 10;
    petSkillGuardGlobal.Current.PetFoodThresholdPct = 10;
    petSkillGuardGlobal.Current.Skills.Clear();
    var petSkillGuardRecognition = new StaticCombatRecognitionService(
        new CombatRecognitionResult("木桩", "80", "90", "30", "90", 80, 90, 30, 90));
    var petSkillGuardController = new NormalHangController(
        petSkillGuardLog,
        petSkillGuardGlobal,
