    Console.WriteLine($"Stuck-subroutine hotkeys={stuckHotkeys}");
    Console.WriteLine($"Stuck-subroutine logs={stuckSubLogs}");
    if (!stuckInput.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
        || stuckInput.SentHotkeys.Contains("F1", StringComparer.OrdinalIgnoreCase)
        || stuckInput.SentHotkeys.Contains("F2", StringComparer.OrdinalIgnoreCase)
        || stuckSubLogs == 0)
    {
        foreach (var entry in stuckLog.Entries)
            Console.WriteLine($"  stuck-log {entry.Level} {entry.Module}: {entry.Message}");
        Console.Error.WriteLine("FAIL: 卡点恢复触发时普通挂机应暂停攻击和技能，只执行卡点恢复动作。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static async Task<bool> RunNormalHangDiagnosticsV2()
{
    Console.WriteLine("NormalHangController diagnostics");

    var log = new RuntimeLogService();
    var global = new TestGlobalConfigService();
