static bool RunCombatRecognitionDiagnostics()
{
    Console.WriteLine("CombatRecognition diagnostics");
    var log = new RuntimeLogService();
    var config = new CombatRecognitionConfig();
    var capture = new SyntheticWindowCaptureService(1531, 955, config);
    var ocr = new SyntheticOcrService("木桩");
    var recognition = new CombatRecognitionService(capture, ocr, log);

    var result = recognition.Recognize(DiagnosticWindow(new nint(100), "synthetic-client", width: 1531, height: 955), config);
    Console.WriteLine($"TargetName={result.TargetNameText}");
    Console.WriteLine($"TargetHp={result.TargetHpPercent}");
    Console.WriteLine($"PlayerHp={result.PlayerHpPercent}");
    Console.WriteLine($"PlayerMp={result.PlayerMpPercent}");
    Console.WriteLine($"PetHp={result.PetHpPercent}");

    var projected = OcrRegionProjection.Resolve(config.PlayerHp, 1531, 955);
    Console.WriteLine($"Projected player HP region={projected.X},{projected.Y},{projected.Width},{projected.Height}");

    if (result.TargetNameText != "木桩"
        || result.TargetHpPercent is < 60 or > 66
        || result.PlayerHpPercent is < 78 or > 82
        || result.PlayerMpPercent is < 68 or > 72
        || result.PetHpPercent is < 53 or > 57
        || projected.IsEmpty)
    {
        Console.Error.WriteLine("FAIL: OCR 区域投影或状态条识别不符合预期。");
        return false;
    }

    var emptyMpCapture = new SyntheticWindowCaptureService(1531, 955, config, playerMpPercent: 0);
    var emptyMpRecognition = new CombatRecognitionService(emptyMpCapture, ocr, log);
    var emptyMpResult = emptyMpRecognition.Recognize(DiagnosticWindow(new nint(101), "synthetic-empty-mp", width: 1531, height: 955), config);
    Console.WriteLine($"EmptyPlayerMp={emptyMpResult.PlayerMpPercent}");

    if (emptyMpResult.PlayerHpPercent is < 78 or > 82
        || emptyMpResult.PlayerMpPercent != 0)
    {
        Console.Error.WriteLine("FAIL: 人物蓝条空槽应识别为 0%，不能返回 null，否则低蓝回血/血迹不会触发。");
        return false;
    }

    var wrongColorCapture = new SyntheticWindowCaptureService(1531, 955, config, useMismatchedStatusColors: true);
    var wrongColorRecognition = new CombatRecognitionService(wrongColorCapture, ocr, log);
    var wrongColorResult = wrongColorRecognition.Recognize(DiagnosticWindow(new nint(102), "synthetic-wrong-status-colors", width: 1531, height: 955), config);
    Console.WriteLine($"WrongColorTargetHp={wrongColorResult.TargetHpPercent}");
    Console.WriteLine($"WrongColorPlayerMp={wrongColorResult.PlayerMpPercent}");

    if (wrongColorResult.TargetHpPercent is not null
        || wrongColorResult.PlayerMpPercent is not null)
    {
        Console.Error.WriteLine("FAIL: 目标血条不能把蓝色背景识别为血量，人物蓝条也不能把红色血条识别为蓝量。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunCombatRegionCenterDiagnostics()
{
    Console.WriteLine("CombatRegionCenter diagnostics");
    var log = new RuntimeLogService();
    var global = new TestGlobalConfigService();
    var globalRegions = new CombatRecognitionConfig
    {
        TargetName = new OcrRegionConfig { X = 10, Y = 20, Width = 30, Height = 40 }
    };
    var localRegions = new CombatRecognitionConfig
    {
        TargetName = new OcrRegionConfig { X = 900, Y = 900, Width = 1, Height = 1 }
    };
    global.Current.CombatRecognition = globalRegions;

    var recognition = new CapturingCombatRecognitionService(
        new CombatRecognitionResult("江湖宵小", "", "", "", "", null, null, null, null));
    var targeting = new NpcTargetingService(new RecognitionPerceptionHub(recognition), global, log);
    var config = new NpcGrabConfig { Recognition = localRegions };
    config.Targets.Clear();
    config.Targets.Add(new NpcGrabTargetConfig
    {
        Kind = NpcGrabTargetKind.Small,
        DisplayName = "small",
        Enabled = true,
        Keywords = "江湖宵小",
        Priority = 1
    });

    var result = targeting.SelectTarget(DiagnosticWindow(new nint(777), "region-center"), config);
    var usedGlobalConfig = ReferenceEquals(recognition.LastConfig, globalRegions);
    var usedLocalConfig = ReferenceEquals(recognition.LastConfig, localRegions);

    Console.WriteLine($"Found={result.Found}");
    Console.WriteLine($"UsedGlobalConfig={usedGlobalConfig}");
    Console.WriteLine($"UsedLocalConfig={usedLocalConfig}");

    if (!result.Found || !usedGlobalConfig || usedLocalConfig)
    {
        Console.Error.WriteLine("FAIL: fixed combat OCR regions must come from global config.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunResolutionProfileDiagnostics()
{
    Console.WriteLine("ResolutionProfile diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var resolution = new ResolutionProfileService(profiles, log);

    var calibrated = new CombatRecognitionConfig
    {
        TargetName = new OcrRegionConfig { X = 20, Y = 20, Width = 100, Height = 18 },
        TargetHp = new OcrRegionConfig { X = 20, Y = 50, Width = 100, Height = 6 },
        PlayerHp = new OcrRegionConfig { X = 20, Y = 70, Width = 100, Height = 6 },
        PlayerMp = new OcrRegionConfig { X = 20, Y = 90, Width = 100, Height = 6 },
        PetHp = new OcrRegionConfig { X = 20, Y = 110, Width = 100, Height = 6 }
    };

    var fallbackWrong = new CombatRecognitionConfig
    {
        TargetName = new OcrRegionConfig { X = 700, Y = 700, Width = 100, Height = 18 },
        TargetHp = new OcrRegionConfig { X = 700, Y = 730, Width = 100, Height = 6 },
        PlayerHp = new OcrRegionConfig { X = 700, Y = 750, Width = 100, Height = 6 },
        PlayerMp = new OcrRegionConfig { X = 700, Y = 770, Width = 100, Height = 6 },
        PetHp = new OcrRegionConfig { X = 700, Y = 790, Width = 100, Height = 6 }
    };

    resolution.SaveCombatProfile(1531, 955, calibrated, "diagnostic");
    var avatarRegion = new OcrRegionConfig { X = 31, Y = 41, Width = 151, Height = 61 };
    resolution.SaveAvatarProfile(1531, 955, avatarRegion, "diagnostic-avatar");

    var capture = new SyntheticWindowCaptureService(1531, 955, calibrated);
    var ocr = new SyntheticOcrService("木桩");
    var recognition = new CombatRecognitionService(capture, ocr, log, resolution);
    var result = recognition.Recognize(DiagnosticWindow(new nint(888), "resolution-profile", width: 1531, height: 955), fallbackWrong);

    var exactProfile = resolution.TryGetCombatProfile(1531, 955, out var loaded);
    var missingProfile = resolution.TryGetCombatProfile(1024, 768, out _);
    var resolvedAvatar = resolution.ResolveAvatar(1531, 955, new OcrRegionConfig { X = 6, Y = 6, Width = 224, Height = 86 });
    var fallbackAvatar = resolution.ResolveAvatar(1024, 768, new OcrRegionConfig { X = 6, Y = 6, Width = 224, Height = 86 });
    Console.WriteLine($"ExactProfile={exactProfile}");
    Console.WriteLine($"MissingProfile={missingProfile}");
    Console.WriteLine($"LoadedSource={loaded.Source}");
    Console.WriteLine($"LoadedAvatarSource={loaded.AvatarSource}");
    Console.WriteLine($"AvatarRegion={resolvedAvatar.X},{resolvedAvatar.Y},{resolvedAvatar.Width},{resolvedAvatar.Height}");
    Console.WriteLine($"FallbackAvatar={fallbackAvatar.X},{fallbackAvatar.Y},{fallbackAvatar.Width},{fallbackAvatar.Height}");
    Console.WriteLine($"PlayerHp={result.PlayerHpPercent}");
    Console.WriteLine($"PlayerMp={result.PlayerMpPercent}");
    Console.WriteLine($"PetHp={result.PetHpPercent}");

    if (!exactProfile
        || missingProfile
        || loaded.Source != "diagnostic"
        || loaded.AvatarSource != "diagnostic-avatar"
        || resolvedAvatar is not { X: 31, Y: 41, Width: 151, Height: 61 }
        || fallbackAvatar is not { X: 6, Y: 6, Width: 224, Height: 86 }
        || result.PlayerHpPercent is < 78 or > 82
        || result.PlayerMpPercent is < 68 or > 72
        || result.PetHpPercent is < 53 or > 57)
    {
        Console.Error.WriteLine("FAIL: resolution profile was not applied to current client size.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunWindowBindingDiagnostics()
{
    Console.WriteLine("WindowBinding diagnostics");
    var log = new RuntimeLogService();
    var binding = new WindowBindingService(log);
    var game = Process.GetProcessesByName("Game").FirstOrDefault(p => p.MainWindowHandle != nint.Zero);

    if (game is not null)
    {
        var bound = binding.BindByHandle(game.MainWindowHandle);
        if (bound is null)
        {
            Console.Error.WriteLine("FAIL: 发现 Game.exe 窗口但绑定失败。");
            return false;
        }

        Console.WriteLine($"Bound Game.exe: pid={bound.Pid}, bitness={bound.Bitness}, size={bound.ClientSizeText}, allowed={bound.IsAutomationAllowed}");
    }
    else
    {
        Console.WriteLine("No running Game.exe window found; checking binding model with synthetic 32-bit window data.");
    }

    var model = DiagnosticWindow(new nint(1), "model-check", width: 1531, height: 955);
    Console.WriteLine($"Synthetic model: bitness={model.Bitness}, size={model.ClientSizeText}, allowed={model.IsAutomationAllowed}, compatibility={model.IsResolutionCompatibilityMode}");

    if (!model.IsAutomationAllowed || !model.IsResolutionCompatibilityMode)
    {
        Console.Error.WriteLine("FAIL: 32 位非 1024x768 窗口应允许启动，并进入分辨率兼容模式。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunLiveClientDiagnostics()
{
    Console.WriteLine("Live client diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var log = new RuntimeLogService();
    var binding = new WindowBindingService(log);
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var capture = new WindowCaptureService(log);
    var client = capture.CaptureClient(window.Hwnd);
    var avatar = capture.CaptureAvatar(window.Hwnd);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-client");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}-{stamp}.png");
    var avatarPath = Path.Combine(evidenceDir, $"avatar-{window.Pid}-{stamp}.png");

    var clientSaved = SaveCapturePng(client, clientPath);
    var avatarSaved = SaveCapturePng(avatar, avatarPath);
    var clientVisual = HasVisualContent(client);
    var avatarVisual = HasVisualContent(avatar);

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Title={window.Title}");
    Console.WriteLine($"Bitness={window.Bitness}");
    Console.WriteLine($"ClientSize={window.ClientSizeText}");
    Console.WriteLine($"AutomationAllowed={window.IsAutomationAllowed}");
    Console.WriteLine($"ClientCapture={client?.Width}x{client?.Height}, saved={clientSaved}, visual={clientVisual}, path={clientPath}");
    Console.WriteLine($"AvatarCapture={avatar?.Width}x{avatar?.Height}, saved={avatarSaved}, visual={avatarVisual}, path={avatarPath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && client is { Width: > 0, Height: > 0 }
             && avatar is { Width: > 0, Height: > 0 }
             && clientSaved
             && avatarSaved
             && clientVisual
             && avatarVisual;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReadOnlyProbeDiagnostics()
{
    Console.WriteLine("Read-only runtime probe diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var result = probe.Probe(window);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "readonly-probe");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"readonly-probe-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true
    };
    var evidence = new
    {
        capturedAt = result.CapturedAt,
        mode = "read-only-process-metadata-no-memory-read-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            enumeratesMemoryRegions = false,
            scansPointers = false,
            callsReadProcessMemory = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            touchesOriginalLegacyData = false
        },
        scope = new
        {
            stage = "A",
            description = "process metadata and version fingerprint only",
            businessDecisionReady = false,
            fallbackRequiredForGameplayState = true
        },
        result.Success,
        result.Status,
        result.Message,
        window = new
        {
            hwnd = result.Hwnd == 0 ? "-" : $"0x{result.Hwnd.ToInt64():X}",
            result.Pid,
            result.Title,
            result.ProcessName,
            result.ProcessPath,
            bitness = result.Bitness.ToString(),
            clientType = result.ClientType.ToString(),
            result.ClientWidth,
            result.ClientHeight
        },
        mainModule = new
        {
            version = result.MainModuleVersion,
            sha256 = result.MainModuleSha256,
            result.ProcessStartTime
        },
        capabilities = result.Capabilities.Select(c => new
        {
            capability = c.Capability.ToString(),
            status = c.Status.ToString(),
            c.Note
        }).ToArray()
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));
    var evidenceOk = ValidateReadOnlyProbeEvidence(evidencePath, result, out var evidenceError);

    Console.WriteLine($"Pid={result.Pid}");
    Console.WriteLine($"Title={result.Title}");
    Console.WriteLine($"Bitness={result.Bitness}");
    Console.WriteLine($"ClientSize={result.ClientWidth}x{result.ClientHeight}");
    Console.WriteLine($"ProcessPath={result.ProcessPath}");
    Console.WriteLine($"Version={result.MainModuleVersion}");
    Console.WriteLine($"SHA256={result.MainModuleSha256}");
    Console.WriteLine($"ProcessStartTime={result.ProcessStartTime}");
    Console.WriteLine("Safety=no-input,no-click,no-vm-read,no-memory-region-scan,no-pointer-scan,no-readprocessmemory,no-memory-state-read,no-write,no-inject,no-hook,no-patch,no-packet-mod,no-legacy-data-touch");
    Console.WriteLine($"EvidenceSelfCheck={evidenceOk}");
    Console.WriteLine($"Evidence={evidencePath}");
    if (!evidenceOk)
        Console.Error.WriteLine($"FAIL: readonly-probe evidence self-check failed: {evidenceError}");
    Console.WriteLine(result.Success && evidenceOk ? "PASS" : "FAIL");
    return result.Success && evidenceOk;
}

static bool ValidateReadOnlyProbeEvidence(string evidencePath, ReadOnlyProcessProbeResult result, out string error)
{
    error = "";
    try
    {
        var root = JsonNode.Parse(File.ReadAllText(evidencePath, Encoding.UTF8))?.AsObject();
        if (root is null)
        {
            error = "JSON root is empty.";
            return false;
        }

        if (StringValue(root["mode"]) != "read-only-process-metadata-no-memory-read-no-input")
            return Fail("mode mismatch.", out error);

        var safety = root["safety"]?.AsObject();
        if (safety is null)
            return Fail("missing safety object.", out error);

        foreach (var key in new[]
                 {
                     "sendsInput",
                     "clicksMouse",
                     "opensProcessForVmRead",
                     "enumeratesMemoryRegions",
                     "scansPointers",
                     "callsReadProcessMemory",
                     "readsGameStateMemory",
                     "writesMemory",
                     "injectsDll",
                     "installsHook",
                     "patchesClient",
                     "modifiesPackets",
                     "touchesOriginalLegacyData"
                 })
        {
            if (BoolValue(safety[key]) != false)
                return Fail($"safety.{key} must be false.", out error);
        }

        var scope = root["scope"]?.AsObject();
        if (scope is null)
            return Fail("missing scope object.", out error);
        if (StringValue(scope["stage"]) != "A")
            return Fail("scope.stage must be A.", out error);
        if (BoolValue(scope["businessDecisionReady"]) != false)
            return Fail("scope.businessDecisionReady must be false.", out error);
        if (BoolValue(scope["fallbackRequiredForGameplayState"]) != true)
            return Fail("scope.fallbackRequiredForGameplayState must be true.", out error);

        var window = root["window"]?.AsObject();
        if (window is null)
            return Fail("missing window object.", out error);
        if (IntValue(window["Pid"]) != result.Pid)
            return Fail("window.Pid mismatch.", out error);
        if (!StringValue(window["ProcessPath"]).EndsWith(@"\Game.exe", StringComparison.OrdinalIgnoreCase))
            return Fail("window.ProcessPath must point to Game.exe.", out error);
        if (StringValue(window["bitness"]) != ClientBitness.X86.ToString())
            return Fail("window.bitness must be X86.", out error);
        if (IntValue(window["ClientWidth"]) <= 0 || IntValue(window["ClientHeight"]) <= 0)
            return Fail("client size must be positive.", out error);

        var mainModule = root["mainModule"]?.AsObject();
        if (mainModule is null)
            return Fail("missing mainModule object.", out error);
        if (string.IsNullOrWhiteSpace(StringValue(mainModule["version"])))
            return Fail("mainModule.version is empty.", out error);
        var sha256 = StringValue(mainModule["sha256"]);
        if (sha256.Length != 64 || sha256.Any(c => !Uri.IsHexDigit(c)))
            return Fail("mainModule.sha256 is not a 64-char hex string.", out error);
        if (!DateTimeOffset.TryParse(StringValue(mainModule["ProcessStartTime"]), out _))
            return Fail("mainModule.ProcessStartTime is not parseable.", out error);

        var capabilities = root["capabilities"]?.AsArray();
        if (capabilities is null)
            return Fail("missing capabilities array.", out error);

        var matrix = capabilities
            .OfType<JsonObject>()
            .ToDictionary(o => StringValue(o["capability"]), o => StringValue(o["status"]), StringComparer.Ordinal);
        if (!matrix.TryGetValue(nameof(RuntimeProbeCapability.ProcessMetadata), out var processMetadata)
            || processMetadata != nameof(RuntimeProbeCapabilityStatus.Available))
            return Fail("ProcessMetadata capability must be Available.", out error);
        if (!matrix.TryGetValue(nameof(RuntimeProbeCapability.VersionFingerprint), out var versionFingerprint)
            || versionFingerprint != nameof(RuntimeProbeCapabilityStatus.Available))
            return Fail("VersionFingerprint capability must be Available.", out error);

        foreach (var capability in new[]
                 {
                     nameof(RuntimeProbeCapability.PlayerSnapshot),
                     nameof(RuntimeProbeCapability.TargetSnapshot),
                     nameof(RuntimeProbeCapability.PetSnapshot),
                     nameof(RuntimeProbeCapability.SceneSnapshot),
                     nameof(RuntimeProbeCapability.InventorySnapshot)
                 })
        {
            if (!matrix.TryGetValue(capability, out var status) || status != nameof(RuntimeProbeCapabilityStatus.Planned))
                return Fail($"{capability} capability must be Planned.", out error);
        }

        return true;
    }
    catch (Exception ex)
    {
        error = ex.Message;
        return false;
    }

    static bool Fail(string message, out string err)
    {
        err = message;
        return false;
    }

    static string StringValue(JsonNode? node) => node?.GetValue<string>() ?? "";
    static bool? BoolValue(JsonNode? node) => node?.GetValue<bool>();
    static int IntValue(JsonNode? node) => node?.GetValue<int>() ?? 0;
}

static bool RunReadOnlyMemoryCapabilityDiagnostics()
{
    Console.WriteLine("Read-only memory capability diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var probeResult = probe.Probe(window);

    using var process = Process.GetProcessById(window.Pid);
    var processPath = string.Empty;
    nint moduleBase = 0;
    int moduleSize = 0;
    try
    {
        processPath = process.MainModule?.FileName ?? string.Empty;
        moduleBase = process.MainModule?.BaseAddress ?? 0;
        moduleSize = process.MainModule?.ModuleMemorySize ?? 0;
    }
    catch
    {
        // Kept empty; the result JSON records the failure without retrying with broader behavior.
    }

    const uint PROCESS_VM_READ = 0x0010;
    const uint PROCESS_QUERY_LIMITED_INFORMATION = 0x1000;
    const int requestedBytes = 1024;
    var buffer = new byte[requestedBytes];
    var openLastError = 0;
    var readLastError = 0;
    var bytesRead = 0;
    var openSucceeded = false;
    var readSucceeded = false;

    var handle = ReadOnlyMemoryNative.OpenProcess(
        PROCESS_QUERY_LIMITED_INFORMATION | PROCESS_VM_READ,
        false,
        window.Pid);
    try
    {
        openSucceeded = handle != 0;
        if (!openSucceeded)
        {
            openLastError = Marshal.GetLastWin32Error();
        }
        else if (moduleBase != 0)
        {
            readSucceeded = ReadOnlyMemoryNative.ReadProcessMemory(
                handle,
                moduleBase,
                buffer,
                buffer.Length,
                out bytesRead);
            if (!readSucceeded)
                readLastError = Marshal.GetLastWin32Error();
        }
    }
    finally
    {
        if (handle != 0)
            ReadOnlyMemoryNative.CloseHandle(handle);
    }

    var actual = bytesRead > 0 ? buffer.Take(bytesRead).ToArray() : Array.Empty<byte>();
    var mz = actual.Length >= 2 && actual[0] == (byte)'M' && actual[1] == (byte)'Z';
    var eLfanew = actual.Length >= 0x40 ? BitConverter.ToInt32(actual, 0x3C) : -1;
    var pe = eLfanew >= 0 && eLfanew + 4 <= actual.Length
             && actual[eLfanew] == (byte)'P'
             && actual[eLfanew + 1] == (byte)'E'
             && actual[eLfanew + 2] == 0
             && actual[eLfanew + 3] == 0;
    var headerHash = actual.Length > 0
        ? Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(actual)).ToLowerInvariant()
        : string.Empty;
    var headerPrefix = actual.Length > 0
        ? Convert.ToHexString(actual.Take(Math.Min(16, actual.Length)).ToArray()).ToLowerInvariant()
        : string.Empty;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "readonly-memory-capability");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"readonly-memory-capability-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-vm-read-capability-main-module-pe-header-only",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = openSucceeded,
            enumeratesMemoryRegions = false,
            scansPointers = false,
            callsReadProcessMemory = readSucceeded,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        scope = new
        {
            stage = "A-plus",
            description = "VM_READ capability only; reads main module PE header bytes, not gameplay state.",
            readClassification = "main-module-header-only",
            businessDecisionReady = false,
            fallbackRequiredForGameplayState = true
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            processPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256
        },
        module = new
        {
            baseAddress = moduleBase == 0 ? "-" : $"0x{moduleBase.ToInt64():X}",
            moduleSize,
            requestedBytes,
            bytesRead,
            openSucceeded,
            openLastError,
            readSucceeded,
            readLastError,
            mz,
            pe,
            eLfanew,
            headerPrefix,
            headerSha256 = headerHash
        },
        gates = new
        {
            provesOnlyVmReadCapability = openSucceeded && readSucceeded && mz && pe,
            provesGameplayStateRead = false,
            mayEnterBusinessDecision = false,
            nextRequiredGate = "单字段候选定位 -> 截图/OCR交叉验证 -> 稳定性采样 -> 回退机制验证"
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"OpenProcess(VM_READ)={openSucceeded}, error={openLastError}");
    Console.WriteLine($"ReadProcessMemory main module header={readSucceeded}, bytes={bytesRead}, error={readLastError}");
    Console.WriteLine($"Header MZ={mz}, PE={pe}, e_lfanew={eLfanew}, sha256={headerHash}");
    Console.WriteLine("Safety=no-input,no-click,vm-read-main-module-header-only,no-memory-region-scan,no-pointer-scan,no-gameplay-state-read,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && openSucceeded
             && readSucceeded
             && bytesRead > 64
             && mz
             && pe
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReadOnlyCoordinateCandidatesDiagnostics()
{
    Console.WriteLine("Read-only coordinate candidate diagnostics");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var probeResult = probe.Probe(window);

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var navigationConfig = returnPoints.Current.NavigationRecognition;
    var navigation = provider.GetRequiredService<ISceneStateService>().Recognize(window, navigationConfig);

    const uint PROCESS_VM_READ = 0x0010;
    const uint PROCESS_QUERY_INFORMATION = 0x0400;
    const long maxBytesToRead = 128L * 1024 * 1024;
    const int maxRegionsToVisit = 2048;
    const int maxHits = 64;
    const int maxChunkBytes = 1024 * 1024;
    const ulong maxUserAddress = 0x7FFF_FFFFUL;

    var patterns = navigation is { X: not null, Y: not null }
        ? BuildCoordinateSearchPatterns(navigation.X.Value, navigation.Y.Value).ToArray()
        : Array.Empty<ReadOnlyMemorySearchPattern>();

    var openSucceeded = false;
    var openLastError = 0;
    ReadOnlyCoordinateMemoryScanResult? scan = null;
    var handle = ReadOnlyMemoryNative.OpenProcess(
        PROCESS_QUERY_INFORMATION | PROCESS_VM_READ,
        false,
        window.Pid);
    try
    {
        openSucceeded = handle != 0;
        if (!openSucceeded)
        {
            openLastError = Marshal.GetLastWin32Error();
        }
        else if (patterns.Length > 0)
        {
            scan = ScanReadableMemoryForPatterns(
                handle,
                patterns,
                maxBytesToRead,
                maxRegionsToVisit,
                maxHits,
                maxChunkBytes,
                maxUserAddress);
        }
    }
    finally
    {
        if (handle != 0)
            ReadOnlyMemoryNative.CloseHandle(handle);
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "readonly-coordinate-candidates");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"readonly-coordinate-candidates-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-coordinate-candidates-ocr-anchor-memory-text-scan-no-input-no-business",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = openSucceeded,
            enumeratesMemoryRegions = openSucceeded && patterns.Length > 0,
            scansPointers = false,
            callsReadProcessMemory = scan?.ReadProcessMemoryCalls > 0,
            readsCandidateStateMemory = scan?.BytesRead > 0,
            readsGameStateMemory = scan?.BytesRead > 0,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        scope = new
        {
            stage = "B-candidate-research",
            field = "Scene.Coordinate",
            description = "Uses screenshot/OCR coordinate as an anchor and searches readable memory for text candidates only.",
            readClassification = "bounded-readable-memory-text-search",
            coordinateMustBeCrossValidated = true,
            mayEnterBusinessDecision = false,
            fallbackRequiredForAutomation = true
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256
        },
        externalAnchor = new
        {
            navigation.MapNameText,
            navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y,
            navigation.HasCoordinate,
            dictionaries = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        scanLimits = new
        {
            maxBytesToRead,
            maxRegionsToVisit,
            maxHits,
            maxChunkBytes,
            maxUserAddress = $"0x{maxUserAddress:X}"
        },
        searchPatterns = patterns.Select(p => new
        {
            p.Label,
            p.Token,
            p.EncodingName,
            p.Length,
            p.HexPrefix
        }).ToArray(),
        memory = scan is null
            ? (object)new
            {
                openSucceeded,
                openLastError,
                skipped = true,
                skipReason = patterns.Length == 0
                    ? "截图/OCR 未取得可解析坐标，禁止无锚点盲扫。"
                    : "未执行扫描。"
            }
            : new
            {
                openSucceeded,
                openLastError,
                skipped = false,
                scan.RegionsVisited,
                scan.ReadableRegions,
                scan.ReadProcessMemoryCalls,
                scan.FailedReadCalls,
                scan.BytesRead,
                scan.HitCount,
                scan.StoppedReason,
                hits = scan.Hits.Select(h => new
                {
                    h.Address,
                    h.RegionBase,
                    h.RegionSize,
                    h.PatternLabel,
                    h.Token,
                    h.EncodingName,
                    h.OffsetInRegion
                }).ToArray()
            },
        gates = new
        {
            anchorReady = navigation.HasCoordinate,
            openProcessReady = openSucceeded,
            candidateSearchExecuted = scan is not null,
            foundAnyCandidate = scan?.HitCount > 0,
            stableFieldReady = false,
            mayEnterBusinessDecision = false,
            nextRequiredGate = "连续采样同一坐标变化 -> 截图/OCR交叉验证 -> 地址稳定性验证 -> 失败回退验证"
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"External coordinate='{navigation.CoordinateText}', parsed={navigation.X},{navigation.Y}, source={navigation.CoordinateSource}, confidence={navigation.CoordinateConfidencePercent}%");
    Console.WriteLine($"OpenProcess(VM_READ)={openSucceeded}, error={openLastError}");
    if (scan is null)
    {
        Console.WriteLine("Memory scan skipped: screenshot/OCR coordinate anchor is not ready.");
    }
    else
    {
        Console.WriteLine($"Memory regions visited={scan.RegionsVisited}, readable={scan.ReadableRegions}, calls={scan.ReadProcessMemoryCalls}, failed={scan.FailedReadCalls}, bytes={scan.BytesRead}, hits={scan.HitCount}, stopped={scan.StoppedReason}");
        foreach (var hit in scan.Hits.Take(12))
            Console.WriteLine($"  hit {hit.PatternLabel} address={hit.Address}, region={hit.RegionBase}, offset={hit.OffsetInRegion}");
        if (scan.Hits.Count > 12)
            Console.WriteLine($"  ... {scan.Hits.Count - 12} more hits omitted from console; see JSON.");
    }
    Console.WriteLine("Safety=no-input,no-click,vm-read-bounded-text-search,no-pointer-scan,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && navigation.HasCoordinate
             && openSucceeded
             && scan is not null
             && scan.ReadProcessMemoryCalls > 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

