        moduleSize = process.MainModule?.ModuleMemorySize ?? 0;
    }
    catch
    {
        // The JSON below records missing module data; no retry with broader behavior is attempted.
    }

    const uint PROCESS_VM_READ = 0x0010;
    const uint PROCESS_QUERY_INFORMATION = 0x0400;
    const long maxBytesToRead = 96L * 1024 * 1024;
    const int maxRegionsToVisit = 2048;
    const int maxHits = 64;
    const int maxChunkBytes = 1024 * 1024;
    const ulong maxUserAddress = 0x7FFF_FFFFUL;
    const int externalBaseOffset = 0x105EA78;
    const int externalXOffset = 0x5C;
    const int externalYOffset = 0x64;

    var openSucceeded = false;
    var openLastError = 0;
    ReadOnlyCoordinateKnownChainResult? knownChain = null;
    ReadOnlyCoordinateFloatPairScanResult? scan = null;

    var handle = ReadOnlyMemoryNative.OpenProcess(
        PROCESS_QUERY_INFORMATION | PROCESS_VM_READ,
        false,
        window.Pid);
    try
    {
        openSucceeded = handle != 0;
        if (!openSucceeded)
        {
            openLastError = Marshal.GetLastWin32Error();
        }
        else if (navigation is { X: not null, Y: not null })
        {
            knownChain = TryReadExternalCoordinateReferenceChain(
                handle,
                moduleBase,
                externalBaseOffset,
                externalXOffset,
                externalYOffset,
                navigation.X.Value,
                navigation.Y.Value);

            scan = ScanReadableMemoryForCoordinateFloatPairs(
                handle,
                navigation.X.Value,
                navigation.Y.Value,
                maxBytesToRead,
                maxRegionsToVisit,
                maxHits,
                maxChunkBytes,
                maxUserAddress);
        }
    }
    finally
    {
        if (handle != 0)
            ReadOnlyMemoryNative.CloseHandle(handle);
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "readonly-coordinate-numeric-candidates");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"readonly-coordinate-numeric-candidates-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-coordinate-numeric-candidates-ocr-anchor-known-chain-and-float-pair-scan-no-input-no-business",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = openSucceeded,
            enumeratesMemoryRegions = openSucceeded && navigation.HasCoordinate,
            scansPointers = false,
            callsReadProcessMemory = (knownChain?.ReadCalls ?? 0) + (scan?.ReadProcessMemoryCalls ?? 0) > 0,
            readsCandidateStateMemory = (knownChain?.ReadSucceeded ?? false) || (scan?.BytesRead ?? 0) > 0,
            readsGameStateMemory = (knownChain?.ReadSucceeded ?? false) || (scan?.BytesRead ?? 0) > 0,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        scope = new
        {
            stage = "B-candidate-research",
            field = "Scene.Coordinate",
            description = "Uses screenshot/OCR coordinate as anchor; validates an external read-only float pointer-chain candidate and scans readable memory for float pair candidates.",
            readClassification = "bounded-readable-memory-numeric-candidate-search",
            coordinateMustBeCrossValidated = true,
            mayEnterBusinessDecision = false,
            fallbackRequiredForAutomation = true
        },
        externalReference = new
        {
            sources = new[]
            {
                @"docs\runtime\external-research\AutoTLBB\4you.CT",
                @"docs\runtime\external-research\AutoTLBB\Client2D.CT"
            },
            basePointer = $"Game.exe+0x{externalBaseOffset:X}",
            xOffset = $"0x{externalXOffset:X}",
            yOffset = $"0x{externalYOffset:X}",
            variableType = "Float",
            importedAsBusinessConfig = false
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256,
            moduleBase = moduleBase == 0 ? "-" : $"0x{moduleBase.ToInt64():X}",
            moduleSize
        },
        externalAnchor = new
        {
            navigation.MapNameText,
            navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y,
            navigation.HasCoordinate,
            dictionaries = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        knownChain,
        scanLimits = new
        {
            maxBytesToRead,
            maxRegionsToVisit,
            maxHits,
            maxChunkBytes,
            maxUserAddress = $"0x{maxUserAddress:X}",
            pairGaps = new[] { 4, 8, 12, 16 },
            matchModes = new[] { "direct-round", "direct-floor", "scaled10-round", "scaled10-floor" }
        },
        floatPairScan = scan is null
            ? (object)new
            {
                skipped = true,
                skipReason = navigation.HasCoordinate
                    ? "未执行扫描。"
                    : "截图/OCR 未取得可解析坐标，禁止无锚点盲扫。"
            }
            : new
            {
                skipped = false,
                scan.RegionsVisited,
                scan.ReadableRegions,
                scan.ReadProcessMemoryCalls,
                scan.FailedReadCalls,
                scan.BytesRead,
                scan.HitCount,
                scan.StoppedReason,
                hits = scan.Hits.Select(h => new
                {
                    h.AddressX,
                    h.AddressY,
                    h.RegionBase,
                    h.RegionSize,
                    h.OffsetInRegion,
                    h.GapBytes,
                    h.XValue,
                    h.YValue,
                    h.MatchMode
                }).ToArray()
            },
        gates = new
        {
            anchorReady = navigation.HasCoordinate,
            openProcessReady = openSucceeded,
            knownChainReadExecuted = knownChain is not null,
            knownChainLooksPlausible = knownChain?.LooksPlausible ?? false,
            floatPairSearchExecuted = scan is not null,
            foundAnyFloatPairCandidate = scan?.HitCount > 0,
            stableFieldReady = false,
            mayEnterBusinessDecision = false,
            nextRequiredGate = "移动到至少3个不同坐标 -> 重复采样 -> 验证候选同步变化 -> 重启客户端验证漂移 -> 失败回退验证"
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"External coordinate='{navigation.CoordinateText}', parsed={navigation.X},{navigation.Y}, source={navigation.CoordinateSource}, confidence={navigation.CoordinateConfidencePercent}%");
    Console.WriteLine($"OpenProcess(VM_READ)={openSucceeded}, error={openLastError}");
    if (knownChain is null)
    {
        Console.WriteLine("Known chain skipped: screenshot/OCR coordinate anchor is not ready.");
    }
    else
    {
        Console.WriteLine($"Known chain read={knownChain.ReadSucceeded}, ptr={knownChain.PointerAddress}, x={knownChain.XValue}, y={knownChain.YValue}, match={knownChain.MatchMode}, plausible={knownChain.LooksPlausible}, error={knownChain.LastError}");
    }
    if (scan is null)
    {
        Console.WriteLine("Float pair scan skipped: screenshot/OCR coordinate anchor is not ready.");
    }
    else
    {
        Console.WriteLine($"Float pairs regions visited={scan.RegionsVisited}, readable={scan.ReadableRegions}, calls={scan.ReadProcessMemoryCalls}, failed={scan.FailedReadCalls}, bytes={scan.BytesRead}, hits={scan.HitCount}, stopped={scan.StoppedReason}");
        foreach (var hit in scan.Hits.Take(12))
            Console.WriteLine($"  hit {hit.MatchMode} x={hit.XValue:0.000} y={hit.YValue:0.000} addressX={hit.AddressX} gap={hit.GapBytes}");
        if (scan.Hits.Count > 12)
            Console.WriteLine($"  ... {scan.Hits.Count - 12} more hits omitted from console; see JSON.");
    }
    Console.WriteLine("Safety=no-input,no-click,vm-read-known-chain-and-bounded-float-scan,no-pointer-scan,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && navigation.HasCoordinate
             && openSucceeded
             && knownChain is not null
             && scan is not null
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReadOnlyCoordinateNumericStabilityDiagnostics(string[] args)
{
    Console.WriteLine("Read-only coordinate numeric stability diagnostics");

    var sampleCount = ParsePositiveIntArg(args, 0, 4, min: 2, max: 12);
    var delayMs = ParsePositiveIntArg(args, 1, 1500, min: 500, max: 10000);

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var hwnd = ResolveGameWindowHandle(args, provider, out var selectionText);
    if (hwnd == nint.Zero)
        return false;

    Console.WriteLine(selectionText);
    var window = binding.BindByHandle(hwnd);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var probeResult = probe.Probe(window);

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var navigationConfig = returnPoints.Current.NavigationRecognition;
    var scene = provider.GetRequiredService<ISceneStateService>();
    var firstNavigation = scene.Recognize(window, navigationConfig);

    const uint PROCESS_VM_READ = 0x0010;
    const uint PROCESS_QUERY_INFORMATION = 0x0400;
    const long maxBytesToRead = 96L * 1024 * 1024;
    const int maxRegionsToVisit = 2048;
    const int maxHits = 64;
    const int maxChunkBytes = 1024 * 1024;
    const ulong maxUserAddress = 0x7FFF_FFFFUL;
    const int maxTrackedCandidates = 16;

    var openSucceeded = false;
    var openLastError = 0;
    ReadOnlyCoordinateFloatPairScanResult? initialScan = null;
    var tracked = Array.Empty<ReadOnlyCoordinateFloatPairHit>();
    var samples = new List<ReadOnlyCoordinateNumericStabilitySample>();

    var handle = ReadOnlyMemoryNative.OpenProcess(
        PROCESS_QUERY_INFORMATION | PROCESS_VM_READ,
        false,
        window.Pid);
    try
    {
        openSucceeded = handle != 0;
        if (!openSucceeded)
        {
            openLastError = Marshal.GetLastWin32Error();
        }
        else if (firstNavigation is { X: not null, Y: not null })
        {
            initialScan = ScanReadableMemoryForCoordinateFloatPairs(
                handle,
                firstNavigation.X.Value,
                firstNavigation.Y.Value,
                maxBytesToRead,
                maxRegionsToVisit,
                maxHits,
                maxChunkBytes,
                maxUserAddress);
            tracked = initialScan.Hits.Take(maxTrackedCandidates).ToArray();

            for (var i = 0; i < sampleCount; i++)
            {
                if (i > 0)
                    Thread.Sleep(delayMs);

                var navigation = scene.Recognize(window, navigationConfig);
                var candidateValues = ReadTrackedCoordinateCandidates(handle, tracked, navigation).ToArray();
                samples.Add(new ReadOnlyCoordinateNumericStabilitySample(
                    i + 1,
                    DateTimeOffset.Now,
                    navigation.CoordinateText,
                    navigation.CoordinateSource,
                    navigation.CoordinateConfidencePercent,
                    navigation.X,
                    navigation.Y,
                    navigation.HasCoordinate,
                    candidateValues));

                Console.WriteLine($"Sample {i + 1}/{sampleCount}: coord='{navigation.CoordinateText}' parsed={navigation.X},{navigation.Y}, candidates={candidateValues.Length}, matches={candidateValues.Count(v => v.MatchesAnchor)}");
            }
        }
    }
    finally
    {
        if (handle != 0)
            ReadOnlyMemoryNative.CloseHandle(handle);
    }

    var coordinateKeys = samples
        .Where(s => s.HasCoordinate && s.X is not null && s.Y is not null)
        .Select(s => $"{s.X},{s.Y}")
        .Distinct(StringComparer.Ordinal)
        .ToArray();

    var summaries = tracked
        .Select(hit =>
        {
            var reads = samples
                .SelectMany(s => s.Candidates.Select(c => new { Sample = s, Candidate = c }))
                .Where(x => x.Candidate.AddressX == hit.AddressX && x.Candidate.AddressY == hit.AddressY)
                .ToArray();
            var matched = reads.Where(x => x.Candidate.MatchesAnchor).ToArray();
            return new
            {
                hit.AddressX,
                hit.AddressY,
                hit.RegionBase,
                hit.GapBytes,
                initialX = hit.XValue,
                initialY = hit.YValue,
                hit.MatchMode,
                readCount = reads.Length,
                readSucceededCount = reads.Count(x => x.Candidate.ReadSucceeded),
                matchCount = matched.Length,
                matchedCoordinateCount = matched
                    .Select(x => $"{x.Sample.X},{x.Sample.Y}")
                    .Distinct(StringComparer.Ordinal)
                    .Count(),
                firstValue = reads.FirstOrDefault()?.Candidate is { } first ? new { first.XValue, first.YValue, first.MatchMode } : null,
                lastValue = reads.LastOrDefault()?.Candidate is { } last ? new { last.XValue, last.YValue, last.MatchMode } : null,
                candidateStableWithinCurrentRun = reads.Length == sampleCount
                    && reads.All(x => x.Candidate.ReadSucceeded)
                    && matched.Length == sampleCount
                    && coordinateKeys.Length >= 3
            };
        })
        .ToArray();

    var stableWithinRunCount = summaries.Count(s => s.candidateStableWithinCurrentRun);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "readonly-coordinate-numeric-stability");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"readonly-coordinate-numeric-stability-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-coordinate-numeric-stability-no-input-no-business",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = openSucceeded,
            enumeratesMemoryRegions = openSucceeded && firstNavigation.HasCoordinate,
            scansPointers = false,
            callsReadProcessMemory = (initialScan?.ReadProcessMemoryCalls ?? 0) + samples.Sum(s => s.Candidates.Count(c => c.ReadAttempted)) > 0,
            readsCandidateStateMemory = (initialScan?.BytesRead ?? 0) > 0 || samples.Any(s => s.Candidates.Any(c => c.ReadSucceeded)),
            readsGameStateMemory = (initialScan?.BytesRead ?? 0) > 0 || samples.Any(s => s.Candidates.Any(c => c.ReadSucceeded)),
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        scope = new
        {
            stage = "B-stability-research",
            field = "Scene.Coordinate",
            description = "Scans numeric coordinate candidates once, then repeatedly re-reads tracked candidates and compares them with screenshot/OCR coordinates.",
            mayEnterBusinessDecision = false,
            fallbackRequiredForAutomation = true
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256
        },
        runtimeData = new
        {
            dictionaries = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        initialAnchor = new
        {
            firstNavigation.CoordinateText,
            firstNavigation.CoordinateSource,
            firstNavigation.CoordinateConfidencePercent,
            firstNavigation.X,
            firstNavigation.Y,
            firstNavigation.HasCoordinate
        },
        scanLimits = new
        {
            maxBytesToRead,
            maxRegionsToVisit,
            maxHits,
            maxChunkBytes,
            maxUserAddress = $"0x{maxUserAddress:X}",
            maxTrackedCandidates,
            sampleCount,
            delayMs
        },
        initialScan = initialScan is null
            ? null
            : new
            {
                initialScan.RegionsVisited,
                initialScan.ReadableRegions,
                initialScan.ReadProcessMemoryCalls,
                initialScan.FailedReadCalls,
                initialScan.BytesRead,
                initialScan.HitCount,
                initialScan.StoppedReason
            },
        trackedCandidates = tracked,
        samples,
        coordinateDistinctCount = coordinateKeys.Length,
        coordinateKeys,
        candidateSummaries = summaries,
        gates = new
        {
            anchorReady = firstNavigation.HasCoordinate,
            openProcessReady = openSucceeded,
            initialScanExecuted = initialScan is not null,
            trackedCandidateCount = tracked.Length,
            sampleCount,
            coordinateDistinctCount = coordinateKeys.Length,
            stableWithinRunCount,
            enoughMovementObserved = coordinateKeys.Length >= 3,
            restartValidated = false,
            stableFieldReady = false,
            mayEnterBusinessDecision = false,
            nextRequiredGate = coordinateKeys.Length >= 3
                ? "重启客户端后复测同一字段漂移；通过后才能考虑进入 ReadOnlyRuntimeStateProvider 候选实现"
                : "移动到至少3个不同坐标后重新运行本命令，筛掉单点假阳性"
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"OpenProcess(VM_READ)={openSucceeded}, error={openLastError}");
    Console.WriteLine($"Initial scan hits={initialScan?.HitCount ?? 0}, tracked={tracked.Length}, samples={samples.Count}, distinctCoords={coordinateKeys.Length}, stableWithinRun={stableWithinRunCount}");
    Console.WriteLine("Safety=no-input,no-click,vm-read-continuous-candidate-reread,no-pointer-scan,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && firstNavigation.HasCoordinate
             && openSucceeded
             && initialScan is not null
             && tracked.Length > 0
             && samples.Count == sampleCount
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunRuntimeFieldCandidatesDiagnostics()
{
    Console.WriteLine("Runtime field candidate diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var probeResult = probe.Probe(window);
    var snapshotService = provider.GetRequiredService<IRuntimeSnapshotService>();
    var snapshots = snapshotService.ReadAll(window).ToArray();
    var screenshot = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ScreenshotOcr);
    var readOnly = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ReadOnlyProcess);
    var candidates = BuildRuntimeFieldCandidates(screenshot, readOnly).ToArray();

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "runtime-field-candidates");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"runtime-field-candidates-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-runtime-field-candidates-no-memory-state-read-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            enumeratesMemoryRegions = false,
            scansPointers = false,
            callsReadProcessMemory = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256
        },
        providerSummary = snapshots.Select(s => new
        {
            provider = s.Provider.ToString(),
            quality = s.Quality.ToString(),
            s.Source,
            s.ConfidencePercent,
            s.Message
        }).ToArray(),
        candidateCount = candidates.Length,
        candidates
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"Candidates={candidates.Length}");
    foreach (var item in candidates)
    {
        Console.WriteLine(
            $"  {item.Category}.{item.Field}: external={item.ExternalStatus}/{item.ExternalSource}/{item.ExternalConfidencePercent}%, readonly={item.ReadOnlyMemoryStatus}, business={item.BusinessStatus}, value={item.CurrentValue}");
    }
    Console.WriteLine("Safety=no-input,no-click,no-vm-read,no-memory-region-scan,no-pointer-scan,no-readprocessmemory,no-memory-state-read,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && candidates.Length >= 12
             && candidates.All(c => c.ReadOnlyMemoryStatus == "NotStarted")
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunRuntimeFieldStabilityDiagnostics()
{
    Console.WriteLine("Runtime field stability diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var probe = provider.GetRequiredService<IReadOnlyGameProcessProbe>();
    var probeResult = probe.Probe(window);
    var snapshotService = provider.GetRequiredService<IRuntimeSnapshotService>();

    const int sampleCount = 5;
    const int intervalMs = 250;
    var samples = new List<IReadOnlyList<RuntimeFieldCandidateEvidence>>();
    var providerSummaries = new List<object>();
    for (var i = 0; i < sampleCount; i++)
    {
        var snapshots = snapshotService.ReadAll(window).ToArray();
        var screenshot = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ScreenshotOcr);
        var readOnly = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ReadOnlyProcess);
        samples.Add(BuildRuntimeFieldCandidates(screenshot, readOnly));
        providerSummaries.Add(new
        {
            index = i + 1,
            capturedAt = DateTimeOffset.Now,
            providers = snapshots.Select(s => new
            {
                provider = s.Provider.ToString(),
                quality = s.Quality.ToString(),
                s.Source,
                s.ConfidencePercent,
                s.Message
            }).ToArray()
        });

        if (i < sampleCount - 1)
            Thread.Sleep(intervalMs);
    }

    var stability = BuildRuntimeFieldStability(samples).ToArray();
    var fieldEvidenceOk = stability.All(HasRuntimeFieldStabilityEvidence);
    var businessGateOk = stability.All(s => !s.BusinessDecisionAllowed && s.BusinessStatus != "BusinessReady");
    var noReadOnlyStateUse = stability.All(s => s.ReadOnlyMemoryStatus == "NotStarted");

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "runtime-field-stability");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"runtime-field-stability-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-runtime-field-stability-no-memory-state-read-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            enumeratesMemoryRegions = false,
            scansPointers = false,
            callsReadProcessMemory = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        sampling = new
        {
            sampleCount,
            intervalMs,
            rule = "字段稳定性只作为下一步单字段验证门槛；不代表可直接进入业务决策。"
        },
        scope = new
        {
            stage = "B-field-stability",
            description = "external screenshot/OCR runtime fields sampled for stability; read-only game state is not used for business decisions",
            businessDecisionReady = false,
            unstableFieldsBlockedFromBusiness = true,
            unavailableFieldsBlockedFromBusiness = true,
            nextStep = "single-field cross validation before any business integration"
        },
        window = new
        {
            hwnd = window.Hwnd == 0 ? "-" : $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            clientType = window.ClientType.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            probeStatus = probeResult.Status,
            probeSha256 = probeResult.MainModuleSha256
        },
        providerSummaries,
        fieldCount = stability.Length,
        stableFieldCount = stability.Count(s => s.StabilityStatus == "Stable"),
        mostlyStableFieldCount = stability.Count(s => s.StabilityStatus == "MostlyStable"),
        unavailableFieldCount = stability.Count(s => s.StabilityStatus == "Unavailable"),
        unstableFieldCount = stability.Count(s => s.StabilityStatus == "Unstable"),
        businessDecisionAllowedFieldCount = stability.Count(s => s.BusinessDecisionAllowed),
        evidenceSelfCheck = new
        {
            fieldEvidenceOk,
            businessGateOk,
            noReadOnlyStateUse,
            passes = fieldEvidenceOk && businessGateOk && noReadOnlyStateUse
        },
        fields = stability
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Probe={probeResult.Status}, SHA256={probeResult.MainModuleSha256}");
    Console.WriteLine($"Samples={sampleCount}, intervalMs={intervalMs}, fields={stability.Length}");
    foreach (var item in stability)
    {
        Console.WriteLine(
            $"  {item.Category}.{item.Field}: status={item.StabilityStatus}, source={item.EvidenceSource}, available={item.AvailableSamples}/{item.SampleCount}, distinct={item.DistinctValueCount}, confidence={item.AverageConfidencePercent}%, readonly={item.ReadOnlyMemoryStatus}, businessAllowed={item.BusinessDecisionAllowed}, values=[{string.Join(" | ", item.Values)}]");
    }
    Console.WriteLine("Safety=no-input,no-click,no-vm-read,no-memory-region-scan,no-pointer-scan,no-readprocessmemory,no-memory-state-read,no-write,no-inject,no-hook,no-patch,no-business-decision");
    Console.WriteLine($"EvidenceSelfCheck={fieldEvidenceOk && businessGateOk && noReadOnlyStateUse}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && probeResult.Success
             && samples.Count == sampleCount
             && stability.Length >= 12
             && fieldEvidenceOk
             && businessGateOk
             && noReadOnlyStateUse
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static IReadOnlyList<RuntimeFieldCandidateEvidence> BuildRuntimeFieldCandidates(
    RuntimeSnapshot? screenshot,
    RuntimeSnapshot? readOnly)
{
    var result = new List<RuntimeFieldCandidateEvidence>();
    var memorySource = readOnly?.Source ?? "read-only-process";
    var gate = "需要先定位只读字段、保存候选地址证据、与截图/OCR交叉验证，并标注稳定性后才允许接入业务。";

    result.Add(Field("Player", "HpPercent", Value(screenshot?.Player.HpPercent), screenshot?.Player.Source, screenshot?.Player.Quality, screenshot?.Player.ConfidencePercent, memorySource, "回血阈值判断", gate));
    result.Add(Field("Player", "MpPercent", Value(screenshot?.Player.MpPercent), screenshot?.Player.Source, screenshot?.Player.Quality, screenshot?.Player.ConfidencePercent, memorySource, "回蓝阈值判断", gate));
    result.Add(Field("Player", "IsDead", Value(screenshot?.Player.IsDead), screenshot?.Player.Source, screenshot?.Player.Quality, screenshot?.Player.ConfidencePercent, memorySource, "死亡回点判断", gate));
    var hasSchool = !string.IsNullOrWhiteSpace(screenshot?.Player.School);
    result.Add(Field("Player", "School", Value(screenshot?.Player.School), hasSchool ? screenshot?.Player.Source : null, hasSchool ? screenshot?.Player.Quality : RuntimeSnapshotQuality.Unavailable, hasSchool ? screenshot?.Player.ConfidencePercent : 0, memorySource, "门派预设/技能策略", gate));

    result.Add(Field("Target", "Name", Value(screenshot?.Target.Name), screenshot?.Target.Source, screenshot?.Target.Quality, screenshot?.Target.ConfidencePercent, memorySource, "目标过滤/日志", gate));
    result.Add(Field("Target", "HpPercent", Value(screenshot?.Target.HpPercent), screenshot?.Target.Source, screenshot?.Target.Quality, screenshot?.Target.ConfidencePercent, memorySource, "打死换怪", gate));
    result.Add(Field("Target", "IsPlayer", Value(screenshot?.Target.IsPlayer), screenshot?.Target.Source, screenshot?.Target.Quality, screenshot?.Target.ConfidencePercent, memorySource, "玩家保护", gate));
    result.Add(Field("Target", "IsAttackable", Value(screenshot?.Target.IsAttackable), screenshot?.Target.Source, screenshot?.Target.Quality, screenshot?.Target.ConfidencePercent, memorySource, "是否释放普攻/技能", gate));

    result.Add(Field("Pet", "HpPercent", Value(screenshot?.Pet.HpPercent), screenshot?.Pet.Source, screenshot?.Pet.Quality, screenshot?.Pet.ConfidencePercent, memorySource, "宠物回血/宠粮", gate));
    result.Add(Field("Pet", "IsSummoned", Value(screenshot?.Pet.IsSummoned), screenshot?.Pet.Source, screenshot?.Pet.Quality, screenshot?.Pet.ConfidencePercent, memorySource, "宠物出战/技能区域点击", gate));

    var hasMap = !string.IsNullOrWhiteSpace(screenshot?.Scene.MapName);
    var hasCoordinate = screenshot?.Scene.X is not null && screenshot.Scene.Y is not null;
    var hasDungeonFlag = screenshot?.Scene.IsDungeon is not null;
    result.Add(Field("Scene", "MapName", Value(screenshot?.Scene.MapName), screenshot?.Scene.MapNameSource, hasMap ? screenshot?.Scene.Quality : RuntimeSnapshotQuality.Unavailable, screenshot?.Scene.MapNameConfidencePercent, memorySource, "回点/野外副本判断", gate));
    result.Add(Field("Scene", "Coordinate", hasCoordinate ? $"{screenshot!.Scene.X},{screenshot.Scene.Y}" : "-", screenshot?.Scene.CoordinateSource, hasCoordinate ? screenshot?.Scene.Quality : RuntimeSnapshotQuality.Unavailable, screenshot?.Scene.CoordinateConfidencePercent, memorySource, "偏离距离/卡点恢复", gate));
    result.Add(Field("Scene", "ReturnPointFieldReady", Value(screenshot?.Scene.ReturnPointFieldReady), screenshot?.Scene.Source, screenshot?.Scene.ReturnPointFieldReady == true ? screenshot?.Scene.Quality : RuntimeSnapshotQuality.Unavailable, screenshot?.Scene.ConfidencePercent, memorySource, $"自动回点门控：{screenshot?.Scene.GateReason ?? "-"}", gate));
    result.Add(Field("Scene", "IsDungeon", Value(screenshot?.Scene.IsDungeon), hasDungeonFlag ? screenshot?.Scene.Source : null, hasDungeonFlag ? screenshot?.Scene.Quality : RuntimeSnapshotQuality.Unavailable, hasDungeonFlag ? screenshot?.Scene.ConfidencePercent : 0, memorySource, "内置挂机/外部打怪自动判断", gate));

    result.Add(Field("Inventory", "IsOpen", Value(screenshot?.Inventory.IsOpen), screenshot?.Inventory.Source, screenshot?.Inventory.Quality, screenshot?.Inventory.ConfidencePercent, memorySource, "清包候选生成", gate));
    result.Add(Field("Inventory", "UsedSlots", Value(screenshot?.Inventory.UsedSlots), screenshot?.Inventory.Source, screenshot?.Inventory.Quality, screenshot?.Inventory.ConfidencePercent, memorySource, "清包触发/容量告警", gate));
    result.Add(Field("Inventory", "SellCandidateCount", screenshot is null ? "-" : screenshot.Inventory.SellCandidateCount.ToString(), screenshot?.Inventory.Source, screenshot?.Inventory.Quality, screenshot?.Inventory.ConfidencePercent, memorySource, "只读候选统计，不默认出售", gate));

    return result;
}

static RuntimeFieldCandidateEvidence Field(
    string category,
    string field,
    string currentValue,
    string? externalSource,
    RuntimeSnapshotQuality? externalQuality,
    int? externalConfidence,
    string readOnlySource,
    string businessPurpose,
    string validationGate)
{
    var quality = externalQuality ?? RuntimeSnapshotQuality.Unavailable;
    var externalStatus = quality switch
    {
        RuntimeSnapshotQuality.Reliable => "Available",
        RuntimeSnapshotQuality.Partial => "Partial",
        _ => "Unavailable"
    };

    return new RuntimeFieldCandidateEvidence(
        category,
        field,
        currentValue,
        string.IsNullOrWhiteSpace(externalSource) ? "external-unavailable" : externalSource.Trim(),
        externalStatus,
        Math.Clamp(externalConfidence ?? 0, 0, 100),
        readOnlySource,
        "NotStarted",
        businessPurpose,
        "ExternalOnly",
        validationGate);
}

static string Value<T>(T? value) => value is null ? "-" : value.ToString() ?? "-";

static IReadOnlyList<RuntimeFieldStabilityEvidence> BuildRuntimeFieldStability(
    IReadOnlyList<IReadOnlyList<RuntimeFieldCandidateEvidence>> samples)
{
    var groups = samples
        .SelectMany((sample, sampleIndex) => sample.Select(field => new { SampleIndex = sampleIndex + 1, Field = field }))
        .GroupBy(x => (x.Field.Category, x.Field.Field))
        .OrderBy(g => g.Key.Category, StringComparer.Ordinal)
        .ThenBy(g => g.Key.Field, StringComparer.Ordinal);

    var result = new List<RuntimeFieldStabilityEvidence>();
    foreach (var group in groups)
    {
        var fields = group
            .OrderBy(x => x.SampleIndex)
            .Select(x => x.Field)
            .ToArray();
        var values = fields.Select(f => f.CurrentValue).ToArray();
        var availableValues = fields
            .Where(f => f.ExternalStatus != "Unavailable" && !string.IsNullOrWhiteSpace(f.CurrentValue) && f.CurrentValue != "-")
            .Select(f => f.CurrentValue)
            .ToArray();
        var distinctValues = availableValues
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        var confidences = fields.Select(f => f.ExternalConfidencePercent).ToArray();
        var availableSamples = availableValues.Length;
        var sampleCount = fields.Length;
        var averageConfidence = confidences.Length == 0
            ? 0
            : (int)Math.Round(confidences.Average());
        var minConfidence = confidences.Length == 0 ? 0 : confidences.Min();
        var maxConfidence = confidences.Length == 0 ? 0 : confidences.Max();
        var readOnlyStatus = fields.Select(f => f.ReadOnlyMemoryStatus)
            .Distinct(StringComparer.Ordinal)
            .SingleOrDefault() ?? "Mixed";
        var evidenceSources = fields.Select(f => f.ExternalSource)
            .Where(v => !string.IsNullOrWhiteSpace(v))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        var evidenceSource = evidenceSources.Length == 0
            ? "external-unavailable"
            : string.Join(",", evidenceSources);
        var businessStatus = fields.Select(f => f.BusinessStatus)
            .Distinct(StringComparer.Ordinal)
            .SingleOrDefault() ?? "Mixed";
        var businessPurpose = fields.Select(f => f.BusinessPurpose)
            .FirstOrDefault(v => !string.IsNullOrWhiteSpace(v)) ?? string.Empty;
        var validationGate = fields.Select(f => f.ValidationGate)
            .FirstOrDefault(v => !string.IsNullOrWhiteSpace(v)) ?? "阶段 B 只允许诊断，不允许进入业务。";

        var stabilityStatus = availableSamples == 0
            ? "Unavailable"
            : availableSamples == sampleCount && distinctValues.Length == 1
                ? "Stable"
                : availableSamples >= sampleCount - 1 && distinctValues.Length <= 2
                    ? "MostlyStable"
                    : "Unstable";

        var nextGate = stabilityStatus switch
        {
            "Stable" => "可进入下一步单字段交叉验证；仍不可直接接入业务。",
            "MostlyStable" => "需要扩大采样并排查漂移来源；不可接入业务。",
            "Unavailable" => "当前不可用；不可接入业务。",
            _ => "不稳定；不可接入业务。"
        };

        result.Add(new RuntimeFieldStabilityEvidence(
            group.Key.Category,
            group.Key.Field,
            evidenceSource,
            sampleCount,
            availableSamples,
            distinctValues.Length,
            values,
            distinctValues,
            minConfidence,
            maxConfidence,
            averageConfidence,
            stabilityStatus,
            readOnlyStatus,
            businessStatus,
            false,
            businessPurpose,
            validationGate,
            nextGate));
    }

    return result;
}

static bool HasRuntimeFieldStabilityEvidence(RuntimeFieldStabilityEvidence item)
{
    var statusOk = item.StabilityStatus is "Stable" or "MostlyStable" or "Unavailable" or "Unstable";
    return !string.IsNullOrWhiteSpace(item.Category)
           && !string.IsNullOrWhiteSpace(item.Field)
           && !string.IsNullOrWhiteSpace(item.EvidenceSource)
           && item.SampleCount > 0
           && item.AvailableSamples >= 0
           && item.AvailableSamples <= item.SampleCount
           && item.DistinctValueCount >= 0
           && item.Values.Count == item.SampleCount
           && item.MinConfidencePercent >= 0
           && item.MinConfidencePercent <= 100
           && item.MaxConfidencePercent >= 0
           && item.MaxConfidencePercent <= 100
           && item.AverageConfidencePercent >= 0
           && item.AverageConfidencePercent <= 100
           && statusOk
           && !string.IsNullOrWhiteSpace(item.ReadOnlyMemoryStatus)
           && !string.IsNullOrWhiteSpace(item.BusinessStatus)
           && !item.BusinessDecisionAllowed
           && !string.IsNullOrWhiteSpace(item.BusinessPurpose)
           && !string.IsNullOrWhiteSpace(item.ValidationGate)
           && !string.IsNullOrWhiteSpace(item.NextGate);
}

static bool RunRuntimeSnapshotDiagnostics()
{
    Console.WriteLine("Runtime snapshot diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    const int loaded = 0;

    var runtimeSnapshotService = provider.GetRequiredService<IRuntimeSnapshotService>();
    var snapshots = runtimeSnapshotService.ReadAll(window).ToArray();
    var preferredReadOnlySnapshot = runtimeSnapshotService.Read(window, RuntimeStateProviderKind.ReadOnlyProcess);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "runtime-snapshot");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"runtime-snapshot-{window.Pid}-{stamp}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-runtime-snapshot-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            enumeratesMemoryRegions = false,
            scansPointers = false,
            callsReadProcessMemory = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        scope = new
        {
            stage = "B-entry",
            description = "aggregate external screenshot runtime snapshot and read-only process metadata",
            readOnlyProcessBusinessFieldsReady = false,
            fallbackRequiredForUnverifiedFields = true
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            dictionaryLoadMode = "skipped-for-fast-runtime-snapshot",
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        snapshots = snapshots.Select(ToEvidence).ToArray(),
        preferredReadOnlyFallback = new
        {
            requestedProvider = RuntimeStateProviderKind.ReadOnlyProcess.ToString(),
            returnedProvider = preferredReadOnlySnapshot.Provider.ToString(),
            preferredReadOnlySnapshot.Source,
            quality = preferredReadOnlySnapshot.Quality.ToString(),
            fallbackUsed = preferredReadOnlySnapshot.Provider != RuntimeStateProviderKind.ReadOnlyProcess,
            preferredReadOnlySnapshot.Message
        },
        fieldAudit = BuildRuntimeFieldAudit(snapshots)
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded} (skipped), glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    foreach (var snapshot in snapshots)
    {
        Console.WriteLine($"{snapshot.Provider}: quality={snapshot.Quality}, confidence={snapshot.ConfidencePercent}, source={snapshot.Source}");
        Console.WriteLine($"  {snapshot.Message}");
        Console.WriteLine($"  Target name={snapshot.Target.Name ?? "-"}, hp={snapshot.Target.HpPercent?.ToString() ?? "-"}, player={snapshot.Target.IsPlayer?.ToString() ?? "-"}, pet={snapshot.Target.IsPet?.ToString() ?? "-"}, attackable={snapshot.Target.IsAttackable?.ToString() ?? "-"}");
        Console.WriteLine($"  Player hp={snapshot.Player.HpPercent?.ToString() ?? "-"}, mp={snapshot.Player.MpPercent?.ToString() ?? "-"}, dead={snapshot.Player.IsDead?.ToString() ?? "-"}");
        Console.WriteLine($"  Pet hp={snapshot.Pet.HpPercent?.ToString() ?? "-"}, summoned={snapshot.Pet.IsSummoned?.ToString() ?? "-"}");
        Console.WriteLine($"  Scene map={snapshot.Scene.MapName ?? "-"} [{snapshot.Scene.MapNameSource ?? "-"} {snapshot.Scene.MapNameConfidencePercent}%], coord={snapshot.Scene.X?.ToString() ?? "-"},{snapshot.Scene.Y?.ToString() ?? "-"} [{snapshot.Scene.CoordinateSource ?? "-"} {snapshot.Scene.CoordinateConfidencePercent}%]");
        Console.WriteLine($"  Scene gate usable={snapshot.Scene.SceneUsable}, returnPointReady={snapshot.Scene.ReturnPointFieldReady}, reason={snapshot.Scene.GateReason}");
    }
    Console.WriteLine($"Preferred ReadOnlyProcess returned={preferredReadOnlySnapshot.Provider}, source={preferredReadOnlySnapshot.Source}, quality={preferredReadOnlySnapshot.Quality}");
    var fieldAudit = BuildRuntimeFieldAudit(snapshots);
    var readyFieldCount = fieldAudit.Count(f => IsRuntimeFieldBusinessCandidate(f));
    Console.WriteLine($"Field audit entries={fieldAudit.Length}, business-candidates={readyFieldCount}");
    Console.WriteLine($"Evidence={evidencePath}");

    var screenshot = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ScreenshotOcr);
    var readOnly = snapshots.FirstOrDefault(s => s.Provider == RuntimeStateProviderKind.ReadOnlyProcess);
    var readOnlyBusinessReady = readOnly is not null && SnapshotHasBusinessFields(readOnly);
    var ok = window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && screenshot is not null
             && screenshot.Source == "screenshot-ocr"
             && screenshot.Quality != RuntimeSnapshotQuality.Unavailable
             && readOnly is not null
             && readOnly.Source == "read-only-process"
             && (readOnlyBusinessReady || preferredReadOnlySnapshot.Provider == RuntimeStateProviderKind.ScreenshotOcr)
             && fieldAudit.Length >= 30
             && fieldAudit.Any(f => FieldText(f, "category") == "Target" && FieldText(f, "field") == "IsPet")
             && fieldAudit.All(HasRuntimeFieldAuditEvidence)
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool SnapshotHasBusinessFields(RuntimeSnapshot snapshot) =>
    snapshot.Player.Quality != RuntimeSnapshotQuality.Unavailable
    || snapshot.Target.Quality != RuntimeSnapshotQuality.Unavailable
    || snapshot.Pet.Quality != RuntimeSnapshotQuality.Unavailable
    || snapshot.Scene.Quality != RuntimeSnapshotQuality.Unavailable
    || snapshot.Inventory.Quality != RuntimeSnapshotQuality.Unavailable
    || snapshot.Player.HpPercent is not null
    || snapshot.Player.MpPercent is not null
    || snapshot.Player.IsDead is not null
    || snapshot.Target.HpPercent is not null
    || snapshot.Target.IsPlayer is not null
    || snapshot.Target.IsAttackable is not null
    || snapshot.Pet.HpPercent is not null
    || snapshot.Pet.IsSummoned is not null
    || !string.IsNullOrWhiteSpace(snapshot.Scene.MapName)
    || snapshot.Scene.X is not null
    || snapshot.Scene.Y is not null
    || snapshot.Inventory.IsOpen is not null
    || snapshot.Inventory.UsedSlots is not null
    || snapshot.Inventory.TotalSlots is not null
    || snapshot.Inventory.Candidates.Count > 0;

static object ToEvidence(RuntimeSnapshot snapshot) => new
{
    provider = snapshot.Provider.ToString(),
    quality = snapshot.Quality.ToString(),
    snapshot.Source,
    snapshot.ConfidencePercent,
    snapshot.CapturedAt,
    snapshot.Message,
    player = new
    {
        quality = snapshot.Player.Quality.ToString(),
        snapshot.Player.Source,
        snapshot.Player.ConfidencePercent,
        snapshot.Player.HpPercent,
        snapshot.Player.MpPercent,
        snapshot.Player.IsDead,
        snapshot.Player.Name,
        snapshot.Player.School
    },
    target = new
    {
        quality = snapshot.Target.Quality.ToString(),
        snapshot.Target.Source,
        snapshot.Target.ConfidencePercent,
        snapshot.Target.Name,
        snapshot.Target.HpPercent,
        snapshot.Target.IsPlayer,
        snapshot.Target.IsPet,
        snapshot.Target.IsAttackable,
        snapshot.Target.IsLost,
        snapshot.Target.Kind
    },
    pet = new
    {
        quality = snapshot.Pet.Quality.ToString(),
        snapshot.Pet.Source,
        snapshot.Pet.ConfidencePercent,
        snapshot.Pet.HpPercent,
        snapshot.Pet.IsSummoned
    },
    scene = new
    {
        quality = snapshot.Scene.Quality.ToString(),
        snapshot.Scene.Source,
        snapshot.Scene.ConfidencePercent,
        snapshot.Scene.SceneUsable,
        snapshot.Scene.MapFieldReady,
        snapshot.Scene.CoordinateFieldReady,
        snapshot.Scene.ReturnPointFieldReady,
        snapshot.Scene.GateReason,
        snapshot.Scene.MapName,
        snapshot.Scene.MapNameSource,
        snapshot.Scene.MapNameConfidencePercent,
        snapshot.Scene.X,
        snapshot.Scene.Y,
        snapshot.Scene.CoordinateSource,
        snapshot.Scene.CoordinateConfidencePercent,
        snapshot.Scene.IsDungeon
    },
    inventory = new
    {
        quality = snapshot.Inventory.Quality.ToString(),
        snapshot.Inventory.Source,
        snapshot.Inventory.ConfidencePercent,
        snapshot.Inventory.IsOpen,
        snapshot.Inventory.UsedSlots,
        snapshot.Inventory.EmptySlots,
        snapshot.Inventory.TotalSlots,
        snapshot.Inventory.SellCandidateCount,
        snapshot.Inventory.ProtectedCount,
        snapshot.Inventory.Executed,
        candidates = snapshot.Inventory.Candidates
    }
};

static Dictionary<string, object>[] BuildRuntimeFieldAudit(IReadOnlyList<RuntimeSnapshot> snapshots)
{
    var result = new List<Dictionary<string, object>>();
    foreach (var snapshot in snapshots)
    {
        var provider = snapshot.Provider.ToString();
        var readOnlyProcess = snapshot.Provider == RuntimeStateProviderKind.ReadOnlyProcess;

        Add("Player", "Name", snapshot.Player.Name, snapshot.Player.Quality, snapshot.Player.Source, snapshot.Player.ConfidencePercent);
        Add("Player", "HpPercent", snapshot.Player.HpPercent, snapshot.Player.Quality, snapshot.Player.Source, snapshot.Player.ConfidencePercent);
        Add("Player", "MpPercent", snapshot.Player.MpPercent, snapshot.Player.Quality, snapshot.Player.Source, snapshot.Player.ConfidencePercent);
        Add("Player", "IsDead", snapshot.Player.IsDead, snapshot.Player.Quality, snapshot.Player.Source, snapshot.Player.ConfidencePercent);
        Add("Player", "School", snapshot.Player.School, snapshot.Player.Quality, snapshot.Player.Source, snapshot.Player.ConfidencePercent);

        Add("Target", "Name", snapshot.Target.Name, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "HpPercent", snapshot.Target.HpPercent, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "IsPlayer", snapshot.Target.IsPlayer, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "IsPet", snapshot.Target.IsPet, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "IsAttackable", snapshot.Target.IsAttackable, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "IsLost", snapshot.Target.IsLost, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);
        Add("Target", "Kind", snapshot.Target.Kind, snapshot.Target.Quality, snapshot.Target.Source, snapshot.Target.ConfidencePercent);

        Add("Pet", "HpPercent", snapshot.Pet.HpPercent, snapshot.Pet.Quality, snapshot.Pet.Source, snapshot.Pet.ConfidencePercent);
        Add("Pet", "IsSummoned", snapshot.Pet.IsSummoned, snapshot.Pet.Quality, snapshot.Pet.Source, snapshot.Pet.ConfidencePercent);

        Add("Scene", "MapName", snapshot.Scene.MapName, snapshot.Scene.Quality, snapshot.Scene.MapNameSource ?? snapshot.Scene.Source, snapshot.Scene.MapNameConfidencePercent);
        Add("Scene", "X", snapshot.Scene.X, snapshot.Scene.Quality, snapshot.Scene.CoordinateSource ?? snapshot.Scene.Source, snapshot.Scene.CoordinateConfidencePercent);
        Add("Scene", "Y", snapshot.Scene.Y, snapshot.Scene.Quality, snapshot.Scene.CoordinateSource ?? snapshot.Scene.Source, snapshot.Scene.CoordinateConfidencePercent);
        Add("Scene", "IsDungeon", snapshot.Scene.IsDungeon, snapshot.Scene.Quality, snapshot.Scene.Source, snapshot.Scene.ConfidencePercent);
        Add("Scene", "ReturnPointFieldReady", snapshot.Scene.ReturnPointFieldReady, snapshot.Scene.Quality, snapshot.Scene.Source, snapshot.Scene.ConfidencePercent);

        Add("Inventory", "IsOpen", snapshot.Inventory.IsOpen, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "UsedSlots", snapshot.Inventory.UsedSlots, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "EmptySlots", snapshot.Inventory.EmptySlots, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "TotalSlots", snapshot.Inventory.TotalSlots, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "SellCandidateCount", snapshot.Inventory.SellCandidateCount, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "ProtectedCount", snapshot.Inventory.ProtectedCount, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);
        Add("Inventory", "Executed", snapshot.Inventory.Executed, snapshot.Inventory.Quality, snapshot.Inventory.Source, snapshot.Inventory.ConfidencePercent);

        void Add(string category, string field, object? value, RuntimeSnapshotQuality quality, string? source, int confidence)
        {
            var hasValue = value switch
            {
                null => false,
                string s => !string.IsNullOrWhiteSpace(s),
                _ => true
            };
            var availability = quality == RuntimeSnapshotQuality.Unavailable || !hasValue
                ? "Unavailable"
                : quality.ToString();
            var businessStatus = readOnlyProcess
                ? "NotBusinessReady"
                : availability == "Reliable" || availability == "Partial"
                    ? "CandidateOnly"
                    : "FallbackRequired";

            result.Add(new Dictionary<string, object>
            {
                ["provider"] = provider,
                ["category"] = category,
                ["field"] = field,
                ["value"] = value?.ToString() ?? string.Empty,
                ["quality"] = quality.ToString(),
                ["source"] = string.IsNullOrWhiteSpace(source) ? $"{provider}:unavailable" : source,
                ["confidencePercent"] = confidence,
                ["availability"] = availability,
                ["businessStatus"] = businessStatus,
                ["fallbackRequired"] = readOnlyProcess || availability == "Unavailable"
            });
        }
    }

    return result.ToArray();
}

static bool HasRuntimeFieldAuditEvidence(IReadOnlyDictionary<string, object> field) =>
    HasText(field, "provider")
    && HasText(field, "category")
    && HasText(field, "field")
    && HasText(field, "quality")
    && HasText(field, "source")
    && HasText(field, "availability")
    && HasText(field, "businessStatus")
    && TryInt(field, "confidencePercent", out var confidence)
    && confidence >= 0
    && confidence <= 100;

static bool IsRuntimeFieldBusinessCandidate(IReadOnlyDictionary<string, object> field) =>
    string.Equals(FieldText(field, "businessStatus"), "CandidateOnly", StringComparison.Ordinal)
    && !FieldBool(field, "fallbackRequired");

static bool HasText(IReadOnlyDictionary<string, object> field, string key) =>
    field.TryGetValue(key, out var value) && !string.IsNullOrWhiteSpace(value?.ToString());

static string FieldText(IReadOnlyDictionary<string, object> field, string key) =>
    field.TryGetValue(key, out var value) ? value?.ToString() ?? string.Empty : string.Empty;

static bool FieldBool(IReadOnlyDictionary<string, object> field, string key) =>
    field.TryGetValue(key, out var value) && value is bool b && b;

static bool TryInt(IReadOnlyDictionary<string, object> field, string key, out int value)
{
    value = 0;
    return field.TryGetValue(key, out var raw) && raw is int i && (value = i) >= 0;
}

static bool RunSceneFieldDiagnostics(string[] args)
{
    Console.WriteLine("Scene field diagnostics");
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = appProfiles.ListProfileNames().FirstOrDefault();
    AppProfileLoadResult? profileLoad = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        profileLoad = appProfiles.LoadAll(profileName);

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    if (client is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var navigation = provider.GetRequiredService<ISceneStateService>().Recognize(window, config.NavigationRecognition);
    var death = provider.GetRequiredService<IDeathRecognitionService>().Recognize(window, config.DeathRecognition);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "scene-fields", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);

    var clientPath = Path.Combine(evidenceDir, "client.png");
    var mapPath = Path.Combine(evidenceDir, "map-region.png");
    var mapZoomPath = Path.Combine(evidenceDir, "map-region-x4.png");
    var coordPath = Path.Combine(evidenceDir, "coordinate-region.png");
    var coordZoomPath = Path.Combine(evidenceDir, "coordinate-region-x4.png");
    var deathPath = Path.Combine(evidenceDir, "death-region.png");
    var deathZoomPath = Path.Combine(evidenceDir, "death-region-x4.png");
    var evidencePath = Path.Combine(evidenceDir, $"scene-fields-{window.Pid}.json");

    var mapResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.MapName, client.Width, client.Height, rightAnchored: true);
    var coordResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.Coordinate, client.Width, client.Height, rightAnchored: true);
    var deathResolved = OcrRegionProjection.Resolve(config.DeathRecognition.PromptRegion, client.Width, client.Height);

    var mapCapture = CropCapture(client, mapResolved);
    var coordCapture = CropCapture(client, coordResolved);
    var deathCapture = CropCapture(client, deathResolved);
    var mapZoom = mapCapture is null ? null : ScaleCaptureNearest(mapCapture, 4);
    var coordZoom = coordCapture is null ? null : ScaleCaptureNearest(coordCapture, 4);
    var deathZoom = deathCapture is null ? null : ScaleCaptureNearest(deathCapture, 4);

    var savedClient = SaveCapturePng(client, clientPath);
    var savedMap = SaveCapturePng(mapCapture, mapPath);
    var savedMapZoom = SaveCapturePng(mapZoom, mapZoomPath);
    var savedCoord = SaveCapturePng(coordCapture, coordPath);
    var savedCoordZoom = SaveCapturePng(coordZoom, coordZoomPath);
    var savedDeath = SaveCapturePng(deathCapture, deathPath);
    var savedDeathZoom = SaveCapturePng(deathZoom, deathZoomPath);

    var mapVisual = HasVisualContent(mapCapture);
    var coordVisual = HasVisualContent(coordCapture);
    var sceneUsable = HasReliableRuntimeMap(navigation) && navigation.HasCoordinate;
    var reason = BuildSceneFieldReason(navigation, mapVisual, coordVisual);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-scene-fields-no-input-no-click-no-memory-state-read",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            diagnosticBusinessDecisionReady = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = profileLoad?.GlobalLoaded ?? false,
            loadedModules = profileLoad?.LoadedModules ?? Array.Empty<string>(),
            missingModules = profileLoad?.MissingModules ?? Array.Empty<string>(),
            confirmedMapName = config.NavigationRecognition.ConfirmedMapName
        },
        recognition = new
        {
            navigation = new
            {
                navigation.MapNameText,
                navigation.MapNameSource,
                navigation.MapNameConfidencePercent,
                navigation.CoordinateText,
                navigation.CoordinateSource,
                navigation.CoordinateConfidencePercent,
                navigation.X,
                navigation.Y,
                navigation.HasMap,
                navigation.HasCoordinate
            },
            death = new
            {
                death.IsDead,
                death.Text,
                death.MatchedKeyword
            }
        },
        gate = new
        {
            sceneUsable,
            mapFieldReady = navigation.HasMap,
            coordinateFieldReady = navigation.HasCoordinate,
            returnPointFieldReady = sceneUsable,
            deathFieldReady = death.IsDead,
            automatedActionReady = false,
            reason,
            fallback = sceneUsable
                ? "字段可作为回点诊断候选，仍需业务配置和连续稳定性验证。"
                : "禁止触发自动回点；继续使用外部打怪或基础按键逻辑，等待进入游戏世界或重新校准区域。"
        },
        regions = new
        {
            client = new { path = clientPath, saved = savedClient, client.Width, client.Height, visual = HasVisualContent(client) },
            map = RegionEvidence(config.NavigationRecognition.MapName, mapResolved, mapPath, savedMap, mapCapture),
            mapZoom = new { path = mapZoomPath, saved = savedMapZoom, visual = HasVisualContent(mapZoom) },
            coordinate = RegionEvidence(config.NavigationRecognition.Coordinate, coordResolved, coordPath, savedCoord, coordCapture),
            coordinateZoom = new { path = coordZoomPath, saved = savedCoordZoom, visual = HasVisualContent(coordZoom) },
            death = RegionEvidence(config.DeathRecognition.PromptRegion, deathResolved, deathPath, savedDeath, deathCapture),
            deathZoom = new { path = deathZoomPath, saved = savedDeathZoom, visual = HasVisualContent(deathZoom) }
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Profile='{profileName}', loaded={profileLoad?.GlobalLoaded ?? false}, confirmedMap='{config.NavigationRecognition.ConfirmedMapName}', loadedModules={profileLoad?.LoadedModules.Count ?? 0}, missingModules={profileLoad?.MissingModules.Count ?? 0}");
    Console.WriteLine($"Scene usable={sceneUsable}, returnPointFieldReady={sceneUsable}, reason={reason}");
    Console.WriteLine($"Navigation map='{navigation.MapNameText}' source={navigation.MapNameSource} confidence={navigation.MapNameConfidencePercent}%, coord='{navigation.CoordinateText}' source={navigation.CoordinateSource} confidence={navigation.CoordinateConfidencePercent}%, parsed={navigation.X},{navigation.Y}");
    Console.WriteLine($"Death dead={death.IsDead}, keyword='{death.MatchedKeyword}', text='{death.Text}'");
    Console.WriteLine($"Crops client={savedClient}, map={savedMap}/{savedMapZoom}, coord={savedCoord}/{savedCoordZoom}, death={savedDeath}/{savedDeathZoom}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && savedClient
             && savedMap
             && savedMapZoom
             && savedCoord
             && savedCoordZoom
             && savedDeath
             && savedDeathZoom
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveNavigationStabilityDiagnostics(string[] args)
{
    Console.WriteLine("Live navigation stability diagnostics");

    var sampleCount = ReadClampedIntOption(args, "--samples", 8, 2, 60);
    var intervalMs = ReadClampedIntOption(args, "--interval-ms", 800, 100, 10000);
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var expectedMapName = ReadOption(args, "--expect-map");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var hwnd = ResolveGameWindowHandle(args, provider, out var selectionText);
    if (hwnd == nint.Zero)
        return false;
    Console.WriteLine(selectionText);
    var window = binding.BindByHandle(hwnd);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = appProfiles.ListProfileNames().FirstOrDefault();
    AppProfileLoadResult? profileLoad = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        profileLoad = appProfiles.LoadAll(profileName);

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var navigationRecognition = provider.GetRequiredService<INavigationRecognitionService>();
    var perception = provider.GetRequiredService<IPerceptionHub>();
    var global = provider.GetRequiredService<IGlobalConfigService>();
    var mapNamePolicy = provider.GetRequiredService<MapNamePolicyService>();
    var mapNameSamples = provider.GetRequiredService<IMapNameSampleRecognitionService>();
    var concreteMapNameSamples = mapNameSamples as MapNameSampleRecognitionService;
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-stability", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"navigation-stability-{window.Pid}.json");

    var sampleRows = new List<object>();
    var coordinates = new List<(int? X, int? Y, string Text, string Source)>();
    var mapPolicyRows = new List<MapNamePolicyPerception>();
    var savedFrames = 0;
    OcrResolvedRegion? lastMapResolved = null;
    OcrResolvedRegion? lastCoordResolved = null;

    for (var i = 1; i <= sampleCount; i++)
    {
        var client = capture.CaptureClient(window.Hwnd);
        if (client is null)
        {
            sampleRows.Add(new
            {
                index = i,
                capturedAt = DateTimeOffset.Now,
                captured = false,
                reason = "客户区截图失败"
            });
            Console.WriteLine($"{i:00}. capture failed");
        }
        else
        {
            var mapResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.MapName, client.Width, client.Height, rightAnchored: true);
            var coordResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.Coordinate, client.Width, client.Height, rightAnchored: true);
            lastMapResolved = mapResolved;
            lastCoordResolved = coordResolved;

            var mapCapture = CropCapture(client, mapResolved);
            var coordCapture = CropCapture(client, coordResolved);
            var mapZoom = mapCapture is null ? null : ScaleCaptureNearest(mapCapture, 4);
            var coordZoom = coordCapture is null ? null : ScaleCaptureNearest(coordCapture, 4);

            var samplePrefix = $"sample-{i:00}";
            var clientPath = Path.Combine(evidenceDir, $"{samplePrefix}-client.png");
            var mapPath = Path.Combine(evidenceDir, $"{samplePrefix}-map.png");
            var mapZoomPath = Path.Combine(evidenceDir, $"{samplePrefix}-map-x4.png");
            var coordPath = Path.Combine(evidenceDir, $"{samplePrefix}-coordinate.png");
            var coordZoomPath = Path.Combine(evidenceDir, $"{samplePrefix}-coordinate-x4.png");

            var savedClient = i == 1 && SaveCapturePng(client, clientPath);
            var savedMap = SaveCapturePng(mapCapture, mapPath);
            var savedMapZoom = SaveCapturePng(mapZoom, mapZoomPath);
            var savedCoord = SaveCapturePng(coordCapture, coordPath);
            var savedCoordZoom = SaveCapturePng(coordZoom, coordZoomPath);
            if (savedCoord)
                savedFrames++;

            // Use the same DI-registered V2 perception path as the product runtime.
            // The previous diagnostic constructed a legacy recognizer without a
            // PerceptionHub, so it always returned an empty map/coordinate result.
            var perceptionSnapshot = perception.Read(window, global.Current);
            var mapPolicy = perceptionSnapshot.Minimap.MapNamePolicy;
            var hubMapBox = perceptionSnapshot.Minimap.MapNameBox;
            var hubMapCapture = hubMapBox.IsEmpty
                ? null
                : CropCaptureRect(client, hubMapBox.X, hubMapBox.Y, hubMapBox.Width, hubMapBox.Height);
            var hubMapMatch = hubMapCapture is null ? null : mapNameSamples.Match(hubMapCapture);
            var hubMapPath = Path.Combine(evidenceDir, $"{samplePrefix}-hub-map.png");
            var savedHubMap = SaveCapturePng(hubMapCapture, hubMapPath);
            mapPolicyRows.Add(mapPolicy);
            var frozenNavigation = navigationRecognition.Recognize(window, config.NavigationRecognition);
            coordinates.Add((frozenNavigation.X, frozenNavigation.Y, frozenNavigation.CoordinateText, frozenNavigation.CoordinateSource));

            sampleRows.Add(new
            {
                index = i,
                capturedAt = DateTimeOffset.Now,
                captured = true,
                client = new { client.Width, client.Height, path = i == 1 ? clientPath : null, saved = savedClient },
                navigation = new
                {
                    frozenNavigation.MapNameText,
                    frozenNavigation.MapNameSource,
                    frozenNavigation.MapNameConfidencePercent,
                    frozenNavigation.CoordinateText,
                    frozenNavigation.CoordinateSource,
                    frozenNavigation.CoordinateConfidencePercent,
                    frozenNavigation.X,
                    frozenNavigation.Y,
                    frozenNavigation.HasMap,
                    frozenNavigation.HasCoordinate,
                    policy = mapPolicy,
                    hubSampleMatch = new
                    {
                        matcherInjected = concreteMapNameSamples is not null,
                        sampleRoot = concreteMapNameSamples?.SampleRoot ?? "",
                        sampleCount = concreteMapNameSamples?.SampleCount ?? 0,
                        box = hubMapBox,
                        cropWidth = hubMapCapture?.Width ?? 0,
                        cropHeight = hubMapCapture?.Height ?? 0,
                        cropPath = hubMapPath,
                        cropSaved = savedHubMap,
                        sampleId = hubMapMatch?.SampleId ?? "",
                        mapName = hubMapMatch?.MapName ?? "",
                        score = hubMapMatch?.Score ?? 0,
                        isConfident = hubMapMatch?.IsConfident ?? false,
                        policyCandidate = hubMapMatch is null
                            ? null
                            : mapNamePolicy.Evaluate(hubMapMatch.MapName, hubMapMatch.Score, "sample_match", hubMapMatch.SampleId)
                    }
                },
                regions = new
                {
                    map = RegionEvidence(config.NavigationRecognition.MapName, mapResolved, mapPath, savedMap, mapCapture),
                    mapZoom = new { path = mapZoomPath, saved = savedMapZoom },
                    coordinate = RegionEvidence(config.NavigationRecognition.Coordinate, coordResolved, coordPath, savedCoord, coordCapture),
                    coordinateZoom = new { path = coordZoomPath, saved = savedCoordZoom }
                }
            });

            Console.WriteLine(
                $"{i:00}. map='{frozenNavigation.MapNameText}' [{frozenNavigation.MapNameSource} {frozenNavigation.MapNameConfidencePercent}%], " +
                $"candidate='{mapPolicy.NormalizedText}' -> '{mapPolicy.CanonicalCandidate}', stable='{mapPolicy.StableMapName}', " +
                $"votes={mapPolicy.Votes}/{mapPolicy.HistoryCount}, frame={mapPolicy.ObservationSequence}, " +
                $"hubBox={hubMapBox.X},{hubMapBox.Y},{hubMapBox.Width}x{hubMapBox.Height}, " +
                $"sample={hubMapMatch?.MapName ?? "-"}/{hubMapMatch?.Score.ToString("0.000") ?? "-"}/{hubMapMatch?.IsConfident.ToString() ?? "-"}, " +
                $"coord='{frozenNavigation.CoordinateText}' [{frozenNavigation.CoordinateSource} {frozenNavigation.CoordinateConfidencePercent}%], parsed={frozenNavigation.X},{frozenNavigation.Y}");
        }

        if (i < sampleCount)
            Thread.Sleep(intervalMs);
    }

    var valid = coordinates.Where(c => c.X is not null && c.Y is not null).ToArray();
    var distinctCoordinates = valid
        .Select(c => $"{c.X},{c.Y}")
        .Distinct(StringComparer.Ordinal)
        .ToArray();
    const int returnGateMaxCredibleStepDelta = 20;
    var stationary = valid.Length >= Math.Min(3, sampleCount)
                     && valid.Max(c => c.X!.Value) - valid.Min(c => c.X!.Value) <= 1
                     && valid.Max(c => c.Y!.Value) - valid.Min(c => c.Y!.Value) <= 1;
    var credibleForReturnGate = valid.Length >= Math.Min(3, sampleCount);
    for (var i = 1; i < valid.Length && credibleForReturnGate; i++)
    {
        credibleForReturnGate =
            Math.Abs(valid[i].X!.Value - valid[i - 1].X!.Value) <= returnGateMaxCredibleStepDelta
            && Math.Abs(valid[i].Y!.Value - valid[i - 1].Y!.Value) <= returnGateMaxCredibleStepDelta;
    }
    var allFromMiniMap = valid.Length > 0
                          && valid.All(c => c.Source.StartsWith("vision-v2/", StringComparison.OrdinalIgnoreCase));
    var stableMapPolicy = mapPolicyRows.LastOrDefault(item => item.Stable);
    var mapPolicyPass = mapNamePolicy.IsAvailable
                        && mapNamePolicy.AssetSha256.Equals(MapNamePolicyService.ExpectedSha256, StringComparison.OrdinalIgnoreCase)
                        && stableMapPolicy is not null
                        && (string.IsNullOrWhiteSpace(expectedMapName)
                            || string.Equals(stableMapPolicy.StableMapName, expectedMapName.Trim(), StringComparison.Ordinal));

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-live-navigation-stability-no-input-no-click",
        safety = new
        {
            sendsInputToGame = false,
            clicksGame = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            readsGameStateMemory = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = profileLoad is not null,
            loadedModules = profileLoad?.LoadedModules,
            missingModules = profileLoad?.MissingModules
        },
        runtimeData = new
        {
            navigationPipeline = "DI/INavigationRecognitionService/PerceptionHub/VisionV2",
            legacyTemplateOcrRequired = false,
            mapNamePolicy = new
            {
                mapNamePolicy.AssetPath,
                mapNamePolicy.AssetVersion,
                mapNamePolicy.AssetSha256,
                mapNamePolicy.RuntimeAuthorized,
                mapNamePolicy.LoadMessage,
                expectedMapName,
                mapPolicyPass
            }
        },
        config = new
        {
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            config.NavigationRecognition.ConfirmedMapNameAutoFilled,
            mapRegion = config.NavigationRecognition.MapName,
            coordinateRegion = config.NavigationRecognition.Coordinate,
            resolved = new
            {
                map = lastMapResolved,
                coordinate = lastCoordResolved
            }
        },
        stability = new
        {
            sampleCount,
            intervalMs,
            validCount = valid.Length,
            savedFrames,
            distinctCoordinates,
            stationary,
            credibleForReturnGate,
            returnGateMaxCredibleStepDelta,
            allFromMiniMap,
            mapPolicyPass,
            stableMapName = stableMapPolicy?.StableMapName ?? "",
            stableMapVotes = stableMapPolicy?.Votes ?? 0,
            reason = credibleForReturnGate
                ? "连续样本坐标未出现大跳变，可作为回点可信输入。"
                : "连续样本坐标跳变；回点安全门应继续阻止自动回点。"
        },
        samples = sampleRows
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}, loadedModules={profileLoad?.LoadedModules.Count ?? 0}, missing={profileLoad?.MissingModules.Count ?? 0}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Samples={sampleCount}, interval={intervalMs}ms, valid={valid.Length}, savedFrames={savedFrames}");
    Console.WriteLine($"Distinct={string.Join(" | ", distinctCoordinates.DefaultIfEmpty("-"))}");
    Console.WriteLine($"Stationary={stationary}, credibleForReturnGate={credibleForReturnGate}, allFromMiniMap={allFromMiniMap}");
    Console.WriteLine($"MapPolicy={mapPolicyPass}, stable='{stableMapPolicy?.StableMapName ?? "-"}', votes={stableMapPolicy?.Votes ?? 0}/{stableMapPolicy?.HistoryCount ?? 0}, runtimeAuthorized={mapNamePolicy.RuntimeAuthorized}, sha256={mapNamePolicy.AssetSha256}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && savedFrames > 0
             && valid.Length >= Math.Min(3, sampleCount)
             && credibleForReturnGate
             && allFromMiniMap
             && mapPolicyPass;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static async Task<bool> RunLivePanelEntryCollectionDiagnostics(string[] args)
{
    Console.WriteLine("Live panel-entry collection diagnostics");

    var slotName = (ReadOption(args, "--slot") ?? "quest").Trim().ToLowerInvariant();
    var slotIndex = slotName switch
    {
        "character" => 0,
        "skill" => 1,
        "pet" => 2,
        "quest" => 3,
        "trade" => 4,
        _ => -1
    };
    if (slotIndex < 0)
    {
        Console.Error.WriteLine("FAIL: --slot 仅支持 character|skill|pet|quest|trade。");
        return false;
    }

    var executeRequested = args.Any(item => item.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var closeAfter = args.Any(item => item.Equals("--close-after", StringComparison.OrdinalIgnoreCase));
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var sampleCount = ReadClampedIntOption(args, "--samples", 3, 2, 12);
    var intervalMs = ReadClampedIntOption(args, "--interval-ms", 350, 150, 3000);
    var artifactDir = ReadOption(args, "--artifact")
        ?? Path.Combine((Environment.GetEnvironmentVariable("TLBB_VISION_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "vision-workspace")), "train", "artifacts", "panel_entry_strip_template_v1_candidate");
    var outputRoot = ReadOption(args, "--output")
        ?? Path.Combine(Environment.CurrentDirectory, "artifacts", "visual-collection", "20260715-map-panel-entries");
    var manifestPath = Path.Combine(artifactDir, "manifest.json");
    var templatePath = Path.Combine(artifactDir, "border_consensus_template.png");
    var maskPath = Path.Combine(artifactDir, "border_mask.png");

    var artifactErrors = new List<string>();
    if (!File.Exists(manifestPath)) artifactErrors.Add($"manifest 不存在：{manifestPath}");
    if (!File.Exists(templatePath)) artifactErrors.Add($"template 不存在：{templatePath}");
    if (!File.Exists(maskPath)) artifactErrors.Add($"mask 不存在：{maskPath}");
    if (artifactErrors.Count > 0)
    {
        foreach (var error in artifactErrors)
            Console.Error.WriteLine($"FAIL: {error}");
        return false;
    }

    var threshold = 0.869772d;
    try
    {
        using var document = JsonDocument.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
        if (document.RootElement.TryGetProperty("threshold", out var thresholdElement))
            threshold = thresholdElement.GetDouble();
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"FAIL: 入口条 manifest 解析失败：{ex.Message}");
        return false;
    }

    var template = LoadCapturePng(templatePath);
    var mask = LoadCapturePng(maskPath);
    if (template is null || mask is null || template.Width != 175 || template.Height != 48
        || mask.Width != template.Width || mask.Height != template.Height)
    {
        Console.Error.WriteLine("FAIL: 入口条模板/掩码尺寸不符合 175x48 契约。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var hwnd = ResolveGameWindowHandle(args, provider, out var selectionText);
    if (hwnd == nint.Zero)
        return false;
    Console.WriteLine(selectionText);
    var window = binding.BindByHandle(hwnd);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var detector = provider.GetRequiredService<IInteractionWindowDetectService>();
    var input = provider.GetRequiredService<IInputService>();
    input.DefaultDispatchMode = dispatch;
    input.YieldToUserInput = false;
    var auditedInput = new AuditedInputService(input);
    var log = provider.GetRequiredService<ILogService>();
    var confirmation = new VisualActionConfirmationService(
        new VisionActionExecutor(auditedInput, log),
        provider.GetRequiredService<IPerceptionHub>(),
        log,
        provider.GetRequiredService<IBackgroundInputCapabilityService>());
    var actionConfig = new GlobalConfig
    {
        InputDispatchMode = dispatch,
        YieldToManualInput = false
    };
    var temporalGate = new QuestLogPanelTemporalGate();

    var before = capture.CaptureClient(window.Hwnd);
    if (before is null || before.Width < 800 || before.Height < 600)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败或尺寸小于候选入口条契约。");
        return false;
    }

    var stripX = before.Width / 2 - 400;
    var stripY = before.Height - 48;
    var strip = CropCaptureRect(before, stripX, stripY, 175, 48);
    if (strip is null)
    {
        Console.Error.WriteLine("FAIL: 入口条 ROI 越界。");
        return false;
    }

    static double MaskedScore(CaptureResult reference, CaptureResult candidate, CaptureResult scoreMask)
    {
        if (reference.Width != candidate.Width || reference.Height != candidate.Height
            || scoreMask.Width != reference.Width || scoreMask.Height != reference.Height)
            return 0;
        double delta = 0;
        var selected = 0;
        var pixelCount = reference.Width * reference.Height;
        for (var i = 0; i < pixelCount; i++)
        {
            var offset = i * 4;
            if (scoreMask.Pixels[offset] == 0)
                continue;
            delta += (Math.Abs(reference.Pixels[offset] - candidate.Pixels[offset])
                      + Math.Abs(reference.Pixels[offset + 1] - candidate.Pixels[offset + 1])
                      + Math.Abs(reference.Pixels[offset + 2] - candidate.Pixels[offset + 2])) / 3d;
            selected++;
        }
        return selected == 0 ? 0 : Math.Clamp(1d - delta / selected / 255d, 0d, 1d);
    }

    static double ChangedPixelRatio(CaptureResult left, CaptureResult right)
    {
        if (left.Width != right.Width || left.Height != right.Height)
            return 1;
        var changed = 0;
        var sampled = 0;
        var pixels = left.Width * left.Height;
        for (var i = 0; i < pixels; i += 4)
        {
            var offset = i * 4;
            var delta = Math.Abs(left.Pixels[offset] - right.Pixels[offset])
                        + Math.Abs(left.Pixels[offset + 1] - right.Pixels[offset + 1])
                        + Math.Abs(left.Pixels[offset + 2] - right.Pixels[offset + 2]);
            if (delta >= 48)
                changed++;
            sampled++;
        }
        return sampled == 0 ? 0 : changed / (double)sampled;
    }

    var score = MaskedScore(template, strip, mask);
    var stripVisible = score >= threshold;
    var slotX = stripX + slotIndex * 35;
    var clickX = slotX + 17;
    var clickY = stripY + 24;
    var timestamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceDir = Path.Combine(outputRoot, $"{timestamp}-{slotName}");
    Directory.CreateDirectory(evidenceDir);
    var beforeClientPath = Path.Combine(evidenceDir, "before-client.png");
    var beforeStripPath = Path.Combine(evidenceDir, "before-strip.png");
    var beforeOverlayPath = Path.Combine(evidenceDir, "before-overlay.png");
    var beforeInteractionOverlayPath = Path.Combine(evidenceDir, "before-interaction-overlay.png");
    var beforeSaved = SaveCapturePng(before, beforeClientPath);
    var stripSaved = SaveCapturePng(strip, beforeStripPath);
    var overlaySaved = SavePanelEntryOverlayPng(before, stripX, stripY, slotIndex, beforeOverlayPath);
    var beforePanelRaw = detector.Detect(before, includeQuestLogPanel: slotName == "quest");
    var beforeInteractionOverlaySaved = SaveInteractionWindowOverlayPng(
        before,
        beforePanelRaw.Detections,
        beforeInteractionOverlayPath);
    var beforeQuestPresent = slotName == "quest"
                             && beforePanelRaw.QuestLogPanelState == VisionTriState.Present;

    var gateReasons = new List<string>();
    if (!stripVisible)
        gateReasons.Add($"入口条模板分数 {score:0.000000} 低于阈值 {threshold:0.000000}。");
    if (beforeQuestPresent)
        gateReasons.Add("任务面板在点击前已出现；拒绝把关闭动作误当成打开动作。");
    if (!DiagnosticWindowNative.IsWindowVisible(window.Hwnd) || DiagnosticWindowNative.IsIconic(window.Hwnd))
        gateReasons.Add("目标游戏窗口不可见或已最小化。");
    if (dispatch != InputDispatchMode.PostMessage)
        gateReasons.Add("当前目标模式只允许 PostMessage 后台输入，拒绝 SendInput 抢占前台。");
    if (!executeRequested)
        gateReasons.Add("未提供 --execute，本次只记录定位计划。");

    var ownershipChecks = new List<object>();
    var actionMessages = new List<string>();
    var clickSent = false;
    var foregroundBeforeOpen = DiagnosticWindowNative.CurrentForegroundWindowHandle();
    var foregroundAfterOpen = foregroundBeforeOpen;
    var foregroundChangedDuringOpen = false;
    var foregroundRestoredAfterOpen = true;
    VisualActionConfirmationResult? openConfirmation = null;
    if (executeRequested && gateReasons.Count == 0)
    {
        var ownership = dispatch == InputDispatchMode.PostMessage
            ? DiagnosticWindowNative.VerifyBackgroundClientPointOwnership(
                window.Hwnd,
                clickX,
                clickY,
                (uint)window.Pid)
            : DiagnosticWindowNative.VerifyClientPointOwnership(
                window.Hwnd,
                clickX,
                clickY,
                (uint)window.Pid);
        ownershipChecks.Add(ownership);
        if (!ownership.OwnedByExpectedPid)
        {
            gateReasons.Add($"入口点击点 PID 归属失败：hitPid={ownership.HitPid}, expected={window.Pid}。");
        }
        else
        {
            if (slotName == "quest")
            {
                openConfirmation = await confirmation.ExecuteAsync(
                    window,
                    actionConfig,
                    new VisualActionConfirmationRequest(
                        new VisionActionDecision(
                            true,
                            VisionActionKind.Click,
                            clickX,
                            clickY,
                            $"panel-entry-open:{slotName}"),
                        "quest_log_panel_present",
                        snapshot => snapshot.InteractionWindows.QuestLogPanelState == VisionTriState.Present,
                        RequireStateTransition: true,
                        RequiredConsecutiveFrames: 2,
                        TimeoutMilliseconds: Math.Clamp(intervalMs * sampleCount + 1200, 1800, 8000),
                        PollMilliseconds: Math.Clamp(intervalMs / 2, 75, 250),
                        ReadOptions: PerceptionReadOptions.QuestLogPanelShadow));
                clickSent = openConfirmation.Receipt.Delivered;
                actionMessages.Add(
                    $"open {slotName}: click ({clickX},{clickY}) => delivered={clickSent}, " +
                    $"state={openConfirmation.State}, fresh={openConfirmation.FreshFramesObserved}, " +
                    $"confirmed={openConfirmation.ConsecutiveConfirmations}");
            }
            else
            {
                clickSent = auditedInput.Click(window.Hwnd, clickX, clickY, dispatch, InputMouseButton.Left);
                actionMessages.Add($"open {slotName}: click ({clickX},{clickY}) => {clickSent}");
            }
            if (!clickSent)
                gateReasons.Add($"{dispatch} 点击发送失败。");
        }
    }

    if (clickSent)
    {
        foregroundAfterOpen = DiagnosticWindowNative.CurrentForegroundWindowHandle();
        foregroundChangedDuringOpen = dispatch == InputDispatchMode.PostMessage
                                      && foregroundAfterOpen != foregroundBeforeOpen;
        if (foregroundChangedDuringOpen)
        {
            foregroundRestoredAfterOpen = DiagnosticWindowNative.TryRestoreForegroundWindow(foregroundBeforeOpen);
            gateReasons.Add(
                $"后台点击意外改变前台窗口：before=0x{foregroundBeforeOpen:X}, after=0x{foregroundAfterOpen:X}, " +
                $"restored={foregroundRestoredAfterOpen}；已停止该输入适配器。");
        }
    }

    var afterRows = new List<object>();
    var openStable = openConfirmation?.Confirmed == true;
    var openVisualChanged = false;
    CaptureResult? lastAfter = null;
    if (clickSent)
    {
        Thread.Sleep(intervalMs);
        for (var i = 1; i <= sampleCount; i++)
        {
            var frame = capture.CaptureClient(window.Hwnd);
            if (frame is null)
            {
                afterRows.Add(new { index = i, captured = false });
                continue;
            }

            lastAfter = frame;
            var raw = detector.Detect(frame, includeQuestLogPanel: slotName == "quest");
            var fused = slotName == "quest"
                ? temporalGate.Observe($"panel-entry-{window.Pid}-{slotName}", frame.Width, frame.Height, raw)
                : raw;
            var changedRatio = ChangedPixelRatio(before, frame);
            openVisualChanged |= changedRatio >= 0.02;
            openStable |= slotName == "quest" && fused.QuestLogPanelState == VisionTriState.Present;
            var framePath = Path.Combine(evidenceDir, $"opened-{i:00}-client.png");
            var overlayPath = Path.Combine(evidenceDir, $"opened-{i:00}-interaction-overlay.png");
            var frameSaved = SaveCapturePng(frame, framePath);
            var interactionOverlaySaved = SaveInteractionWindowOverlayPng(frame, fused.Detections, overlayPath);
            afterRows.Add(new
            {
                index = i,
                captured = true,
                frame.Sequence,
                frame.CapturedAt,
                path = framePath,
                frameSaved,
                overlayPath,
                interactionOverlaySaved,
                changedRatio,
                raw.Available,
                raw.ModelVersion,
                raw.Message,
                rawQuestState = raw.QuestLogPanelState.ToString(),
                fusedQuestState = fused.QuestLogPanelState.ToString(),
                detections = fused.Detections.Select(item => new
                {
                    item.ClassName,
                    item.Box,
                    item.Confidence
                }).ToArray()
            });
            if (i < sampleCount)
                Thread.Sleep(intervalMs);
        }
    }

    if (clickSent && slotName != "quest")
    {
        gateReasons.Add(
            $"{slotName} 尚无专用面板 L1；全屏像素变化只能作为采集证据，不能证明面板已打开，" +
            "本次状态记为 panel_unconfirmed 且不发送关闭点击。");
    }
    else if (clickSent && !openStable)
    {
        gateReasons.Add(
            $"任务面板后台点击已投递，但未在连续两张新帧中确认打开：" +
            $"{openConfirmation?.State.ToString() ?? "no_confirmation_result"}。");
    }

    var canClose = clickSent
                   && !foregroundChangedDuringOpen
                   && closeAfter
                   && slotName == "quest"
                   && openStable;
    var closeSent = false;
    object? closeOwnership = null;
    CaptureResult? closedFrame = null;
    InteractionWindowPerception? closedPerception = null;
    var foregroundBeforeClose = DiagnosticWindowNative.CurrentForegroundWindowHandle();
    var foregroundAfterClose = foregroundBeforeClose;
    var foregroundChangedDuringClose = false;
    var foregroundRestoredAfterClose = true;
    VisualActionConfirmationResult? closeConfirmation = null;
    if (canClose)
    {
        var ownership = dispatch == InputDispatchMode.PostMessage
            ? DiagnosticWindowNative.VerifyBackgroundClientPointOwnership(
                window.Hwnd,
                clickX,
                clickY,
                (uint)window.Pid)
            : DiagnosticWindowNative.VerifyClientPointOwnership(
                window.Hwnd,
                clickX,
                clickY,
                (uint)window.Pid);
        closeOwnership = ownership;
        ownershipChecks.Add(ownership);
        if (ownership.OwnedByExpectedPid)
        {
            closeConfirmation = await confirmation.ExecuteAsync(
                window,
                actionConfig,
                new VisualActionConfirmationRequest(
                    new VisionActionDecision(
                        true,
                        VisionActionKind.Click,
                        clickX,
                        clickY,
                        $"panel-entry-close:{slotName}"),
                    "quest_log_panel_absent",
                    snapshot => snapshot.InteractionWindows.QuestLogPanelState == VisionTriState.Absent,
                    RequireStateTransition: true,
                    RequiredConsecutiveFrames: 2,
                    TimeoutMilliseconds: Math.Clamp(intervalMs * sampleCount + 1200, 1800, 8000),
                    PollMilliseconds: Math.Clamp(intervalMs / 2, 75, 250),
                    ReadOptions: PerceptionReadOptions.QuestLogPanelShadow));
            closeSent = closeConfirmation.Receipt.Delivered;
            actionMessages.Add(
                $"close {slotName}: click ({clickX},{clickY}) => delivered={closeSent}, " +
                $"state={closeConfirmation.State}, fresh={closeConfirmation.FreshFramesObserved}, " +
                $"confirmed={closeConfirmation.ConsecutiveConfirmations}");
            foregroundAfterClose = DiagnosticWindowNative.CurrentForegroundWindowHandle();
            foregroundChangedDuringClose = dispatch == InputDispatchMode.PostMessage
                                           && foregroundAfterClose != foregroundBeforeClose;
            if (foregroundChangedDuringClose)
            {
                foregroundRestoredAfterClose = DiagnosticWindowNative.TryRestoreForegroundWindow(foregroundBeforeClose);
                actionMessages.Add(
                    $"close stopped: foreground changed from 0x{foregroundBeforeClose:X} " +
                    $"to 0x{foregroundAfterClose:X}, restored={foregroundRestoredAfterClose}");
            }
            Thread.Sleep(Math.Max(150, Math.Min(intervalMs, 450)));
            closedFrame = capture.CaptureClient(window.Hwnd);
            if (closedFrame is not null)
            {
                var raw = detector.Detect(closedFrame, includeQuestLogPanel: slotName == "quest");
                closedPerception = slotName == "quest"
                    ? temporalGate.Observe($"panel-entry-{window.Pid}-{slotName}", closedFrame.Width, closedFrame.Height, raw)
                    : raw;
                SaveCapturePng(closedFrame, Path.Combine(evidenceDir, "closed-client.png"));
                SaveInteractionWindowOverlayPng(
                    closedFrame,
                    closedPerception.Detections,
                    Path.Combine(evidenceDir, "closed-interaction-overlay.png"));
            }
        }
        else
        {
            actionMessages.Add("close skipped: PID ownership verification failed");
        }
    }

    var inputAudit = BuildInputAudit(auditedInput);
    var confirmationState = !executeRequested
        ? "dry_run"
        : !clickSent
            ? "blocked_or_click_failed"
            : slotName == "quest"
                ? openStable ? "l1_two_fresh_frame_confirmed" : $"quest_{openConfirmation?.State.ToString() ?? "not_confirmed"}"
                : "panel_l1_not_available_unconfirmed";
    var closedConfirmed = closeConfirmation?.Confirmed == true;

    static string FileSha256(string path) => File.Exists(path)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))
        : string.Empty;

    var runManifestPath = Path.Combine(evidenceDir, "manifest.json");
    var jsonOptions = new JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var runManifest = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "panel-entry-controlled-collection",
        safety = new
        {
            executeRequested,
            sendsInput = clickSent || closeSent,
            dispatch = dispatch.ToString(),
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            runtimeAuthorized = false,
            scope = "single verified panel-entry click plus optional same-slot close"
        },
        window = new
        {
            window.Pid,
            hwnd = $"0x{window.Hwnd:X}",
            window.Title,
            window.ClientWidth,
            window.ClientHeight,
            window.Bitness,
            window.ProcessPath
        },
        artifact = new
        {
            artifactDir,
            manifestPath,
            manifestSha256 = FileSha256(manifestPath),
            templatePath,
            templateSha256 = FileSha256(templatePath),
            maskPath,
            maskSha256 = FileSha256(maskPath),
            threshold,
            runtimeAuthorized = false
        },
        detection = new
        {
            stripBbox = new[] { stripX, stripY, stripX + 175, stripY + 48 },
            slotBboxes = Enumerable.Range(0, 5)
                .Select(index => new[] { stripX + index * 35, stripY, stripX + (index + 1) * 35, stripY + 48 })
                .ToArray(),
            score,
            visible = stripVisible,
            selectedSlot = slotName,
            selectedSlotIndex = slotIndex,
            click = new { x = clickX, y = clickY },
            beforeQuestState = beforePanelRaw.QuestLogPanelState.ToString(),
            beforePanelRaw.Available,
            beforePanelRaw.ModelVersion,
            beforePanelRaw.Message,
            beforePanelRaw.InferenceMilliseconds,
            beforeDetections = beforePanelRaw.Detections.Select(item => new
            {
                item.ClassName,
                item.Box,
                item.Confidence
            }).ToArray()
        },
        evidence = new
        {
            beforeClientPath,
            beforeClientSha256 = FileSha256(beforeClientPath),
            beforeStripPath,
            beforeStripSha256 = FileSha256(beforeStripPath),
            beforeOverlayPath,
            beforeOverlaySha256 = FileSha256(beforeOverlayPath),
            beforeSaved,
            stripSaved,
            overlaySaved,
            beforeInteractionOverlayPath,
            beforeInteractionOverlaySha256 = FileSha256(beforeInteractionOverlayPath),
            beforeInteractionOverlaySaved,
            afterRows,
            closedClientPath = closedFrame is null ? null : Path.Combine(evidenceDir, "closed-client.png")
        },
        action = new
        {
            gateReasons,
            ownershipChecks,
            closeOwnership,
            actionMessages,
            clickSent,
            closeAfter,
            canClose,
            closeSent,
            foreground = new
            {
                beforeOpen = $"0x{foregroundBeforeOpen:X}",
                afterOpen = $"0x{foregroundAfterOpen:X}",
                changedDuringOpen = foregroundChangedDuringOpen,
                restoredAfterOpen = foregroundRestoredAfterOpen,
                beforeClose = $"0x{foregroundBeforeClose:X}",
                afterClose = $"0x{foregroundAfterClose:X}",
                changedDuringClose = foregroundChangedDuringClose,
                restoredAfterClose = foregroundRestoredAfterClose
            },
            openConfirmation = openConfirmation is null ? null : new
            {
                state = openConfirmation.State.ToString(),
                openConfirmation.Reason,
                openConfirmation.BaselineFrameSequence,
                openConfirmation.LastFrameSequence,
                openConfirmation.FreshFramesObserved,
                openConfirmation.ConsecutiveConfirmations,
                foregroundBefore = $"0x{openConfirmation.ForegroundBefore:X}",
                foregroundAfter = $"0x{openConfirmation.ForegroundAfter:X}"
            },
            closeConfirmation = closeConfirmation is null ? null : new
            {
                state = closeConfirmation.State.ToString(),
                closeConfirmation.Reason,
                closeConfirmation.BaselineFrameSequence,
                closeConfirmation.LastFrameSequence,
                closeConfirmation.FreshFramesObserved,
                closeConfirmation.ConsecutiveConfirmations,
                foregroundBefore = $"0x{closeConfirmation.ForegroundBefore:X}",
                foregroundAfter = $"0x{closeConfirmation.ForegroundAfter:X}"
            },
            closedConfirmed,
            confirmationState,
            openStable,
            openVisualChanged,
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.Clicks
        }
    };
    File.WriteAllText(runManifestPath, JsonSerializer.Serialize(runManifest, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"PID={window.Pid}, size={window.ClientSizeText}, slot={slotName}");
    Console.WriteLine($"Strip={stripX},{stripY},175x48 score={score:0.000000} threshold={threshold:0.000000} visible={stripVisible}");
    Console.WriteLine($"Click={clickX},{clickY}, execute={executeRequested}, sent={clickSent}, confirmation={confirmationState}");
    Console.WriteLine($"Close requested={closeAfter}, sent={closeSent}, confirmed={closedConfirmed}");
    foreach (var reason in gateReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Evidence={runManifestPath}");

    var ok = beforeSaved && stripSaved && overlaySaved && stripVisible && File.Exists(runManifestPath)
             && (!executeRequested || (clickSent
                                         && !foregroundChangedDuringOpen
                                         && !foregroundChangedDuringClose
                                         && openStable))
             && (!closeAfter || !clickSent || !canClose || closedConfirmed);
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveVerifiedClickDiagnostics(string[] args)
{
    Console.WriteLine("Live verified single-click diagnostics");

    var requestedPid = ReadIntOption(args, "--pid", 0);
    var point = ReadOffsetOption(args, "--point", (-1, -1));
    var label = (ReadOption(args, "--label") ?? "verified-click").Trim();
    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.SendInput);
    var backgroundStrategy = (ReadOption(args, "--background-strategy") ?? "input-service")
        .Trim()
        .ToLowerInvariant();
    var holdMs = Math.Clamp(ReadIntOption(args, "--hold-ms", 180), 80, 1000);
    var waitMs = Math.Clamp(ReadIntOption(args, "--wait-ms", 900), 250, 5000);

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .Where(p => requestedPid <= 0 || p.Id == requestedPid)
        .OrderByDescending(p => p.Id == requestedPid)
        .ThenBy(p => p.Id)
        .FirstOrDefault();
    if (game is null)
    {
        Console.Error.WriteLine(requestedPid > 0
            ? $"FAIL: 未找到 PID={requestedPid} 的 Game.exe 主窗口。"
            : "FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();
    var binding = provider.GetRequiredService<IWindowBindingService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var perception = provider.GetRequiredService<IPerceptionHub>();
    var global = provider.GetRequiredService<IGlobalConfigService>();
    var realInput = provider.GetRequiredService<IInputService>();
    var auditedInput = new AuditedInputService(realInput);

    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    RuntimePerceptionSnapshot? ReadSnapshot()
    {
        try
        {
            return perception.Read(window, global.Current);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Snapshot warning: {ex.Message}");
            return null;
        }
    }

    static object Summarize(RuntimePerceptionSnapshot? snapshot) => new
    {
        available = snapshot is not null,
        frameSequence = snapshot?.FrameSequence,
        capturedAt = snapshot?.CapturedAt,
        playerHpPercent = snapshot?.SelfBars.PlayerHpPercent,
        playerMpPercent = snapshot?.SelfBars.PlayerMpPercent,
        petHpPercent = snapshot?.SelfBars.PetHpPercent,
        petState = snapshot?.SelfBars.PetState.ToString(),
        targetPresence = snapshot?.Target.Presence.ToString(),
        targetName = snapshot?.Target.NameText,
        targetHpPercent = snapshot?.Target.HpPercent,
        mapName = snapshot?.Minimap.MapNamePolicy.StableMapName,
        mapSource = snapshot?.Minimap.MapNamePolicy.CandidateSource,
        coordinateX = snapshot?.Minimap.X,
        coordinateY = snapshot?.Minimap.Y
    };

    static double ChangedPixelRatio(CaptureResult? left, CaptureResult? right)
    {
        if (left is null || right is null || left.Width != right.Width || left.Height != right.Height)
            return 0;

        var changed = 0;
        var sampled = 0;
        var pixels = left.Width * left.Height;
        for (var i = 0; i < pixels; i += 4)
        {
            var offset = i * 4;
            var delta = Math.Abs(left.Pixels[offset] - right.Pixels[offset])
                        + Math.Abs(left.Pixels[offset + 1] - right.Pixels[offset + 1])
                        + Math.Abs(left.Pixels[offset + 2] - right.Pixels[offset + 2]);
            if (delta >= 48)
                changed++;
            sampled++;
        }

        return sampled == 0 ? 0 : changed / (double)sampled;
    }

    var before = capture.CaptureClient(window.Hwnd);
    var beforeSnapshot = ReadSnapshot();
    var gateReasons = new List<string>();
    if (before is null)
        gateReasons.Add("点击前客户区截图失败。");
    if (point.X < 0 || point.Y < 0 || point.X >= window.ClientWidth || point.Y >= window.ClientHeight)
        gateReasons.Add($"客户区坐标越界：({point.X},{point.Y}) / {window.ClientWidth}x{window.ClientHeight}。");
    if (!DiagnosticWindowNative.IsWindowVisible(window.Hwnd) || DiagnosticWindowNative.IsIconic(window.Hwnd))
        gateReasons.Add("目标游戏窗口不可见或已最小化。");
    if (!executeRequested)
        gateReasons.Add("未提供 --execute，本次仅生成单点计划和点击前证据。");

    DiagnosticPointOwnership? ownership = null;
    var clickSent = false;
    var foregroundBefore = DiagnosticWindowNative.CurrentForegroundWindowHandle();
    var foregroundAfter = foregroundBefore;
    var foregroundChanged = false;
    var foregroundRestored = true;
    CaptureResult? pressed = null;
    string nativeDispatchDetail = "";
    if (executeRequested && gateReasons.Count == 0)
    {
        ownership = dispatch == InputDispatchMode.PostMessage
            ? DiagnosticWindowNative.VerifyBackgroundClientPointOwnership(
                window.Hwnd,
                point.X,
                point.Y,
                (uint)window.Pid)
            : DiagnosticWindowNative.VerifyClientPointOwnership(
                window.Hwnd,
                point.X,
                point.Y,
                (uint)window.Pid);
        if (!ownership.OwnedByExpectedPid)
        {
            gateReasons.Add($"点击点 PID 归属失败：hitPid={ownership.HitPid}, expected={window.Pid}。");
        }
        else
        {
            if (dispatch == InputDispatchMode.SendInput)
                _ = DiagnosticWindowNative.ActivateWindowForDiagnostic(window.Hwnd);
            clickSent = dispatch == InputDispatchMode.PostMessage && backgroundStrategy != "input-service"
                ? DiagnosticBackgroundMouseProbe.TryClick(
                    window.Hwnd,
                    point.X,
                    point.Y,
                    backgroundStrategy,
                    holdMs,
                    () => capture.CaptureClient(window.Hwnd),
                    out pressed,
                    out nativeDispatchDetail)
                : auditedInput.Click(window.Hwnd, point.X, point.Y, dispatch, InputMouseButton.Left);
            if (!clickSent)
                gateReasons.Add(string.IsNullOrWhiteSpace(nativeDispatchDetail)
                    ? "单次点击发送失败。"
                    : $"后台点击发送失败：{nativeDispatchDetail}");
            else
            {
                foregroundAfter = DiagnosticWindowNative.CurrentForegroundWindowHandle();
                foregroundChanged = dispatch == InputDispatchMode.PostMessage
                                    && foregroundAfter != foregroundBefore;
                if (foregroundChanged)
                {
                    foregroundRestored = DiagnosticWindowNative.TryRestoreForegroundWindow(foregroundBefore);
                    gateReasons.Add(
                        $"后台点击意外改变前台窗口：before=0x{foregroundBefore:X}, after=0x{foregroundAfter:X}, " +
                        $"restored={foregroundRestored}；已停止该输入适配器。");
                }
            }
        }
    }

    if (clickSent)
        Thread.Sleep(waitMs);
    var after = clickSent ? capture.CaptureClient(window.Hwnd) : null;
    var afterSnapshot = clickSent ? ReadSnapshot() : null;
    var changedPixelRatio = ChangedPixelRatio(before, after);
    var pressedChangedPixelRatio = ChangedPixelRatio(before, pressed);
    var visualResponseObserved = Math.Max(changedPixelRatio, pressedChangedPixelRatio) >= 0.001;
    if (clickSent && after is not null && !visualResponseObserved)
    {
        gateReasons.Add(
            "点击消息已投递，但前后客户区画面无可观察变化；不能据此证明客户端执行了点击。" +
            "需要调用方用面板 L1、按钮状态或业务结果继续确认。");
    }

    var safeLabel = new string(label.Select(c => char.IsLetterOrDigit(c) || c is '-' or '_' ? c : '-').ToArray()).Trim('-');
    if (string.IsNullOrWhiteSpace(safeLabel))
        safeLabel = "verified-click";
    var evidenceDir = Path.Combine(
        Environment.CurrentDirectory,
        "artifacts",
        "live-verified-click",
        $"{DateTime.Now:yyyyMMdd-HHmmss}-{safeLabel}");
    Directory.CreateDirectory(evidenceDir);
    var beforePath = Path.Combine(evidenceDir, "before-client.png");
    var pressedPath = Path.Combine(evidenceDir, "pressed-client.png");
    var afterPath = Path.Combine(evidenceDir, "after-client.png");
    var manifestPath = Path.Combine(evidenceDir, "manifest.json");
    var beforeSaved = SaveCapturePng(before, beforePath);
    var pressedSaved = pressed is not null && SaveCapturePng(pressed, pressedPath);
    var afterSaved = after is not null && SaveCapturePng(after, afterPath);
    var inputAudit = BuildInputAudit(auditedInput);

    static string Sha256File(string path) => File.Exists(path)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))
        : string.Empty;

    var manifest = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-verified-single-click",
        label,
        safety = new
        {
            executeRequested,
            clickSent,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            scope = "one verified client-coordinate left click"
        },
        window = new
        {
            window.Pid,
            hwnd = $"0x{window.Hwnd:X}",
            window.Title,
            window.ClientWidth,
            window.ClientHeight,
            window.ProcessPath
        },
        action = new
        {
            point = new { point.X, point.Y },
            dispatch = dispatch.ToString(),
            backgroundStrategy,
            holdMs,
            nativeDispatchDetail,
            waitMs,
            ownership,
            gateReasons,
            foreground = new
            {
                before = $"0x{foregroundBefore:X}",
                after = $"0x{foregroundAfter:X}",
                changed = foregroundChanged,
                restored = foregroundRestored
            },
            visualConfirmation = new
            {
                changedPixelRatio,
                pressedChangedPixelRatio,
                observed = visualResponseObserved,
                semanticConfirmed = false,
                state = visualResponseObserved
                    ? "visual_change_observed_semantics_unconfirmed"
                    : "message_delivered_no_visual_response"
            },
            inputAudit.ClickCount,
            inputAudit.Clicks
        },
        before = new
        {
            path = beforePath,
            saved = beforeSaved,
            sha256 = Sha256File(beforePath),
            snapshot = Summarize(beforeSnapshot)
        },
        pressed = new
        {
            path = pressed is null ? null : pressedPath,
            saved = pressedSaved,
            sha256 = pressed is null ? "" : Sha256File(pressedPath)
        },
        after = new
        {
            path = after is null ? null : afterPath,
            saved = afterSaved,
            sha256 = after is null ? "" : Sha256File(afterPath),
            snapshot = Summarize(afterSnapshot)
        }
    };
    var jsonOptions = new JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(manifestPath, JsonSerializer.Serialize(manifest, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"PID={window.Pid}, hwnd=0x{window.Hwnd:X}, size={window.ClientSizeText}");
    Console.WriteLine($"Point={point.X},{point.Y}, label={label}, execute={executeRequested}, sent={clickSent}, dispatch={dispatch}, strategy={backgroundStrategy}");
    Console.WriteLine($"Visual response={visualResponseObserved}, pressed change={pressedChangedPixelRatio:P4}, after change={changedPixelRatio:P4}; semantic confirmation is caller-specific.");
    foreach (var reason in gateReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Evidence={manifestPath}");

    var evidenceSaved = beforeSaved
                        && File.Exists(manifestPath)
                        && (!executeRequested || (clickSent && !foregroundChanged && afterSaved));
    if (!evidenceSaved)
    {
        Console.WriteLine("FAIL");
        return false;
    }

    if (executeRequested)
    {
        Console.WriteLine("UNCONFIRMED: native delivery and pixel changes are not business-state confirmation.");
        return false;
    }

    Console.WriteLine("PASS_DRY_RUN");
    return true;
}

static bool RunLiveReturnPointEvidenceDiagnostics(string[] args)
{
    Console.WriteLine("Live return-point evidence diagnostics");
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = appProfiles.ListProfileNames().FirstOrDefault();
    AppProfileLoadResult? profileLoad = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        profileLoad = appProfiles.LoadAll(profileName);

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    if (client is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var fallbackRoute = FindImportedHorseRouteFile();
    ReturnPointImportResult? importedFallback = null;
    if (config.Points.Count == 0 && fallbackRoute is not null)
        importedFallback = returnPoints.ImportLegacyIni(fallbackRoute, "diagnostic-fallback-routes");

    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var deathRecognition = provider.GetRequiredService<IDeathRecognitionService>();
    var navigation = sceneState.Recognize(window, config.NavigationRecognition);
    var death = deathRecognition.Recognize(window, config.DeathRecognition);
    var nearest = navigation.HasCoordinate && HasReliableRuntimeMap(navigation) ? FindNearestReturnPoint(config, navigation) : null;
    var distance = nearest is null || !navigation.HasCoordinate
        ? (double?)null
        : Distance(navigation.X!.Value, navigation.Y!.Value, nearest.X, nearest.Y);
    var predicted = PredictReturnPointAction(config, navigation, death, nearest, distance);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-point", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var mapPath = Path.Combine(evidenceDir, "map-region.png");
    var coordPath = Path.Combine(evidenceDir, "coordinate-region.png");
    var deathPath = Path.Combine(evidenceDir, "death-region.png");
    var evidencePath = Path.Combine(evidenceDir, $"return-point-{window.Pid}.json");

    var mapResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.MapName, client.Width, client.Height, rightAnchored: true);
    var coordResolved = OcrRegionProjection.Resolve(config.NavigationRecognition.Coordinate, client.Width, client.Height, rightAnchored: true);
    var deathResolved = OcrRegionProjection.Resolve(config.DeathRecognition.PromptRegion, client.Width, client.Height);
    var mapCapture = CropCapture(client, mapResolved);
    var coordCapture = CropCapture(client, coordResolved);
    var deathCapture = CropCapture(client, deathResolved);

    var savedClient = SaveCapturePng(client, clientPath);
    var savedMap = SaveCapturePng(mapCapture, mapPath);
    var savedCoord = SaveCapturePng(coordCapture, coordPath);
    var savedDeath = SaveCapturePng(deathCapture, deathPath);
    var sceneUsable = HasReliableRuntimeMap(navigation) && navigation.HasCoordinate;
    var sceneReason = BuildSceneFieldReason(navigation, HasVisualContent(mapCapture), HasVisualContent(coordCapture));

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-return-point-evidence-no-input-no-click",
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = profileLoad is not null,
            loadedModules = profileLoad?.LoadedModules,
            missingModules = profileLoad?.MissingModules
        },
        config = new
        {
            config.ProfileName,
            config.EnableFixedFarmReturn,
            config.EnableEarthSpiritReturn,
            config.EnableDeathReturn,
            config.EnableStuckRecovery,
            config.ArrivalDistance,
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            config.NavigationRecognition.ConfirmedMapNameAutoFilled,
            pointCount = config.Points.Count,
            fallbackRouteImported = importedFallback is null ? null : new
            {
                importedFallback.SourcePath,
                importedFallback.MapCount,
                importedFallback.PointCount,
                importedFallback.SkippedCount
            }
        },
        recognition = new
        {
            navigation = new
            {
                navigation.MapNameText,
                navigation.MapNameSource,
                navigation.MapNameConfidencePercent,
                navigation.CoordinateText,
                navigation.CoordinateSource,
                navigation.CoordinateConfidencePercent,
                navigation.X,
                navigation.Y,
                navigation.HasMap,
                navigation.HasCoordinate
            },
            death = new
            {
                death.IsDead,
                death.Text,
                death.MatchedKeyword
            }
        },
        sceneGate = new
        {
            sceneUsable,
            mapFieldReady = navigation.HasMap,
            coordinateFieldReady = navigation.HasCoordinate,
            returnPointFieldReady = sceneUsable,
            automatedActionReady = false,
            reason = sceneReason
        },
        nearest = nearest is null ? null : new
        {
            nearest.MapName,
            nearest.X,
            nearest.Y,
            nearest.Label,
            kind = nearest.Kind.ToString(),
            distance
        },
        predicted,
        regions = new
        {
            client = new { path = clientPath, saved = savedClient, client.Width, client.Height, visual = HasVisualContent(client) },
            map = RegionEvidence(config.NavigationRecognition.MapName, mapResolved, mapPath, savedMap, mapCapture),
            coordinate = RegionEvidence(config.NavigationRecognition.Coordinate, coordResolved, coordPath, savedCoord, coordCapture),
            death = RegionEvidence(config.DeathRecognition.PromptRegion, deathResolved, deathPath, savedDeath, deathCapture)
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}, loadedModules={profileLoad?.LoadedModules.Count ?? 0}, missing={profileLoad?.MissingModules.Count ?? 0}, confirmedMap='{config.NavigationRecognition.ConfirmedMapName}', autoFilled={config.NavigationRecognition.ConfirmedMapNameAutoFilled}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Scene usable={sceneUsable}, returnPointFieldReady={sceneUsable}, reason={sceneReason}");
    Console.WriteLine($"Navigation map='{navigation.MapNameText}' source={navigation.MapNameSource} confidence={navigation.MapNameConfidencePercent}%, coord='{navigation.CoordinateText}' source={navigation.CoordinateSource} confidence={navigation.CoordinateConfidencePercent}%, parsed={navigation.X},{navigation.Y}");
    Console.WriteLine($"Death dead={death.IsDead}, keyword='{death.MatchedKeyword}', text='{death.Text}'");
    Console.WriteLine(nearest is null
        ? "Nearest=-"
        : $"Nearest={nearest.MapName}({nearest.X},{nearest.Y}), distance={distance:0.0}, kind={nearest.Kind}");
    Console.WriteLine($"Predicted={predicted.action}, suspend={predicted.shouldSuspendCombat}, reason={predicted.reason}");
    Console.WriteLine($"Crops map={savedMap}, coord={savedCoord}, death={savedDeath}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && savedClient
             && savedMap
             && savedCoord
             && savedDeath
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveReturnPointDryRunDiagnostics()
{
    Console.WriteLine("Live return-point dry-run diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);

    var returnPoints = new ReturnPointService(new MemoryProfileService(), provider.GetRequiredService<ILogService>());
    ResetScenarioConfig(returnPoints.Current);
    returnPoints.Current.EnableFixedFarmReturn = true;
    returnPoints.Current.ArrivalDistance = 3;
    returnPoints.Current.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
    returnPoints.Current.ReturnNavigation.Hotkey = "F5";
    returnPoints.Current.ReturnNavigation.ActionIntervalMs = 200;

    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var liveNavigation = sceneState.Recognize(window, returnPoints.Current.NavigationRecognition);
    if (!liveNavigation.HasCoordinate)
    {
        Console.Error.WriteLine($"FAIL: 当前真实窗口未识别坐标，不能构造 DryRun。coord='{liveNavigation.CoordinateText}'");
        return false;
    }

    const string confirmedMap = "诊断地图";
    var target = new ReturnPoint
    {
        MapName = confirmedMap,
        X = Math.Max(0, liveNavigation.X!.Value + 40),
        Y = Math.Max(0, liveNavigation.Y!.Value + 40),
        Label = "live-dryrun-target",
        Kind = ReturnPointKind.FixedFarm,
        SourceModule = "diagnostic-live-dryrun",
        SourcePath = "no-game-input"
    };
    returnPoints.AddPoint(target);
    returnPoints.Current.NavigationRecognition.ConfirmedMapName = confirmedMap;

    var dryRunNavigation = new NavigationRecognitionResult(
        confirmedMap,
        liveNavigation.CoordinateText,
        liveNavigation.X,
        liveNavigation.Y,
        "diagnostic-confirmed-map",
        100,
        liveNavigation.CoordinateSource,
        liveNavigation.CoordinateConfidencePercent);
    var input = new CountingInputService();
    var runtime = new ReturnPointRuntimeService(
        returnPoints,
        new StaticSceneStateService(dryRunNavigation),
        new StaticDeathRecognitionService(new DeathRecognitionResult(false, "", "")),
        new ReturnNavigationService(input, provider.GetRequiredService<ILogService>()),
        provider.GetRequiredService<ILogService>());

    runtime.Reset();
    var result = EvaluateReturnPointRuntime(runtime, window, 3);
    var distance = Distance(dryRunNavigation.X!.Value, dryRunNavigation.Y!.Value, target.X, target.Y);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-point-dryrun", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-point-dryrun-{window.Pid}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-coordinate-confirmed-map-return-dryrun-no-game-input",
        safety = new
        {
            usesRealGameWindow = true,
            sendsToRealGameWindow = false,
            inputService = nameof(CountingInputService),
            input.SendKeyCount,
            input.ClickCount,
            input.SendTextCount
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        liveNavigation = new
        {
            liveNavigation.MapNameText,
            liveNavigation.MapNameSource,
            liveNavigation.MapNameConfidencePercent,
            liveNavigation.CoordinateText,
            liveNavigation.CoordinateSource,
            liveNavigation.CoordinateConfidencePercent,
            liveNavigation.X,
            liveNavigation.Y,
            liveNavigation.HasCoordinate,
            liveNavigation.HasMap
        },
        dryRun = new
        {
            confirmedMap,
            target.MapName,
            target.X,
            target.Y,
            distance,
            returnPoints.Current.ArrivalDistance,
            result.Action,
            result.ShouldSuspendCombat,
            result.Message,
            sentHotkeys = input.SentHotkeys.ToArray()
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Live coord='{liveNavigation.CoordinateText}' parsed={liveNavigation.X},{liveNavigation.Y}, source={liveNavigation.CoordinateSource}, confidence={liveNavigation.CoordinateConfidencePercent}%");
    Console.WriteLine($"DryRun confirmedMap={confirmedMap}, target={target.X},{target.Y}, distance={distance:0.0}, arrival={returnPoints.Current.ArrivalDistance}");
    Console.WriteLine($"DryRun action={result.Action}, suspend={result.ShouldSuspendCombat}, message={result.Message}");
    Console.WriteLine($"Safety send={input.SendKeyCount}, click={input.ClickCount}, text={input.SendTextCount}, hotkeys={string.Join(",", input.SentHotkeys)}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && liveNavigation.HasCoordinate
             && result.Action == ReturnPointRuntimeAction.ReturnToPoint
             && result.ShouldSuspendCombat
             && input.SendKeyCount == 1
             && input.SentHotkeys.Contains("F5", StringComparer.OrdinalIgnoreCase)
             && input.ClickCount == 0
             && input.SendTextCount == 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveReturnPointArmDiagnostics(string[] args)
{
    Console.WriteLine("Live return-point arm diagnostics");

    var mapName = ReadOption(args, "--map");
    if (string.IsNullOrWhiteSpace(mapName))
    {
        Console.Error.WriteLine("FAIL: 必须提供 --map <当前地图名>，避免程序猜地图。");
        return false;
    }

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p") ?? $"方案-回点测试-{DateTime.Now:HHmm}";
    var hotkey = ReadOption(args, "--hotkey") ?? "F5";
    var replace = args.Any(a => a.Equals("--replace", StringComparison.OrdinalIgnoreCase));
    var arrival = ReadIntOption(args, "--arrival", 8);
    var interval = ReadIntOption(args, "--interval", 1000);
    var offset = ReadOffsetOption(args, "--offset", (0, 0));
    var click = ReadOffsetOption(args, "--click", (520, 360));
    var clickButton = ReadMouseButtonOption(args, "--button", InputMouseButton.Left);
    var clickRepeat = ReadIntOption(args, "--repeat", 1);
    var clickInterval = ReadIntOption(args, "--click-interval", 120);
    var afterHotkey = ReadOption(args, "--after-hotkey") ?? "";
    var afterDelay = ReadIntOption(args, "--after-delay", 120);
    var radius = ReadIntOption(args, "--radius", 220);
    var invertX = args.Any(a => a.Equals("--invert-x", StringComparison.OrdinalIgnoreCase));
    var invertY = args.Any(a => a.Equals("--invert-y", StringComparison.OrdinalIgnoreCase));
    var delay = ReadIntOption(args, "--delay", 120);
    var navigationMode = ReadReturnNavigationModeOption(args, "--mode", ReturnNavigationMode.HotkeyOnly);
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var label = ReadOption(args, "--label") ?? $"当前坐标-{DateTime.Now:HHmmss}";

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var dictionaryEvidence = new
    {
        totalFiles = dictionaryLoad.TotalFiles,
        loadedFiles = dictionaryLoad.LoadedFiles,
        skippedFiles = dictionaryLoad.SkippedFiles,
        loadedGlyphs = dictionaryLoad.LoadedGlyphs
    };

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var profileExists = appProfiles.ListProfileNames().Contains(profileName, StringComparer.Ordinal);
    AppProfileLoadResult? loadResult = profileExists ? appProfiles.LoadAll(profileName) : null;

    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var liveNavigation = sceneState.Recognize(window, returnPoints.Current.NavigationRecognition);
    if (!liveNavigation.HasCoordinate)
    {
        Console.Error.WriteLine($"FAIL: 当前真实窗口未识别坐标，不能生成返点配置。coord='{liveNavigation.CoordinateText}'");
        return false;
    }

    if (replace)
        returnPoints.Clear();

    var normalizedMap = NormalizeDiagnosticMapName(mapName);
    if (string.IsNullOrWhiteSpace(normalizedMap))
    {
        Console.Error.WriteLine("FAIL: --map 不是有效地图名。");
        return false;
    }

    var point = new ReturnPoint
    {
        MapName = normalizedMap,
        X = Math.Max(0, liveNavigation.X!.Value + offset.X),
        Y = Math.Max(0, liveNavigation.Y!.Value + offset.Y),
        Label = label,
        Kind = ReturnPointKind.FixedFarm,
        SourceModule = "diagnostic-live-arm",
        SourcePath = "live-return-point-arm"
    };
    returnPoints.AddPoint(point);

    var config = returnPoints.Current;
    config.ProfileName = profileName;
    config.EnableFixedFarmReturn = true;
    config.ArrivalDistance = Math.Max(1, arrival);
    config.NavigationRecognition.ConfirmedMapName = normalizedMap;
    config.NavigationRecognition.ConfirmedMapNameAutoFilled = false;
    config.ReturnNavigation.Mode = navigationMode;
    config.ReturnNavigation.Hotkey = hotkey;
    config.ReturnNavigation.ClickX = click.X;
    config.ReturnNavigation.ClickY = click.Y;
    config.ReturnNavigation.ClickButton = clickButton;
    config.ReturnNavigation.ClickRepeat = Math.Clamp(clickRepeat, 1, 10);
    config.ReturnNavigation.ClickIntervalMs = Math.Clamp(clickInterval, 20, 1000);
    config.ReturnNavigation.AfterClickHotkey = afterHotkey.Trim();
    config.ReturnNavigation.AfterClickDelayMs = Math.Clamp(afterDelay, 0, 3000);
    config.ReturnNavigation.DirectionRadius = Math.Clamp(radius, 20, 2000);
    config.ReturnNavigation.DirectionInvertX = invertX;
    config.ReturnNavigation.DirectionInvertY = invertY;
    config.ReturnNavigation.OpenMapDelayMs = Math.Clamp(delay, 0, 5000);
    config.ReturnNavigation.DispatchMode = dispatch;
    config.ReturnNavigation.ActionIntervalMs = Math.Max(200, interval);

    appProfiles.SaveAll(profileName);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-point-arm", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-point-arm-{window.Pid}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-coordinate-return-point-profile-arm-no-input",
        safety = new
        {
            sendsToRealGameWindow = false,
            clicksMouse = false,
            writesProfile = true,
            replaceExistingReturnPoints = replace
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        profile = new
        {
            profileName,
            profileExistsBefore = profileExists,
            loaded = loadResult is not null,
            loadedModules = loadResult?.LoadedModules,
            missingModules = loadResult?.MissingModules
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        liveNavigation = new
        {
            liveNavigation.MapNameText,
            liveNavigation.MapNameSource,
            liveNavigation.MapNameConfidencePercent,
            liveNavigation.CoordinateText,
            liveNavigation.CoordinateSource,
            liveNavigation.CoordinateConfidencePercent,
            liveNavigation.X,
            liveNavigation.Y,
            liveNavigation.HasCoordinate,
            liveNavigation.HasMap
        },
        configured = new
        {
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            point.MapName,
            point.X,
            point.Y,
            point.Label,
            offset,
            config.ArrivalDistance,
            returnMode = config.ReturnNavigation.Mode.ToString(),
            config.ReturnNavigation.Hotkey,
            config.ReturnNavigation.ClickX,
            config.ReturnNavigation.ClickY,
            clickButton = config.ReturnNavigation.ClickButton.ToString(),
            config.ReturnNavigation.ClickRepeat,
            config.ReturnNavigation.ClickIntervalMs,
            config.ReturnNavigation.AfterClickHotkey,
            config.ReturnNavigation.AfterClickDelayMs,
            config.ReturnNavigation.DirectionRadius,
            config.ReturnNavigation.DirectionInvertX,
            config.ReturnNavigation.DirectionInvertY,
            config.ReturnNavigation.OpenMapDelayMs,
            dispatch = config.ReturnNavigation.DispatchMode.ToString(),
            config.ReturnNavigation.ActionIntervalMs,
            pointCount = config.Points.Count
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Profile={profileName}, existed={profileExists}, replace={replace}");
    Console.WriteLine($"Live coord='{liveNavigation.CoordinateText}' parsed={liveNavigation.X},{liveNavigation.Y}, source={liveNavigation.CoordinateSource}, confidence={liveNavigation.CoordinateConfidencePercent}%");
    Console.WriteLine($"Configured map={normalizedMap}, point={point.X},{point.Y}, mode={navigationMode}, hotkey={hotkey}, click={click.X},{click.Y}, button={config.ReturnNavigation.ClickButton}, repeat={config.ReturnNavigation.ClickRepeat}, afterHotkey='{config.ReturnNavigation.AfterClickHotkey}', radius={config.ReturnNavigation.DirectionRadius}, invert={config.ReturnNavigation.DirectionInvertX}/{config.ReturnNavigation.DirectionInvertY}, delay={config.ReturnNavigation.OpenMapDelayMs}, dispatch={dispatch}, arrival={config.ArrivalDistance}");
    Console.WriteLine($"Safety send=0, click=0, text=0");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && liveNavigation.HasCoordinate
             && config.Points.Any(p => p.Id == point.Id)
             && config.NavigationRecognition.ConfirmedMapName == normalizedMap
             && config.ReturnNavigation.Mode == navigationMode
             && string.Equals(config.ReturnNavigation.Hotkey, hotkey, StringComparison.OrdinalIgnoreCase)
             && config.ReturnNavigation.ClickX == click.X
             && config.ReturnNavigation.ClickY == click.Y
             && config.ReturnNavigation.ClickButton == clickButton
             && config.ReturnNavigation.ClickRepeat == Math.Clamp(clickRepeat, 1, 10)
             && string.Equals(config.ReturnNavigation.AfterClickHotkey, afterHotkey.Trim(), StringComparison.OrdinalIgnoreCase)
             && config.ReturnNavigation.DirectionRadius == Math.Clamp(radius, 20, 2000)
             && config.ReturnNavigation.DirectionInvertX == invertX
             && config.ReturnNavigation.DirectionInvertY == invertY
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveNavigationActionDiagnostics(string[] args)
{
    Console.WriteLine("Live navigation action probe");

    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var requestedPid = ReadIntOption(args, "--pid", 0);
    var requestedInputHwnd = ReadHandleOption(args, "--input-hwnd", nint.Zero);
    var backgroundStrategy = (ReadOption(args, "--background-strategy") ?? "input-service").Trim().ToLowerInvariant();
    var expectedResult = (ReadOption(args, "--expect") ?? "navigation").Trim().ToLowerInvariant();
    var hotkey = ReadOption(args, "--hotkey") ?? "";
    var clickProvided = args.Any(a => a.Equals("--click", StringComparison.OrdinalIgnoreCase));
    var click = ReadOffsetOption(args, "--click", (-1, -1));
    var clickButton = ReadMouseButtonOption(args, "--button", InputMouseButton.Left);
    var repeat = Math.Clamp(ReadIntOption(args, "--repeat", 1), 1, 10);
    var clickInterval = Math.Clamp(ReadIntOption(args, "--click-interval", 120), 20, 1000);
    var delay = Math.Clamp(ReadIntOption(args, "--delay", 120), 0, 5000);
    var afterHotkey = ReadOption(args, "--after-hotkey") ?? "";
    var afterDelay = Math.Clamp(ReadIntOption(args, "--after-delay", 120), 0, 3000);
    var verifyMs = Math.Clamp(ReadIntOption(args, "--verify-ms", executeRequested ? 3000 : 0), 0, 30000);
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var target = ReadOffsetOption(args, "--target", (-1, -1));
    var hasTarget = target.X >= 0 && target.Y >= 0;

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .Where(p => requestedPid <= 0 || p.Id == requestedPid)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine(requestedPid > 0
            ? $"FAIL: 未找到 PID={requestedPid} 的 Game.exe 主窗口。"
            : "FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var realInput = provider.GetRequiredService<IInputService>();
    var perceptionHub = provider.GetRequiredService<IPerceptionHub>();
    var globalConfig = provider.GetRequiredService<IGlobalConfigService>();
    var inputHwnd = requestedInputHwnd == nint.Zero ? window.Hwnd : requestedInputHwnd;

    var gateReasons = new List<string>();
    if (window.Bitness != ClientBitness.X86 || !window.IsAutomationAllowed)
        gateReasons.Add($"目标窗口不可执行自动化：{window.AutomationBlockReason}");
    if (!DiagnosticWindowNative.IsWindow(inputHwnd))
        gateReasons.Add($"输入窗口句柄无效：0x{inputHwnd:X}。");
    else
    {
        _ = DiagnosticWindowNative.GetWindowThreadProcessId(inputHwnd, out var inputWindowPid);
        if (inputWindowPid != (uint)window.Pid)
            gateReasons.Add($"输入窗口 0x{inputHwnd:X} 不属于目标 PID={window.Pid}。");
    }
    if (string.IsNullOrWhiteSpace(hotkey) && !clickProvided && string.IsNullOrWhiteSpace(afterHotkey))
        gateReasons.Add("未提供任何动作参数。");
    if (!string.IsNullOrWhiteSpace(hotkey) && !realInput.TryParseHotkey(hotkey, out var hotkeyError))
        gateReasons.Add($"热键无效：{hotkeyError}");
    if (!string.IsNullOrWhiteSpace(afterHotkey) && !realInput.TryParseHotkey(afterHotkey, out var afterHotkeyError))
        gateReasons.Add($"后置热键无效：{afterHotkeyError}");
    if (clickProvided && (click.X < 0 || click.Y < 0))
        gateReasons.Add($"点击坐标无效：{click.X},{click.Y}");

    var allowedToExecute = executeRequested && gateReasons.Count == 0;
    IInputService input = allowedToExecute
        ? new AuditedInputService(realInput)
        : new CountingInputService();

    var beforeWindow = binding.BindByHandle(window.Hwnd) ?? window;
    var beforeNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var beforeCapture = capture.CaptureClient(window.Hwnd);
    var beforePerception = expectedResult is "target" or "hp-drop"
        ? perceptionHub.Read(window, globalConfig.Current)
        : null;

    if (!executeRequested)
        gateReasons.Add("未提供 --execute，本次只记录计划动作，不发送输入。");

    var actionMessages = new List<string>();
    if (!string.IsNullOrWhiteSpace(hotkey))
    {
        var nativeDetail = string.Empty;
        var actionOk = backgroundStrategy == "input-service"
            ? input.SendKey(inputHwnd, hotkey, dispatch)
            : allowedToExecute && DiagnosticBackgroundKeyProbe.TrySend(inputHwnd, hotkey, backgroundStrategy, out nativeDetail);
        actionMessages.Add(backgroundStrategy == "input-service"
            ? $"hotkey {hotkey}: {actionOk}"
            : $"hotkey {hotkey} via {backgroundStrategy}: {actionOk}; {nativeDetail}");
        if (delay > 0)
            Thread.Sleep(delay);
    }

    if (clickProvided)
    {
        for (var i = 0; i < repeat; i++)
        {
            var actionOk = input.Click(inputHwnd, click.X, click.Y, dispatch, clickButton);
            actionMessages.Add($"click {clickButton} ({click.X},{click.Y}) {i + 1}/{repeat}: {actionOk}");
            if (i + 1 < repeat)
                Thread.Sleep(clickInterval);
        }
    }

    if (!string.IsNullOrWhiteSpace(afterHotkey))
    {
        if (afterDelay > 0)
            Thread.Sleep(afterDelay);
        var actionOk = input.SendKey(inputHwnd, afterHotkey, dispatch);
        actionMessages.Add($"after hotkey {afterHotkey}: {actionOk}");
    }

    if (verifyMs > 0)
        Thread.Sleep(verifyMs);

    var afterWindow = binding.BindByHandle(window.Hwnd) ?? window;
    var afterNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var afterCapture = capture.CaptureClient(window.Hwnd);
    var afterPerception = expectedResult is "target" or "hp-drop"
        ? perceptionHub.Read(window, globalConfig.Current)
        : null;
    var beforeClientSize = beforeWindow.ClientSizeText;
    var afterClientSize = afterWindow.ClientSizeText;
    var clientSizeStable = string.Equals(beforeClientSize, afterClientSize, StringComparison.OrdinalIgnoreCase);
    var inputAudit = BuildInputAudit(input);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-action", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var beforePath = Path.Combine(evidenceDir, $"before-{window.Pid}.png");
    var afterPath = Path.Combine(evidenceDir, $"after-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"navigation-action-{window.Pid}.json");
    var beforeSaved = SaveCapturePng(beforeCapture, beforePath);
    var afterSaved = SaveCapturePng(afterCapture, afterPath);
    var beforeVisual = HasVisualContent(beforeCapture);
    var afterVisual = HasVisualContent(afterCapture);

    var coordinateChanged = beforeNavigation.HasCoordinate
        && afterNavigation.HasCoordinate
        && (beforeNavigation.X != afterNavigation.X || beforeNavigation.Y != afterNavigation.Y);
    var mapChanged = beforeNavigation.HasMap
        && afterNavigation.HasMap
        && !string.Equals(beforeNavigation.MapNameText, afterNavigation.MapNameText, StringComparison.Ordinal);
    var beforeDistanceToTarget = hasTarget && beforeNavigation.HasCoordinate
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var afterDistanceToTarget = hasTarget && afterNavigation.HasCoordinate
        ? Distance(afterNavigation.X!.Value, afterNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var movedCloserToTarget = beforeDistanceToTarget is not null
        && afterDistanceToTarget is not null
        && afterDistanceToTarget.Value < beforeDistanceToTarget.Value - 1.0;
    var arrivedAtTarget = afterDistanceToTarget is not null && afterDistanceToTarget.Value <= 8.0;
    var targetConfirmed = afterPerception?.Target.Presence == TargetPresence.Present
                          && afterPerception.Target.Life is TargetLifeState.Live or TargetLifeState.Weak;
    var targetHpDropped = beforePerception?.Target.HpPercent is int beforeTargetHp
                          && afterPerception?.Target.HpPercent is int afterTargetHp
                          && afterTargetHp < beforeTargetHp;

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-navigation-action-probe",
        safety = new
        {
            executeRequested,
            allowedToExecute,
            sendsToRealGameWindow = allowedToExecute,
            blockedReasons = gateReasons,
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.SentHotkeys,
            inputAudit.Clicks
        },
        window = new
        {
            window.Pid,
            window.Title,
            mainHwnd = $"0x{window.Hwnd:X}",
            inputHwnd = $"0x{inputHwnd:X}",
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        action = new
        {
            hotkey,
            clickProvided,
            click.X,
            click.Y,
            target = hasTarget ? new { target.X, target.Y } : null,
            button = clickButton.ToString(),
            repeat,
            clickInterval,
            delay,
            afterHotkey,
            afterDelay,
            verifyMs,
            dispatch = dispatch.ToString(),
            backgroundStrategy,
            expectedResult,
            messages = actionMessages
        },
        beforeNavigation = new
        {
            beforeNavigation.MapNameText,
            beforeNavigation.MapNameSource,
            beforeNavigation.MapNameConfidencePercent,
            beforeNavigation.CoordinateText,
            beforeNavigation.CoordinateSource,
            beforeNavigation.CoordinateConfidencePercent,
            beforeNavigation.X,
            beforeNavigation.Y,
            beforeNavigation.HasMap,
            beforeNavigation.HasCoordinate
        },
        afterNavigation = new
        {
            afterNavigation.MapNameText,
            afterNavigation.MapNameSource,
            afterNavigation.MapNameConfidencePercent,
            afterNavigation.CoordinateText,
            afterNavigation.CoordinateSource,
            afterNavigation.CoordinateConfidencePercent,
            afterNavigation.X,
            afterNavigation.Y,
            afterNavigation.HasMap,
            afterNavigation.HasCoordinate
        },
        beforeTarget = beforePerception is null ? null : new
        {
            presence = beforePerception.Target.Presence.ToString(),
            life = beforePerception.Target.Life.ToString(),
            beforePerception.Target.HpPercent,
            beforePerception.Target.NameText,
            beforePerception.Target.Confidence
        },
        afterTarget = afterPerception is null ? null : new
        {
            presence = afterPerception.Target.Presence.ToString(),
            life = afterPerception.Target.Life.ToString(),
            afterPerception.Target.HpPercent,
            afterPerception.Target.NameText,
            afterPerception.Target.Confidence
        },
        verification = new
        {
            coordinateChanged,
            mapChanged,
            beforeDistanceToTarget,
            afterDistanceToTarget,
            movedCloserToTarget,
            arrivedAtTarget,
            targetConfirmed,
            targetHpDropped,
            beforePath,
            afterPath,
            beforeSaved,
            afterSaved,
            beforeVisual,
            afterVisual
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"ExecuteRequested={executeRequested}, allowedToExecute={allowedToExecute}");
    foreach (var reason in gateReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Before map='{beforeNavigation.MapNameText}' source={beforeNavigation.MapNameSource} coord='{beforeNavigation.CoordinateText}' parsed={beforeNavigation.X},{beforeNavigation.Y}");
    Console.WriteLine($"After  map='{afterNavigation.MapNameText}' source={afterNavigation.MapNameSource} coord='{afterNavigation.CoordinateText}' parsed={afterNavigation.X},{afterNavigation.Y}");
    if (hasTarget)
        Console.WriteLine($"Target={target.X},{target.Y}, distBefore={beforeDistanceToTarget:0.0}, distAfter={afterDistanceToTarget:0.0}, movedCloser={movedCloserToTarget}, arrived={arrivedAtTarget}");
    Console.WriteLine($"Input send={inputAudit.SendKeyCount}, click={inputAudit.ClickCount}, text={inputAudit.SendTextCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)}");
    foreach (var msg in actionMessages)
        Console.WriteLine($"Action: {msg}");
    Console.WriteLine($"Changed coordinate={coordinateChanged}, map={mapChanged}");
    if (beforePerception is not null && afterPerception is not null)
        Console.WriteLine($"Target before={beforePerception.Target.Presence}/{beforePerception.Target.Life}/{beforePerception.Target.HpPercent}% after={afterPerception.Target.Presence}/{afterPerception.Target.Life}/{afterPerception.Target.HpPercent}% confirmed={targetConfirmed} hpDropped={targetHpDropped}");
    Console.WriteLine($"Capture before={beforeSaved}/{beforeVisual}, after={afterSaved}/{afterVisual}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && beforeSaved
             && afterSaved
             && (!allowedToExecute || expectedResult switch
             {
                 "target" => targetConfirmed,
                 "hp-drop" => targetHpDropped,
                 _ => hasTarget
                     ? movedCloserToTarget || arrivedAtTarget
                     : coordinateChanged || mapChanged
             });

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveNavigationCoordinateDiagnostics(string[] args)
{
    Console.WriteLine("Live navigation coordinate probe");

    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var target = ReadOffsetOption(args, "--target", (-1, -1));
    var xField = ReadOffsetOption(args, "--x-field", (1490, 469));
    var yField = ReadOffsetOption(args, "--y-field", (1530, 469));
    var moveButton = ReadOffsetOption(args, "--move", (1560, 469));
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.SendInput);
    var textMode = (ReadOption(args, "--text-mode") ?? "keys").Trim().ToLowerInvariant();
    var verifyMs = Math.Clamp(ReadIntOption(args, "--verify-ms", executeRequested ? 8000 : 0), 0, 30000);
    var stepDelay = Math.Clamp(ReadIntOption(args, "--step-delay", 120), 20, 1000);

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var realInput = provider.GetRequiredService<IInputService>();

    var gateReasons = new List<string>();
    if (window.Bitness != ClientBitness.X86 || !window.IsAutomationAllowed)
        gateReasons.Add($"目标窗口不可执行自动化：{window.AutomationBlockReason}");
    if (target.X < 0 || target.Y < 0)
        gateReasons.Add("--target 坐标无效，应为 x,y。");
    if (xField.X < 0 || xField.Y < 0 || yField.X < 0 || yField.Y < 0 || moveButton.X < 0 || moveButton.Y < 0)
        gateReasons.Add("输入框或移动按钮坐标无效。");

    var allowedToExecute = executeRequested && gateReasons.Count == 0;
    IInputService input = allowedToExecute
        ? new AuditedInputService(realInput)
        : new CountingInputService();

    var beforeNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var beforeCapture = capture.CaptureClient(window.Hwnd);

    if (!executeRequested)
        gateReasons.Add("未提供 --execute，本次只记录计划动作，不发送输入。");

    var actionMessages = new List<string>();
    bool DoClick((int X, int Y) point, string label)
    {
        var actionOk = input.Click(window.Hwnd, point.X, point.Y, dispatch, InputMouseButton.Left);
        actionMessages.Add($"{label} click ({point.X},{point.Y}): {actionOk}");
        Thread.Sleep(stepDelay);
        return actionOk;
    }

    bool DoKey(string key, string label)
    {
        var actionOk = input.SendKey(window.Hwnd, key, dispatch);
        actionMessages.Add($"{label} hotkey {key}: {actionOk}");
        Thread.Sleep(stepDelay);
        return actionOk;
    }

    bool DoText(string text, string label)
    {
        if (textMode is "key" or "keys" or "hotkey")
        {
            var allOk = true;
            foreach (var ch in text)
            {
                var key = ch.ToString();
                var actionOk = input.SendKey(window.Hwnd, key, dispatch);
                actionMessages.Add($"{label} key '{key}': {actionOk}");
                allOk &= actionOk;
                Thread.Sleep(Math.Min(stepDelay, 120));
            }

            Thread.Sleep(stepDelay);
            return allOk;
        }
        else
        {
            var actionOk = input.SendText(window.Hwnd, text, dispatch);
            actionMessages.Add($"{label} text '{text}': {actionOk}");
            Thread.Sleep(stepDelay);
            return actionOk;
        }
    }

    DoClick(xField, "x-field");
    DoKey("Ctrl+A", "x-field");
    DoText(target.X.ToString(), "x-field");
    DoClick(yField, "y-field");
    DoKey("Ctrl+A", "y-field");
    DoText(target.Y.ToString(), "y-field");
    DoClick(moveButton, "move-button");

    if (verifyMs > 0)
        Thread.Sleep(verifyMs);

    var afterNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var afterCapture = capture.CaptureClient(window.Hwnd);
    var inputAudit = BuildInputAudit(input);

    var beforeDistance = beforeNavigation.HasCoordinate
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var afterDistance = afterNavigation.HasCoordinate
        ? Distance(afterNavigation.X!.Value, afterNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var movedCloser = beforeDistance is not null && afterDistance is not null && afterDistance.Value < beforeDistance.Value - 1.0;
    var arrived = afterDistance is not null && afterDistance.Value <= 8.0;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-coordinate", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var beforePath = Path.Combine(evidenceDir, $"before-{window.Pid}.png");
    var afterPath = Path.Combine(evidenceDir, $"after-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"navigation-coordinate-{window.Pid}.json");
    var beforeSaved = SaveCapturePng(beforeCapture, beforePath);
    var afterSaved = SaveCapturePng(afterCapture, afterPath);
    var beforeVisual = HasVisualContent(beforeCapture);
    var afterVisual = HasVisualContent(afterCapture);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "scene-map-coordinate-navigation-probe",
        safety = new
        {
            executeRequested,
            allowedToExecute,
            sendsToRealGameWindow = allowedToExecute,
            blockedReasons = gateReasons,
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.SentHotkeys,
            inputAudit.Clicks
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        action = new
        {
            target.X,
            target.Y,
            xField,
            yField,
            moveButton,
            dispatch = dispatch.ToString(),
            textMode,
            verifyMs,
            stepDelay,
            messages = actionMessages
        },
        beforeNavigation = new
        {
            beforeNavigation.MapNameText,
            beforeNavigation.MapNameSource,
            beforeNavigation.MapNameConfidencePercent,
            beforeNavigation.CoordinateText,
            beforeNavigation.CoordinateSource,
            beforeNavigation.CoordinateConfidencePercent,
            beforeNavigation.X,
            beforeNavigation.Y,
            beforeNavigation.HasMap,
            beforeNavigation.HasCoordinate,
            distance = beforeDistance
        },
        afterNavigation = new
        {
            afterNavigation.MapNameText,
            afterNavigation.MapNameSource,
            afterNavigation.MapNameConfidencePercent,
            afterNavigation.CoordinateText,
            afterNavigation.CoordinateSource,
            afterNavigation.CoordinateConfidencePercent,
            afterNavigation.X,
            afterNavigation.Y,
            afterNavigation.HasMap,
            afterNavigation.HasCoordinate,
            distance = afterDistance
        },
        verification = new
        {
            movedCloser,
            arrived,
            beforePath,
            afterPath,
            beforeSaved,
            afterSaved,
            beforeVisual,
            afterVisual
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"ExecuteRequested={executeRequested}, allowedToExecute={allowedToExecute}");
    foreach (var reason in gateReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Target={target.X},{target.Y}");
    Console.WriteLine($"Before map='{beforeNavigation.MapNameText}' coord='{beforeNavigation.CoordinateText}' parsed={beforeNavigation.X},{beforeNavigation.Y}, distance={beforeDistance:0.0}");
    Console.WriteLine($"After  map='{afterNavigation.MapNameText}' coord='{afterNavigation.CoordinateText}' parsed={afterNavigation.X},{afterNavigation.Y}, distance={afterDistance:0.0}");
    Console.WriteLine($"Input send={inputAudit.SendKeyCount}, text={inputAudit.SendTextCount}, click={inputAudit.ClickCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)}");
    foreach (var msg in actionMessages)
        Console.WriteLine($"Action: {msg}");
    Console.WriteLine($"MovedCloser={movedCloser}, arrived={arrived}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && beforeSaved
             && afterSaved
             && (!allowedToExecute || movedCloser || arrived);

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveReturnRecordPlanDiagnostics(string[] args)
{
    Console.WriteLine("Live return record plan diagnostics");

    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? $"方案-真实回点-{DateTime.Now:MMdd-HHmm}"
        : requestedProfile.Trim();
    var durationMs = Math.Clamp(ReadIntOption(args, "--duration-ms", 20000), 3000, 120000);
    var prepareHotkeysText = ReadOption(args, "--prepare-hotkeys") ?? "M,Tab";
    var prepareDelayMs = Math.Clamp(ReadIntOption(args, "--prepare-delay-ms", 500), 20, 5000);
    var prepareYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);
    var requestedMapName = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var targetOption = ReadOffsetOption(args, "--target", (-1, -1));
    var hasExplicitTarget = targetOption.X >= 0 && targetOption.Y >= 0;
    var offset = ReadOffsetOption(args, "--offset", (20, 0));

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var window = TryBindFirstGameWindow(provider);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var profileLoadedForMap = !string.IsNullOrWhiteSpace(requestedProfile) && returnPoints.Load(profileName);
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var navigation = sceneState.Recognize(window, returnPoints.Current.NavigationRecognition);
    var confirmedMapName = NormalizeDiagnosticMapName(returnPoints.Current.NavigationRecognition.ConfirmedMapName);
    var mapName = ResolveDiagnosticMapName(navigation, requestedMapName, confirmedMapName, out var mapNameSource);

    if (string.IsNullOrWhiteSpace(mapName) || !navigation.HasCoordinate)
    {
        Console.Error.WriteLine($"FAIL: 当前地图/坐标未稳定识别，不能生成真实录制计划。map='{navigation.MapNameText}', coord='{navigation.CoordinateText}', manualMap='{requestedMapName}', confirmedMap='{confirmedMapName}'");
        return false;
    }

    var target = hasExplicitTarget
        ? targetOption
        : (Math.Max(0, navigation.X!.Value + offset.X), Math.Max(0, navigation.Y!.Value + offset.Y));
    var distanceToTarget = Distance(navigation.X!.Value, navigation.Y!.Value, target.Item1, target.Item2);
    var quotedProfile = QuotePowerShellArg(profileName);
    var quotedMap = QuotePowerShellArg(mapName);
    var mapOption = $" --map {quotedMap}";
    var targetText = $"{target.Item1},{target.Item2}";
    var prepareQuoted = QuotePowerShellArg(prepareHotkeysText);
    var dotnet = "& 'C:\\Program Files\\dotnet\\dotnet.exe'";
    var project = "'.\\tools\\TlbbAgent.Diagnostics\\TlbbAgent.Diagnostics.csproj'";
    var recordCommand =
        $"{dotnet} run --no-build --project {project} -- live-navigation-record{mapOption} --target {targetText} --duration-ms {durationMs} --prepare-hotkeys {prepareQuoted} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs} --execute-prepare";
    var importCommand =
        $"{dotnet} run --no-build --project {project} -- return-navigation-import-record --profile {quotedProfile}{mapOption} --slot fixed --latest --pre-hotkeys {prepareQuoted} --pre-delay-ms {prepareDelayMs} --force --add-point --confirm-map --label 真实回点 --dispatch SendInput";
    var checkCommand =
        $"{dotnet} run --no-build --project {project} -- live-return-navigation-readiness --profile {quotedProfile} --slot fixed";
    var executeCommand =
        $"{dotnet} run --no-build --project {project} -- live-return-point-execute --profile {quotedProfile} --execute --verify-ms 10000";

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-record-plan", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"return-record-plan-{window.Pid}.json");
    var client = capture.CaptureClient(window.Hwnd);
    var clientSaved = SaveCapturePng(client, clientPath);
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-return-record-plan-readonly-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesProfile = false,
            generatedCommandsOnly = true
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        current = new
        {
            mapName,
            resolvedMapNameSource = mapNameSource,
            requestedMapName,
            confirmedMapName,
            profileLoadedForMap,
            navigation.MapNameText,
            rawMapNameSource = navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y
        },
        target = new
        {
            X = target.Item1,
            Y = target.Item2,
            explicitTarget = hasExplicitTarget,
            offset,
            distanceToTarget
        },
        plan = new
        {
            profileName,
            durationMs,
            prepareHotkeys = prepareHotkeysText,
            prepareDelayMs,
            prepareYieldMs,
            commands = new
            {
                recordCommand,
                importCommand,
                checkCommand,
                executeCommand
            }
        },
        capture = new
        {
            clientPath,
            clientSaved,
            visual = HasVisualContent(client),
            width = client?.Width ?? 0,
            height = client?.Height ?? 0
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}, bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Current={mapName} {navigation.X},{navigation.Y}, mapSource={mapNameSource}, coordSource={navigation.CoordinateSource}, confidence={navigation.CoordinateConfidencePercent}%");
    Console.WriteLine($"Target={targetText}, distance={distanceToTarget:0.0}, profile={profileName}");
    Console.WriteLine("Step1 record:");
    Console.WriteLine(recordCommand);
    Console.WriteLine("Step2 import:");
    Console.WriteLine(importCommand);
    Console.WriteLine("Step3 check:");
    Console.WriteLine(checkCommand);
    Console.WriteLine("Step4 execute:");
    Console.WriteLine(executeCommand);
    Console.WriteLine($"ClientCapture={clientPath}, saved={clientSaved}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && !string.IsNullOrWhiteSpace(mapName)
             && navigation.HasCoordinate
             && distanceToTarget > 1.0
             && clientSaved
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveReturnRecordWorkflowDiagnostics(string[] args)
{
    Console.WriteLine("Live return record controlled workflow diagnostics");

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(profileName))
    {
        Console.Error.WriteLine("FAIL: 必须提供 --profile <方案名>，避免把录制样本导入非预期方案。");
        return false;
    }

    var target = ReadOffsetOption(args, "--target", (-1, -1));
    if (target.X < 0 || target.Y < 0)
    {
        Console.Error.WriteLine("FAIL: 必须提供 --target x,y；真实回点录制必须验证靠近或到达目标坐标。");
        return false;
    }

    var mapName = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var slotText = ReadOption(args, "--slot") ?? "fixed";
    var durationMs = Math.Clamp(ReadIntOption(args, "--duration-ms", 20000), 3000, 120000);
    var prepareHotkeysText = ReadOption(args, "--prepare-hotkeys") ?? "M,Tab";
    var prepareDelayMs = Math.Clamp(ReadIntOption(args, "--prepare-delay-ms", 500), 20, 5000);
    var prepareYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);
    var executePrepare = args.Any(a => a.Equals("--execute-prepare", StringComparison.OrdinalIgnoreCase));
    var ignoreYield = args.Any(a => a.Equals("--ignore-yield", StringComparison.OrdinalIgnoreCase));
    var allowEmpty = args.Any(a => a.Equals("--allow-empty", StringComparison.OrdinalIgnoreCase));
    var force = args.Any(a => a.Equals("--force", StringComparison.OrdinalIgnoreCase));
    var addPoint = !args.Any(a => a.Equals("--no-add-point", StringComparison.OrdinalIgnoreCase));
    var confirmMap = !args.Any(a => a.Equals("--no-confirm-map", StringComparison.OrdinalIgnoreCase));
    var label = ReadOption(args, "--label") ?? "真实回点";
    var dispatch = ReadOption(args, "--dispatch") ?? "SendInput";
    var expectRecordFail = args.Any(a => a.Equals("--expect-record-fail", StringComparison.OrdinalIgnoreCase));

    var workflowDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-record-workflow", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(workflowDir);
    var workflowEvidencePath = Path.Combine(workflowDir, $"return-record-workflow-{SanitizeFileName(profileName)}.json");
    var steps = new List<object>();

    void WriteEvidence(bool success, string finalStatus, string? latestRecord)
    {
        var evidence = new
        {
            capturedAt = DateTimeOffset.Now,
            mode = "live-return-record-controlled-workflow",
            safety = new
            {
                sendsPrepareInputOnlyWhenExecutePrepare = executePrepare,
                prepareYieldMs,
                ignoreYield,
                importsOnlyAfterRecordAndVerifyPass = true,
                writesProfileOnlyAfterVerifiedRecord = true,
                writesMemory = false,
                patchesClient = false
            },
            request = new
            {
                profileName,
                mapName,
                slot = slotText,
                target = new { target.X, target.Y },
                durationMs,
                prepareHotkeysText,
                prepareDelayMs,
                executePrepare,
                allowEmpty,
                force,
                addPoint,
                confirmMap,
                label,
                dispatch,
                expectRecordFail
            },
            latestRecord,
            steps,
            success,
            finalStatus
        };
        File.WriteAllText(workflowEvidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));
    }

    var recordArgs = new List<string>
    {
        "--duration-ms", durationMs.ToString(CultureInfo.InvariantCulture),
        "--target", $"{target.X},{target.Y}",
        "--prepare-hotkeys", prepareHotkeysText,
        "--prepare-delay-ms", prepareDelayMs.ToString(CultureInfo.InvariantCulture),
        "--yield-ms", prepareYieldMs.ToString(CultureInfo.InvariantCulture)
    };
    if (!string.IsNullOrWhiteSpace(mapName))
        recordArgs.AddRange(new[] { "--map", mapName });
    if (executePrepare)
        recordArgs.Add("--execute-prepare");
    if (ignoreYield)
        recordArgs.Add("--ignore-yield");
    if (allowEmpty)
        recordArgs.Add("--allow-empty");

    Console.WriteLine("Step1 record");
    var recordOk = RunLiveNavigationRecordDiagnostics(recordArgs.ToArray());
    var latestRecord = FindLatestNavigationRecordEvidenceRaw();
    steps.Add(new
    {
        step = "record",
        ok = recordOk,
        latestRecord,
        args = recordArgs.ToArray()
    });

    if (!recordOk)
    {
        var ok = expectRecordFail;
        var status = ok
            ? "录制按预期失败，未执行校验/导入/门禁。"
            : "录制失败，已停止，未导入任何样本。";
        WriteEvidence(ok, status, latestRecord);
        Console.WriteLine($"Workflow: {status}");
        Console.WriteLine($"Evidence={workflowEvidencePath}");
        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }

    Console.WriteLine("Step2 verify latest record");
    var verifyOk = RunReturnNavigationRecordVerifyDiagnostics(new[] { "--latest" });
    steps.Add(new
    {
        step = "verify",
        ok = verifyOk,
        latestRecord
    });
    if (!verifyOk)
    {
        WriteEvidence(false, "录制样本校验失败，已停止，未导入。", latestRecord);
        Console.WriteLine($"Evidence={workflowEvidencePath}");
        Console.WriteLine("FAIL");
        return false;
    }

    var importArgs = new List<string>
    {
        "--profile", profileName,
        "--slot", slotText,
        "--latest",
        "--pre-hotkeys", prepareHotkeysText,
        "--pre-delay-ms", prepareDelayMs.ToString(CultureInfo.InvariantCulture),
        "--label", label,
        "--dispatch", dispatch
    };
    if (!string.IsNullOrWhiteSpace(mapName))
        importArgs.AddRange(new[] { "--map", mapName });
    if (force)
        importArgs.Add("--force");
    if (addPoint)
        importArgs.Add("--add-point");
    if (confirmMap)
        importArgs.Add("--confirm-map");

    Console.WriteLine("Step3 import verified record");
    var importOk = RunReturnNavigationImportRecordDiagnostics(importArgs.ToArray());
    steps.Add(new
    {
        step = "import",
        ok = importOk,
        args = importArgs.ToArray()
    });
    if (!importOk)
    {
        WriteEvidence(false, "导入失败，已停止。", latestRecord);
        Console.WriteLine($"Evidence={workflowEvidencePath}");
        Console.WriteLine("FAIL");
        return false;
    }

    Console.WriteLine("Step4 live readiness");
    var readinessArgs = new[] { "--profile", profileName, "--slot", slotText };
    var readinessOk = RunLiveReturnNavigationReadinessDiagnostics(readinessArgs);
    steps.Add(new
    {
        step = "readiness",
        ok = readinessOk,
        args = readinessArgs
    });

    WriteEvidence(readinessOk, readinessOk ? "录制、校验、导入、门禁检查完成。" : "已导入，但真实窗口门禁仍未通过。", latestRecord);
    Console.WriteLine($"Evidence={workflowEvidencePath}");
    Console.WriteLine(readinessOk ? "PASS" : "FAIL");
    return readinessOk;
}

static bool RunLiveNavigationRecordDiagnostics(string[] args)
{
    Console.WriteLine("Live navigation manual record diagnostics");

    var durationMs = Math.Clamp(ReadIntOption(args, "--duration-ms", 15000), 300, 120000);
    var pollMs = Math.Clamp(ReadIntOption(args, "--poll-ms", 20), 10, 200);
    var sampleMs = Math.Clamp(ReadIntOption(args, "--sample-ms", 1000), 250, 10000);
    var allowEmpty = args.Any(a => a.Equals("--allow-empty", StringComparison.OrdinalIgnoreCase));
    var target = ReadOffsetOption(args, "--target", (-1, -1));
    var hasTarget = target.X >= 0 && target.Y >= 0;
    var requestedMapName = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var executePrepare = args.Any(a => a.Equals("--execute-prepare", StringComparison.OrdinalIgnoreCase));
    var prepareYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);
    var ignorePrepareYield = args.Any(a => a.Equals("--ignore-yield", StringComparison.OrdinalIgnoreCase));
    var prepareHotkeys = ReadRecordedPrepareHotkeys(args, ReadIntOption(args, "--prepare-delay-ms", 500));

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var input = provider.GetRequiredService<IInputService>();
    input.YieldToUserInput = prepareYieldMs > 0;
    input.UserInputYieldMs = prepareYieldMs;

    var prepareMessages = new List<string>();
    var prepareGateReasons = new List<string>();
    if (prepareHotkeys.Count > 0 && !executePrepare)
        prepareGateReasons.Add("提供了 --prepare-hotkeys 但未提供 --execute-prepare，本次不发送准备热键。");

    foreach (var hotkey in prepareHotkeys)
    {
        if (string.IsNullOrWhiteSpace(hotkey.Hotkey))
            prepareGateReasons.Add("准备热键为空。");
        else if (!input.TryParseHotkey(hotkey.Hotkey, out var hotkeyError))
            prepareGateReasons.Add($"准备热键无效：{hotkey.Hotkey} | {hotkeyError}");
    }

    InputYieldStatus? prepareYieldStatus = null;
    if (executePrepare && prepareHotkeys.Count > 0 && prepareYieldMs > 0)
    {
        prepareYieldStatus = input.GetYieldStatus(window.Hwnd, InputDispatchMode.SendInput);
        if (prepareYieldStatus.ShouldYield && !ignorePrepareYield)
        {
            prepareGateReasons.Add($"检测到近期人工操作，跳过准备热键以避免抢窗口：{prepareYieldStatus.Reason}");
        }
        else if (prepareYieldStatus.ShouldYield && ignorePrepareYield)
        {
            prepareMessages.Add($"ignore-yield: 检测到近期人工操作但按参数继续准备热键：{prepareYieldStatus.Reason}");
        }
    }

    var allowPrepareInput = executePrepare && prepareHotkeys.Count > 0 && prepareGateReasons.Count == 0;
    if (executePrepare && prepareHotkeys.Count == 0)
        prepareGateReasons.Add("提供了 --execute-prepare 但没有准备热键。");

    if (allowPrepareInput)
    {
        if (ignorePrepareYield)
            input.YieldToUserInput = false;

        foreach (var hotkey in prepareHotkeys)
        {
            var sent = input.SendKey(window.Hwnd, hotkey.Hotkey, InputDispatchMode.SendInput);
            prepareMessages.Add($"prepare hotkey {hotkey.Hotkey}: {sent}");
            if (hotkey.DelayAfterMs > 0)
                Thread.Sleep(Math.Clamp(hotkey.DelayAfterMs, 20, 5000));
        }
    }

    var beforeWindow = binding.BindByHandle(window.Hwnd) ?? window;
    var beforeRawNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var beforeNavigation = ApplyDiagnosticMapNameIfMissing(beforeRawNavigation, requestedMapName, "manual-option");
    var beforeCapture = capture.CaptureClient(window.Hwnd);
    var events = new List<NavigationRecordedMouseEvent>();
    var samples = new List<NavigationRecordSample>();

    bool leftDown = IsMouseDown(MouseRecordNative.VK_LBUTTON);
    bool rightDown = IsMouseDown(MouseRecordNative.VK_RBUTTON);

    Console.WriteLine($"Recording {durationMs}ms. 手动执行一次寻路点击；默认只记录鼠标状态，不发送输入。");
    foreach (var reason in prepareGateReasons)
        Console.WriteLine($"PrepareGate: {reason}");
    foreach (var message in prepareMessages)
        Console.WriteLine($"Prepare: {message}");
    var sw = Stopwatch.StartNew();
    var nextSampleMs = 0L;
    while (sw.ElapsedMilliseconds < durationMs)
    {
        var elapsed = sw.ElapsedMilliseconds;
        if (elapsed >= nextSampleMs)
        {
            var nav = ApplyDiagnosticMapNameIfMissing(
                sceneState.Recognize(window, new NavigationRecognitionConfig()),
                requestedMapName,
                "manual-option");
            samples.Add(new NavigationRecordSample(
                elapsed,
                nav.MapNameText,
                nav.CoordinateText,
                nav.X,
                nav.Y,
                nav.MapNameConfidencePercent,
                nav.CoordinateConfidencePercent));
            nextSampleMs = elapsed + sampleMs;
        }

        var hasCursor = MouseRecordNative.GetCursorPos(out var point);
        var currentLeft = IsMouseDown(MouseRecordNative.VK_LBUTTON);
        var currentRight = IsMouseDown(MouseRecordNative.VK_RBUTTON);

        if (currentLeft != leftDown)
        {
            AddMouseRecordEvent(events, binding, sceneState, window, elapsed, "Left", currentLeft ? "Down" : "Up", hasCursor, point);
            leftDown = currentLeft;
        }

        if (currentRight != rightDown)
        {
            AddMouseRecordEvent(events, binding, sceneState, window, elapsed, "Right", currentRight ? "Down" : "Up", hasCursor, point);
            rightDown = currentRight;
        }

        Thread.Sleep(pollMs);
    }

    var afterWindow = binding.BindByHandle(window.Hwnd) ?? window;
    var afterRawNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var afterNavigation = ApplyDiagnosticMapNameIfMissing(afterRawNavigation, requestedMapName, "manual-option");
    var afterCapture = capture.CaptureClient(window.Hwnd);
    var beforeClientSize = beforeWindow.ClientSizeText;
    var afterClientSize = afterWindow.ClientSizeText;
    var clientSizeStable = string.Equals(beforeClientSize, afterClientSize, StringComparison.OrdinalIgnoreCase);
    var coordinateChanged = beforeNavigation.HasCoordinate
        && afterNavigation.HasCoordinate
        && (beforeNavigation.X != afterNavigation.X || beforeNavigation.Y != afterNavigation.Y);
    var distanceMoved = beforeNavigation.HasCoordinate && afterNavigation.HasCoordinate
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, afterNavigation.X!.Value, afterNavigation.Y!.Value)
        : (double?)null;
    var beforeDistanceToTarget = hasTarget && beforeNavigation.HasCoordinate
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var afterDistanceToTarget = hasTarget && afterNavigation.HasCoordinate
        ? Distance(afterNavigation.X!.Value, afterNavigation.Y!.Value, target.X, target.Y)
        : (double?)null;
    var movedCloserToTarget = beforeDistanceToTarget is not null
        && afterDistanceToTarget is not null
        && afterDistanceToTarget.Value < beforeDistanceToTarget.Value - 1.0;
    var arrivedAtTarget = afterDistanceToTarget is not null && afterDistanceToTarget.Value <= 8.0;
    var inClientDownClickCount = events.Count(e =>
        e.InClient
        && string.Equals(e.Action, "Down", StringComparison.OrdinalIgnoreCase)
        && (string.Equals(e.Button, "Left", StringComparison.OrdinalIgnoreCase)
            || string.Equals(e.Button, "Right", StringComparison.OrdinalIgnoreCase)));
    var outOfClientDownClickCount = events.Count(e =>
        !e.InClient
        && string.Equals(e.Action, "Down", StringComparison.OrdinalIgnoreCase)
        && (string.Equals(e.Button, "Left", StringComparison.OrdinalIgnoreCase)
            || string.Equals(e.Button, "Right", StringComparison.OrdinalIgnoreCase)));
    var operatorInterferenceReasons = new List<string>();
    if (!allowEmpty && inClientDownClickCount > 1)
        operatorInterferenceReasons.Add($"录制期间出现 {inClientDownClickCount} 次客户区点击；真实回点样本默认只接受一次明确寻路点击。");
    if (outOfClientDownClickCount > 0)
        operatorInterferenceReasons.Add($"录制期间出现 {outOfClientDownClickCount} 次客户区外点击，可能混入用户操作。");
    if (!clientSizeStable)
        operatorInterferenceReasons.Add($"录制期间客户区尺寸变化：{beforeClientSize} -> {afterClientSize}，复放坐标可能偏移。");
    var operatorInterferenceRisk = operatorInterferenceReasons.Count > 0;
    var usableForImport = inClientDownClickCount > 0;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-record", DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));
    Directory.CreateDirectory(evidenceDir);
    var beforePath = Path.Combine(evidenceDir, $"before-{window.Pid}.png");
    var afterPath = Path.Combine(evidenceDir, $"after-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"navigation-record-{window.Pid}.json");
    var beforeSaved = SaveCapturePng(beforeCapture, beforePath);
    var afterSaved = SaveCapturePng(afterCapture, afterPath);
    var beforeVisual = HasVisualContent(beforeCapture);
    var afterVisual = HasVisualContent(afterCapture);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "manual-navigation-success-recorder-read-only",
        safety = new
        {
            sendsInput = allowPrepareInput,
            clicksMouse = false,
            hooksInput = false,
            readsMouseStateOnly = true,
            allowEmpty,
            executePrepare,
            prepareHotkeys,
            prepareGateReasons,
            prepareMessages,
            prepareYieldMs,
            ignorePrepareYield,
            prepareYieldStatus,
            durationMs,
            pollMs,
            sampleMs
        },
        target = hasTarget ? new { target.X, target.Y } : null,
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        beforeNavigation = new
        {
            beforeNavigation.MapNameText,
            beforeNavigation.MapNameSource,
            beforeNavigation.MapNameConfidencePercent,
            rawMapNameText = beforeRawNavigation.MapNameText,
            rawMapNameSource = beforeRawNavigation.MapNameSource,
            rawMapNameConfidencePercent = beforeRawNavigation.MapNameConfidencePercent,
            requestedMapName,
            beforeNavigation.CoordinateText,
            beforeNavigation.X,
            beforeNavigation.Y,
            beforeNavigation.CoordinateConfidencePercent
        },
        afterNavigation = new
        {
            afterNavigation.MapNameText,
            afterNavigation.MapNameSource,
            afterNavigation.MapNameConfidencePercent,
            rawMapNameText = afterRawNavigation.MapNameText,
            rawMapNameSource = afterRawNavigation.MapNameSource,
            rawMapNameConfidencePercent = afterRawNavigation.MapNameConfidencePercent,
            requestedMapName,
            afterNavigation.CoordinateText,
            afterNavigation.X,
            afterNavigation.Y,
            afterNavigation.CoordinateConfidencePercent
        },
        verification = new
        {
            coordinateChanged,
            distanceMoved,
            beforeDistanceToTarget,
            afterDistanceToTarget,
            movedCloserToTarget,
            arrivedAtTarget,
            beforeClientSize,
            afterClientSize,
            clientSizeStable,
            eventCount = events.Count,
            inClientDownClickCount,
            outOfClientDownClickCount,
            operatorInterferenceRisk,
            operatorInterferenceReasons,
            usableForImport,
            beforePath,
            afterPath,
            beforeSaved,
            afterSaved,
            beforeVisual,
            afterVisual
        },
        events,
        samples
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, beforeSize={beforeClientSize}, afterSize={afterClientSize}, sizeStable={clientSizeStable}, allowed={window.IsAutomationAllowed}");
    if (prepareYieldStatus is not null)
        Console.WriteLine($"PrepareYield enabled={prepareYieldStatus.Enabled}, shouldYield={prepareYieldStatus.ShouldYield}, ageMs={prepareYieldStatus.LastInputAgeMs:0}, remainingMs={prepareYieldStatus.RemainingYieldMs:0}, ignore={ignorePrepareYield}, reason={prepareYieldStatus.Reason}");
    Console.WriteLine($"Before map='{beforeNavigation.MapNameText}' coord='{beforeNavigation.CoordinateText}' parsed={beforeNavigation.X},{beforeNavigation.Y}");
    Console.WriteLine($"After  map='{afterNavigation.MapNameText}' coord='{afterNavigation.CoordinateText}' parsed={afterNavigation.X},{afterNavigation.Y}");
    if (hasTarget)
        Console.WriteLine($"Target={target.X},{target.Y}, distBefore={beforeDistanceToTarget:0.0}, distAfter={afterDistanceToTarget:0.0}, movedCloser={movedCloserToTarget}, arrived={arrivedAtTarget}");
    Console.WriteLine($"Events={events.Count}, inClientDownClicks={inClientDownClickCount}, outOfClientDownClicks={outOfClientDownClickCount}, samples={samples.Count}, usableForImport={usableForImport}, interferenceRisk={operatorInterferenceRisk}, coordinateChanged={coordinateChanged}, distanceMoved={distanceMoved:0.0}");
    foreach (var reason in operatorInterferenceReasons)
        Console.WriteLine($"InterferenceGate: {reason}");
    foreach (var e in events.Take(12))
        Console.WriteLine($"Event {e.ElapsedMs}ms {e.Button} {e.Action}: screen={e.ScreenX},{e.ScreenY}, client={e.ClientX},{e.ClientY}, inClient={e.InClient}, nav={e.MapNameText} {e.CoordinateText}");
    Console.WriteLine($"Capture before={beforeSaved}/{beforeVisual}, after={afterSaved}/{afterVisual}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && beforeSaved
             && afterSaved
             && beforeVisual
             && afterVisual
             && (allowEmpty || usableForImport)
             && !operatorInterferenceRisk
             && prepareGateReasons.Count == 0
             && (!hasTarget || movedCloserToTarget || arrivedAtTarget);

    Console.WriteLine(ok ? "PASS" : "FAIL");
    if (!ok && !allowEmpty && !usableForImport)
        Console.Error.WriteLine("FAIL: 未录到客户区点击。请在录制时间内手动点击场景地图，或仅取证时添加 --allow-empty。");
    if (!ok && hasTarget && !movedCloserToTarget && !arrivedAtTarget)
        Console.Error.WriteLine("FAIL: 录制后未验证到朝目标坐标移动。请重新录制一次有效寻路点击，或去掉 --target 仅记录点击样本。");
    if (!ok && operatorInterferenceRisk)
        Console.Error.WriteLine("FAIL: 录制期间检测到疑似人工操作干扰。请重新录制，录制窗口内只做一次明确寻路点击。");
    return ok;
}

static bool RunReturnNavigationRecordVerifyDiagnostics(string[] args)
{
    Console.WriteLine("Return navigation record verify diagnostics");

    var expectFail = args.Any(a => a.Equals("--expect-fail", StringComparison.OrdinalIgnoreCase));
    var evidencePath = ReadOption(args, "--evidence") ?? args.FirstOrDefault(a => a.EndsWith(".json", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(evidencePath) || args.Any(a => a.Equals("--latest", StringComparison.OrdinalIgnoreCase)))
        evidencePath = FindLatestNavigationRecordEvidenceRaw();

    if (string.IsNullOrWhiteSpace(evidencePath) || !File.Exists(evidencePath))
    {
        Console.Error.WriteLine("FAIL: 未找到 navigation-record JSON。请提供 --evidence <json> 或先运行 live-navigation-record。");
        return false;
    }

    evidencePath = Path.GetFullPath(evidencePath);
    var reasons = new List<string>();
    var warnings = new List<string>();
    JsonObject root;
    try
    {
        root = JsonNode.Parse(File.ReadAllText(evidencePath, Encoding.UTF8))?.AsObject()
               ?? throw new InvalidOperationException("invalid navigation record json");
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"FAIL: 录制样本 JSON 解析失败：{ex.Message}");
        return false;
    }

    var synthetic = IsSyntheticRecordedSourceForDiagnostics(evidencePath);
    if (synthetic)
        reasons.Add("录制样本路径包含 synthetic/smoke，只允许诊断回归，禁止导入真实方案。");

    var window = root["window"]?.AsObject();
    var target = root["target"]?.AsObject();
    var before = root["beforeNavigation"]?.AsObject();
    var after = root["afterNavigation"]?.AsObject();
    var verification = root["verification"]?.AsObject();
    var events = root["events"]?.AsArray() ?? new JsonArray();
    var samples = root["samples"]?.AsArray() ?? new JsonArray();

    var clientSize = ReadJsonString(window, "clientSize");
    if (string.IsNullOrWhiteSpace(clientSize))
        reasons.Add("缺少 window.clientSize，无法保证录制坐标适配当前客户区。");
    else if (!TryParseClientSize(clientSize, out _, out _))
        reasons.Add($"window.clientSize 格式无效：{clientSize}");

    var targetX = ReadJsonInt(target, "X");
    var targetY = ReadJsonInt(target, "Y");
    if (targetX is null || targetY is null)
        reasons.Add("缺少 target.X/Y；真实回点必须有目标坐标来验证靠近或到达。");

    var beforeX = ReadJsonInt(before, "X");
    var beforeY = ReadJsonInt(before, "Y");
    var afterX = ReadJsonInt(after, "X");
    var afterY = ReadJsonInt(after, "Y");
    if (beforeX is null || beforeY is null)
        reasons.Add("缺少 beforeNavigation 坐标。");
    if (afterX is null || afterY is null)
        reasons.Add("缺少 afterNavigation 坐标。");

    var usableForImport = ReadJsonBool(verification, "usableForImport");
    var movedCloser = ReadJsonBool(verification, "movedCloserToTarget");
    var arrived = ReadJsonBool(verification, "arrivedAtTarget");
    var recordedOperatorInterferenceRisk = ReadJsonBool(verification, "operatorInterferenceRisk");
    var beforeClientSize = ReadJsonString(verification, "beforeClientSize");
    var afterClientSize = ReadJsonString(verification, "afterClientSize");
    var clientSizeStableFieldPresent = verification is not null
                                       && verification.TryGetPropertyValue("clientSizeStable", out var clientSizeStableNode)
                                       && clientSizeStableNode is not null;
    var clientSizeStable = !clientSizeStableFieldPresent || ReadJsonBool(verification, "clientSizeStable");
    if (!usableForImport)
        reasons.Add("verification.usableForImport=false；没有可导入的客户区点击。");
    if (!movedCloser && !arrived)
        reasons.Add("未验证到 movedCloserToTarget 或 arrivedAtTarget；禁止作为真实回点样本。");
    if (!clientSizeStable)
        reasons.Add($"录制期间客户区尺寸变化：{beforeClientSize} -> {afterClientSize}，复放坐标可能偏移。");
    if (!string.IsNullOrWhiteSpace(beforeClientSize)
        && !string.IsNullOrWhiteSpace(afterClientSize)
        && !string.Equals(beforeClientSize, afterClientSize, StringComparison.OrdinalIgnoreCase))
        reasons.Add($"录制开始/结束客户区尺寸不一致：{beforeClientSize} -> {afterClientSize}。");

    var inClientDownClickCount = 0;
    var outOfClientDownClickCount = 0;
    foreach (var node in events)
    {
        if (node is not JsonObject e)
            continue;
        if (!string.Equals(ReadJsonString(e, "Action"), "Down", StringComparison.OrdinalIgnoreCase))
            continue;
        var button = ReadJsonString(e, "Button");
        if (!string.Equals(button, "Left", StringComparison.OrdinalIgnoreCase)
            && !string.Equals(button, "Right", StringComparison.OrdinalIgnoreCase))
            continue;

        if (ReadJsonBool(e, "InClient"))
            inClientDownClickCount++;
        else
            outOfClientDownClickCount++;
    }

    if (inClientDownClickCount == 0)
        reasons.Add("没有客户区内鼠标 Down 点击，无法复放真实寻路。");
    if (inClientDownClickCount > 1)
        reasons.Add($"录制样本包含 {inClientDownClickCount} 次客户区点击；真实回点样本默认只接受一次明确寻路点击，避免混入用户操作。");
    if (outOfClientDownClickCount > 0)
        reasons.Add($"录制样本包含 {outOfClientDownClickCount} 次客户区外点击，疑似录制期间用户操作干扰。");
    if (recordedOperatorInterferenceRisk)
        reasons.Add("verification.operatorInterferenceRisk=true；录制阶段已标记疑似人工操作干扰。");

    var beforePath = ReadJsonString(verification, "beforePath");
    var afterPath = ReadJsonString(verification, "afterPath");
    if (!string.IsNullOrWhiteSpace(beforePath) && !File.Exists(beforePath))
        warnings.Add($"before 截图证据缺失：{beforePath}");
    if (!string.IsNullOrWhiteSpace(afterPath) && !File.Exists(afterPath))
        warnings.Add($"after 截图证据缺失：{afterPath}");

    var acceptableForRealImport = reasons.Count == 0;
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-navigation-record-verify", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var verifyEvidencePath = Path.Combine(evidenceDir, $"record-verify-{SanitizeFileName(Path.GetFileNameWithoutExtension(evidencePath))}.json");
    var output = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-navigation-record-verify-readonly-no-input",
        sourceEvidence = evidencePath,
        acceptableForRealImport,
        syntheticOrSmoke = synthetic,
        reasons,
        warnings,
        window = new
        {
            clientSize,
            title = ReadJsonString(window, "Title"),
            bitness = ReadJsonString(window, "bitness")
        },
        before = new
        {
            map = ReadJsonString(before, "MapNameText"),
            coordinate = ReadJsonString(before, "CoordinateText"),
            X = beforeX,
            Y = beforeY
        },
        after = new
        {
            map = ReadJsonString(after, "MapNameText"),
            coordinate = ReadJsonString(after, "CoordinateText"),
            X = afterX,
            Y = afterY
        },
        target = new
        {
            X = targetX,
            Y = targetY
        },
        verification = new
        {
            usableForImport,
            movedCloserToTarget = movedCloser,
            arrivedAtTarget = arrived,
            operatorInterferenceRisk = recordedOperatorInterferenceRisk,
            beforeClientSize,
            afterClientSize,
            clientSizeStable,
            coordinateChanged = ReadJsonBool(verification, "coordinateChanged"),
            inClientDownClickCount,
            outOfClientDownClickCount,
            eventCount = events.Count,
            sampleCount = samples.Count
        }
    };
    File.WriteAllText(verifyEvidencePath, System.Text.Json.JsonSerializer.Serialize(output, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Source={evidencePath}");
    Console.WriteLine($"ClientSize={clientSize}, synthetic={synthetic}");
    Console.WriteLine($"Before={beforeX},{beforeY}; After={afterX},{afterY}; Target={targetX},{targetY}");
    Console.WriteLine($"Clicks inClient={inClientDownClickCount}, outOfClient={outOfClientDownClickCount}, events={events.Count}, samples={samples.Count}");
    Console.WriteLine($"Verification usable={usableForImport}, movedCloser={movedCloser}, arrived={arrived}, interferenceRisk={recordedOperatorInterferenceRisk}, sizeStable={clientSizeStable}");
    foreach (var warning in warnings)
        Console.WriteLine($"WARN: {warning}");
    foreach (var reason in reasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Evidence={verifyEvidencePath}");

    var ok = expectFail ? !acceptableForRealImport : acceptableForRealImport;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveNavigationReplayDiagnostics(string[] args)
{
    Console.WriteLine("Live navigation replay diagnostics");

    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var evidencePath = ReadOption(args, "--evidence") ?? args.FirstOrDefault(a => a.EndsWith(".json", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(evidencePath) || args.Any(a => a.Equals("--latest", StringComparison.OrdinalIgnoreCase)))
        evidencePath = FindLatestNavigationRecordEvidenceRaw();

    if (string.IsNullOrWhiteSpace(evidencePath) || !File.Exists(evidencePath))
    {
        Console.Error.WriteLine("FAIL: 未找到可复放的 live-navigation-record JSON。请提供 --evidence <json> 或先运行 live-navigation-record。");
        return false;
    }

    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.SendInput);
    var verifyMs = Math.Clamp(ReadIntOption(args, "--verify-ms", executeRequested ? 8000 : 0), 0, 30000);
    var clickIntervalMs = Math.Clamp(ReadIntOption(args, "--click-interval", 120), 20, 2000);
    var maxClicks = Math.Clamp(ReadIntOption(args, "--max-clicks", 8), 1, 50);
    var preHotkeys = ReadRecordedPreHotkeys(args, evidencePath, ReadIntOption(args, "--pre-delay-ms", 500));

    var record = LoadNavigationReplayRecord(evidencePath, maxClicks);
    if (record.Actions.Count == 0)
    {
        Console.Error.WriteLine("FAIL: 记录文件中没有可复放的客户区点击。");
        return false;
    }

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var realInput = provider.GetRequiredService<IInputService>();

    var gateReasons = new List<string>();
    if (window.Bitness != ClientBitness.X86 || !window.IsAutomationAllowed)
        gateReasons.Add($"目标窗口不可执行自动化：{window.AutomationBlockReason}");
    foreach (var action in record.Actions)
    {
        if (action.ClientX < 0 || action.ClientY < 0 || action.ClientX >= window.ClientWidth || action.ClientY >= window.ClientHeight)
            gateReasons.Add($"记录点击超出当前客户区：{action.ClientX},{action.ClientY}，当前 {window.ClientSizeText}。");
    }
    foreach (var hotkey in preHotkeys)
    {
        if (string.IsNullOrWhiteSpace(hotkey.Hotkey))
            gateReasons.Add("前置热键为空。");
        else if (!realInput.TryParseHotkey(hotkey.Hotkey, out var hotkeyError))
            gateReasons.Add($"前置热键无效：{hotkey.Hotkey} | {hotkeyError}");
    }

    var allowedToExecute = executeRequested && gateReasons.Count == 0;
    if (!executeRequested)
        gateReasons.Add("未提供 --execute，本次只记录复放计划，不发送输入。");

    IInputService input = allowedToExecute
        ? new AuditedInputService(realInput)
        : new CountingInputService();

    var beforeNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var beforeCapture = capture.CaptureClient(window.Hwnd);
    var actionMessages = new List<string>();
    foreach (var hotkey in preHotkeys)
    {
        var ok = input.SendKey(window.Hwnd, hotkey.Hotkey, dispatch);
        actionMessages.Add($"pre-hotkey {hotkey.Hotkey}: {ok}");
        if (hotkey.DelayAfterMs > 0)
            Thread.Sleep(Math.Clamp(hotkey.DelayAfterMs, 20, 5000));
    }

    foreach (var action in record.Actions)
    {
        var ok = input.Click(window.Hwnd, action.ClientX, action.ClientY, dispatch, action.Button);
        actionMessages.Add($"{action.Button} click ({action.ClientX},{action.ClientY}) from {action.ElapsedMs}ms: {ok}");
        Thread.Sleep(clickIntervalMs);
    }

    if (verifyMs > 0)
        Thread.Sleep(verifyMs);

    var afterNavigation = sceneState.Recognize(window, new NavigationRecognitionConfig());
    var afterCapture = capture.CaptureClient(window.Hwnd);
    var inputAudit = BuildInputAudit(input);

    var coordinateChanged = beforeNavigation.HasCoordinate
        && afterNavigation.HasCoordinate
        && (beforeNavigation.X != afterNavigation.X || beforeNavigation.Y != afterNavigation.Y);
    var distanceMoved = beforeNavigation.HasCoordinate && afterNavigation.HasCoordinate
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, afterNavigation.X!.Value, afterNavigation.Y!.Value)
        : (double?)null;
    var beforeDistanceToRecordedAfter = beforeNavigation.HasCoordinate && record.AfterX is not null && record.AfterY is not null
        ? Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, record.AfterX.Value, record.AfterY.Value)
        : (double?)null;
    var afterDistanceToRecordedAfter = afterNavigation.HasCoordinate && record.AfterX is not null && record.AfterY is not null
        ? Distance(afterNavigation.X!.Value, afterNavigation.Y!.Value, record.AfterX.Value, record.AfterY.Value)
        : (double?)null;
    var movedCloserToRecordedAfter = beforeDistanceToRecordedAfter is not null
        && afterDistanceToRecordedAfter is not null
        && afterDistanceToRecordedAfter.Value < beforeDistanceToRecordedAfter.Value - 1.0;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-replay", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var beforePath = Path.Combine(evidenceDir, $"before-{window.Pid}.png");
    var afterPath = Path.Combine(evidenceDir, $"after-{window.Pid}.png");
    var replayEvidencePath = Path.Combine(evidenceDir, $"navigation-replay-{window.Pid}.json");
    var beforeSaved = SaveCapturePng(beforeCapture, beforePath);
    var afterSaved = SaveCapturePng(afterCapture, afterPath);
    var beforeVisual = HasVisualContent(beforeCapture);
    var afterVisual = HasVisualContent(afterCapture);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "manual-navigation-record-replay",
        sourceEvidence = evidencePath,
        safety = new
        {
            executeRequested,
            allowedToExecute,
            sendsToRealGameWindow = allowedToExecute,
            blockedReasons = gateReasons,
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.SentHotkeys,
            inputAudit.Clicks
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        record = new
        {
            record.SourceClientSize,
            record.BeforeMap,
            record.BeforeCoordinate,
            record.BeforeX,
            record.BeforeY,
            record.AfterMap,
            record.AfterCoordinate,
            record.AfterX,
            record.AfterY,
            preHotkeys,
            actions = record.Actions
        },
        replay = new
        {
            dispatch = dispatch.ToString(),
            verifyMs,
            clickIntervalMs,
            messages = actionMessages
        },
        beforeNavigation = new
        {
            beforeNavigation.MapNameText,
            beforeNavigation.CoordinateText,
            beforeNavigation.X,
            beforeNavigation.Y,
            distanceToRecordedAfter = beforeDistanceToRecordedAfter
        },
        afterNavigation = new
        {
            afterNavigation.MapNameText,
            afterNavigation.CoordinateText,
            afterNavigation.X,
            afterNavigation.Y,
            distanceToRecordedAfter = afterDistanceToRecordedAfter
        },
        verification = new
        {
            coordinateChanged,
            distanceMoved,
            movedCloserToRecordedAfter,
            beforePath,
            afterPath,
            beforeSaved,
            afterSaved,
            beforeVisual,
            afterVisual
        }
    };
    File.WriteAllText(replayEvidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"EvidenceSource={evidencePath}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"ExecuteRequested={executeRequested}, allowedToExecute={allowedToExecute}");
    foreach (var reason in gateReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Record before='{record.BeforeMap}' '{record.BeforeCoordinate}' parsed={record.BeforeX},{record.BeforeY}; after='{record.AfterMap}' '{record.AfterCoordinate}' parsed={record.AfterX},{record.AfterY}");
    Console.WriteLine($"PreHotkeys={string.Join(",", preHotkeys.Select(h => $"{h.Hotkey}/delay={h.DelayAfterMs}"))}");
    Console.WriteLine($"Before map='{beforeNavigation.MapNameText}' coord='{beforeNavigation.CoordinateText}' parsed={beforeNavigation.X},{beforeNavigation.Y}, distToRecordAfter={beforeDistanceToRecordedAfter:0.0}");
    Console.WriteLine($"After  map='{afterNavigation.MapNameText}' coord='{afterNavigation.CoordinateText}' parsed={afterNavigation.X},{afterNavigation.Y}, distToRecordAfter={afterDistanceToRecordedAfter:0.0}");
    Console.WriteLine($"Input send={inputAudit.SendKeyCount}, text={inputAudit.SendTextCount}, click={inputAudit.ClickCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)}");
    foreach (var msg in actionMessages.Take(12))
        Console.WriteLine($"Action: {msg}");
    Console.WriteLine($"coordinateChanged={coordinateChanged}, distanceMoved={distanceMoved:0.0}, movedCloserToRecordedAfter={movedCloserToRecordedAfter}");
    Console.WriteLine($"Evidence={replayEvidencePath}");

    var replayOk = File.Exists(replayEvidencePath)
                   && new FileInfo(replayEvidencePath).Length > 0
                   && beforeSaved
                   && afterSaved
                   && beforeVisual
                   && afterVisual
                   && (!allowedToExecute || coordinateChanged || movedCloserToRecordedAfter);

    Console.WriteLine(replayOk ? "PASS" : "FAIL");
    return replayOk;
}

static bool RunReturnNavigationImportRecordDiagnostics(string[] args)
{
    Console.WriteLine("Return navigation import record diagnostics");

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(profileName))
    {
        Console.Error.WriteLine("FAIL: 必须提供 --profile <方案名>，避免误覆盖未知配置。");
        return false;
    }

    var evidencePath = ReadOption(args, "--evidence") ?? args.FirstOrDefault(a => a.EndsWith(".json", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(evidencePath) || args.Any(a => a.Equals("--latest", StringComparison.OrdinalIgnoreCase)))
        evidencePath = FindLatestNavigationRecordEvidenceRaw();

    if (string.IsNullOrWhiteSpace(evidencePath) || !File.Exists(evidencePath))
    {
        Console.Error.WriteLine("FAIL: 未找到 live-navigation-record JSON。请提供 --evidence <json> 或先运行 live-navigation-record。");
        return false;
    }

    var force = args.Any(a => a.Equals("--force", StringComparison.OrdinalIgnoreCase));
    var expectFail = args.Any(a => a.Equals("--expect-fail", StringComparison.OrdinalIgnoreCase));
    var allowSynthetic = args.Any(a => a.Equals("--allow-synthetic", StringComparison.OrdinalIgnoreCase));
    var addPoint = args.Any(a => a.Equals("--add-point", StringComparison.OrdinalIgnoreCase));
    var confirmMap = args.Any(a => a.Equals("--confirm-map", StringComparison.OrdinalIgnoreCase));
    var confirmedMapName = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var label = ReadOption(args, "--label") ?? "";
    var slot = ReturnNavigationRecordImportService.ParseSlot(ReadOption(args, "--slot") ?? "fixed");
    var maxClicks = Math.Clamp(ReadIntOption(args, "--max-clicks", 8), 1, 50);
    var fallbackDelayMs = Math.Clamp(ReadIntOption(args, "--delay-ms", 120), 20, 5000);
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var pointKind = ReadReturnPointKindOption(args, "--point-kind", ReturnPointKindForSlot(slot));
    var preHotkeys = ReadRecordedPreHotkeys(args, evidencePath, ReadIntOption(args, "--pre-delay-ms", 500));

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();
    var importer = provider.GetRequiredService<IReturnNavigationRecordImportService>();
    var import = importer.Import(new ReturnNavigationRecordImportRequest
    {
        ProfileName = profileName,
        EvidencePath = evidencePath,
        Slot = slot,
        Force = force,
        ConfirmMapFromRecordEnd = confirmMap,
        AddReturnPointFromRecordEnd = addPoint,
        ReturnPointLabel = label,
        ReturnPointKind = pointKind,
        ConfirmedMapName = confirmedMapName,
        MaxClicks = maxClicks,
        FallbackDelayMs = fallbackDelayMs,
        PreHotkeys = preHotkeys,
        DispatchMode = dispatch,
        AllowSyntheticForDiagnostics = allowSynthetic
    });
    if (!import.Success)
    {
        if (expectFail)
        {
            Console.WriteLine($"Expected failure: {import.Message}");
            Console.WriteLine("PASS");
            return true;
        }

        Console.Error.WriteLine($"FAIL: {import.Message}");
        return false;
    }
    if (expectFail)
    {
        Console.Error.WriteLine("FAIL: 期望导入失败，但录制记录被导入。");
        return false;
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-navigation-import-record", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var importEvidencePath = Path.Combine(evidenceDir, $"return-navigation-import-{SanitizeFileName(profileName)}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var importEvidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-navigation-import-record",
        profileName,
        profileExisted = import.ProfileExisted,
        allowSynthetic,
        confirmedMapName,
        slot = import.SlotName,
        sourceEvidence = import.EvidencePath,
        import.SourceClientSize,
        import.BeforeMap,
        import.BeforeCoordinate,
        import.BeforeX,
        import.BeforeY,
        import.AfterMap,
        import.AfterCoordinate,
        import.AfterX,
        import.AfterY,
        import.TargetX,
        import.TargetY,
        import.MovedCloserToTarget,
        import.ArrivedAtTarget,
        import.ConfirmedMapFromRecordEnd,
        import.AddedReturnPointFromRecordEnd,
        import.AddedReturnPoint,
        dispatch = dispatch.ToString(),
        recordedPreHotkeys = import.RecordedPreHotkeys,
        recordedClicks = import.RecordedClicks
    };
    File.WriteAllText(importEvidencePath, System.Text.Json.JsonSerializer.Serialize(importEvidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}, existed={import.ProfileExisted}");
    Console.WriteLine($"Slot={import.SlotName}, mode={ReturnNavigationMode.RecordedClientClickSequence}, dispatch={dispatch}, allowSynthetic={allowSynthetic}");
    Console.WriteLine($"Source={import.EvidencePath}");
    Console.WriteLine($"Record before='{import.BeforeMap}' '{import.BeforeCoordinate}' parsed={import.BeforeX},{import.BeforeY}; after='{import.AfterMap}' '{import.AfterCoordinate}' parsed={import.AfterX},{import.AfterY}");
    Console.WriteLine($"Target={import.TargetX},{import.TargetY}, movedCloser={import.MovedCloserToTarget}, arrived={import.ArrivedAtTarget}");
    Console.WriteLine($"ConfirmMapFromRecordEnd={import.ConfirmedMapFromRecordEnd}, AddReturnPointFromRecordEnd={import.AddedReturnPointFromRecordEnd}, point={import.AddedReturnPoint?.MapName} {import.AddedReturnPoint?.X},{import.AddedReturnPoint?.Y} [{import.AddedReturnPoint?.Kind}]");
    Console.WriteLine($"Imported pre-hotkeys={import.RecordedPreHotkeys.Count}: {string.Join(";", import.RecordedPreHotkeys.Select(h => $"{h.Hotkey}/delay={h.DelayAfterMs}"))}");
    Console.WriteLine($"Imported clicks={import.RecordedClicks.Count}: {string.Join(";", import.RecordedClicks.Select(c => $"{c.Button}:{c.ClientX},{c.ClientY}/delay={c.DelayAfterMs}"))}");
    Console.WriteLine($"Evidence={importEvidencePath}");
    Console.WriteLine("PASS");
    return true;
}

static bool RunReturnNavigationCheckDiagnostics(string[] args)
{
    Console.WriteLine("Return navigation profile check diagnostics");

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(profileName))
    {
        Console.Error.WriteLine("FAIL: 必须提供 --profile <方案名>。");
        return false;
    }

    var explicitClientSize = TryParseClientSize(ReadOption(args, "--client-size"), out var explicitWidth, out var explicitHeight)
        ? (Width: explicitWidth, Height: explicitHeight)
        : ((int Width, int Height)?)null;
    var slotOnly = args.Any(a => a.Equals("--slot-only", StringComparison.OrdinalIgnoreCase));
    var slotFilterText = ReadOption(args, "--slot");
    var slotFilter = string.IsNullOrWhiteSpace(slotFilterText)
        ? (ReturnNavigationSlot?)null
        : ReturnNavigationRecordImportService.ParseSlot(slotFilterText);

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var profiles = provider.GetRequiredService<IAppProfileService>();
    var load = profiles.LoadAll(profileName);
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;

    var allChecks = new List<ReturnNavigationSlotCheck>();
    allChecks.Add(CheckReturnNavigationSlot("挂机回点", ReturnNavigationSlot.FixedFarm, config.EnableFixedFarmReturn, config.ReturnNavigation, explicitClientSize));
    allChecks.Add(CheckReturnNavigationSlot("土灵回点", ReturnNavigationSlot.EarthSpirit, config.EnableEarthSpiritReturn, config.EarthSpiritNavigation, explicitClientSize));
    allChecks.Add(CheckReturnNavigationSlot("卡点恢复", ReturnNavigationSlot.StuckRecovery, config.EnableStuckRecovery, config.StuckRecoveryNavigation, explicitClientSize));
    allChecks.Add(CheckReturnNavigationSlot("死亡回点", ReturnNavigationSlot.DeathReturn, config.EnableDeathReturn, config.DeathReturnNavigation, explicitClientSize));
    var checks = slotFilter is null
        ? allChecks
        : allChecks.Where(c => c.Slot == slotFilter.Value).ToList();

    var globalReasons = new List<string>();
    var returnLoaded = load.LoadedModules.Contains("返点配置", StringComparer.Ordinal);
    if (!returnLoaded)
        globalReasons.Add("方案中未加载到返点配置。");
    if (!slotOnly)
    {
        if (!IsAnyReturnGateEnabled(config))
            globalReasons.Add("回点、土灵、卡点恢复和死亡回点均未启用。");
        if (config.Points.Count == 0)
            globalReasons.Add("未配置返点坐标；定点回点无法判断目标点。");
        if (string.IsNullOrWhiteSpace(config.NavigationRecognition.ConfirmedMapName))
            globalReasons.Add("未确认当前地图；地图 OCR 不稳定时真实回点会被门禁拦截。");
    }

    var enabledChecks = checks.Where(c => c.Enabled).ToArray();
    var hasRunnableSlot = enabledChecks.Any(c => c.IsRunnable);
    if (!hasRunnableSlot)
        globalReasons.Add("没有任何已启用槽位具备可执行导航动作。");

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-navigation-check", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-navigation-check-{SanitizeFileName(profileName)}.json");
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-navigation-profile-check",
        profileName,
        explicitClientSize,
        slotOnly,
        slotFilter,
        profile = new
        {
            loadedModules = load.LoadedModules,
            missingModules = load.MissingModules,
            returnLoaded
        },
        config = new
        {
            config.ProfileName,
            config.EnableFixedFarmReturn,
            config.EnableEarthSpiritReturn,
            config.EnableStuckRecovery,
            config.EnableDeathReturn,
            points = config.Points.Count,
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            config.ArrivalDistance,
            config.ReturnRetryLimit
        },
        globalReasons,
        slots = checks
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}");
    Console.WriteLine($"ReturnLoaded={returnLoaded}, points={config.Points.Count}, confirmedMap={config.NavigationRecognition.ConfirmedMapName}");
    foreach (var reason in globalReasons)
        Console.WriteLine($"Gate: {reason}");
    foreach (var check in checks)
    {
        Console.WriteLine($"Slot={check.SlotName}, enabled={check.Enabled}, mode={check.Mode}, runnable={check.IsRunnable}, recorded={check.RecordedClickCount}");
        foreach (var reason in check.Reasons)
            Console.WriteLine($"  - {reason}");
    }
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = returnLoaded && checks.Count > 0 && globalReasons.Count == 0 && enabledChecks.Length > 0 && enabledChecks.All(c => c.IsRunnable);
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReturnReadinessDiagnostics(string[] args)
{
    Console.WriteLine("Return point readiness diagnostics");

    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var dictionaryEvidence = new
    {
        totalFiles = dictionaryLoad.TotalFiles,
        loadedFiles = dictionaryLoad.LoadedFiles,
        skippedFiles = dictionaryLoad.SkippedFiles,
        loadedGlyphs = dictionaryLoad.LoadedGlyphs
    };

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindFirstGameWindow();

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var loaded = string.IsNullOrWhiteSpace(requestedProfile) || returnPoints.Load(requestedProfile);
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? returnPoints.Current.ProfileName
        : requestedProfile;

    var report = provider.GetRequiredService<IReturnPointReadinessService>().Inspect(includeLiveRecognition: true);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-readiness", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-readiness-{(window?.Pid.ToString() ?? "no-window")}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-readiness-readonly-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesMemory = false,
            patchesClient = false
        },
        requestedProfile = requestedProfile ?? "",
        profileName,
        profileLoaded = loaded,
        dictionaryLoad = dictionaryEvidence,
        boundWindow = window is null ? null : new
        {
            window.Pid,
            Title = CleanEvidenceText(window.Title),
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            window.ClientWidth,
            window.ClientHeight
        },
        report
    };
    var jsonOptions = new System.Text.Json.JsonSerializerOptions { WriteIndented = true };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}, loaded={loaded}, dictionaries={dictionaryLoad.LoadedGlyphs}");
    Console.WriteLine($"Window={(window is null ? "-" : $"{window.Pid}/{window.Bitness}/{window.ClientSizeText}")}");
    Console.WriteLine($"Level={report.Level}");
    Console.WriteLine($"Summary={report.Summary}");
    Console.WriteLine($"NextAction={report.NextAction}");
    Console.WriteLine($"Scene={report.SceneSummary}");
    foreach (var slot in report.Slots)
        Console.WriteLine($"Slot={slot.SlotName}, enabled={slot.Enabled}, level={slot.Level}, summary={slot.Summary}");
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine("PASS");
    return true;
}

static bool RunReturnCaptureCurrentDiagnostics(string[] args)
{
    Console.WriteLine("Return point current-position capture diagnostics");

    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var label = ReadOption(args, "--label") ?? "current-position";
    var kind = ReadReturnCaptureKindOption(args, "--kind", ReturnPointKind.FixedFarm);
    var commit = args.Any(a => a.Equals("--commit", StringComparison.OrdinalIgnoreCase));

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());
    var dictionaryEvidence = new
    {
        totalFiles = dictionaryLoad.TotalFiles,
        loadedFiles = dictionaryLoad.LoadedFiles,
        skippedFiles = dictionaryLoad.SkippedFiles,
        loadedGlyphs = dictionaryLoad.LoadedGlyphs
    };

    var window = TryBindFirstGameWindow(provider);
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var profileLoaded = false;
    var profileName = requestedProfile?.Trim() ?? "";

    if (!string.IsNullOrWhiteSpace(profileName))
    {
        profileLoaded = returnPoints.Load(profileName);
    }
    else
    {
        profileName = returnPoints.Current.ProfileName;
    }

    ReturnPointCaptureResult result;
    string? commitBlockReason = null;
    if (commit && string.IsNullOrWhiteSpace(requestedProfile))
    {
        commitBlockReason = "--commit requires --profile to avoid saving into an unintended default profile.";
        result = new ReturnPointCaptureResult(false, commitBlockReason, null, null);
    }
    else if (!string.IsNullOrWhiteSpace(requestedProfile) && !profileLoaded)
    {
        commitBlockReason = $"profile not found or failed to load: {requestedProfile}";
        result = new ReturnPointCaptureResult(false, commitBlockReason, null, null);
    }
    else
    {
        var capture = provider.GetRequiredService<IReturnPointCaptureService>();
        result = commit
            ? capture.CaptureAndAddCurrentPoint(kind, label)
            : capture.PreviewCurrentPoint();

        if (commit && result.Success)
            returnPoints.Save(profileName);
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-capture-current", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-capture-current-{(window?.Pid.ToString() ?? "no-window")}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = commit ? "return-capture-current-commit" : "return-capture-current-preview-readonly",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesMemory = false,
            patchesClient = false,
            writesConfig = commit && result.Success
        },
        requestedProfile = requestedProfile ?? "",
        profileName,
        profileLoaded,
        commit,
        kind = kind.ToString(),
        label,
        dictionaryLoad = dictionaryEvidence,
        boundWindow = window is null ? null : new
        {
            window.Pid,
            Title = CleanEvidenceText(window.Title),
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            window.ClientWidth,
            window.ClientHeight
        },
        commitBlockReason,
        result = new
        {
            result.Success,
            MessageCode = result.Success ? "success" : "failed",
            MessageUtf8Base64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(result.Message ?? string.Empty)),
            point = result.Point is null ? null : new
            {
                result.Point.Id,
                MapName = CleanEvidenceText(result.Point.MapName),
                result.Point.X,
                result.Point.Y,
                Label = CleanEvidenceText(result.Point.Label),
                Kind = result.Point.Kind.ToString(),
                SourceModule = CleanEvidenceText(result.Point.SourceModule),
                SourcePath = CleanEvidenceText(result.Point.SourcePath)
            },
            navigation = result.Navigation is null ? null : new
            {
                MapNameText = CleanEvidenceText(result.Navigation.MapNameText),
                CoordinateText = CleanEvidenceText(result.Navigation.CoordinateText),
                result.Navigation.X,
                result.Navigation.Y,
                MapNameSource = CleanEvidenceText(result.Navigation.MapNameSource),
                result.Navigation.MapNameConfidencePercent,
                CoordinateSource = CleanEvidenceText(result.Navigation.CoordinateSource),
                result.Navigation.CoordinateConfidencePercent,
                result.Navigation.HasMap,
                result.Navigation.HasCoordinate
            }
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Mode={(commit ? "commit" : "preview")}, profile={profileName}, loaded={profileLoaded}, dictionaries={dictionaryLoad.LoadedGlyphs}, kind={kind}, label={label}");
    Console.WriteLine($"Window={(window is null ? "-" : $"{window.Pid}/{window.Bitness}/{window.ClientSizeText}")}");
    Console.WriteLine($"Success={result.Success}");
    Console.WriteLine($"Message={result.Message}");
    if (result.Point is not null)
        Console.WriteLine($"Point={result.Point.MapName} {result.Point.X},{result.Point.Y} [{result.Point.Kind}] label={result.Point.Label}");
    if (result.Navigation is not null)
        Console.WriteLine($"Navigation=map={result.Navigation.MapNameText} coord={result.Navigation.CoordinateText}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = result.Success && (!commit || File.Exists(evidencePath));
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReturnPrepareCurrentDiagnostics(string[] args)
{
    Console.WriteLine("Return point current-position preparation diagnostics");

    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(requestedProfile))
    {
        Console.Error.WriteLine("FAIL: 必须指定 --profile，避免把当前点写入非预期方案。");
        return false;
    }

    var profileName = requestedProfile.Trim();
    var kind = ReadReturnCaptureKindOption(args, "--kind", ReturnPointKind.FixedFarm);
    var label = ReadOption(args, "--label") ?? "当前挂机点";
    var offset = ReadOffsetOption(args, "--offset", (20, 0));
    var durationMs = Math.Clamp(ReadIntOption(args, "--duration-ms", 20000), 3000, 120000);
    var prepareHotkeysText = ReadOption(args, "--prepare-hotkeys") ?? "M,Tab";
    var prepareDelayMs = Math.Clamp(ReadIntOption(args, "--prepare-delay-ms", 500), 20, 5000);
    var prepareYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var window = TryBindFirstGameWindow(provider);
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var profileLoaded = returnPoints.Load(profileName);
    if (!profileLoaded)
    {
        Console.Error.WriteLine($"FAIL: 指定方案无法加载：{profileName}");
        return false;
    }

    var capture = provider.GetRequiredService<IReturnPointCaptureService>();
    var preview = capture.PreviewCurrentPoint();
    var readiness = provider.GetRequiredService<IReturnPointReadinessService>().Inspect(includeLiveRecognition: true);

    var currentMap = preview.Point?.MapName ?? readiness.MapName;
    var currentX = preview.Point?.X ?? readiness.X;
    var currentY = preview.Point?.Y ?? readiness.Y;
    var hasCurrentPoint = preview.Success
                          && !string.IsNullOrWhiteSpace(currentMap)
                          && currentX is not null
                          && currentY is not null;

    var returnTargetX = hasCurrentPoint ? Math.Max(0, currentX!.Value) : -1;
    var returnTargetY = hasCurrentPoint ? Math.Max(0, currentY!.Value) : -1;
    var suggestedStartX = hasCurrentPoint ? Math.Max(0, currentX!.Value + offset.X) : -1;
    var suggestedStartY = hasCurrentPoint ? Math.Max(0, currentY!.Value + offset.Y) : -1;

    var dotnet = "& 'C:\\Program Files\\dotnet\\dotnet.exe'";
    var project = "'.\\tools\\TlbbAgent.Diagnostics\\TlbbAgent.Diagnostics.csproj'";
    var profileArg = QuotePowerShellArg(profileName);
    var labelArg = QuotePowerShellArg(label);
    var mapArg = QuotePowerShellArg(currentMap ?? "");
    var prepareArg = QuotePowerShellArg(prepareHotkeysText);
    var kindArg = ReturnCaptureKindText(kind);
    var slotArg = ReturnNavigationSlotText(ReturnSlotForPointKind(kind));
    var targetText = $"{returnTargetX},{returnTargetY}";
    var suggestedStartText = $"{suggestedStartX},{suggestedStartY}";

    var captureCommand = hasCurrentPoint
        ? $"{dotnet} run --no-build --project {project} -- return-capture-current --profile {profileArg} --kind {kindArg} --label {labelArg} --commit"
        : "";
    var recordPlanCommand = hasCurrentPoint
        ? $"{dotnet} run --no-build --project {project} -- live-return-record-plan --profile {profileArg} --map {mapArg} --target {targetText} --duration-ms {durationMs} --prepare-hotkeys {prepareArg} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs}"
        : "";
    var recordCommand = hasCurrentPoint
        ? $"{dotnet} run --no-build --project {project} -- live-navigation-record --map {mapArg} --target {targetText} --duration-ms {durationMs} --prepare-hotkeys {prepareArg} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs} --execute-prepare"
        : "";
    var workflowCommand = hasCurrentPoint
        ? $"{dotnet} run --no-build --project {project} -- live-return-record-workflow --profile {profileArg} --map {mapArg} --target {targetText} --duration-ms {durationMs} --prepare-hotkeys {prepareArg} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs} --execute-prepare --force --label {labelArg}"
        : "";
    var importCommand = hasCurrentPoint
        ? $"{dotnet} run --no-build --project {project} -- return-navigation-import-record --profile {profileArg} --map {mapArg} --slot {slotArg} --latest --pre-hotkeys {prepareArg} --pre-delay-ms {prepareDelayMs} --force --add-point --confirm-map --label {labelArg}"
        : "";
    var readinessCommand = $"{dotnet} run --no-build --project {project} -- return-readiness --profile {profileArg}";
    var executeCheckCommand = $"{dotnet} run --no-build --project {project} -- live-return-point-execute --profile {profileArg} --verify-ms 10000";
    var executeCommand = $"{dotnet} run --no-build --project {project} -- live-return-point-execute --profile {profileArg} --execute --verify-ms 10000";

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-prepare-current", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-prepare-current-{(window?.Pid.ToString() ?? "no-window")}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-prepare-current-readonly-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesConfig = false,
            writesMemory = false,
            patchesClient = false,
            generatedCommandsOnly = true
        },
        profileName,
        profileLoaded,
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs
        },
        window = window is null ? null : new
        {
            window.Pid,
            Title = CleanEvidenceText(window.Title),
            bitness = window.Bitness.ToString(),
            window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        preview = new
        {
            preview.Success,
            MessageUtf8Base64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(preview.Message ?? "")),
            point = preview.Point is null ? null : new
            {
                MapName = CleanEvidenceText(preview.Point.MapName),
                preview.Point.X,
                preview.Point.Y,
                Kind = preview.Point.Kind.ToString(),
                Label = CleanEvidenceText(preview.Point.Label)
            },
            navigation = preview.Navigation is null ? null : new
            {
                MapNameText = CleanEvidenceText(preview.Navigation.MapNameText),
                CoordinateText = CleanEvidenceText(preview.Navigation.CoordinateText),
                preview.Navigation.X,
                preview.Navigation.Y,
                preview.Navigation.MapNameConfidencePercent,
                preview.Navigation.CoordinateConfidencePercent
            }
        },
        readiness = new
        {
            readiness.Level,
            SummaryUtf8Base64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(readiness.Summary ?? "")),
            NextActionUtf8Base64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(readiness.NextAction ?? "")),
            readiness.SceneSummary
        },
        returnTarget = hasCurrentPoint ? new { X = returnTargetX, Y = returnTargetY } : null,
        suggestedRecordingStart = hasCurrentPoint ? new { X = suggestedStartX, Y = suggestedStartY, offset } : null,
        commands = new
        {
            captureCommand,
            recordPlanCommand,
            recordCommand,
            workflowCommand,
            importCommand,
            readinessCommand,
            executeCheckCommand,
            executeCommand
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}, loaded={profileLoaded}, dictionaries={dictionaryLoad.LoadedGlyphs}");
    Console.WriteLine($"Window={(window is null ? "-" : $"{window.Pid}/{window.Bitness}/{window.ClientSizeText}")}");
    Console.WriteLine($"Preview={preview.Success}, message={preview.Message}");
    if (hasCurrentPoint)
    {
        Console.WriteLine($"Current={currentMap} {currentX},{currentY}");
        Console.WriteLine($"ReturnTarget={targetText}");
        Console.WriteLine($"SuggestedRecordingStart={suggestedStartText}, offset={offset.X},{offset.Y}");
        Console.WriteLine("Step0 commit current point:");
        Console.WriteLine(captureCommand);
        Console.WriteLine("Step1 move away manually before recording:");
        Console.WriteLine($"Move near {suggestedStartText}, then record back to {targetText}.");
        Console.WriteLine("Step2 generate record plan:");
        Console.WriteLine(recordPlanCommand);
        Console.WriteLine("Step3 one-command workflow:");
        Console.WriteLine(workflowCommand);
        Console.WriteLine("Step3b record manual navigation:");
        Console.WriteLine(recordCommand);
        Console.WriteLine("Step4 import latest record:");
        Console.WriteLine(importCommand);
    }

    Console.WriteLine("Step5 readiness:");
    Console.WriteLine(readinessCommand);
    Console.WriteLine("Step6 dry-run execute gate:");
    Console.WriteLine(executeCheckCommand);
    Console.WriteLine("Step7 real execute after gates pass:");
    Console.WriteLine(executeCommand);
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = profileLoaded && preview.Success && File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunReturnPrepareSavedPointDiagnostics(string[] args)
{
    Console.WriteLine("Return saved-point recording preparation diagnostics");

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(profileName))
    {
        Console.Error.WriteLine("FAIL: 必须指定 --profile。");
        return false;
    }

    profileName = profileName.Trim();
    var kind = ReadReturnCaptureKindOption(args, "--kind", ReturnPointKind.FixedFarm);
    var requestedSlot = ReturnSlotForPointKind(kind);
    var labelFilter = ReadOption(args, "--label") ?? "";
    var explicitTarget = ReadOffsetOption(args, "--target", (-1, -1));
    var hasExplicitTarget = explicitTarget.X >= 0 && explicitTarget.Y >= 0;
    var requestedMap = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var durationMs = Math.Clamp(ReadIntOption(args, "--duration-ms", 20000), 3000, 120000);
    var prepareHotkeysText = ReadOption(args, "--prepare-hotkeys") ?? "M,Tab";
    var prepareDelayMs = Math.Clamp(ReadIntOption(args, "--prepare-delay-ms", 500), 20, 5000);
    var prepareYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var window = TryBindFirstGameWindow(provider);
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var profileLoaded = returnPoints.Load(profileName);
    if (!profileLoaded)
    {
        Console.Error.WriteLine($"FAIL: 指定方案无法加载：{profileName}");
        return false;
    }

    NavigationRecognitionResult? scene = null;
    if (window is not null)
    {
        try
        {
            scene = provider.GetRequiredService<ISceneStateService>().Recognize(window, returnPoints.Current.NavigationRecognition);
        }
        catch
        {
            scene = null;
        }
    }

    var sceneMap = NormalizeDiagnosticMapName(scene?.MapNameText ?? "");
    var effectiveMap = !string.IsNullOrWhiteSpace(requestedMap)
        ? requestedMap
        : sceneMap;

    var candidates = returnPoints.Current.Points
        .Where(p => string.IsNullOrWhiteSpace(effectiveMap) || IsDiagnosticSameMap(p.MapName, effectiveMap))
        .ToArray();

    if (hasExplicitTarget)
        candidates = candidates
            .Where(p => p.X == explicitTarget.X && p.Y == explicitTarget.Y)
            .ToArray();

    if (!string.IsNullOrWhiteSpace(labelFilter))
        candidates = candidates
            .Where(p => p.Label.Contains(labelFilter, StringComparison.OrdinalIgnoreCase))
            .ToArray();

    var preferredCandidates = candidates
        .Where(p => IsPreferredPointForRequestedReturnKind(p.Kind, kind))
        .ToArray();
    if (preferredCandidates.Length > 0)
        candidates = preferredCandidates;

    ReturnPoint? selected = null;
    if (scene?.HasCoordinate == true)
    {
        var sceneX = scene.X!.Value;
        var sceneY = scene.Y!.Value;
        selected = candidates
            .OrderBy(p => Distance(sceneX, sceneY, p.X, p.Y))
            .FirstOrDefault();
    }
    selected ??= candidates.FirstOrDefault();

    if (selected is null)
    {
        Console.Error.WriteLine($"FAIL: 当前方案没有匹配的已保存回点。profile={profileName}, requestedKind={kind}, slot={requestedSlot}, map={effectiveMap}, label={labelFilter}, target={(hasExplicitTarget ? $"{explicitTarget.X},{explicitTarget.Y}" : "-")}");
        return false;
    }

    var distanceToSelected = scene?.HasCoordinate == true
        ? Distance(scene.X!.Value, scene.Y!.Value, selected.X, selected.Y)
        : (double?)null;
    var slotArg = ReturnNavigationSlotText(requestedSlot);
    var mapArg = QuotePowerShellArg(selected.MapName);
    var profileArg = QuotePowerShellArg(profileName);
    var labelArg = QuotePowerShellArg(string.IsNullOrWhiteSpace(selected.Label) ? "已保存回点" : selected.Label);
    var prepareArg = QuotePowerShellArg(prepareHotkeysText);
    var targetText = $"{selected.X},{selected.Y}";
    var dotnet = "& 'C:\\Program Files\\dotnet\\dotnet.exe'";
    var project = "'.\\tools\\TlbbAgent.Diagnostics\\TlbbAgent.Diagnostics.csproj'";
    var workflowCommand =
        $"{dotnet} run --no-build --project {project} -- live-return-record-workflow --profile {profileArg} --map {mapArg} --target {targetText} --slot {slotArg} --duration-ms {durationMs} --prepare-hotkeys {prepareArg} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs} --execute-prepare --force --label {labelArg}";
    var recordCommand =
        $"{dotnet} run --no-build --project {project} -- live-navigation-record --map {mapArg} --target {targetText} --duration-ms {durationMs} --prepare-hotkeys {prepareArg} --prepare-delay-ms {prepareDelayMs} --yield-ms {prepareYieldMs} --execute-prepare";
    var readinessCommand =
        $"{dotnet} run --no-build --project {project} -- return-readiness --profile {profileArg}";

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-prepare-saved-point", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-prepare-saved-point-{(window?.Pid.ToString() ?? "no-window")}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-prepare-saved-point-readonly-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesConfig = false,
            writesMemory = false,
            patchesClient = false,
            generatedCommandsOnly = true
        },
        profileName,
        profileLoaded,
        requestedKind = kind.ToString(),
        requestedSlot = requestedSlot.ToString(),
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs
        },
        window = window is null ? null : new
        {
            window.Pid,
            Title = CleanEvidenceText(window.Title),
            bitness = window.Bitness.ToString(),
            window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        scene = scene is null ? null : new
        {
            MapName = CleanEvidenceText(scene.MapNameText),
            scene.X,
            scene.Y,
            scene.MapNameConfidencePercent,
            scene.CoordinateConfidencePercent,
            scene.MapNameSource,
            scene.CoordinateSource
        },
        selected = new
        {
            selected.Id,
            MapName = CleanEvidenceText(selected.MapName),
            selected.X,
            selected.Y,
            Label = CleanEvidenceText(selected.Label),
            Kind = selected.Kind.ToString(),
            distanceToSelected
        },
        commands = new
        {
            workflowCommand,
            recordCommand,
            readinessCommand
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}, loaded={profileLoaded}, dictionaries={dictionaryLoad.LoadedGlyphs}");
    Console.WriteLine($"Window={(window is null ? "-" : $"{window.Pid}/{window.Bitness}/{window.ClientSizeText}")}");
    Console.WriteLine($"Scene={(scene is null ? "-" : $"{scene.MapNameText} {scene.X},{scene.Y}")}");
    Console.WriteLine($"RequestedSlot={requestedSlot}, requestedKind={kind}");
    Console.WriteLine($"SavedReturnTarget={selected.MapName} {selected.X},{selected.Y}, kind={selected.Kind}, label={selected.Label}, distance={(distanceToSelected is null ? "-" : distanceToSelected.Value.ToString("0.0", CultureInfo.InvariantCulture))}");
    if (distanceToSelected is not null && distanceToSelected.Value <= returnPoints.Current.ArrivalDistance)
        Console.WriteLine($"Gate: 当前距离 {distanceToSelected.Value:0.0} 在到达范围 {returnPoints.Current.ArrivalDistance} 内；请先手动离开回点，再录制回到该点。");
    Console.WriteLine("Step1 one-command workflow after moving away:");
    Console.WriteLine(workflowCommand);
    Console.WriteLine("Step1b manual record only:");
    Console.WriteLine(recordCommand);
    Console.WriteLine("Step2 readiness:");
    Console.WriteLine(readinessCommand);
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine("PASS");
    return true;
}

static bool RunLiveReturnNavigationReadinessDiagnostics(string[] args)
{
    Console.WriteLine("Live return-navigation readiness diagnostics");

    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var slotText = ReadOption(args, "--slot") ?? "fixed";
    var slot = ReturnNavigationRecordImportService.ParseSlot(slotText);

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var window = TryBindFirstGameWindow(provider);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口，无法做实时回点门禁检查。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = appProfiles.ListProfileNames().FirstOrDefault();

    AppProfileLoadResult? loadResult = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        loadResult = appProfiles.LoadAll(profileName);

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var (slotName, slotEnabled, navigationConfig) = SelectReadinessNavigationSlot(config, slot);
    var profileLoadedReturnPoints = loadResult?.LoadedModules.Contains("返点配置", StringComparer.Ordinal) == true;

    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var deathRecognition = provider.GetRequiredService<IDeathRecognitionService>();
    var navigation = sceneState.Recognize(window, config.NavigationRecognition);
    var death = deathRecognition.Recognize(window, config.DeathRecognition);
    var target = ResolveReadinessTargetPoint(config, slot, navigation);
    var distance = target is null || !navigation.HasCoordinate
        ? (double?)null
        : Distance(navigation.X!.Value, navigation.Y!.Value, target.X, target.Y);
    var inRange = distance is not null && distance.Value <= config.ArrivalDistance;

    var slotCheck = CheckReturnNavigationSlot(
        slotName,
        slot,
        slotEnabled,
        navigationConfig,
        (window.ClientWidth, window.ClientHeight));

    var blockedReasons = new List<string>();
    var warnings = new List<string>();

    if (window.Bitness != ClientBitness.X86)
        blockedReasons.Add("绑定窗口不是 32 位客户端。");
    if (!window.IsAutomationAllowed)
        blockedReasons.Add(window.AutomationBlockReason);
    if (string.IsNullOrWhiteSpace(profileName))
        blockedReasons.Add("未找到可加载的配置方案。");
    if (loadResult is null)
        blockedReasons.Add("未加载完整方案。");
    else if (!profileLoadedReturnPoints)
        blockedReasons.Add("方案中未加载到返点配置。");
    if (!slotEnabled)
        blockedReasons.Add($"{slotName}未启用。");
    if (navigationConfig.Mode == ReturnNavigationMode.Disabled)
        blockedReasons.Add($"{slotName}导航动作关闭。");
    if (navigationConfig.Mode == ReturnNavigationMode.RecordedClientClickSequence)
    {
        var syntheticSource = FindSyntheticRecordedSourceForDiagnostics(navigationConfig);
        if (!string.IsNullOrWhiteSpace(syntheticSource))
            blockedReasons.Add($"录制样本来自合成/Smoke 证据，只能用于回归测试，禁止真实执行：{syntheticSource}");
    }

    foreach (var reason in slotCheck.Reasons)
        if (!reason.StartsWith("录制序列来自合成/Smoke", StringComparison.Ordinal)
            && !blockedReasons.Contains(reason, StringComparer.Ordinal))
            blockedReasons.Add(reason);
    foreach (var problem in slotCheck.CoordinateProblems)
        blockedReasons.Add(problem);
    foreach (var missing in slotCheck.MissingEvidencePaths)
        blockedReasons.Add($"来源证据缺失：{missing}");

    if (!navigation.HasMap)
        blockedReasons.Add("当前地图未识别，禁止真实回点。");
    if (!navigation.HasCoordinate)
        blockedReasons.Add("当前坐标未识别，禁止真实回点。");
    if (target is null)
    {
        blockedReasons.Add(slot == ReturnNavigationSlot.DeathReturn
            ? "没有可用的死亡回点目标。"
            : "当前地图没有同地图回点目标。");
    }
    else
    {
        if (navigation.HasMap && !MapsMatchForReadiness(navigation.MapNameText, target.MapName))
            blockedReasons.Add($"当前地图 {navigation.MapNameText} 与目标地图 {target.MapName} 不一致。");

        if (navigationConfig.Mode == ReturnNavigationMode.RecordedClientClickSequence)
        {
            var recordedDestinationGate = CheckRecordedDestinationForReadiness(navigationConfig, target);
            foreach (var reason in recordedDestinationGate)
                blockedReasons.Add(reason);

            if (!string.IsNullOrWhiteSpace(navigationConfig.RecordedSourceClientSize)
                && !string.Equals(navigationConfig.RecordedSourceClientSize.Trim(), window.ClientSizeText, StringComparison.OrdinalIgnoreCase))
            {
                blockedReasons.Add($"录制来源客户区 {navigationConfig.RecordedSourceClientSize} 与当前客户区 {window.ClientSizeText} 不一致。");
            }

            if (string.IsNullOrWhiteSpace(navigationConfig.RecordedSourceEvidencePath))
                warnings.Add("录制序列缺少总来源证据路径；不影响执行，但不利于追溯。");
        }
    }

    if (inRange)
        warnings.Add($"当前位置已经在到达距离内：{distance:0.0} <= {config.ArrivalDistance}，不需要执行回点动作。");
    if (death.IsDead && slot != ReturnNavigationSlot.DeathReturn)
        warnings.Add($"检测到死亡关键词：{death.MatchedKeyword}；当前检查槽位不是死亡回点。");

    var readyToExecute = !inRange && blockedReasons.Count == 0;
    var state = inRange
        ? "InRange"
        : readyToExecute
            ? "ReadyToExecute"
            : "Blocked";

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-navigation-readiness", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"return-navigation-readiness-{window.Pid}.json");
    var clientSaved = SaveCapturePng(client, clientPath);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "live-return-navigation-readiness-readonly-no-input",
        safety = new
        {
            sendsToRealGameWindow = false,
            readyToExecute,
            inRange,
            state,
            blockedReasons,
            warnings
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = loadResult is not null,
            profileLoadedReturnPoints,
            loadedModules = loadResult?.LoadedModules,
            missingModules = loadResult?.MissingModules
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        slot = new
        {
            slot,
            slotName,
            enabled = slotEnabled,
            navigationConfig.Mode,
            navigationConfig.DispatchMode,
            navigationConfig.Hotkey,
            navigationConfig.ClickX,
            navigationConfig.ClickY,
            recordedClickCount = navigationConfig.RecordedClicks.Count,
            recordedPreHotkeyCount = navigationConfig.RecordedPreHotkeys.Count,
            navigationConfig.RecordedSourceClientSize,
            navigationConfig.RecordedSourceEvidencePath,
            navigationConfig.RecordedAfterMap,
            navigationConfig.RecordedAfterX,
            navigationConfig.RecordedAfterY,
            navigationConfig.RecordedTargetX,
            navigationConfig.RecordedTargetY,
            navigationConfig.RecordedMovedCloserToTarget,
            navigationConfig.RecordedArrivedAtTarget,
            slotCheck
        },
        scene = new
        {
            navigation.MapNameText,
            navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y,
            navigation.HasMap,
            navigation.HasCoordinate,
            death = new
            {
                death.IsDead,
                death.MatchedKeyword,
                death.Text
            }
        },
        target = target is null ? null : new
        {
            target.MapName,
            target.X,
            target.Y,
            target.Label,
            kind = target.Kind.ToString(),
            distance,
            config.ArrivalDistance
        },
        capture = new
        {
            client = new
            {
                path = clientPath,
                saved = clientSaved,
                visual = HasVisualContent(client),
                width = client?.Width ?? 0,
                height = client?.Height ?? 0
            }
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}, size={window.ClientSizeText}, bitness={window.Bitness}, profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}");
    Console.WriteLine($"Slot={slotName}, enabled={slotEnabled}, mode={navigationConfig.Mode}, state={state}, readyToExecute={readyToExecute}, inRange={inRange}");
    Console.WriteLine($"Scene map='{navigation.MapNameText}', coord='{navigation.CoordinateText}', parsed={navigation.X},{navigation.Y}, death={death.IsDead}");
    Console.WriteLine(target is null
        ? "Target=-"
        : $"Target={target.MapName}({target.X},{target.Y}), kind={target.Kind}, distance={distance:0.0}, arrival={config.ArrivalDistance}");
    foreach (var warning in warnings)
        Console.WriteLine($"WARN: {warning}");
    foreach (var reason in blockedReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"ClientCapture={clientPath}, saved={clientSaved}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && clientSaved
             && (readyToExecute || inRange);
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static (string SlotName, bool Enabled, ReturnNavigationConfig Navigation) SelectReadinessNavigationSlot(
    ReturnPointConfig config,
    ReturnNavigationSlot slot) => slot switch
{
    ReturnNavigationSlot.EarthSpirit => ("土灵回点", config.EnableEarthSpiritReturn, config.EarthSpiritNavigation),
    ReturnNavigationSlot.StuckRecovery => ("卡点恢复", config.EnableStuckRecovery, config.StuckRecoveryNavigation),
    ReturnNavigationSlot.DeathReturn => ("死亡回点", config.EnableDeathReturn, config.DeathReturnNavigation),
    _ => ("挂机回点", config.EnableFixedFarmReturn, config.ReturnNavigation)
};

static ReturnPoint? ResolveReadinessTargetPoint(
    ReturnPointConfig config,
    ReturnNavigationSlot slot,
    NavigationRecognitionResult navigation)
{
    if (slot == ReturnNavigationSlot.DeathReturn)
    {
        var deathPoint = config.Points.FirstOrDefault(p => p.Kind == ReturnPointKind.DeathReturn);
        if (deathPoint is not null)
            return deathPoint;
    }

    if (slot == ReturnNavigationSlot.EarthSpirit)
    {
        var earthPoint = config.Points.FirstOrDefault(p =>
            p.Kind == ReturnPointKind.EarthSpirit
            && (!HasReliableRuntimeMap(navigation) || MapsMatchForReadiness(p.MapName, navigation.MapNameText)));
        if (earthPoint is not null)
            return earthPoint;
    }

    if (slot == ReturnNavigationSlot.StuckRecovery)
    {
        var recoveryPoint = config.Points.FirstOrDefault(p =>
            p.Kind == ReturnPointKind.Recovery
            && (!HasReliableRuntimeMap(navigation) || MapsMatchForReadiness(p.MapName, navigation.MapNameText)));
        if (recoveryPoint is not null)
            return recoveryPoint;
    }

    return FindNearestReturnPoint(config, navigation)
           ?? config.Points.FirstOrDefault(p => HasReliableRuntimeMap(navigation) && MapsMatchForReadiness(p.MapName, navigation.MapNameText));
}

static IReadOnlyList<string> CheckRecordedDestinationForReadiness(ReturnNavigationConfig nav, ReturnPoint target)
{
    var reasons = new List<string>();
    if (!string.IsNullOrWhiteSpace(nav.RecordedAfterMap)
        && !MapsMatchForReadiness(nav.RecordedAfterMap, target.MapName))
        reasons.Add($"录制终点地图 {nav.RecordedAfterMap} 与目标地图 {target.MapName} 不一致。");

    var recordedX = nav.RecordedAfterX ?? nav.RecordedTargetX;
    var recordedY = nav.RecordedAfterY ?? nav.RecordedTargetY;
    if (recordedX is null || recordedY is null)
    {
        reasons.Add("录制序列缺少终点/目标坐标。");
        return reasons;
    }

    var distance = Distance(target.X, target.Y, recordedX.Value, recordedY.Value);
    if (distance > 8)
        reasons.Add($"录制终点 {recordedX},{recordedY} 与当前目标 {target.X},{target.Y} 偏差 {distance:0.0}，拒绝复放。");

    return reasons;
}

static string FindSyntheticRecordedSourceForDiagnostics(ReturnNavigationConfig nav)
{
    var candidates = nav.RecordedPreHotkeys
        .Select(h => h.SourceEvidencePath)
        .Concat(nav.RecordedClicks.Select(c => c.SourceEvidencePath))
        .Prepend(nav.RecordedSourceEvidencePath);

    return candidates.FirstOrDefault(IsSyntheticRecordedSourceForDiagnostics) ?? "";
}

static bool IsSyntheticRecordedSourceForDiagnostics(string? path)
{
    if (string.IsNullOrWhiteSpace(path))
        return false;

    var value = path.Replace('\\', '/').ToLowerInvariant();
    return value.Contains("synthetic", StringComparison.Ordinal)
           || value.Contains("smoke", StringComparison.Ordinal)
           || value.Contains("navigation-record-synthetic", StringComparison.Ordinal);
}

static bool MapsMatchForReadiness(string left, string right)
{
    var normalizedLeft = NormalizeMapNameForReadiness(left);
    var normalizedRight = NormalizeMapNameForReadiness(right);
    if (string.IsNullOrWhiteSpace(normalizedLeft) || string.IsNullOrWhiteSpace(normalizedRight))
        return false;

    return string.Equals(normalizedLeft, normalizedRight, StringComparison.Ordinal)
           || normalizedLeft.Contains(normalizedRight, StringComparison.Ordinal)
           || normalizedRight.Contains(normalizedLeft, StringComparison.Ordinal);
}

static string NormalizeMapNameForReadiness(string value)
{
    var chars = (value ?? string.Empty)
        .Trim()
        .Where(c => c is >= '\u4E00' and <= '\u9FFF' || char.IsLetterOrDigit(c))
        .ToArray();
    return chars.Length == 0 ? string.Empty : new string(chars);
}

static ReturnNavigationSlotCheck CheckReturnNavigationSlot(
    string slotName,
    ReturnNavigationSlot slot,
    bool enabled,
    ReturnNavigationConfig nav,
    (int Width, int Height)? explicitClientSize)
{
    var reasons = new List<string>();
    var sourceSizes = new List<string>();
    var sourceEvidenceMissing = new List<string>();
    var coordinateProblems = new List<string>();
    var runnable = !enabled || nav.Mode != ReturnNavigationMode.Disabled;

    if (!enabled)
    {
        reasons.Add("槽位未启用。");
        return new ReturnNavigationSlotCheck(slot, slotName, enabled, nav.Mode.ToString(), 0, runnable, reasons, sourceSizes, sourceEvidenceMissing, coordinateProblems);
    }

    if (nav.Mode == ReturnNavigationMode.Disabled)
    {
        reasons.Add("槽位已启用，但导航动作关闭。");
        runnable = false;
    }

    if (RequiresHotkeyForCheck(nav.Mode) && string.IsNullOrWhiteSpace(nav.Hotkey))
    {
        reasons.Add("导航模式需要热键，但热键为空。");
        runnable = false;
    }

    if (RequiresClickForCheck(nav.Mode) && (nav.ClickX < 0 || nav.ClickY < 0))
    {
        reasons.Add($"点击坐标无效：{nav.ClickX},{nav.ClickY}。");
        runnable = false;
    }

    if (nav.Mode == ReturnNavigationMode.RecordedClientClickSequence)
    {
        if (!nav.RecordedMovedCloserToTarget && !nav.RecordedArrivedAtTarget)
        {
            reasons.Add("录制序列缺少靠近/到达验证标记。");
            runnable = false;
        }

        var syntheticSource = FindSyntheticRecordedSourceForDiagnostics(nav);
        if (!string.IsNullOrWhiteSpace(syntheticSource))
        {
            reasons.Add($"录制序列来自合成/Smoke 证据，只能用于诊断回归，不能真实执行：{syntheticSource}");
            runnable = false;
        }

        if (string.IsNullOrWhiteSpace(nav.RecordedSourceClientSize))
        {
            reasons.Add("录制序列缺少来源客户区尺寸。");
            runnable = false;
        }
        else
        {
            if (!sourceSizes.Contains(nav.RecordedSourceClientSize, StringComparer.Ordinal))
                sourceSizes.Add(nav.RecordedSourceClientSize);

            if (explicitClientSize is not null
                && TryParseClientSize(nav.RecordedSourceClientSize, out var recordedWidth, out var recordedHeight)
                && (recordedWidth != explicitClientSize.Value.Width || recordedHeight != explicitClientSize.Value.Height))
            {
                reasons.Add($"录制来源客户区 {recordedWidth}x{recordedHeight} 与指定客户区 {explicitClientSize.Value.Width}x{explicitClientSize.Value.Height} 不一致。");
                runnable = false;
            }
        }

        if (nav.RecordedAfterX is null && nav.RecordedTargetX is null
            || nav.RecordedAfterY is null && nav.RecordedTargetY is null)
        {
            reasons.Add("录制序列缺少终点/目标坐标。");
            runnable = false;
        }

        if (!string.IsNullOrWhiteSpace(nav.RecordedSourceEvidencePath) && !File.Exists(nav.RecordedSourceEvidencePath))
        {
            sourceEvidenceMissing.Add(nav.RecordedSourceEvidencePath);
            runnable = false;
        }

        for (var i = 0; i < nav.RecordedPreHotkeys.Count; i++)
        {
            var hotkey = nav.RecordedPreHotkeys[i];
            if (string.IsNullOrWhiteSpace(hotkey.Hotkey))
            {
                reasons.Add($"前置热键第 {i + 1} 步为空。");
                runnable = false;
            }

            if (hotkey.DelayAfterMs < 0)
            {
                reasons.Add($"前置热键第 {i + 1} 步延迟为负数：{hotkey.DelayAfterMs}。");
                runnable = false;
            }

            if (!string.IsNullOrWhiteSpace(hotkey.SourceEvidencePath) && !File.Exists(hotkey.SourceEvidencePath))
            {
                sourceEvidenceMissing.Add(hotkey.SourceEvidencePath);
                runnable = false;
            }
        }

        if (nav.RecordedClicks.Count == 0)
        {
            reasons.Add("录制序列为空。");
            runnable = false;
        }

        for (var i = 0; i < nav.RecordedClicks.Count; i++)
        {
            var click = nav.RecordedClicks[i];
            if (click.ClientX < 0 || click.ClientY < 0)
            {
                coordinateProblems.Add($"第 {i + 1} 步客户区坐标为负数：{click.ClientX},{click.ClientY}。");
                runnable = false;
            }

            if (click.DelayAfterMs < 0)
            {
                reasons.Add($"第 {i + 1} 步延迟为负数：{click.DelayAfterMs}。");
                runnable = false;
            }

            if (!string.IsNullOrWhiteSpace(click.SourceEvidencePath))
            {
                if (!File.Exists(click.SourceEvidencePath))
                {
                    sourceEvidenceMissing.Add(click.SourceEvidencePath);
                    runnable = false;
                }
                else if (TryReadNavigationRecordClientSize(click.SourceEvidencePath, out var sourceWidth, out var sourceHeight))
                {
                    var sizeText = $"{sourceWidth}x{sourceHeight}";
                    if (!sourceSizes.Contains(sizeText, StringComparer.Ordinal))
                        sourceSizes.Add(sizeText);
                    if (click.ClientX >= sourceWidth || click.ClientY >= sourceHeight)
                    {
                        coordinateProblems.Add($"第 {i + 1} 步超出来源客户区 {sizeText}：{click.ClientX},{click.ClientY}。");
                        runnable = false;
                    }
                }
            }

            if (explicitClientSize is not null
                && (click.ClientX >= explicitClientSize.Value.Width || click.ClientY >= explicitClientSize.Value.Height))
            {
                coordinateProblems.Add($"第 {i + 1} 步超出指定客户区 {explicitClientSize.Value.Width}x{explicitClientSize.Value.Height}：{click.ClientX},{click.ClientY}。");
                runnable = false;
            }
        }

        if (sourceEvidenceMissing.Count > 0)
            reasons.Add($"来源证据缺失 {sourceEvidenceMissing.Count} 个。");
        if (coordinateProblems.Count > 0)
            reasons.Add($"录制点击坐标存在问题 {coordinateProblems.Count} 个。");
    }

    return new ReturnNavigationSlotCheck(
        slot,
        slotName,
        enabled,
        nav.Mode.ToString(),
        nav.RecordedClicks.Count,
        runnable,
        reasons,
        sourceSizes,
        sourceEvidenceMissing.Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
        coordinateProblems);
}

static bool RequiresHotkeyForCheck(ReturnNavigationMode mode) =>
    mode is ReturnNavigationMode.HotkeyOnly
        or ReturnNavigationMode.HotkeyThenClickClientPoint
        or ReturnNavigationMode.HotkeyThenDirectionalClientClick;

static bool RequiresClickForCheck(ReturnNavigationMode mode) =>
    mode is ReturnNavigationMode.ClickClientPoint
        or ReturnNavigationMode.HotkeyThenClickClientPoint
        or ReturnNavigationMode.DirectionalClientClick
        or ReturnNavigationMode.HotkeyThenDirectionalClientClick;

static bool TryParseClientSize(string? value, out int width, out int height)
{
    width = 0;
    height = 0;
    if (string.IsNullOrWhiteSpace(value))
        return false;

    var parts = value.ToLowerInvariant()
        .Split(['x', '*', '×'], StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    return parts.Length == 2
           && int.TryParse(parts[0], out width)
           && int.TryParse(parts[1], out height)
           && width > 0
           && height > 0;
}

static bool TryReadNavigationRecordClientSize(string path, out int width, out int height)
{
    width = 0;
    height = 0;
    try
    {
        var root = JsonNode.Parse(File.ReadAllText(path, Encoding.UTF8))?.AsObject();
        var size = root?["window"]?.AsObject()?["clientSize"]?.GetValue<string>();
        return TryParseClientSize(size, out width, out height);
    }
    catch
    {
        return false;
    }
}

static string? FindLatestNavigationRecordEvidenceRaw()
{
    var root = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-navigation-record");
    if (!Directory.Exists(root))
        return null;

    return Directory.EnumerateFiles(root, "navigation-record-*.json", SearchOption.AllDirectories)
        .Select(path => new FileInfo(path))
        .OrderByDescending(file => file.LastWriteTimeUtc)
        .Select(file => file.FullName)
        .FirstOrDefault();
}

static NavigationReplayRecord LoadNavigationReplayRecord(string evidencePath, int maxClicks)
{
    var root = JsonNode.Parse(File.ReadAllText(evidencePath, Encoding.UTF8))?.AsObject()
        ?? throw new InvalidOperationException("invalid navigation record json");
    var window = root["window"]?.AsObject();
    var before = root["beforeNavigation"]?.AsObject();
    var after = root["afterNavigation"]?.AsObject();
    var events = root["events"]?.AsArray() ?? new JsonArray();
    var actions = new List<NavigationReplayAction>();

    foreach (var node in events)
    {
        if (actions.Count >= maxClicks)
            break;
        if (node is not JsonObject e)
            continue;

        var action = ReadJsonString(e, "Action");
        if (!string.Equals(action, "Down", StringComparison.OrdinalIgnoreCase))
            continue;

        var inClient = ReadJsonBool(e, "InClient");
        var clientX = ReadJsonInt(e, "ClientX");
        var clientY = ReadJsonInt(e, "ClientY");
        if (!inClient || clientX is null || clientY is null || clientX < 0 || clientY < 0)
            continue;

        var buttonText = ReadJsonString(e, "Button");
        var button = string.Equals(buttonText, "Right", StringComparison.OrdinalIgnoreCase)
            ? InputMouseButton.Right
            : InputMouseButton.Left;
        actions.Add(new NavigationReplayAction(
            ReadJsonLong(e, "ElapsedMs") ?? 0,
            button,
            clientX.Value,
            clientY.Value));
    }

    return new NavigationReplayRecord(
        ReadJsonString(window, "clientSize"),
        ReadJsonString(before, "MapNameText"),
        ReadJsonString(before, "CoordinateText"),
        ReadJsonInt(before, "X"),
        ReadJsonInt(before, "Y"),
        ReadJsonString(after, "MapNameText"),
        ReadJsonString(after, "CoordinateText"),
        ReadJsonInt(after, "X"),
        ReadJsonInt(after, "Y"),
        actions);
}

static string ReadJsonString(JsonObject? obj, string name) =>
    obj is not null && obj.TryGetPropertyValue(name, out var node) ? node?.GetValue<string>() ?? "" : "";

static int? ReadJsonInt(JsonObject? obj, string name) =>
    obj is not null && obj.TryGetPropertyValue(name, out var node) && node is not null && int.TryParse(node.ToString(), out var value)
        ? value
        : null;

static long? ReadJsonLong(JsonObject? obj, string name) =>
    obj is not null && obj.TryGetPropertyValue(name, out var node) && node is not null && long.TryParse(node.ToString(), out var value)
        ? value
        : null;

static bool ReadJsonBool(JsonObject? obj, string name) =>
    obj is not null && obj.TryGetPropertyValue(name, out var node) && node is not null && bool.TryParse(node.ToString(), out var value) && value;

static void AddMouseRecordEvent(
    List<NavigationRecordedMouseEvent> events,
    IWindowBindingService binding,
    ISceneStateService sceneState,
    BoundGameWindow window,
    long elapsedMs,
    string button,
    string action,
    bool hasCursor,
    MouseRecordNative.Point point)
{
    var screenX = hasCursor ? point.X : -1;
    var screenY = hasCursor ? point.Y : -1;
    var clientX = -1;
    var clientY = -1;
    var inClient = hasCursor && binding.TryScreenToClient(window, screenX, screenY, out clientX, out clientY, out _);
    if (!inClient)
    {
        clientX = -1;
        clientY = -1;
    }

    var nav = sceneState.Recognize(window, new NavigationRecognitionConfig());
    events.Add(new NavigationRecordedMouseEvent(
        elapsedMs,
        button,
        action,
        screenX,
        screenY,
        clientX,
        clientY,
        inClient,
        nav.MapNameText,
        nav.CoordinateText,
        nav.X,
        nav.Y,
        nav.MapNameConfidencePercent,
        nav.CoordinateConfidencePercent));
}

static bool IsMouseDown(int virtualKey) =>
    (MouseRecordNative.GetAsyncKeyState(virtualKey) & unchecked((short)0x8000)) != 0;

static bool RunLiveReturnPointExecuteDiagnostics(string[] args)
{
    Console.WriteLine("Live return-point controlled execute diagnostics");

    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var yieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 1200), 0, 10000);
    var ignoreYield = args.Any(a => a.Equals("--ignore-yield", StringComparison.OrdinalIgnoreCase));
    var expectYield = args.Any(a => a.Equals("--expect-yield", StringComparison.OrdinalIgnoreCase));

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();
    var log = provider.GetRequiredService<ILogService>();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    AppProfileLoadResult? loadResult = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        loadResult = appProfiles.LoadAll(profileName);

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var profileLoadedReturnPoints = loadResult?.LoadedModules.Contains("返点配置", StringComparer.Ordinal) == true;

    var preGateReasons = new List<string>();
    if (window.Bitness != ClientBitness.X86)
        preGateReasons.Add("绑定窗口不是 32 位客户端。");
    if (!window.IsAutomationAllowed)
        preGateReasons.Add(window.AutomationBlockReason);
    if (string.IsNullOrWhiteSpace(profileName))
        preGateReasons.Add("未指定方案，且没有可用的当前方案；真实执行必须显式加载方案。");
    if (loadResult is null)
        preGateReasons.Add("未加载完整方案。");
    else if (!profileLoadedReturnPoints)
        preGateReasons.Add("方案中未加载到返点配置。");
    if (!IsAnyReturnGateEnabled(config))
        preGateReasons.Add("返点、土灵、死亡返点和卡点恢复均未启用。");
    if (config.Points.Count == 0)
        preGateReasons.Add("未配置返点坐标。");
    if (string.IsNullOrWhiteSpace(config.NavigationRecognition.ConfirmedMapName))
        preGateReasons.Add("未确认当前地图；地图 OCR 不稳定时禁止真实回点。");
    if (!HasExecutableReturnAction(config))
        preGateReasons.Add("未配置可执行的回点/土灵/死亡/卡点动作。");
    var syntheticRecordedReturnSource = FindEnabledSyntheticRecordedReturnSource(config);
    if (!string.IsNullOrWhiteSpace(syntheticRecordedReturnSource))
        preGateReasons.Add($"启用的录制回点样本来自合成/Smoke 证据，只能用于回归测试，禁止真实执行：{syntheticRecordedReturnSource}");

    var realInput = provider.GetRequiredService<IInputService>();
    realInput.YieldToUserInput = yieldMs > 0;
    realInput.UserInputYieldMs = yieldMs;
    var yieldDispatch = ResolvePrimaryReturnNavigationDispatch(config);
    var executeYieldStatus = realInput.GetYieldStatus(window.Hwnd, yieldDispatch);
    if (executeRequested && executeYieldStatus.ShouldYield && !ignoreYield)
        preGateReasons.Add($"检测到近期人工操作，跳过真实回点输入：{executeYieldStatus.Reason}");
    if (executeRequested && expectYield && !executeYieldStatus.ShouldYield)
        preGateReasons.Add("本次为让控门禁测试：指定了 --expect-yield，但当前未触发人工让控；为避免误发真实输入，拒绝执行。");
    if (executeRequested && expectYield && executeYieldStatus.ShouldYield)
        preGateReasons.Add("本次为让控门禁测试：已检测到人工让控，按预期拒绝真实输入。");

    var allowedToExecute = executeRequested && preGateReasons.Count == 0;
    var executionReasons = preGateReasons.ToList();
    if (!executeRequested)
        executionReasons.Add("未提供 --execute，本次只做受控预演，不向游戏发送输入。");
    else if (executeYieldStatus.ShouldYield && ignoreYield)
        executionReasons.Add($"已显式忽略人工操作让控：{executeYieldStatus.Reason}");

    IInputService input = allowedToExecute
        ? new AuditedInputService(realInput)
        : new CountingInputService();
    var inputMode = allowedToExecute ? "real-audited" : "planned-counting";

    var runtime = new ReturnPointRuntimeService(
        returnPoints,
        provider.GetRequiredService<ISceneStateService>(),
        provider.GetRequiredService<IDeathRecognitionService>(),
        new ReturnNavigationService(input, log),
        log);

    var sceneState = provider.GetRequiredService<ISceneStateService>();
    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-return-point-execute", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var beforeClientPath = Path.Combine(evidenceDir, $"before-client-{window.Pid}.png");
    var afterClientPath = Path.Combine(evidenceDir, $"after-client-{window.Pid}.png");
    var actionOverlayPath = Path.Combine(evidenceDir, $"return-navigation-actions-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"return-point-execute-{window.Pid}.json");

    var beforeCapture = capture.CaptureClient(window.Hwnd);
    var beforeCaptureSaved = SaveCapturePng(beforeCapture, beforeClientPath);
    var beforeCaptureVisual = HasVisualContent(beforeCapture);
    var beforeNavigation = sceneState.Recognize(window, config.NavigationRecognition);
    var beforeNearest = beforeNavigation.HasCoordinate && HasReliableRuntimeMap(beforeNavigation) ? FindNearestReturnPoint(config, beforeNavigation) : null;
    var beforeDistance = beforeNearest is null || !beforeNavigation.HasCoordinate
        ? (double?)null
        : Distance(beforeNavigation.X!.Value, beforeNavigation.Y!.Value, beforeNearest.X, beforeNearest.Y);

    runtime.Reset();
    var result = EvaluateReturnPointRuntime(runtime, window, 3);
    var navigation = sceneState.Recognize(window, config.NavigationRecognition);
    var nearest = navigation.HasCoordinate && HasReliableRuntimeMap(navigation) ? FindNearestReturnPoint(config, navigation) : null;
    var distance = nearest is null || !navigation.HasCoordinate
        ? (double?)null
        : Distance(navigation.X!.Value, navigation.Y!.Value, nearest.X, nearest.Y);
    var actionMarkers = BuildReturnNavigationActionMarkers(window, navigation, nearest, config, result.Action);
    var actionOverlaySaved = beforeCapture is not null && SaveReturnNavigationActionsOverlayPng(beforeCapture, actionMarkers, actionOverlayPath);

    var inputAudit = BuildInputAudit(input);
    var verifyDelayMs = ReadIntOption(args, "--verify-ms", allowedToExecute ? 6000 : 0);
    NavigationRecognitionResult? afterNavigation = null;
    double? afterDistance = null;
    bool? arrivedAfterExecute = null;
    bool? movedCloserAfterExecute = null;
    string verificationMessage = "未执行真实输入，跳过后置坐标验证。";

    if (allowedToExecute && verifyDelayMs > 0 && nearest is not null)
    {
        Thread.Sleep(Math.Clamp(verifyDelayMs, 500, 30000));
        afterNavigation = sceneState.Recognize(window, config.NavigationRecognition);
        if (afterNavigation.HasCoordinate && HasReliableRuntimeMap(afterNavigation)
            && string.Equals(afterNavigation.MapNameText, nearest.MapName, StringComparison.Ordinal))
        {
            afterDistance = Distance(afterNavigation.X!.Value, afterNavigation.Y!.Value, nearest.X, nearest.Y);
            arrivedAfterExecute = afterDistance.Value <= config.ArrivalDistance;
            movedCloserAfterExecute = beforeDistance is not null && afterDistance.Value < beforeDistance.Value - 1.0;
            verificationMessage = arrivedAfterExecute.Value
                ? $"已到达返点范围：{afterDistance.Value:0.0} <= {config.ArrivalDistance}。"
                : movedCloserAfterExecute.Value
                    ? $"坐标已向返点移动：{beforeDistance:0.0} -> {afterDistance.Value:0.0}。"
                    : $"未验证到有效回点移动：{beforeDistance:0.0} -> {afterDistance.Value:0.0}。";
        }
        else
        {
            verificationMessage = "后置坐标或地图未识别，无法证明回点动作有效。";
        }
    }

    var afterCapture = capture.CaptureClient(window.Hwnd);
    var afterCaptureSaved = SaveCapturePng(afterCapture, afterClientPath);
    var afterCaptureVisual = HasVisualContent(afterCapture);
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "controlled-live-return-point-execute-gated",
        safety = new
        {
            executeRequested,
            allowedToExecute,
            sendsToRealGameWindow = allowedToExecute,
            plannedOnly = !allowedToExecute,
            inputMode,
            inputService = input.GetType().Name,
            blockedReasons = executionReasons,
            userInputYield = new
            {
                yieldMs,
                ignoreYield,
                expectYield,
                dispatch = yieldDispatch.ToString(),
                executeYieldStatus.Enabled,
                executeYieldStatus.CanReadLastInput,
                executeYieldStatus.ShouldYield,
                executeYieldStatus.LastInputAgeMs,
                executeYieldStatus.RemainingYieldMs,
                executeYieldStatus.OwnRecentAutomationInput,
                executeYieldStatus.TargetForeground,
                executeYieldStatus.CursorInsideClient,
                executeYieldStatus.TargetActive,
                executeYieldStatus.Scope,
                executeYieldStatus.Reason
            },
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.SentHotkeys,
            inputAudit.Clicks
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = loadResult is not null,
            profileLoadedReturnPoints,
            loadedModules = loadResult?.LoadedModules,
            missingModules = loadResult?.MissingModules
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        captures = new
        {
            beforeClient = new
            {
                path = beforeClientPath,
                saved = beforeCaptureSaved,
                visual = beforeCaptureVisual,
                width = beforeCapture?.Width ?? 0,
                height = beforeCapture?.Height ?? 0
            },
            afterClient = new
            {
                path = afterClientPath,
                saved = afterCaptureSaved,
                visual = afterCaptureVisual,
                width = afterCapture?.Width ?? 0,
                height = afterCapture?.Height ?? 0
            },
            returnNavigationActions = new
            {
                path = actionOverlayPath,
                saved = actionOverlaySaved,
                markers = actionMarkers
            }
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        config = new
        {
            config.ProfileName,
            config.EnableFixedFarmReturn,
            config.EnableEarthSpiritReturn,
            config.EnableDeathReturn,
            config.EnableStuckRecovery,
            config.ArrivalDistance,
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            config.NavigationRecognition.ConfirmedMapNameAutoFilled,
            pointCount = config.Points.Count,
            returnMode = config.ReturnNavigation.Mode.ToString(),
            returnHotkey = config.ReturnNavigation.Hotkey,
            returnClickX = config.ReturnNavigation.ClickX,
            returnClickY = config.ReturnNavigation.ClickY,
            returnClickButton = config.ReturnNavigation.ClickButton.ToString(),
            returnClickRepeat = config.ReturnNavigation.ClickRepeat,
            returnAfterClickHotkey = config.ReturnNavigation.AfterClickHotkey,
            earthMode = config.EarthSpiritNavigation.Mode.ToString(),
            deathMode = config.DeathReturnNavigation.Mode.ToString(),
            stuckMode = config.StuckRecoveryNavigation.Mode.ToString()
        },
        beforeNavigation = new
        {
            beforeNavigation.MapNameText,
            beforeNavigation.MapNameSource,
            beforeNavigation.MapNameConfidencePercent,
            beforeNavigation.CoordinateText,
            beforeNavigation.CoordinateSource,
            beforeNavigation.CoordinateConfidencePercent,
            beforeNavigation.X,
            beforeNavigation.Y,
            beforeNavigation.HasMap,
            beforeNavigation.HasCoordinate,
            nearest = beforeNearest is null ? null : new
            {
                beforeNearest.MapName,
                beforeNearest.X,
                beforeNearest.Y,
                beforeNearest.Label,
                kind = beforeNearest.Kind.ToString(),
                distance = beforeDistance
            }
        },
        navigation = new
        {
            navigation.MapNameText,
            navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y,
            navigation.HasMap,
            navigation.HasCoordinate
        },
        nearest = nearest is null ? null : new
        {
            nearest.MapName,
            nearest.X,
            nearest.Y,
            nearest.Label,
            kind = nearest.Kind.ToString(),
            distance
        },
        result = new
        {
            result.Action,
            result.ShouldSuspendCombat,
            result.Message
        },
        verification = new
        {
            verifyDelayMs,
            verificationMessage,
            arrivedAfterExecute,
            movedCloserAfterExecute,
            afterDistance,
            afterNavigation = afterNavigation is null ? null : new
            {
                afterNavigation.MapNameText,
                afterNavigation.MapNameSource,
                afterNavigation.MapNameConfidencePercent,
                afterNavigation.CoordinateText,
                afterNavigation.CoordinateSource,
                afterNavigation.CoordinateConfidencePercent,
                afterNavigation.X,
                afterNavigation.Y,
                afterNavigation.HasMap,
                afterNavigation.HasCoordinate
            }
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}, returnPointsLoaded={profileLoadedReturnPoints}, points={config.Points.Count}, confirmedMap='{config.NavigationRecognition.ConfirmedMapName}'");
    Console.WriteLine($"ExecuteRequested={executeRequested}, allowedToExecute={allowedToExecute}");
    Console.WriteLine($"YieldGate enabled={executeYieldStatus.Enabled}, shouldYield={executeYieldStatus.ShouldYield}, ageMs={executeYieldStatus.LastInputAgeMs:0}, remainingMs={executeYieldStatus.RemainingYieldMs:0}, ignore={ignoreYield}, dispatch={yieldDispatch}, reason={executeYieldStatus.Reason}");
    foreach (var reason in executionReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine($"Before map='{beforeNavigation.MapNameText}' coord='{beforeNavigation.CoordinateText}' parsed={beforeNavigation.X},{beforeNavigation.Y}, distance={beforeDistance:0.0}");
    Console.WriteLine($"Navigation map='{navigation.MapNameText}' source={navigation.MapNameSource} confidence={navigation.MapNameConfidencePercent}%, coord='{navigation.CoordinateText}' source={navigation.CoordinateSource} confidence={navigation.CoordinateConfidencePercent}%, parsed={navigation.X},{navigation.Y}");
    Console.WriteLine(nearest is null
        ? "Nearest=-"
        : $"Nearest={nearest.MapName}({nearest.X},{nearest.Y}), distance={distance:0.0}, kind={nearest.Kind}");
    Console.WriteLine($"Result action={result.Action}, suspend={result.ShouldSuspendCombat}, message={result.Message}");
    Console.WriteLine(allowedToExecute
        ? $"Actual input send={inputAudit.SendKeyCount}, click={inputAudit.ClickCount}, text={inputAudit.SendTextCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)}"
        : $"Planned input send={inputAudit.SendKeyCount}, click={inputAudit.ClickCount}, text={inputAudit.SendTextCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)} (not sent to game)");
    Console.WriteLine($"ActionOverlay={actionOverlayPath}, saved={actionOverlaySaved}, markers={actionMarkers.Count}");
    if (allowedToExecute)
    {
        Console.WriteLine(afterNavigation is null
            ? $"Post-verify skipped, message={verificationMessage}"
            : $"Post-verify map='{afterNavigation.MapNameText}' coord='{afterNavigation.CoordinateText}' parsed={afterNavigation.X},{afterNavigation.Y}, distance={afterDistance:0.0}, arrived={arrivedAfterExecute}, movedCloser={movedCloserAfterExecute}, message={verificationMessage}");
    }
    Console.WriteLine($"Captures before={beforeCaptureSaved}/{beforeCaptureVisual} {beforeClientPath}, after={afterCaptureSaved}/{afterCaptureVisual} {afterClientPath}");
    Console.WriteLine($"Evidence={evidencePath}");

    var evidenceOk = File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0;
    var captureEvidenceOk = beforeCaptureSaved && afterCaptureSaved && beforeCaptureVisual && afterCaptureVisual && actionOverlaySaved;
    var noUnexpectedRealInput = input is CountingInputService
        || allowedToExecute
        || inputAudit is { SendKeyCount: 0, ClickCount: 0, SendTextCount: 0 };
    var executionVerified = !allowedToExecute
        || arrivedAfterExecute == true
        || movedCloserAfterExecute == true;
    var ok = evidenceOk && captureEvidenceOk && noUnexpectedRealInput && executionVerified;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static IReadOnlyList<ReturnNavigationActionMarker> BuildReturnNavigationActionMarkers(
    BoundGameWindow window,
    NavigationRecognitionResult current,
    ReturnPoint? nearest,
    ReturnPointConfig config,
    ReturnPointRuntimeAction action)
{
    var (slotName, navigation, target) = action switch
    {
        ReturnPointRuntimeAction.EarthSpiritReturn => (
            "土灵返点",
            config.EarthSpiritNavigation,
            FindPreferredDiagnosticPoint(config, ReturnPointKind.EarthSpirit) ?? nearest),
        ReturnPointRuntimeAction.DeathReturn => (
            "死亡回点",
            config.DeathReturnNavigation,
            FindPreferredDiagnosticPoint(config, ReturnPointKind.DeathReturn) ?? config.Points.FirstOrDefault()),
        ReturnPointRuntimeAction.StuckRecovery => (
            "卡点恢复",
            config.StuckRecoveryNavigation,
            FindPreferredDiagnosticPoint(config, ReturnPointKind.Recovery) ?? nearest),
        _ => (
            "挂机回点",
            config.ReturnNavigation,
            nearest)
    };

    var markers = new List<ReturnNavigationActionMarker>();
    switch (navigation.Mode)
    {
        case ReturnNavigationMode.ClickClientPoint:
        case ReturnNavigationMode.HotkeyThenClickClientPoint:
            AddMarker(markers, slotName, navigation.Mode, navigation.ClickX, navigation.ClickY, navigation.ClickButton, 1, target, "configured-click");
            break;

        case ReturnNavigationMode.DirectionalClientClick:
        case ReturnNavigationMode.HotkeyThenDirectionalClientClick:
            if (target is not null && current.HasCoordinate)
            {
                var point = ResolveDiagnosticDirectionalClick(window, current, target, navigation);
                AddMarker(markers, slotName, navigation.Mode, point.X, point.Y, navigation.ClickButton, 1, target, "directional-click");
            }
            break;

        case ReturnNavigationMode.RecordedClientClickSequence:
            for (var i = 0; i < navigation.RecordedClicks.Count; i++)
            {
                var click = navigation.RecordedClicks[i];
                AddMarker(markers, slotName, navigation.Mode, click.ClientX, click.ClientY, click.Button, i + 1, target, "recorded-click");
            }
            break;
    }

    return markers;
}

static InputDispatchMode ResolvePrimaryReturnNavigationDispatch(ReturnPointConfig config)
{
    if (config.EnableFixedFarmReturn && config.ReturnNavigation.Mode != ReturnNavigationMode.Disabled)
        return config.ReturnNavigation.DispatchMode;
    if (config.EnableEarthSpiritReturn && config.EarthSpiritNavigation.Mode != ReturnNavigationMode.Disabled)
        return config.EarthSpiritNavigation.DispatchMode;
    if (config.EnableStuckRecovery && config.StuckRecoveryNavigation.Mode != ReturnNavigationMode.Disabled)
        return config.StuckRecoveryNavigation.DispatchMode;
    if (config.EnableDeathReturn && config.DeathReturnNavigation.Mode != ReturnNavigationMode.Disabled)
        return config.DeathReturnNavigation.DispatchMode;
    return config.ReturnNavigation.DispatchMode;
}

static ReturnPoint? FindPreferredDiagnosticPoint(ReturnPointConfig config, ReturnPointKind kind) =>
    config.Points.FirstOrDefault(p => p.Kind == kind) ?? config.Points.FirstOrDefault();

static void AddMarker(
    List<ReturnNavigationActionMarker> markers,
    string slotName,
    ReturnNavigationMode mode,
    int x,
    int y,
    InputMouseButton button,
    int order,
    ReturnPoint? target,
    string source)
{
    markers.Add(new ReturnNavigationActionMarker(
        slotName,
        mode.ToString(),
        order,
        x,
        y,
        button.ToString(),
        target?.MapName ?? "",
        target?.X,
        target?.Y,
        target?.Label ?? "",
        source));
}

static (int X, int Y) ResolveDiagnosticDirectionalClick(
    BoundGameWindow window,
    NavigationRecognitionResult current,
    ReturnPoint targetPoint,
    ReturnNavigationConfig config)
{
    var dx = targetPoint.X - current.X!.Value;
    var dy = targetPoint.Y - current.Y!.Value;
    if (config.DirectionInvertX)
        dx = -dx;
    if (config.DirectionInvertY)
        dy = -dy;

    var length = Math.Sqrt(dx * dx + dy * dy);
    if (length < 0.001)
        return (ClampClientX(window, config.ClickX), ClampClientY(window, config.ClickY));

    var radius = Math.Clamp(config.DirectionRadius, 20, Math.Max(20, Math.Min(window.ClientWidth, window.ClientHeight) / 2));
    var x = config.ClickX + (int)Math.Round(dx / length * radius);
    var y = config.ClickY + (int)Math.Round(dy / length * radius);
    return (ClampClientX(window, x), ClampClientY(window, y));
}

static int ClampClientX(BoundGameWindow window, int x) =>
    Math.Clamp(x, 0, Math.Max(0, window.ClientWidth - 1));

static int ClampClientY(BoundGameWindow window, int y) =>
    Math.Clamp(y, 0, Math.Max(0, window.ClientHeight - 1));

static string? ReadOption(string[] args, string name)
{
    for (var i = 0; i < args.Length; i++)
    {
        if (!args[i].Equals(name, StringComparison.OrdinalIgnoreCase))
            continue;

        if (i + 1 >= args.Length)
            return null;

        var value = args[i + 1].Trim();
        return value.Length == 0 ? null : value;
    }

    return null;
}

static int ReadIntOption(string[] args, string name, int fallback) =>
    int.TryParse(ReadOption(args, name), out var value) ? value : fallback;

static nint ReadHandleOption(string[] args, string name, nint fallback)
{
    var raw = ReadOption(args, name);
    if (string.IsNullOrWhiteSpace(raw))
        return fallback;

    var normalized = raw.Trim();
    var style = NumberStyles.Integer;
    if (normalized.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
    {
        normalized = normalized[2..];
        style = NumberStyles.AllowHexSpecifier;
    }

    return long.TryParse(normalized, style, CultureInfo.InvariantCulture, out var value)
        ? new nint(value)
        : fallback;
}

static (int X, int Y) ReadOffsetOption(string[] args, string name, (int X, int Y) fallback)
{
    var value = ReadOption(args, name);
    if (string.IsNullOrWhiteSpace(value))
        return fallback;

    var parts = value.Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    if (parts.Length != 2)
        return fallback;

    return int.TryParse(parts[0], out var x) && int.TryParse(parts[1], out var y)
        ? (x, y)
        : fallback;
}

static InputDispatchMode ReadDispatchOption(string[] args, string name, InputDispatchMode fallback) =>
    Enum.TryParse<InputDispatchMode>(ReadOption(args, name), ignoreCase: true, out var mode) ? mode : fallback;

static IReadOnlyList<RecordedNavigationHotkey> ReadRecordedPreHotkeys(string[] args, string sourceEvidencePath, int defaultDelayMs)
{
    return ReadRecordedHotkeysOption(args, "--pre-hotkeys", "--pre-hotkey", sourceEvidencePath, defaultDelayMs);
}

static IReadOnlyList<RecordedNavigationHotkey> ReadRecordedPrepareHotkeys(string[] args, int defaultDelayMs)
{
    return ReadRecordedHotkeysOption(args, "--prepare-hotkeys", "--prepare-hotkey", "", defaultDelayMs);
}

static IReadOnlyList<RecordedNavigationHotkey> ReadRecordedHotkeysOption(
    string[] args,
    string pluralName,
    string singularName,
    string sourceEvidencePath,
    int defaultDelayMs)
{
    var value = ReadOption(args, pluralName) ?? ReadOption(args, singularName) ?? "";
    if (string.IsNullOrWhiteSpace(value))
        return Array.Empty<RecordedNavigationHotkey>();

    var delay = Math.Clamp(defaultDelayMs, 20, 5000);
    return value
        .Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)
        .Where(h => !string.IsNullOrWhiteSpace(h))
        .Select(h => new RecordedNavigationHotkey
        {
            Hotkey = h.Trim(),
            DelayAfterMs = delay,
            SourceEvidencePath = sourceEvidencePath
        })
        .ToArray();
}

static ReturnPointKind ReadReturnPointKindOption(string[] args, string name, ReturnPointKind fallback) =>
    Enum.TryParse<ReturnPointKind>(ReadOption(args, name), ignoreCase: true, out var kind) ? kind : fallback;

static ReturnPointKind ReadReturnCaptureKindOption(string[] args, string name, ReturnPointKind fallback)
{
    var value = ReadOption(args, name);
    if (string.IsNullOrWhiteSpace(value))
        return fallback;

    return value.Trim().ToLowerInvariant() switch
    {
        "normal" => ReturnPointKind.Normal,
        "fixed" or "farm" or "fixed-farm" => ReturnPointKind.FixedFarm,
        "earth" or "earth-spirit" or "tuling" => ReturnPointKind.EarthSpirit,
        "death" or "death-return" => ReturnPointKind.DeathReturn,
        "stuck" or "recovery" or "stuck-recovery" => ReturnPointKind.Recovery,
        _ when Enum.TryParse<ReturnPointKind>(value, ignoreCase: true, out var parsed) => parsed,
        _ => fallback
    };
}

static ReturnPointKind ReturnPointKindForSlot(ReturnNavigationSlot slot) => slot switch
{
    ReturnNavigationSlot.FixedFarm => ReturnPointKind.FixedFarm,
    ReturnNavigationSlot.EarthSpirit => ReturnPointKind.EarthSpirit,
    ReturnNavigationSlot.StuckRecovery => ReturnPointKind.Recovery,
    ReturnNavigationSlot.DeathReturn => ReturnPointKind.DeathReturn,
    _ => ReturnPointKind.FixedFarm
};

static ReturnNavigationSlot ReturnSlotForPointKind(ReturnPointKind kind) => kind switch
{
    ReturnPointKind.EarthSpirit => ReturnNavigationSlot.EarthSpirit,
    ReturnPointKind.DeathReturn => ReturnNavigationSlot.DeathReturn,
    ReturnPointKind.Recovery => ReturnNavigationSlot.StuckRecovery,
    _ => ReturnNavigationSlot.FixedFarm
};

static bool IsPreferredPointForRequestedReturnKind(ReturnPointKind pointKind, ReturnPointKind requestedKind) => requestedKind switch
{
    ReturnPointKind.FixedFarm => pointKind is ReturnPointKind.FixedFarm or ReturnPointKind.Normal,
    ReturnPointKind.EarthSpirit => pointKind == ReturnPointKind.EarthSpirit,
    ReturnPointKind.DeathReturn => pointKind == ReturnPointKind.DeathReturn,
    ReturnPointKind.Recovery => false,
    ReturnPointKind.Normal => true,
    _ => false
};

static string ReturnCaptureKindText(ReturnPointKind kind) => kind switch
{
    ReturnPointKind.Normal => "normal",
    ReturnPointKind.FixedFarm => "fixed",
    ReturnPointKind.EarthSpirit => "earth",
    ReturnPointKind.DeathReturn => "death",
    ReturnPointKind.Recovery => "recovery",
    _ => "fixed"
};

static string ReturnNavigationSlotText(ReturnNavigationSlot slot) => slot switch
{
    ReturnNavigationSlot.EarthSpirit => "earth",
    ReturnNavigationSlot.StuckRecovery => "stuck",
    ReturnNavigationSlot.DeathReturn => "death",
    _ => "fixed"
};

static InputMouseButton ReadMouseButtonOption(string[] args, string name, InputMouseButton fallback)
{
    var value = ReadOption(args, name);
    if (string.IsNullOrWhiteSpace(value))
        return fallback;

    return value.Trim().ToLowerInvariant() switch
    {
        "left" or "l" or "左" or "左键" => InputMouseButton.Left,
        "right" or "r" or "右" or "右键" => InputMouseButton.Right,
        _ when Enum.TryParse<InputMouseButton>(value, ignoreCase: true, out var parsed) => parsed,
        _ => fallback
    };
}

static ReturnNavigationMode ReadReturnNavigationModeOption(string[] args, string name, ReturnNavigationMode fallback)
{
    var value = ReadOption(args, name);
    if (string.IsNullOrWhiteSpace(value))
        return fallback;

    return value.Trim().ToLowerInvariant() switch
    {
        "click" or "click-client" or "client-click" or "point" or "点击" =>
            ReturnNavigationMode.ClickClientPoint,
        "hotkey-click" or "hotkeythenclick" or "hotkey-then-click" or "key-click" or "热键点击" =>
            ReturnNavigationMode.HotkeyThenClickClientPoint,
        "direction" or "directional" or "direction-click" or "directional-click" or "dir" or "方向" or "方向点击" =>
            ReturnNavigationMode.DirectionalClientClick,
        "hotkey-direction" or "hotkey-directional" or "key-direction" or "key-dir" or "热键方向" or "热键方向点击" =>
            ReturnNavigationMode.HotkeyThenDirectionalClientClick,
        "recorded" or "record" or "replay" or "sequence" or "recorded-clicks" or "录制" or "录制序列" =>
            ReturnNavigationMode.RecordedClientClickSequence,
        "hotkey" or "key" or "热键" =>
            ReturnNavigationMode.HotkeyOnly,
        "disabled" or "off" or "none" or "关闭" =>
            ReturnNavigationMode.Disabled,
        _ when Enum.TryParse<ReturnNavigationMode>(value, ignoreCase: true, out var parsed) => parsed,
        _ => fallback
    };
}

static InventoryGridConfig? ReadInventoryGridOption(string[] args)
{
    var value = ReadOption(args, "--grid");
    if (string.IsNullOrWhiteSpace(value))
        return null;

    var parts = value.Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    if (parts.Length is not 6 and not 8)
        return null;

    var numbers = new int[parts.Length];
    for (var i = 0; i < parts.Length; i++)
    {
        if (!int.TryParse(parts[i], out numbers[i]))
            return null;
    }

    return new InventoryGridConfig
    {
        ScanMode = InventoryScanMode.ManualGrid,
        Enabled = true,
        X = numbers[0],
        Y = numbers[1],
        Columns = numbers[2],
        Rows = numbers[3],
        CellWidth = numbers[4],
        CellHeight = numbers[5],
        GapX = parts.Length == 8 ? numbers[6] : 3,
        GapY = parts.Length == 8 ? numbers[7] : 3
    };
}

static string NormalizeDiagnosticMapName(string mapName)
{
    var chars = mapName.Trim()
        .Where(c => c is >= '\u4E00' and <= '\u9FFF' || char.IsLetterOrDigit(c))
        .ToArray();
    return chars.Length == 0 ? string.Empty : new string(chars);
}

static bool IsDiagnosticSameMap(string left, string right)
{
    var a = NormalizeDiagnosticMapName(left);
    var b = NormalizeDiagnosticMapName(right);
    return !string.IsNullOrWhiteSpace(a)
           && !string.IsNullOrWhiteSpace(b)
           && (a.Contains(b, StringComparison.Ordinal) || b.Contains(a, StringComparison.Ordinal));
}

static string ResolveDiagnosticMapName(
    NavigationRecognitionResult navigation,
    string requestedMapName,
    string confirmedMapName,
    out string source)
{
    if (navigation.HasMap)
    {
        source = string.IsNullOrWhiteSpace(navigation.MapNameSource)
            ? "ocr"
            : navigation.MapNameSource;
        return NormalizeDiagnosticMapName(navigation.MapNameText);
    }

    if (!string.IsNullOrWhiteSpace(requestedMapName))
    {
        source = "manual-option";
        return requestedMapName;
    }

    if (!string.IsNullOrWhiteSpace(confirmedMapName))
    {
        source = "profile-confirmed-map";
        return confirmedMapName;
    }

    source = "";
    return "";
}

static NavigationRecognitionResult ApplyDiagnosticMapNameIfMissing(
    NavigationRecognitionResult navigation,
    string requestedMapName,
    string source)
{
    if (navigation.HasMap || string.IsNullOrWhiteSpace(requestedMapName))
        return navigation;

    return navigation with
    {
        MapNameText = requestedMapName,
        MapNameSource = source,
        MapNameConfidencePercent = 100
    };
}

static bool IsAnyReturnGateEnabled(ReturnPointConfig config) =>
    config.EnableFixedFarmReturn
    || config.EnableEarthSpiritReturn
    || config.EnableDeathReturn
    || config.EnableStuckRecovery;

static bool HasExecutableReturnAction(ReturnPointConfig config) =>
    config.EnableFixedFarmReturn && config.ReturnNavigation.Mode != ReturnNavigationMode.Disabled
    || config.EnableEarthSpiritReturn && config.EarthSpiritNavigation.Mode != ReturnNavigationMode.Disabled
    || config.EnableDeathReturn && config.DeathReturnNavigation.Mode != ReturnNavigationMode.Disabled
    || config.EnableStuckRecovery && config.StuckRecoveryNavigation.Mode != ReturnNavigationMode.Disabled;

static string FindEnabledSyntheticRecordedReturnSource(ReturnPointConfig config)
{
    var enabledNavigations = new[]
    {
        (config.EnableFixedFarmReturn, config.ReturnNavigation),
        (config.EnableEarthSpiritReturn, config.EarthSpiritNavigation),
        (config.EnableDeathReturn, config.DeathReturnNavigation),
        (config.EnableStuckRecovery, config.StuckRecoveryNavigation)
    };

    foreach (var (enabled, navigation) in enabledNavigations)
    {
        if (!enabled || navigation.Mode != ReturnNavigationMode.RecordedClientClickSequence)
            continue;

        var source = FindSyntheticRecordedSourceForDiagnostics(navigation);
        if (!string.IsNullOrWhiteSpace(source))
            return source;
    }

    return "";
}

static InputAudit BuildInputAudit(IInputService input) =>
    input switch
    {
        CountingInputService counting => new InputAudit(
            counting.SendKeyCount,
            counting.SendTextCount,
            counting.ClickCount,
            counting.SentHotkeys.ToArray(),
            counting.Clicks.Select(c => new ClientClick(c.X, c.Y, c.Button.ToString())).ToArray()),
        AuditedInputService audited => audited.Snapshot(),
        _ => new InputAudit(0, 0, 0, Array.Empty<string>(), Array.Empty<ClientClick>())
    };

static bool RunLiveDeathReturnEvidenceDiagnostics(string[] args)
{
    Console.WriteLine("Live death-return evidence diagnostics");
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = appProfiles.ListProfileNames().FirstOrDefault();
    AppProfileLoadResult? profileLoad = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        profileLoad = appProfiles.LoadAll(profileName);

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    if (client is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var fallbackRoute = FindImportedHorseRouteFile();
    ReturnPointImportResult? importedFallback = null;
    if (config.Points.Count == 0 && fallbackRoute is not null)
        importedFallback = returnPoints.ImportLegacyIni(fallbackRoute, "diagnostic-fallback-routes");

    var deathRecognition = provider.GetRequiredService<IDeathRecognitionService>();
    var death = deathRecognition.Recognize(window, config.DeathRecognition);
    var currentConfigPrediction = PredictDeathReturnAction(config, death);
    var enabledProbeConfig = CopyReturnPointConfigForPrediction(config);
    enabledProbeConfig.EnableDeathReturn = true;
    if (enabledProbeConfig.DeathReturnNavigation.Mode == ReturnNavigationMode.Disabled)
    {
        enabledProbeConfig.DeathReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
        enabledProbeConfig.DeathReturnNavigation.Hotkey = "F8";
    }
    var enabledPrediction = PredictDeathReturnAction(enabledProbeConfig, death);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-death-return", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var deathPath = Path.Combine(evidenceDir, "death-region.png");
    var deathZoomPath = Path.Combine(evidenceDir, "death-region-x4.png");
    var evidencePath = Path.Combine(evidenceDir, $"death-return-{window.Pid}.json");

    var deathResolved = OcrRegionProjection.Resolve(config.DeathRecognition.PromptRegion, client.Width, client.Height);
    var deathCapture = CropCapture(client, deathResolved);
    var deathZoom = deathCapture is null ? null : ScaleCaptureNearest(deathCapture, 4);

    var savedClient = SaveCapturePng(client, clientPath);
    var savedDeath = SaveCapturePng(deathCapture, deathPath);
    var savedDeathZoom = SaveCapturePng(deathZoom, deathZoomPath);
    var deathVisual = HasVisualContent(deathCapture);
    var deathFieldReady = deathVisual && !string.IsNullOrWhiteSpace(death.Text);
    var deathReason = BuildDeathReturnGateReason(config, death, deathVisual);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-death-return-evidence-no-input-no-click-no-action",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            executesReturnAction = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            diagnosticBusinessDecisionReady = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = profileLoad is not null,
            loadedModules = profileLoad?.LoadedModules,
            missingModules = profileLoad?.MissingModules
        },
        config = new
        {
            config.ProfileName,
            config.EnableDeathReturn,
            pointCount = config.Points.Count,
            confirmedMap = config.NavigationRecognition.ConfirmedMapName,
            config.NavigationRecognition.ConfirmedMapNameAutoFilled,
            deathKeywords = config.DeathRecognition.Keywords,
            deathReturnAction = new
            {
                config.DeathReturnNavigation.Mode,
                config.DeathReturnNavigation.Hotkey,
                config.DeathReturnNavigation.ClickX,
                config.DeathReturnNavigation.ClickY,
                config.DeathReturnNavigation.ActionIntervalMs,
                config.DeathReturnNavigation.DispatchMode
            },
            fallbackRouteImported = importedFallback is null ? null : new
            {
                importedFallback.SourcePath,
                importedFallback.MapCount,
                importedFallback.PointCount,
                importedFallback.SkippedCount
            }
        },
        recognition = new
        {
            death.IsDead,
            death.Text,
            death.MatchedKeyword,
            deathFieldReady,
            deathVisual
        },
        deathGate = new
        {
            fieldReady = deathFieldReady,
            keywordMatched = death.IsDead,
            actionConfigured = config.DeathReturnNavigation.Mode != ReturnNavigationMode.Disabled,
            pointAvailable = config.Points.Count > 0,
            currentConfigMayReturn = config.EnableDeathReturn && death.IsDead && config.Points.Count > 0,
            automatedActionReady = false,
            reason = deathReason
        },
        currentConfigPrediction,
        enabledProbePrediction = enabledPrediction,
        regions = new
        {
            client = new { path = clientPath, saved = savedClient, client.Width, client.Height, visual = HasVisualContent(client) },
            death = RegionEvidence(config.DeathRecognition.PromptRegion, deathResolved, deathPath, savedDeath, deathCapture),
            deathZoom = new { path = deathZoomPath, saved = savedDeathZoom, scale = 4 }
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}, loadedModules={profileLoad?.LoadedModules.Count ?? 0}, missing={profileLoad?.MissingModules.Count ?? 0}, confirmedMap='{config.NavigationRecognition.ConfirmedMapName}', autoFilled={config.NavigationRecognition.ConfirmedMapNameAutoFilled}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Death dead={death.IsDead}, keyword='{death.MatchedKeyword}', fieldReady={deathFieldReady}, visual={deathVisual}");
    Console.WriteLine($"Death text='{death.Text}'");
    Console.WriteLine($"Gate currentMayReturn={config.EnableDeathReturn && death.IsDead && config.Points.Count > 0}, automatedActionReady=False, reason={deathReason}");
    Console.WriteLine($"Current prediction={currentConfigPrediction.action}, suspend={currentConfigPrediction.shouldSuspendCombat}, reason={currentConfigPrediction.reason}");
    Console.WriteLine($"Enabled-probe prediction={enabledPrediction.action}, suspend={enabledPrediction.shouldSuspendCombat}, reason={enabledPrediction.reason}");
    Console.WriteLine($"Crops death={savedDeath}, zoom={savedDeathZoom}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && savedClient
             && savedDeath
             && savedDeathZoom
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && (!death.IsDead || enabledPrediction.action == nameof(ReturnPointRuntimeAction.DeathReturn));

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveDeathReturnExecuteDiagnostics(string[] args)
{
    Console.WriteLine("Live death-return controlled execute diagnostics");

    var executeRequested = args.Any(a => a.Equals("--execute", StringComparison.OrdinalIgnoreCase));
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();
    var log = provider.GetRequiredService<ILogService>();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = string.IsNullOrWhiteSpace(requestedProfile)
        ? appProfiles.CurrentProfileName
        : requestedProfile.Trim();
    AppProfileLoadResult? loadResult = null;
    if (!string.IsNullOrWhiteSpace(profileName))
        loadResult = appProfiles.LoadAll(profileName);

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var profileLoadedReturnPoints = loadResult?.LoadedModules.Contains("返点配置", StringComparer.Ordinal) == true;

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    var deathRecognition = provider.GetRequiredService<IDeathRecognitionService>();
    var death = deathRecognition.Recognize(window, config.DeathRecognition);
    var deathResolved = client is null
        ? new OcrResolvedRegion(0, 0, 0, 0)
        : OcrRegionProjection.Resolve(config.DeathRecognition.PromptRegion, client.Width, client.Height);
    var deathCapture = client is null ? null : CropCapture(client, deathResolved);
    var deathZoom = deathCapture is null ? null : ScaleCaptureNearest(deathCapture, 4);
    var deathVisual = HasVisualContent(deathCapture);
    var target = FindPreferredDeathReturnPoint(config);

    var preGateReasons = new List<string>();
    if (window.Bitness != ClientBitness.X86)
        preGateReasons.Add("绑定窗口不是 32 位客户端。");
    if (!window.IsAutomationAllowed)
        preGateReasons.Add(window.AutomationBlockReason);
    if (string.IsNullOrWhiteSpace(profileName))
        preGateReasons.Add("未指定方案，且没有可用的当前方案；真实执行必须显式加载方案。");
    if (loadResult is null)
        preGateReasons.Add("未加载完整方案。");
    else if (!profileLoadedReturnPoints)
        preGateReasons.Add("方案中未加载到返点配置。");
    if (!config.EnableDeathReturn)
        preGateReasons.Add("当前方案未启用死亡回点。");
    if (target is null)
        preGateReasons.Add("未配置可用死亡回点坐标。");
    if (config.DeathReturnNavigation.Mode == ReturnNavigationMode.Disabled)
        preGateReasons.Add("死亡返回动作未配置。");
    if (!deathVisual)
        preGateReasons.Add("死亡识别区域没有有效视觉内容。");
    if (!death.IsDead)
        preGateReasons.Add("未命中死亡关键词，禁止触发死亡回点。");

    var allowedToExecute = executeRequested && preGateReasons.Count == 0;
    var executionReasons = preGateReasons.ToList();
    if (!executeRequested)
        executionReasons.Add("未提供 --execute，本次只做受控预演，不向游戏发送输入。");

    IInputService input = allowedToExecute
        ? new AuditedInputService(provider.GetRequiredService<IInputService>())
        : new CountingInputService();
    var inputMode = allowedToExecute ? "real-audited" : "planned-counting";
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-death-return-execute", DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var beforeClientPath = Path.Combine(evidenceDir, $"before-client-{window.Pid}.png");
    var afterClientPath = Path.Combine(evidenceDir, $"after-client-{window.Pid}.png");
    var deathPath = Path.Combine(evidenceDir, "death-region.png");
    var deathZoomPath = Path.Combine(evidenceDir, "death-region-x4.png");
    var evidencePath = Path.Combine(evidenceDir, $"death-return-execute-{window.Pid}.json");

    ReturnNavigationResult? navigationResult = null;
    if (target is not null && death.IsDead && config.EnableDeathReturn && config.DeathReturnNavigation.Mode != ReturnNavigationMode.Disabled)
    {
        navigationResult = new ReturnNavigationService(input, log).TryNavigate(
            window,
            new NavigationRecognitionResult(string.Empty, death.Text, null, null),
            target,
            0,
            config.DeathReturnNavigation);
    }

    var afterClient = capture.CaptureClient(window.Hwnd);
    var inputAudit = BuildInputAudit(input);
    var savedClient = SaveCapturePng(client, clientPath);
    var savedBeforeClient = SaveCapturePng(client, beforeClientPath);
    var savedAfterClient = SaveCapturePng(afterClient, afterClientPath);
    var savedDeath = SaveCapturePng(deathCapture, deathPath);
    var savedDeathZoom = SaveCapturePng(deathZoom, deathZoomPath);
    var beforeClientVisual = HasVisualContent(client);
    var afterClientVisual = HasVisualContent(afterClient);

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "controlled-live-death-return-execute-gated",
        safety = new
        {
            executeRequested,
            allowedToExecute,
            sendsToRealGameWindow = allowedToExecute,
            plannedOnly = !allowedToExecute,
            inputMode,
            inputService = input.GetType().Name,
            blockedReasons = executionReasons,
            inputAudit.SendKeyCount,
            inputAudit.SendTextCount,
            inputAudit.ClickCount,
            inputAudit.SentHotkeys,
            inputAudit.Clicks
        },
        profile = new
        {
            requestedProfile,
            profileName,
            loaded = loadResult is not null,
            profileLoadedReturnPoints,
            loadedModules = loadResult?.LoadedModules,
            missingModules = loadResult?.MissingModules
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.AutomationBlockReason
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        config = new
        {
            config.ProfileName,
            config.EnableDeathReturn,
            pointCount = config.Points.Count,
            deathMode = config.DeathReturnNavigation.Mode.ToString(),
            config.DeathReturnNavigation.Hotkey,
            config.DeathReturnNavigation.ClickX,
            config.DeathReturnNavigation.ClickY,
            config.DeathReturnNavigation.ActionIntervalMs,
            dispatchMode = config.DeathReturnNavigation.DispatchMode.ToString()
        },
        recognition = new
        {
            death.IsDead,
            death.Text,
            death.MatchedKeyword,
            deathVisual,
            deathFieldReady = deathVisual && !string.IsNullOrWhiteSpace(death.Text)
        },
        target = target is null
            ? null
            : new
            {
                target.MapName,
                target.X,
                target.Y,
                target.Label,
                kind = target.Kind.ToString()
            },
        navigationResult = navigationResult is null
            ? null
            : new
            {
                navigationResult.Executed,
                navigationResult.Message
            },
        captures = new
        {
            beforeClient = new
            {
                path = beforeClientPath,
                saved = savedBeforeClient,
                visual = beforeClientVisual,
                width = client?.Width ?? 0,
                height = client?.Height ?? 0
            },
            afterClient = new
            {
                path = afterClientPath,
                saved = savedAfterClient,
                visual = afterClientVisual,
                width = afterClient?.Width ?? 0,
                height = afterClient?.Height ?? 0
            }
        },
        regions = new
        {
            client = new { path = clientPath, saved = savedClient, width = client?.Width ?? 0, height = client?.Height ?? 0, visual = HasVisualContent(client) },
            death = RegionEvidence(config.DeathRecognition.PromptRegion, deathResolved, deathPath, savedDeath, deathCapture),
            deathZoom = new { path = deathZoomPath, saved = savedDeathZoom, scale = 4 }
        }
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "-" : profileName)}, returnPointsLoaded={profileLoadedReturnPoints}, points={config.Points.Count}, deathEnabled={config.EnableDeathReturn}, deathMode={config.DeathReturnNavigation.Mode}");
    Console.WriteLine($"Death dead={death.IsDead}, keyword='{death.MatchedKeyword}', visual={deathVisual}, text='{death.Text}'");
    Console.WriteLine(target is null
        ? "Death target=-"
        : $"Death target={target.MapName}({target.X},{target.Y}), kind={target.Kind}, label={target.Label}");
    Console.WriteLine($"ExecuteRequested={executeRequested}, allowedToExecute={allowedToExecute}");
    foreach (var reason in executionReasons)
        Console.WriteLine($"Gate: {reason}");
    Console.WriteLine(navigationResult is null
        ? "Result=-"
        : $"Result executed={navigationResult.Executed}, message={navigationResult.Message}");
    Console.WriteLine(allowedToExecute
        ? $"Actual input send={inputAudit.SendKeyCount}, click={inputAudit.ClickCount}, text={inputAudit.SendTextCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)}"
        : $"Planned input send={inputAudit.SendKeyCount}, click={inputAudit.ClickCount}, text={inputAudit.SendTextCount}, hotkeys={string.Join(",", inputAudit.SentHotkeys)} (not sent to game)");
    Console.WriteLine($"Captures before={savedBeforeClient}/{beforeClientVisual} {beforeClientPath}, after={savedAfterClient}/{afterClientVisual} {afterClientPath}");
    Console.WriteLine($"Evidence={evidencePath}");

    var evidenceOk = File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0 && savedClient && savedDeath && savedDeathZoom;
    var captureEvidenceOk = savedBeforeClient && savedAfterClient && beforeClientVisual && afterClientVisual;
    var noUnexpectedRealInput = input is CountingInputService
        || allowedToExecute
        || inputAudit is { SendKeyCount: 0, ClickCount: 0, SendTextCount: 0 };
    var noFalseAction = death.IsDead || inputAudit is { SendKeyCount: 0, ClickCount: 0, SendTextCount: 0 };
    var ok = evidenceOk && captureEvidenceOk && noUnexpectedRealInput && noFalseAction;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveMapNameEvidenceDiagnostics(string? label)
{
    Console.WriteLine("Live map-name evidence diagnostics");
    label = string.IsNullOrWhiteSpace(label) ? null : label.Trim();

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    if (client is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current.NavigationRecognition;
    var resolved = OcrRegionProjection.Resolve(config.MapName, client.Width, client.Height, rightAnchored: true);
    var mapCapture = CropCapture(client, resolved);
    if (mapCapture is null)
    {
        Console.Error.WriteLine("FAIL: 地图名区域为空或超出客户区。");
        return false;
    }

    var rawText = ocr.Recognize(mapCapture).Trim();
    var rawScaled = ScaleCaptureNearest(mapCapture, 3);
    var (goldMask, goldPixels) = BuildGoldTextMask(mapCapture, 1);
    var goldMaskScaled = ScaleCaptureNearest(goldMask, 3);
    var goldMaskText = ocr.Recognize(goldMask).Trim();
    var goldMaskScaledText = ocr.Recognize(goldMaskScaled).Trim();
    var bestSampleMatch = MatchAcceptedMapNameSamples(goldMask);
    var bestSampleMatchConfident = bestSampleMatch is not null && bestSampleMatch.Value.Score >= 0.70;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-map-name", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var rawPath = Path.Combine(evidenceDir, "map-region.png");
    var rawScaledPath = Path.Combine(evidenceDir, "map-region-x3.png");
    var maskPath = Path.Combine(evidenceDir, "map-gold-mask.png");
    var maskScaledPath = Path.Combine(evidenceDir, "map-gold-mask-x3.png");
    var evidencePath = Path.Combine(evidenceDir, $"map-name-{window.Pid}.json");

    var savedClient = SaveCapturePng(client, clientPath);
    var savedRaw = SaveCapturePng(mapCapture, rawPath);
    var savedRawScaled = SaveCapturePng(rawScaled, rawScaledPath);
    var savedMask = SaveCapturePng(goldMask, maskPath);
    var savedMaskScaled = SaveCapturePng(goldMaskScaled, maskScaledPath);

    var pixelCount = Math.Max(1, mapCapture.Width * mapCapture.Height);
    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    var sample = TryWriteMapNameSample(
        label,
        window,
        resolved,
        config.MapName,
        rawText,
        goldMaskText,
        goldMaskScaledText,
        goldPixels,
        rawPath,
        rawScaledPath,
        maskPath,
        maskScaledPath,
        goldMask,
        jsonOptions);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-map-name-evidence-no-input-no-click",
        label,
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        region = new
        {
            configured = config.MapName,
            resolved = new { resolved.X, resolved.Y, resolved.Width, resolved.Height },
            rightAnchored = true
        },
        recognition = new
        {
            rawText,
            goldMaskText,
            goldMaskScaledText,
            goldPixels,
            goldPixelRatio = goldPixels / (double)pixelCount,
            bestSampleMatch = bestSampleMatch is null ? null : new
            {
                bestSampleMatch.Value.Label,
                bestSampleMatch.Value.SampleId,
                bestSampleMatch.Value.Score,
                IsConfident = bestSampleMatchConfident,
                Threshold = 0.70,
                bestSampleMatch.Value.SamplePath
            },
            note = "rawText 为空通常表示旧字库不适配当前金色地图文字；优先用截图证据校准，不把空结果接入回点决策。"
        },
        sample,
        files = new
        {
            client = new { path = clientPath, saved = savedClient },
            raw = new { path = rawPath, saved = savedRaw, visual = HasVisualContent(mapCapture) },
            rawScaled = new { path = rawScaledPath, saved = savedRawScaled },
            goldMask = new { path = maskPath, saved = savedMask, visual = HasVisualContent(goldMask) },
            goldMaskScaled = new { path = maskScaledPath, saved = savedMaskScaled }
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Region configured=({config.MapName.X},{config.MapName.Y},{config.MapName.Width},{config.MapName.Height}), resolved=({resolved.X},{resolved.Y},{resolved.Width},{resolved.Height})");
    if (!string.IsNullOrWhiteSpace(label))
        Console.WriteLine($"Label={label}");
    Console.WriteLine($"Map rawText='{rawText}', goldMaskText='{goldMaskText}', goldMaskScaledText='{goldMaskScaledText}', goldPixels={goldPixels}");
    Console.WriteLine(bestSampleMatch is null
        ? "BestSampleMatch=-"
        : $"BestSampleMatch={bestSampleMatch.Value.Label}, score={bestSampleMatch.Value.Score:0.000}, confident={bestSampleMatchConfident}, sample={bestSampleMatch.Value.SampleId}");
    Console.WriteLine($"Files raw={rawPath}");
    Console.WriteLine($"Files rawX3={rawScaledPath}");
    Console.WriteLine($"Files mask={maskPath}");
    Console.WriteLine($"Files maskX3={maskScaledPath}");
    if (sample is not null)
        Console.WriteLine($"Sample={sample}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && savedClient
             && savedRaw
             && savedRawScaled
             && savedMask
             && savedMaskScaled
             && HasVisualContent(mapCapture)
             && goldPixels > 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static object? TryWriteMapNameSample(
    string? label,
    BoundGameWindow window,
    OcrResolvedRegion resolved,
    OcrRegionConfig configured,
    string rawText,
    string goldMaskText,
    string goldMaskScaledText,
    int goldPixels,
    string rawPath,
    string rawScaledPath,
    string maskPath,
    string maskScaledPath,
    CaptureResult goldMask,
    System.Text.Json.JsonSerializerOptions evidenceJsonOptions)
{
    if (string.IsNullOrWhiteSpace(label))
        return null;

    var safeLabel = SanitizeFileName(label);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var sampleRoot = Path.Combine(Environment.CurrentDirectory, "data", "samples", "map-names");
    var sampleDir = Path.Combine(sampleRoot, $"{stamp}-{safeLabel}");
    Directory.CreateDirectory(sampleDir);

    var sampleRaw = Path.Combine(sampleDir, "map-region.png");
    var sampleRawScaled = Path.Combine(sampleDir, "map-region-x3.png");
    var sampleMask = Path.Combine(sampleDir, "map-gold-mask.png");
    var sampleMaskScaled = Path.Combine(sampleDir, "map-gold-mask-x3.png");
    var sampleJson = Path.Combine(sampleDir, "sample.json");
    var indexJsonl = Path.Combine(sampleRoot, "samples.jsonl");

    if (File.Exists(rawPath))
        File.Copy(rawPath, sampleRaw, overwrite: true);
    if (File.Exists(rawScaledPath))
        File.Copy(rawScaledPath, sampleRawScaled, overwrite: true);
    if (File.Exists(maskPath))
        File.Copy(maskPath, sampleMask, overwrite: true);
    if (File.Exists(maskScaledPath))
        File.Copy(maskScaledPath, sampleMaskScaled, overwrite: true);

    var sample = new
    {
        capturedAt = DateTimeOffset.Now,
        label,
        safeLabel,
        trusted = false,
        reviewStatus = "NeedsReview",
        reviewNote = "人工输入标签仅作为候选标签，必须复核 map-region-x3.png 或 gold-mask-x3.png 后才能进入训练/匹配。",
        source = "live-map-name",
        mode = "read-only-map-name-sample-no-input-no-click",
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText
        },
        region = new
        {
            configured,
            resolved = new { resolved.X, resolved.Y, resolved.Width, resolved.Height },
            rightAnchored = true
        },
        recognition = new
        {
            rawText,
            goldMaskText,
            goldMaskScaledText,
            goldPixels
        },
        mask = BuildMapNameMaskJson(goldMask),
        files = new
        {
            raw = sampleRaw,
            rawScaled = sampleRawScaled,
            goldMask = sampleMask,
            goldMaskScaled = sampleMaskScaled
        }
    };

    File.WriteAllText(sampleJson, System.Text.Json.JsonSerializer.Serialize(sample, evidenceJsonOptions), new UTF8Encoding(false));

    var indexLineOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = false,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.AppendAllText(indexJsonl, System.Text.Json.JsonSerializer.Serialize(sample, indexLineOptions) + Environment.NewLine, new UTF8Encoding(false));

    return new
    {
        label,
        root = sampleDir,
        json = sampleJson,
        index = indexJsonl
    };
}

static bool RunMapNameSamplesDiagnostics(string[] args)
{
    var action = args.FirstOrDefault()?.Trim().ToLowerInvariant();
    if (string.IsNullOrWhiteSpace(action))
        action = "list";

    return action switch
    {
        "list" => ListMapNameSamples(),
        "accept" => UpdateMapNameSampleReview(args, accepted: true),
        "reject" => UpdateMapNameSampleReview(args, accepted: false),
        "import" => ImportMapNameSample(args),
        "match" => MatchMapNameSample(args),
        "verify" => VerifyMapNameSamples(),
        "audit" => AuditMapNameSamples(),
        "rebuild-index" => RebuildMapNameSampleIndex(verbose: true),
        "help" or "-h" or "--help" => PrintMapNameSamplesHelp(),
        _ => PrintMapNameSamplesHelp()
    };
}

static bool PrintMapNameSamplesHelp()
{
    Console.WriteLine("Map name samples diagnostics");
    Console.WriteLine("Usage:");
    Console.WriteLine("  map-name-samples list");
    Console.WriteLine("  map-name-samples accept <sample-id-or-path> [correct-label]");
    Console.WriteLine("  map-name-samples reject <sample-id-or-path> [reason]");
    Console.WriteLine("  map-name-samples import <map-region.png> <地图名> [--accept]");
    Console.WriteLine("  map-name-samples match <map-region.png>");
    Console.WriteLine("  map-name-samples verify");
    Console.WriteLine("  map-name-samples audit");
    Console.WriteLine("  map-name-samples rebuild-index");
    Console.WriteLine();
    Console.WriteLine("说明：该命令只读/改写 data/samples/map-names 下的本地采样资产，不访问游戏窗口。");
    return false;
}

static bool MatchMapNameSample(string[] args)
{
    if (args.Length < 2 || string.IsNullOrWhiteSpace(args[1]))
    {
        Console.Error.WriteLine("FAIL: match 需要地图名区域 PNG 路径。");
        PrintMapNameSamplesHelp();
        return false;
    }

    var imagePath = Path.GetFullPath(args[1].Trim().Trim('"'));
    if (!File.Exists(imagePath))
    {
        Console.Error.WriteLine($"FAIL: 地图区域图片不存在：{imagePath}");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null || capture.Width <= 0 || capture.Height <= 0)
    {
        Console.Error.WriteLine($"FAIL: 无法读取地图区域图片：{imagePath}");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var matcher = provider.GetRequiredService<IMapNameSampleRecognitionService>();
    var hub = provider.GetRequiredService<IPerceptionHub>();
    var injectedMatcher = hub.GetType()
        .GetField("_mapNameSamples", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)
        ?.GetValue(hub);
    var match = matcher.Match(capture);

    Console.WriteLine($"Map region: {capture.Width}x{capture.Height}");
    Console.WriteLine($"Path: {imagePath}");
    Console.WriteLine($"PerceptionHub sample matcher injected: {injectedMatcher is IMapNameSampleRecognitionService}");
    if (match is null)
    {
        Console.WriteLine("NO MATCH: no gold-text pixels or no accepted samples were loaded.");
        return false;
    }

    Console.WriteLine($"Best sample: id={match.SampleId}, label={match.MapName}, score={match.Score:0.000000}, confident={match.IsConfident}");
    Console.WriteLine($"Sample path: {match.SamplePath}");
    return match.IsConfident;
}

static bool ImportMapNameSample(string[] args)
{
    if (args.Length < 3)
    {
        PrintMapNameSamplesHelp();
        return false;
    }

    var imagePath = args[1].Trim().Trim('"');
    var label = args[2].Trim();
    var accept = args.Any(a => string.Equals(a, "--accept", StringComparison.OrdinalIgnoreCase));
    if (!File.Exists(imagePath))
    {
        Console.Error.WriteLine($"FAIL: 地图区域图片不存在：{imagePath}");
        return false;
    }

    if (string.IsNullOrWhiteSpace(label))
    {
        Console.Error.WriteLine("FAIL: 地图名不能为空。");
        return false;
    }

    var raw = LoadCapturePng(imagePath);
    if (raw is null || raw.Width <= 0 || raw.Height <= 0)
    {
        Console.Error.WriteLine($"FAIL: 无法读取地图区域图片：{imagePath}");
        return false;
    }

    var (goldMask, goldPixels) = BuildGoldTextMask(raw, 1);
    if (goldPixels <= 0)
    {
        Console.Error.WriteLine("FAIL: 图片中未提取到金色地图文字像素，请确认传入的是地图名区域原图。");
        return false;
    }

    var safeLabel = SanitizeFileName(label);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var sampleRoot = MapNameSampleRoot();
    Directory.CreateDirectory(sampleRoot);
    var sampleDir = Path.Combine(sampleRoot, $"{stamp}-{safeLabel}");
    Directory.CreateDirectory(sampleDir);

    var rawPath = Path.Combine(sampleDir, "map-region.png");
    var rawScaledPath = Path.Combine(sampleDir, "map-region-x3.png");
    var maskPath = Path.Combine(sampleDir, "map-gold-mask.png");
    var maskScaledPath = Path.Combine(sampleDir, "map-gold-mask-x3.png");
    var sampleJson = Path.Combine(sampleDir, "sample.json");
    var indexJsonl = Path.Combine(sampleRoot, "samples.jsonl");

    var rawScaled = ScaleCaptureNearest(raw, 3);
    var goldMaskScaled = ScaleCaptureNearest(goldMask, 3);
    var savedRaw = SaveCapturePng(raw, rawPath);
    var savedRawScaled = SaveCapturePng(rawScaled, rawScaledPath);
    var savedMask = SaveCapturePng(goldMask, maskPath);
    var savedMaskScaled = SaveCapturePng(goldMaskScaled, maskScaledPath);

    var reviewStatus = accept ? "Accepted" : "NeedsReview";
    var reviewNote = accept
        ? "由离线地图区域图导入并显式接受；导入前应人工核对 map-region-x3.png。"
        : "由离线地图区域图导入；必须人工核对 map-region-x3.png 后才能接受。";
    var sample = new
    {
        capturedAt = DateTimeOffset.Now,
        label,
        safeLabel,
        trusted = accept,
        reviewStatus,
        reviewNote,
        source = "map-name-samples-import",
        mode = "offline-map-name-sample-import-no-process-no-input-no-click",
        sourceImage = Path.GetFullPath(imagePath),
        window = new
        {
            pid = 0,
            title = "",
            bitness = "",
            clientSize = ""
        },
        region = new
        {
            configured = new { X = 0, Y = 0, Width = raw.Width, Height = raw.Height },
            resolved = new { X = 0, Y = 0, Width = raw.Width, Height = raw.Height },
            rightAnchored = false
        },
        recognition = new
        {
            rawText = "",
            goldMaskText = "",
            goldMaskScaledText = "",
            goldPixels
        },
        mask = BuildMapNameMaskJson(goldMask),
        files = new
        {
            raw = rawPath,
            rawScaled = rawScaledPath,
            goldMask = maskPath,
            goldMaskScaled = maskScaledPath
        }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(sampleJson, System.Text.Json.JsonSerializer.Serialize(sample, jsonOptions), new UTF8Encoding(false));

    var indexLineOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = false,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.AppendAllText(indexJsonl, System.Text.Json.JsonSerializer.Serialize(sample, indexLineOptions) + Environment.NewLine, new UTF8Encoding(false));

    Console.WriteLine("Imported map name sample");
    Console.WriteLine($"Image={imagePath}");
    Console.WriteLine($"Label={label}");
    Console.WriteLine($"Accepted={accept}");
    Console.WriteLine($"GoldPixels={goldPixels}");
    Console.WriteLine($"Saved raw={savedRaw}, rawX3={savedRawScaled}, mask={savedMask}, maskX3={savedMaskScaled}");
    Console.WriteLine($"Sample={Path.GetFileName(sampleDir)}");
    Console.WriteLine(sampleJson);
    Console.WriteLine("PASS");
    return savedRaw && savedRawScaled && savedMask && savedMaskScaled && File.Exists(sampleJson);
}

static bool ListMapNameSamples()
{
    Console.WriteLine("Map name samples");
    var sampleFiles = EnumerateMapNameSampleFiles().ToList();
    if (sampleFiles.Count == 0)
    {
        Console.WriteLine("No samples.");
        return true;
    }

    foreach (var sampleFile in sampleFiles)
    {
        var node = ReadSampleNode(sampleFile);
        if (node is null)
        {
            Console.WriteLine($"BROKEN {sampleFile}");
            continue;
        }

        var id = Path.GetFileName(Path.GetDirectoryName(sampleFile));
        var label = ReadString(node, "label");
        var status = ReadString(node, "reviewStatus");
        var trusted = ReadBool(node, "trusted");
        var size = ReadNestedString(node, "window", "clientSize");
        var raw = ReadNestedString(node, "files", "rawScaled");
        Console.WriteLine($"{id} | label={DisplayBlank(label)} | trusted={trusted} | status={DisplayBlank(status)} | size={DisplayBlank(size)}");
        Console.WriteLine($"  {raw}");
    }

    return true;
}

static bool UpdateMapNameSampleReview(string[] args, bool accepted)
{
    if (args.Length < 2 || string.IsNullOrWhiteSpace(args[1]))
    {
        Console.Error.WriteLine(accepted
            ? "FAIL: accept 需要 sample-id-or-path。"
            : "FAIL: reject 需要 sample-id-or-path。");
        PrintMapNameSamplesHelp();
        return false;
    }

    var sampleFile = ResolveMapNameSamplePath(args[1]);
    if (sampleFile is null)
    {
        Console.Error.WriteLine($"FAIL: 未找到样本：{args[1]}");
        return false;
    }

    var node = ReadSampleNode(sampleFile);
    if (node is null)
    {
        Console.Error.WriteLine($"FAIL: 样本 JSON 损坏：{sampleFile}");
        return false;
    }

    if (accepted)
    {
        var label = args.Length >= 3 ? string.Join(' ', args.Skip(2)).Trim() : ReadString(node, "label");
        if (string.IsNullOrWhiteSpace(label))
        {
            Console.Error.WriteLine("FAIL: 接受样本必须有地图名标签。");
            return false;
        }

        node["label"] = label;
        node["safeLabel"] = SanitizeFileName(label);
        node["trusted"] = true;
        node["reviewStatus"] = "Accepted";
        node["acceptedAt"] = DateTimeOffset.Now.ToString("O");
        node["reviewedBy"] = "map-name-samples";
        node["reviewNote"] = "人工复核截图后接受；允许进入后续地图名模板训练/匹配。";
        node["rejectionReason"] = null;
        if (node["mask"] is null)
            TryBackfillMapNameSampleMask(node);
    }
    else
    {
        var reason = args.Length >= 3
            ? string.Join(' ', args.Skip(2)).Trim()
            : "人工复核后拒绝。";
        node["trusted"] = false;
        node["reviewStatus"] = "Rejected";
        node["rejectedAt"] = DateTimeOffset.Now.ToString("O");
        node["reviewedBy"] = "map-name-samples";
        node["rejectionReason"] = reason;
    }

    WriteSampleNode(sampleFile, node);
    RebuildMapNameSampleIndex(verbose: false);

    var id = Path.GetFileName(Path.GetDirectoryName(sampleFile));
    Console.WriteLine($"{(accepted ? "Accepted" : "Rejected")} {id}");
    Console.WriteLine(sampleFile);
    return true;
}

static bool VerifyMapNameSamples()
{
    Console.WriteLine("Verify map name samples");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var matcher = provider.GetRequiredService<IMapNameSampleRecognitionService>();

    var acceptedSamples = EnumerateMapNameSampleFiles()
        .Select(p => (Path: p, Node: ReadSampleNode(p)))
        .Where(x => x.Node is not null
                    && ReadBool(x.Node, "trusted")
                    && string.Equals(ReadString(x.Node, "reviewStatus"), "Accepted", StringComparison.Ordinal))
        .ToList();

    if (acceptedSamples.Count == 0)
    {
        Console.WriteLine("No accepted samples.");
        return true;
    }

    var ok = true;
    foreach (var (samplePath, node) in acceptedSamples)
    {
        var label = ReadString(node!, "label");
        var rawPath = ReadNestedString(node!, "files", "raw");
        var capture = string.IsNullOrWhiteSpace(rawPath) ? null : LoadCapturePng(rawPath);
        if (capture is null)
        {
            Console.WriteLine($"FAIL {Path.GetFileName(Path.GetDirectoryName(samplePath))}: cannot load raw capture");
            ok = false;
            continue;
        }

        var match = matcher.Match(capture);
        var passed = match is not null
                     && match.IsConfident
                     && string.Equals(match.MapName, label, StringComparison.Ordinal);
        Console.WriteLine(passed
            ? $"PASS {Path.GetFileName(Path.GetDirectoryName(samplePath))}: {match!.MapName}, score={match.Score:0.000}"
            : $"FAIL {Path.GetFileName(Path.GetDirectoryName(samplePath))}: expected={label}, got={match?.MapName ?? "-"}, score={match?.Score.ToString("0.000") ?? "-"}, confident={match?.IsConfident.ToString() ?? "-"}");
        ok &= passed;
    }

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool AuditMapNameSamples()
{
    Console.WriteLine("Map name sample audit");

    var sampleFiles = EnumerateMapNameSampleFiles().ToList();
    var entries = new List<object>();
    var broken = new List<object>();
    var accepted = new List<(string Id, string Label, string SafeLabel, string Suffix, string Path, bool HasMask, bool DirectoryLabelMismatch)>();
    var trustedStatusIssues = new List<object>();
    var missingMask = new List<object>();
    var directoryMismatches = new List<object>();

    foreach (var sampleFile in sampleFiles)
    {
        var id = Path.GetFileName(Path.GetDirectoryName(sampleFile)) ?? "";
        var node = ReadSampleNode(sampleFile);
        if (node is null)
        {
            broken.Add(new { id, path = sampleFile, reason = "sample.json cannot be parsed" });
            continue;
        }

        var label = ReadString(node, "label");
        var safeLabel = ReadString(node, "safeLabel");
        if (string.IsNullOrWhiteSpace(safeLabel) && !string.IsNullOrWhiteSpace(label))
            safeLabel = SanitizeFileName(label);
        var status = ReadString(node, "reviewStatus");
        var trusted = ReadBool(node, "trusted");
        var suffix = ExtractMapSampleDirectorySuffix(id);
        var hasMask = node["mask"] is JsonObject mask
                      && mask["Rows"] is JsonArray rows
                      && rows.Count > 0;
        var isAccepted = trusted && string.Equals(status, "Accepted", StringComparison.Ordinal);
        var directoryLabelMismatch = isAccepted
                                     && !string.IsNullOrWhiteSpace(suffix)
                                     && !string.IsNullOrWhiteSpace(safeLabel)
                                     && !string.Equals(suffix, safeLabel, StringComparison.Ordinal);

        if (trusted && !string.Equals(status, "Accepted", StringComparison.Ordinal))
        {
            trustedStatusIssues.Add(new { id, label, trusted, status, path = sampleFile });
        }

        if (isAccepted)
        {
            accepted.Add((id, label, safeLabel, suffix, sampleFile, hasMask, directoryLabelMismatch));
            if (!hasMask)
                missingMask.Add(new { id, label, path = sampleFile });
            if (directoryLabelMismatch)
                directoryMismatches.Add(new { id, directorySuffix = suffix, label, safeLabel, path = sampleFile });
        }

        entries.Add(new
        {
            id,
            label,
            safeLabel,
            reviewStatus = status,
            trusted,
            directorySuffix = suffix,
            hasMask,
            directoryLabelMismatch,
            path = sampleFile
        });
    }

    var duplicateLabels = accepted
        .Where(e => !string.IsNullOrWhiteSpace(e.Label))
        .GroupBy(e => e.Label, StringComparer.Ordinal)
        .Where(g => g.Count() > 1)
        .Select(g => new
        {
            label = g.Key,
            count = g.Count(),
            samples = g.Select(e => e.Id).ToArray()
        })
        .ToArray();

    var issues =
        broken.Count
        + trustedStatusIssues.Count
        + missingMask.Count
        + directoryMismatches.Count;

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "map-name-sample-audit", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var jsonPath = Path.Combine(evidenceDir, "map-name-sample-audit.json");
    var mdPath = Path.Combine(evidenceDir, "map-name-sample-audit.md");

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "map-name-sample-audit-readonly-no-game-window",
        safety = new
        {
            visitsGameWindow = false,
            sendsInput = false,
            clicksMouse = false,
            writesProfile = false,
            writesSamples = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false
        },
        root = MapNameSampleRoot(),
        total = sampleFiles.Count,
        accepted = accepted.Count,
        rejected = entries.Count(e => string.Equals(GetAnonymousString(e, "reviewStatus"), "Rejected", StringComparison.Ordinal)),
        needsReview = entries.Count(e => string.Equals(GetAnonymousString(e, "reviewStatus"), "NeedsReview", StringComparison.Ordinal)),
        broken = broken.Count,
        issues,
        issueBreakdown = new
        {
            broken = broken.Count,
            trustedStatusIssues = trustedStatusIssues.Count,
            missingMask = missingMask.Count,
            directoryMismatches = directoryMismatches.Count,
            duplicateAcceptedLabels = duplicateLabels.Length
        },
        brokenSamples = broken,
        trustedStatusIssueSamples = trustedStatusIssues,
        missingMaskSamples = missingMask,
        directoryMismatchSamples = directoryMismatches,
        duplicateLabels,
        entries
    };
    File.WriteAllText(jsonPath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    var md = new StringBuilder();
    md.AppendLine("# Map Name Sample Audit");
    md.AppendLine();
    md.AppendLine($"- CapturedAt: {DateTimeOffset.Now:O}");
    md.AppendLine($"- Root: {MapNameSampleRoot()}");
    md.AppendLine($"- Total: {sampleFiles.Count}");
    md.AppendLine($"- Accepted: {accepted.Count}");
    md.AppendLine($"- Issues: {issues}");
    md.AppendLine("- Safety: read-only local sample audit; no game window, no input, no profile write.");
    md.AppendLine();
    md.AppendLine("## Issue Breakdown");
    md.AppendLine();
    md.AppendLine($"- Broken: {broken.Count}");
    md.AppendLine($"- TrustedStatusIssues: {trustedStatusIssues.Count}");
    md.AppendLine($"- MissingMask: {missingMask.Count}");
    md.AppendLine($"- DirectoryMismatches: {directoryMismatches.Count}");
    md.AppendLine($"- DuplicateAcceptedLabels: {duplicateLabels.Length}");
    md.AppendLine();
    if (directoryMismatches.Count > 0)
    {
        md.AppendLine("## Directory Mismatches");
        md.AppendLine();
        foreach (var item in directoryMismatches)
            md.AppendLine($"- {System.Text.Json.JsonSerializer.Serialize(item, JsonOptions())}");
        md.AppendLine();
    }
    if (missingMask.Count > 0)
    {
        md.AppendLine("## Missing Mask");
        md.AppendLine();
        foreach (var item in missingMask)
            md.AppendLine($"- {System.Text.Json.JsonSerializer.Serialize(item, JsonOptions())}");
        md.AppendLine();
    }
    if (duplicateLabels.Length > 0)
    {
        md.AppendLine("## Duplicate Accepted Labels");
        md.AppendLine();
        foreach (var item in duplicateLabels)
            md.AppendLine($"- {System.Text.Json.JsonSerializer.Serialize(item, JsonOptions())}");
        md.AppendLine();
    }
    md.AppendLine("## Evidence");
    md.AppendLine();
    md.AppendLine($"- JSON: {jsonPath}");
    File.WriteAllText(mdPath, md.ToString(), new UTF8Encoding(false));

    Console.WriteLine($"Total={sampleFiles.Count}");
    Console.WriteLine($"Accepted={accepted.Count}");
    Console.WriteLine($"Issues={issues}");
    Console.WriteLine($"Broken={broken.Count}");
    Console.WriteLine($"TrustedStatusIssues={trustedStatusIssues.Count}");
    Console.WriteLine($"MissingMask={missingMask.Count}");
    Console.WriteLine($"DirectoryMismatches={directoryMismatches.Count}");
    Console.WriteLine($"DuplicateAcceptedLabels={duplicateLabels.Length}");
    Console.WriteLine($"Evidence={jsonPath}");
    Console.WriteLine($"Markdown={mdPath}");
    Console.WriteLine(issues == 0 ? "PASS" : "FAIL");
    return issues == 0;
}

static string ExtractMapSampleDirectorySuffix(string id)
{
    const int stampLength = 15; // yyyyMMdd-HHmmss
    return id.Length > stampLength + 1 && id[stampLength] == '-'
        ? id[(stampLength + 1)..]
        : "";
}

static string GetAnonymousString(object value, string propertyName)
{
    var property = value.GetType().GetProperty(propertyName);
    return property?.GetValue(value)?.ToString() ?? "";
}

static bool RebuildMapNameSampleIndex(bool verbose)
{
    var root = MapNameSampleRoot();
    Directory.CreateDirectory(root);
    var indexPath = Path.Combine(root, "samples.jsonl");
    var sampleFiles = EnumerateMapNameSampleFiles().ToList();
    var compactOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = false,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    using var writer = new StreamWriter(indexPath, append: false, new UTF8Encoding(false));
    var count = 0;
    foreach (var sampleFile in sampleFiles)
    {
        var node = ReadSampleNode(sampleFile);
        if (node is null)
            continue;

        writer.WriteLine(node.ToJsonString(compactOptions));
        count++;
    }

    if (verbose)
    {
        Console.WriteLine($"Rebuilt {indexPath}");
        Console.WriteLine($"Samples={count}");
    }

    return true;
}

static IEnumerable<string> EnumerateMapNameSampleFiles()
{
    var root = MapNameSampleRoot();
    if (!Directory.Exists(root))
        yield break;

    foreach (var dir in Directory.EnumerateDirectories(root).OrderBy(Path.GetFileName, StringComparer.Ordinal))
    {
        var sample = Path.Combine(dir, "sample.json");
        if (File.Exists(sample))
            yield return sample;
    }
}

static string? ResolveMapNameSamplePath(string idOrPath)
{
    if (string.IsNullOrWhiteSpace(idOrPath))
        return null;

    var value = idOrPath.Trim().Trim('"');
    if (File.Exists(value))
        return Path.GetFileName(value).Equals("sample.json", StringComparison.OrdinalIgnoreCase) ? value : null;

    if (Directory.Exists(value))
    {
        var sample = Path.Combine(value, "sample.json");
        return File.Exists(sample) ? sample : null;
    }

    var root = MapNameSampleRoot();
    var direct = Path.Combine(root, value, "sample.json");
    if (File.Exists(direct))
        return direct;

    var match = Directory.Exists(root)
        ? Directory.EnumerateDirectories(root)
            .Select(d => Path.Combine(d, "sample.json"))
            .FirstOrDefault(p => File.Exists(p)
                                 && Path.GetFileName(Path.GetDirectoryName(p))?.Contains(value, StringComparison.OrdinalIgnoreCase) == true)
        : null;

    return match;
}

static JsonObject? ReadSampleNode(string sampleFile)
{
    try
    {
        return JsonNode.Parse(File.ReadAllText(sampleFile, Encoding.UTF8)) as JsonObject;
    }
    catch
    {
        return null;
    }
}

static void WriteSampleNode(string sampleFile, JsonObject node)
{
    var options = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(sampleFile, node.ToJsonString(options), new UTF8Encoding(false));
}

static string MapNameSampleRoot() =>
    Path.Combine(Environment.CurrentDirectory, "data", "samples", "map-names");

static string ReadString(JsonObject node, string name) =>
    node[name]?.GetValue<string>() ?? "";

static string ReadNestedString(JsonObject node, string objectName, string name) =>
    node[objectName] is JsonObject child ? ReadString(child, name) : "";

static bool ReadBool(JsonObject node, string name) =>
    node[name]?.GetValue<bool>() ?? false;

static string DisplayBlank(string value) =>
    string.IsNullOrWhiteSpace(value) ? "-" : value;

static object BuildMapNameMaskJson(CaptureResult mask)
{
    return new
    {
        mask.Width,
        mask.Height,
        Rows = BuildMapNameMaskRows(mask)
    };
}

static string[] BuildMapNameMaskRows(CaptureResult mask)
{
    var rows = new string[mask.Height];
    for (var y = 0; y < mask.Height; y++)
    {
        var chars = new char[mask.Width];
        for (var x = 0; x < mask.Width; x++)
            chars[x] = IsDarkMaskPixel(mask, x, y) ? '#' : '.';
        rows[y] = new string(chars);
    }

    return rows;
}

static void TryBackfillMapNameSampleMask(JsonObject node)
{
    var maskPath = ReadNestedString(node, "files", "goldMask");
    if (string.IsNullOrWhiteSpace(maskPath) || !File.Exists(maskPath))
        return;

    var capture = LoadCapturePng(maskPath);
    if (capture is null)
        return;

    var rows = BuildMapNameMaskRows(capture);
    node["mask"] = new JsonObject
    {
        ["width"] = capture.Width,
        ["height"] = capture.Height,
        ["rows"] = new JsonArray(rows.Select(r => JsonValue.Create(r)).ToArray<JsonNode?>())
    };
}

static (string Label, string SampleId, double Score, string SamplePath)? MatchAcceptedMapNameSamples(CaptureResult currentMask)
{
    var best = (Label: "", SampleId: "", Score: 0.0, SamplePath: "");
    foreach (var sampleFile in EnumerateMapNameSampleFiles())
    {
        var node = ReadSampleNode(sampleFile);
        if (node is null)
            continue;

        if (!ReadBool(node, "trusted")
            || !string.Equals(ReadString(node, "reviewStatus"), "Accepted", StringComparison.Ordinal))
        {
            continue;
        }

        var label = ReadString(node, "label");
        var maskPath = ReadNestedString(node, "files", "goldMask");
        if (string.IsNullOrWhiteSpace(label) || !File.Exists(maskPath))
            continue;

        var sampleMask = LoadCapturePng(maskPath);
        if (sampleMask is null)
            continue;

        var score = CompareGoldMasks(currentMask, sampleMask);
        if (score <= best.Score)
            continue;

        best = (label, Path.GetFileName(Path.GetDirectoryName(sampleFile)) ?? "-", score, sampleFile);
    }

    return best.Score > 0 ? best : null;
}

static double CompareGoldMasks(CaptureResult current, CaptureResult sample)
{
    if (current.Width <= 0 || current.Height <= 0 || sample.Width <= 0 || sample.Height <= 0)
        return 0;

    var normalized = current.Width == sample.Width && current.Height == sample.Height
        ? current
        : ResizeCaptureNearest(current, sample.Width, sample.Height);

    var intersection = 0;
    var union = 0;
    for (var y = 0; y < sample.Height; y++)
    {
        for (var x = 0; x < sample.Width; x++)
        {
            var currentDark = IsDarkMaskPixel(normalized, x, y);
            var sampleDark = IsDarkMaskPixel(sample, x, y);
            if (currentDark && sampleDark)
                intersection++;
            if (currentDark || sampleDark)
                union++;
        }
    }

    return union == 0 ? 0 : intersection / (double)union;
}

static bool IsDarkMaskPixel(CaptureResult image, int x, int y)
{
    var p = (y * image.Width + x) * 4;
    if (p < 0 || p + 2 >= image.Pixels.Length)
        return false;

    return image.Pixels[p] + image.Pixels[p + 1] + image.Pixels[p + 2] < 384;
}

static CaptureResult ResizeCaptureNearest(CaptureResult image, int width, int height)
{
    var pixels = new byte[width * height * 4];
    for (var y = 0; y < height; y++)
    {
        var sourceY = Math.Min(image.Height - 1, (int)Math.Round(y * (image.Height - 1) / (double)Math.Max(1, height - 1)));
        for (var x = 0; x < width; x++)
        {
            var sourceX = Math.Min(image.Width - 1, (int)Math.Round(x * (image.Width - 1) / (double)Math.Max(1, width - 1)));
            var source = (sourceY * image.Width + sourceX) * 4;
            var target = (y * width + x) * 4;
            pixels[target] = image.Pixels[source];
            pixels[target + 1] = image.Pixels[source + 1];
            pixels[target + 2] = image.Pixels[source + 2];
            pixels[target + 3] = image.Pixels[source + 3];
        }
    }

    return new CaptureResult(width, height, pixels);
}

static CaptureResult? CropCapture(CaptureResult source, OcrResolvedRegion region)
{
    if (region.IsEmpty)
        return null;

    var dst = new byte[region.Width * region.Height * 4];
    var srcStride = source.Width * 4;
    var dstStride = region.Width * 4;
    for (var row = 0; row < region.Height; row++)
        Array.Copy(source.Pixels, (region.Y + row) * srcStride + region.X * 4, dst, row * dstStride, dstStride);

    return new CaptureResult(region.Width, region.Height, dst);
}

static CaptureResult? CropCaptureRect(CaptureResult source, int x, int y, int width, int height)
{
    if (width <= 0 || height <= 0)
        return null;

    var left = Math.Clamp(x, 0, Math.Max(0, source.Width - 1));
    var top = Math.Clamp(y, 0, Math.Max(0, source.Height - 1));
    var right = Math.Clamp(x + width, left + 1, source.Width);
    var bottom = Math.Clamp(y + height, top + 1, source.Height);
    var cropWidth = right - left;
    var cropHeight = bottom - top;
    if (cropWidth <= 0 || cropHeight <= 0)
        return null;

    var dst = new byte[cropWidth * cropHeight * 4];
    var srcStride = source.Width * 4;
    var dstStride = cropWidth * 4;
    for (var row = 0; row < cropHeight; row++)
        Array.Copy(source.Pixels, (top + row) * srcStride + left * 4, dst, row * dstStride, dstStride);

    return new CaptureResult(cropWidth, cropHeight, dst);
}

static (CaptureResult Mask, int GoldPixelCount) BuildGoldTextMask(CaptureResult image, int scale)
{
    if (scale <= 0)
        scale = 1;

    var width = image.Width * scale;
    var height = image.Height * scale;
    var pixels = new byte[width * height * 4];
    Array.Fill<byte>(pixels, 255);

    var goldPixels = 0;
    for (var y = 0; y < image.Height; y++)
    {
        for (var x = 0; x < image.Width; x++)
        {
            var p = (y * image.Width + x) * 4;
            var b = image.Pixels[p];
            var g = image.Pixels[p + 1];
            var r = image.Pixels[p + 2];
            if (!IsGoldMapTextPixel(r, g, b))
                continue;

            goldPixels++;
            for (var sy = 0; sy < scale; sy++)
            {
                for (var sx = 0; sx < scale; sx++)
                    SetPixel(pixels, width, x * scale + sx, y * scale + sy, 0, 0, 0);
            }
        }
    }

    return (new CaptureResult(width, height, pixels), goldPixels);
}

static CaptureResult ScaleCaptureNearest(CaptureResult image, int scale)
{
    if (scale <= 1)
        return image;

    var width = image.Width * scale;
    var height = image.Height * scale;
    var pixels = new byte[width * height * 4];
    for (var y = 0; y < height; y++)
    {
        var sourceY = y / scale;
        for (var x = 0; x < width; x++)
        {
            var sourceX = x / scale;
            var source = (sourceY * image.Width + sourceX) * 4;
            var target = (y * width + x) * 4;
            pixels[target] = image.Pixels[source];
            pixels[target + 1] = image.Pixels[source + 1];
            pixels[target + 2] = image.Pixels[source + 2];
            pixels[target + 3] = image.Pixels[source + 3];
        }
    }

    return new CaptureResult(width, height, pixels);
}

static bool IsGoldMapTextPixel(byte r, byte g, byte b)
{
    return r >= 145
           && g >= 105
           && b <= 120
           && r >= g
           && g >= b + 20
           && r + g >= 285;
}

static string SanitizeFileName(string value)
{
    var invalid = Path.GetInvalidFileNameChars();
    var cleaned = new string(value
        .Trim()
        .Select(ch => invalid.Contains(ch) || char.IsControl(ch) ? '_' : ch)
        .ToArray());

    cleaned = string.Join("_", cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries));
    return string.IsNullOrWhiteSpace(cleaned) ? "unknown" : cleaned[..Math.Min(cleaned.Length, 40)];
}

static string QuotePowerShellArg(string value) => $"'{(value ?? string.Empty).Replace("'", "''")}'";

static bool HasReliableRuntimeMap(NavigationRecognitionResult navigation) =>
    navigation.HasMap
    && !string.Equals(navigation.MapNameSource, "manual-confirmed-map", StringComparison.OrdinalIgnoreCase);

static string BuildSceneFieldReason(NavigationRecognitionResult navigation, bool mapVisual, bool coordinateVisual)
{
    if (HasReliableRuntimeMap(navigation) && navigation.HasCoordinate)
        return "地图和坐标均已识别，可作为回点字段候选。";

    if (navigation.HasMap && !HasReliableRuntimeMap(navigation))
        return $"地图仅来自手动确认({navigation.MapNameText})，不是实时识别结果；为避免跨地图误回点，自动回点禁止触发。";

    if (!mapVisual && !coordinateVisual)
        return "地图和坐标裁剪区均无有效视觉内容；可能未进入游戏世界、窗口被遮挡、截图失败或识别区域严重错位。";

    if (!navigation.HasMap && !navigation.HasCoordinate)
        return "地图和坐标均未识别；可能未进入游戏世界、当前界面没有小地图坐标、区域偏移或 OCR 字库不足。";

    if (!navigation.HasCoordinate)
        return "已看到坐标裁剪区但未解析出坐标；自动回点禁止触发，需要进入游戏世界、校准坐标区域或补充识别模板。";

    return "已识别坐标但未识别地图名；为避免跨地图误回点，自动回点禁止触发，需要确认地图名区域或人工确认地图。";
}

static string BuildDeathReturnGateReason(ReturnPointConfig config, DeathRecognitionResult death, bool deathVisual)
{
    if (!deathVisual)
        return "死亡识别区域没有有效视觉内容；可能未进入游戏世界、窗口被遮挡或死亡区域偏移，禁止触发死亡回点。";

    if (string.IsNullOrWhiteSpace(death.Text))
        return "死亡识别区域未识别出文本；当前不能作为死亡回点依据。";

    if (!death.IsDead)
        return "未命中死亡关键词；禁止触发死亡回点。";

    if (!config.EnableDeathReturn)
        return "已命中死亡关键词，但当前配置未启用死亡回点；诊断不执行动作。";

    if (config.Points.Count == 0)
        return "已命中死亡关键词，但没有可用回点坐标；禁止触发死亡回点。";

    if (config.DeathReturnNavigation.Mode == ReturnNavigationMode.Disabled)
        return "已命中死亡关键词，但死亡返回动作未配置；禁止触发死亡回点。";

    return "已命中死亡关键词且配置具备死亡回点条件；本诊断仍只读取证据，不执行动作。";
}

static object RegionEvidence(OcrRegionConfig configured, OcrResolvedRegion resolved, string path, bool saved, CaptureResult? capture) => new
{
    configured = new
    {
        configured.Enabled,
        configured.X,
        configured.Y,
        configured.Width,
        configured.Height
    },
    resolved = new
    {
        resolved.X,
        resolved.Y,
        resolved.Width,
        resolved.Height,
        resolved.IsEmpty
    },
    path,
    saved,
    visual = HasVisualContent(capture)
};

static ReturnPoint? FindNearestReturnPoint(ReturnPointConfig config, NavigationRecognitionResult navigation)
{
    if (!HasReliableRuntimeMap(navigation) || !navigation.HasCoordinate)
        return null;

    var sameMap = config.Points
        .Where(p => p.MapName.Contains(navigation.MapNameText, StringComparison.Ordinal)
                    || navigation.MapNameText.Contains(p.MapName, StringComparison.Ordinal))
        .ToList();
    if (sameMap.Count == 0)
        return null;

    return sameMap
        .OrderBy(p => Distance(navigation.X!.Value, navigation.Y!.Value, p.X, p.Y))
        .FirstOrDefault();
}

static ReturnPoint? FindPreferredDeathReturnPoint(ReturnPointConfig config) =>
    config.Points.FirstOrDefault(p => p.Kind == ReturnPointKind.DeathReturn)
    ?? config.Points.FirstOrDefault();

static double Distance(int x1, int y1, int x2, int y2)
{
    var dx = x1 - x2;
    var dy = y1 - y2;
    return Math.Sqrt(dx * dx + dy * dy);
}

static (int TotalFiles, int LoadedFiles, int SkippedFiles, int LoadedGlyphs) LoadDiagnosticOcrDictionaries(
    ITemplateOcrService ocr,
    IReadOnlyList<string> dictionaryFiles,
    int maxFileBytes = 120_000,
    int maxFiles = 8)
{
    var before = ocr.LoadedGlyphCount;
    var loadedFiles = 0;
    var skippedFiles = 0;

    foreach (var file in dictionaryFiles.OrderBy(DictionaryLoadPriority).ThenBy(Path.GetFileName, StringComparer.OrdinalIgnoreCase))
    {
        var info = new FileInfo(file);
        if (!info.Exists)
        {
            skippedFiles++;
            continue;
        }

        if (loadedFiles >= maxFiles || (info.Length > maxFileBytes && !IsHighPriorityDictionary(file)))
        {
            skippedFiles++;
            continue;
        }

        ocr.LoadDictionary(file);
        loadedFiles++;
    }

    return (
        dictionaryFiles.Count,
        loadedFiles,
        skippedFiles,
        Math.Max(0, ocr.LoadedGlyphCount - before));
}

static int DictionaryLoadPriority(string path)
{
    var name = Path.GetFileName(path).ToLowerInvariant();
    if (name.Contains("number", StringComparison.Ordinal) || name.Contains("sample", StringComparison.Ordinal))
        return 0;
    if (name.Contains("aj", StringComparison.Ordinal))
        return 1;
    if (name.Contains("dungeon", StringComparison.Ordinal))
        return 2;
    return 10;
}

static bool IsHighPriorityDictionary(string path) => DictionaryLoadPriority(path) <= 1;

static ReturnPointEvidencePrediction PredictDeathReturnAction(ReturnPointConfig config, DeathRecognitionResult death)
{
    if (!config.EnableDeathReturn)
        return new("None", false, "死亡回点未启用。");

    if (config.Points.Count == 0)
        return new("None", false, "未配置回点坐标，死亡回点无法执行。");

    if (!death.IsDead)
        return new("None", false, "未检测到死亡提示。");

    if (config.DeathReturnNavigation.Mode == ReturnNavigationMode.Disabled)
        return new(nameof(ReturnPointRuntimeAction.DeathReturn), false, "检测到死亡提示，但死亡返回动作未配置。");

    return new(nameof(ReturnPointRuntimeAction.DeathReturn), true, $"检测到死亡关键词：{death.MatchedKeyword}");
}

static ReturnPointConfig CopyReturnPointConfigForPrediction(ReturnPointConfig source) =>
    new()
    {
        ProfileName = source.ProfileName,
        EnableFixedFarmReturn = source.EnableFixedFarmReturn,
        EnableEarthSpiritReturn = source.EnableEarthSpiritReturn,
        EnableDeathReturn = source.EnableDeathReturn,
        EnableStuckRecovery = source.EnableStuckRecovery,
        CheckIntervalMs = source.CheckIntervalMs,
        ArrivalDistance = source.ArrivalDistance,
        StuckTimeoutMs = source.StuckTimeoutMs,
        ReturnRetryLimit = source.ReturnRetryLimit,
        ReturnTravelWaitMs = source.ReturnTravelWaitMs,
        NavigationRecognition = source.NavigationRecognition,
        DeathRecognition = source.DeathRecognition,
        ReturnNavigation = source.ReturnNavigation,
        EarthSpiritNavigation = source.EarthSpiritNavigation,
        StuckRecoveryNavigation = source.StuckRecoveryNavigation,
        DeathReturnNavigation = new ReturnNavigationConfig
        {
            Mode = source.DeathReturnNavigation.Mode,
            Hotkey = source.DeathReturnNavigation.Hotkey,
            OpenMapDelayMs = source.DeathReturnNavigation.OpenMapDelayMs,
            ClickX = source.DeathReturnNavigation.ClickX,
            ClickY = source.DeathReturnNavigation.ClickY,
            ActionIntervalMs = source.DeathReturnNavigation.ActionIntervalMs,
            DispatchMode = source.DeathReturnNavigation.DispatchMode
        },
        Points = source.Points.ToList()
    };

static ReturnPointEvidencePrediction PredictReturnPointAction(
    ReturnPointConfig config,
    NavigationRecognitionResult navigation,
    DeathRecognitionResult death,
    ReturnPoint? nearest,
    double? distance)
{
    if (!config.EnableFixedFarmReturn && !config.EnableEarthSpiritReturn && !config.EnableDeathReturn && !config.EnableStuckRecovery)
        return new("None", false, "返点未启用。");

    if (config.Points.Count == 0)
        return new("None", false, "未配置返点坐标。");

    if (config.EnableDeathReturn && death.IsDead)
        return new(nameof(ReturnPointRuntimeAction.DeathReturn), true, $"检测到死亡关键词：{death.MatchedKeyword}");

    if (!navigation.HasCoordinate)
        return new(nameof(ReturnPointRuntimeAction.MissingNavigation), false, BuildSceneFieldReason(navigation, mapVisual: true, coordinateVisual: true));

    if (!navigation.HasMap)
        return new(nameof(ReturnPointRuntimeAction.MissingNavigation), false, BuildSceneFieldReason(navigation, mapVisual: true, coordinateVisual: true));

    if (nearest is null || distance is null)
        return new(nameof(ReturnPointRuntimeAction.None), false, "当前地图没有同地图返点坐标，禁止跨地图回点。");

    if (distance.Value <= config.ArrivalDistance)
        return new(nameof(ReturnPointRuntimeAction.InRange), false, $"当前位置在到达距离内：{distance.Value:0.0} <= {config.ArrivalDistance}。");

    if (config.EnableEarthSpiritReturn)
        return new(nameof(ReturnPointRuntimeAction.EarthSpiritReturn), true, $"距离返点 {distance.Value:0.0}，土灵返点优先。");

    if (config.EnableFixedFarmReturn)
        return new(nameof(ReturnPointRuntimeAction.ReturnToPoint), true, $"距离返点 {distance.Value:0.0}，需要执行普通返点。");

    if (config.EnableStuckRecovery)
        return new("MonitorOnly", false, "仅启用卡点恢复，需要连续运动样本判断。");

    return new("None", false, "当前配置不会触发返点动作。");
}

static bool RunLiveBagCalibrationDiagnostics()
{
    Console.WriteLine("Live bag calibration diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var log = new RuntimeLogService();
    var binding = new WindowBindingService(log);
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var capture = new WindowCaptureService(log);
    var client = capture.CaptureClient(window.Hwnd);
    var inventory = new InventoryRecognitionService(capture, log);
    var calibration = inventory.AutoCalibrate(window);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-bag-calibration");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}-{stamp}.png");
    var evidencePath = Path.Combine(evidenceDir, $"bag-calibration-{window.Pid}-{stamp}.json");
    var clientSaved = SaveCapturePng(client, clientPath);
    var clientVisual = HasVisualContent(client);

    var status = calibration.Success ? "CALIBRATED" : "NOT_DETECTED";
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-no-click-no-sell",
        status,
        message = calibration.Message,
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        capture = new
        {
            client = client is null ? null : new { client.Width, client.Height, saved = clientSaved, visual = clientVisual, path = clientPath }
        },
        grid = calibration.Grid is null
            ? null
            : new
            {
                calibration.Grid.X,
                calibration.Grid.Y,
                calibration.Grid.Columns,
                calibration.Grid.Rows,
                calibration.Grid.CellWidth,
                calibration.Grid.CellHeight,
                calibration.Grid.GapX,
                calibration.Grid.GapY
            },
        preview = calibration.PreviewScan is null
            ? null
            : new
            {
                calibration.PreviewScan.Success,
                calibration.PreviewScan.OccupiedCount,
                calibration.PreviewScan.EmptyCount,
                calibration.PreviewScan.Width,
                calibration.PreviewScan.Height
            }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Title={window.Title}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Capture client={client?.Width}x{client?.Height}, saved={clientSaved}, visual={clientVisual}, path={clientPath}");
    Console.WriteLine($"Status={status}");
    Console.WriteLine($"Message={calibration.Message}");
    if (calibration.Grid is not null)
    {
        Console.WriteLine($"Grid=({calibration.Grid.X},{calibration.Grid.Y}) {calibration.Grid.Columns}x{calibration.Grid.Rows}, cell={calibration.Grid.CellWidth}x{calibration.Grid.CellHeight}, gap={calibration.Grid.GapX}/{calibration.Grid.GapY}");
        Console.WriteLine($"Preview occupied={calibration.PreviewScan?.OccupiedCount}, empty={calibration.PreviewScan?.EmptyCount}");
    }
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && client is { Width: > 0, Height: > 0 }
             && clientSaved
             && clientVisual
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && (!calibration.Success || calibration is { Grid: not null, PreviewScan.Success: true });

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveBagGridProbeDiagnostics(string[] args)
{
    Console.WriteLine("Live bag grid probe diagnostics");
    var maxCandidates = Math.Clamp(ReadIntOption(args, "--max", 5), 1, 12);
    var requestedPid = ReadIntOption(args, "--pid", 0);

    var games = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .ToArray();
    var game = requestedPid > 0
        ? games.FirstOrDefault(p => p.Id == requestedPid)
        : games.FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine(requestedPid > 0
            ? $"FAIL: 未找到正在运行的 Game.exe PID={requestedPid} 主窗口。"
            : "FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var log = new RuntimeLogService();
    var binding = new WindowBindingService(log);
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var capture = new WindowCaptureService(log);
    var client = capture.CaptureClient(window.Hwnd);
    if (client is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var registry = new ModelArtifactRegistry();
    using var interactionWindows = new InteractionWindowDetectService(registry, log);
    var interactionControls = new InteractionControlCatalogService(log);
    var inventory = new InventoryRecognitionService(capture, log, interactionWindows, interactionControls);
    var probe = inventory.ProbeGridCandidates(client, maxCandidates);
    var interaction = interactionWindows.Detect(client);
    var bagPanel = interaction.Detections
        .Where(item => string.Equals(item.ClassName, "bag_panel", StringComparison.Ordinal))
        .OrderByDescending(item => item.Confidence)
        .FirstOrDefault();
    var bagLayout = bagPanel is null ? null : interactionControls.Map(client.Sequence, bagPanel);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-bag-grid-probe", DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}.png");
    var evidencePath = Path.Combine(evidenceDir, $"bag-grid-probe-{window.Pid}.json");
    var controlsOverlayPath = Path.Combine(evidenceDir, $"interaction-v3-{window.Pid}.png");
    var clientSaved = SaveCapturePng(client, clientPath);
    var clientVisual = HasVisualContent(client);
    var controlsOverlayError = "";
    var controlsOverlaySaved = bagLayout is not null
                               && interactionControls.TryRenderDebugOverlay(
                                   client,
                                   [bagLayout],
                                   controlsOverlayPath,
                                   out controlsOverlayError);
    var controlsOverlayMessage = controlsOverlaySaved ? "" : controlsOverlayError;
    var overlays = new List<object>();
    var index = 0;
    foreach (var candidate in probe.Candidates)
    {
        index++;
        var overlayPath = Path.Combine(evidenceDir, $"candidate-{index:00}-score-{candidate.Score:0.000}.png");
        var overlaySaved = SaveGridOverlayPng(client, candidate.Grid, overlayPath);
        overlays.Add(new
        {
            index,
            overlayPath,
            overlaySaved,
            candidate.Score,
            candidate.IsLikelyInventory,
            candidate.Source,
            candidate.Grid.X,
            candidate.Grid.Y,
            candidate.Grid.Columns,
            candidate.Grid.Rows,
            candidate.Grid.CellWidth,
            candidate.Grid.CellHeight,
            candidate.Grid.GapX,
            candidate.Grid.GapY
        });
    }

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-bag-grid-probe-no-click-no-sell",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            sellsItems = false,
            modifiesInventory = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        capture = new
        {
            client.Width,
            client.Height,
            clientSaved,
            clientVisual,
            clientPath,
            controlsOverlaySaved,
            controlsOverlayPath,
            controlsOverlayMessage
        },
        interactionV3 = new
        {
            interaction.Available,
            interaction.ModelVersion,
            interaction.InferenceMilliseconds,
            panel = bagPanel is null
                ? null
                : new
                {
                    bagPanel.ClassName,
                    bagPanel.Confidence,
                    bagPanel.Box.X,
                    bagPanel.Box.Y,
                    bagPanel.Box.Width,
                    bagPanel.Box.Height,
                    frameSequence = interaction.FrameSequence
                },
            layout = bagLayout is null
                ? null
                : new
                {
                    bagLayout.FrameSequence,
                    bagLayout.AssetVersion,
                    bagLayout.RuntimeAuthorized,
                    bagLayout.Message,
                    bagCells = bagLayout.Regions
                        .Where(region => region.RegionId == "bag_cells")
                        .Select(region => new
                        {
                            region.Rows,
                            region.Columns,
                            count = region.Cells.Count,
                            cells = region.Cells.Select(cell => new
                            {
                                cell.Row,
                                cell.Column,
                                cell.CellBox.X,
                                cell.CellBox.Y,
                                cell.CellBox.Width,
                                cell.CellBox.Height,
                                clickX = cell.CellBox.X + cell.CellBox.Width / 2,
                                clickY = cell.CellBox.Y + cell.CellBox.Height / 2
                            }).ToArray()
                        }).FirstOrDefault()
                }
        },
        probe = new
        {
            probe.Success,
            probe.Message,
            requestedMax = maxCandidates,
            count = probe.Candidates.Count
        },
        candidates = overlays
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Title={window.Title}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Capture client={client.Width}x{client.Height}, saved={clientSaved}, visual={clientVisual}, path={clientPath}");
    Console.WriteLine($"Probe success={probe.Success}, count={probe.Candidates.Count}, message={probe.Message}");
    index = 0;
    foreach (var candidate in probe.Candidates)
    {
        index++;
        Console.WriteLine($"Candidate {index}: score={candidate.Score:0.000}, likely={candidate.IsLikelyInventory}, source={candidate.Source}, grid=({candidate.Grid.X},{candidate.Grid.Y}) {candidate.Grid.Columns}x{candidate.Grid.Rows}, cell={candidate.Grid.CellWidth}x{candidate.Grid.CellHeight}, gap={candidate.Grid.GapX}/{candidate.Grid.GapY}");
    }
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && clientSaved
             && clientVisual
             && controlsOverlaySaved
             && bagPanel is { Confidence: >= 0.75 }
             && bagLayout is { FrameSequence: var layoutFrame }
             && layoutFrame == client.Sequence
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveBagCleanupDiagnostics(string[] args)
{
    Console.WriteLine("Live bag cleanup candidate diagnostics");
    var requestedPid = ReadIntOption(args, "--pid", 0);
    var gridArgumentProvided = args.Any(a => a.Equals("--grid", StringComparison.OrdinalIgnoreCase));
    var manualGrid = ReadInventoryGridOption(args);
    var openBagRequested = args.Any(a => a.Equals("--open-bag", StringComparison.OrdinalIgnoreCase)
                                         || a.Equals("--execute-open-bag", StringComparison.OrdinalIgnoreCase));
    var executeOpenBag = args.Any(a => a.Equals("--execute-open-bag", StringComparison.OrdinalIgnoreCase));
    var openBagHotkey = ReadOption(args, "--open-hotkey") ?? "";
    var openBagDispatch = ReadDispatchOption(args, "--open-dispatch", InputDispatchMode.PostMessage);
    var openBagDelayMs = Math.Clamp(ReadIntOption(args, "--open-delay-ms", 350), 0, 5000);
    var openBagYieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 800), 0, 5000);
    var ignoreYield = args.Any(a => a.Equals("--ignore-yield", StringComparison.OrdinalIgnoreCase));
    if (gridArgumentProvided && manualGrid is null)
    {
        Console.Error.WriteLine("FAIL: --grid 格式无效，应为 x,y,列,行,格宽,格高[,横间距,纵间距]。");
        return false;
    }

    var games = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .ToArray();
    var game = requestedPid > 0
        ? games.FirstOrDefault(p => p.Id == requestedPid)
        : games.FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine(requestedPid > 0
            ? $"FAIL: 未找到正在运行的 Game.exe PID={requestedPid} 主窗口。"
            : "FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var log = new RuntimeLogService();
    var binding = new WindowBindingService(log);
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    IInputService openBagInput = executeOpenBag
        ? new AuditedInputService(new InputService(log))
        : new CountingInputService();
    openBagInput.YieldToUserInput = executeOpenBag && !ignoreYield && openBagYieldMs > 0;
    openBagInput.UserInputYieldMs = openBagYieldMs;
    var openBagInputMode = executeOpenBag ? "real-audited" : "planned-counting";
    var openBagParseOk = openBagInput.TryParseHotkey(openBagHotkey, out var openBagHotkeyError);
    var openBagYieldStatus = executeOpenBag
        ? openBagInput.GetYieldStatus(window.Hwnd, openBagDispatch)
        : null;
    var openBagBlockedByYield = openBagRequested
                                && executeOpenBag
                                && openBagParseOk
                                && openBagYieldStatus?.ShouldYield == true;
    var openBagSendAttempted = false;
    var openBagSendOk = false;
    if (openBagRequested && openBagParseOk)
    {
        if (!openBagBlockedByYield)
        {
            openBagSendAttempted = true;
            openBagSendOk = openBagInput.SendKey(window.Hwnd, openBagHotkey, openBagDispatch);
        }

        if (executeOpenBag && openBagSendAttempted && openBagSendOk && openBagDelayMs > 0)
            Thread.Sleep(openBagDelayMs);
    }

    var capture = new WindowCaptureService(log);
    var client = capture.CaptureClient(window.Hwnd);
    var registry = new ModelArtifactRegistry();
    using var interactionWindows = new InteractionWindowDetectService(registry, log);
    var interactionControls = new InteractionControlCatalogService(log);
    var inventory = new InventoryRecognitionService(capture, log, interactionWindows, interactionControls);
    var cleanupInput = new CountingInputService();
    var cleanup = new BagCleanupService(
        inventory,
        new ItemPolicyService(log),
        cleanupInput,
        log,
        capture,
        null,
        null,
        interactionWindows,
        interactionControls);
    var calibration = client is null
        ? new InventoryGridCalibrationResult(false, "客户区截图失败，无法校准背包。", null, null)
        : inventory.AutoCalibrate(client);
    var interaction = client is null
        ? InteractionWindowPerception.Unavailable(0, "Client capture failed.")
        : interactionWindows.Detect(client);
    var bagPanel = interaction.Detections
        .Where(item => string.Equals(item.ClassName, "bag_panel", StringComparison.Ordinal))
        .OrderByDescending(item => item.Confidence)
        .FirstOrDefault();
    var bagLayout = client is null || bagPanel is null
        ? null
        : interactionControls.Map(client.Sequence, bagPanel);

    BagCleanupResult? analysis = null;
    BagCleanupResult? execute = null;
    var config = new BagCleanupConfig
    {
        Mode = BagCleanupExecutionMode.DryRun,
        AllowActualSell = false,
        OpenBagBeforeScan = false,
        Policy = new ItemPolicyConfig
        {
            ProtectUnknownItems = true,
            RequireExplicitSellKeyword = true,
            BlockKeywords = { "绑定", "任务", "贵重", "珍兽", "宝石", "装备", "秘籍", "技能书" }
        }
    };

    var selectedGrid = calibration.Success ? calibration.Grid : manualGrid;
    var gridSource = calibration.Success
        ? "interaction-window-v3/bag_cells"
        : manualGrid is not null
            ? "manual-argument-fallback"
            : "none";

    if (selectedGrid is not null)
    {
        config.Grid = CopyGrid(selectedGrid);
        analysis = cleanup.Analyze(window, config);
        execute = cleanup.Execute(window, config);
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-bag-cleanup");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var clientPath = Path.Combine(evidenceDir, $"client-{window.Pid}-{stamp}.png");
    var overlayPath = Path.Combine(evidenceDir, $"bag-grid-{window.Pid}-{stamp}.png");
    var controlsOverlayPath = Path.Combine(evidenceDir, $"interaction-v3-{window.Pid}-{stamp}.png");
    var evidencePath = Path.Combine(evidenceDir, $"bag-cleanup-{window.Pid}-{stamp}.json");
    var clientSaved = SaveCapturePng(client, clientPath);
    var overlaySaved = client is not null && SaveGridOverlayPng(client, selectedGrid, overlayPath);
    var controlsOverlayError = "";
    var controlsOverlaySaved = client is not null
                               && bagLayout is not null
                               && interactionControls.TryRenderDebugOverlay(
                                   client,
                                   [bagLayout],
                                   controlsOverlayPath,
                                   out controlsOverlayError);
    var clientVisual = HasVisualContent(client);
    var status = selectedGrid is not null
        ? analysis?.Success == true ? "ANALYZED" : "SCAN_FAILED"
        : "NOT_DETECTED";
    var openBagAudit = openBagInput switch
    {
        CountingInputService counting => new InputAudit(
            counting.SendKeyCount,
            counting.SendTextCount,
            counting.ClickCount,
            counting.SentHotkeys.ToArray(),
            counting.Clicks.Select(c => new ClientClick(c.X, c.Y, c.Button.ToString())).ToArray()),
        AuditedInputService audited => audited.Snapshot(),
        _ => new InputAudit(0, 0, 0, Array.Empty<string>(), Array.Empty<ClientClick>())
    };
    var cleanupAudit = BuildInputAudit(cleanupInput);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-dry-run-no-click-no-sell",
        status,
        message = analysis?.Message ?? calibration.Message,
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        capture = new
        {
            client = client is null ? null : new { client.Width, client.Height, saved = clientSaved, visual = clientVisual, path = clientPath },
            overlay = new { saved = overlaySaved, path = overlayPath },
            controlsOverlay = new { saved = controlsOverlaySaved, path = controlsOverlayPath, error = controlsOverlayError }
        },
        interactionV3 = new
        {
            interaction.Available,
            interaction.ModelVersion,
            interaction.InferenceMilliseconds,
            panel = bagPanel is null
                ? null
                : new
                {
                    bagPanel.ClassName,
                    bagPanel.Confidence,
                    bagPanel.Box.X,
                    bagPanel.Box.Y,
                    bagPanel.Box.Width,
                    bagPanel.Box.Height,
                    frameSequence = interaction.FrameSequence
                },
            layout = bagLayout is null
                ? null
                : new
                {
                    bagLayout.FrameSequence,
                    bagLayout.AssetVersion,
                    bagLayout.RuntimeAuthorized,
                    bagLayout.Message,
                    bagCells = bagLayout.Regions
                        .Where(region => region.RegionId == "bag_cells")
                        .Select(region => new
                        {
                            region.Rows,
                            region.Columns,
                            count = region.Cells.Count,
                            cells = region.Cells.Select(cell => new
                            {
                                cell.Row,
                                cell.Column,
                                cell.CellBox.X,
                                cell.CellBox.Y,
                                cell.CellBox.Width,
                                cell.CellBox.Height,
                                clickX = cell.CellBox.X + cell.CellBox.Width / 2,
                                clickY = cell.CellBox.Y + cell.CellBox.Height / 2
                            }).ToArray()
                        }).FirstOrDefault()
                }
        },
        safety = new
        {
            dryRun = true,
            allowActualSell = false,
            autoSellEnabled = false,
            sellActionRequiresSecondConfirmation = true,
            actualSellBlockedByCurrentBuild = true,
            unknownItemsProtectedByDefault = true,
            protectedItemClasses = new[] { "unknown", "bound", "quest", "valuable", "pet", "gem", "equipment", "skill-book" },
            executed = execute?.Executed ?? false,
            openBag = new
            {
                requested = openBagRequested,
                executeRequested = executeOpenBag,
                sendsToRealGameWindow = executeOpenBag,
                inputMode = openBagInputMode,
                hotkey = openBagHotkey,
                dispatch = openBagDispatch.ToString(),
                delayMs = openBagDelayMs,
                respectManualInput = openBagInput.YieldToUserInput,
                yieldMs = openBagInput.UserInputYieldMs,
                ignoreYield,
                blockedByYield = openBagBlockedByYield,
                yieldStatus = openBagYieldStatus is null
                    ? null
                    : new
                    {
                        openBagYieldStatus.Enabled,
                        openBagYieldStatus.CanReadLastInput,
                        openBagYieldStatus.ShouldYield,
                        openBagYieldStatus.YieldMs,
                        openBagYieldStatus.LastInputAgeMs,
                        openBagYieldStatus.RemainingYieldMs,
                        openBagYieldStatus.TargetActive,
                        openBagYieldStatus.Scope,
                        openBagYieldStatus.Reason
                    },
                parseOk = openBagParseOk,
                parseError = openBagHotkeyError,
                attempted = openBagSendAttempted,
                sentOk = openBagSendOk,
                audit = openBagAudit
            },
            cleanupInput = cleanupAudit,
            sendsInput = executeOpenBag && openBagAudit.SendKeyCount > 0 || cleanupAudit.SendKeyCount > 0 || cleanupAudit.SendTextCount > 0,
            clicksMouse = cleanupAudit.ClickCount > 0,
            sellsItems = false,
            modifiesInventory = false
        },
        grid = selectedGrid is null
            ? null
            : new
            {
                source = gridSource,
                selectedGrid.X,
                selectedGrid.Y,
                selectedGrid.Columns,
                selectedGrid.Rows,
                selectedGrid.CellWidth,
                selectedGrid.CellHeight,
                selectedGrid.GapX,
                selectedGrid.GapY,
                autoCalibration = calibration.Grid is null
                    ? null
                    : new
                    {
                        calibration.Success,
                        calibration.Grid.X,
                        calibration.Grid.Y,
                        calibration.Grid.Columns,
                        calibration.Grid.Rows,
                        calibration.Grid.CellWidth,
                        calibration.Grid.CellHeight,
                        calibration.Grid.GapX,
                        calibration.Grid.GapY
                    }
            },
        scan = analysis?.Scan is null
            ? null
            : new
            {
                analysis.Scan.Success,
                analysis.Scan.Message,
                analysis.Scan.Width,
                analysis.Scan.Height,
                analysis.Scan.OccupiedCount,
                analysis.Scan.EmptyCount,
                slots = analysis.Scan.Slots.Select(s => new
                {
                    s.Index,
                    s.Row,
                    s.Column,
                    s.X,
                    s.Y,
                    s.Width,
                    s.Height,
                    state = s.State.ToString(),
                    s.ItemName,
                    s.OccupancyScore,
                    s.Source
                }).ToArray()
            },
        candidates = analysis is null
            ? Array.Empty<object>()
            : analysis.Candidates.Select(c => new
            {
                c.Slot.Index,
                c.Slot.Row,
                c.Slot.Column,
                decision = c.Decision.ToString(),
                c.Reason,
                c.Slot.ItemName,
                c.Slot.OccupancyScore,
                protectedByDefault = c.Decision != ItemCleanupDecision.SellCandidate
            }).Cast<object>().ToArray(),
        summary = analysis is null
            ? null
            : new
            {
                analysis.Success,
                analysis.SellCandidateCount,
                analysis.ProtectedCount,
                analysis.Executed,
                executeExecuted = execute?.Executed ?? false
            }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Title={window.Title}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Status={status}");
    Console.WriteLine($"Message={analysis?.Message ?? calibration.Message}");
    Console.WriteLine($"OpenBag requested={openBagRequested}, execute={executeOpenBag}, hotkey={openBagHotkey}, dispatch={openBagDispatch}, inputMode={openBagInputMode}, parseOk={openBagParseOk}, attempted={openBagSendAttempted}, sentOk={openBagSendOk}, blockedByYield={openBagBlockedByYield}");
    if (openBagYieldStatus is not null)
        Console.WriteLine($"OpenBag yield respect={openBagInput.YieldToUserInput}, shouldYield={openBagYieldStatus.ShouldYield}, ageMs={openBagYieldStatus.LastInputAgeMs:0}, remainingMs={openBagYieldStatus.RemainingYieldMs:0}, reason={openBagYieldStatus.Reason}");
    Console.WriteLine($"Capture client={client?.Width}x{client?.Height}, saved={clientSaved}, visual={clientVisual}, path={clientPath}");
    Console.WriteLine($"Overlay saved={overlaySaved}, path={overlayPath}");
    Console.WriteLine($"Grid source={gridSource}");
    if (selectedGrid is not null)
    {
        Console.WriteLine($"Grid=({selectedGrid.X},{selectedGrid.Y}) {selectedGrid.Columns}x{selectedGrid.Rows}, cell={selectedGrid.CellWidth}x{selectedGrid.CellHeight}, gap={selectedGrid.GapX}/{selectedGrid.GapY}");
        Console.WriteLine($"Scan occupied={analysis?.Scan.OccupiedCount}, empty={analysis?.Scan.EmptyCount}, sell={analysis?.SellCandidateCount}, protected={analysis?.ProtectedCount}");
    }
    Console.WriteLine($"Safety openBag send={openBagAudit.SendKeyCount}, text={openBagAudit.SendTextCount}, click={openBagAudit.ClickCount}; cleanup send={cleanupAudit.SendKeyCount}, text={cleanupAudit.SendTextCount}, click={cleanupAudit.ClickCount}, executed={execute?.Executed ?? false}");
    Console.WriteLine($"Evidence={evidencePath}");

    var openBagGateOk = !openBagRequested
                        || openBagParseOk
                           && (openBagBlockedByYield
                               ? openBagAudit.SendKeyCount == 0
                                 && openBagAudit.SendTextCount == 0
                                 && openBagAudit.ClickCount == 0
                               : openBagSendAttempted
                                 && openBagAudit.SendKeyCount == 1
                                 && openBagAudit.SendTextCount == 0
                                 && openBagAudit.ClickCount == 0
                                 && (!executeOpenBag || openBagSendOk));
    var ok = window.IsAutomationAllowed
             && client is { Width: > 0, Height: > 0 }
             && clientSaved
             && overlaySaved
             && controlsOverlaySaved
             && clientVisual
             && bagPanel is { Confidence: >= 0.75 }
             && bagLayout is { FrameSequence: var layoutFrame }
             && layoutFrame == client.Sequence
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && openBagGateOk
             && (!executeOpenBag || openBagBlockedByYield || openBagAudit.SentHotkeys.Contains(openBagHotkey, StringComparer.OrdinalIgnoreCase))
             && cleanupAudit.SendKeyCount == 0
             && cleanupAudit.SendTextCount == 0
             && cleanupAudit.ClickCount == 0
             && execute?.Executed != true
             && (selectedGrid is null || analysis is { Success: true, Executed: false });

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static InventoryGridConfig CopyGrid(InventoryGridConfig grid) =>
    new()
    {
        ScanMode = grid.ScanMode,
        Enabled = grid.Enabled,
        X = grid.X,
        Y = grid.Y,
        Columns = grid.Columns,
        Rows = grid.Rows,
        CellWidth = grid.CellWidth,
        CellHeight = grid.CellHeight,
        GapX = grid.GapX,
        GapY = grid.GapY,
        SlotNameOverrides = new Dictionary<int, string>(grid.SlotNameOverrides),
        SlotNameSources = new Dictionary<int, string>(grid.SlotNameSources)
    };

static bool RunImageBagCalibrationDiagnostics(string? imagePath)
{
    Console.WriteLine("Image bag calibration diagnostics");
    if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 PNG 截图路径。");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 截图读取失败。");
        return false;
    }

    var log = new RuntimeLogService();
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var calibration = inventory.AutoCalibrate(capture);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "image-bag-calibration");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var baseName = Path.GetFileNameWithoutExtension(imagePath);
    var overlayPath = Path.Combine(evidenceDir, $"{baseName}-{stamp}-grid.png");
    var evidencePath = Path.Combine(evidenceDir, $"{baseName}-{stamp}.json");
    var overlaySaved = SaveGridOverlayPng(capture, calibration.Grid, overlayPath);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "static-image-no-click-no-sell",
        source = imagePath,
        overlay = overlayPath,
        overlaySaved,
        status = calibration.Success ? "CALIBRATED" : "NOT_DETECTED",
        message = calibration.Message,
        capture = new { capture.Width, capture.Height, visual = HasVisualContent(capture) },
        grid = calibration.Grid is null
            ? null
            : new
            {
                calibration.Grid.X,
                calibration.Grid.Y,
                calibration.Grid.Columns,
                calibration.Grid.Rows,
                calibration.Grid.CellWidth,
                calibration.Grid.CellHeight,
                calibration.Grid.GapX,
                calibration.Grid.GapY
            },
        preview = calibration.PreviewScan is null
            ? null
            : new
            {
                calibration.PreviewScan.Success,
                calibration.PreviewScan.OccupiedCount,
                calibration.PreviewScan.EmptyCount,
                calibration.PreviewScan.Width,
                calibration.PreviewScan.Height
            }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Source={imagePath}");
    Console.WriteLine($"Capture={capture.Width}x{capture.Height}, visual={HasVisualContent(capture)}");
    Console.WriteLine($"Status={(calibration.Success ? "CALIBRATED" : "NOT_DETECTED")}");
    Console.WriteLine($"Message={calibration.Message}");
    if (calibration.Grid is not null)
    {
        Console.WriteLine($"Grid=({calibration.Grid.X},{calibration.Grid.Y}) {calibration.Grid.Columns}x{calibration.Grid.Rows}, cell={calibration.Grid.CellWidth}x{calibration.Grid.CellHeight}, gap={calibration.Grid.GapX}/{calibration.Grid.GapY}");
        Console.WriteLine($"Preview occupied={calibration.PreviewScan?.OccupiedCount}, empty={calibration.PreviewScan?.EmptyCount}");
    }
    Console.WriteLine($"Overlay={overlayPath}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = capture.Width > 0
             && capture.Height > 0
             && HasVisualContent(capture)
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && (!calibration.Success || calibration is { Grid: not null, PreviewScan.Success: true } && overlaySaved);

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunImageBagCleanupDiagnostics(string[] args)
{
    Console.WriteLine("Image bag cleanup candidate diagnostics");

    var imagePath = ReadOption(args, "--image")
                    ?? args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 PNG 截图路径。");
        return false;
    }

    var gridArgumentProvided = args.Any(a => a.Equals("--grid", StringComparison.OrdinalIgnoreCase));
    var manualGrid = ReadInventoryGridOption(args);
    if (gridArgumentProvided && manualGrid is null)
    {
        Console.Error.WriteLine("FAIL: --grid 格式无效，应为 x,y,列,行,格宽,格高[,横间距,纵间距]。");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 截图读取失败。");
        return false;
    }

    var log = new RuntimeLogService();
    var input = new CountingInputService();
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var policy = new ItemPolicyService(log);
    var cleanup = new BagCleanupService(inventory, policy, input, log);
    var reportService = new BagCleanupReportService();
    var calibration = inventory.AutoCalibrate(capture);

    var config = new BagCleanupConfig
    {
        Mode = BagCleanupExecutionMode.DryRun,
        AllowActualSell = false,
        OpenBagBeforeScan = false,
        Policy = new ItemPolicyConfig
        {
            ProtectUnknownItems = true,
            RequireExplicitSellKeyword = true,
            BlockKeywords = { "绑定", "任务", "贵重", "珍兽", "宝石", "装备", "秘籍", "技能书" }
        }
    };
    var legacyLoaded = policy.LoadLegacyItemLists((Environment.GetEnvironmentVariable("TLBB_LEGACY_DATA_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "legacy-data")), config.Policy);
    AddDelimitedOptionValues(args, "--sell-keywords", config.Policy.SellKeywords);
    AddDelimitedOptionValues(args, "--keep-items", config.Policy.KeepItems);
    AddDelimitedOptionValues(args, "--block-keywords", config.Policy.BlockKeywords);
    AddDelimitedOptionValues(args, "--store-items", config.Policy.StoreItems);
    AddDelimitedOptionValues(args, "--trade-items", config.Policy.TradeItems);

    var selectedGrid = manualGrid ?? (calibration.Success ? calibration.Grid : null);
    var gridSource = manualGrid is not null ? "manual-argument" : calibration.Success ? "auto-calibration" : "none";
    ApplySlotNameOverrides(args, selectedGrid);
    var templateIndexPath = ReadOption(args, "--template-index") ?? ReadOption(args, "--index");
    var templateThreshold = Math.Clamp(ReadDoubleOption(args, "--template-threshold", ReadDoubleOption(args, "--threshold", 0.92)), 0.50, 1.0);
    var templateInnerPadding = Math.Clamp(ReadIntOption(args, "--inner-padding", 1), 0, 8);
    var templateMatches = selectedGrid is not null && !string.IsNullOrWhiteSpace(templateIndexPath)
        ? ApplyBagTemplateMatchesToCleanup(capture, selectedGrid, config.Policy, templateIndexPath, templateThreshold, templateInnerPadding)
        : new List<BagTemplateSlotMatchEvidence>();

    BagCleanupResult? analysis = null;
    BagCleanupResult? execute = null;
    if (selectedGrid is not null)
    {
        config.Grid = CopyGrid(selectedGrid);
        var window = DiagnosticWindow(new nint(0xBACC), "image-bag-cleanup", capture.Width, capture.Height);
        analysis = cleanup.Analyze(window, config);
        execute = cleanup.Execute(window, config);
    }

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var baseName = SanitizeFileName(Path.GetFileNameWithoutExtension(imagePath));
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "image-bag-cleanup", $"{stamp}-{baseName}");
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "bag-grid-overlay.png");
    var reportPath = Path.Combine(evidenceDir, "cleanup-candidates.txt");
    var evidencePath = Path.Combine(evidenceDir, "bag-cleanup.json");

    var clientSaved = SaveCapturePng(capture, clientPath);
    var overlaySaved = SaveGridOverlayPng(capture, selectedGrid, overlayPath);
    var reportSaved = false;
    if (analysis is not null)
    {
        reportService.SaveTextReport(reportPath, analysis, config);
        reportSaved = File.Exists(reportPath) && new FileInfo(reportPath).Length > 0;
    }

    var status = selectedGrid is not null
        ? analysis?.Success == true ? "ANALYZED" : "SCAN_FAILED"
        : "NOT_DETECTED";

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "static-image-read-only-dry-run-no-click-no-sell",
        status,
        message = analysis?.Message ?? calibration.Message,
        sourceImage = imagePath,
        replayImage = clientPath,
        capture = new { capture.Width, capture.Height, saved = clientSaved, visual = HasVisualContent(capture) },
        overlay = new { path = overlayPath, saved = overlaySaved },
        report = new { path = reportPath, saved = reportSaved },
        templateMatching = new
        {
            enabled = !string.IsNullOrWhiteSpace(templateIndexPath),
            indexPath = templateIndexPath ?? "",
            threshold = templateThreshold,
            innerPadding = templateInnerPadding,
            matchCount = templateMatches.Count(m => m.Matched),
            appliedCount = templateMatches.Count(m => m.AppliedToCleanup),
            sellCandidateRuleCount = templateMatches.Count(m => m.AppliedToCleanup && string.Equals(m.Policy, "SellCandidate", StringComparison.OrdinalIgnoreCase)),
            matches = templateMatches
        },
        safety = new
        {
            processAccess = false,
            sendsInput = false,
            clicksMouse = false,
            dryRun = true,
            allowActualSell = false,
            autoSellEnabled = false,
            sellActionRequiresSecondConfirmation = true,
            actualSellBlockedByCurrentBuild = true,
            unknownItemsProtectedByDefault = true,
            protectedItemClasses = new[] { "unknown", "bound", "quest", "valuable", "pet", "gem", "equipment", "skill-book" },
            executed = execute?.Executed ?? false,
            input.SendKeyCount,
            input.SendTextCount,
            input.ClickCount,
            sellsItems = false,
            modifiesInventory = false
        },
        policy = new
        {
            legacyLoaded,
            config.Policy.RequireExplicitSellKeyword,
            config.Policy.ProtectUnknownItems,
            keepCount = config.Policy.KeepItems.Count,
            storeCount = config.Policy.StoreItems.Count,
            tradeCount = config.Policy.TradeItems.Count,
            sellKeywordCount = config.Policy.SellKeywords.Count,
            blockKeywordCount = config.Policy.BlockKeywords.Count
        },
        grid = selectedGrid is null
            ? null
            : new
            {
                source = gridSource,
                selectedGrid.X,
                selectedGrid.Y,
                selectedGrid.Columns,
                selectedGrid.Rows,
                selectedGrid.CellWidth,
                selectedGrid.CellHeight,
                selectedGrid.GapX,
                selectedGrid.GapY,
                slotNameOverrideCount = selectedGrid.SlotNameOverrides.Count,
                autoCalibration = calibration.Grid is null
                    ? null
                    : new
                    {
                        calibration.Success,
                        calibration.Grid.X,
                        calibration.Grid.Y,
                        calibration.Grid.Columns,
                        calibration.Grid.Rows,
                        calibration.Grid.CellWidth,
                        calibration.Grid.CellHeight,
                        calibration.Grid.GapX,
                        calibration.Grid.GapY
                    }
            },
        scan = analysis?.Scan is null
            ? null
            : new
            {
                analysis.Scan.Success,
                analysis.Scan.Message,
                analysis.Scan.Width,
                analysis.Scan.Height,
                analysis.Scan.OccupiedCount,
                analysis.Scan.EmptyCount,
                slots = analysis.Scan.Slots.Select(s => new
                {
                    s.Index,
                    s.Row,
                    s.Column,
                    s.X,
                    s.Y,
                    s.Width,
                    s.Height,
                    state = s.State.ToString(),
                    s.ItemName,
                    s.OccupancyScore,
                    s.Source
                }).ToArray()
            },
        candidates = analysis is null
            ? Array.Empty<object>()
            : analysis.Candidates.Select(c => new
            {
                c.Slot.Index,
                c.Slot.Row,
                c.Slot.Column,
                decision = c.Decision.ToString(),
                c.Reason,
                c.Slot.ItemName,
                c.Slot.OccupancyScore,
                status = ToCleanupDisplayStatus(c),
                protectedByDefault = c.Decision != ItemCleanupDecision.SellCandidate
            }).Cast<object>().ToArray(),
        summary = analysis is null
            ? null
            : new
            {
                analysis.Success,
                analysis.SellCandidateCount,
                analysis.ProtectedCount,
                analysis.Executed,
                executeExecuted = execute?.Executed ?? false
            }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Source={imagePath}");
    Console.WriteLine($"Capture={capture.Width}x{capture.Height}, saved={clientSaved}, visual={HasVisualContent(capture)}");
    Console.WriteLine($"Status={status}");
    Console.WriteLine($"Message={analysis?.Message ?? calibration.Message}");
    Console.WriteLine($"Grid source={gridSource}");
    if (selectedGrid is not null)
    {
        Console.WriteLine($"Grid=({selectedGrid.X},{selectedGrid.Y}) {selectedGrid.Columns}x{selectedGrid.Rows}, cell={selectedGrid.CellWidth}x{selectedGrid.CellHeight}, gap={selectedGrid.GapX}/{selectedGrid.GapY}, slotNames={selectedGrid.SlotNameOverrides.Count}");
        Console.WriteLine($"Scan occupied={analysis?.Scan.OccupiedCount}, empty={analysis?.Scan.EmptyCount}, sell={analysis?.SellCandidateCount}, protected={analysis?.ProtectedCount}");
    }
    if (!string.IsNullOrWhiteSpace(templateIndexPath))
        Console.WriteLine($"Template index={templateIndexPath}, matched={templateMatches.Count(m => m.Matched)}, applied={templateMatches.Count(m => m.AppliedToCleanup)}, threshold={templateThreshold:0.000}");
    Console.WriteLine($"Safety send={input.SendKeyCount}, text={input.SendTextCount}, click={input.ClickCount}, executed={execute?.Executed ?? false}");
    Console.WriteLine($"Overlay={overlayPath}");
    Console.WriteLine($"Report={(reportSaved ? reportPath : "-")}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = capture.Width > 0
             && capture.Height > 0
             && HasVisualContent(capture)
             && clientSaved
             && overlaySaved
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && input.SendKeyCount == 0
             && input.SendTextCount == 0
             && input.ClickCount == 0
             && execute?.Executed != true
             && (selectedGrid is null || analysis is { Success: true, Executed: false } && reportSaved);

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunImageBagSlotSamplesDiagnostics(string[] args)
{
    Console.WriteLine("Image bag slot sample export diagnostics");

    var imagePath = ReadOption(args, "--image")
                    ?? args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 PNG 截图路径。");
        return false;
    }

    var gridArgumentProvided = args.Any(a => a.Equals("--grid", StringComparison.OrdinalIgnoreCase));
    var manualGrid = ReadInventoryGridOption(args);
    if (gridArgumentProvided && manualGrid is null)
    {
        Console.Error.WriteLine("FAIL: --grid 格式无效，应为 x,y,列,行,格宽,格高[,横间距,纵间距]。");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 截图读取失败。");
        return false;
    }

    var includeEmpty = args.Any(a => a.Equals("--include-empty", StringComparison.OrdinalIgnoreCase));
    var innerPadding = Math.Clamp(ReadIntOption(args, "--inner-padding", 1), 0, 8);
    var log = new RuntimeLogService();
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var calibration = inventory.AutoCalibrate(capture);
    var selectedGrid = manualGrid ?? (calibration.Success ? calibration.Grid : null);
    var gridSource = manualGrid is not null ? "manual-argument" : calibration.Success ? "auto-calibration" : "none";

    if (selectedGrid is null)
    {
        Console.Error.WriteLine($"FAIL: {calibration.Message}");
        return false;
    }

    var scan = inventory.Scan(capture, CopyGrid(selectedGrid));
    if (!scan.Success)
    {
        Console.Error.WriteLine($"FAIL: {scan.Message}");
        return false;
    }

    var slots = scan.Slots
        .Where(s => includeEmpty || s.State == InventorySlotState.Occupied)
        .OrderBy(s => s.Index)
        .ToArray();
    if (slots.Length == 0)
    {
        Console.Error.WriteLine("FAIL: 未找到可导出的格子样本。");
        return false;
    }

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var baseName = SanitizeFileName(Path.GetFileNameWithoutExtension(imagePath));
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "image-bag-slot-samples", $"{stamp}-{baseName}");
    var cellsDir = Path.Combine(evidenceDir, "slots");
    Directory.CreateDirectory(cellsDir);

    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "bag-grid-overlay.png");
    var manifestPath = Path.Combine(evidenceDir, "manifest.json");
    var manifestTsvPath = Path.Combine(evidenceDir, "manifest.tsv");
    var clientSaved = SaveCapturePng(capture, clientPath);
    var overlaySaved = SaveGridOverlayPng(capture, selectedGrid, overlayPath);

    var exported = new List<object>(slots.Length);
    var tsv = new StringBuilder();
    tsv.AppendLine("index\trow\tcolumn\tstate\toccupancyScore\titemName\tpolicy\treviewStatus\tcellPath\ticonPath");
    var savedCount = 0;
    foreach (var slot in slots)
    {
        var safeState = slot.State.ToString().ToLowerInvariant();
        var prefix = $"slot-{slot.Index:00}-r{slot.Row}c{slot.Column}-{safeState}";
        var cellPath = Path.Combine(cellsDir, $"{prefix}-cell.png");
        var iconPath = Path.Combine(cellsDir, $"{prefix}-icon.png");
        var cell = CropCaptureRect(capture, slot.X, slot.Y, slot.Width, slot.Height);
        var icon = CropCaptureRect(
            capture,
            slot.X + innerPadding,
            slot.Y + innerPadding,
            slot.Width - innerPadding * 2,
            slot.Height - innerPadding * 2);
        var cellSaved = SaveCapturePng(cell, cellPath);
        var iconSaved = SaveCapturePng(icon, iconPath);
        if (cellSaved || iconSaved)
            savedCount++;

        var reviewStatus = slot.State == InventorySlotState.Occupied ? "NeedsReview" : "EmptyReference";
        var policy = slot.State == InventorySlotState.Occupied ? "UnknownProtected" : "Ignore";
        exported.Add(new
        {
            slot.Index,
            slot.Row,
            slot.Column,
            slot.X,
            slot.Y,
            slot.Width,
            slot.Height,
            state = slot.State.ToString(),
            slot.OccupancyScore,
            slot.ItemName,
            slot.Source,
            policy,
            reviewStatus,
            cell = new { path = cellPath, saved = cellSaved, width = cell?.Width ?? 0, height = cell?.Height ?? 0 },
            icon = new { path = iconPath, saved = iconSaved, padding = innerPadding, width = icon?.Width ?? 0, height = icon?.Height ?? 0 }
        });
        tsv.Append(slot.Index).Append('\t')
            .Append(slot.Row).Append('\t')
            .Append(slot.Column).Append('\t')
            .Append(slot.State).Append('\t')
            .Append(slot.OccupancyScore.ToString("0.000", CultureInfo.InvariantCulture)).Append('\t')
            .Append(EscapeTsv(slot.ItemName)).Append('\t')
            .Append(policy).Append('\t')
            .Append(reviewStatus).Append('\t')
            .Append(cellPath).Append('\t')
            .Append(iconPath)
            .AppendLine();
    }

    File.WriteAllText(manifestTsvPath, tsv.ToString(), new UTF8Encoding(false));

    var manifest = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "static-image-slot-sample-export-no-process-no-click-no-sell",
        sourceImage = imagePath,
        replayImage = clientPath,
        overlay = new { path = overlayPath, saved = overlaySaved },
        manifestTsv = manifestTsvPath,
        capture = new { capture.Width, capture.Height, saved = clientSaved, visual = HasVisualContent(capture) },
        safety = new
        {
            processAccess = false,
            sendsInput = false,
            clicksMouse = false,
            sellsItems = false,
            modifiesInventory = false,
            unknownItemsProtectedByDefault = true,
            exportedOnly = true
        },
        grid = new
        {
            source = gridSource,
            selectedGrid.X,
            selectedGrid.Y,
            selectedGrid.Columns,
            selectedGrid.Rows,
            selectedGrid.CellWidth,
            selectedGrid.CellHeight,
            selectedGrid.GapX,
            selectedGrid.GapY,
            autoCalibration = calibration.Grid is null
                ? null
                : new
                {
                    calibration.Success,
                    calibration.Grid.X,
                    calibration.Grid.Y,
                    calibration.Grid.Columns,
                    calibration.Grid.Rows,
                    calibration.Grid.CellWidth,
                    calibration.Grid.CellHeight,
                    calibration.Grid.GapX,
                    calibration.Grid.GapY
                }
        },
        scan = new
        {
            scan.Success,
            scan.Message,
            scan.Width,
            scan.Height,
            scan.OccupiedCount,
            scan.EmptyCount,
            exportedCount = exported.Count,
            savedCount,
            includeEmpty,
            innerPadding
        },
        slots = exported
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(manifestPath, System.Text.Json.JsonSerializer.Serialize(manifest, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Source={imagePath}");
    Console.WriteLine($"Capture={capture.Width}x{capture.Height}, saved={clientSaved}, visual={HasVisualContent(capture)}");
    Console.WriteLine($"Grid source={gridSource}");
    Console.WriteLine($"Grid=({selectedGrid.X},{selectedGrid.Y}) {selectedGrid.Columns}x{selectedGrid.Rows}, cell={selectedGrid.CellWidth}x{selectedGrid.CellHeight}, gap={selectedGrid.GapX}/{selectedGrid.GapY}");
    Console.WriteLine($"Scan occupied={scan.OccupiedCount}, empty={scan.EmptyCount}");
    Console.WriteLine($"Exported={exported.Count}, saved={savedCount}, includeEmpty={includeEmpty}, innerPadding={innerPadding}");
    Console.WriteLine($"Overlay={overlayPath}");
    Console.WriteLine($"Manifest={manifestPath}");
    Console.WriteLine($"ManifestTsv={manifestTsvPath}");
    Console.WriteLine($"SlotsDir={cellsDir}");

    var ok = clientSaved
             && overlaySaved
             && savedCount == exported.Count
             && File.Exists(manifestPath)
             && new FileInfo(manifestPath).Length > 0
             && File.Exists(manifestTsvPath)
             && new FileInfo(manifestTsvPath).Length > 0
             && HasVisualContent(capture)
             && scan.Success;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static string EscapeTsv(string value) =>
    (value ?? string.Empty).Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ').Trim();

static bool RunBagItemTemplateLabelDiagnostics(string[] args)
{
    Console.WriteLine("Bag item template label diagnostics");

    var manifestPath = ReadOption(args, "--manifest")
                       ?? args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(manifestPath) || !File.Exists(manifestPath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 manifest.tsv。");
        return false;
    }

    var rawSlot = ReadOption(args, "--slot") ?? ReadOption(args, "--index");
    if (!int.TryParse(rawSlot, NumberStyles.Integer, CultureInfo.InvariantCulture, out var slotIndex) || slotIndex < 0)
    {
        Console.Error.WriteLine("FAIL: 请使用 --slot 指定要标注的格子 index。");
        return false;
    }

    var itemName = (ReadOption(args, "--name") ?? ReadOption(args, "--item") ?? string.Empty).Trim();
    var policy = NormalizeTemplatePolicy(ReadOption(args, "--policy") ?? "Keep");
    if (string.IsNullOrWhiteSpace(itemName)
        && !string.Equals(policy, "Ignore", StringComparison.OrdinalIgnoreCase)
        && !string.Equals(policy, "UnknownProtected", StringComparison.OrdinalIgnoreCase))
    {
        Console.Error.WriteLine("FAIL: Keep/Store/Trade/SellCandidate 策略必须填写 --name。");
        return false;
    }

    var inPlace = args.Any(a => a.Equals("--in-place", StringComparison.OrdinalIgnoreCase));
    var outputPath = ReadOption(args, "--output");
    if (string.IsNullOrWhiteSpace(outputPath))
    {
        outputPath = inPlace
            ? manifestPath
            : Path.Combine(
                Path.GetDirectoryName(Path.GetFullPath(manifestPath)) ?? Environment.CurrentDirectory,
                $"{Path.GetFileNameWithoutExtension(manifestPath)}-labeled.tsv");
    }

    if (Path.GetFullPath(outputPath).Equals(Path.GetFullPath(manifestPath), StringComparison.OrdinalIgnoreCase) && !inPlace)
    {
        Console.Error.WriteLine("FAIL: 如需覆盖原 manifest，请显式使用 --in-place；否则请指定不同 --output。");
        return false;
    }

    var document = ReadTsvDocument(manifestPath);
    if (document.Rows.Count == 0)
    {
        Console.Error.WriteLine("FAIL: manifest.tsv 没有可标注的数据行。");
        return false;
    }

    EnsureTsvColumn(document.Headers, document.Rows, "itemName");
    EnsureTsvColumn(document.Headers, document.Rows, "policy");
    EnsureTsvColumn(document.Headers, document.Rows, "reviewStatus");

    var row = document.Rows.FirstOrDefault(r =>
        int.TryParse(GetTsvValue(r, "index"), NumberStyles.Integer, CultureInfo.InvariantCulture, out var index)
        && index == slotIndex);
    if (row is null)
    {
        Console.Error.WriteLine($"FAIL: manifest 中找不到 index={slotIndex} 的格子。");
        return false;
    }

    var before = new
    {
        itemName = GetTsvValue(row, "itemName"),
        policy = GetTsvValue(row, "policy"),
        reviewStatus = GetTsvValue(row, "reviewStatus")
    };

    row["itemName"] = itemName;
    row["policy"] = policy;
    row["reviewStatus"] = string.Equals(policy, "UnknownProtected", StringComparison.OrdinalIgnoreCase)
        ? "NeedsReview"
        : "Reviewed";

    var outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
    if (!string.IsNullOrWhiteSpace(outputDir))
        Directory.CreateDirectory(outputDir);

    var backupPath = string.Empty;
    if (inPlace)
    {
        backupPath = $"{manifestPath}.bak-{DateTime.Now:yyyyMMdd-HHmmss}";
        File.Copy(manifestPath, backupPath, overwrite: false);
    }

    WriteTsvDocument(outputPath, document.Headers, document.Rows);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "bag-item-template-label", stamp);
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "label.json");
    var evidence = new
    {
        generatedAt = DateTimeOffset.Now,
        mode = "bag-item-template-label-no-game-access-no-click-no-sell",
        manifestPath,
        outputPath,
        backupPath = string.IsNullOrWhiteSpace(backupPath) ? null : backupPath,
        slotIndex,
        before,
        after = new
        {
            itemName,
            policy,
            reviewStatus = row["reviewStatus"]
        },
        safety = new
        {
            processAccess = false,
            sendsInput = false,
            clicksMouse = false,
            sellsItems = false,
            modifiesInventory = false,
            labelsOnly = true,
            sellCandidateIsReportOnly = true
        },
        source = new
        {
            row = GetTsvValue(row, "row"),
            column = GetTsvValue(row, "column"),
            cellPath = GetTsvValue(row, "cellPath"),
            iconPath = GetTsvValue(row, "iconPath")
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Manifest={manifestPath}");
    Console.WriteLine($"Output={outputPath}");
    Console.WriteLine($"Slot={slotIndex}, Name={itemName}, Policy={policy}, Review={row["reviewStatus"]}");
    if (!string.IsNullOrWhiteSpace(backupPath))
        Console.WriteLine($"Backup={backupPath}");
    Console.WriteLine("Safety process=False, input=False, click=False, sell=False");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(outputPath)
             && new FileInfo(outputPath).Length > 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && (!inPlace || File.Exists(backupPath));
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunBagItemTemplateIndexDiagnostics(string[] args)
{
    Console.WriteLine("Bag item template index diagnostics");

    var manifestPath = ReadOption(args, "--manifest")
                       ?? args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.OrdinalIgnoreCase));
    if (string.IsNullOrWhiteSpace(manifestPath) || !File.Exists(manifestPath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 manifest.tsv。");
        return false;
    }

    var outputPath = ReadOption(args, "--output")
                     ?? Path.Combine(Environment.CurrentDirectory, "data", "samples", "bag-items", "index.json");
    var outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
    if (!string.IsNullOrWhiteSpace(outputDir))
        Directory.CreateDirectory(outputDir);

    var rows = ReadTsvRows(manifestPath).ToArray();
    if (rows.Length == 0)
    {
        Console.Error.WriteLine("FAIL: manifest.tsv 没有可读取的样本行。");
        return false;
    }

    var manifestDir = Path.GetDirectoryName(Path.GetFullPath(manifestPath)) ?? Environment.CurrentDirectory;
    var templates = new List<Dictionary<string, object?>>();
    var review = new List<object>();
    foreach (var row in rows)
    {
        var index = GetTsvValue(row, "index");
        var itemName = GetTsvValue(row, "itemName");
        var policy = NormalizeTemplatePolicy(GetTsvValue(row, "policy"));
        var iconPath = ResolveRelativePath(manifestDir, GetTsvValue(row, "iconPath"));
        var cellPath = ResolveRelativePath(manifestDir, GetTsvValue(row, "cellPath"));
        var reason = string.Empty;

        if (string.IsNullOrWhiteSpace(itemName))
            reason = "itemName 为空，需要人工标注。";
        else if (string.IsNullOrWhiteSpace(iconPath) || !File.Exists(iconPath))
            reason = "iconPath 不存在，不能入模板。";

        if (!string.IsNullOrWhiteSpace(reason))
        {
            review.Add(new
            {
                index,
                row = GetTsvValue(row, "row"),
                column = GetTsvValue(row, "column"),
                state = GetTsvValue(row, "state"),
                itemName,
                policy,
                reason,
                cellPath,
                iconPath
            });
            continue;
        }

        var icon = LoadCapturePng(iconPath);
        var sha256 = ComputeFileSha256(iconPath);
        templates.Add(new Dictionary<string, object?>
        {
            ["id"] = $"{SanitizeFileName(itemName)}-{index}-{sha256[..Math.Min(8, sha256.Length)]}",
            ["itemName"] = itemName.Trim(),
            ["policy"] = policy,
            ["cleanupDecision"] = policy,
            ["source"] = new
            {
                manifestPath,
                index,
                row = GetTsvValue(row, "row"),
                column = GetTsvValue(row, "column"),
                cellPath,
                iconPath
            },
            ["image"] = new
            {
                iconWidth = icon?.Width ?? 0,
                iconHeight = icon?.Height ?? 0,
                sha256,
                averageHash = icon is null ? string.Empty : ComputeAverageHash64(icon)
            },
            ["safety"] = new
            {
                canSellOnlyIfPolicyIsSellCandidate = true,
                defaultUnknownProtected = true,
                generatedFromHumanLabel = true
            }
        });
    }

    var sellRuleCount = templates.Count(t =>
        t.TryGetValue("policy", out var value)
        && string.Equals(value?.ToString(), "SellCandidate", StringComparison.OrdinalIgnoreCase));
    var indexDocument = new
    {
        version = 1,
        generatedAt = DateTimeOffset.Now,
        mode = "bag-item-template-index-no-game-access-no-click-no-sell",
        sourceManifest = manifestPath,
        outputPath,
        summary = new
        {
            sourceRows = rows.Length,
            templateCount = templates.Count,
            reviewCount = review.Count,
            sellRuleCount,
            explicitSellCandidateRequired = true,
            unknownItemsProtectedByDefault = true
        },
        safety = new
        {
            processAccess = false,
            sendsInput = false,
            clicksMouse = false,
            sellsItems = false,
            modifiesInventory = false,
            generatesRulesOnly = true,
            noAutomaticSellRulesForUnlabeledSamples = true
        },
        templates,
        review
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(outputPath, System.Text.Json.JsonSerializer.Serialize(indexDocument, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Manifest={manifestPath}");
    Console.WriteLine($"Output={outputPath}");
    Console.WriteLine($"Rows={rows.Length}, Templates={templates.Count}, NeedsReview={review.Count}, SellRules={sellRuleCount}");
    Console.WriteLine("Safety process=False, input=False, click=False, sell=False");

    var ok = File.Exists(outputPath)
             && new FileInfo(outputPath).Length > 0
             && rows.Length > 0
             && review.Count + templates.Count == rows.Length;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static IReadOnlyList<Dictionary<string, string>> ReadTsvRows(string path)
{
    var document = ReadTsvDocument(path);
    return document.Rows;
}

static (List<string> Headers, List<Dictionary<string, string>> Rows) ReadTsvDocument(string path)
{
    var lines = File.ReadAllLines(path, Encoding.UTF8);
    if (lines.Length == 0)
        return (new List<string>(), new List<Dictionary<string, string>>());

    var headers = lines[0]
        .Split('\t')
        .Select(h => h.Trim())
        .Where(h => h.Length > 0)
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToList();
    var rows = new List<Dictionary<string, string>>();
    foreach (var line in lines.Skip(1))
    {
        if (string.IsNullOrWhiteSpace(line))
            continue;

        var parts = line.Split('\t');
        var row = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        for (var i = 0; i < headers.Count; i++)
            row[headers[i]] = i < parts.Length ? parts[i].Trim() : string.Empty;
        rows.Add(row);
    }

    return (headers, rows);
}

static void EnsureTsvColumn(List<string> headers, IEnumerable<Dictionary<string, string>> rows, string column)
{
    if (!headers.Contains(column, StringComparer.OrdinalIgnoreCase))
        headers.Add(column);

    foreach (var row in rows)
        row.TryAdd(column, string.Empty);
}

static void WriteTsvDocument(string path, IReadOnlyList<string> headers, IEnumerable<IReadOnlyDictionary<string, string>> rows)
{
    var content = new StringBuilder();
    content.AppendLine(string.Join('\t', headers.Select(EscapeTsv)));
    foreach (var row in rows)
    {
        content.AppendLine(string.Join('\t', headers.Select(header => EscapeTsv(GetTsvValue(row, header)))));
    }

    File.WriteAllText(path, content.ToString(), new UTF8Encoding(false));
}

static string GetTsvValue(IReadOnlyDictionary<string, string> row, string name) =>
    row.TryGetValue(name, out var value) ? value.Trim() : string.Empty;

static string ResolveRelativePath(string baseDirectory, string path)
{
    if (string.IsNullOrWhiteSpace(path))
        return string.Empty;

    return Path.IsPathRooted(path) ? path : Path.GetFullPath(Path.Combine(baseDirectory, path));
}

static string NormalizeTemplatePolicy(string policy)
{
    if (string.IsNullOrWhiteSpace(policy))
        return "UnknownProtected";

    return policy.Trim().Replace(" ", string.Empty, StringComparison.OrdinalIgnoreCase) switch
    {
        "Keep" => "Keep",
        "Store" => "Store",
        "Trade" => "Trade",
        "SellCandidate" => "SellCandidate",
        "BlockedUnknown" => "UnknownProtected",
        "UnknownProtected" => "UnknownProtected",
        "Ignore" => "Ignore",
        _ => "UnknownProtected"
    };
}

static string ComputeFileSha256(string path)
{
    using var stream = File.OpenRead(path);
    return Convert.ToHexString(SHA256.HashData(stream));
}

static string ComputeAverageHash64(CaptureResult image)
{
    const int size = 8;
    Span<double> values = stackalloc double[size * size];
    for (var y = 0; y < size; y++)
    {
        var sourceY = Math.Clamp((int)Math.Round((y + 0.5) * image.Height / size), 0, Math.Max(0, image.Height - 1));
        for (var x = 0; x < size; x++)
        {
            var sourceX = Math.Clamp((int)Math.Round((x + 0.5) * image.Width / size), 0, Math.Max(0, image.Width - 1));
            var p = (sourceY * image.Width + sourceX) * 4;
            var b = image.Pixels[p];
            var g = image.Pixels[p + 1];
            var r = image.Pixels[p + 2];
            values[y * size + x] = r * 0.299 + g * 0.587 + b * 0.114;
        }
    }

    var avg = 0.0;
    for (var i = 0; i < values.Length; i++)
        avg += values[i];
    avg /= values.Length;

    ulong bits = 0;
    for (var i = 0; i < values.Length; i++)
    {
        if (values[i] >= avg)
            bits |= 1UL << i;
    }

    return bits.ToString("X16", CultureInfo.InvariantCulture);
}

static List<BagTemplateSlotMatchEvidence> ApplyBagTemplateMatchesToCleanup(
    CaptureResult capture,
    InventoryGridConfig selectedGrid,
    ItemPolicyConfig policy,
    string? templateIndexPath,
    double threshold,
    int innerPadding)
{
    var evidence = new List<BagTemplateSlotMatchEvidence>();
    if (string.IsNullOrWhiteSpace(templateIndexPath) || !File.Exists(templateIndexPath))
    {
        evidence.Add(new BagTemplateSlotMatchEvidence(
            -1,
            -1,
            -1,
            false,
            false,
            0,
            "",
            "UnknownProtected",
            "",
            "模板索引不存在，未应用模板匹配。"));
        return evidence;
    }

    var templates = LoadBagItemTemplates(templateIndexPath).ToArray();
    if (templates.Length == 0)
        return evidence;

    var log = new RuntimeLogService();
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var scan = inventory.Scan(capture, CopyGrid(selectedGrid));
    if (!scan.Success)
    {
        evidence.Add(new BagTemplateSlotMatchEvidence(
            -1,
            -1,
            -1,
            false,
            false,
            0,
            "",
            "UnknownProtected",
            "",
            scan.Message));
        return evidence;
    }

    foreach (var slot in scan.Slots.Where(s => s.State == InventorySlotState.Occupied).OrderBy(s => s.Index))
    {
        var icon = CropCaptureRect(
            capture,
            slot.X + innerPadding,
            slot.Y + innerPadding,
            slot.Width - innerPadding * 2,
            slot.Height - innerPadding * 2);
        var match = icon is null ? null : FindBestBagItemTemplateMatch(icon, templates);
        var best = match.GetValueOrDefault();
        var matched = match is not null && best.Score >= threshold;
        var policyName = matched ? NormalizeTemplatePolicy(best.Template.Policy) : "UnknownProtected";
        var itemName = matched ? best.Template.ItemName : "";
        var applied = false;
        var reason = "未命中可信模板，按未知物品保护。";

        if (matched)
        {
            if (selectedGrid.SlotNameOverrides.ContainsKey(slot.Index))
            {
                reason = "命中模板，但该格已有手工标注，保留手工标注。";
            }
            else if (string.Equals(policyName, "Ignore", StringComparison.OrdinalIgnoreCase)
                     || string.Equals(policyName, "UnknownProtected", StringComparison.OrdinalIgnoreCase))
            {
                reason = $"命中模板 {itemName}，策略 {policyName}，不写入可处理候选。";
            }
            else
            {
                selectedGrid.SlotNameOverrides[slot.Index] = itemName;
                selectedGrid.SlotNameSources[slot.Index] = "template-match";
                ApplyTemplatePolicyToCleanupPolicy(itemName, policyName, policy);
                applied = true;
                reason = $"命中模板 {itemName}，策略 {policyName}，已接入本次候选报告。";
            }
        }

        evidence.Add(new BagTemplateSlotMatchEvidence(
            slot.Index,
            slot.Row,
            slot.Column,
            matched,
            applied,
            matched ? best.Score : 0,
            itemName,
            policyName,
            matched ? best.Template.Id : "",
            reason));
    }

    return evidence;
}

static void ApplyTemplatePolicyToCleanupPolicy(string itemName, string policyName, ItemPolicyConfig policy)
{
    if (string.IsNullOrWhiteSpace(itemName))
        return;

    static void AddUnique(List<string> list, string value)
    {
        if (!list.Any(v => string.Equals(v.Trim(), value.Trim(), StringComparison.OrdinalIgnoreCase)))
            list.Add(value.Trim());
    }

    switch (NormalizeTemplatePolicy(policyName))
    {
        case "Keep":
            AddUnique(policy.KeepItems, itemName);
            break;
        case "Store":
            AddUnique(policy.StoreItems, itemName);
            break;
        case "Trade":
            AddUnique(policy.TradeItems, itemName);
            break;
        case "SellCandidate":
            AddUnique(policy.SellKeywords, itemName);
            break;
    }
}

static string ToCleanupDisplayStatus(ItemCleanupCandidate candidate)
{
    if (string.IsNullOrWhiteSpace(candidate.Slot.ItemName))
        return "待复核/未知保护";

    return candidate.Decision switch
    {
        ItemCleanupDecision.Keep => "保留",
        ItemCleanupDecision.Store => "存仓候选",
        ItemCleanupDecision.Trade => "交易候选",
        ItemCleanupDecision.SellCandidate => "出售候选",
        ItemCleanupDecision.BlockedUnknown => "待复核/未知保护",
        _ => "待复核/未知保护"
    };
}

static bool RunBagItemTemplateMatchDiagnostics(string[] args)
{
    Console.WriteLine("Bag item template match diagnostics");

    var imagePath = ReadOption(args, "--image")
                    ?? args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.OrdinalIgnoreCase));
    var indexPath = ReadOption(args, "--index")
                    ?? Path.Combine(Environment.CurrentDirectory, "data", "samples", "bag-items", "index.json");
    if (string.IsNullOrWhiteSpace(imagePath) || !File.Exists(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的背包 PNG 截图路径。");
        return false;
    }

    if (string.IsNullOrWhiteSpace(indexPath) || !File.Exists(indexPath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的模板索引 index.json。");
        return false;
    }

    var threshold = Math.Clamp(ReadDoubleOption(args, "--threshold", 0.92), 0.50, 1.0);
    var innerPadding = Math.Clamp(ReadIntOption(args, "--inner-padding", 1), 0, 8);
    var gridArgumentProvided = args.Any(a => a.Equals("--grid", StringComparison.OrdinalIgnoreCase));
    var manualGrid = ReadInventoryGridOption(args);
    if (gridArgumentProvided && manualGrid is null)
    {
        Console.Error.WriteLine("FAIL: --grid 格式无效，应为 x,y,列,行,格宽,格高[,横间距,纵间距]。");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 截图读取失败。");
        return false;
    }

    var templates = LoadBagItemTemplates(indexPath).ToArray();
    var log = new RuntimeLogService();
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var calibration = inventory.AutoCalibrate(capture);
    var selectedGrid = manualGrid ?? (calibration.Success ? calibration.Grid : null);
    var gridSource = manualGrid is not null ? "manual-argument" : calibration.Success ? "auto-calibration" : "none";
    if (selectedGrid is null)
    {
        Console.Error.WriteLine($"FAIL: {calibration.Message}");
        return false;
    }

    var scan = inventory.Scan(capture, CopyGrid(selectedGrid));
    if (!scan.Success)
    {
        Console.Error.WriteLine($"FAIL: {scan.Message}");
        return false;
    }

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var baseName = SanitizeFileName(Path.GetFileNameWithoutExtension(imagePath));
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "bag-item-template-match", $"{stamp}-{baseName}");
    var slotsDir = Path.Combine(evidenceDir, "slots");
    Directory.CreateDirectory(slotsDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "bag-grid-overlay.png");
    var evidencePath = Path.Combine(evidenceDir, "match.json");
    var clientSaved = SaveCapturePng(capture, clientPath);
    var overlaySaved = SaveGridOverlayPng(capture, selectedGrid, overlayPath);

    var results = new List<object>();
    var savedSlots = 0;
    foreach (var slot in scan.Slots.Where(s => s.State == InventorySlotState.Occupied).OrderBy(s => s.Index))
    {
        var icon = CropCaptureRect(
            capture,
            slot.X + innerPadding,
            slot.Y + innerPadding,
            slot.Width - innerPadding * 2,
            slot.Height - innerPadding * 2);
        var iconPath = Path.Combine(slotsDir, $"slot-{slot.Index:00}-r{slot.Row}c{slot.Column}-query.png");
        if (SaveCapturePng(icon, iconPath))
            savedSlots++;

        var match = icon is null ? null : FindBestBagItemTemplateMatch(icon, templates);
        var bestMatch = match.GetValueOrDefault();
        var matched = match is not null && bestMatch.Score >= threshold;
        var decision = matched ? NormalizeTemplatePolicy(bestMatch.Template.Policy) : "UnknownProtected";
        if (!matched || string.Equals(decision, "Ignore", StringComparison.OrdinalIgnoreCase))
            decision = "UnknownProtected";

        results.Add(new
        {
            slot.Index,
            slot.Row,
            slot.Column,
            slot.X,
            slot.Y,
            slot.Width,
            slot.Height,
            slot.OccupancyScore,
            queryIcon = new { path = iconPath, saved = icon is not null && File.Exists(iconPath) },
            matched,
            threshold,
            decision,
            protectedByDefault = !string.Equals(decision, "SellCandidate", StringComparison.OrdinalIgnoreCase),
            best = match is null
                ? null
                : new
                {
                    bestMatch.Score,
                    bestMatch.Template.Id,
                    bestMatch.Template.ItemName,
                    bestMatch.Template.Policy,
                    bestMatch.Template.IconPath,
                    bestMatch.Template.Sha256,
                    bestMatch.Template.AverageHash
                },
            reason = matched
                ? $"命中模板 {bestMatch.Template.ItemName}，策略 {decision}。"
                : "未命中可信模板，按未知物品保护。"
        });
    }

    var sellCandidateCount = results.Count(r =>
    {
        var decision = r.GetType().GetProperty("decision")?.GetValue(r)?.ToString();
        return string.Equals(decision, "SellCandidate", StringComparison.OrdinalIgnoreCase);
    });
    var matchedCount = results.Count(r =>
    {
        var matched = r.GetType().GetProperty("matched")?.GetValue(r);
        return matched is bool value && value;
    });

    var evidence = new
    {
        generatedAt = DateTimeOffset.Now,
        mode = "bag-item-template-match-no-game-access-no-click-no-sell",
        sourceImage = imagePath,
        indexPath,
        threshold,
        replayImage = clientPath,
        overlay = new { path = overlayPath, saved = overlaySaved },
        capture = new { capture.Width, capture.Height, saved = clientSaved, visual = HasVisualContent(capture) },
        safety = new
        {
            processAccess = false,
            sendsInput = false,
            clicksMouse = false,
            sellsItems = false,
            modifiesInventory = false,
            unknownItemsProtectedByDefault = true,
            sellCandidatesAreReportOnly = true
        },
        grid = new
        {
            source = gridSource,
            selectedGrid.X,
            selectedGrid.Y,
            selectedGrid.Columns,
            selectedGrid.Rows,
            selectedGrid.CellWidth,
            selectedGrid.CellHeight,
            selectedGrid.GapX,
            selectedGrid.GapY
        },
        templates = new
        {
            loaded = templates.Length,
            available = templates.Count(t => t.Icon is not null)
        },
        scan = new
        {
            scan.Success,
            scan.Message,
            scan.OccupiedCount,
            scan.EmptyCount,
            matchedCount,
            unknownProtectedCount = results.Count - matchedCount,
            sellCandidateCount,
            savedSlots
        },
        results
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Image={imagePath}");
    Console.WriteLine($"Index={indexPath}");
    Console.WriteLine($"Templates={templates.Length}, available={templates.Count(t => t.Icon is not null)}");
    Console.WriteLine($"Grid source={gridSource}, grid=({selectedGrid.X},{selectedGrid.Y}) {selectedGrid.Columns}x{selectedGrid.Rows}");
    Console.WriteLine($"Scan occupied={scan.OccupiedCount}, empty={scan.EmptyCount}");
    Console.WriteLine($"Matched={matchedCount}, UnknownProtected={results.Count - matchedCount}, SellCandidates={sellCandidateCount}, threshold={threshold:0.000}");
    Console.WriteLine($"Safety process=False, input=False, click=False, sell=False");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = clientSaved
             && overlaySaved
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && scan.Success
             && savedSlots == results.Count
             && sellCandidateCount <= matchedCount;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static double ReadDoubleOption(string[] args, string name, double fallback) =>
    double.TryParse(ReadOption(args, name), NumberStyles.Float, CultureInfo.InvariantCulture, out var value) ? value : fallback;

static IReadOnlyList<BagItemTemplateEntry> LoadBagItemTemplates(string indexPath)
{
    var root = JsonNode.Parse(File.ReadAllText(indexPath, Encoding.UTF8))?.AsObject();
    var templates = root?["templates"]?.AsArray();
    if (templates is null)
        return Array.Empty<BagItemTemplateEntry>();

    var result = new List<BagItemTemplateEntry>();
    var baseDir = Path.GetDirectoryName(Path.GetFullPath(indexPath)) ?? Environment.CurrentDirectory;
    foreach (var node in templates.OfType<JsonObject>())
    {
        var id = node["id"]?.GetValue<string>() ?? string.Empty;
        var itemName = node["itemName"]?.GetValue<string>() ?? string.Empty;
        var policy = NormalizeTemplatePolicy(node["policy"]?.GetValue<string>() ?? "UnknownProtected");
        var source = node["source"]?.AsObject();
        var image = node["image"]?.AsObject();
        var iconPath = ResolveRelativePath(baseDir, source?["iconPath"]?.GetValue<string>() ?? string.Empty);
        var icon = File.Exists(iconPath) ? LoadCapturePng(iconPath) : null;
        if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(itemName))
            continue;

        result.Add(new BagItemTemplateEntry(
            id,
            itemName,
            policy,
            iconPath,
            image?["sha256"]?.GetValue<string>() ?? string.Empty,
            image?["averageHash"]?.GetValue<string>() ?? string.Empty,
            icon));
    }

    return result;
}

static (BagItemTemplateEntry Template, double Score)? FindBestBagItemTemplateMatch(CaptureResult query, IReadOnlyList<BagItemTemplateEntry> templates)
{
    var bestTemplate = default(BagItemTemplateEntry);
    var bestScore = -1.0;
    foreach (var template in templates)
    {
        if (template.Icon is null)
            continue;

        var score = CompareIconSimilarity(query, template.Icon);
        if (score > bestScore)
        {
            bestScore = score;
            bestTemplate = template;
        }
    }

    return bestTemplate is null ? null : (bestTemplate, bestScore);
}

static double CompareIconSimilarity(CaptureResult a, CaptureResult b)
{
    if (a.Width <= 0 || a.Height <= 0 || b.Width <= 0 || b.Height <= 0)
        return 0.0;

    var width = Math.Min(a.Width, b.Width);
    var height = Math.Min(a.Height, b.Height);
    var total = 0.0;
    var count = 0;
    for (var y = 0; y < height; y++)
    {
        var ay = Math.Clamp((int)Math.Round((y + 0.5) * a.Height / height - 0.5), 0, a.Height - 1);
        var by = Math.Clamp((int)Math.Round((y + 0.5) * b.Height / height - 0.5), 0, b.Height - 1);
        for (var x = 0; x < width; x++)
        {
            var ax = Math.Clamp((int)Math.Round((x + 0.5) * a.Width / width - 0.5), 0, a.Width - 1);
            var bx = Math.Clamp((int)Math.Round((x + 0.5) * b.Width / width - 0.5), 0, b.Width - 1);
            var ap = (ay * a.Width + ax) * 4;
            var bp = (by * b.Width + bx) * 4;
            var diff = Math.Abs(a.Pixels[ap] - b.Pixels[bp])
                       + Math.Abs(a.Pixels[ap + 1] - b.Pixels[bp + 1])
                       + Math.Abs(a.Pixels[ap + 2] - b.Pixels[bp + 2]);
            total += diff / 3.0;
            count++;
        }
    }

    if (count == 0)
        return 0.0;

    return Math.Clamp(1.0 - total / count / 255.0, 0.0, 1.0);
}

static void ApplySlotNameOverrides(string[] args, InventoryGridConfig? grid)
{
    if (grid is null)
        return;

    var value = ReadOption(args, "--slot-names");
    if (string.IsNullOrWhiteSpace(value))
        return;

    var pairs = value.Split(';', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    foreach (var pair in pairs)
    {
        var separator = pair.IndexOf('=');
        if (separator < 0)
            separator = pair.IndexOf(':');
        if (separator <= 0 || separator + 1 >= pair.Length)
            continue;

        var rawIndex = pair[..separator].Trim();
        var name = pair[(separator + 1)..].Trim();
        if (!int.TryParse(rawIndex, out var index) || index < 0 || string.IsNullOrWhiteSpace(name))
            continue;

        grid.SlotNameOverrides[index] = name;
    }
}

static void AddDelimitedOptionValues(string[] args, string optionName, List<string> target)
{
    var value = ReadOption(args, optionName);
    if (string.IsNullOrWhiteSpace(value))
        return;

    foreach (var item in value.Split(new[] { ';', ',', '|', '\n' }, StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries))
    {
        if (!string.IsNullOrWhiteSpace(item))
            target.Add(item.Trim());
    }
}

static bool RunImageCombatRecognitionDiagnostics(string? inputPath)
{
    Console.WriteLine("Image combat recognition diagnostics");
    var imagePath = ResolveCombatImageInput(inputPath);
    if (string.IsNullOrWhiteSpace(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入存在的 client.png、live-recognition 证据目录或 recognition.json。");
        return false;
    }

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 战斗截图读取失败。");
        return false;
    }

    var log = new RuntimeLogService();
    var ocr = new TemplateOcrService(log);
    var runtimeData = new RuntimeDataService(log);
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var global = new GlobalConfigService(new MemoryProfileService(), log);
    var recognition = new CombatRecognitionService(new StaticClientCaptureService(capture), ocr, log);
    var window = DiagnosticWindow(new nint(0xC0DE), "image-combat-recognition", capture.Width, capture.Height);
    var combat = recognition.Recognize(window, global.Current.CombatRecognition);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var baseName = SanitizeFileName(Path.GetFileNameWithoutExtension(imagePath));
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "image-combat-recognition", $"{stamp}-{baseName}");
    Directory.CreateDirectory(evidenceDir);
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "combat-regions-overlay.png");
    var evidencePath = Path.Combine(evidenceDir, "recognition.json");
    var clientSaved = SaveCapturePng(capture, clientPath);
    var combatRegions = BuildCombatRegionEvidence(capture, global.Current.CombatRecognition, evidenceDir, combat);
    var overlaySaved = SaveCombatRegionsOverlayPng(capture, combatRegions, overlayPath);
    var targetProtection = BuildTargetProtectionEvidence(capture, global.Current.CombatRecognition, combat, combatRegions);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "static-image-no-process-no-input",
        sourceImage = imagePath,
        replayImage = clientPath,
        overlay = new { path = overlayPath, saved = overlaySaved },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        capture = new { capture.Width, capture.Height, visual = HasVisualContent(capture), saved = clientSaved },
        combat = new
        {
            combat.TargetNameText,
            combat.TargetHpText,
            combat.PlayerHpText,
            combat.PlayerMpText,
            combat.PetHpText,
            combat.TargetHpPercent,
            combat.PlayerHpPercent,
            combat.PlayerMpPercent,
            combat.PetHpPercent,
            combat.HasTarget,
            combat.TargetLooksLikePlayer,
            combat.TargetProtectionAmbiguous,
            combat.TargetLooksLikePet,
            combat.TargetIsAttackable,
            targetProtection,
            regions = combatRegions
        }
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Source={imagePath}");
    Console.WriteLine($"Capture={capture.Width}x{capture.Height}, visual={HasVisualContent(capture)}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Combat target='{combat.TargetNameText}', targetHp={combat.TargetHpPercent}, hp={combat.PlayerHpPercent}, mp={combat.PlayerMpPercent}, pet={combat.PetHpPercent}, player={combat.TargetLooksLikePlayer}, protectionRisk={combat.TargetProtectionAmbiguous}");
    Console.WriteLine($"Target protection decision={targetProtection.Decision}, protected={targetProtection.ProtectedByPlayerGuard}, statusBars={targetProtection.StatusBars.Matched}, schoolMarker={targetProtection.SchoolMarker.Matched}, portraitPlayerLike={targetProtection.Portrait.PlayerLike}");
    Console.WriteLine($"Combat regions saved={combatRegions.Count(r => r.Saved)}/{combatRegions.Length}, zoom={combatRegions.Count(r => r.ZoomSaved)}/{combatRegions.Length}, overlay={overlaySaved}");
