             && HasVisualContent(capture)
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && clientSaved
             && overlaySaved
             && combatRegions.All(r => r.Saved && r.ZoomSaved)
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunCombatSamplesDiagnostics(string? inputPath)
{
    Console.WriteLine("Combat sample replay diagnostics");

    var samplesRoot = string.IsNullOrWhiteSpace(inputPath)
        ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LongBanXing", "samples", "targets")
        : inputPath.Trim().Trim('"');

    if (!Directory.Exists(samplesRoot))
    {
        Console.Error.WriteLine($"FAIL: 样本目录不存在：{samplesRoot}");
        return false;
    }

    var sampleDirs = DiscoverCombatSampleDirectories(samplesRoot).ToList();
    if (sampleDirs.Count == 0)
    {
        Console.Error.WriteLine($"FAIL: 未找到包含 client.png 的目标样本目录：{samplesRoot}");
        return false;
    }

    var log = new RuntimeLogService();
    var ocr = new TemplateOcrService(log);
    var runtimeData = new RuntimeDataService(log);
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var global = new GlobalConfigService(new MemoryProfileService(), log);
    var targetSamples = new TargetProtectionSampleService(log);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceRoot = Path.Combine(Environment.CurrentDirectory, "artifacts", "combat-sample-replay", stamp);
    Directory.CreateDirectory(evidenceRoot);

    var results = new List<CombatSampleReplayResult>();
    for (var i = 0; i < sampleDirs.Count; i++)
    {
        var sampleDir = sampleDirs[i];
        var clientPath = Path.Combine(sampleDir, "client.png");
        var capture = LoadCapturePng(clientPath);
        var label = ReadCombatSampleLabel(sampleDir);
        var expected = ReadCombatSampleExpectedKind(sampleDir, label);
        var evidenceDir = Path.Combine(evidenceRoot, $"{i + 1:000}-{SanitizeFileName(Path.GetFileName(sampleDir))}");
        Directory.CreateDirectory(evidenceDir);

        if (capture is null)
        {
            results.Add(new CombatSampleReplayResult(
                sampleDir,
                label,
                expected,
                "unreadable",
                false,
                "client.png 读取失败",
                clientPath,
                evidenceDir,
                false,
                false,
                false,
                false,
                null,
                "",
                "",
                0,
                "",
                null,
                null,
                null,
                null));
            continue;
        }

        var recognition = new CombatRecognitionService(new StaticClientCaptureService(capture), ocr, log, targetSamples: targetSamples, global: global);
        var window = DiagnosticWindow(new nint(0xC0DE + i), "combat-sample-replay", capture.Width, capture.Height);
        var combat = recognition.Recognize(window, global.Current.CombatRecognition);
        var actual = ResolveCombatActualKind(combat);
        var (passed, reason) = EvaluateCombatSample(expected, combat, actual);

        var replayPath = Path.Combine(evidenceDir, "client.png");
        var overlayPath = Path.Combine(evidenceDir, "combat-regions-overlay.png");
        var replaySaved = SaveCapturePng(capture, replayPath);
        var combatRegions = BuildCombatRegionEvidence(capture, global.Current.CombatRecognition, evidenceDir, combat);
        var overlaySaved = SaveCombatRegionsOverlayPng(capture, combatRegions, overlayPath);

        var sampleEvidence = new
        {
            replayedAt = DateTimeOffset.Now,
            sampleDirectory = sampleDir,
            label,
            expectedKind = expected,
            actualKind = actual,
            passed,
            reason,
            replayImage = new { path = replayPath, saved = replaySaved },
            overlay = new { path = overlayPath, saved = overlaySaved },
            capture = new { capture.Width, capture.Height, visual = HasVisualContent(capture) },
            combat = new
            {
                combat.TargetNameText,
                combat.TargetHpText,
                combat.PlayerHpText,
                combat.PlayerMpText,
                combat.PetHpText,
                combat.TargetHpPercent,
                combat.PlayerHpPercent,
                combat.PlayerMpPercent,
                combat.PetHpPercent,
                combat.HasTarget,
                combat.TargetLooksLikePlayer,
                combat.TargetProtectionAmbiguous,
                combat.TargetLooksLikePet,
                combat.TargetIsAttackable,
                combat.TargetSampleKind,
                combat.TargetSampleLabel,
                combat.TargetSampleScore,
                combat.TargetSampleSource,
                regions = combatRegions
            }
        };
        var sampleEvidencePath = Path.Combine(evidenceDir, "recognition.json");
        File.WriteAllText(sampleEvidencePath, System.Text.Json.JsonSerializer.Serialize(sampleEvidence, JsonOptions()), new UTF8Encoding(false));

        results.Add(new CombatSampleReplayResult(
            sampleDir,
            label,
            expected,
            actual,
            passed,
            reason,
            clientPath,
            evidenceDir,
            combat.HasTarget,
            combat.TargetLooksLikePlayer,
            combat.TargetProtectionAmbiguous,
            combat.TargetLooksLikePet,
            combat.TargetIsAttackable,
            combat.TargetSampleKind,
            combat.TargetSampleLabel,
            combat.TargetSampleScore,
            combat.TargetSampleSource,
            combat.TargetHpPercent,
            combat.PlayerHpPercent,
            combat.PlayerMpPercent,
            combat.PetHpPercent));

        Console.WriteLine($"{i + 1:000}. expected={expected}, actual={actual}, pass={FormatPass(passed)}, label='{label}', reason={reason}");
    }

    var summaryPath = Path.Combine(evidenceRoot, "summary.json");
    var summary = new
    {
        replayedAt = DateTimeOffset.Now,
        mode = "static-sample-replay-no-process-no-input",
        samplesRoot,
        evidenceRoot,
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        total = results.Count,
        passed = results.Count(r => r.Passed == true),
        failed = results.Count(r => r.Passed == false),
        uncheckedCount = results.Count(r => r.Passed is null),
        results
    };
    File.WriteAllText(summaryPath, System.Text.Json.JsonSerializer.Serialize(summary, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Samples={results.Count}, pass={results.Count(r => r.Passed == true)}, fail={results.Count(r => r.Passed == false)}, unchecked={results.Count(r => r.Passed is null)}");
    Console.WriteLine($"Dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Evidence={summaryPath}");

    var ok = results.Count > 0
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && results.All(r => r.Passed != false)
             && File.Exists(summaryPath)
             && new FileInfo(summaryPath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunCombatSampleHealthDiagnostics(string? inputPath)
{
    Console.WriteLine("Combat sample health diagnostics");

    var samplesRoot = string.IsNullOrWhiteSpace(inputPath)
        ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LongBanXing", "samples", "targets")
        : inputPath.Trim().Trim('"');

    var requiredRegions = new[]
    {
        "target_name",
        "target_hp",
        "target_mp",
        "target_rage",
        "target_status",
        "school_marker",
        "target_portrait",
        "player_hp",
        "player_mp",
        "player_rage",
        "pet_hp"
    };

    var sampleDirs = Directory.Exists(samplesRoot)
        ? DiscoverCombatSampleDirectories(samplesRoot).ToArray()
        : Array.Empty<string>();

    var results = new List<CombatSampleHealthResult>();
    foreach (var sampleDir in sampleDirs)
    {
        var label = ReadCombatSampleLabel(sampleDir);
        var expected = ReadCombatSampleExpectedKind(sampleDir, label);
        var metadataPath = Path.Combine(sampleDir, "metadata.json");
        var clientPath = Path.Combine(sampleDir, "client.png");
        var overlayPath = Path.Combine(sampleDir, "overlay.png");
        var cropsDir = Path.Combine(sampleDir, "crops");
        var metadataRegions = ReadCombatSampleRegionKeys(metadataPath);
        var cropRegionKeys = Directory.Exists(cropsDir)
            ? Directory.EnumerateFiles(cropsDir, "*.png", SearchOption.TopDirectoryOnly)
                .Select(Path.GetFileNameWithoutExtension)
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Select(v => v!.Split('_').Length >= 2 ? $"{v.Split('_')[0]}_{v.Split('_')[1]}" : v)
                .ToHashSet(StringComparer.OrdinalIgnoreCase)
            : new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        var presentRegions = new HashSet<string>(metadataRegions, StringComparer.OrdinalIgnoreCase);
        presentRegions.UnionWith(cropRegionKeys);
        var missingRegions = requiredRegions
            .Where(r => !presentRegions.Contains(r))
            .ToArray();

        var clientOk = File.Exists(clientPath) && new FileInfo(clientPath).Length > 0;
        var overlayOk = File.Exists(overlayPath) && new FileInfo(overlayPath).Length > 0;
        var metadataOk = File.Exists(metadataPath) && new FileInfo(metadataPath).Length > 0;
        var readyForReplay = clientOk && metadataOk && expected != "unknown";
        var readyForTemplate = readyForReplay && missingRegions.Length == 0;

        results.Add(new CombatSampleHealthResult(
            sampleDir,
            label,
            expected,
            clientOk,
            overlayOk,
            metadataOk,
            readyForReplay,
            readyForTemplate,
            presentRegions.OrderBy(v => v, StringComparer.OrdinalIgnoreCase).ToArray(),
            missingRegions));
    }

    var counts = results
        .GroupBy(r => r.ExpectedKind, StringComparer.OrdinalIgnoreCase)
        .ToDictionary(g => g.Key, g => g.Count(), StringComparer.OrdinalIgnoreCase);
    int Count(string kind) => counts.TryGetValue(kind, out var value) ? value : 0;
    var monsterLike = Count("monster") + Count("boss") + Count("elite");
    var recommendedReady = Count("player") >= 3
                           && Count("monster") >= 3
                           && Count("boss") + Count("elite") >= 2
                           && Count("pet") >= 1
                           && Count("none") >= 1
                           && results.Where(r => r.ExpectedKind != "unknown").All(r => r.ReadyForTemplate);
    var minimalReady = Count("player") >= 1
                       && monsterLike >= 1
                       && results.Where(r => r.ExpectedKind is "player" or "monster" or "boss" or "elite").All(r => r.ReadyForTemplate);

    var missingRecommended = new List<string>();
    if (Count("player") < 3)
        missingRecommended.Add($"玩家样本还需 {3 - Count("player")} 个");
    if (Count("monster") < 3)
        missingRecommended.Add($"普通怪物样本还需 {3 - Count("monster")} 个");
    if (Count("boss") + Count("elite") < 2)
        missingRecommended.Add($"首领/BOSS 样本还需 {2 - Count("boss") - Count("elite")} 个");
    if (Count("pet") < 1)
        missingRecommended.Add("宠物/宝宝样本还需 1 个");
    if (Count("none") < 1)
        missingRecommended.Add("无目标样本还需 1 个");
    if (results.Any(r => r.ExpectedKind != "unknown" && !r.ReadyForTemplate))
        missingRecommended.Add("部分已标注样本缺少必需裁剪区域或 metadata");

    var templateGate = BuildTargetProtectionTemplateGate(results);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "combat-sample-health");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"combat-sample-health-{stamp}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "offline-combat-sample-health-no-process-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        samplesRoot,
        requiredRegions,
        total = results.Count,
        counts,
        minimalReady,
        recommendedReady,
        targetProtectionTemplateGate = templateGate,
        missingRecommended,
        results
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Root={samplesRoot}");
    Console.WriteLine($"Samples={results.Count}, player={Count("player")}, monster={Count("monster")}, boss={Count("boss") + Count("elite")}, pet={Count("pet")}, none={Count("none")}, unknown={Count("unknown")}");
    Console.WriteLine($"MinimalReady={minimalReady}, RecommendedReady={recommendedReady}");
    Console.WriteLine($"TemplateGate={templateGate.Status}, readyToBuild={templateGate.ReadyToBuildTemplates}, businessReady={templateGate.BusinessDecisionReady}");
    Console.WriteLine($"TemplateGateReason={templateGate.Reason}");
    if (missingRecommended.Count > 0)
        Console.WriteLine($"Missing={string.Join("；", missingRecommended)}");
    foreach (var item in results.Take(12))
    {
        Console.WriteLine($"  {Path.GetFileName(item.Directory)}: expected={item.ExpectedKind}, replay={item.ReadyForReplay}, template={item.ReadyForTemplate}, missingRegions={item.MissingRegions.Count}");
    }
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine("PASS");
    return true;
}

