        var metadataRegions = ReadCombatSampleRegionKeys(metadataPath);
        var cropRegionKeys = Directory.Exists(cropsDir)
            ? Directory.EnumerateFiles(cropsDir, "*.png", SearchOption.TopDirectoryOnly)
                .Select(Path.GetFileNameWithoutExtension)
                .Where(v => !string.IsNullOrWhiteSpace(v))
                .Select(v => v!.Split('_').Length >= 2 ? $"{v.Split('_')[0]}_{v.Split('_')[1]}" : v)
                .ToHashSet(StringComparer.OrdinalIgnoreCase)
            : new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        var presentRegions = new HashSet<string>(metadataRegions, StringComparer.OrdinalIgnoreCase);
        presentRegions.UnionWith(cropRegionKeys);
        var missingRegions = requiredRegions
            .Where(r => !presentRegions.Contains(r))
            .ToArray();

        var clientOk = File.Exists(clientPath) && new FileInfo(clientPath).Length > 0;
        var overlayOk = File.Exists(overlayPath) && new FileInfo(overlayPath).Length > 0;
        var metadataOk = File.Exists(metadataPath) && new FileInfo(metadataPath).Length > 0;
        var readyForReplay = clientOk && metadataOk && expected != "unknown";
        var readyForTemplate = readyForReplay && missingRegions.Length == 0;

        results.Add(new CombatSampleHealthResult(
