            clicksMouse = false,
            opensProcessForVmRead = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            promotesSamples = false,
            modifiesSampleLibrary = false
        },
        samplesRoot,
        counts = new
        {
            player = readyPlayers,
            monster = readyMonsters,
            boss = readyBosses,
            pet = readyPets,
            none = readyNone
        },
        recommendedReady,
        recommendations,
        guardrail = "历史候选中的 player-or-ambiguous 只能人工复核；不能为了凑数直接提升，否则会污染玩家保护和 BOSS/人形怪边界。"
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Root={samplesRoot}");
    Console.WriteLine($"ReadyCounts=player:{readyPlayers}/3, monster:{readyMonsters}/3, boss:{readyBosses}/2, pet:{readyPets}/1, none:{readyNone}/1");
    Console.WriteLine($"RecommendedReady={recommendedReady}");
    if (recommendations.Count == 0)
    {
        Console.WriteLine("Next=样本覆盖已达到推荐门槛。");
    }
    else
    {
        Console.WriteLine("Next:");
        foreach (var item in recommendations)
            Console.WriteLine($"  - {item.Kind}: 还需 {item.Missing} 个；{item.Scene}");
    }
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine("PASS");
    return true;
}

static void AddRecommendation(
    List<CombatSampleNextRecommendation> recommendations,
    string kind,
    int ready,
    int required,
    string reason,
    string scene,
    string capture)
{
    if (ready >= required)
        return;

    recommendations.Add(new CombatSampleNextRecommendation(
        Kind: kind,
        Ready: ready,
        Required: required,
        Missing: required - ready,
        Reason: reason,
        Scene: scene,
        Capture: capture));
}

static TargetProtectionTemplateGateEvidence BuildTargetProtectionTemplateGate(IReadOnlyList<CombatSampleHealthResult> results)
{
    var readyPlayers = results.Count(r => r.ExpectedKind.Equals("player", StringComparison.OrdinalIgnoreCase) && r.ReadyForTemplate);
    var readyMonsters = results.Count(r => r.ExpectedKind.Equals("monster", StringComparison.OrdinalIgnoreCase) && r.ReadyForTemplate);
    var readyBosses = results.Count(r => (r.ExpectedKind.Equals("boss", StringComparison.OrdinalIgnoreCase) || r.ExpectedKind.Equals("elite", StringComparison.OrdinalIgnoreCase)) && r.ReadyForTemplate);
    var readyPets = results.Count(r => r.ExpectedKind.Equals("pet", StringComparison.OrdinalIgnoreCase) && r.ReadyForTemplate);
    var readyNone = results.Count(r => r.ExpectedKind.Equals("none", StringComparison.OrdinalIgnoreCase) && r.ReadyForTemplate);

    var minimalNegativeSet = readyMonsters + readyBosses;
    var readyToStartResearch = readyPlayers >= 1 && minimalNegativeSet >= 1;
    var readyToBuildTemplates = readyPlayers >= 3
                                && readyMonsters >= 3
                                && readyBosses >= 2
                                && readyPets >= 1
                                && readyNone >= 1;

    var missing = new List<string>();
    if (readyPlayers < 3) missing.Add($"玩家模板样本还需 {3 - readyPlayers} 个");
    if (readyMonsters < 3) missing.Add($"普通怪物反例还需 {3 - readyMonsters} 个");
    if (readyBosses < 2) missing.Add($"首领/BOSS反例还需 {2 - readyBosses} 个");
    if (readyPets < 1) missing.Add("宠物反例还需 1 个");
    if (readyNone < 1) missing.Add("无目标反例还需 1 个");

    var status = readyToBuildTemplates
        ? "ReadyToBuildTemplateClassifier"
        : readyToStartResearch
            ? "ProtectiveBlockEnabledInsufficientForClassifier"
            : "BlockedMissingSamples";
    var reason = readyToBuildTemplates
        ? "样本覆盖已满足模板分类器训练/阈值标定的最低安全门槛；仍需实现并回归验证模板匹配后，才允许把门派/头像升级为高置信玩家分类。"
        : readyToStartResearch
            ? "样本覆盖不足以做高置信玩家分类；门派竖牌/头像类结构已作为高风险保护性阻断信号接入，默认不攻击，避免误伤玩家。"
            : "样本覆盖不足，门派竖牌/头像仍只能作为诊断辅助；未满足最小正反样本前不能进入业务判断。";

    return new TargetProtectionTemplateGateEvidence(
        Status: status,
        ReadyToStartResearch: readyToStartResearch,
        ReadyToBuildTemplates: readyToBuildTemplates,
        BusinessDecisionReady: readyToStartResearch,
        CanUseSchoolMarkerForPlayerProtection: readyToStartResearch,
        CanUsePortraitForPlayerProtection: false,
        ReadyPlayerSamples: readyPlayers,
        ReadyMonsterSamples: readyMonsters,
        ReadyBossOrEliteSamples: readyBosses,
        ReadyPetSamples: readyPets,
        ReadyNoTargetSamples: readyNone,
        Missing: missing,
        Reason: reason);
}

static bool RunTargetProtectionIndexDiagnostics(string[] args)
{
    Console.WriteLine("Target protection sample index diagnostics");

    var samplesRoot = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LongBanXing", "samples", "targets");
    var outputPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LongBanXing", "samples", "target-protection-index.json");

    for (var i = 0; i < args.Length; i++)
    {
        var arg = args[i].Trim().Trim('"');
        if (string.Equals(arg, "--output", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
        {
            outputPath = args[++i].Trim().Trim('"');
            continue;
        }

        if (!arg.StartsWith("-", StringComparison.Ordinal))
            samplesRoot = arg;
    }

    if (!Directory.Exists(samplesRoot))
    {
        Console.Error.WriteLine($"FAIL: 样本目录不存在：{samplesRoot}");
        return false;
    }

    var samples = new JsonArray();
    var skipped = 0;
    foreach (var sampleDir in DiscoverCombatSampleDirectories(samplesRoot))
    {
        var label = ReadCombatSampleLabel(sampleDir);
        var kind = ReadCombatSampleExpectedKind(sampleDir, label);
        if (kind is "unknown" or "none")
        {
            skipped++;
            continue;
        }

        var crops = Path.Combine(sampleDir, "crops");
        var schoolMarkerHash = TryReadCropHash(crops, "school-marker.png");
        var portraitHash = TryReadCropHash(crops, "target-portrait.png");
        var statusHash = TryReadCropHash(crops, "target-status.png");
        if (string.IsNullOrWhiteSpace(schoolMarkerHash)
            && string.IsNullOrWhiteSpace(portraitHash)
            && string.IsNullOrWhiteSpace(statusHash))
        {
            skipped++;
            continue;
        }

        samples.Add(new JsonObject
        {
            ["sampleId"] = Path.GetFileName(sampleDir),
            ["label"] = label,
            ["kind"] = kind,
            ["sourcePath"] = sampleDir,
            ["schoolMarkerHash"] = schoolMarkerHash,
            ["targetPortraitHash"] = portraitHash,
            ["targetStatusHash"] = statusHash
        });
    }

    Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!);
    var root = new JsonObject
    {
        ["schemaVersion"] = 1,
        ["createdAt"] = DateTimeOffset.Now.ToString("O"),
        ["samplesRoot"] = samplesRoot,
        ["samples"] = samples,
        ["notes"] = "只读目标保护样本索引；由目标采集样本生成，不访问游戏、不发送输入。"
    };
    File.WriteAllText(outputPath, root.ToJsonString(JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Samples={samples.Count}, skipped={skipped}");
    Console.WriteLine($"Index={outputPath}");
    Console.WriteLine(samples.Count > 0 ? "PASS" : "FAIL");
    return samples.Count > 0;
}

static string TryReadCropHash(string cropsDir, string fileName)
{
    var path = ResolveTargetProtectionCropPath(cropsDir, fileName);
    var capture = File.Exists(path) ? LoadCapturePng(path) : null;
    return capture is null ? "" : ComputeAverageHash64(capture);
}

static string ResolveTargetProtectionCropPath(string cropsDir, string fileName)
{
    var exact = Path.Combine(cropsDir, fileName);
    if (File.Exists(exact))
        return exact;

    if (!Directory.Exists(cropsDir))
        return exact;

    var key = Path.GetFileNameWithoutExtension(fileName).Replace('-', '_');
    var hyphenKey = key.Replace('_', '-');
    return Directory.EnumerateFiles(cropsDir, "*.png")
        .OrderBy(p => p, StringComparer.OrdinalIgnoreCase)
        .FirstOrDefault(path =>
        {
            var name = Path.GetFileNameWithoutExtension(path);
            return name.Equals(key, StringComparison.OrdinalIgnoreCase)
                   || name.Equals(hyphenKey, StringComparison.OrdinalIgnoreCase)
                   || name.StartsWith(key + "_", StringComparison.OrdinalIgnoreCase)
                   || name.StartsWith(hyphenKey + "-", StringComparison.OrdinalIgnoreCase);
        }) ?? exact;
}

static bool RunCombatSamplePromoteDiagnostics(string[] args)
{
    Console.WriteLine("Combat sample promote diagnostics");

    var sourceArg = args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.Ordinal));
    var imagePath = ResolveCombatImageInput(sourceArg);
    if (string.IsNullOrWhiteSpace(imagePath))
    {
        Console.Error.WriteLine("FAIL: 请传入证据目录、recognition.json 或 client.png。");
        return false;
    }

    var kind = ReadOption(args, "--kind");
    if (!IsKnownCombatSampleKind(kind))
    {
        Console.Error.WriteLine("FAIL: --kind 必须是 player、monster、boss、elite、pet、none 或 unknown。");
        return false;
    }

    kind = kind!.Trim().ToLowerInvariant();
    var allowRiskyPromotion = args.Any(a => a.Equals("--allow-risk", StringComparison.OrdinalIgnoreCase));
    var label = ReadOption(args, "--label");
    if (string.IsNullOrWhiteSpace(label))
        label = $"{kind}_{Path.GetFileName(Path.GetDirectoryName(imagePath)) ?? Path.GetFileNameWithoutExtension(imagePath)}";

    var outputRoot = ReadOption(args, "--output");
    if (string.IsNullOrWhiteSpace(outputRoot))
    {
        outputRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "LongBanXing",
            "samples",
            "targets");
    }
    outputRoot = outputRoot!.Trim().Trim('"');

    var capture = LoadCapturePng(imagePath);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: client.png 读取失败。");
        return false;
    }

    var log = new RuntimeLogService();
    var ocr = new TemplateOcrService(log);
    var runtimeData = new RuntimeDataService(log);
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var global = new GlobalConfigService(new MemoryProfileService(), log);
    var recognition = new CombatRecognitionService(new StaticClientCaptureService(capture), ocr, log);
    var window = DiagnosticWindow(new nint(0xC0DE), "combat-sample-promote", capture.Width, capture.Height);
    var combat = recognition.Recognize(window, global.Current.CombatRecognition);
    var promotionRiskReasons = BuildCombatSamplePromotionRiskReasons(kind, combat).ToArray();
    if (promotionRiskReasons.Length > 0 && !allowRiskyPromotion)
    {
        Console.Error.WriteLine("FAIL: 样本提升被安全门禁拒绝。");
        Console.Error.WriteLine("Reason=" + string.Join(", ", promotionRiskReasons));
        Console.Error.WriteLine("如确认为人工复核过的特殊样本，可追加 --allow-risk；默认不建议对攻击放行样本使用。");
        return false;
    }

    var timestamp = DateTime.Now;
    var sampleName = $"{timestamp:yyyyMMdd-HHmmssfff}_{SanitizeFileName(label)}";
    var sampleDir = Path.Combine(outputRoot, sampleName);
    var cropsDir = Path.Combine(sampleDir, "crops");
    Directory.CreateDirectory(cropsDir);

    var clientPath = Path.Combine(sampleDir, "client.png");
    var overlayPath = Path.Combine(sampleDir, "overlay.png");
    var copiedClient = SaveCapturePng(capture, clientPath);
    var combatRegions = BuildCombatRegionEvidence(capture, global.Current.CombatRecognition, cropsDir, combat);
    var overlaySaved = SaveCombatRegionsOverlayPng(capture, combatRegions, overlayPath);
    var sourceRecognition = ResolveSourceRecognitionPath(sourceArg);
    var targetProtection = BuildTargetProtectionEvidence(capture, global.Current.CombatRecognition, combat, combatRegions);

    var metadata = new TargetSampleMetadataEvidence(
        SchemaVersion: 3,
        CreatedAt: timestamp.ToString("O"),
        Label: label.Trim(),
        ExpectedKind: kind,
        Source: new TargetSampleSourceEvidence(
            SourcePath: sourceArg?.Trim().Trim('"') ?? imagePath,
            SourceImagePath: imagePath,
            SourceRecognitionPath: sourceRecognition ?? string.Empty,
            PromoteMode: "combat-sample-promote"),
        Window: new TargetSampleWindowEvidence(
            Hwnd: window.Id,
            Pid: window.Pid,
            Title: window.Title,
            ProcessName: window.ProcessName,
            ProcessPath: window.ProcessPath,
            Bitness: window.Bitness.ToString(),
            ClientWidth: capture.Width,
            ClientHeight: capture.Height),
        TargetOffset: new TargetSampleOffsetEvidence(0, 0),
        Files: new TargetSampleFilesEvidence("client.png", "overlay.png", "crops"),
        Regions: combatRegions.Select(r => new TargetSampleRegionEvidence(
            Key: NormalizeCombatRegionKey(r.Name),
            Title: CombatRegionTitle(r.Name),
            FileName: Path.GetFileName(r.Path),
            ZoomFileName: Path.GetFileName(r.ZoomPath),
            Region: new OcrResolvedRegion(r.ResolvedX, r.ResolvedY, r.ResolvedWidth, r.ResolvedHeight))).ToArray(),
        Recognition: new TargetSampleRecognitionEvidence(
            ActualKind: ResolveCombatActualKind(combat),
            TargetLooksLikePlayer: combat.TargetLooksLikePlayer,
            TargetProtectionAmbiguous: combat.TargetProtectionAmbiguous,
            TargetLooksLikePet: combat.TargetLooksLikePet,
            TargetHpPercent: combat.TargetHpPercent,
            PlayerHpPercent: combat.PlayerHpPercent,
            PlayerMpPercent: combat.PlayerMpPercent,
            PetHpPercent: combat.PetHpPercent,
            TargetProtectionDecision: targetProtection.Decision));

    var metadataPath = Path.Combine(sampleDir, "metadata.json");
    File.WriteAllText(metadataPath, System.Text.Json.JsonSerializer.Serialize(metadata, JsonOptions()), new UTF8Encoding(false));

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "combat-sample-promote");
    Directory.CreateDirectory(evidenceDir);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidencePath = Path.Combine(evidenceDir, $"combat-sample-promote-{stamp}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "offline-combat-sample-promote-no-process-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        sourceImage = imagePath,
        sampleDirectory = sampleDir,
        expectedKind = kind,
        label,
        allowRiskyPromotion,
        promotionRiskReasons,
        copiedClient,
        overlaySaved,
        cropsSaved = combatRegions.Count(r => r.Saved),
        cropsTotal = combatRegions.Length,
        metadataPath,
        dictionaryFiles = dictionaryFiles.Count,
        loadedGlyphsDelta = dictionaryLoad.LoadedGlyphs,
        recognition = metadata.Recognition,
        targetProtection
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    var ok = copiedClient
             && overlaySaved
             && combatRegions.Length >= 11
             && combatRegions.All(r => r.Saved && r.ZoomSaved)
             && File.Exists(metadataPath)
             && new FileInfo(metadataPath).Length > 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine($"Source={imagePath}");
    Console.WriteLine($"Sample={sampleDir}");
    Console.WriteLine($"ExpectedKind={kind}, actual={metadata.Recognition.ActualKind}, targetProtection={metadata.Recognition.TargetProtectionDecision}");
    Console.WriteLine($"Files client={copiedClient}, overlay={overlaySaved}, crops={combatRegions.Count(r => r.Saved)}/{combatRegions.Length}");
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static IEnumerable<string> BuildCombatSamplePromotionRiskReasons(string kind, CombatRecognitionResult combat)
{
    var normalizedKind = kind.Trim().ToLowerInvariant();
    var attackReleaseSample = normalizedKind is "monster" or "boss" or "elite";

    if (attackReleaseSample)
    {
        if (!combat.HasTarget)
            yield return "attack-release-sample-has-no-target";
        if (combat.TargetLooksLikePlayer)
            yield return "attack-release-sample-player-like";
        if (combat.TargetProtectionAmbiguous)
            yield return "attack-release-sample-ambiguous-player-risk";
        if (combat.TargetLooksLikePet)
            yield return "attack-release-sample-pet-like";
    }

    if (normalizedKind == "none" && combat.HasTarget)
        yield return "none-sample-but-target-detected";

    if (normalizedKind == "pet" && (combat.TargetLooksLikePlayer || combat.TargetProtectionAmbiguous))
        yield return "pet-sample-player-like-or-ambiguous";

    if (normalizedKind == "player" && combat.TargetLooksLikePet)
        yield return "player-sample-pet-like";
}

static bool RunCombatSampleCandidatesDiagnostics(string[] args)
{
    Console.WriteLine("Combat sample candidates diagnostics");

    var rootArg = args.FirstOrDefault(a => !a.StartsWith("--", StringComparison.Ordinal));
    var root = string.IsNullOrWhiteSpace(rootArg)
        ? Path.Combine(Environment.CurrentDirectory, "artifacts", "live-normal-hang-preview")
        : rootArg.Trim().Trim('"');

    if (!Directory.Exists(root))
    {
        Console.Error.WriteLine($"FAIL: 预览根目录不存在：{root}");
        return false;
    }

    var output = ReadOption(args, "--output");
    if (string.IsNullOrWhiteSpace(output))
    {
        var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
        output = Path.Combine(Environment.CurrentDirectory, "artifacts", "combat-sample-candidates", stamp);
    }
    output = output!.Trim().Trim('"');
    Directory.CreateDirectory(output);

    var candidates = DiscoverCombatSampleDirectories(root)
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .OrderByDescending(Directory.GetLastWriteTime)
        .Select(ReadCombatSampleCandidate)
        .ToArray();

    var jsonPath = Path.Combine(output, "combat-sample-candidates.json");
    var tsvPath = Path.Combine(output, "combat-sample-candidates.tsv");
    var htmlPath = Path.Combine(output, "combat-sample-candidates.html");
    var safety = new
    {
        processAccess = false,
        sendsInput = false,
        clicksMouse = false,
        readsGameStateMemory = false,
        writesMemory = false,
        injectsDll = false,
        promotesSamples = false,
        modifiesSampleLibrary = false
    };
    File.WriteAllText(jsonPath, System.Text.Json.JsonSerializer.Serialize(new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "offline-combat-sample-candidates-no-process-no-input",
        root,
        output,
        safety,
        totals = new
        {
            candidates.Length,
            recommended = candidates.Count(c => c.Recommendation == "review-for-promotion"),
            protectOnly = candidates.Count(c => c.Recommendation == "protect-only-review"),
            notRecommended = candidates.Count(c => c.Recommendation == "not-recommended")
        },
        candidates
    }, JsonOptions()), new UTF8Encoding(false));

    var sb = new StringBuilder();
    sb.AppendLine("name\trecommendation\tsuggestedKind\trisk\ttargetHp\tplayerLike\tambiguous\tpetLike\tattackable\tcompleteRegions\treason\tsource");
    foreach (var item in candidates)
    {
        sb.AppendLine(string.Join('\t', new[]
        {
            item.Name,
            item.Recommendation,
            item.SuggestedKind,
            item.Risk,
            item.TargetHpPercent?.ToString(CultureInfo.InvariantCulture) ?? "",
            item.TargetLooksLikePlayer?.ToString() ?? "",
            item.TargetProtectionAmbiguous?.ToString() ?? "",
            item.TargetLooksLikePet?.ToString() ?? "",
            item.TargetIsAttackable?.ToString() ?? "",
            item.CompleteRegions.ToString(CultureInfo.InvariantCulture),
            item.Reason.Replace('\t', ' '),
            item.SourcePath
        }));
    }
    File.WriteAllText(tsvPath, sb.ToString(), new UTF8Encoding(false));
    File.WriteAllText(htmlPath, BuildCombatSampleCandidatesHtml(candidates, root), new UTF8Encoding(false));

    Console.WriteLine($"Root={root}");
    Console.WriteLine($"Candidates={candidates.Length}, recommended={candidates.Count(c => c.Recommendation == "review-for-promotion")}, protectOnly={candidates.Count(c => c.Recommendation == "protect-only-review")}, notRecommended={candidates.Count(c => c.Recommendation == "not-recommended")}");
    foreach (var item in candidates.Take(12))
        Console.WriteLine($"{item.Name}: {item.Recommendation}/{item.SuggestedKind}, risk={item.Risk}, hp={item.TargetHpPercent?.ToString(CultureInfo.InvariantCulture) ?? "-"}, reason={item.Reason}");
    Console.WriteLine($"Report={tsvPath}");
    Console.WriteLine($"Review={htmlPath}");
    Console.WriteLine($"Evidence={jsonPath}");
    Console.WriteLine("PASS");
    return File.Exists(jsonPath) && File.Exists(tsvPath) && File.Exists(htmlPath);
}

static string BuildCombatSampleCandidatesHtml(IReadOnlyList<CombatSampleCandidateEvidence> candidates, string root)
{
    var sb = new StringBuilder();
    sb.AppendLine("<!doctype html>");
    sb.AppendLine("<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><title>Combat Sample Candidates</title>");
    sb.AppendLine("<style>");
    sb.AppendLine("body{margin:0;background:#0b1017;color:#dce6f3;font:14px/1.45 'Segoe UI','Microsoft YaHei',sans-serif}header{position:sticky;top:0;background:#101823;border-bottom:1px solid #263344;padding:16px 22px;z-index:2}h1{margin:0 0 6px;font-size:20px}.meta{color:#91a4bc}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(440px,1fr));gap:16px;padding:18px}.card{background:#131b26;border:1px solid #2a3748;border-radius:8px;overflow:hidden}.head{display:flex;gap:8px;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid #263344}.name{font-weight:700}.badge{padding:3px 8px;border-radius:999px;font-size:12px}.ok{background:#123c2d;color:#8ff0b3}.protect{background:#3b2e12;color:#ffd37a}.bad{background:#3b1720;color:#ff9eb0}.risk{color:#9fb1c6}.shot{display:block;width:100%;height:250px;object-fit:contain;background:#06090d}.crops{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:10px 12px}.crop{min-width:0}.crop img{display:block;width:100%;height:56px;object-fit:contain;background:#06090d;border:1px solid #2a3748;border-radius:4px}.crop span{display:block;margin-top:3px;color:#91a4bc;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.kv{display:grid;grid-template-columns:110px 1fr;gap:3px 10px;padding:0 12px 12px;color:#bfd0e4}.kv div:nth-child(odd){color:#7f93ad}.path{font-family:Consolas,monospace;font-size:11px;word-break:break-all;color:#7f93ad;border-top:1px solid #263344;padding:9px 12px}");
    sb.AppendLine("</style></head><body>");
    sb.AppendLine("<header>");
    sb.AppendLine("<h1>目标样本候选复核</h1>");
    sb.AppendLine($"<div class=\"meta\">Root: {HtmlEscape(root)} | total={candidates.Count} | review-for-promotion={candidates.Count(c => c.Recommendation == "review-for-promotion")} | protect-only-review={candidates.Count(c => c.Recommendation == "protect-only-review")}</div>");
    sb.AppendLine("</header><main class=\"grid\">");

    foreach (var item in candidates)
    {
        var badgeClass = item.Recommendation switch
        {
            "review-for-promotion" => "ok",
            "protect-only-review" => "protect",
            _ => "bad"
        };
        sb.AppendLine("<section class=\"card\">");
        sb.AppendLine("<div class=\"head\">");
        sb.AppendLine($"<span class=\"name\">{HtmlEscape(item.Name)}</span><span class=\"badge {badgeClass}\">{HtmlEscape(item.Recommendation)} / {HtmlEscape(item.SuggestedKind)}</span>");
        sb.AppendLine("</div>");
        sb.AppendLine($"<a href=\"{FileUri(item.ClientImagePath)}\"><img class=\"shot\" src=\"{FileUri(item.ClientImagePath)}\" alt=\"client\"></a>");
        sb.AppendLine("<div class=\"crops\">");
        AddCandidateCrop(sb, item.SourcePath, "target-name.png", "target-name");
        AddCandidateCrop(sb, item.SourcePath, "target-hp.png", "target-hp");
        AddCandidateCrop(sb, item.SourcePath, "target-status.png", "target-status");
        AddCandidateCrop(sb, item.SourcePath, "school-marker.png", "school-marker");
        AddCandidateCrop(sb, item.SourcePath, "target-portrait.png", "target-portrait");
        AddCandidateCrop(sb, item.SourcePath, "target-mp.png", "target-mp");
        AddCandidateCrop(sb, item.SourcePath, "target-rage.png", "target-rage");
        AddCandidateCrop(sb, item.SourcePath, "pet-hp.png", "pet-hp");
        sb.AppendLine("</div>");
        sb.AppendLine("<div class=\"kv\">");
        sb.AppendLine($"<div>risk</div><div>{HtmlEscape(item.Risk)}</div>");
        sb.AppendLine($"<div>reason</div><div>{HtmlEscape(item.Reason)}</div>");
        sb.AppendLine($"<div>targetHp</div><div>{item.TargetHpPercent?.ToString(CultureInfo.InvariantCulture) ?? "-"}</div>");
        sb.AppendLine($"<div>playerLike</div><div>{item.TargetLooksLikePlayer?.ToString() ?? "-"}</div>");
        sb.AppendLine($"<div>ambiguous</div><div>{item.TargetProtectionAmbiguous?.ToString() ?? "-"}</div>");
        sb.AppendLine($"<div>petLike</div><div>{item.TargetLooksLikePet?.ToString() ?? "-"}</div>");
        sb.AppendLine($"<div>regions</div><div>{item.CompleteRegions}/{item.RequiredRegions}</div>");
        sb.AppendLine("</div>");
        sb.AppendLine($"<div class=\"path\">{HtmlEscape(item.SourcePath)}</div>");
        sb.AppendLine("</section>");
    }

    sb.AppendLine("</main></body></html>");
    return sb.ToString();
}

static void AddCandidateCrop(StringBuilder sb, string sourcePath, string fileName, string label)
{
    var path = Path.Combine(sourcePath, fileName);
    sb.AppendLine("<div class=\"crop\">");
    if (File.Exists(path))
        sb.AppendLine($"<a href=\"{FileUri(path)}\"><img src=\"{FileUri(path)}\" alt=\"{HtmlEscape(label)}\"></a>");
    else
        sb.AppendLine("<div style=\"height:56px;border:1px dashed #3a4a5d;border-radius:4px\"></div>");
    sb.AppendLine($"<span>{HtmlEscape(label)}</span>");
    sb.AppendLine("</div>");
}

static string FileUri(string path) => new Uri(Path.GetFullPath(path)).AbsoluteUri;

static string HtmlEscape(string text) => text
    .Replace("&", "&amp;", StringComparison.Ordinal)
    .Replace("<", "&lt;", StringComparison.Ordinal)
    .Replace(">", "&gt;", StringComparison.Ordinal)
    .Replace("\"", "&quot;", StringComparison.Ordinal);

static CombatSampleCandidateEvidence ReadCombatSampleCandidate(string dir)
{
    var pngs = Directory.EnumerateFiles(dir, "*.png")
        .Select(Path.GetFileName)
        .Where(name => !string.IsNullOrWhiteSpace(name))
        .ToHashSet(StringComparer.OrdinalIgnoreCase);
    var jsonPath = ResolveCombatSampleCandidateJsonPath(dir);
    var text = !string.IsNullOrWhiteSpace(jsonPath) && File.Exists(jsonPath)
        ? File.ReadAllText(jsonPath, Encoding.UTF8)
        : string.Empty;

    var targetLooksLikePlayer = ReadNullableBoolField(text, "TargetLooksLikePlayer");
    var targetProtectionAmbiguous = ReadNullableBoolField(text, "TargetProtectionAmbiguous");
    var targetLooksLikePet = ReadNullableBoolField(text, "TargetLooksLikePet");
    var targetIsAttackable = ReadNullableBoolField(text, "TargetIsAttackable");
    var targetHpPercent = ReadNullableIntField(text, "TargetHpPercent");
    var targetNameText = ReadNullableStringField(text, "TargetNameText") ?? string.Empty;
    var label = ReadCombatSampleLabel(dir);
    var expectedKind = ReadCombatSampleExpectedKind(dir, label);

    var required = new[]
    {
        "client.png",
        "target-name.png",
        "target-hp.png",
        "target-mp.png",
        "target-rage.png",
        "target-status.png",
        "school-marker.png",
        "target-portrait.png",
        "player-hp.png",
        "player-mp.png",
        "player-rage.png",
        "pet-hp.png"
    };
    var completeRegions = required.Count(file => pngs.Contains(file));
    var hasFullRegions = completeRegions == required.Length;
    var hasTargetEvidence = targetHpPercent is > 0 || pngs.Contains("target-name.png") || pngs.Contains("target-portrait.png");

    var recommendation = "not-recommended";
    var suggestedKind = "unknown";
    var risk = "high";
    var reason = "missing-reviewable-target-evidence";

    if (!hasFullRegions)
    {
        reason = $"incomplete-required-crops:{completeRegions}/{required.Length}";
    }
    else if (expectedKind == "player" || targetLooksLikePlayer == true || targetProtectionAmbiguous == true)
    {
        recommendation = "protect-only-review";
        suggestedKind = expectedKind == "player" ? "player" : "player-or-ambiguous";
        risk = targetProtectionAmbiguous == true ? "high" : "medium";
        reason = expectedKind == "player"
            ? "labeled-player-protect-only-not-monster-release"
            : "player-like-or-ambiguous-protect-only-not-monster-release";
    }
    else if (expectedKind == "pet" || targetLooksLikePet == true)
    {
        recommendation = "review-for-promotion";
        suggestedKind = "pet";
        risk = "medium";
        reason = expectedKind == "pet"
            ? "labeled-pet-review-before-promotion"
            : "pet-like-review-before-promotion";
    }
    else if ((expectedKind is "monster" or "boss" or "elite") && hasTargetEvidence)
    {
        recommendation = "review-for-promotion";
        suggestedKind = expectedKind;
        risk = expectedKind is "boss" or "elite" ? "medium" : "low";
        reason = $"labeled-{expectedKind}-review-before-promotion";
    }
    else if (hasTargetEvidence && targetHpPercent is > 0)
    {
        recommendation = "review-for-promotion";
        suggestedKind = "monster";
        risk = pngs.Contains("target-portrait.png") || pngs.Contains("school-marker.png") ? "medium" : "low";
        reason = "target-hp-present-not-player-review-before-promotion";
    }
    else if (expectedKind == "none" || !hasTargetEvidence)
    {
        recommendation = "review-for-promotion";
        suggestedKind = "none";
        risk = "medium";
        reason = expectedKind == "none"
            ? "labeled-none-review-before-promotion"
            : "no-target-evidence-review-before-none-promotion";
    }

    return new CombatSampleCandidateEvidence(
        Name: Path.GetFileName(dir),
        SourcePath: dir,
        ClientImagePath: Path.Combine(dir, "client.png"),
        PreviewJsonPath: jsonPath,
        Recommendation: recommendation,
        SuggestedKind: suggestedKind,
        Risk: risk,
        Reason: reason,
        CompleteRegions: completeRegions,
        RequiredRegions: required.Length,
        TargetNameText: targetNameText,
        TargetHpPercent: targetHpPercent,
        TargetLooksLikePlayer: targetLooksLikePlayer,
        TargetProtectionAmbiguous: targetProtectionAmbiguous,
        TargetLooksLikePet: targetLooksLikePet,
        TargetIsAttackable: targetIsAttackable);
}

static string ResolveCombatSampleCandidateJsonPath(string dir)
{
    var priority = new[]
    {
        "normal-hang-preview.json",
        "recognition.json",
        "metadata.json"
    };

    foreach (var fileName in priority)
    {
        var path = Path.Combine(dir, fileName);
        if (File.Exists(path))
            return path;
    }

    return string.Empty;
}

static bool? ReadNullableBoolField(string text, string name)
{
    var value = ReadJsonFieldToken(text, name);
    if (bool.TryParse(value, out var result))
        return result;
    return null;
}

static int? ReadNullableIntField(string text, string name)
{
    var value = ReadJsonFieldToken(text, name);
    if (int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var result))
        return result;
    return null;
}

static string? ReadNullableStringField(string text, string name)
{
    var token = ReadJsonFieldToken(text, name);
    if (string.IsNullOrWhiteSpace(token))
        return null;
    if (token.Length >= 2 && token[0] == '"' && token[^1] == '"')
        return token[1..^1];
    return token;
}

static string? ReadJsonFieldToken(string text, string name)
{
    if (string.IsNullOrEmpty(text))
        return null;

    var marker = $"\"{name}\"";
    var index = text.IndexOf(marker, StringComparison.Ordinal);
    if (index < 0)
        return null;

    var colon = text.IndexOf(':', index + marker.Length);
    if (colon < 0)
        return null;

    var start = colon + 1;
    while (start < text.Length && char.IsWhiteSpace(text[start]))
        start++;

    if (start >= text.Length)
        return null;

    if (text[start] == '"')
    {
        var end = text.IndexOf('"', start + 1);
        return end > start ? text[start..(end + 1)] : null;
    }

    var stop = start;
    while (stop < text.Length && text[stop] is not ',' and not '\r' and not '\n' and not '}')
        stop++;
    return text[start..stop].Trim();
}

static string? ResolveSourceRecognitionPath(string? sourceArg)
{
    if (string.IsNullOrWhiteSpace(sourceArg))
        return null;

    var path = sourceArg.Trim().Trim('"');
    if (File.Exists(path) && Path.GetFileName(path).Equals("recognition.json", StringComparison.OrdinalIgnoreCase))
        return path;

    if (Directory.Exists(path))
    {
        var recognition = Path.Combine(path, "recognition.json");
        return File.Exists(recognition) ? recognition : null;
    }

    var sibling = Path.Combine(Path.GetDirectoryName(path) ?? ".", "recognition.json");
    return File.Exists(sibling) ? sibling : null;
}

static string NormalizeCombatRegionKey(string name) => name.Replace('-', '_');

static string CombatRegionTitle(string name) => name switch
{
    "target-name" => "目标名字",
    "target-hp" => "目标血条",
    "target-mp" => "目标蓝条",
    "target-rage" => "目标怒气",
    "target-status" => "玩家条判定",
    "school-marker" => "门派竖牌",
    "target-portrait" => "目标头像",
    "player-hp" => "人物血条",
    "player-mp" => "人物蓝条",
    "player-rage" => "人物怒气",
    "pet-hp" => "宠物血条",
    _ => name
};

static IReadOnlyList<string> ReadCombatSampleRegionKeys(string metadataPath)
{
    if (!File.Exists(metadataPath))
        return Array.Empty<string>();

    try
    {
        var node = JsonNode.Parse(File.ReadAllText(metadataPath, Encoding.UTF8));
        var regions = node?["Regions"]?.AsArray();
        if (regions is null)
            return Array.Empty<string>();

        return regions
            .Select(r => r?["Key"]?.GetValue<string>())
            .Where(v => !string.IsNullOrWhiteSpace(v))
            .Select(v => v!.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }
    catch
    {
        return Array.Empty<string>();
    }
}

static IEnumerable<string> DiscoverCombatSampleDirectories(string root)
{
    if (File.Exists(Path.Combine(root, "client.png")))
    {
        yield return root;
        yield break;
    }

    foreach (var dir in Directory.EnumerateDirectories(root, "*", SearchOption.AllDirectories)
                 .Where(d => File.Exists(Path.Combine(d, "client.png")))
                 .OrderBy(d => d, StringComparer.OrdinalIgnoreCase))
    {
        yield return dir;
    }
}

static string ReadCombatSampleLabel(string sampleDir)
{
    var metadataPath = Path.Combine(sampleDir, "metadata.json");
    if (File.Exists(metadataPath))
    {
        try
        {
            var node = JsonNode.Parse(File.ReadAllText(metadataPath, Encoding.UTF8));
            var label = node?["Label"]?.GetValue<string>();
            if (!string.IsNullOrWhiteSpace(label))
                return label.Trim();
        }
        catch
        {
            // Fall through to directory name; metadata parsing is diagnostic only.
        }
    }

    return Path.GetFileName(sampleDir);
}

static string ReadCombatSampleExpectedKind(string sampleDir, string label)
{
    var metadataPath = Path.Combine(sampleDir, "metadata.json");
    if (File.Exists(metadataPath))
    {
        try
        {
            var node = JsonNode.Parse(File.ReadAllText(metadataPath, Encoding.UTF8));
            var expected = node?["ExpectedKind"]?.GetValue<string>();
            if (IsKnownCombatSampleKind(expected))
                return expected!.Trim().ToLowerInvariant();
        }
        catch
        {
            // Fall through to legacy free-text inference.
        }
    }

    return InferCombatSampleExpectedKind(label);
}

static bool IsKnownCombatSampleKind(string? value)
{
    return value?.Trim().ToLowerInvariant() is "unknown" or "player" or "pet" or "monster" or "boss" or "elite" or "none";
}

static string InferCombatSampleExpectedKind(string label)
{
    var value = label.Trim().ToLowerInvariant();
    if (string.IsNullOrWhiteSpace(value))
        return "unknown";

    if (value.Contains("无目标") || value.Contains("空目标") || value.Contains("none") || value.Contains("empty") || value.Contains("no-target"))
        return "none";

    if (value.Contains("玩家") || value.Contains("人物") || value.Contains("角色") || value.Contains("门派") || value.Contains("player") || value.Contains("role") || value.Contains("character"))
        return "player";

    if (value.Contains("宠物") || value.Contains("宝宝") || value.Contains("召唤兽") || value.Contains("bb") || value.Contains("pet"))
        return "pet";

    if (value.Contains("boss") || value.Contains("首领") || value.Contains("小头目") || value.Contains("头目") || value.Contains("elite"))
        return "boss";

    if (value.Contains("怪") || value.Contains("monster") || value.Contains("mob") || value.Contains("npc"))
        return "monster";

    return "unknown";
}

static string ResolveCombatActualKind(CombatRecognitionResult combat)
{
    if (combat.TargetLooksLikePlayer)
        return "player";
    if (combat.TargetSampleKind is "monster" or "boss" or "elite" or "pet")
        return combat.TargetSampleKind;
    if (combat.TargetProtectionAmbiguous)
        return "player-protection-risk";
    if (combat.TargetLooksLikePet)
        return "pet";
    if (combat.HasTarget)
        return "monster-or-target";
    return "none";
}

static (bool? Passed, string Reason) EvaluateCombatSample(string expected, CombatRecognitionResult combat, string actual)
{
    return expected switch
    {
        "player" when combat.TargetLooksLikePlayer => (true, "目标保护特征命中玩家"),
        "player" when combat.TargetProtectionAmbiguous => (null, "只命中门派竖牌/头像类歧义特征，需要人工复核；不再作为已确认玩家样本通过"),
        "player" => (false, "期望玩家目标，但未识别为玩家"),
        "pet" when combat.TargetLooksLikePet => (true, "目标保护特征命中宠物"),
        "pet" => (false, "期望宠物目标，但未识别为宠物"),
        "monster" when combat.HasTarget && !combat.TargetLooksLikePlayer && !combat.TargetProtectionAmbiguous && !combat.TargetLooksLikePet => (true, "识别为业务可攻击的非玩家非宠物目标"),
        "monster" => (false, "期望怪物目标，但业务会按玩家/宠物/高风险目标阻断，或未识别到目标"),
        "boss" or "elite" when combat.HasTarget && !combat.TargetLooksLikePlayer && !combat.TargetProtectionAmbiguous && !combat.TargetLooksLikePet => (true, "首领/BOSS 通过业务攻击门禁"),
        "boss" or "elite" => (false, "期望首领/BOSS 可攻击，但业务会按玩家/宠物/高风险目标阻断，或未识别到目标"),
        "none" when !combat.HasTarget => (true, "无目标状态正确"),
        "none" => (false, "期望无目标，但识别到目标"),
        _ => (null, $"标签无法推断期望类型，实际={actual}")
    };
}

static string FormatPass(bool? passed) => passed switch
{
    true => "PASS",
    false => "FAIL",
    _ => "UNCHECKED"
};

static System.Text.Json.JsonSerializerOptions JsonOptions() => new()
{
    WriteIndented = true,
    Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
};

static string CleanEvidenceText(string? text)
{
    if (string.IsNullOrEmpty(text))
        return string.Empty;

    var builder = new StringBuilder(text.Length);
    foreach (var ch in text)
    {
        builder.Append(char.IsControl(ch) ? ' ' : ch);
    }

    return builder.ToString().Trim();
}

static string? ResolveCombatImageInput(string? inputPath)
{
    if (string.IsNullOrWhiteSpace(inputPath))
        return null;

    var path = inputPath.Trim().Trim('"');
    if (Directory.Exists(path))
    {
        var client = Path.Combine(path, "client.png");
        return File.Exists(client) ? client : null;
    }

    if (!File.Exists(path))
        return null;

    if (Path.GetFileName(path).Equals("recognition.json", StringComparison.OrdinalIgnoreCase))
    {
        var client = Path.Combine(Path.GetDirectoryName(path) ?? ".", "client.png");
        return File.Exists(client) ? client : null;
    }

    return path;
}

static bool RunLiveRecognitionDiagnostics(string[] args, bool targetProtectionOnly = false)
{
    Console.WriteLine(targetProtectionOnly ? "Live target protection diagnostics" : "Live recognition diagnostics");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();
    var truthName = ReadStringOption(args, "--truth-name");
    var targetType = ReadStringOption(args, "--target-type");

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var hwnd = ResolveGameWindowHandle(args, provider, out var selectionText);
    if (hwnd == nint.Zero)
        return false;

    Console.WriteLine(selectionText);
    var window = binding.BindByHandle(hwnd);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);
    var loaded = dictionaryLoad.LoadedGlyphs;

    var capture = provider.GetRequiredService<IWindowCaptureService>();
    var client = capture.CaptureClient(window.Hwnd);
    var avatar = capture.CaptureAvatar(window.Hwnd);

    var roleIdentityService = provider.GetRequiredService<IRoleIdentityService>();
    var identityResolution = roleIdentityService.ResolveAsync(window).GetAwaiter().GetResult();
    var profiles = provider.GetRequiredService<IAppProfileService>();
    string? profileName = null;
    if (identityResolution.IsMatched
        && identityResolution.Match is not null
        && profiles.ListProfileNames().Contains(identityResolution.Match.ProfileName, StringComparer.Ordinal))
    {
        var roleLoad = profiles.LoadAll(identityResolution.Match.ProfileName);
        if (roleLoad.GlobalLoaded)
            profileName = identityResolution.Match.ProfileName;
    }
    profileName ??= TryLoadCurrentGlobalConfig(provider);
    var global = provider.GetRequiredService<IGlobalConfigService>().Current;
    var returnPoints = provider.GetRequiredService<IReturnPointService>().Current;
    var horse = provider.GetRequiredService<IHorseBanditConfigService>().Current;

    // Never borrow another role's key mapping when the current visual identity is unresolved.
    // The fallback profile is useful for read-only perception defaults only.
    var roleIdentities = identityResolution.IsMatched && identityResolution.Match is not null
        ? new[] { identityResolution.Match }
        : Array.Empty<CharacterIdentityRecord>();
    var hotkeyService = provider.GetRequiredService<IGameHotkeyProfileService>();
    GameHotkeyProfileLoadResult? hotkeyProfile = roleIdentities.Length == 1
        ? hotkeyService.BindToRole(window, roleIdentities[0].DisplayName)
        : null;
    var perception = provider.GetRequiredService<IPerceptionHub>().Read(
        window,
        global,
        new PerceptionReadOptions(IncludeTargetOpenText: true));
    var skillSlots = perception.SkillBar.VisualSlots.Select(slot =>
    {
        var mappedHotkey = string.Empty;
        if (slot.Column >= 0
            && string.Equals(slot.ActivationKind, "keyboard", StringComparison.OrdinalIgnoreCase)
            && hotkeyService.TryResolve(window.Hwnd, GameInputSemanticIds.SkillSlot(slot.Column + 1), out var binding))
        {
            mappedHotkey = binding.Hotkey;
        }

        var policy = global.AiSkills.FirstOrDefault(candidate => string.Equals(
            candidate.ExpectedVisualSkillId?.Trim(),
            slot.SkillId?.Trim(),
            StringComparison.OrdinalIgnoreCase));
        var blockers = new List<string>();
        if (slot.FrameSequence <= 0 || slot.FrameSequence != perception.FrameSequence)
            blockers.Add("stale_frame");
        if (slot.Identity != VisionSkillIdentityState.Matched)
            blockers.Add($"identity_{slot.Identity.ToString().ToLowerInvariant()}");
        if (!string.Equals(slot.IdentitySource, "icons_ingame", StringComparison.OrdinalIgnoreCase))
            blockers.Add("identity_source_untrusted");
        if (!slot.HangUsable)
            blockers.Add("hang_not_usable");
        if (!string.Equals(slot.ReleaseRule, "allowed_by_policy", StringComparison.OrdinalIgnoreCase))
            blockers.Add("release_rule_blocked");
        if (!slot.Castable)
            blockers.Add("not_castable");
        if (slot.Cooldown != VisionCooldownState.Ready)
            blockers.Add($"cooldown_{slot.Cooldown.ToString().ToLowerInvariant()}");
        if (policy is null || !policy.Enabled)
            blockers.Add("ai_policy_missing");
        if (string.Equals(slot.ActivationKind, "keyboard", StringComparison.OrdinalIgnoreCase)
            && string.IsNullOrWhiteSpace(mappedHotkey)
            && string.IsNullOrWhiteSpace(policy?.Hotkey))
        {
            blockers.Add("verified_hotkey_missing");
        }
        if (string.Equals(slot.ActivationKind, "mouse", StringComparison.OrdinalIgnoreCase)
            && (!slot.ClickX.HasValue || !slot.ClickY.HasValue))
        {
            blockers.Add("click_point_missing");
        }

        return new
        {
            slot.FrameSequence,
            slot.Index,
            slot.SlotId,
            slot.Row,
            slot.Column,
            slot.Surface,
            slot.Key,
            slot.ActivationKind,
            slot.SlotBox,
            slot.ClickX,
            slot.ClickY,
            slot.Cooldown,
            slot.SkillId,
            slot.SkillName,
            slot.Identity,
            slot.IdentitySource,
            slot.MatchScore,
            slot.MatchMargin,
            slot.HangUsable,
            slot.Castable,
            slot.PolicyClass,
            slot.ReleaseRule,
            mappedHotkey,
            configuredHotkey = policy?.Hotkey ?? string.Empty,
            policyEnabled = policy?.Enabled ?? false,
            blockers
        };
    }).ToArray();

    var combat = VisionCombatResultMapper.FromSnapshot(perception);
    var navigation = provider.GetRequiredService<INavigationRecognitionService>().Recognize(window, returnPoints.NavigationRecognition);
    var death = provider.GetRequiredService<IDeathRecognitionService>().Recognize(window, returnPoints.DeathRecognition);
    var horseRecognition = provider.GetRequiredService<IHorseBanditRecognitionService>().Recognize(window, horse.Recognition);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var artifactName = targetProtectionOnly ? "live-target-protection" : "live-recognition";
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", artifactName, $"{stamp}-{window.Pid}");
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "recognition.json");
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var avatarPath = Path.Combine(evidenceDir, "avatar.png");
    var overlayPath = Path.Combine(evidenceDir, "combat-regions-overlay.png");
    var clientSaved = SaveCapturePng(client, clientPath);
    var avatarSaved = SaveCapturePng(avatar, avatarPath);
    var fixedRegionEvidenceDir = Path.Combine(evidenceDir, "fixed-region-diagnostics");
    Directory.CreateDirectory(fixedRegionEvidenceDir);
    var fixedRegionDiagnostics = BuildCombatRegionEvidence(
        client,
        global.CombatRecognition,
        fixedRegionEvidenceDir,
        combat);
    var combatRegions = BuildVisionV2CombatRegionEvidence(client, perception, evidenceDir, combat);
    var overlaySaved = client is not null && SaveCombatRegionsOverlayPng(client, combatRegions, overlayPath);
    var targetProtection = BuildTargetProtectionEvidence(client, global.CombatRecognition, combat, fixedRegionDiagnostics);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = targetProtectionOnly
            ? "read-only-live-target-protection-no-input"
            : "read-only-live-recognition-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            opensProcessForVmRead = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            businessDecisionReady = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryFiles = dictionaryFiles.Count,
            loadedGlyphsDelta = loaded,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        profile = new
        {
            name = profileName,
            school = global.School.ToString(),
            global.SkillCooldownRecognitionEnabled,
            skillMode = global.SkillCooldownRecognitionEnabled ? "ai_visual" : "custom_timer",
            customSkills = global.Skills.Count(skill => skill.Enabled && !string.IsNullOrWhiteSpace(skill.Hotkey)),
            aiSkills = global.AiSkills.Count(skill => skill.Enabled && !string.IsNullOrWhiteSpace(skill.ExpectedVisualSkillId)),
            aiSkillIds = global.AiSkills
                .Where(skill => skill.Enabled && !string.IsNullOrWhiteSpace(skill.ExpectedVisualSkillId))
                .Select(skill => skill.ExpectedVisualSkillId)
                .ToArray(),
            identityMatches = roleIdentities.Select(identity => identity.DisplayName).ToArray(),
            identityResolution = new
            {
                status = identityResolution.Status.ToString(),
                observedName = identityResolution.Observation.SuggestedName,
                identityResolution.Observation.Quality,
                identityResolution.Reason
            },
            hotkeyProfile = hotkeyProfile is null
                ? null
                : new
                {
                    status = hotkeyProfile.Status.ToString(),
                    hotkeyProfile.RoleName,
                    hotkeyProfile.Reason,
                    dispatchableBindings = hotkeyProfile.Bindings.Count(binding => binding.IsDispatchable)
                }
        },
        capture = new
        {
            client = client is null ? null : new
            {
                client.Width,
                client.Height,
                visual = HasVisualContent(client),
                path = clientPath,
                saved = clientSaved,
                sha256 = clientSaved ? ComputeFileSha256(clientPath) : null
            },
            avatar = avatar is null ? null : new
            {
                avatar.Width,
                avatar.Height,
                visual = HasVisualContent(avatar),
                path = avatarPath,
                saved = avatarSaved,
                sha256 = avatarSaved ? ComputeFileSha256(avatarPath) : null
            }
        },
        acceptanceLabel = new
        {
            truthName,
            targetType,
            manuallyLabeled = !string.IsNullOrWhiteSpace(truthName)
                              || !string.IsNullOrWhiteSpace(targetType)
        },
        combat = new
        {
            perception.FrameSequence,
            combat.TargetNameText,
            targetNameOpenText = new
            {
                perception.TargetNameOpenText.Text,
                perception.TargetNameOpenText.Confidence,
                perception.TargetNameOpenText.Slot,
                perception.TargetNameOpenText.Source,
                perception.TargetNameOpenText.Engine,
                perception.TargetNameOpenText.Message
            },
            combat.TargetHpText,
            combat.PlayerHpText,
            combat.PlayerMpText,
            combat.PetHpText,
            combat.TargetHpPercent,
            combat.PlayerHpPercent,
            combat.PlayerMpPercent,
            combat.PetHpPercent,
            combat.HasTarget,
            combat.TargetLooksLikePlayer,
            combat.TargetProtectionAmbiguous,
            combat.TargetLooksLikePet,
            combat.TargetIsAttackable,
            combat.TargetHasSchoolMarker,
            combat.TargetHasPlayerPortrait,
            combat.TargetHasPlayerStatusBars,
            combat.TargetSampleKind,
            combat.TargetSampleLabel,
            combat.TargetSampleSource,
            combat.TargetSampleScore,
            targetProtection,
            overlay = new { path = overlayPath, saved = overlaySaved },
            regions = combatRegions,
            fixedRegionDiagnostics
        },
        skills = new
        {
            perception.FrameSequence,
            perception.SkillBar.Source,
            perception.SkillBar.Message,
            total = skillSlots.Length,
            currentFrame = skillSlots.Count(slot => slot.FrameSequence == perception.FrameSequence),
            matched = skillSlots.Count(slot => slot.Identity == VisionSkillIdentityState.Matched),
            ready = skillSlots.Count(slot => slot.Cooldown == VisionCooldownState.Ready),
            castable = skillSlots.Count(slot => slot.Castable),
            executable = skillSlots.Count(slot => slot.blockers.Count == 0),
            slots = skillSlots
        },
        navigation = new
        {
            navigation.MapNameText,
            navigation.MapNameSource,
            navigation.MapNameConfidencePercent,
            navigation.CoordinateText,
            navigation.CoordinateSource,
            navigation.CoordinateConfidencePercent,
            navigation.X,
            navigation.Y,
            navigation.HasMap,
            navigation.HasCoordinate
        },
        death = new
        {
            death.IsDead,
            death.Text,
            death.MatchedKeyword
        },
        horse = new
        {
            horseRecognition.TeamStatusText,
            horseRecognition.FollowStatusText,
            horseRecognition.DistanceText,
            horseRecognition.Distance,
            horseRecognition.IsFollowing,
            horseRecognition.IsLostFollow
        },
    };

    var jsonOptions = new System.Text.Json.JsonSerializerOptions
    {
        WriteIndented = true,
        Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, jsonOptions), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Legacy OCR (informational only): dictionaries={dictionaryFiles.Count}, loadedDelta={loaded}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Capture client={client?.Width}x{client?.Height}, avatar={avatar?.Width}x{avatar?.Height}");
    Console.WriteLine($"Profile={Blank(profileName ?? string.Empty)}, school={global.School}, skillMode={(global.SkillCooldownRecognitionEnabled ? "ai_visual" : "custom_timer")}, AI policies={global.AiSkills.Count(skill => skill.Enabled && !string.IsNullOrWhiteSpace(skill.ExpectedVisualSkillId))}");
    Console.WriteLine($"Role resolution={identityResolution.Status}, observed={Blank(identityResolution.Observation.SuggestedName)}, reason={identityResolution.Reason}");
    Console.WriteLine($"Role identity matches={roleIdentities.Length}, hotkey profile={hotkeyProfile?.Status.ToString() ?? "not_bound"}, reason={hotkeyProfile?.Reason ?? "profile_identity_not_unique"}");
    Console.WriteLine($"AI slots total/current/matched/ready/castable/executable={skillSlots.Length}/{skillSlots.Count(slot => slot.FrameSequence == perception.FrameSequence)}/{skillSlots.Count(slot => slot.Identity == VisionSkillIdentityState.Matched)}/{skillSlots.Count(slot => slot.Cooldown == VisionCooldownState.Ready)}/{skillSlots.Count(slot => slot.Castable)}/{skillSlots.Count(slot => slot.blockers.Count == 0)}");
    foreach (var slot in skillSlots.Where(slot => slot.Identity == VisionSkillIdentityState.Matched || slot.blockers.Count == 0))
    {
        Console.WriteLine($"  {slot.SlotId}: {Blank(slot.SkillName)} [{Blank(slot.SkillId)}] {slot.Cooldown}, action={Blank(slot.mappedHotkey)}, blockers={string.Join(',', slot.blockers)}");
    }
    Console.WriteLine($"Combat target='{combat.TargetNameText}', targetHp={combat.TargetHpPercent}, hp={combat.PlayerHpPercent}, mp={combat.PlayerMpPercent}, pet={combat.PetHpPercent}, player={combat.TargetLooksLikePlayer}, protectionRisk={combat.TargetProtectionAmbiguous}");
    Console.WriteLine($"Target attackable={combat.TargetIsAttackable}, sample={Blank(combat.TargetSampleKind)}, sampleScore={combat.TargetSampleScore:0.000}, structure={TargetStructureText(combat)}");
    Console.WriteLine($"Target protection decision={targetProtection.Decision}, protected={targetProtection.ProtectedByPlayerGuard}, statusBars={targetProtection.StatusBars.Matched}, schoolMarker={targetProtection.SchoolMarker.Matched}, portraitAux={targetProtection.Portrait.Visual}");
    Console.WriteLine($"Combat regions saved={combatRegions.Count(r => r.Saved)}/{combatRegions.Length}, zoom={combatRegions.Count(r => r.ZoomSaved)}/{combatRegions.Length}, overlay={overlaySaved}");
    Console.WriteLine($"Navigation map='{navigation.MapNameText}' source={navigation.MapNameSource} confidence={navigation.MapNameConfidencePercent}%, coord='{navigation.CoordinateText}' source={navigation.CoordinateSource} confidence={navigation.CoordinateConfidencePercent}%, parsed={navigation.X},{navigation.Y}");
    Console.WriteLine($"Death dead={death.IsDead}, text='{death.Text}'");
    Console.WriteLine($"Horse follow={horseRecognition.IsFollowing}, lost={horseRecognition.IsLostFollow}, distance={horseRecognition.Distance}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && client is { Width: > 0, Height: > 0 }
             && avatar is { Width: > 0, Height: > 0 }
             && HasVisualContent(client)
             && HasVisualContent(avatar)
             && clientSaved
             && avatarSaved
             && overlaySaved
             && combatRegions.All(r => r.Saved && r.ZoomSaved)
             && targetProtection.EvidenceComplete
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLiveRecoveryPreviewDiagnostics()
{
    Console.WriteLine("Live recovery preview diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var profileName = TryLoadCurrentGlobalConfig(provider);
    var global = provider.GetRequiredService<IGlobalConfigService>().Current;
    var frames = provider.GetRequiredService<ILatestFrameService>();
    var hub = provider.GetRequiredService<IPerceptionHub>();
    var temporalObservations = new List<object>();
    RuntimePerceptionSnapshot snapshot = default!;
    for (var sample = 1; sample <= 3; sample++)
    {
        snapshot = hub.Read(
            window,
            global,
            new PerceptionReadOptions(IncludeTargetOpenText: false));
        temporalObservations.Add(new
        {
            sample,
            snapshot.FrameSequence,
            snapshot.SelfBars.PetState,
            snapshot.SelfBars.PetHpPercent,
            snapshot.SelfBars.PetPanelGeometrySource,
            snapshot.SelfBars.Message
        });
        if (sample < 3)
            Thread.Sleep(375);
    }
    var capture = frames.GetCached(window.Hwnd, snapshot.FrameSequence);
    var combat = VisionCombatResultMapper.FromSnapshot(snapshot);
    var actions = BuildRecoveryPreviewActions(global, combat, window);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-recovery-preview", $"{stamp}-{window.Pid}");
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "recovery-preview.json");
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "combat-regions-overlay.png");
    var recoveryOverlayPath = Path.Combine(evidenceDir, "recovery-actions-overlay.png");

    var clientSaved = SaveCapturePng(capture, clientPath);
    var combatRegions = BuildVisionV2CombatRegionEvidence(capture, snapshot, evidenceDir, combat);
    var overlaySaved = capture is not null && SaveCombatRegionsOverlayPng(capture, combatRegions, overlayPath);
    var recoveryOverlaySaved = capture is not null && SaveRecoveryActionsOverlayPng(capture, actions, recoveryOverlayPath);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-recovery-preview-no-input",
        safety = new
        {
            sendsInput = false,
            sendKeyCount = 0,
            clicksMouse = false,
            clickCount = 0,
            writesText = false,
            textInputCount = 0,
            opensProcessForVmRead = false,
            readsGameStateMemory = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false
        },
        profile = new
        {
            name = profileName,
            source = string.IsNullOrWhiteSpace(profileName) ? "default-global-config" : "current-profile-global-config"
        },
        window = new
        {
            hwnd = $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            window.ProcessPath,
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        recognition = new
        {
            pipeline = "PerceptionHub/VisionV2SlotService",
            snapshot.FrameSequence,
            captureFrameSequence = capture?.Sequence,
            frameSequenceMatched = capture is not null && capture.Sequence == snapshot.FrameSequence,
            snapshot.SelfBars.Source,
            snapshot.SelfBars.Message,
            snapshot.SelfBars.PlayerConfidence,
            snapshot.SelfBars.PetState,
            snapshot.SelfBars.PetConfidence,
            temporalObservations,
            combat.TargetNameText,
            combat.TargetHpText,
            combat.PlayerHpText,
            combat.PlayerMpText,
            combat.PetHpText,
            combat.TargetHpPercent,
            combat.PlayerHpPercent,
            combat.PlayerMpPercent,
            combat.PetHpPercent,
            combat.HasTarget,
            combat.TargetLooksLikePlayer,
            combat.TargetLooksLikePet,
            combat.TargetIsAttackable,
            geometry = new
            {
                playerPanel = snapshot.SelfBars.PlayerPanelBox,
                playerPanelSource = snapshot.SelfBars.PlayerPanelGeometrySource,
                playerHpRelative = snapshot.SelfBars.PlayerHpRelativeBox,
                playerHpSource = snapshot.SelfBars.PlayerHpSourceBox,
                playerMpRelative = snapshot.SelfBars.PlayerMpRelativeBox,
                playerMpSource = snapshot.SelfBars.PlayerMpSourceBox,
                petPanel = snapshot.SelfBars.PetPanelBox,
                petPanelSource = snapshot.SelfBars.PetPanelGeometrySource,
                petHpRelative = snapshot.SelfBars.PetHpRelativeBox,
                petHpSource = snapshot.SelfBars.PetHpSourceBox
            },
            degradations = snapshot.Degradations.Select(item => new { item.Code, item.Message }).ToArray(),
            client = capture is null ? null : new { capture.Width, capture.Height, visual = HasVisualContent(capture), path = clientPath, saved = clientSaved },
            overlay = new { path = overlayPath, saved = overlaySaved },
            recoveryOverlay = new
            {
                path = recoveryOverlayPath,
                saved = recoveryOverlaySaved,
                markers = actions
                    .Where(a => a.ClientClickX is not null && a.ClientClickY is not null)
                    .Select(a => new
                    {
                        a.Key,
                        a.Label,
                        x = a.ClientClickX,
                        y = a.ClientClickY,
                        bottomOffset = a.ClientClickBottomOffset,
                        a.ClientClickClientSize
                    })
                    .ToArray()
            },
            regions = combatRegions
        },
        effectiveConfig = new
        {
            global.HpThresholdPct,
            global.MpThresholdPct,
            global.PetFoodThresholdPct,
            global.BloodManaThresholdPct,
            global.SymbiosisHealThresholdPct,
            pillSharedCooldownMs = ResolvePreviewPillCooldownMs(global),
            petFoodCooldownMs = Math.Max(10000, global.PetFoodCooldownMs),
            bloodManaCooldownMs = Math.Max(30000, global.BloodManaCooldownMs),
            symbiosisHealCooldownMs = Math.Max(30000, global.SymbiosisHealCooldownMs),
            petDeployCooldownMs = Math.Max(3000, global.PetDeployCooldownMs),
            healHotkey = global.HealHotkey,
            manaHotkey = global.ManaHotkey,
            bloodManaMode = global.BloodManaActivationMode.ToString(),
            bloodManaHotkey = EffectivePreviewBloodManaHotkey(global),
            bloodManaClick = ResolvePreviewPetSkillClickPoint("血迹回蓝", global.BloodManaClickX, global.BloodManaClickBottomOffset, window),
            symbiosisMode = global.SymbiosisHealActivationMode.ToString(),
            symbiosisHotkey = global.SymbiosisHealHotkey,
            symbiosisClick = ResolvePreviewPetSkillClickPoint("共生回血", global.SymbiosisHealClickX, global.SymbiosisHealClickBottomOffset, window),
            petFoodHotkey = EffectivePreviewPetFoodHotkey(global),
            petDeployMode = global.PetDeployActivationMode.ToString(),
            petDeployHotkey = global.PetDeployHotkey,
            petDeployClick = global.PetDeployActivationMode == PetSkillActivationMode.ClientClick && global.PetDeployClickX > 0 && global.PetDeployClickBottomOffset > 0
                ? ResolvePreviewPetSkillClickPoint("宠物出战", global.PetDeployClickX, global.PetDeployClickBottomOffset, window)
                : null
        },
        actions
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<default>" : profileName)}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Perception frame={snapshot.FrameSequence}, capture frame={capture?.Sequence}, matched={capture is not null && capture.Sequence == snapshot.FrameSequence}");
    Console.WriteLine($"Recognition target='{combat.TargetNameText}', targetHp={combat.TargetHpPercent}, hp={combat.PlayerHpPercent}, mp={combat.PlayerMpPercent}, pet={combat.PetHpPercent}");
    foreach (var action in actions)
        Console.WriteLine($"{action.Label}: {action.Decision} | {action.Reason}");
    Console.WriteLine($"RecoveryActionOverlay={recoveryOverlayPath}, saved={recoveryOverlaySaved}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && capture is { Width: > 0, Height: > 0 }
             && capture.Sequence == snapshot.FrameSequence
             && HasVisualContent(capture)
             && clientSaved
             && overlaySaved
             && recoveryOverlaySaved
             && combatRegions.All(r => r.IsEmpty || (r.Saved && r.ZoomSaved))
             && actions.Count > 0
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunLivePetDeployCalibrationDiagnostics(string[] args)
{
    Console.WriteLine("Live pet deploy calibration diagnostics");

    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();

    if (game is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var window = binding.BindByHandle(game.MainWindowHandle);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var capture = provider.GetRequiredService<IWindowCaptureService>().CaptureClient(window.Hwnd);
    if (capture is null)
    {
        Console.Error.WriteLine("FAIL: 客户区截图失败。");
        return false;
    }

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var resolvedProfile = appProfiles.ResolveProfileForWindow(window);
    var profileName = resolvedProfile
                      ?? appProfiles.CurrentProfileName
                      ?? appProfiles.ListProfileNames().FirstOrDefault()
                      ?? "方案-0621-0916";

    var bandHeight = ReadClampedIntOption(args, "--height", 280, 80, Math.Max(80, Math.Min(capture.Height, 700)));
    bandHeight = Math.Min(bandHeight, capture.Height);
    var step = ReadClampedIntOption(args, "--step", 40, 20, 120);
    var bandY = Math.Max(0, capture.Height - bandHeight);
    var band = CropCaptureRect(capture, 0, bandY, capture.Width, bandHeight);

    PetDeployCalibrationPoint? explicitCandidate = null;
    var candidateText = ReadStringOption(args, "--candidate");
    if (!string.IsNullOrWhiteSpace(candidateText))
    {
        if (!TryParseClientBottomClick(candidateText, out var candidateX, out var candidateBottom))
        {
            Console.Error.WriteLine($"FAIL: --candidate 格式无效：{candidateText}，应为 x,bottom。");
            return false;
        }

        explicitCandidate = BuildPetDeployPoint("explicit", candidateX, candidateBottom, capture.Width, capture.Height);
    }

    var detectedSlots = band is null
        ? new List<PetDeployCalibrationPoint>()
        : BuildPetDeploySlotCandidates(band, bandY, capture.Width, capture.Height, maxCandidates: 36);
    var suggestions = detectedSlots
        .Concat(BuildPetDeployCalibrationSuggestions(capture.Width, capture.Height))
        .DistinctBy(p => $"{p.X / 8}:{p.Bottom / 8}")
        .ToList();
    if (explicitCandidate is not null)
        suggestions.Insert(0, explicitCandidate);
    var overlayPoints = suggestions.Take(8).ToList();

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-pet-deploy-calibration", $"{stamp}-{window.Pid}");
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "pet-deploy-calibration.json");
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var bottomPath = Path.Combine(evidenceDir, "bottom-band.png");
    var overlayPath = Path.Combine(evidenceDir, "pet-deploy-grid-overlay.png");
    var bottomOverlayPath = Path.Combine(evidenceDir, "bottom-band-grid-overlay.png");
    var reportPath = Path.Combine(evidenceDir, "pet-deploy-candidates.md");

    var clientSaved = SaveCapturePng(capture, clientPath);
    var bottomSaved = SaveCapturePng(band, bottomPath);
    var overlaySaved = SavePetDeployCalibrationOverlayPng(capture, bandY, bandHeight, step, overlayPoints, overlayPath);
    var bottomOverlaySaved = band is not null && SavePetDeployBottomBandOverlayPng(band, bandY, step, overlayPoints, bottomOverlayPath);

    var profileArg = QuotePowerShellArg(profileName);
    var suggestionCommands = suggestions
        .Take(8)
        .Select((p, index) => new
        {
            Rank = index + 1,
            p.Name,
            p.X,
            p.Y,
            p.Bottom,
            p.InsideClient,
            applyCommand = $"& 'C:\\Program Files\\dotnet\\dotnet.exe' run --no-build --project '.\\tools\\TlbbAgent.Diagnostics\\TlbbAgent.Diagnostics.csproj' -- pet-deploy-candidate-apply --latest --rank {index + 1} --profile {profileArg} --commit",
            coordinateCommand = $"& 'C:\\Program Files\\dotnet\\dotnet.exe' run --no-build --project '.\\tools\\TlbbAgent.Diagnostics\\TlbbAgent.Diagnostics.csproj' -- profile-recovery-bootstrap --profile {profileArg} --commit --pet-deploy-click {p.X},{p.Bottom}"
        })
        .ToArray();

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-pet-deploy-click-calibration-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesProfile = false,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false
        },
        window = new
        {
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            window.ProcessPath,
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed
        },
        profile = new
        {
            name = profileName,
            resolvedProfile,
            source = resolvedProfile is not null ? "window-map" : appProfiles.CurrentProfileName is not null ? "current-profile" : "first-or-fallback"
        },
        grid = new
        {
            bandTopY = bandY,
            bandHeight,
            step,
            detectedSlotCount = detectedSlots.Count,
            coordinateMode = "client x + bottom offset",
            instruction = "在 overlay 里确认宠物出战按钮中心点后，用 x,bottom 写入 profile-recovery-bootstrap。"
        },
        capture = new
        {
            client = new { capture.Width, capture.Height, path = clientPath, saved = clientSaved, visual = HasVisualContent(capture) },
            bottomBand = band is null ? null : new { band.Width, band.Height, path = bottomPath, saved = bottomSaved, visual = HasVisualContent(band) },
            overlay = new { path = overlayPath, saved = overlaySaved },
            bottomOverlay = new { path = bottomOverlayPath, saved = bottomOverlaySaved }
        },
        explicitCandidate,
        overlayPointCount = overlayPoints.Count,
        detectedSlots = detectedSlots
            .Select(p => new { p.Name, p.X, p.Y, p.Bottom, p.Score, p.Width, p.Height, p.InsideClient })
            .ToArray(),
        suggestions = suggestionCommands
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));
    var report = new StringBuilder();
    report.AppendLine("# 宠物出战点击点候选");
    report.AppendLine();
    report.AppendLine($"- 生成时间：{DateTimeOffset.Now:yyyy-MM-dd HH:mm:ss zzz}");
    report.AppendLine($"- 绑定窗口：PID {window.Pid}，{window.ClientSizeText}，{window.ProcessPath}");
    report.AppendLine($"- 当前方案：{profileName}");
    report.AppendLine($"- 完整截图：`{clientPath}`");
    report.AppendLine($"- 底部区域：`{bottomPath}`");
    report.AppendLine($"- 底部候选图：`{bottomOverlayPath}`");
    report.AppendLine($"- JSON 证据：`{evidencePath}`");
    report.AppendLine();
    report.AppendLine("## 使用方式");
    report.AppendLine();
    report.AppendLine("1. 打开底部候选图，确认哪个候选点位于“宠物出战 / 当前宠物出战”按钮中心。");
    report.AppendLine("2. 复制对应候选点的写入命令执行。");
    report.AppendLine("3. 写入后运行 `profile-health` 或 P0 审计确认“宠物出战”警告消失。");
    report.AppendLine();
    report.AppendLine("## 前 8 个候选点");
    report.AppendLine();
    report.AppendLine("| 图上编号 | 候选名 | X | bottom | Y | 推荐写入命令 | 坐标写入命令 |");
    report.AppendLine("|---:|---|---:|---:|---:|---|---|");
    foreach (var item in suggestionCommands.Take(8))
    {
        report.AppendLine($"| `{item.Rank}` | `{item.Name}` | {item.X} | {item.Bottom} | {item.Y} | `{item.applyCommand}` | `{item.coordinateCommand}` |");
    }
    File.WriteAllText(reportPath, report.ToString(), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={profileName}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Client={clientPath}, saved={clientSaved}");
    Console.WriteLine($"BottomBand={bottomPath}, saved={bottomSaved}");
    Console.WriteLine($"Overlay={overlayPath}, saved={overlaySaved}");
    Console.WriteLine($"BottomOverlay={bottomOverlayPath}, saved={bottomOverlaySaved}");
    foreach (var item in suggestionCommands.Take(8))
        Console.WriteLine($"POINT {item.Rank} ({item.Name}): x={item.X}, bottom={item.Bottom}, y={item.Y}, inside={item.InsideClient}");
    Console.WriteLine($"DetectedSlots={detectedSlots.Count}");
    Console.WriteLine($"Evidence={evidencePath}");
    Console.WriteLine($"Report={reportPath}");

    var ok = window.Bitness == ClientBitness.X86
             && window.IsAutomationAllowed
             && HasVisualContent(capture)
             && clientSaved
             && bottomSaved
             && overlaySaved
             && bottomOverlaySaved
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && File.Exists(reportPath)
             && new FileInfo(reportPath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunPetDeployCandidateApplyDiagnostics(string[] args)
{
    Console.WriteLine("Pet deploy candidate apply diagnostics");

    var rankText = ReadOption(args, "--rank") ?? ReadOption(args, "--candidate") ?? ReadOption(args, "-r");
    if (!TryParseCandidateRank(rankText, out var rank))
    {
        Console.Error.WriteLine("FAIL: 请指定候选编号，例如 --rank 7 或 --rank p07。");
        return false;
    }

    var evidencePath = ReadOption(args, "--evidence");
    if (string.IsNullOrWhiteSpace(evidencePath) || args.Any(a => a.Equals("--latest", StringComparison.OrdinalIgnoreCase)))
        evidencePath = FindLatestPetDeployCalibrationEvidenceRaw();

    if (string.IsNullOrWhiteSpace(evidencePath) || !File.Exists(evidencePath))
    {
        Console.Error.WriteLine("FAIL: 找不到宠物出战校准证据。先运行 live-pet-deploy-calibration。");
        return false;
    }

    JsonNode? root;
    try
    {
        root = JsonNode.Parse(File.ReadAllText(evidencePath, Encoding.UTF8));
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"FAIL: 校准 JSON 读取失败：{ex.Message}");
        return false;
    }

    var suggestions = root?["suggestions"]?.AsArray();
    if (suggestions is null || suggestions.Count == 0)
    {
        Console.Error.WriteLine("FAIL: 校准 JSON 中没有 suggestions 候选点。");
        return false;
    }

    if (rank < 1 || rank > suggestions.Count)
    {
        Console.Error.WriteLine($"FAIL: 候选编号超出范围：{rank}，可用范围 1..{suggestions.Count}。");
        return false;
    }

    var node = suggestions[rank - 1];
    if (node is null
        || !TryGetJsonInt(node, "X", out var x)
        || !TryGetJsonInt(node, "Bottom", out var bottom))
    {
        Console.Error.WriteLine($"FAIL: 候选 {rank} 缺少 X/Bottom 字段。");
        return false;
    }

    var name = JsonStringValue(node["Name"], $"p{rank:00}");
    var y = TryGetJsonInt(node, "Y", out var parsedY) ? parsedY : 0;
    var insideClient = JsonBoolValue(node["InsideClient"]) ?? true;
    if (!insideClient)
    {
        Console.Error.WriteLine($"FAIL: 候选 {name} 不在客户区内，拒绝写入。");
        return false;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var init = provider.GetRequiredService<IAppInitService>();
    init.Initialize();

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var global = provider.GetRequiredService<IGlobalConfigService>();
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var evidenceProfile = JsonStringValue(root?["profile"]?["name"], "");
    var lastProfile = appProfiles.CurrentProfileName;
    var liveWindow = TryBindFirstGameWindow(provider);
    var resolvedProfile = liveWindow is null ? null : appProfiles.ResolveProfileForWindow(liveWindow);
    var availableProfiles = appProfiles.ListProfileNames().ToArray();
    var profileName = ResolveHealthProfileName(
        requestedProfile ?? evidenceProfile,
        resolvedProfile,
        lastProfile,
        availableProfiles,
        out var profileSource);

    var errors = new List<string>();
    var warnings = new List<string>();
    var commit = HasFlag(args, "--commit");
    var force = HasFlag(args, "--force");
    var loaded = false;

    if (string.IsNullOrWhiteSpace(profileName))
    {
        errors.Add("没有可用用户方案。");
    }
    else
    {
        var load = appProfiles.LoadAll(profileName);
        loaded = load.GlobalLoaded;
        if (!loaded)
            errors.Add($"当前方案无法加载：{profileName}");
    }

    var cfg = global.Current;
    var before = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
        ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
        : $"Hotkey/{cfg.PetDeployHotkey}";
    var after = $"ClientClick/{x},bottom-{bottom}";
    var wouldChange = force
                      || cfg.PetDeployActivationMode != PetSkillActivationMode.ClientClick
                      || cfg.PetDeployClickX != x
                      || cfg.PetDeployClickBottomOffset != bottom
                      || !string.IsNullOrWhiteSpace(cfg.PetDeployHotkey);

    if (!commit)
        warnings.Add("预览模式：未写入方案；确认后追加 --commit 才会保存。");

    if (commit && errors.Count == 0 && wouldChange && !string.IsNullOrWhiteSpace(profileName))
    {
        cfg.PetDeployActivationMode = PetSkillActivationMode.ClientClick;
        cfg.PetDeployClickX = x;
        cfg.PetDeployClickBottomOffset = bottom;
        cfg.PetDeployHotkey = "";
        global.Save(profileName);
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "pet-deploy-candidate-apply", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var applyEvidencePath = Path.Combine(evidenceDir, "pet-deploy-candidate-apply.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "pet-deploy-candidate-apply-no-input-no-click",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesProfile = commit && errors.Count == 0,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false
        },
        sourceEvidence = evidencePath,
        rank,
        candidate = new { name, x, bottom, y, insideClient },
        profile = new { name = profileName, source = profileSource, requestedProfile, evidenceProfile, lastProfile, loaded },
        change = new { before, after, wouldChange, committed = commit && errors.Count == 0 && wouldChange },
        warnings,
        errors
    };
    File.WriteAllText(applyEvidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"EvidenceSource={evidencePath}");
    Console.WriteLine($"Candidate={name}, rank={rank}, x={x}, bottom={bottom}, y={y}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<none>" : profileName)}, source={profileSource}, loaded={loaded}, commit={commit}, force={force}");
    Console.WriteLine($"Before={before}");
    Console.WriteLine($"After={after}");
    Console.WriteLine($"WouldChange={wouldChange}");
    foreach (var warning in warnings)
        Console.WriteLine($"WARN: {warning}");
    foreach (var error in errors)
        Console.Error.WriteLine($"ERROR: {error}");
    Console.WriteLine($"Evidence={applyEvidencePath}");

    var ok = errors.Count == 0 && File.Exists(applyEvidencePath) && new FileInfo(applyEvidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool TryParseCandidateRank(string? value, out int rank)
{
    rank = 0;
    if (string.IsNullOrWhiteSpace(value))
        return false;

    var text = value.Trim();
    if (text.StartsWith("p", StringComparison.OrdinalIgnoreCase))
        text = text[1..];

    return int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out rank)
           && rank > 0;
}

static bool TryGetJsonInt(JsonNode node, string name, out int value)
{
    value = 0;
    return node is JsonObject obj
           && obj.TryGetPropertyValue(name, out var child)
           && child is not null
           && int.TryParse(child.ToString(), NumberStyles.Integer, CultureInfo.InvariantCulture, out value);
}

static string JsonStringValue(JsonNode? node, string fallback) =>
    node is null ? fallback : node.ToString();

static bool? JsonBoolValue(JsonNode? node)
{
    if (node is null)
        return null;
    return bool.TryParse(node.ToString(), out var value) ? value : null;
}

static string? FindLatestPetDeployCalibrationEvidenceRaw()
{
    var root = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-pet-deploy-calibration");
    if (!Directory.Exists(root))
        return null;

    return Directory.GetFiles(root, "pet-deploy-calibration.json", SearchOption.AllDirectories)
        .Select(path => new FileInfo(path))
        .OrderByDescending(file => file.LastWriteTimeUtc)
        .FirstOrDefault()
        ?.FullName;
}

static async Task<bool> RunLiveNormalHangPreviewDiagnostics(string[] args)
{
    Console.WriteLine("Live normal-hang preview diagnostics");

    var durationMs = ReadClampedIntOption(args, "--duration-ms", 800, 200, 60000);
    var requestedProfile = ReadStringOption(args, "--profile");
    var lockNavigation = HasFlag(args, "--lock-navigation");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var hwnd = ResolveGameWindowHandle(args, provider, out var selectionText);
    if (hwnd == nint.Zero)
        return false;

    Console.WriteLine(selectionText);
    var window = binding.BindByHandle(hwnd);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: Game.exe 绑定失败。");
        return false;
    }

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, dictionaryFiles);

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var globalService = provider.GetRequiredService<IGlobalConfigService>();
    AppProfileLoadResult? profileLoad = null;
    string? profileName;
    if (!string.IsNullOrWhiteSpace(requestedProfile))
    {
        profileName = requestedProfile;
        profileLoad = appProfiles.LoadAll(profileName);
        if (!profileLoad.GlobalLoaded)
            Console.WriteLine($"WARN: 指定方案未找到或加载失败，将使用当前内存配置：{profileName}");
    }
    else
    {
        profileName = appProfiles.CurrentProfileName;
        if (string.IsNullOrWhiteSpace(profileName))
            profileName = appProfiles.ListProfileNames().FirstOrDefault();

        if (!string.IsNullOrWhiteSpace(profileName))
            profileLoad = appProfiles.LoadAll(profileName);
    }

    var global = globalService.Current;
    var returnPointConfig = provider.GetRequiredService<IReturnPointService>().Current;
    var capture = provider.GetRequiredService<IWindowCaptureService>().CaptureClient(window.Hwnd);
    var recognition = provider.GetRequiredService<ICombatRecognitionService>();
    var combatBefore = recognition.Recognize(window, global.CombatRecognition);
    var recoveryActions = BuildRecoveryPreviewActions(global, combatBefore, window);

    var previewLog = new RuntimeLogService();
    var input = new CountingInputService { DefaultDispatchMode = global.InputDispatchMode };
    var sceneState = provider.GetRequiredService<ISceneStateService>();
    NavigationRecognitionResult? lockedNavigation = null;
    if (lockNavigation)
        lockedNavigation = sceneState.Recognize(window, returnPointConfig.NavigationRecognition);

    var returnPointRuntime = new ReturnPointRuntimeService(
        provider.GetRequiredService<IReturnPointService>(),
        lockedNavigation is null ? sceneState : new StaticSceneStateService(lockedNavigation),
        provider.GetRequiredService<IDeathRecognitionService>(),
        new ReturnNavigationService(input, previewLog),
        previewLog);
    var runtimeSnapshotService = provider.GetService<IRuntimeSnapshotService>();
    var runtimeSnapshotBefore = runtimeSnapshotService?.Read(window, RuntimeStateProviderKind.ScreenshotOcr);
    var previewBackendSelector = CreateCombatBackendSelector(previewLog, input, recognition, runtimeSnapshotService);
    var previewBackend = previewBackendSelector.Resolve(window, global, out var previewBackendStatus);
    var backendBefore = previewBackend.Read(window, global);
    var controller = new NormalHangController(
        previewLog,
        globalService,
        previewBackendSelector,
        returnPointRuntime,
        new StateMachineEngine(previewLog));

    controller.Attach(window);
    controller.Start();
    await Task.Delay(durationMs);
    var stateBeforeStop = controller.CurrentStateName;
    var runStateBeforeStop = controller.RunState;
    controller.Stop();

    var combatAfter = recognition.Recognize(window, global.CombatRecognition);
    var hotkeys = input.SentHotkeys.ToArray();
    var hotkeyCounts = hotkeys
        .GroupBy(h => h, StringComparer.OrdinalIgnoreCase)
        .OrderBy(g => g.Key, StringComparer.OrdinalIgnoreCase)
        .Select(g => new { hotkey = g.Key, count = g.Count() })
        .ToArray();
    var hotkeyCountText = hotkeyCounts.Length == 0
        ? "-"
        : string.Join(", ", hotkeyCounts.Select(c => $"{c.hotkey}={c.count}"));
    var clicks = input.Clicks.Select(c => new { x = c.X, y = c.Y }).ToArray();
    var logs = previewLog.Entries
        .Select(e => new
        {
            time = e.Time.ToString("HH:mm:ss.fff"),
            level = e.Level.ToString(),
            e.Module,
            e.Window,
            e.Message
        })
        .ToArray();

    var attackHotkey = global.AttackHotkey?.Trim() ?? string.Empty;
    var acquireHotkey = global.Targeting.AcquireHotkey?.Trim() ?? string.Empty;
    var enabledCombatSkillHotkeys = global.Skills
        .Where(s => s.Enabled && s.Kind != SkillKind.Buff && !string.IsNullOrWhiteSpace(s.Hotkey))
        .Select(s => s.Hotkey.Trim())
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();
    var enabledBuffHotkeys = global.Skills
        .Where(s => s.Enabled && s.Kind == SkillKind.Buff && !string.IsNullOrWhiteSpace(s.Hotkey))
        .Select(s => s.Hotkey.Trim())
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();
    var enabledSkillHotkeys = global.Skills
        .Where(s => s.Enabled && !string.IsNullOrWhiteSpace(s.Hotkey))
        .Select(s => s.Hotkey.Trim())
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();
    var recoveryHotkeys = new[]
        {
            global.HealHotkey,
            global.ManaHotkey,
            global.PetFoodHotkey,
            global.PetDeployHotkey,
            global.BloodManaHotkey,
            global.SymbiosisHealHotkey
        }
        .Where(h => !string.IsNullOrWhiteSpace(h))
        .Select(h => h.Trim())
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();
    var returnHotkeys = new[]
        {
            returnPointConfig.ReturnNavigation.Hotkey,
            returnPointConfig.EarthSpiritNavigation.Hotkey,
            returnPointConfig.DeathReturnNavigation.Hotkey,
            returnPointConfig.StuckRecoveryNavigation.Hotkey
        }
        .Where(h => !string.IsNullOrWhiteSpace(h))
        .Select(h => h.Trim())
        .Distinct(StringComparer.OrdinalIgnoreCase)
        .ToArray();

    var wouldAcquire = !string.IsNullOrWhiteSpace(acquireHotkey)
                       && hotkeys.Any(h => string.Equals(h, acquireHotkey, StringComparison.OrdinalIgnoreCase));
    var wouldNormalAttack = !string.IsNullOrWhiteSpace(attackHotkey)
                            && hotkeys.Any(h => string.Equals(h, attackHotkey, StringComparison.OrdinalIgnoreCase));
    var wouldUseCombatSkill = hotkeys.Any(h => enabledCombatSkillHotkeys.Contains(h, StringComparer.OrdinalIgnoreCase));
    var wouldUseBuff = hotkeys.Any(h => enabledBuffHotkeys.Contains(h, StringComparer.OrdinalIgnoreCase));
    var wouldUseSkill = hotkeys.Any(h => enabledSkillHotkeys.Contains(h, StringComparer.OrdinalIgnoreCase));
    var wouldUseRecoveryHotkey = hotkeys.Any(h => recoveryHotkeys.Contains(h, StringComparer.OrdinalIgnoreCase));
    var wouldUseReturnHotkey = hotkeys.Any(h => returnHotkeys.Contains(h, StringComparer.OrdinalIgnoreCase));
    var wouldUseRecoveryClick = clicks.Length > 0;
    var wouldAttack = wouldNormalAttack || wouldUseCombatSkill;
    var coarseProtectedTargetWithAttack = (combatBefore.TargetLooksLikePlayer || combatBefore.TargetProtectionAmbiguous || combatBefore.TargetLooksLikePet)
                                           && wouldAttack;
    var protectedTargetWouldBeAttacked = HasProtectedTargetAttackConflict(previewLog.Entries);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "live-normal-hang-preview", $"{stamp}-{window.Pid}");
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "normal-hang-preview.json");
    var clientPath = Path.Combine(evidenceDir, "client.png");
    var overlayPath = Path.Combine(evidenceDir, "combat-regions-overlay.png");
    var recoveryOverlayPath = Path.Combine(evidenceDir, "recovery-actions-overlay.png");
    var clientSaved = SaveCapturePng(capture, clientPath);
    var combatRegions = BuildCombatRegionEvidence(capture, global.CombatRecognition, evidenceDir, combatBefore);
    var overlaySaved = capture is not null && SaveCombatRegionsOverlayPng(capture, combatRegions, overlayPath);
    var recoveryOverlaySaved = capture is not null && SaveRecoveryActionsOverlayPng(capture, recoveryActions, recoveryOverlayPath);

    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "read-only-normal-hang-preview-no-real-input",
        durationMs,
        safety = new
        {
            sendsInputToGame = false,
            inputService = nameof(CountingInputService),
            plannedSendKeyCount = input.SendKeyCount,
            plannedClickCount = input.ClickCount,
            plannedTextCount = input.SendTextCount,
            writesMemory = false,
            injectsDll = false,
            installsHook = false,
            patchesClient = false,
            modifiesPackets = false,
            readsGameStateMemory = false
        },
        profile = new
        {
            name = profileName,
            source = string.IsNullOrWhiteSpace(profileName) ? "default-global-config" : "loaded-app-profile",
            profileLoad = profileLoad is null
                ? null
                : new
                {
                    profileLoad.GlobalLoaded,
                    loadedModules = profileLoad.LoadedModules,
                    missingModules = profileLoad.MissingModules
                }
        },
        window = new
        {
            hwnd = $"0x{window.Hwnd.ToInt64():X}",
            window.Pid,
            window.Title,
            bitness = window.Bitness.ToString(),
            window.ProcessPath,
            clientSize = window.ClientSizeText,
            window.IsAutomationAllowed,
            window.IsResolutionCompatibilityMode
        },
        runtimeData = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs,
            ocr.LoadedGlyphCount,
            ocr.RenderableGlyphCount
        },
        config = new
        {
            navigationMode = lockedNavigation is null ? "live-per-loop" : "locked-live-snapshot",
            lockedNavigation = lockedNavigation is null
                ? null
                : new
                {
                    lockedNavigation.MapNameText,
                    lockedNavigation.MapNameSource,
                    lockedNavigation.MapNameConfidencePercent,
                    lockedNavigation.CoordinateText,
                    lockedNavigation.CoordinateSource,
                    lockedNavigation.CoordinateConfidencePercent,
                    lockedNavigation.X,
                    lockedNavigation.Y,
                    lockedNavigation.HasMap,
                    lockedNavigation.HasCoordinate
                },
            inputDispatchMode = global.InputDispatchMode.ToString(),
            combatBackendPreference = global.CombatBackendPreference.ToString(),
            attackHotkey,
            attackIntervalMs = global.AttackIntervalMs,
            acquireHotkey,
            targetSwitchMode = global.Targeting.SwitchMode.ToString(),
            targetFilter = global.Targeting.Filter.ToString(),
            global.Targeting.BlockPlayerTargets,
            global.Targeting.AutoAcquireWhenNoTarget,
            global.Targeting.ScanIntervalMs,
            global.Targeting.AcquireIntervalMs,
            skills = global.Skills.Select(s => new
            {
                s.Name,
                s.Enabled,
                kind = s.Kind.ToString(),
                condition = s.Condition.ToString(),
                s.Hotkey,
                intervalMs = s.IntervalMs
            }).ToArray(),
            recovery = new
            {
                global.HpThresholdPct,
                global.MpThresholdPct,
                global.PetFoodThresholdPct,
                global.BloodManaThresholdPct,
                global.SymbiosisHealThresholdPct,
                pillSharedCooldownMs = ResolvePreviewPillCooldownMs(global),
                bloodManaCooldownMs = Math.Max(30000, global.BloodManaCooldownMs),
                symbiosisHealCooldownMs = Math.Max(30000, global.SymbiosisHealCooldownMs)
            },
            returnPoint = new
            {
                returnPointConfig.EnableFixedFarmReturn,
                returnPointConfig.EnableEarthSpiritReturn,
                returnPointConfig.EnableDeathReturn,
                returnPointConfig.EnableStuckRecovery,
                returnPointConfig.CheckIntervalMs,
                returnPointConfig.ArrivalDistance,
                returnPointConfig.StuckTimeoutMs,
                returnPointConfig.ReturnRetryLimit,
                points = returnPointConfig.Points.Select(p => new
                {
                    p.MapName,
                    p.X,
                    p.Y,
                    p.Label,
                    kind = p.Kind.ToString(),
                    p.SourceModule,
                    p.SourcePath
                }).ToArray(),
                returnMode = returnPointConfig.ReturnNavigation.Mode.ToString(),
                returnHotkey = returnPointConfig.ReturnNavigation.Hotkey,
                earthMode = returnPointConfig.EarthSpiritNavigation.Mode.ToString(),
                earthHotkey = returnPointConfig.EarthSpiritNavigation.Hotkey,
                deathMode = returnPointConfig.DeathReturnNavigation.Mode.ToString(),
                deathHotkey = returnPointConfig.DeathReturnNavigation.Hotkey,
                stuckMode = returnPointConfig.StuckRecoveryNavigation.Mode.ToString(),
                stuckHotkey = returnPointConfig.StuckRecoveryNavigation.Hotkey
            }
        },
        recognitionBefore = BuildCombatPreviewSnapshot(combatBefore),
        runtimeSnapshotBefore = runtimeSnapshotBefore is null
            ? null
            : new
            {
                provider = runtimeSnapshotBefore.Provider.ToString(),
                runtimeSnapshotBefore.Source,
                quality = runtimeSnapshotBefore.Quality.ToString(),
                runtimeSnapshotBefore.Message,
                target = runtimeSnapshotBefore.Target
            },
        backendBefore = new
        {
            kind = previewBackend.Kind.ToString(),
            previewBackend.DisplayName,
            status = previewBackendStatus,
            snapshot = BuildCombatPreviewSnapshot(backendBefore)
        },
        recognitionAfter = BuildCombatPreviewSnapshot(combatAfter),
        prediction = new
        {
            wouldAcquire,
            wouldNormalAttack,
            wouldUseCombatSkill,
            wouldUseBuff,
            wouldUseSkill,
            wouldAttack,
            wouldUseReturnHotkey,
            wouldUseRecoveryHotkey,
            wouldUseRecoveryClick,
            protectedTargetWouldBeAttacked,
            coarseProtectedTargetWithAttack,
            reason = protectedTargetWouldBeAttacked
                ? "日志顺序显示保护目标期间仍计划攻击，需要阻断。"
                : coarseProtectedTargetWithAttack
                    ? "截图级粗略检测发现保护目标与攻击动作同段出现；日志顺序未发现保护目标后继续攻击。"
                    : "未发现玩家/宠物保护冲突。"
        },
        recoveryPreview = new
        {
            actions = recoveryActions,
            overlay = new
            {
                path = recoveryOverlayPath,
                saved = recoveryOverlaySaved,
                markers = recoveryActions
                    .Where(a => a.ClientClickX is not null && a.ClientClickY is not null)
                    .Select(a => new
                    {
                        a.Key,
                        a.Label,
                        x = a.ClientClickX,
                        y = a.ClientClickY,
                        bottomOffset = a.ClientClickBottomOffset,
                        a.ClientClickClientSize
                    })
                    .ToArray()
            }
        },
        plannedInput = new
        {
            hotkeys,
            hotkeyCounts,
            clicks,
            sentTexts = input.SentTexts.ToArray()
        },
        controller = new
        {
            stateBeforeStop,
            runStateBeforeStop = runStateBeforeStop.ToString(),
            stateAfterStop = controller.CurrentStateName,
            runStateAfterStop = controller.RunState.ToString()
        },
        capture = capture is null ? null : new
        {
            capture.Width,
            capture.Height,
            visual = HasVisualContent(capture),
            path = clientPath,
            saved = clientSaved
        },
        overlay = new { path = overlayPath, saved = overlaySaved },
        combatRegions,
        logs
    };

    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Pid={window.Pid}");
    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<default>" : profileName)}");
    if (profileLoad is not null)
        Console.WriteLine($"Profile modules loaded={profileLoad.LoadedModules.Count}, missing={profileLoad.MissingModules.Count}");
    Console.WriteLine($"Bitness={window.Bitness}, size={window.ClientSizeText}, allowed={window.IsAutomationAllowed}");
    Console.WriteLine($"Duration={durationMs}ms, backend={global.CombatBackendPreference}, inputMode={global.InputDispatchMode}");
    Console.WriteLine($"NavigationMode={(lockedNavigation is null ? "live-per-loop" : "locked-live-snapshot")}, locked={lockedNavigation?.MapNameText ?? "-"} {lockedNavigation?.CoordinateText ?? "-"}");
    Console.WriteLine($"Return points={returnPointConfig.Points.Count}, fixed={returnPointConfig.EnableFixedFarmReturn}, earth={returnPointConfig.EnableEarthSpiritReturn}, death={returnPointConfig.EnableDeathReturn}, stuck={returnPointConfig.EnableStuckRecovery}");
    Console.WriteLine($"Dictionaries total={dictionaryLoad.TotalFiles}, loadedFiles={dictionaryLoad.LoadedFiles}, glyphs={ocr.LoadedGlyphCount}, renderable={ocr.RenderableGlyphCount}");
    Console.WriteLine($"Recognition target='{combatBefore.TargetNameText}', targetHp={combatBefore.TargetHpPercent}, hp={combatBefore.PlayerHpPercent}, mp={combatBefore.PlayerMpPercent}, pet={combatBefore.PetHpPercent}, player={combatBefore.TargetLooksLikePlayer}, protectionRisk={combatBefore.TargetProtectionAmbiguous}, petTarget={combatBefore.TargetLooksLikePet}, attackable={combatBefore.TargetIsAttackable}");
    if (runtimeSnapshotBefore is not null)
        Console.WriteLine($"RuntimeSnapshot provider={runtimeSnapshotBefore.Provider}, source={runtimeSnapshotBefore.Source}, targetKind={runtimeSnapshotBefore.Target.Kind}, targetName='{runtimeSnapshotBefore.Target.Name}', targetHp={runtimeSnapshotBefore.Target.HpPercent}, attackable={runtimeSnapshotBefore.Target.IsAttackable}");
    Console.WriteLine($"Backend target='{backendBefore.TargetNameText}', targetHp={backendBefore.TargetHpPercent}, hp={backendBefore.PlayerHpPercent}, mp={backendBefore.PlayerMpPercent}, pet={backendBefore.PetHpPercent}, player={backendBefore.TargetLooksLikePlayer}, protectionRisk={backendBefore.TargetProtectionAmbiguous}, petTarget={backendBefore.TargetLooksLikePet}, attackable={backendBefore.TargetIsAttackable}, sample={backendBefore.TargetSampleKind}");
    Console.WriteLine($"Would acquire={wouldAcquire}, normalAttack={wouldNormalAttack}, combatSkill={wouldUseCombatSkill}, buff={wouldUseBuff}, anySkill={wouldUseSkill}, attack={wouldAttack}, recoveryKey={wouldUseRecoveryHotkey}, recoveryClick={wouldUseRecoveryClick}");
    foreach (var action in recoveryActions)
        Console.WriteLine($"Recovery {action.Label}: {action.Decision} | {action.Reason} | {action.Action}");
    Console.WriteLine($"RecoveryOverlay={recoveryOverlayPath}, saved={recoveryOverlaySaved}");
    Console.WriteLine($"Would returnHotkey={wouldUseReturnHotkey}, returnHotkeys={(returnHotkeys.Length == 0 ? "-" : string.Join("/", returnHotkeys))}");
    Console.WriteLine($"Hotkeys={hotkeyCountText}");
    Console.WriteLine($"Clicks={clicks.Length}");
    Console.WriteLine($"Controller beforeStop={runStateBeforeStop}/{stateBeforeStop}");
    Console.WriteLine($"ProtectionConflict={protectedTargetWouldBeAttacked}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = window.IsAutomationAllowed
             && dictionaryFiles.Count > 0
             && ocr.RenderableGlyphCount > 0
             && capture is { Width: > 0, Height: > 0 }
             && HasVisualContent(capture)
             && clientSaved
             && overlaySaved
             && recoveryOverlaySaved
             && combatRegions.All(r => r.Saved && r.ZoomSaved)
             && !protectedTargetWouldBeAttacked
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;

    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static object BuildCombatPreviewSnapshot(CombatRecognitionResult combat) => new
{
    combat.TargetNameText,
    combat.TargetHpText,
    combat.PlayerHpText,
    combat.PlayerMpText,
    combat.PetHpText,
    combat.TargetHpPercent,
    combat.PlayerHpPercent,
    combat.PlayerMpPercent,
    combat.PetHpPercent,
    combat.HasTargetName,
    combat.HasTargetHp,
    combat.HasTarget,
    combat.TargetLooksLikePlayer,
    combat.TargetProtectionAmbiguous,
    combat.TargetLooksLikePet,
    combat.TargetIsAttackable,
    combat.TargetSampleKind,
    combat.TargetSampleLabel,
    combat.TargetSampleSource,
    combat.TargetSampleScore
};

static int ReadClampedIntOption(string[] args, string name, int defaultValue, int min, int max)
{
    for (var i = 0; i < args.Length; i++)
    {
        if (!string.Equals(args[i], name, StringComparison.OrdinalIgnoreCase))
            continue;

        if (i + 1 >= args.Length || !int.TryParse(args[i + 1], out var value))
            return defaultValue;

        return Math.Clamp(value, min, max);
    }

    return defaultValue;
}

static string? ReadStringOption(string[] args, string name)
{
    for (var i = 0; i < args.Length; i++)
    {
        if (!string.Equals(args[i], name, StringComparison.OrdinalIgnoreCase))
            continue;

        if (i + 1 >= args.Length)
            return null;

        var value = args[i + 1].Trim();
        return string.IsNullOrWhiteSpace(value) ? null : value;
    }

    return null;
}

static bool HasFlag(string[] args, string name) =>
    args.Any(a => string.Equals(a, name, StringComparison.OrdinalIgnoreCase));

static bool HasProtectedTargetAttackConflict(IReadOnlyList<LogEntry> entries)
{
    var protectedTargetActive = false;
    foreach (var entry in entries.OrderBy(e => e.Time))
    {
        var message = entry.Message;
        if (message.Contains("疑似玩家目标", StringComparison.Ordinal)
            || message.Contains("疑似宠物目标", StringComparison.Ordinal))
        {
            protectedTargetActive = true;
            continue;
        }

        if (message.Contains("玩家目标保护", StringComparison.Ordinal)
            || message.Contains("宠物目标保护", StringComparison.Ordinal)
            || message.Contains("重新选怪", StringComparison.Ordinal)
            || message.Contains("发送选怪热键", StringComparison.Ordinal))
        {
            protectedTargetActive = false;
            continue;
        }

        if (protectedTargetActive
            && (message.Contains("发送普攻热键", StringComparison.Ordinal)
                || message.Contains("释放技能", StringComparison.Ordinal)
                || message.Contains("释放Buff", StringComparison.Ordinal)))
        {
            return true;
        }
    }

    return false;
}

static string? TryLoadCurrentGlobalConfig(ServiceProvider provider)
{
    var profiles = provider.GetRequiredService<IAppProfileService>();
    var profileName = profiles.CurrentProfileName;
    if (string.IsNullOrWhiteSpace(profileName))
        profileName = profiles.ListProfileNames().FirstOrDefault();

    if (string.IsNullOrWhiteSpace(profileName))
        return null;

    var loaded = provider.GetRequiredService<IGlobalConfigService>().Load(profileName);
    return loaded ? profileName : null;
}

static List<RecoveryPreviewAction> BuildRecoveryPreviewActions(GlobalConfig cfg, CombatRecognitionResult combat, BoundGameWindow window)
{
    var actions = new List<RecoveryPreviewAction>();
    var pillCooldownMs = ResolvePreviewPillCooldownMs(cfg);

    var healWillUsePill = AddHotkeyThresholdPreview(
        actions,
        key: "pill-heal",
        label: "吃药回血",
        source: "PlayerHpPercent",
        currentPercent: combat.PlayerHpPercent,
        thresholdPercent: cfg.HpThresholdPct,
        hotkey: cfg.HealHotkey,
        effectiveCooldownMs: pillCooldownMs,
        blockedReason: "");

    AddHotkeyThresholdPreview(
        actions,
        key: "pill-mana",
        label: "吃药回蓝",
        source: "PlayerMpPercent",
        currentPercent: combat.PlayerMpPercent,
        thresholdPercent: cfg.MpThresholdPct,
        hotkey: cfg.ManaHotkey,
        effectiveCooldownMs: pillCooldownMs,
        blockedReason: healWillUsePill ? "吃药回血在同一轮优先占用了药品公共 CD。" : "");

    AddPetSkillThresholdPreview(
        actions,
        key: "blood-mana",
        label: "血迹回蓝",
        source: "PlayerMpPercent",
        currentPercent: combat.PlayerMpPercent,
        thresholdPercent: cfg.BloodManaThresholdPct,
        activationMode: cfg.BloodManaActivationMode,
        hotkey: EffectivePreviewBloodManaHotkey(cfg),
        click: ResolvePreviewPetSkillClickPoint("血迹回蓝", cfg.BloodManaClickX, cfg.BloodManaClickBottomOffset, window),
        effectiveCooldownMs: Math.Max(30000, cfg.BloodManaCooldownMs));

    AddPetSkillThresholdPreview(
        actions,
        key: "symbiosis-heal",
        label: "共生回血",
        source: "PlayerHpPercent",
        currentPercent: combat.PlayerHpPercent,
        thresholdPercent: cfg.SymbiosisHealThresholdPct,
        activationMode: cfg.SymbiosisHealActivationMode,
        hotkey: cfg.SymbiosisHealHotkey,
        click: ResolvePreviewPetSkillClickPoint("共生回血", cfg.SymbiosisHealClickX, cfg.SymbiosisHealClickBottomOffset, window),
        effectiveCooldownMs: Math.Max(30000, cfg.SymbiosisHealCooldownMs));

    AddHotkeyThresholdPreview(
        actions,
        key: "pet-food",
        label: "宠粮回血",
        source: "PetHpPercent",
        currentPercent: combat.PetHpPercent,
        thresholdPercent: cfg.PetFoodThresholdPct,
        hotkey: EffectivePreviewPetFoodHotkey(cfg),
        effectiveCooldownMs: Math.Max(10000, cfg.PetFoodCooldownMs),
        blockedReason: "");

    AddPetDeployPreview(actions, cfg, combat, window);
    return actions;
}

static bool AddHotkeyThresholdPreview(
    List<RecoveryPreviewAction> actions,
    string key,
    string label,
    string source,
    int? currentPercent,
    int thresholdPercent,
    string hotkey,
    int effectiveCooldownMs,
    string blockedReason)
{
    var conditionMet = currentPercent is not null && currentPercent <= thresholdPercent;
    var configured = !string.IsNullOrWhiteSpace(hotkey);
    var decision = "skip";
    var reason = currentPercent is null
        ? $"{source} 未识别，不能触发。"
        : $"{currentPercent}% > {thresholdPercent}%，未低于阈值。";
    var action = configured ? $"热键 {hotkey}" : "未配置热键";

    if (conditionMet)
    {
        if (!string.IsNullOrWhiteSpace(blockedReason))
        {
            decision = "blocked";
            reason = blockedReason;
        }
        else if (!configured)
        {
            decision = "blocked";
            reason = $"{currentPercent}% <= {thresholdPercent}%，但未配置热键。";
        }
        else
        {
            decision = "would-trigger";
            reason = $"{currentPercent}% <= {thresholdPercent}%，首轮冷却视为可用。";
        }
    }

    actions.Add(new RecoveryPreviewAction(
        Key: key,
        Label: label,
        Source: source,
        CurrentPercent: currentPercent,
        ThresholdPercent: thresholdPercent,
        ConditionMet: conditionMet,
        Configured: configured,
        ReadyAtStart: true,
        Action: action,
        EffectiveCooldownMs: effectiveCooldownMs,
        Decision: decision,
        Reason: reason));

    return conditionMet && configured && string.IsNullOrWhiteSpace(blockedReason);
}

static void AddPetSkillThresholdPreview(
    List<RecoveryPreviewAction> actions,
    string key,
    string label,
    string source,
    int? currentPercent,
    int thresholdPercent,
    PetSkillActivationMode activationMode,
    string hotkey,
    PetSkillClickPoint click,
    int effectiveCooldownMs)
{
    var conditionMet = currentPercent is not null && currentPercent <= thresholdPercent;
    var configured = activationMode == PetSkillActivationMode.ClientClick || !string.IsNullOrWhiteSpace(hotkey);
    var action = activationMode == PetSkillActivationMode.ClientClick
        ? $"点击客户区({click.X},{click.Y})"
        : (!string.IsNullOrWhiteSpace(hotkey) ? $"热键 {hotkey}" : "未配置热键");
    var decision = "skip";
    var reason = currentPercent is null
        ? $"{source} 未识别，不能触发。"
        : $"{currentPercent}% > {thresholdPercent}%，未低于阈值。";

    if (conditionMet)
    {
        if (!configured)
        {
            decision = "blocked";
            reason = $"{currentPercent}% <= {thresholdPercent}%，但未配置触发方式。";
        }
        else
        {
            decision = "would-trigger";
            reason = $"{currentPercent}% <= {thresholdPercent}%，宠物技能独立冷却首轮视为可用。";
        }
    }

    actions.Add(new RecoveryPreviewAction(
        Key: key,
        Label: label,
        Source: source,
        CurrentPercent: currentPercent,
        ThresholdPercent: thresholdPercent,
        ConditionMet: conditionMet,
        Configured: configured,
        ReadyAtStart: true,
        Action: action,
        EffectiveCooldownMs: effectiveCooldownMs,
        Decision: decision,
        Reason: reason,
        ClientClickX: activationMode == PetSkillActivationMode.ClientClick ? click.X : null,
        ClientClickY: activationMode == PetSkillActivationMode.ClientClick ? click.Y : null,
        ClientClickBottomOffset: activationMode == PetSkillActivationMode.ClientClick ? click.BottomOffset : null,
        ClientClickClientSize: activationMode == PetSkillActivationMode.ClientClick ? click.ClientSize : null));
}

static void AddPetDeployPreview(List<RecoveryPreviewAction> actions, GlobalConfig cfg, CombatRecognitionResult combat, BoundGameWindow window)
{
    var conditionMet = combat.PetHpPercent is null;
    var useClick = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick;
    var clickConfigured = cfg.PetDeployClickX > 0 && cfg.PetDeployClickBottomOffset > 0;
    var click = useClick && clickConfigured
        ? ResolvePreviewPetSkillClickPoint("宠物出战", cfg.PetDeployClickX, cfg.PetDeployClickBottomOffset, window)
        : new PetSkillClickPoint("宠物出战", 0, 0, 0, window.ClientSizeText);
    var configured = useClick ? clickConfigured : !string.IsNullOrWhiteSpace(cfg.PetDeployHotkey);
    var action = useClick
        ? (configured ? $"点击客户区({click.X},{click.Y})" : "未校准点击点")
        : (configured ? $"热键 {cfg.PetDeployHotkey}" : "未配置热键");
    var decision = "skip";
    var reason = combat.PetHpPercent is null
        ? "当前单帧未识别到宠物血条；实战需要连续 3 轮未识别才尝试出战。"
        : $"宠物血量已识别为 {combat.PetHpPercent}%，不触发出战。";

    if (conditionMet)
    {
        if (!configured)
        {
            decision = "blocked";
            reason += useClick ? " 但未校准宠物出战点击点。" : " 但未配置宠物出战热键。";
        }
        else
        {
            decision = "pending";
            reason += " 如果连续 3 轮成立，将触发出战当前宠物。";
        }
    }

    actions.Add(new RecoveryPreviewAction(
        Key: "pet-deploy",
        Label: "宠物出战",
        Source: "PetHpPercent",
        CurrentPercent: combat.PetHpPercent,
        ThresholdPercent: 0,
        ConditionMet: conditionMet,
        Configured: configured,
        ReadyAtStart: true,
        Action: action,
        EffectiveCooldownMs: Math.Max(3000, cfg.PetDeployCooldownMs),
        Decision: decision,
        Reason: reason,
        ClientClickX: useClick && configured ? click.X : null,
        ClientClickY: useClick && configured ? click.Y : null,
        ClientClickBottomOffset: useClick && configured ? click.BottomOffset : null,
        ClientClickClientSize: useClick && configured ? click.ClientSize : null));
}

static int ResolvePreviewPillCooldownMs(GlobalConfig cfg) =>
    Math.Max(10000, Math.Max(cfg.PillHealCooldownMs, cfg.PillManaCooldownMs));

static string EffectivePreviewBloodManaHotkey(GlobalConfig cfg) =>
    !string.IsNullOrWhiteSpace(cfg.BloodManaHotkey) ? cfg.BloodManaHotkey : cfg.PetManaHotkey;

static string EffectivePreviewPetFoodHotkey(GlobalConfig cfg) =>
    !string.IsNullOrWhiteSpace(cfg.PetFoodHotkey) ? cfg.PetFoodHotkey : cfg.PetHealHotkey;

static PetSkillClickPoint ResolvePreviewPetSkillClickPoint(string label, int x, int bottomOffset, BoundGameWindow target)
{
    var legacyBadDefault = (x == 170 || x == 135) && bottomOffset == 90;
    var resolvedX = x;
    var resolvedBottom = bottomOffset;

    if (legacyBadDefault || resolvedX <= 0 || resolvedX >= target.ClientWidth)
    {
        var ratio = x == 135 ? 0.405 : 0.43;
        resolvedX = (int)Math.Round(target.ClientWidth * ratio);
    }

    if (legacyBadDefault || resolvedBottom <= 0 || resolvedBottom >= target.ClientHeight)
        resolvedBottom = (int)Math.Round(target.ClientHeight * 0.065);

    resolvedX = Math.Clamp(resolvedX, 0, Math.Max(0, target.ClientWidth - 1));
    resolvedBottom = Math.Clamp(resolvedBottom, 1, Math.Max(1, target.ClientHeight - 1));
    var y = target.ClientHeight - resolvedBottom;
    return new PetSkillClickPoint(label, resolvedX, y, resolvedBottom, target.ClientSizeText);
}

static bool SaveCapturePng(CaptureResult? capture, string path)
{
    if (capture is null || capture.Width <= 0 || capture.Height <= 0 || capture.Pixels.Length < capture.Width * capture.Height * 4)
        return false;

    try
    {
        var source = BitmapSource.Create(
            capture.Width,
            capture.Height,
            96,
            96,
            PixelFormats.Bgr32,
            null,
            capture.Pixels,
            capture.Width * 4);
        source.Freeze();

        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(source));
        using (var stream = File.Create(path))
        {
            encoder.Save(stream);
        }
        return new FileInfo(path).Length > 0;
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"PNG 保存失败：{ex.Message}");
        return false;
    }
}

static bool SavePanelEntryOverlayPng(
    CaptureResult capture,
    int stripX,
    int stripY,
    int selectedSlotIndex,
    string path)
{
    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);
    DrawRect(pixels, capture.Width, capture.Height, stripX, stripY, 175, 48, 50, 220, 255);
    for (var index = 0; index < 5; index++)
    {
        var selected = index == selectedSlotIndex;
        DrawRect(
            pixels,
            capture.Width,
            capture.Height,
            stripX + index * 35,
            stripY,
            35,
            48,
            selected ? (byte)255 : (byte)90,
            selected ? (byte)215 : (byte)170,
            selected ? (byte)40 : (byte)255);
    }
    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static bool SaveInteractionWindowOverlayPng(
    CaptureResult capture,
    IReadOnlyList<InteractionWindowDetection> detections,
    string path)
{
    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);
    foreach (var detection in detections)
    {
        var box = detection.Box;
        var (r, g, b) = string.Equals(detection.ClassName, "quest_log_panel", StringComparison.Ordinal)
            ? ((byte)75, (byte)255, (byte)120)
            : ((byte)255, (byte)185, (byte)55);
        DrawRect(pixels, capture.Width, capture.Height, box.X, box.Y, box.Width, box.Height, r, g, b);
    }
    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static CaptureResult? LoadCapturePng(string path)
{
    try
    {
        using var stream = File.OpenRead(path);
        var decoder = BitmapDecoder.Create(stream, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
        var frame = decoder.Frames[0];
        BitmapSource converted = frame.Format == PixelFormats.Bgr32
            ? frame
            : new FormatConvertedBitmap(frame, PixelFormats.Bgr32, null, 0);
        converted.Freeze();

        var stride = converted.PixelWidth * 4;
        var pixels = new byte[stride * converted.PixelHeight];
        converted.CopyPixels(pixels, stride, 0);
        return new CaptureResult(converted.PixelWidth, converted.PixelHeight, pixels);
    }
    catch (Exception ex)
    {
        Console.Error.WriteLine($"PNG 读取失败：{ex.Message}");
        return null;
    }
}

static bool SaveGridOverlayPng(CaptureResult capture, InventoryGridConfig? grid, string path)
{
    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);
    if (grid is not null)
    {
        var totalWidth = grid.Columns * grid.CellWidth + Math.Max(0, grid.Columns - 1) * grid.GapX;
        var totalHeight = grid.Rows * grid.CellHeight + Math.Max(0, grid.Rows - 1) * grid.GapY;
        DrawRect(pixels, capture.Width, capture.Height, grid.X, grid.Y, totalWidth, totalHeight, 70, 255, 70);
        for (var row = 0; row < grid.Rows; row++)
        {
            for (var col = 0; col < grid.Columns; col++)
            {
                var x = grid.X + col * (grid.CellWidth + grid.GapX);
                var y = grid.Y + row * (grid.CellHeight + grid.GapY);
                DrawRect(pixels, capture.Width, capture.Height, x, y, grid.CellWidth, grid.CellHeight, 255, 225, 45);
            }
        }
    }

    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static CombatRegionEvidence[] BuildCombatRegionEvidence(
    CaptureResult? client,
    CombatRecognitionConfig config,
    string evidenceDir,
    CombatRecognitionResult combat)
{
    var regions = new List<CombatRegionEvidence>
    {
        SaveCombatRegionEvidence(client, "target-name", config.TargetName, evidenceDir, combat.TargetNameText, null),
        SaveCombatRegionEvidence(client, "target-hp", config.TargetHp, evidenceDir, combat.TargetHpText, combat.TargetHpPercent),
        SaveCombatRegionEvidence(client, "target-mp", config.TargetMp, evidenceDir, string.Empty, null),
        SaveCombatRegionEvidence(client, "target-rage", config.TargetRage, evidenceDir, string.Empty, null),
        SaveCombatRegionEvidence(client, "player-hp", config.PlayerHp, evidenceDir, combat.PlayerHpText, combat.PlayerHpPercent),
        SaveCombatRegionEvidence(client, "player-mp", config.PlayerMp, evidenceDir, combat.PlayerMpText, combat.PlayerMpPercent),
        SaveCombatRegionEvidence(client, "pet-hp", config.PetHp, evidenceDir, combat.PetHpText, combat.PetHpPercent)
    };

    if (client is not null)
    {
        var targetHp = OcrRegionProjection.Resolve(config.TargetHp, client.Width, client.Height);
        var playerHp = OcrRegionProjection.Resolve(config.PlayerHp, client.Width, client.Height);

        regions.Add(SaveResolvedCombatRegionEvidence(
            client,
            "target-status",
            ClampCombatRegion(new OcrResolvedRegion(targetHp.X, targetHp.Y, targetHp.Width, Math.Min(26, client.Height - targetHp.Y)), client.Width, client.Height),
            evidenceDir,
            null,
            null));
        regions.Add(SaveResolvedCombatRegionEvidence(
            client,
            "school-marker",
            ClampCombatRegion(new OcrResolvedRegion(Math.Max(0, targetHp.X - 36), Math.Max(0, targetHp.Y - 24), 36, 82), client.Width, client.Height),
            evidenceDir,
            null,
            null));
        regions.Add(SaveResolvedCombatRegionEvidence(
            client,
            "target-portrait",
            ClampCombatRegion(new OcrResolvedRegion(Math.Min(client.Width - 1, targetHp.X + targetHp.Width + 10), Math.Max(0, targetHp.Y - 24), 88, 88), client.Width, client.Height),
            evidenceDir,
            null,
            null));
        regions.Add(SaveResolvedCombatRegionEvidence(
            client,
            "player-rage",
            ClampCombatRegion(new OcrResolvedRegion(playerHp.X, playerHp.Y + 12, playerHp.Width, 6), client.Width, client.Height),
            evidenceDir,
            null,
            null));
    }

    return regions.ToArray();
}

static CombatRegionEvidence[] BuildVisionV2CombatRegionEvidence(
    CaptureResult? client,
    RuntimePerceptionSnapshot snapshot,
    string evidenceDir,
    CombatRecognitionResult combat)
{
    var bars = snapshot.SelfBars;
    return
    [
        SaveVisionRegionEvidence(client, "target-panel", snapshot.Target.PanelBox, snapshot.Target.PanelBox, VisionBox.Empty, evidenceDir, null, null, "L1 target_status_panel"),
        SaveVisionRegionEvidence(client, "target-name", snapshot.Target.NameBox, snapshot.Target.PanelBox, RelativeTo(snapshot.Target.PanelBox, snapshot.Target.NameBox), evidenceDir, combat.TargetNameText, null, "L1 target_name"),
        SaveVisionRegionEvidence(client, "target-hp", snapshot.Target.HpBarBox, snapshot.Target.PanelBox, RelativeTo(snapshot.Target.PanelBox, snapshot.Target.HpBarBox), evidenceDir, combat.TargetHpText, combat.TargetHpPercent, "L1/L2 target HP"),
        SaveVisionRegionEvidence(client, "player-panel", bars.PlayerPanelBox, bars.PlayerPanelBox, VisionBox.Empty, evidenceDir, null, null, bars.PlayerPanelGeometrySource),
        SaveVisionRegionEvidence(client, "player-hp", bars.PlayerHpSourceBox, bars.PlayerPanelBox, bars.PlayerHpRelativeBox, evidenceDir, combat.PlayerHpText, combat.PlayerHpPercent, $"Vision V2 player slot via {bars.PlayerPanelGeometrySource}"),
        SaveVisionRegionEvidence(client, "player-mp", bars.PlayerMpSourceBox, bars.PlayerPanelBox, bars.PlayerMpRelativeBox, evidenceDir, combat.PlayerMpText, combat.PlayerMpPercent, $"Vision V2 player slot via {bars.PlayerPanelGeometrySource}"),
        SaveVisionRegionEvidence(client, "pet-panel", bars.PetPanelBox, bars.PetPanelBox, VisionBox.Empty, evidenceDir, null, null, bars.PetPanelGeometrySource),
        SaveVisionRegionEvidence(client, "pet-hp", bars.PetHpSourceBox, bars.PetPanelBox, bars.PetHpRelativeBox, evidenceDir, combat.PetHpText, combat.PetHpPercent, $"Vision V2 pet slot via {bars.PetPanelGeometrySource}")
    ];
}

static CombatRegionEvidence SaveVisionRegionEvidence(
    CaptureResult? client,
    string name,
    VisionBox sourceBox,
    VisionBox panelBox,
    VisionBox relativeBox,
    string evidenceDir,
    string? recognizedText,
    int? recognizedPercent,
    string geometrySource)
{
    var resolved = sourceBox.IsEmpty
        ? new OcrResolvedRegion(0, 0, 0, 0)
        : ClampCombatRegion(
            new OcrResolvedRegion(sourceBox.X, sourceBox.Y, sourceBox.Width, sourceBox.Height),
            client?.Width ?? 0,
            client?.Height ?? 0);
    return SaveResolvedCombatRegionEvidence(
        client,
        name,
        resolved,
        evidenceDir,
        recognizedText,
        recognizedPercent) with
    {
        GeometrySource = geometrySource,
        ParentPanelBox = panelBox,
        RelativeBox = relativeBox,
        SourceBox = sourceBox
    };
}

static VisionBox RelativeTo(VisionBox panel, VisionBox source)
{
    if (panel.IsEmpty || source.IsEmpty)
        return VisionBox.Empty;
    return new VisionBox(source.X - panel.X, source.Y - panel.Y, source.Width, source.Height);
}

static TargetProtectionEvidence BuildTargetProtectionEvidence(
    CaptureResult? client,
    CombatRecognitionConfig config,
    CombatRecognitionResult combat,
    IReadOnlyList<CombatRegionEvidence> regions)
{
    var statusBars = AnalyzeTargetStatusBars(client, config);
    var schoolMarker = AnalyzeTargetSchoolMarker(client, config);
    var portrait = AnalyzeTargetPortrait(client, config);
    var references = regions
        .Where(r => r.Name is "target-hp" or "target-mp" or "target-rage" or "target-status" or "school-marker" or "target-portrait")
        .Select(r => new TargetProtectionRegionReference(
            r.Name,
            r.ResolvedX,
            r.ResolvedY,
            r.ResolvedWidth,
            r.ResolvedHeight,
            r.Path,
            r.ZoomPath,
            r.Saved,
            r.ZoomSaved,
            r.Visual))
        .ToArray();

    var protectedByPlayerGuard = combat.TargetLooksLikePlayer;
    var decision = combat.TargetLooksLikePlayer
        ? "ProtectedPlayerTarget"
        : combat.TargetProtectionAmbiguous
            ? "ReviewHighRiskSchoolMarker"
        : schoolMarker.Matched
            ? "AmbiguousSchoolMarkerNeedsTemplate"
        : combat.HasTarget
            ? "NotClassifiedAsPlayer"
            : "NoActionableTarget";
    var reason = combat.TargetLooksLikePlayer
        ? "命中玩家保护特征；正式打怪链路会阻止普攻和技能，并切换下一个目标。"
        : combat.TargetProtectionAmbiguous
            ? "检测到门派竖牌/头像类高风险结构；正式打怪链路会跳过攻击并重新选怪，但不会把它升级为已确认玩家。"
        : schoolMarker.Matched
            ? "检测到竖牌/头像类结构，但当前未接入门派模板；该信号只作诊断，不直接判定玩家，避免首领/怪物误拦。"
        : combat.HasTarget
            ? "当前未命中玩家保护特征；仍需经过宠物/不可攻击/目标策略等后续门槛。"
            : "当前没有可行动目标；正式打怪链路只会尝试选怪。";

    return new TargetProtectionEvidence(
        protectedByPlayerGuard,
        decision,
        reason,
        statusBars,
        schoolMarker,
        portrait,
        references,
        EvidenceComplete: client is not null
                          && statusBars.EvidenceComplete
                          && schoolMarker.EvidenceComplete
                          && portrait.EvidenceComplete
                          && references.Length >= 6
                          && references.All(r => r.Saved && r.ZoomSaved));
}

static TargetStatusBarsEvidence AnalyzeTargetStatusBars(CaptureResult? client, CombatRecognitionConfig config)
{
    if (client is null)
        return TargetStatusBarsEvidence.Empty("no-client-capture");

    var hp = OcrRegionProjection.Resolve(config.TargetHp, client.Width, client.Height);
    var mp = OcrRegionProjection.Resolve(config.TargetMp, client.Width, client.Height);
    var rage = OcrRegionProjection.Resolve(config.TargetRage, client.Width, client.Height);

    var hpSample = CropCapture(client, hp);
    var mpSample = CropCapture(client, mp);
    var rageSample = CropCapture(client, rage);

    var redHp = AnalyzeHorizontalColorBar(hpSample, IsDiagnosticRedStatusPixel, 0.30);
    var greenHp = AnalyzeHorizontalColorBar(hpSample, IsDiagnosticGreenStatusPixel, 0.30);
    var blue = AnalyzeHorizontalColorBar(mpSample, IsDiagnosticBlueStatusPixel, 0.24);
    var yellow = AnalyzeHorizontalColorBar(rageSample, IsDiagnosticYellowStatusPixel, 0.24);
    var hasHp = redHp.Matched || greenHp.Matched;
    var matched = hasHp && (blue.Matched || yellow.Matched);

    return new TargetStatusBarsEvidence(
        Matched: matched,
        HasHpBar: hasHp,
        HasBlueBar: blue.Matched,
        HasYellowRageBar: yellow.Matched,
        RedHp: redHp,
        GreenHp: greenHp,
        BlueMp: blue,
        YellowRage: yellow,
        EvidenceComplete: !hp.IsEmpty && !mp.IsEmpty && !rage.IsEmpty && hpSample is not null && mpSample is not null && rageSample is not null,
        Rule: "HP(red|green) && (MP blue || rage yellow). MP/rage may be empty, so school marker is a separate fallback.");
}

static TargetSchoolMarkerEvidence AnalyzeTargetSchoolMarker(CaptureResult? client, CombatRecognitionConfig config)
{
    if (client is null)
        return TargetSchoolMarkerEvidence.Empty("no-client-capture");

    var hp = OcrRegionProjection.Resolve(config.TargetHp, client.Width, client.Height);
    if (hp.IsEmpty)
        return TargetSchoolMarkerEvidence.Empty("target-hp-region-empty");

    var marker = ClampCombatRegion(
        new OcrResolvedRegion(Math.Max(0, hp.X - 36), Math.Max(0, hp.Y - 24), 36, 82),
        client.Width,
        client.Height);
    var sample = CropCapture(client, marker);
    if (sample is null)
        return TargetSchoolMarkerEvidence.Empty("marker-crop-empty");

    var total = sample.Width * sample.Height;
    var gold = 0;
    var dark = 0;
    var verticalGoldColumns = 0;
    var strongEdges = 0;

    for (var x = 0; x < sample.Width; x++)
    {
        var columnGold = 0;
        for (var y = 0; y < sample.Height; y++)
        {
            var p = (y * sample.Width + x) * 4;
            var b = sample.Pixels[p];
            var g = sample.Pixels[p + 1];
            var r = sample.Pixels[p + 2];

            if (IsDiagnosticSchoolGoldPixel(r, g, b))
            {
                gold++;
                columnGold++;
            }

            if (Math.Max(r, Math.Max(g, b)) < 55)
                dark++;

            if (x > 0)
            {
                var left = p - 4;
                var lum = r + g + b;
                var leftLum = sample.Pixels[left + 2] + sample.Pixels[left + 1] + sample.Pixels[left];
                if (Math.Abs(lum - leftLum) > 100)
                    strongEdges++;
            }
        }

        if (columnGold >= Math.Max(5, sample.Height / 5))
            verticalGoldColumns++;
    }

    var goldRatio = Ratio(gold, total);
    var darkRatio = Ratio(dark, total);
    var edgeRatio = Ratio(strongEdges, total);
    var matched = goldRatio > 0.045
                  && darkRatio > 0.18
                  && edgeRatio > 0.045
                  && verticalGoldColumns >= 2;

    return new TargetSchoolMarkerEvidence(
        Matched: matched,
        GoldRatio: goldRatio,
        DarkRatio: darkRatio,
        EdgeRatio: edgeRatio,
        VerticalGoldColumns: verticalGoldColumns,
        EvidenceComplete: true,
        Rule: "goldRatio>0.045 && darkRatio>0.18 && edgeRatio>0.045 && verticalGoldColumns>=2");
}

static TargetPortraitEvidence AnalyzeTargetPortrait(CaptureResult? client, CombatRecognitionConfig config)
{
    if (client is null)
        return new TargetPortraitEvidence(false, false, 0, 0, 0, 0, 0, false, "no-client-capture", "portrait is auxiliary; school marker requires player-like portrait");

    var hp = OcrRegionProjection.Resolve(config.TargetHp, client.Width, client.Height);
    if (hp.IsEmpty)
        return new TargetPortraitEvidence(false, false, 0, 0, 0, 0, 0, false, "target-hp-region-empty", "portrait is auxiliary; school marker requires player-like portrait");

    var portrait = ClampCombatRegion(
        new OcrResolvedRegion(Math.Min(client.Width - 1, hp.X + hp.Width + 10), Math.Max(0, hp.Y - 24), 88, 88),
        client.Width,
        client.Height);
    var sample = CropCapture(client, portrait);
    if (sample is null)
        return new TargetPortraitEvidence(false, false, 0, 0, 0, 0, 0, false, "portrait-crop-empty", "portrait is auxiliary; school marker requires player-like portrait");

    var total = sample.Width * sample.Height;
    var goldOrSkin = 0;
    var bright = 0;
    var saturated = 0;
    var dark = 0;
    var edge = 0;
    for (var y = 0; y < sample.Height; y++)
    {
        for (var x = 0; x < sample.Width; x++)
        {
            var p = (y * sample.Width + x) * 4;
            var b = sample.Pixels[p];
            var g = sample.Pixels[p + 1];
            var r = sample.Pixels[p + 2];
            var max = Math.Max(r, Math.Max(g, b));
            var min = Math.Min(r, Math.Min(g, b));
            if (max > 135)
                bright++;
            if (max - min > 55)
                saturated++;
            if (max < 45)
                dark++;
            if (IsDiagnosticSkinOrGoldPixel(r, g, b))
                goldOrSkin++;

            if (x > 0 && y > 0)
            {
                var left = p - 4;
                var up = p - sample.Width * 4;
                var lum = r + g + b;
                var leftLum = sample.Pixels[left + 2] + sample.Pixels[left + 1] + sample.Pixels[left];
                var upLum = sample.Pixels[up + 2] + sample.Pixels[up + 1] + sample.Pixels[up];
                if (Math.Abs(lum - leftLum) > 95 || Math.Abs(lum - upLum) > 95)
                    edge++;
            }
        }
    }

    var goldSkinRatio = Ratio(goldOrSkin, total);
    var saturatedRatio = Ratio(saturated, total);
    var brightRatio = Ratio(bright, total);
    var darkRatio = Ratio(dark, total);
    var edgeRatio = Ratio(edge, total);
    var playerLike = goldSkinRatio > 0.10
                     && saturatedRatio > 0.18
                     && brightRatio > 0.08
                     && darkRatio > 0.05
                     && edgeRatio > 0.08;

    return new TargetPortraitEvidence(
        Visual: HasVisualContent(sample),
        PlayerLike: playerLike,
        GoldSkinRatio: goldSkinRatio,
        BrightRatio: brightRatio,
        SaturatedRatio: saturatedRatio,
        DarkRatio: darkRatio,
        EdgeRatio: edgeRatio,
        EvidenceComplete: true,
        Status: "auxiliary-only",
        Rule: "school marker must be combined with player-like portrait; portrait alone is still not sufficient");
}

static ColorBarSignalEvidence AnalyzeHorizontalColorBar(CaptureResult? image, Func<byte, byte, byte, bool> predicate, double minCoverage)
{
    if (image is null || image.Width <= 0 || image.Height <= 0)
        return new ColorBarSignalEvidence(false, 0, 0, 0, 0);

    var bestRun = 0;
    var currentRun = 0;
    var bestCoverage = 0.0;
    var minPixels = Math.Max(6, (int)Math.Round(image.Width * minCoverage));

    for (var y = 0; y < image.Height; y++)
    {
        var count = 0;
        for (var x = 0; x < image.Width; x++)
        {
            var p = (y * image.Width + x) * 4;
            var b = image.Pixels[p];
            var g = image.Pixels[p + 1];
            var r = image.Pixels[p + 2];
            if (predicate(r, g, b))
                count++;
        }

        bestCoverage = Math.Max(bestCoverage, count / (double)image.Width);
        if (count >= minPixels)
        {
            currentRun++;
            bestRun = Math.Max(bestRun, currentRun);
        }
        else
        {
            currentRun = 0;
        }
    }

    return new ColorBarSignalEvidence(
        Matched: bestRun >= 2,
        Width: image.Width,
        Height: image.Height,
        BestContinuousRows: bestRun,
        BestRowCoverage: Math.Round(bestCoverage, 4));
}

static double Ratio(int count, int total) =>
    total <= 0 ? 0 : Math.Round(count / (double)total, 4);

static bool IsDiagnosticRedStatusPixel(byte r, byte g, byte b) =>
    r > 95 && r > g + 25 && r > b + 25;

static bool IsDiagnosticBlueStatusPixel(byte r, byte g, byte b) =>
    b > 85 && b > r + 20 && b > g + 5;

static bool IsDiagnosticGreenStatusPixel(byte r, byte g, byte b) =>
    g > 95 && g > r + 20 && g > b + 20;

static bool IsDiagnosticYellowStatusPixel(byte r, byte g, byte b) =>
    r > 115 && g > 85 && b < 90 && r > b + 40 && g > b + 30;

static bool IsDiagnosticSchoolGoldPixel(byte r, byte g, byte b) =>
    r > 120 && g > 80 && b < 95 && r >= g && r > b + 35 && g > b + 20;

static bool IsDiagnosticSkinOrGoldPixel(byte r, byte g, byte b)
{
    var skin = r > 115 && g > 70 && b > 45 && r > g + 12 && g > b - 10;
    var gold = r > 130 && g > 95 && b < 90 && r >= g && g > b + 20;
    return skin || gold;
}

static CombatRegionEvidence SaveCombatRegionEvidence(
    CaptureResult? client,
    string name,
    OcrRegionConfig configured,
    string evidenceDir,
    string? recognizedText,
    int? recognizedPercent)
{
    var safeName = SanitizeFileName(name);
    var cropPath = Path.Combine(evidenceDir, $"{safeName}.png");
    var zoomPath = Path.Combine(evidenceDir, $"{safeName}-x4.png");
    var resolved = client is null
        ? new OcrResolvedRegion(0, 0, 0, 0)
        : OcrRegionProjection.Resolve(configured, client.Width, client.Height);

    return SaveCombatRegionEvidenceCore(
        client,
        name,
        configured.Enabled,
        configured.X,
        configured.Y,
        configured.Width,
        configured.Height,
        resolved,
        cropPath,
        zoomPath,
        recognizedText,
        recognizedPercent);
}

static CombatRegionEvidence SaveResolvedCombatRegionEvidence(
    CaptureResult? client,
    string name,
    OcrResolvedRegion resolved,
    string evidenceDir,
    string? recognizedText,
    int? recognizedPercent)
{
    var safeName = SanitizeFileName(name);
    return SaveCombatRegionEvidenceCore(
        client,
        name,
        enabled: true,
        configX: resolved.X,
        configY: resolved.Y,
        configWidth: resolved.Width,
        configHeight: resolved.Height,
        resolved,
        Path.Combine(evidenceDir, $"{safeName}.png"),
        Path.Combine(evidenceDir, $"{safeName}-x4.png"),
        recognizedText,
        recognizedPercent);
}

static CombatRegionEvidence SaveCombatRegionEvidenceCore(
    CaptureResult? client,
    string name,
    bool enabled,
    int configX,
    int configY,
    int configWidth,
    int configHeight,
    OcrResolvedRegion resolved,
    string cropPath,
    string zoomPath,
    string? recognizedText,
    int? recognizedPercent)
{
    var crop = client is null ? null : CropCapture(client, resolved);
    var zoom = crop is null ? null : ScaleCaptureNearest(crop, 4);
    var saved = SaveCapturePng(crop, cropPath);
    var zoomSaved = SaveCapturePng(zoom, zoomPath);

    return new CombatRegionEvidence(
        name,
        enabled,
        configX,
        configY,
        configWidth,
        configHeight,
        resolved.X,
        resolved.Y,
        resolved.Width,
        resolved.Height,
        resolved.IsEmpty,
        cropPath,
        zoomPath,
        saved,
        zoomSaved,
        HasVisualContent(crop),
        string.IsNullOrWhiteSpace(recognizedText) ? null : recognizedText.Trim(),
        recognizedPercent)
    {
        CropSha256 = saved ? ComputeFileSha256(cropPath) : null,
        ZoomSha256 = zoomSaved ? ComputeFileSha256(zoomPath) : null
    };
}

static OcrResolvedRegion ClampCombatRegion(OcrResolvedRegion region, int width, int height)
{
    if (width <= 0 || height <= 0 || region.Width <= 0 || region.Height <= 0)
        return new OcrResolvedRegion(0, 0, 0, 0);

    var x = Math.Clamp(region.X, 0, Math.Max(0, width - 1));
    var y = Math.Clamp(region.Y, 0, Math.Max(0, height - 1));
    var w = Math.Min(region.Width, width - x);
    var h = Math.Min(region.Height, height - y);
    return new OcrResolvedRegion(x, y, Math.Max(0, w), Math.Max(0, h));
}

static bool SaveCombatRegionsOverlayPng(CaptureResult capture, IReadOnlyList<CombatRegionEvidence> regions, string path)
{
    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);

    foreach (var region in regions)
    {
        var (r, g, b) = CombatRegionColor(region.Name);
        DrawRect(pixels, capture.Width, capture.Height, region.ResolvedX, region.ResolvedY, region.ResolvedWidth, region.ResolvedHeight, r, g, b);
        DrawRect(pixels, capture.Width, capture.Height, region.ResolvedX + 1, region.ResolvedY + 1, Math.Max(0, region.ResolvedWidth - 2), Math.Max(0, region.ResolvedHeight - 2), r, g, b);
    }

    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static bool SaveRecoveryActionsOverlayPng(CaptureResult capture, IReadOnlyList<RecoveryPreviewAction> actions, string path)
{
    if (capture.Width <= 0 || capture.Height <= 0 || capture.Pixels.Length < capture.Width * capture.Height * 4)
        return false;

    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);

    foreach (var action in actions.Where(a => a.ClientClickX is not null && a.ClientClickY is not null))
    {
        var x = Math.Clamp(action.ClientClickX!.Value, 0, capture.Width - 1);
        var y = Math.Clamp(action.ClientClickY!.Value, 0, capture.Height - 1);
        var (r, g, b) = RecoveryActionColor(action.Key);
        DrawTargetMarker(pixels, capture.Width, capture.Height, x, y, r, g, b);
    }

    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static bool SavePetDeployCalibrationOverlayPng(
    CaptureResult capture,
    int bandY,
    int bandHeight,
    int step,
    IReadOnlyList<PetDeployCalibrationPoint> points,
    string path)
{
    if (capture.Width <= 0 || capture.Height <= 0 || capture.Pixels.Length < capture.Width * capture.Height * 4)
        return false;

    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);

    DrawRect(pixels, capture.Width, capture.Height, 0, bandY, capture.Width, bandHeight, 70, 220, 255);
    for (var x = 0; x < capture.Width; x += step)
        DrawLine(pixels, capture.Width, capture.Height, x, bandY, x, Math.Min(capture.Height - 1, bandY + bandHeight - 1), 55, 110, 145);
    for (var y = bandY; y < capture.Height; y += step)
        DrawLine(pixels, capture.Width, capture.Height, 0, y, capture.Width - 1, y, 55, 110, 145);

    var pointIndex = 0;
    foreach (var point in points.Where(p => p.InsideClient))
    {
        pointIndex++;
        if (string.Equals(point.Source, "detected-slot", StringComparison.OrdinalIgnoreCase)
            && point.Width > 0
            && point.Height > 0)
        {
            DrawRect(pixels, capture.Width, capture.Height, point.X - point.Width / 2, point.Y - point.Height / 2, point.Width, point.Height, 255, 220, 70);
            DrawTargetMarker(pixels, capture.Width, capture.Height, point.X, point.Y, 255, 220, 70);
            DrawNumberLabel(pixels, capture.Width, capture.Height, point.X - point.Width / 2, point.Y - point.Height / 2 - 18, pointIndex);
            continue;
        }

        var color = string.Equals(point.Name, "explicit", StringComparison.OrdinalIgnoreCase)
            ? (R: (byte)255, G: (byte)80, B: (byte)80)
            : (R: (byte)80, G: (byte)255, B: (byte)150);
        DrawTargetMarker(pixels, capture.Width, capture.Height, point.X, point.Y, color.R, color.G, color.B);
        DrawNumberLabel(pixels, capture.Width, capture.Height, point.X - 12, point.Y - 30, pointIndex);
    }

    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static bool SavePetDeployBottomBandOverlayPng(
    CaptureResult band,
    int sourceBandY,
    int step,
    IReadOnlyList<PetDeployCalibrationPoint> points,
    string path)
{
    if (band.Width <= 0 || band.Height <= 0 || band.Pixels.Length < band.Width * band.Height * 4)
        return false;

    var pixels = new byte[band.Pixels.Length];
    Array.Copy(band.Pixels, pixels, pixels.Length);

    DrawRect(pixels, band.Width, band.Height, 0, 0, band.Width, band.Height, 70, 220, 255);
    for (var x = 0; x < band.Width; x += step)
        DrawLine(pixels, band.Width, band.Height, x, 0, x, band.Height - 1, 55, 110, 145);
    for (var y = 0; y < band.Height; y += step)
        DrawLine(pixels, band.Width, band.Height, 0, y, band.Width - 1, y, 55, 110, 145);

    var pointIndex = 0;
    foreach (var point in points.Where(p => p.InsideClient))
    {
        pointIndex++;
        var localY = point.Y - sourceBandY;
        if (localY < 0 || localY >= band.Height)
            continue;

        if (string.Equals(point.Source, "detected-slot", StringComparison.OrdinalIgnoreCase)
            && point.Width > 0
            && point.Height > 0)
        {
            DrawRect(pixels, band.Width, band.Height, point.X - point.Width / 2, localY - point.Height / 2, point.Width, point.Height, 255, 220, 70);
            DrawTargetMarker(pixels, band.Width, band.Height, point.X, localY, 255, 220, 70);
            DrawNumberLabel(pixels, band.Width, band.Height, point.X - point.Width / 2, localY - point.Height / 2 - 18, pointIndex);
            continue;
        }

        var color = string.Equals(point.Name, "explicit", StringComparison.OrdinalIgnoreCase)
            ? (R: (byte)255, G: (byte)80, B: (byte)80)
            : (R: (byte)80, G: (byte)255, B: (byte)150);
        DrawTargetMarker(pixels, band.Width, band.Height, point.X, localY, color.R, color.G, color.B);
        DrawNumberLabel(pixels, band.Width, band.Height, point.X - 12, localY - 30, pointIndex);
    }

    return SaveCapturePng(new CaptureResult(band.Width, band.Height, pixels), path);
}

static bool SaveReturnNavigationActionsOverlayPng(CaptureResult capture, IReadOnlyList<ReturnNavigationActionMarker> markers, string path)
{
    if (capture.Width <= 0 || capture.Height <= 0 || capture.Pixels.Length < capture.Width * capture.Height * 4)
        return false;

    var pixels = new byte[capture.Pixels.Length];
    Array.Copy(capture.Pixels, pixels, pixels.Length);

    foreach (var marker in markers)
    {
        if (marker.X < 0 || marker.Y < 0 || marker.X >= capture.Width || marker.Y >= capture.Height)
            continue;

        var (r, g, b) = ReturnNavigationMarkerColor(marker.Source);
        DrawTargetMarker(pixels, capture.Width, capture.Height, marker.X, marker.Y, r, g, b);
    }

    return SaveCapturePng(new CaptureResult(capture.Width, capture.Height, pixels), path);
}

static (byte R, byte G, byte B) ReturnNavigationMarkerColor(string source)
{
    return source switch
    {
        "directional-click" => (70, 255, 170),
        "recorded-click" => (255, 190, 70),
        _ => (255, 90, 70)
    };
}

static (byte R, byte G, byte B) RecoveryActionColor(string key)
{
    return key switch
    {
        "blood-mana" => (70, 220, 255),
        "symbiosis-heal" => (255, 80, 220),
        _ => (255, 255, 255)
    };
}

static (byte R, byte G, byte B) CombatRegionColor(string name)
{
    return name switch
    {
        "target-name" => (255, 90, 255),
        "target-hp" => (255, 70, 70),
        "target-mp" => (80, 140, 255),
        "target-rage" => (255, 220, 60),
        "target-status" => (80, 255, 255),
        "school-marker" => (255, 190, 40),
        "target-portrait" => (255, 90, 220),
        "player-hp" => (70, 255, 90),
        "player-mp" => (70, 220, 255),
        "player-rage" => (255, 220, 60),
        "pet-hp" => (255, 155, 45),
        _ => (255, 255, 255)
    };
}

static void DrawRect(byte[] pixels, int imageWidth, int imageHeight, int x, int y, int width, int height, byte r, byte g, byte b)
{
    if (width <= 0 || height <= 0)
        return;

    DrawLine(pixels, imageWidth, imageHeight, x, y, x + width - 1, y, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x, y + height - 1, x + width - 1, y + height - 1, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x, y, x, y + height - 1, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x + width - 1, y, x + width - 1, y + height - 1, r, g, b);
}

static void DrawTargetMarker(byte[] pixels, int imageWidth, int imageHeight, int x, int y, byte r, byte g, byte b)
{
    const int outer = 12;
    const int inner = 4;

    DrawRect(pixels, imageWidth, imageHeight, x - outer, y - outer, outer * 2 + 1, outer * 2 + 1, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x - outer - 4, y, x - inner, y, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x + inner, y, x + outer + 4, y, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x, y - outer - 4, x, y - inner, r, g, b);
    DrawLine(pixels, imageWidth, imageHeight, x, y + inner, x, y + outer + 4, r, g, b);

    SetPixel(pixels, imageWidth, x, y, 255, 255, 255);
    DrawRect(pixels, imageWidth, imageHeight, x - 1, y - 1, 3, 3, 255, 255, 255);
}

static void DrawNumberLabel(byte[] pixels, int imageWidth, int imageHeight, int x, int y, int number)
{
    var text = number.ToString(CultureInfo.InvariantCulture);
    var width = text.Length * 10 + 5;
    var height = 15;
    x = Math.Clamp(x, 0, Math.Max(0, imageWidth - width - 1));
    y = Math.Clamp(y, 0, Math.Max(0, imageHeight - height - 1));

    FillRectClamped(pixels, imageWidth, imageHeight, x, y, width, height, 0, 0, 0);
    DrawRect(pixels, imageWidth, imageHeight, x, y, width, height, 255, 255, 255);

    var cursor = x + 4;
    foreach (var ch in text)
    {
        DrawDigit(pixels, imageWidth, imageHeight, cursor, y + 3, ch, 255, 255, 255);
        cursor += 10;
    }
}

static void DrawDigit(byte[] pixels, int imageWidth, int imageHeight, int x, int y, char digit, byte r, byte g, byte b)
{
    var pattern = digit switch
    {
        '0' => new[] { "111", "101", "101", "101", "111" },
        '1' => new[] { "010", "110", "010", "010", "111" },
        '2' => new[] { "111", "001", "111", "100", "111" },
        '3' => new[] { "111", "001", "111", "001", "111" },
        '4' => new[] { "101", "101", "111", "001", "001" },
        '5' => new[] { "111", "100", "111", "001", "111" },
        '6' => new[] { "111", "100", "111", "101", "111" },
        '7' => new[] { "111", "001", "010", "010", "010" },
        '8' => new[] { "111", "101", "111", "101", "111" },
        '9' => new[] { "111", "101", "111", "001", "111" },
        _ => Array.Empty<string>()
    };

    const int scale = 2;
    for (var row = 0; row < pattern.Length; row++)
    {
        for (var col = 0; col < pattern[row].Length; col++)
        {
            if (pattern[row][col] != '1')
                continue;
            FillRectClamped(pixels, imageWidth, imageHeight, x + col * scale, y + row * scale, scale, scale, r, g, b);
        }
    }
}

static void FillRectClamped(byte[] pixels, int imageWidth, int imageHeight, int x, int y, int width, int height, byte r, byte g, byte b)
{
    if (width <= 0 || height <= 0)
        return;

    var xStart = Math.Max(0, x);
    var yStart = Math.Max(0, y);
    var xEnd = Math.Min(imageWidth - 1, x + width - 1);
    var yEnd = Math.Min(imageHeight - 1, y + height - 1);
    for (var yy = yStart; yy <= yEnd; yy++)
    {
        for (var xx = xStart; xx <= xEnd; xx++)
            SetPixel(pixels, imageWidth, xx, yy, r, g, b);
    }
}

static void DrawLine(byte[] pixels, int imageWidth, int imageHeight, int x1, int y1, int x2, int y2, byte r, byte g, byte b)
{
    if (x1 == x2)
    {
        var yStart = Math.Max(0, Math.Min(y1, y2));
        var yEnd = Math.Min(imageHeight - 1, Math.Max(y1, y2));
        if (x1 < 0 || x1 >= imageWidth)
            return;

        for (var y = yStart; y <= yEnd; y++)
            SetPixel(pixels, imageWidth, x1, y, r, g, b);
        return;
    }

    if (y1 == y2)
    {
        var xStart = Math.Max(0, Math.Min(x1, x2));
        var xEnd = Math.Min(imageWidth - 1, Math.Max(x1, x2));
        if (y1 < 0 || y1 >= imageHeight)
            return;

        for (var x = xStart; x <= xEnd; x++)
            SetPixel(pixels, imageWidth, x, y1, r, g, b);
    }
}

static void SetPixel(byte[] pixels, int imageWidth, int x, int y, byte r, byte g, byte b)
{
    var p = (y * imageWidth + x) * 4;
    if (p < 0 || p + 3 >= pixels.Length)
        return;

    pixels[p] = b;
    pixels[p + 1] = g;
    pixels[p + 2] = r;
    pixels[p + 3] = 255;
}

static bool HasVisualContent(CaptureResult? capture)
{
    if (capture is null || capture.Pixels.Length < capture.Width * capture.Height * 4)
        return false;

    var min = 255;
    var max = 0;
    var stride = Math.Max(4, capture.Pixels.Length / 256);
    stride -= stride % 4;
    if (stride <= 0)
        stride = 4;

    for (var i = 0; i + 2 < capture.Pixels.Length; i += stride)
    {
        var luma = (capture.Pixels[i] + capture.Pixels[i + 1] + capture.Pixels[i + 2]) / 3;
        min = Math.Min(min, luma);
        max = Math.Max(max, luma);
        if (max - min >= 8)
            return true;
    }

    return false;
}

static bool RunAuthScan()
{
    Console.WriteLine("Sensitive source scan");
    var patterns = new[]
    {
        "xx" + ".dll", "P_UserLogin", "会员账号", "会员密码", "远端授权", "授权失败",
        "账号过期", "注册账户", "账户充值", "账户改密"
    };

    var roots = new[] { "src" };
    var hits = new List<string>();
    foreach (var root in roots.Where(Directory.Exists))
    {
        foreach (var file in Directory.EnumerateFiles(root, "*.*", SearchOption.AllDirectories))
        {
            if (file.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase)
                || file.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}", StringComparison.OrdinalIgnoreCase))
                continue;

            var ext = Path.GetExtension(file);
            if (ext is not ".cs" and not ".xaml" and not ".json")
                continue;

            string text;
            try { text = File.ReadAllText(file); }
            catch { continue; }

            foreach (var pattern in patterns)
            {
                if (text.Contains(pattern, StringComparison.OrdinalIgnoreCase))
                    hits.Add($"{file}: {pattern}");
            }
        }
    }

    foreach (var hit in hits)
        Console.WriteLine(hit);

    if (hits.Count > 0)
    {
        Console.Error.WriteLine("FAIL: src 中出现敏感组件关键词。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunDataImportDiagnostics(string? sourceRootArg, string? importedRootArg)
{
    Console.WriteLine("Data import diagnostics");
    var sourceRoot = string.IsNullOrWhiteSpace(sourceRootArg)
        ? (Environment.GetEnvironmentVariable("TLBB_LEGACY_DATA_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "legacy-data"))
        : sourceRootArg;
    var importedRoot = string.IsNullOrWhiteSpace(importedRootArg)
        ? Path.Combine(Environment.CurrentDirectory, "data", "imported")
        : importedRootArg;

    if (!Directory.Exists(sourceRoot))
    {
        Console.Error.WriteLine($"FAIL: source root not found: {sourceRoot}");
        return false;
    }

    var log = new RuntimeLogService();
    var adapter = new LegacyDataAdapter(log);
    var result = adapter.ImportKnownData(new LegacyImportOptions
    {
        SourceRoot = sourceRoot,
        ImportedRoot = importedRoot,
        Overwrite = true
    });

    if (!File.Exists(result.IndexPath) || !File.Exists(result.InternalSourceIndexPath))
    {
        Console.Error.WriteLine("FAIL: index files were not created.");
        return false;
    }

    var publicText = File.ReadAllText(result.IndexPath);
    var auditText = File.ReadAllText(result.InternalSourceIndexPath);
    var jsonOptions = new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true };
    var publicItems = System.Text.Json.JsonSerializer.Deserialize<List<LegacyImportIndexItem>>(publicText, jsonOptions) ?? new();
    var auditItems = System.Text.Json.JsonSerializer.Deserialize<List<LegacyImportIndexItem>>(auditText, jsonOptions) ?? new();

    var publicLeaksSourceRoot = publicText.Contains(sourceRoot, StringComparison.OrdinalIgnoreCase);
    var publicLeaksKnownSourceName =
        publicText.Contains("蓝钻", StringComparison.OrdinalIgnoreCase)
        || publicText.Contains("UU", StringComparison.OrdinalIgnoreCase)
        || publicText.Contains("xx" + ".dll", StringComparison.OrdinalIgnoreCase)
        || publicText.Contains("授权数据", StringComparison.OrdinalIgnoreCase);
    var auditHasRealPaths = auditItems.Any(i => Path.IsPathRooted(i.SourcePath));
    var auditHasSourceRoot = auditItems.Any(i =>
        i.SourcePath.StartsWith(sourceRoot, StringComparison.OrdinalIgnoreCase)
        || i.SourcePath.StartsWith(Path.Combine("C:\\", "sys"), StringComparison.OrdinalIgnoreCase));
    var runtimeData = new RuntimeDataService(log);
    var summary = runtimeData.ReadPublicIndex();
    var routeResolved = runtimeData.TryResolveFile(Path.Combine("routes", "route-points-a.ini"), out _);
    var configResolved = runtimeData.TryResolveFile(Path.Combine("config-samples", "horse-a.sanitized.ini"), out _);
    var questionDirectoryResolved = runtimeData.TryResolveDirectory("question-bank", out _);
    var dictionaryFiles = runtimeData.EnumerateDictionaryFiles();

    Console.WriteLine($"Source root={sourceRoot}");
    Console.WriteLine($"Imported root={result.ImportedRoot}");
    Console.WriteLine($"Total={result.TotalItems}, copied={result.CopiedItems}, sanitized={result.SanitizedItems}, missing={result.MissingItems}");
    Console.WriteLine($"Public index={result.IndexPath}");
    Console.WriteLine($"Internal index={result.InternalSourceIndexPath}");
    Console.WriteLine($"Public items={publicItems.Count}, audit items={auditItems.Count}");
    Console.WriteLine($"Audit has real paths={auditHasRealPaths}");
    Console.WriteLine($"Runtime data status={summary.Status}");
    Console.WriteLine($"Runtime dictionary files={dictionaryFiles.Count}");

    var ok = result.TotalItems > 0
             && result.CopiedItems > 0
             && result.MissingItems == 0
             && publicItems.Count == auditItems.Count
             && auditHasRealPaths
             && auditHasSourceRoot
             && !publicLeaksSourceRoot
             && !publicLeaksKnownSourceName
             && publicItems.All(i => string.IsNullOrWhiteSpace(i.SourcePath))
             && auditItems.All(i => !string.IsNullOrWhiteSpace(i.SourcePath))
             && summary.Exists
             && summary.Total == publicItems.Count
             && summary.Available > 0
             && routeResolved
             && configResolved
             && questionDirectoryResolved
             && dictionaryFiles.Count > 0;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: data import index split did not meet source/audit requirements.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunAppProfileDiagnostics()
{
    Console.WriteLine("AppProfile diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
