    schoolTask.Current.PlanName = "诊断师门";
    treasureMap.Current.PlanName = "诊断挖图";
    guild.Current.PlanName = "诊断帮贡";
    utility.Current.PlanName = "诊断便捷";
    utility.Current.Steps[0].Enabled = true;
    utility.Current.Steps[0].Hotkey = "F10";
    shout.Current.Enabled = true;
    shout.Current.Messages.Clear();
    shout.Current.Messages.Add(new ShoutMessage { Text = "diagnostic shout", Enabled = true });

    appProfiles.SaveAll(name);
    profiles.Save("方案-诊断回点", "{}");
    profiles.Save("方案-回点点击证据", "{}");
    profiles.Save("diagnostic-loose-profile", "{}");

    var expectedKeys = new[]
    {
        name,
        "return-points-" + name,
        "horse-bandit-" + name,
        "npc-grab-" + name,
        "auto-rebel-" + name,
        "auto-monk-" + name,
        "auto-reconnect-" + name,
        "auto-login-" + name,
        "dungeon-" + name,
        "life-collect-" + name,
        "trade-" + name,
        "material-craft-" + name,
        "school-task-" + name,
        "treasure-map-" + name,
        "guild-contribution-" + name,
        "utility-" + name,
        "shout-" + name
    };

    var savedKeys = profiles.ListProfileNames();
    var missingKeys = expectedKeys.Where(k => !savedKeys.Contains(k, StringComparer.Ordinal)).ToList();
    var publicProfiles = appProfiles.ListProfileNames();
    Console.WriteLine($"Stored keys={string.Join(", ", savedKeys)}");
    Console.WriteLine($"Public profiles={string.Join(", ", publicProfiles)}");

    if (missingKeys.Count > 0)
    {
        Console.Error.WriteLine($"FAIL: 聚合保存缺少内部配置：{string.Join(", ", missingKeys)}");
        return false;
    }

    if (publicProfiles.Count != 1 || publicProfiles[0] != name)
    {
        Console.Error.WriteLine("FAIL: 左侧方案列表不应显示模块内部前缀配置。");
        return false;
