    utility.Current.Steps[0].Hotkey = "";
    shout.Current.Enabled = false;
    shout.Current.Messages.Clear();

    var loaded = appProfiles.LoadAll(name);
    Console.WriteLine($"Loaded modules={string.Join(", ", loaded.LoadedModules)}");
    Console.WriteLine($"Missing modules={string.Join(", ", loaded.MissingModules)}");

    var ok = loaded.GlobalLoaded
             && loaded.MissingModules.Count == 0
             && global.Current.AttackHotkey == "F9"
             && returnPoints.Current.Points.Count == 1
             && horse.Current.SearchHotkey == "6"
             && npc.Current.ScanIntervalMs == 123
             && rebel.Current.SearchHotkey == "F7"
             && monk.Current.SearchHotkey == "F8"
             && reconnect.Current.Enabled
             && reconnect.Current.CheckIntervalMs == 2500
             && autoLogin.Current.Enabled
             && autoLogin.Current.StartDelayMs == 300
             && dungeon.Current.RunCount == 3
             && life.Current.CollectHotkey == "F6"
             && materialCraft.Current.PlanName == "诊断加工"
             && schoolTask.Current.PlanName == "诊断师门"
             && treasureMap.Current.PlanName == "诊断挖图"
             && guild.Current.PlanName == "诊断帮贡"
             && utility.Current.PlanName == "诊断便捷"
             && utility.Current.Steps[0].Hotkey == "F10"
             && shout.Current.Enabled
             && shout.Current.Messages.Count == 1
             && shout.Current.Messages[0].Text == "diagnostic shout";

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: 聚合加载未恢复全部模块配置。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static async Task<bool> RunProfileAutoSaveDiagnostics()
{
    Console.WriteLine("Profile autosave diagnostics");

    var sharedProfiles = new MemoryProfileService();
    var expectedSkillIntervalMs = -1;
    var expectedSkillCondition = SkillCondition.Always;
    using (var provider = BuildProfileAutoSaveProvider(sharedProfiles, includeViewModels: true))
    {
        var vm = provider.GetRequiredService<MainViewModel>();
        var appProfiles = provider.GetRequiredService<IAppProfileService>();
        var home = vm.CurrentDetail as GlobalConfigPageViewModel;
        var profileName = appProfiles.CurrentProfileName ?? vm.SelectedProfile;

        if (home is null || string.IsNullOrWhiteSpace(profileName))
        {
