static async Task<bool> RunProfileWindowAutoLoadDiagnostics()
{
    Console.WriteLine("Profile window autoload diagnostics");

    var sharedProfiles = new MemoryProfileService();
    const string mappedProfile = "窗口方案-A";
    const string otherProfile = "窗口方案-B";
    var hwnd = new nint(0x5511);

    var firstBinding = new FakeWindowBindingService();
    firstBinding.TitleOverride = "《新天龙八部》 0.08.1509 (原始一区:江山如画)";
    firstBinding.ProcessPathOverride = @"C:\Game\TLBB\Bin\Game.exe";
    using (var firstProvider = BuildProfileAutoSaveProvider(sharedProfiles, includeViewModels: true, firstBinding))
    {
        var vm = firstProvider.GetRequiredService<MainViewModel>();
        var appProfiles = firstProvider.GetRequiredService<IAppProfileService>();
        var global = firstProvider.GetRequiredService<IGlobalConfigService>();

        global.Current.AttackHotkey = "Q";
        global.Current.Targeting.AcquireHotkey = "G";
        appProfiles.SaveAll(mappedProfile);
        vm.SelectedProfile = mappedProfile;
        firstBinding.BindByHandle(hwnd);
        if (firstBinding.Current is not null)
            appProfiles.RememberWindowProfile(firstBinding.Current, mappedProfile);
        await Task.Delay(50);
    }

    using (var secondProvider = BuildProfileAutoSaveProvider(sharedProfiles, includeViewModels: false))
    {
        var appProfiles = secondProvider.GetRequiredService<IAppProfileService>();
        var global = secondProvider.GetRequiredService<IGlobalConfigService>();

        global.Current.AttackHotkey = "Z";
        global.Current.Targeting.AcquireHotkey = "X";
        appProfiles.SaveAll(otherProfile);
    }

    var unmappedBinding = new FakeWindowBindingService();
    unmappedBinding.TitleOverride = "《新天龙八部》 0.08.1707 (另一个区:未记住角色)";
    unmappedBinding.ProcessPathOverride = @"C:\Game\TLBB\Bin\Game.exe";
    using (var unmappedProvider = BuildProfileAutoSaveProvider(sharedProfiles, includeViewModels: true, unmappedBinding))
    {
        var appProfiles = unmappedProvider.GetRequiredService<IAppProfileService>();
        unmappedBinding.BindByHandle(new nint(0x6611));
        await Task.Delay(50);
        var unexpected = unmappedBinding.Current is null ? null : appProfiles.ResolveProfileForWindow(unmappedBinding.Current);
        if (!string.IsNullOrWhiteSpace(unexpected))
        {
            Console.Error.WriteLine($"FAIL: 未记住窗口被自动映射到了方案：{unexpected}");
            return false;
        }
    }

    var secondBinding = new FakeWindowBindingService();
    secondBinding.TitleOverride = "《新天龙八部》 0.08.1707 (原始一区:江山如画)";
    secondBinding.ProcessPathOverride = @"C:\Game\TLBB\Bin\Game.exe";
    using var verifyProvider = BuildProfileAutoSaveProvider(sharedProfiles, includeViewModels: true, secondBinding);
    var verifyVm = verifyProvider.GetRequiredService<MainViewModel>();
    var verifyProfiles = verifyProvider.GetRequiredService<IAppProfileService>();
    var verifyGlobal = verifyProvider.GetRequiredService<IGlobalConfigService>();

    var beforeProfile = verifyProfiles.CurrentProfileName;
    var beforeAttack = verifyGlobal.Current.AttackHotkey;
    secondBinding.BindByHandle(hwnd);
    await Task.Delay(50);

    Console.WriteLine($"Before bind profile={beforeProfile}, attack={beforeAttack}");
    Console.WriteLine($"After bind profile={verifyProfiles.CurrentProfileName}, selected={verifyVm.SelectedProfile}, attack={verifyGlobal.Current.AttackHotkey}, acquire={verifyGlobal.Current.Targeting.AcquireHotkey}");
    Console.WriteLine($"Version-title changed: {firstBinding.TitleOverride} -> {secondBinding.TitleOverride}");

    var ok = beforeProfile == otherProfile
             && beforeAttack == "Z"
             && verifyProfiles.CurrentProfileName == mappedProfile
             && verifyVm.SelectedProfile == mappedProfile
             && verifyGlobal.Current.AttackHotkey == "Q"
             && verifyGlobal.Current.Targeting.AcquireHotkey == "G";

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: 绑定同一窗口后未自动加载已记住的方案。");
        return false;
    }

    const string sameWindowProfileA = "同标题多开-A";
    const string sameWindowProfileB = "同标题多开-B";
    var sameWindowA = new BoundGameWindow
    {
        Hwnd = new nint(0x7711),
        Pid = 17711,
        Title = "《新天龙八部》 同一区服",
        ProcessName = "Game",
        ProcessPath = @"C:\Game\TLBB\Bin64\Game.exe",
        Bitness = ClientBitness.X64,
        ClientType = ClientType.Tlbb64,
        ClientWidth = 1920,
        ClientHeight = 1080,
        RunState = RunState.Ready
    };
    var sameWindowB = new BoundGameWindow
    {
        Hwnd = new nint(0x7722),
        Pid = 17722,
        Title = sameWindowA.Title,
        ProcessName = sameWindowA.ProcessName,
        ProcessPath = sameWindowA.ProcessPath,
        Bitness = sameWindowA.Bitness,
        ClientType = sameWindowA.ClientType,
        ClientWidth = sameWindowA.ClientWidth,
        ClientHeight = sameWindowA.ClientHeight,
        RunState = RunState.Ready
    };

    verifyProfiles.SaveAll(sameWindowProfileA);
    verifyProfiles.RememberWindowProfile(sameWindowA, sameWindowProfileA);
    verifyProfiles.SaveAll(sameWindowProfileB);
    verifyProfiles.RememberWindowProfile(sameWindowB, sameWindowProfileB);
    var resolvedA = verifyProfiles.ResolveProfileForWindow(sameWindowA);
    var resolvedB = verifyProfiles.ResolveProfileForWindow(sameWindowB);
    var sameTitleMultiOpenOk = resolvedA == sameWindowProfileA && resolvedB == sameWindowProfileB;
    Console.WriteLine($"Same-title multi-open A={resolvedA}, B={resolvedB} => {(sameTitleMultiOpenOk ? "PASS" : "FAIL")}");

    if (!sameTitleMultiOpenOk)
    {
        Console.Error.WriteLine("FAIL: 同路径同标题的多开窗口在当前会话中发生方案串用。");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunProfileHealthDiagnostics(string[] args)
{
    Console.WriteLine("Profile health diagnostics");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var init = provider.GetRequiredService<IAppInitService>();
    init.Initialize();

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var global = provider.GetRequiredService<IGlobalConfigService>();
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var lastProfile = appProfiles.CurrentProfileName;
    var liveWindow = TryBindFirstGameWindow(provider);
    var resolvedProfile = liveWindow is null ? null : appProfiles.ResolveProfileForWindow(liveWindow);
    var availableProfiles = appProfiles.ListProfileNames().ToArray();
    var profileName = ResolveHealthProfileName(requestedProfile, resolvedProfile, lastProfile, availableProfiles, out var profileSource);

    var errors = new List<string>();
    var warnings = new List<string>();
    var infos = new List<string>();
    var loaded = false;
    AppProfileLoadResult? profileLoad = null;
    if (string.IsNullOrWhiteSpace(profileName))
    {
        errors.Add("没有可用用户方案。");
    }
    else
    {
        profileLoad = appProfiles.LoadAll(profileName);
        loaded = profileLoad.GlobalLoaded;
        if (!loaded)
            errors.Add($"当前方案无法加载：{profileName}");
        if (profileLoad.MissingModules.Count > 0)
            infos.Add($"方案部分模块未配置：{string.Join("、", profileLoad.MissingModules)}。");
    }

    var cfg = global.Current;
    if (!string.IsNullOrWhiteSpace(requestedProfile))
        infos.Add($"使用显式指定方案：{profileName}。");
    else if (string.Equals(profileSource, "window-map", StringComparison.Ordinal))
        infos.Add($"上次方案不可用或不适合当前窗口，已按绑定窗口映射检查方案：{profileName}。");
    else if (string.Equals(profileSource, "last", StringComparison.Ordinal))
        infos.Add($"使用上次方案：{profileName}。");
    else if (string.Equals(profileSource, "first", StringComparison.Ordinal))
        infos.Add($"使用首个可用方案：{profileName}。");

    if (!string.IsNullOrWhiteSpace(lastProfile)
        && !availableProfiles.Contains(lastProfile, StringComparer.OrdinalIgnoreCase))
    {
        warnings.Add($"上次方案不存在：{lastProfile}。");
    }

    var readiness = provider.GetRequiredService<IMainlineReadinessService>()
        .Inspect(cfg, liveWindow, includeReturnPointReadiness: true, includeLiveReturnRecognition: true);
    var readinessItems = readiness.Items
        .Select(item => new
        {
            severity = item.Severity.ToString(),
            item.Feature,
            item.Message,
            item.ActionArea,
            item.Action,
            item.BlocksStart
        })
        .ToArray();
    foreach (var item in readiness.Infos)
        infos.Add(FormatHealthReadinessItem(item));
    foreach (var item in readiness.Warnings)
        warnings.Add(FormatHealthReadinessItem(item));
    foreach (var item in readiness.Errors)
        errors.Add(FormatHealthReadinessItem(item));

    var pillCooldown = ResolvePreviewPillCooldownMs(cfg);

    if (liveWindow is null)
    {
        infos.Add("未检测到正在运行的 Game.exe，跳过窗口映射检查。");
    }
    else if (string.IsNullOrWhiteSpace(resolvedProfile))
    {
        warnings.Add($"当前 Game.exe 窗口未映射到任何方案：{liveWindow.Title}");
    }
    else if (!string.Equals(resolvedProfile, profileName, StringComparison.Ordinal))
    {
        warnings.Add($"当前 Game.exe 窗口映射到 {resolvedProfile}，但当前方案是 {profileName}。绑定后会自动切换。");
    }
    else
    {
        infos.Add($"当前 Game.exe 窗口可解析到当前方案：{resolvedProfile}。");
    }

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "profile-health", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "profile-health.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        profile = new
        {
            name = profileName,
            source = profileSource,
            requestedProfile,
            lastProfile,
            loaded,
            loadedModules = profileLoad?.LoadedModules ?? Array.Empty<string>(),
            missingModules = profileLoad?.MissingModules ?? Array.Empty<string>(),
            profilesRoot = init.Paths.Profiles
        },
        window = liveWindow is null
            ? null
            : new
            {
                liveWindow.Pid,
                liveWindow.Title,
                liveWindow.ProcessPath,
                bitness = liveWindow.Bitness.ToString(),
                liveWindow.ClientSizeText,
                resolvedProfile
            },
        global = new
        {
            cfg.SchemaVersion,
            cfg.InputDispatchMode,
            cfg.CombatBackendPreference,
            playerHpRegion = cfg.CombatRecognition.PlayerHp,
            playerMpRegion = cfg.CombatRecognition.PlayerMp,
            acquireHotkey = cfg.Targeting.AcquireHotkey,
            cfg.AttackHotkey,
            cfg.HealHotkey,
            cfg.ManaHotkey,
            bloodManaMode = cfg.BloodManaActivationMode.ToString(),
            bloodManaHotkey = EffectivePreviewBloodManaHotkey(cfg),
            symbiosisMode = cfg.SymbiosisHealActivationMode.ToString(),
            cfg.SymbiosisHealHotkey,
            petFoodHotkey = EffectivePreviewPetFoodHotkey(cfg),
            petDeployMode = cfg.PetDeployActivationMode.ToString(),
            cfg.PetDeployHotkey,
            cfg.PetDeployClickX,
            cfg.PetDeployClickBottomOffset,
            cfg.HpThresholdPct,
            cfg.MpThresholdPct,
            cfg.PetFoodThresholdPct,
            cfg.BloodManaThresholdPct,
            cfg.SymbiosisHealThresholdPct,
            pillCooldownMs = pillCooldown,
            petFoodCooldownMs = Math.Max(10000, cfg.PetFoodCooldownMs),
            bloodManaCooldownMs = Math.Max(30000, cfg.BloodManaCooldownMs),
            symbiosisHealCooldownMs = Math.Max(30000, cfg.SymbiosisHealCooldownMs)
        },
        readinessItems,
        errors,
        warnings,
        infos
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<none>" : profileName)}, loaded={loaded}");
    Console.WriteLine($"Acquire={cfg.Targeting.AcquireHotkey}, Attack={cfg.AttackHotkey}, Heal={cfg.HealHotkey}, Mana={cfg.ManaHotkey}");
    var petDeployAction = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
        ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
        : $"Hotkey/{cfg.PetDeployHotkey}";
    Console.WriteLine($"BloodMana={cfg.BloodManaActivationMode}/{EffectivePreviewBloodManaHotkey(cfg)}, Symbiosis={cfg.SymbiosisHealActivationMode}/{cfg.SymbiosisHealHotkey}, PetFood={EffectivePreviewPetFoodHotkey(cfg)}, PetDeploy={petDeployAction}");
    foreach (var info in infos)
        Console.WriteLine($"INFO: {info}");
    foreach (var warning in warnings)
        Console.WriteLine($"WARN: {warning}");
    foreach (var error in errors)
        Console.Error.WriteLine($"ERROR: {error}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = errors.Count == 0 && File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static bool RunProfileRecoveryBootstrapDiagnostics(string[] args)
{
    Console.WriteLine("Profile recovery bootstrap diagnostics");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var init = provider.GetRequiredService<IAppInitService>();
    init.Initialize();

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var global = provider.GetRequiredService<IGlobalConfigService>();
    var input = provider.GetRequiredService<IInputService>();
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var commit = HasFlag(args, "--commit");
    var force = HasFlag(args, "--force");
    var lastProfile = appProfiles.CurrentProfileName;
    var liveWindow = TryBindFirstGameWindow(provider);
    var resolvedProfile = liveWindow is null ? null : appProfiles.ResolveProfileForWindow(liveWindow);
    var availableProfiles = appProfiles.ListProfileNames().ToArray();
    var profileName = ResolveHealthProfileName(requestedProfile, resolvedProfile, lastProfile, availableProfiles, out var profileSource);

    var errors = new List<string>();
    var warnings = new List<string>();
    var changes = new List<object>();

    if (string.IsNullOrWhiteSpace(profileName))
    {
        errors.Add("没有可用用户方案。");
    }
    else
    {
        var loaded = appProfiles.LoadAll(profileName);
        if (!loaded.GlobalLoaded)
            errors.Add($"当前方案无法加载：{profileName}");
    }

    var cfg = global.Current;
    var reserved = BuildReservedHotkeys(cfg);
    var explicitHeal = ReadOption(args, "--heal");
    var explicitMana = ReadOption(args, "--mana");
    var explicitPetFood = ReadOption(args, "--pet-food");
    var explicitPetDeployHotkey = ReadOption(args, "--pet-deploy-hotkey");
    var explicitPetDeployClick = ReadOption(args, "--pet-deploy-click");

    PlanHotkey(
        "HealHotkey",
        "吃药回血",
        cfg.HealHotkey,
        explicitHeal,
        "F8",
        reserved,
        force,
        input,
        errors,
        changes,
        value => cfg.HealHotkey = value);

    PlanHotkey(
        "ManaHotkey",
        "吃药回蓝",
        cfg.ManaHotkey,
        explicitMana,
        "F9",
        reserved,
        force,
        input,
        errors,
        changes,
        value => cfg.ManaHotkey = value);

    PlanHotkey(
        "PetFoodHotkey",
        "宠粮回血",
        EffectivePreviewPetFoodHotkey(cfg),
        explicitPetFood,
        "F10",
        reserved,
        force,
        input,
        errors,
        changes,
        value => cfg.PetFoodHotkey = value);

    var petDeployMissing = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
        ? cfg.PetDeployClickX <= 0 || cfg.PetDeployClickBottomOffset <= 0
        : string.IsNullOrWhiteSpace(cfg.PetDeployHotkey);

    if (force || petDeployMissing)
    {
        if (!string.IsNullOrWhiteSpace(explicitPetDeployClick))
        {
            if (!TryParseClientBottomClick(explicitPetDeployClick, out var x, out var bottom))
            {
                errors.Add($"宠物出战点击点格式无效：{explicitPetDeployClick}，应为 x,bottom。");
            }
            else
            {
                var before = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
                    ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
                    : $"Hotkey/{cfg.PetDeployHotkey}";
                changes.Add(new
                {
                    field = "PetDeploy",
                    feature = "宠物出战",
                    before,
                    after = $"ClientClick/{x},bottom-{bottom}",
                    willChange = true,
                    reason = "使用显式点击点"
                });
                if (errors.Count == 0)
                {
                    cfg.PetDeployActivationMode = PetSkillActivationMode.ClientClick;
                    cfg.PetDeployClickX = x;
                    cfg.PetDeployClickBottomOffset = bottom;
                    cfg.PetDeployHotkey = "";
                }
            }
        }
        else
        {
            var petDeploy = explicitPetDeployHotkey ?? ChooseFreeHotkey("F6", reserved);
            if (string.IsNullOrWhiteSpace(petDeploy))
            {
                changes.Add(new
                {
                    field = "PetDeploy",
                    feature = "宠物出战",
                    before = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
                        ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
                        : $"Hotkey/{cfg.PetDeployHotkey}",
                    after = "",
                    willChange = false,
                    reason = "没有空闲 F1-F10 热键"
                });
                var message = "宠物出战没有可用默认热键；请显式指定 --pet-deploy-hotkey 或 --pet-deploy-click。";
                warnings.Add(message);
            }
            else if (!ValidateBootstrapHotkey(input, "宠物出战", petDeploy, errors))
            {
                // Validation already recorded the reason.
            }
            else
            {
                reserved.Add(NormalizeHotkeyForSet(petDeploy));
                var before = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
                    ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
                    : $"Hotkey/{cfg.PetDeployHotkey}";
                changes.Add(new
                {
                    field = "PetDeploy",
                    feature = "宠物出战",
                    before,
                    after = $"Hotkey/{petDeploy}",
                    willChange = true,
                    reason = explicitPetDeployHotkey is null ? "自动选择未占用热键" : "使用显式热键"
                });
                if (errors.Count == 0)
                {
                    cfg.PetDeployActivationMode = PetSkillActivationMode.Hotkey;
                    cfg.PetDeployHotkey = petDeploy;
                    cfg.PetDeployClickX = 0;
                    cfg.PetDeployClickBottomOffset = 0;
                }
            }
        }
    }
    else
    {
        changes.Add(new
        {
            field = "PetDeploy",
            feature = "宠物出战",
            before = cfg.PetDeployActivationMode == PetSkillActivationMode.ClientClick
                ? $"ClientClick/{cfg.PetDeployClickX},bottom-{cfg.PetDeployClickBottomOffset}"
                : $"Hotkey/{cfg.PetDeployHotkey}",
            after = "",
            willChange = false,
            reason = "已配置，未指定 --force"
        });
    }

    if (commit && errors.Count == 0 && !string.IsNullOrWhiteSpace(profileName))
    {
        global.Save(profileName);
    }
    else if (!commit)
    {
        warnings.Add("预览模式：未写入方案；确认后追加 --commit 才会保存。");
    }

    var readiness = provider.GetRequiredService<IMainlineReadinessService>()
        .Inspect(cfg, liveWindow, includeReturnPointReadiness: true, includeLiveReturnRecognition: true);

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "profile-recovery-bootstrap", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "profile-recovery-bootstrap.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        committed = commit && errors.Count == 0,
        commitRequested = commit,
        force,
        profile = new { name = profileName, source = profileSource, requestedProfile, lastProfile },
        window = liveWindow is null
            ? null
            : new
            {
                liveWindow.Pid,
                liveWindow.Title,
                liveWindow.ProcessPath,
                bitness = liveWindow.Bitness.ToString(),
                liveWindow.ClientSizeText,
                resolvedProfile
            },
        changes,
        readiness = readiness.Items.Select(item => new
        {
            severity = item.Severity.ToString(),
            item.Feature,
            item.Message,
            item.ActionArea,
            item.Action,
            item.BlocksStart
        }).ToArray(),
        errors,
        warnings
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<none>" : profileName)}, source={profileSource}, commit={commit}, force={force}");
    foreach (var change in changes)
        Console.WriteLine($"CHANGE: {System.Text.Json.JsonSerializer.Serialize(change, JsonOptions())}");
    foreach (var warning in warnings)
        Console.WriteLine($"WARN: {warning}");
    foreach (var error in errors)
        Console.Error.WriteLine($"ERROR: {error}");
    Console.WriteLine($"ReadinessErrors={readiness.Errors.Count}, ReadinessWarnings={readiness.Warnings.Count}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = errors.Count == 0 && File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static HashSet<string> BuildReservedHotkeys(GlobalConfig cfg)
{
    var reserved = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    Add(cfg.AttackHotkey);
    Add(cfg.Targeting.AcquireHotkey);
    Add(cfg.Targeting.ProtectedTargetClearHotkey);
    Add(cfg.GameBuiltInHangSwitchMode == GameBuiltInHangSwitchMode.Hotkey ? cfg.GameBuiltInHangSwitchHotkey : "");
    foreach (var skill in cfg.Skills.Where(s => s.Enabled))
        Add(skill.Hotkey);

    return reserved;

    void Add(string? hotkey)
    {
        var normalized = NormalizeHotkeyForSet(hotkey);
        if (!string.IsNullOrWhiteSpace(normalized))
            reserved.Add(normalized);
    }
}

static void PlanHotkey(
    string field,
    string feature,
    string currentValue,
    string? explicitValue,
    string desiredDefault,
    HashSet<string> reserved,
    bool force,
    IInputService input,
    List<string> errors,
    List<object> changes,
    Action<string> apply)
{
    if (!force && !string.IsNullOrWhiteSpace(currentValue))
    {
        reserved.Add(NormalizeHotkeyForSet(currentValue));
        changes.Add(new
        {
            field,
            feature,
            before = currentValue,
            after = "",
            willChange = false,
            reason = "已配置，未指定 --force"
        });
        return;
    }

    var next = explicitValue ?? ChooseFreeHotkey(desiredDefault, reserved);
    if (string.IsNullOrWhiteSpace(next))
    {
        errors.Add($"{feature} 没有可用默认热键；请显式指定 --{ToKebabFieldName(field)}。");
        return;
    }

    if (!ValidateBootstrapHotkey(input, feature, next, errors))
        return;

    var normalized = NormalizeHotkeyForSet(next);
    if (reserved.Contains(normalized) && !string.Equals(normalized, NormalizeHotkeyForSet(currentValue), StringComparison.OrdinalIgnoreCase))
    {
        errors.Add($"{feature} 热键冲突：{next} 已被其他关键动作占用。");
        return;
    }

    reserved.Add(normalized);
    changes.Add(new
    {
        field,
        feature,
        before = currentValue,
        after = next,
        willChange = true,
        reason = explicitValue is null ? "自动选择未占用热键" : "使用显式热键"
    });
    apply(next);
}

static string ChooseFreeHotkey(string desiredDefault, HashSet<string> reserved)
{
    var candidates = new[]
    {
        desiredDefault,
        "F10",
        "F9",
        "F8",
        "F6",
        "F5",
        "F4",
        "F3",
        "F2"
    };

    return candidates
        .Select(NormalizeHotkeyForSet)
        .Where(candidate => !string.IsNullOrWhiteSpace(candidate))
        .FirstOrDefault(candidate => !reserved.Contains(candidate)) ?? "";
}

static bool ValidateBootstrapHotkey(IInputService input, string feature, string hotkey, List<string> errors)
{
    if (string.IsNullOrWhiteSpace(hotkey))
    {
        errors.Add($"{feature} 热键为空。");
        return false;
    }

    if (!input.TryParseHotkey(hotkey, out var error))
    {
        errors.Add($"{feature} 热键无效：{hotkey} | {error}");
        return false;
    }

    return true;
}

static string NormalizeHotkeyForSet(string? hotkey) =>
    (hotkey ?? string.Empty).Trim().ToUpperInvariant();

static string ToKebabFieldName(string field)
{
    var builder = new StringBuilder();
    foreach (var ch in field)
    {
        if (char.IsUpper(ch) && builder.Length > 0)
            builder.Append('-');
        builder.Append(char.ToLowerInvariant(ch));
    }

    return builder.ToString().Replace("-hotkey", "", StringComparison.OrdinalIgnoreCase);
}

static bool TryParseClientBottomClick(string value, out int x, out int bottom)
{
    x = 0;
    bottom = 0;
    var parts = value.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    return parts.Length == 2
           && int.TryParse(parts[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out x)
           && int.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out bottom)
           && x > 0
           && bottom > 0;
}

static IEnumerable<PetDeployCalibrationPoint> BuildPetDeployCalibrationSuggestions(int clientWidth, int clientHeight)
{
    var ratios = new[]
    {
        0.36,
        0.405,
        0.43,
        0.455,
        0.48,
        0.505,
        0.53,
        0.555,
        0.58,
        0.605
    };
    var bottomRatios = new[] { 0.055, 0.075, 0.095, 0.12 };
    var index = 1;
    foreach (var bottomRatio in bottomRatios)
    {
        foreach (var ratio in ratios)
        {
            var x = (int)Math.Round(clientWidth * ratio);
            var bottom = (int)Math.Round(clientHeight * bottomRatio);
            yield return BuildPetDeployPoint($"p{index:00}", x, bottom, clientWidth, clientHeight);
            index++;
        }
    }
}

static List<PetDeployCalibrationPoint> BuildPetDeploySlotCandidates(
    CaptureResult band,
    int sourceBandY,
    int clientWidth,
    int clientHeight,
    int maxCandidates)
{
    const int slotSize = 36;
    const int scanStep = 6;
    var candidates = new List<(int X, int Y, double Score)>();
    var minX = (int)Math.Round(clientWidth * 0.22);
    var maxX = (int)Math.Round(clientWidth * 0.74);
    var minY = Math.Max(0, (int)Math.Round(band.Height * 0.20));
    var maxY = Math.Max(minY, band.Height - slotSize - 1);

    for (var y = minY; y <= maxY; y += scanStep)
    {
        for (var x = minX; x <= Math.Min(maxX, band.Width - slotSize - 1); x += scanStep)
        {
            var score = ScoreActionSlotWindow(band, x, y, slotSize, slotSize);
            if (score >= 0.34)
                candidates.Add((x + slotSize / 2, sourceBandY + y + slotSize / 2, score));
        }
    }

    var result = new List<PetDeployCalibrationPoint>();
    foreach (var item in candidates
                 .OrderByDescending(c => c.Score)
                 .ThenBy(c => c.Y)
                 .ThenBy(c => c.X))
    {
        if (result.Any(existing => DistanceSquared(existing.X, existing.Y, item.X, item.Y) < 26 * 26))
            continue;

        result.Add(new PetDeployCalibrationPoint(
            $"slot{result.Count + 1:00}",
            item.X,
            item.Y,
            Math.Max(1, clientHeight - item.Y),
            item.X >= 0 && item.X < clientWidth && item.Y >= 0 && item.Y < clientHeight,
            "detected-slot",
            Math.Round(item.Score, 4),
            slotSize,
            slotSize));

        if (result.Count >= maxCandidates)
            break;
    }

    return result
        .OrderBy(p => p.Y)
        .ThenBy(p => p.X)
        .ToList();
}

static double ScoreActionSlotWindow(CaptureResult image, int x, int y, int width, int height)
{
    var total = 0;
    var nonBlue = 0;
    var dark = 0;
    var gold = 0;
    var edge = 0;
    for (var yy = y; yy < y + height && yy < image.Height; yy++)
    {
        for (var xx = x; xx < x + width && xx < image.Width; xx++)
        {
            ReadBgr(image, xx, yy, out var b, out var g, out var r);
            total++;
            if (!LooksLikeBlueSceneBackground(b, g, r))
                nonBlue++;
            if (r < 55 && g < 55 && b < 70)
                dark++;
            if (r > 120 && g > 80 && b < 95 && r >= g)
                gold++;
            if (xx + 1 < image.Width && yy + 1 < image.Height)
            {
                ReadBgr(image, xx + 1, yy, out var b2, out var g2, out var r2);
                ReadBgr(image, xx, yy + 1, out var b3, out var g3, out var r3);
                var l = (r + g + b) / 3;
                var l2 = (r2 + g2 + b2) / 3;
                var l3 = (r3 + g3 + b3) / 3;
                if (Math.Abs(l - l2) + Math.Abs(l - l3) > 70)
                    edge++;
            }
        }
    }

    if (total == 0)
        return 0;

    var nonBlueRatio = nonBlue / (double)total;
    var darkRatio = dark / (double)total;
    var goldRatio = gold / (double)total;
    var edgeRatio = edge / (double)total;

    // Slot candidates usually have dark framed interiors, gold borders and dense icon edges.
    return nonBlueRatio * 0.38
           + darkRatio * 0.24
           + Math.Min(0.25, goldRatio * 1.8)
           + Math.Min(0.20, edgeRatio * 0.9);
}

static bool LooksLikeBlueSceneBackground(byte b, byte g, byte r) =>
    b > 115 && b > r + 25 && b >= g - 5;

static void ReadBgr(CaptureResult image, int x, int y, out byte b, out byte g, out byte r)
{
    var p = (y * image.Width + x) * 4;
    b = image.Pixels[p];
    g = image.Pixels[p + 1];
    r = image.Pixels[p + 2];
}

static int DistanceSquared(int x1, int y1, int x2, int y2)
{
    var dx = x1 - x2;
    var dy = y1 - y2;
    return dx * dx + dy * dy;
}

static PetDeployCalibrationPoint BuildPetDeployPoint(string name, int x, int bottom, int clientWidth, int clientHeight)
{
    var y = clientHeight - bottom;
    return new PetDeployCalibrationPoint(
        name,
        x,
        y,
        bottom,
        x >= 0 && x < clientWidth && y >= 0 && y < clientHeight && bottom > 0,
        "ratio");
}

static string FormatHealthReadinessItem(MainlineReadinessItem item)
{
    var text = $"{item.Feature}：{item.Message}";
    if (!string.IsNullOrWhiteSpace(item.ActionArea) || !string.IsNullOrWhiteSpace(item.Action))
    {
        var area = string.IsNullOrWhiteSpace(item.ActionArea) ? "配置" : item.ActionArea;
        var action = string.IsNullOrWhiteSpace(item.Action) ? "按提示处理。" : item.Action;
        text = $"{text} 处理：{area} - {action}";
    }

    return text;
}

static string? ResolveHealthProfileName(
    string? requestedProfile,
    string? resolvedProfile,
    string? lastProfile,
    IReadOnlyCollection<string> availableProfiles,
    out string source)
{
    source = "none";

    if (!string.IsNullOrWhiteSpace(requestedProfile))
    {
        source = "requested";
        return requestedProfile;
    }

    if (!string.IsNullOrWhiteSpace(resolvedProfile)
        && availableProfiles.Contains(resolvedProfile, StringComparer.OrdinalIgnoreCase))
    {
        source = "window-map";
        return resolvedProfile;
    }

    if (!string.IsNullOrWhiteSpace(lastProfile)
        && availableProfiles.Contains(lastProfile, StringComparer.OrdinalIgnoreCase))
    {
        source = "last";
        return lastProfile;
    }

    var first = availableProfiles.FirstOrDefault();
    if (!string.IsNullOrWhiteSpace(first))
        source = "first";
    return first;
}

static bool RunReturnProfileAuditDiagnostics(string[] args)
{
    Console.WriteLine("Return profile audit diagnostics");

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    var init = provider.GetRequiredService<IAppInitService>();
    init.Initialize();

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var requestedProfile = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    var lastProfile = appProfiles.CurrentProfileName;
    var liveWindow = TryBindFirstGameWindow(provider);
    var resolvedProfile = liveWindow is null ? null : appProfiles.ResolveProfileForWindow(liveWindow);
    var availableProfiles = appProfiles.ListProfileNames().ToArray();
    var profileName = ResolveHealthProfileName(requestedProfile, resolvedProfile, lastProfile, availableProfiles, out var profileSource);

    AppProfileLoadResult? profileLoad = null;
    var errors = new List<string>();
    if (string.IsNullOrWhiteSpace(profileName))
    {
        errors.Add("没有可用用户方案。");
    }
    else
    {
        profileLoad = appProfiles.LoadAll(profileName);
        if (!profileLoad.GlobalLoaded && profileLoad.LoadedModules.Count == 0)
            errors.Add($"当前方案无法加载：{profileName}");
    }

    var config = returnPoints.Current;
    var readiness = provider.GetRequiredService<IReturnPointReadinessService>().Inspect(includeLiveRecognition: true);
    var sceneMap = readiness.MapName;

    var slotRows = new[]
    {
        BuildReturnAuditSlot(ReturnNavigationSlot.FixedFarm, config.EnableFixedFarmReturn, config.ReturnNavigation, config, readiness, sceneMap, profileName ?? ""),
        BuildReturnAuditSlot(ReturnNavigationSlot.EarthSpirit, config.EnableEarthSpiritReturn, config.EarthSpiritNavigation, config, readiness, sceneMap, profileName ?? ""),
        BuildReturnAuditSlot(ReturnNavigationSlot.StuckRecovery, config.EnableStuckRecovery, config.StuckRecoveryNavigation, config, readiness, sceneMap, profileName ?? ""),
        BuildReturnAuditSlot(ReturnNavigationSlot.DeathReturn, config.EnableDeathReturn, config.DeathReturnNavigation, config, readiness, sceneMap, profileName ?? "")
    };

    var points = config.Points
        .Select(p => new
        {
            p.Id,
            p.MapName,
            p.X,
            p.Y,
            p.Label,
            kind = p.Kind.ToString()
        })
        .ToArray();

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-profile-audit", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, "return-profile-audit.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = "return-profile-audit-readonly-no-input",
        safety = new
        {
            sendsInput = false,
            writesProfile = false,
            writesOriginalData = false
        },
        profile = new
        {
            name = profileName,
            source = profileSource,
            requestedProfile,
            lastProfile,
            loadedModules = profileLoad?.LoadedModules ?? Array.Empty<string>(),
            missingModules = profileLoad?.MissingModules ?? Array.Empty<string>(),
            profilesRoot = init.Paths.Profiles
        },
        window = liveWindow is null
            ? null
            : new
            {
                liveWindow.Pid,
                liveWindow.Title,
                liveWindow.ProcessPath,
                bitness = liveWindow.Bitness.ToString(),
                liveWindow.ClientSizeText,
                resolvedProfile
            },
        scene = new
        {
            readiness.MapName,
            readiness.X,
            readiness.Y,
            readiness.SceneSummary
        },
        settings = new
        {
            config.ArrivalDistance,
            config.CheckIntervalMs,
            config.StuckTimeoutMs,
            config.ReturnRetryLimit,
            config.ReturnTravelWaitMs
        },
        points,
        slots = slotRows,
        readiness = new
        {
            level = readiness.Level.ToString(),
            readiness.Summary,
            readiness.NextAction
        },
        errors
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={(string.IsNullOrWhiteSpace(profileName) ? "<none>" : profileName)}, source={profileSource}, loadedModules={profileLoad?.LoadedModules.Count ?? 0}");
    Console.WriteLine($"Window={(liveWindow is null ? "<none>" : $"{liveWindow.Pid}/{liveWindow.Bitness}/{liveWindow.ClientSizeText}")}");
    Console.WriteLine($"Scene={readiness.SceneSummary}");
    Console.WriteLine($"Readiness={readiness.Level}, {readiness.Summary}");
    Console.WriteLine($"NextAction={readiness.NextAction}");
    Console.WriteLine($"Points={config.Points.Count}, arrivalDistance={config.ArrivalDistance}, checkIntervalMs={config.CheckIntervalMs}");
    foreach (var row in slotRows)
    {
        Console.WriteLine($"Slot={row.slotName}, enabled={row.enabled}, level={row.level}, points={row.pointCount}, sameMap={row.sameMapPointCount}, nav={row.navigation.mode}, navReady={row.navigation.configured}, recordedClicks={row.navigation.recordedClickCount}");
        if (row.reasons.Length > 0)
            Console.WriteLine($"  Reasons={string.Join("；", row.reasons)}");
        Console.WriteLine($"  Next={row.nextAction}");
    }
    foreach (var error in errors)
        Console.Error.WriteLine($"ERROR: {error}");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = errors.Count == 0 && File.Exists(evidencePath) && new FileInfo(evidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static ReturnAuditSlotRow BuildReturnAuditSlot(
    ReturnNavigationSlot slot,
    bool enabled,
    ReturnNavigationConfig navigation,
    ReturnPointConfig config,
    ReturnPointReadinessReport readiness,
    string sceneMap,
    string profileName)
{
    var readinessSlot = readiness.Slots.FirstOrDefault(s => s.Slot == slot);
    var pointCount = config.Points.Count(p => IsReturnAuditPointForSlot(p.Kind, slot));
    var sameMapPointCount = slot == ReturnNavigationSlot.DeathReturn || string.IsNullOrWhiteSpace(sceneMap)
        ? 0
        : config.Points.Count(p => IsReturnAuditPointForSlot(p.Kind, slot) && IsDiagnosticSameMap(p.MapName, sceneMap));
    var reasons = readinessSlot?.Reasons.ToArray() ?? Array.Empty<string>();
    var navigationStatus = BuildReturnAuditNavigationStatus(navigation);
    var nextAction = BuildReturnAuditNextAction(enabled, pointCount, sameMapPointCount, navigation, reasons, slot, sceneMap, profileName);

    return new ReturnAuditSlotRow(
        ReturnNavigationSlotText(slot),
        readinessSlot?.SlotName ?? slot.ToString(),
        enabled,
        readinessSlot?.Level.ToString() ?? "Unknown",
        readinessSlot?.Summary ?? "",
        ReturnAuditPointScopeText(slot),
        pointCount,
        sameMapPointCount,
        sceneMap,
        navigationStatus,
        reasons,
        nextAction);
}

static bool IsReturnAuditPointForSlot(ReturnPointKind kind, ReturnNavigationSlot slot) => slot switch
{
    ReturnNavigationSlot.FixedFarm => true,
    ReturnNavigationSlot.EarthSpirit => true,
    ReturnNavigationSlot.StuckRecovery => true,
    ReturnNavigationSlot.DeathReturn => true,
    _ => false
};

static string ReturnAuditPointScopeText(ReturnNavigationSlot slot) => slot switch
{
    ReturnNavigationSlot.DeathReturn => "DeathPreferredThenAny",
    ReturnNavigationSlot.EarthSpirit => "EarthPreferredThenNearestSameMap",
    ReturnNavigationSlot.StuckRecovery => "NearestSameMap",
    _ => "NearestSameMap"
};

static ReturnAuditNavigationStatus BuildReturnAuditNavigationStatus(ReturnNavigationConfig navigation)
{
    var configured = navigation.Mode switch
    {
        ReturnNavigationMode.Disabled => false,
        ReturnNavigationMode.HotkeyOnly => !string.IsNullOrWhiteSpace(navigation.Hotkey),
        ReturnNavigationMode.ClickClientPoint => navigation.ClickX > 0 && navigation.ClickY > 0,
        ReturnNavigationMode.HotkeyThenClickClientPoint => !string.IsNullOrWhiteSpace(navigation.Hotkey) && navigation.ClickX > 0 && navigation.ClickY > 0,
        ReturnNavigationMode.DirectionalClientClick => navigation.ClickX > 0 && navigation.ClickY > 0,
        ReturnNavigationMode.HotkeyThenDirectionalClientClick => !string.IsNullOrWhiteSpace(navigation.Hotkey) && navigation.ClickX > 0 && navigation.ClickY > 0,
        ReturnNavigationMode.RecordedClientClickSequence => navigation.RecordedClicks.Count > 0 && (navigation.RecordedMovedCloserToTarget || navigation.RecordedArrivedAtTarget),
        _ => false
    };

    return new ReturnAuditNavigationStatus(
        navigation.Mode.ToString(),
        configured,
        navigation.Hotkey,
        navigation.ClickX,
        navigation.ClickY,
        navigation.ClickButton.ToString(),
        navigation.ClickRepeat,
        navigation.DispatchMode.ToString(),
        navigation.RecordedPreHotkeys.Count,
        navigation.RecordedClicks.Count,
        navigation.RecordedSourceClientSize,
        navigation.RecordedSourceEvidencePath,
        navigation.RecordedBeforeMap,
        navigation.RecordedBeforeX,
        navigation.RecordedBeforeY,
        navigation.RecordedAfterMap,
        navigation.RecordedAfterX,
        navigation.RecordedAfterY,
        navigation.RecordedTargetX,
        navigation.RecordedTargetY,
        navigation.RecordedMovedCloserToTarget,
        navigation.RecordedArrivedAtTarget);
}

static string BuildReturnAuditNextAction(
    bool enabled,
    int pointCount,
    int sameMapPointCount,
    ReturnNavigationConfig navigation,
    IReadOnlyList<string> reasons,
    ReturnNavigationSlot slot,
    string sceneMap,
    string profileName)
{
    var slotArg = ReturnNavigationSlotText(slot);
    var profileArg = string.IsNullOrWhiteSpace(profileName)
        ? "<方案名>"
        : QuotePowerShellArg(profileName);
    if (!enabled)
        return "未启用；如果需要此能力，先在回点配置中开启。";

    if (slot != ReturnNavigationSlot.DeathReturn && pointCount == 0)
        return "缺少可用回点；先采集当前挂机点或导入旧坐标。";

    if (slot != ReturnNavigationSlot.DeathReturn && !string.IsNullOrWhiteSpace(sceneMap) && sameMapPointCount == 0)
        return $"当前地图 {sceneMap} 没有同地图回点；先在本地图采集回点。";

    if (navigation.Mode == ReturnNavigationMode.Disabled || reasons.Any(r => r.Contains("导航动作关闭", StringComparison.Ordinal)))
        return $"缺少导航动作；优先执行 return-prepare-saved-point --profile {profileArg} --kind {slotArg} 生成录制命令。";

    if (navigation.Mode == ReturnNavigationMode.RecordedClientClickSequence && navigation.RecordedClicks.Count == 0)
        return "录制序列为空；重新录制并导入真实客户区点击样本。";

    if (navigation.Mode == ReturnNavigationMode.RecordedClientClickSequence
        && !navigation.RecordedMovedCloserToTarget
        && !navigation.RecordedArrivedAtTarget)
        return "录制样本未验证靠近或到达；重新录制可验证样本。";

    if (reasons.Count > 0)
        return $"处理阻断项：{reasons[0]}";

    return "配置看起来可用；下一步做 dry-run 或受控真实回点验证。";
}

static bool RunReturnDirectionalArmDiagnostics(string[] args)
{
    Console.WriteLine("Return directional-arm diagnostics");

    var profileName = ReadOption(args, "--profile") ?? ReadOption(args, "-p");
    if (string.IsNullOrWhiteSpace(profileName))
    {
        Console.Error.WriteLine("FAIL: 必须指定 --profile。");
        return false;
    }

    profileName = profileName.Trim();
    var commit = args.Any(a => string.Equals(a, "--commit", StringComparison.OrdinalIgnoreCase));
    var requestedSlots = ReadReturnDirectionalArmSlots(ReadOption(args, "--slot") ?? "fixed");
    if (requestedSlots.Length == 0)
    {
        Console.Error.WriteLine("FAIL: --slot 仅支持 fixed、stuck、both。");
        return false;
    }

    var mode = ReadReturnNavigationModeOption(args, "--mode", ReturnNavigationMode.DirectionalClientClick);
    if (mode is not (ReturnNavigationMode.DirectionalClientClick or ReturnNavigationMode.HotkeyThenDirectionalClientClick))
    {
        Console.Error.WriteLine("FAIL: 方向回点只支持 --mode direction 或 hotkey-direction。");
        return false;
    }

    var hotkey = ReadOption(args, "--hotkey") ?? "";
    if (mode == ReturnNavigationMode.HotkeyThenDirectionalClientClick && string.IsNullOrWhiteSpace(hotkey))
    {
        Console.Error.WriteLine("FAIL: hotkey-direction 模式必须提供 --hotkey。");
        return false;
    }

    var explicitTarget = ReadOffsetOption(args, "--target", (-1, -1));
    var hasExplicitTarget = explicitTarget.X >= 0 && explicitTarget.Y >= 0;
    var labelFilter = ReadOption(args, "--label") ?? "";
    var requestedMap = NormalizeDiagnosticMapName(ReadOption(args, "--map") ?? "");
    var explicitCenter = ReadOffsetOption(args, "--center", (-1, -1));
    var radius = Math.Clamp(ReadIntOption(args, "--radius", 220), 20, 2000);
    var arrival = Math.Max(1, ReadIntOption(args, "--arrival", 8));
    var interval = Math.Max(200, ReadIntOption(args, "--interval", 1200));
    var delay = Math.Clamp(ReadIntOption(args, "--delay", 120), 0, 5000);
    var clickButton = ReadMouseButtonOption(args, "--button", InputMouseButton.Left);
    var clickRepeat = Math.Clamp(ReadIntOption(args, "--repeat", 1), 1, 10);
    var clickInterval = Math.Clamp(ReadIntOption(args, "--click-interval", 120), 20, 1000);
    var afterHotkey = (ReadOption(args, "--after-hotkey") ?? "").Trim();
    var afterDelay = Math.Clamp(ReadIntOption(args, "--after-delay", 120), 0, 3000);
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var invertX = args.Any(a => string.Equals(a, "--invert-x", StringComparison.OrdinalIgnoreCase));
    var invertY = args.Any(a => string.Equals(a, "--invert-y", StringComparison.OrdinalIgnoreCase));

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();
    provider.GetRequiredService<IAppInitService>().Initialize();

    var runtimeData = provider.GetRequiredService<IRuntimeDataService>();
    var ocr = provider.GetRequiredService<ITemplateOcrService>();
    var dictionaryLoad = LoadDiagnosticOcrDictionaries(ocr, runtimeData.EnumerateDictionaryFiles());

    var window = TryBindFirstGameWindow(provider);
    if (window is null)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口，无法基于当前坐标计算方向点击。");
        return false;
    }

    var appProfiles = provider.GetRequiredService<IAppProfileService>();
    var load = appProfiles.LoadAll(profileName);
    if (!load.GlobalLoaded && load.LoadedModules.Count == 0)
    {
        Console.Error.WriteLine($"FAIL: 指定方案无法加载：{profileName}");
        return false;
    }

    var returnPoints = provider.GetRequiredService<IReturnPointService>();
    var config = returnPoints.Current;
    var scene = provider.GetRequiredService<ISceneStateService>().Recognize(window, config.NavigationRecognition);
    if (!scene.HasCoordinate)
    {
        Console.Error.WriteLine($"FAIL: 当前坐标未识别，不能生成方向回点。coord='{scene.CoordinateText}'");
        return false;
    }

    var sceneMap = NormalizeDiagnosticMapName(scene.MapNameText);
    var effectiveMap = !string.IsNullOrWhiteSpace(requestedMap) ? requestedMap : sceneMap;
    var candidates = config.Points
        .Where(p => string.IsNullOrWhiteSpace(effectiveMap) || IsDiagnosticSameMap(p.MapName, effectiveMap))
        .ToArray();

    if (hasExplicitTarget)
        candidates = candidates.Where(p => p.X == explicitTarget.X && p.Y == explicitTarget.Y).ToArray();

    if (!string.IsNullOrWhiteSpace(labelFilter))
        candidates = candidates.Where(p => p.Label.Contains(labelFilter, StringComparison.OrdinalIgnoreCase)).ToArray();

    var sceneX = scene.X!.Value;
    var sceneY = scene.Y!.Value;
    var selected = candidates
        .OrderBy(p => Distance(sceneX, sceneY, p.X, p.Y))
        .FirstOrDefault();
    if (selected is null)
    {
        Console.Error.WriteLine($"FAIL: 当前方案没有可用于方向回点的同地图保存点。profile={profileName}, map={effectiveMap}, target={(hasExplicitTarget ? $"{explicitTarget.X},{explicitTarget.Y}" : "-")}, label={labelFilter}");
        return false;
    }

    var centerX = explicitCenter.X >= 0 ? explicitCenter.X : window.ClientWidth / 2;
    var centerY = explicitCenter.Y >= 0 ? explicitCenter.Y : window.ClientHeight / 2;
    centerX = Math.Clamp(centerX, 0, Math.Max(0, window.ClientWidth - 1));
    centerY = Math.Clamp(centerY, 0, Math.Max(0, window.ClientHeight - 1));

    var previewClick = ComputeDirectionalPreviewClick(
        window,
        sceneX,
        sceneY,
        selected.X,
        selected.Y,
        centerX,
        centerY,
        radius,
        invertX,
        invertY);
    var distance = Distance(sceneX, sceneY, selected.X, selected.Y);

    var plannedNavigation = new ReturnNavigationConfig
    {
        Mode = mode,
        Hotkey = hotkey,
        OpenMapDelayMs = delay,
        ClickX = centerX,
        ClickY = centerY,
        ClickButton = clickButton,
        ClickRepeat = clickRepeat,
        ClickIntervalMs = clickInterval,
        AfterClickHotkey = afterHotkey,
        AfterClickDelayMs = afterDelay,
        DirectionRadius = radius,
        DirectionInvertX = invertX,
        DirectionInvertY = invertY,
        ActionIntervalMs = interval,
        DispatchMode = dispatch
    };

    if (commit)
    {
        config.ArrivalDistance = arrival;
        config.NavigationRecognition.ConfirmedMapName = selected.MapName;
        config.NavigationRecognition.ConfirmedMapNameAutoFilled = false;

        foreach (var slot in requestedSlots)
        {
            ApplyReturnDirectionalNavigationToSlot(config, slot, plannedNavigation);
        }

        appProfiles.SaveAll(profileName);
    }

    var slotPlans = requestedSlots.Select(slot => new
    {
        slot = ReturnNavigationSlotText(slot),
        slotName = slot switch
        {
            ReturnNavigationSlot.StuckRecovery => "卡点恢复",
            _ => "挂机回点"
        },
        willEnable = commit,
        targetNavigationMode = plannedNavigation.Mode.ToString()
    }).ToArray();

    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "return-directional-arm", DateTime.Now.ToString("yyyyMMdd-HHmmss"));
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"return-directional-arm-{window.Pid}.json");
    var evidence = new
    {
        capturedAt = DateTimeOffset.Now,
        mode = commit ? "return-directional-arm-commit-no-input" : "return-directional-arm-preview-no-input",
        safety = new
        {
            sendsInput = false,
            clicksMouse = false,
            writesProfile = commit,
            writesMemory = false,
            injectsDll = false,
            hooksClient = false,
            patchesClient = false
        },
        profile = new
        {
            profileName,
            loadedModules = load.LoadedModules,
            missingModules = load.MissingModules
        },
        dictionaryLoad = new
        {
            dictionaryLoad.TotalFiles,
            dictionaryLoad.LoadedFiles,
            dictionaryLoad.SkippedFiles,
            dictionaryLoad.LoadedGlyphs
        },
        window = new
        {
            window.Pid,
            Title = CleanEvidenceText(window.Title),
            bitness = window.Bitness.ToString(),
            window.ClientSizeText,
            window.IsAutomationAllowed
        },
        scene = new
        {
            MapName = CleanEvidenceText(scene.MapNameText),
            scene.X,
            scene.Y,
            scene.MapNameSource,
            scene.MapNameConfidencePercent,
            scene.CoordinateSource,
            scene.CoordinateConfidencePercent
        },
        selectedTarget = new
        {
            selected.Id,
            MapName = CleanEvidenceText(selected.MapName),
            selected.X,
            selected.Y,
            Label = CleanEvidenceText(selected.Label),
            Kind = selected.Kind.ToString(),
            distance
        },
        planned = new
        {
            commit,
            slots = slotPlans,
            arrival,
            navigation = BuildReturnAuditNavigationStatus(plannedNavigation),
            center = new { x = centerX, y = centerY },
            previewClick = new { x = previewClick.X, y = previewClick.Y },
            distanceToTarget = distance,
            inArrivalRange = distance <= arrival
        }
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Profile={profileName}, commit={commit}, slots={string.Join(",", requestedSlots.Select(ReturnNavigationSlotText))}");
    Console.WriteLine($"Window={window.Pid}/{window.Bitness}/{window.ClientSizeText}");
    Console.WriteLine($"Scene={scene.MapNameText} {scene.X},{scene.Y}");
    Console.WriteLine($"Target={selected.MapName} {selected.X},{selected.Y}, label={selected.Label}, distance={distance:0.0}, arrival={arrival}");
    Console.WriteLine($"Mode={mode}, dispatch={dispatch}, center={centerX},{centerY}, radius={radius}, previewClick={previewClick.X},{previewClick.Y}, button={clickButton}, repeat={clickRepeat}");
    if (!commit)
        Console.WriteLine("PreviewOnly=未写入方案；确认后追加 --commit 才会保存方向点击配置。");
    if (distance <= arrival)
        Console.WriteLine($"Gate=当前距离 {distance:0.0} 已在到达范围内；此时不会触发真实回点，建议离开回点后再验证。");
    Console.WriteLine("Safety send=0, click=0");
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && window.Bitness == ClientBitness.X86
             && scene.HasCoordinate
             && previewClick.X >= 0
             && previewClick.Y >= 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static ReturnNavigationSlot[] ReadReturnDirectionalArmSlots(string value)
{
    return value.Trim().ToLowerInvariant() switch
    {
        "both" or "all" or "fixed-stuck" or "stuck-fixed" => new[] { ReturnNavigationSlot.FixedFarm, ReturnNavigationSlot.StuckRecovery },
        "fixed" or "farm" or "return" => new[] { ReturnNavigationSlot.FixedFarm },
        "stuck" or "recovery" => new[] { ReturnNavigationSlot.StuckRecovery },
        _ => Array.Empty<ReturnNavigationSlot>()
    };
}

static void ApplyReturnDirectionalNavigationToSlot(
    ReturnPointConfig config,
    ReturnNavigationSlot slot,
    ReturnNavigationConfig source)
{
    var target = slot switch
    {
        ReturnNavigationSlot.StuckRecovery => config.StuckRecoveryNavigation,
        _ => config.ReturnNavigation
    };

    target.Mode = source.Mode;
    target.Hotkey = source.Hotkey;
    target.OpenMapDelayMs = source.OpenMapDelayMs;
    target.ClickX = source.ClickX;
    target.ClickY = source.ClickY;
    target.ClickButton = source.ClickButton;
    target.ClickRepeat = source.ClickRepeat;
    target.ClickIntervalMs = source.ClickIntervalMs;
    target.AfterClickHotkey = source.AfterClickHotkey;
    target.AfterClickDelayMs = source.AfterClickDelayMs;
    target.DirectionRadius = source.DirectionRadius;
    target.DirectionInvertX = source.DirectionInvertX;
    target.DirectionInvertY = source.DirectionInvertY;
    target.ActionIntervalMs = source.ActionIntervalMs;
    target.DispatchMode = source.DispatchMode;

    if (slot == ReturnNavigationSlot.StuckRecovery)
        config.EnableStuckRecovery = true;
    else
        config.EnableFixedFarmReturn = true;
}

static (int X, int Y) ComputeDirectionalPreviewClick(
    BoundGameWindow window,
    int currentX,
    int currentY,
    int targetX,
    int targetY,
    int centerX,
    int centerY,
    int radius,
    bool invertX,
    bool invertY)
{
    var dx = targetX - currentX;
    var dy = targetY - currentY;
    if (invertX)
        dx = -dx;
    if (invertY)
        dy = -dy;

    var length = Math.Sqrt(dx * dx + dy * dy);
    if (length < 0.001)
        return (Math.Clamp(centerX, 0, Math.Max(0, window.ClientWidth - 1)), Math.Clamp(centerY, 0, Math.Max(0, window.ClientHeight - 1)));

    var x = centerX + (int)Math.Round(dx / length * radius);
    var y = centerY + (int)Math.Round(dy / length * radius);
    return (Math.Clamp(x, 0, Math.Max(0, window.ClientWidth - 1)), Math.Clamp(y, 0, Math.Max(0, window.ClientHeight - 1)));
}

static bool RunBuiltInHangSwitchDiagnostics(string[] args)
{
    Console.WriteLine("Built-in hang switch diagnostics");

    var executeRequested = args.Any(a => string.Equals(a, "--execute", StringComparison.OrdinalIgnoreCase));
    var requireLive = args.Any(a => string.Equals(a, "--require-live", StringComparison.OrdinalIgnoreCase));
    var mode = ReadGameBuiltInHangSwitchModeOption(args);
    var hotkey = ReadOption(args, "--hotkey") ?? "";
    var click = ReadOffsetOption(args, "--click", (-1, -1));
    var x = ReadIntOption(args, "--x", click.X);
    var y = ReadIntOption(args, "--y", click.Y);
    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var cooldownMs = Math.Clamp(ReadIntOption(args, "--cooldown-ms", 3000), 500, 60000);

    if (mode == GameBuiltInHangSwitchMode.Disabled)
    {
        if (!string.IsNullOrWhiteSpace(hotkey))
            mode = GameBuiltInHangSwitchMode.Hotkey;
        else if (x > 0 && y > 0)
            mode = GameBuiltInHangSwitchMode.ClientClick;
    }

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var window = TryBindFirstGameWindow(provider);
    var usingSyntheticWindow = window is null;
    if (window is null)
    {
        if (requireLive || executeRequested)
        {
            Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口；真实执行必须绑定真实窗口。");
            return false;
        }

        window = DiagnosticWindow(new nint(4401), "synthetic-built-in-hang-switch", 1920, 1080);
    }

    var cfg = provider.GetRequiredService<IGlobalConfigService>().Current;
    cfg.CombatBackendPreference = CombatBackendPreference.InternalPlugin;
    cfg.InputDispatchMode = dispatch;
    cfg.GameBuiltInHangSwitchMode = mode;
    cfg.GameBuiltInHangSwitchHotkey = hotkey;
    cfg.GameBuiltInHangSwitchClickX = x;
    cfg.GameBuiltInHangSwitchClickY = y;
    cfg.GameBuiltInHangSwitchCooldownMs = cooldownMs;

    var service = provider.GetRequiredService<IGameBuiltInHangSwitchService>();
    var result = service.TryTrigger(window, cfg, executeRequested);

    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss-fff");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "built-in-hang-switch", stamp);
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"built-in-hang-switch-{window.Pid}-{mode.ToString().ToLowerInvariant()}.json");
    var evidence = new
    {
        mode = "built-in-hang-switch-diagnostic",
        generatedAt = DateTimeOffset.Now,
        safety = new
        {
            dryRun = !executeRequested,
            executeRequested,
            usingSyntheticWindow,
            noMemoryWrite = true,
            mouseHook = true,
            keyboardIgnored = true,
            noPatch = true
        },
        window = new
        {
            hwnd = window.Hwnd.ToInt64(),
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            window.ClientSizeText
        },
        config = new
        {
            cfg.CombatBackendPreference,
            cfg.InputDispatchMode,
            cfg.GameBuiltInHangSwitchMode,
            cfg.GameBuiltInHangSwitchHotkey,
            cfg.GameBuiltInHangSwitchClickX,
            cfg.GameBuiltInHangSwitchClickY,
            cfg.GameBuiltInHangSwitchCooldownMs
        },
        result
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Window={(usingSyntheticWindow ? "synthetic" : $"pid={window.Pid}")}, size={window.ClientSizeText}, mode={cfg.GameBuiltInHangSwitchMode}, dispatch={cfg.InputDispatchMode}");
    Console.WriteLine($"Result: configured={result.IsConfigured}, valid={result.IsValid}, wouldExecute={result.WouldExecute}, executed={result.Executed}, action={result.Action}");
    Console.WriteLine(result.Message);
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = result.IsConfigured
             && result.IsValid
             && (executeRequested ? result.Executed : result.WouldExecute)
             && File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0;
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static GameBuiltInHangSwitchMode ReadGameBuiltInHangSwitchModeOption(string[] args)
{
    var value = ReadOption(args, "--mode")?.Trim();
    if (string.IsNullOrWhiteSpace(value))
        return GameBuiltInHangSwitchMode.Disabled;

    return value.ToLowerInvariant() switch
    {
        "click" or "client-click" or "clientclick" => GameBuiltInHangSwitchMode.ClientClick,
        "key" or "hotkey" => GameBuiltInHangSwitchMode.Hotkey,
        "disabled" or "none" or "off" => GameBuiltInHangSwitchMode.Disabled,
        _ when Enum.TryParse<GameBuiltInHangSwitchMode>(value, ignoreCase: true, out var mode) => mode,
        _ => GameBuiltInHangSwitchMode.Disabled
    };
}

static bool RunInputYieldStatusDiagnostics(string[] args)
{
    Console.WriteLine("Input yield status diagnostics");

    var dispatch = ReadDispatchOption(args, "--dispatch", InputDispatchMode.PostMessage);
    var yieldMs = Math.Clamp(ReadIntOption(args, "--yield-ms", 800), 0, 10000);
    var requireLive = args.Any(a => string.Equals(a, "--require-live", StringComparison.OrdinalIgnoreCase));

    var services = new ServiceCollection();
    services.AddTlbbCore();
    using var provider = services.BuildServiceProvider();

    var window = TryBindFirstGameWindow(provider);
    var usingSyntheticWindow = window is null;
    if (window is null)
    {
        if (requireLive)
        {
            Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
            return false;
        }

        window = DiagnosticWindow(new nint(4410), "synthetic-input-yield-status", 1920, 1080);
    }

    var input = provider.GetRequiredService<IInputService>();
    input.YieldToUserInput = yieldMs > 0;
    input.UserInputYieldMs = yieldMs;
    input.DefaultDispatchMode = dispatch;

    var status = input.GetYieldStatus(window.Hwnd, dispatch);
    var stamp = DateTime.Now.ToString("yyyyMMdd-HHmmss-fff");
    var evidenceDir = Path.Combine(Environment.CurrentDirectory, "artifacts", "input-yield-status", stamp);
    Directory.CreateDirectory(evidenceDir);
    var evidencePath = Path.Combine(evidenceDir, $"input-yield-status-{window.Pid}.json");
    var evidence = new
    {
        mode = "input-yield-status-read-only",
        generatedAt = DateTimeOffset.Now,
        safety = new
        {
            readOnly = true,
            sendsInput = false,
            clicks = false,
            noMemoryWrite = true,
            noHook = true,
            noPatch = true,
            usingSyntheticWindow
        },
        window = new
        {
            hwnd = window.Hwnd.ToInt64(),
            window.Pid,
            window.Title,
            window.ProcessPath,
            bitness = window.Bitness.ToString(),
            window.ClientWidth,
            window.ClientHeight,
            window.ClientSizeText
        },
        config = new
        {
            dispatch,
            yieldMs,
            input.YieldToUserInput
        },
        status
    };
    File.WriteAllText(evidencePath, System.Text.Json.JsonSerializer.Serialize(evidence, JsonOptions()), new UTF8Encoding(false));

    Console.WriteLine($"Window={(usingSyntheticWindow ? "synthetic" : $"pid={window.Pid}")}, size={window.ClientSizeText}, dispatch={dispatch}, yieldMs={yieldMs}");
    Console.WriteLine($"ShouldYield={status.ShouldYield}, targetActive={status.TargetActive}, ageMs={status.LastInputAgeMs:0}, remainingMs={status.RemainingYieldMs:0}, scope={status.Scope}");
    Console.WriteLine(status.Reason);
    Console.WriteLine($"Evidence={evidencePath}");

    var ok = File.Exists(evidencePath)
             && new FileInfo(evidencePath).Length > 0
             && status.Enabled == (yieldMs > 0);
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static BoundGameWindow? TryBindFirstGameWindow(ServiceProvider provider)
{
    var game = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .FirstOrDefault();
    return game is null
        ? null
        : provider.GetRequiredService<IWindowBindingService>().BindByHandle(game.MainWindowHandle);
}

static nint ResolveGameWindowHandle(string[] args, ServiceProvider provider, out string selectionText)
{
    var hwndText = ReadStringOption(args, "--hwnd");
    if (!string.IsNullOrWhiteSpace(hwndText))
    {
        if (TryParseWindowHandle(hwndText, out var hwnd))
        {
            selectionText = $"Window selection: --hwnd {hwndText}";
            return hwnd;
        }

        Console.Error.WriteLine($"FAIL: --hwnd 无法解析：{hwndText}");
        selectionText = string.Empty;
        return nint.Zero;
    }

    var games = Process.GetProcessesByName("Game")
        .Where(p => p.MainWindowHandle != nint.Zero)
        .OrderBy(p => p.Id)
        .ToArray();

    if (games.Length == 0)
    {
        Console.Error.WriteLine("FAIL: 未找到正在运行的 Game.exe 主窗口。");
        selectionText = string.Empty;
        return nint.Zero;
    }

    var binding = provider.GetRequiredService<IWindowBindingService>();
    var candidates = games
        .Select(p => new { Process = p, Window = binding.BindByHandle(p.MainWindowHandle) })
        .Where(x => x.Window is not null)
        .Select(x => new GameWindowCandidate(
            x.Process.Id,
            x.Window!,
            Math.Max(0, x.Window!.ClientWidth) * Math.Max(0, x.Window!.ClientHeight)))
        .OrderByDescending(x => x.Area)
        .ThenBy(x => x.Pid)
        .ToArray();

    if (candidates.Length == 0)
    {
        Console.Error.WriteLine("FAIL: 找到 Game.exe，但窗口绑定失败。");
        selectionText = string.Empty;
        return nint.Zero;
    }

    var pidText = ReadStringOption(args, "--pid");
    var selected = candidates.FirstOrDefault();
    if (!string.IsNullOrWhiteSpace(pidText))
    {
        if (!int.TryParse(pidText, out var pid))
        {
            Console.Error.WriteLine($"FAIL: --pid 无法解析：{pidText}");
            selectionText = string.Empty;
            return nint.Zero;
        }

        selected = candidates.FirstOrDefault(c => c.Pid == pid);
        if (selected is null)
        {
            Console.Error.WriteLine($"FAIL: 未找到带主窗口的 Game.exe PID={pid}。");
            Console.WriteLine(FormatGameCandidates(candidates, selectedPid: null));
            selectionText = string.Empty;
            return nint.Zero;
        }
    }

    selectionText = FormatGameCandidates(candidates, selected!.Pid);
    return selected.Window.Hwnd;
}

static string FormatGameCandidates(IReadOnlyList<GameWindowCandidate> candidates, int? selectedPid)
{
    var builder = new StringBuilder();
    builder.AppendLine("Game window candidates:");
    foreach (var candidate in candidates)
    {
        var marker = selectedPid == candidate.Pid ? "*" : " ";
        builder.Append(marker)
            .Append(" pid=").Append(candidate.Pid)
            .Append(" hwnd=0x").Append(candidate.Window.Hwnd.ToInt64().ToString("X", CultureInfo.InvariantCulture))
            .Append(" bitness=").Append(candidate.Window.Bitness)
            .Append(" size=").Append(candidate.Window.ClientSizeText)
            .Append(" title=").Append(candidate.Window.Title)
            .AppendLine();
    }

    if (selectedPid is null)
        builder.AppendLine("No window selected.");
    else
        builder.AppendLine("Selection rule: --pid/--hwnd if supplied; otherwise largest client area.");
    return builder.ToString().TrimEnd();
}

static bool TryParseWindowHandle(string text, out nint hwnd)
{
    hwnd = nint.Zero;
    var value = text.Trim();
    if (value.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
    {
        if (long.TryParse(value[2..], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var hex))
        {
            hwnd = new nint(hex);
            return hwnd != nint.Zero;
        }

        return false;
    }

    if (!long.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var number))
        return false;

    hwnd = new nint(number);
    return hwnd != nint.Zero;
}

static ServiceProvider BuildProfileAutoSaveProvider(MemoryProfileService profiles, bool includeViewModels, IWindowBindingService? binding = null)
{
    var services = new ServiceCollection();
    services.AddTlbbCore();
    services.AddSingleton<IProfileService>(profiles);
    if (binding is not null)
        services.AddSingleton(binding);

    if (includeViewModels)
    {
        services.AddSingleton<BindingPanelViewModel>();
        services.AddSingleton<LogPanelViewModel>();
        services.AddSingleton<MainViewModel>();
    }

    return services.BuildServiceProvider();
}

static async Task<bool> RunShoutDiagnostics()
{
    Console.WriteLine("Shout diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var config = new ShoutConfigService(profiles, log);
    var global = new TestGlobalConfigService();
    var input = new CountingInputService();
    var services = new ServiceCollection();
    services.AddTlbbCore();
    services.AddSingleton<ILogService>(log);
    services.AddSingleton<IProfileService>(profiles);
    services.AddSingleton<IShoutConfigService>(config);
    services.AddSingleton<IGlobalConfigService>(global);
    services.AddSingleton<IInputService>(input);
    using var provider = services.BuildServiceProvider();
    var controller = provider.GetRequiredService<IShoutController>();

    global.Current.InputDispatchMode = InputDispatchMode.SendInput;
    config.Current.Enabled = true;
    config.Current.OpenChatHotkey = "Enter";
    config.Current.CommitHotkey = "Enter";
    config.Current.IntervalMs = 80;
    config.Current.MessageDelayMs = 0;
    config.Current.CommitDelayMs = 0;
    config.Current.RotateMessages = true;
    config.Current.Messages.Clear();
    config.Current.Messages.Add(new ShoutMessage { Id = "duplicate", Text = "龙伴行喊话诊断1", Enabled = true, Channel = ShoutChannel.Nearby });
    config.Current.Messages.Add(new ShoutMessage { Id = "duplicate", Text = "龙伴行喊话诊断2", Enabled = true, Channel = ShoutChannel.World });
    config.Save("shout-diagnostic");

    config.Current.Messages.Clear();
    config.Current.Enabled = false;
    var loaded = config.Load("shout-diagnostic");

    controller.Attach(DiagnosticWindow(new nint(6701), "shout-runtime"));
    controller.Start();
    await Task.Delay(240);
    var gatedState = controller.RunState;
    controller.Stop();

    var sentTextCount = input.SendTextCount;
    var sentHotkeys = string.Join(",", input.SentHotkeys);
    var sentTexts = string.Join("|", input.SentTexts);
    var gateLogs = log.Entries.Count(e => e.Module == "喊话" && e.Message.Contains("频道未就绪", StringComparison.Ordinal));
    var stableQueue = config.Current.Messages.Count == 2
                      && config.Current.Messages.Select(message => message.Id).Distinct(StringComparer.Ordinal).Count() == 2
                      && config.Current.Messages[0].Order == 1
                      && config.Current.Messages[1].Order == 2
                      && config.Current.Messages[1].Channel == ShoutChannel.World;

    Console.WriteLine($"Loaded={loaded}");
    Console.WriteLine($"SendText calls={sentTextCount}");
    Console.WriteLine($"Sent hotkeys={sentHotkeys}");
    Console.WriteLine($"Sent texts={sentTexts}");
    Console.WriteLine($"Channel gate logs={gateLogs}");
    Console.WriteLine($"Stable queue={stableQueue}");
    Console.WriteLine($"Gated state={gatedState}");
    Console.WriteLine($"Applied input mode={input.DefaultDispatchMode}");

    var ok = loaded
             && stableQueue
             && ShoutConfig.WorldChannelCooldownMs == 180_000
             && sentTextCount == 0
             && input.SentHotkeys.Count == 0
             && gateLogs >= 1
             && gatedState == RunState.Error;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: shout queue persistence or channel safety gate did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static async Task<bool> RunAutoReconnectDiagnostics()
{
    Console.WriteLine("AutoReconnect diagnostics");

    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var config = new AutoReconnectConfigService(profiles, log);
    config.Current.Enabled = true;
    config.Current.CheckIntervalMs = 500;
    config.Current.RebindTimeoutMs = 100;
    config.Current.RelaunchDelayMs = 0;
    config.Current.MaxRestartAttempts = 2;

    var rebindBinding = new FakeWindowBindingService();
    var rebindClient = new FakeClientProcessService
    {
        ProcessAlive = true,
        WaitWindowHandle = new nint(0x2222)
    };
    rebindClient.AliveWindows.Add(new nint(0x2222));

    var rebindController = new AutoReconnectController(log, config, rebindClient, rebindBinding, new StateMachineEngine(log));
    rebindController.Attach(DiagnosticWindow(new nint(0x1111), "lost-window"));
    rebindController.Start();
    await Task.Delay(220);
    rebindController.Stop();

    Console.WriteLine($"Rebind bind calls={rebindBinding.BindHandleCalls}");
    Console.WriteLine($"Rebind wait calls={rebindClient.WaitCalls}");
    Console.WriteLine($"Rebind state={rebindController.CurrentStateName}, run={rebindController.RunState}");

    var restartBinding = new FakeWindowBindingService();
    var restartClient = new FakeClientProcessService
    {
        ProcessAlive = false,
        StartedPid = 777,
        WaitWindowHandle = new nint(0x3333)
    };
    restartClient.AliveWindows.Add(new nint(0x3333));

    config.Current.Enabled = true;
    config.Current.ProcessPathOverride = Path.Combine(Environment.CurrentDirectory, "diagnostic-game.exe");
    config.Current.RestartWhenProcessExited = true;

    var restartController = new AutoReconnectController(log, config, restartClient, restartBinding, new StateMachineEngine(log));
    restartController.Attach(DiagnosticWindow(new nint(0x1111), "dead-process"));
    restartController.Start();
    await Task.Delay(220);
    restartController.Stop();

    Console.WriteLine($"Restart start calls={restartClient.StartCalls}");
    Console.WriteLine($"Restart bind calls={restartBinding.BindHandleCalls}");
    Console.WriteLine($"Restart last path={restartClient.LastStartPath}");
    Console.WriteLine($"Restart state={restartController.CurrentStateName}, run={restartController.RunState}");

    var loadedBefore = config.Load("auto-reconnect-diagnostic");
    config.Save("auto-reconnect-diagnostic");
    config.Current.Enabled = false;
    config.Current.CheckIntervalMs = 9999;
    var loadedAfter = config.Load("auto-reconnect-diagnostic");

    Console.WriteLine($"Config missing before save={loadedBefore == false}");
    Console.WriteLine($"Config loaded after save={loadedAfter}");

    var ok = rebindBinding.BindHandleCalls >= 1
             && rebindClient.WaitCalls >= 1
             && restartClient.StartCalls == 1
             && restartBinding.BindHandleCalls >= 1
             && string.Equals(restartClient.LastStartPath, Path.Combine(Environment.CurrentDirectory, "diagnostic-game.exe"), StringComparison.Ordinal)
             && loadedAfter
             && config.Current.Enabled
             && config.Current.CheckIntervalMs == 500;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: auto reconnect did not recover or persist config as expected.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

