        var uiOpenBagCandidates = cleanupPage.CleanupCandidates.Count;
        var uiOpenBagInputCount = cleanupInput.SendKeyCount;
        var uiOpenBagClickCount = cleanupInput.ClickCount;
        var uiOpenBagStatus = cleanupPage.CleanupStatus;
