        await cleanupPage.OpenBagThenAnalyzeCleanupCommand.ExecuteAsync(null);
        var uiControlledOpenCandidates = cleanupPage.CleanupCandidates.Count;
        var uiControlledOpenSendCount = cleanupUiOpenInput.SendKeyCount;
        var uiControlledOpenHotkey = cleanupUiOpenInput.SentHotkeys.LastOrDefault() ?? "";
        var uiControlledOpenCleanupInputCount = cleanupInput.SendKeyCount + cleanupInput.SendTextCount + cleanupInput.ClickCount;
        var uiControlledOpenStatus = cleanupPage.CleanupStatus;
        var uiControlledOpenSafetySummary = cleanupPage.CleanupSafetySummary;

        cleanupPage.PlanName = "清包前端自动保存";
        var editableStep = cleanupPage.Steps.FirstOrDefault();
        if (editableStep is not null)
        {
            editableStep.Label = "清包队列自动保存";
            editableStep.Hotkey = "F8";
        }

        var persistedUtility = new UtilityConfigService(profiles, log);
        var persistedLoaded = persistedUtility.Load(cleanupPage.ProfileName);
        var persistedStep = persistedUtility.Current.Steps.FirstOrDefault();
        var persistedPlanName = persistedUtility.Current.PlanName;
        var persistedStepLabel = persistedStep?.Label ?? "";
        var persistedStepHotkey = persistedStep?.Hotkey ?? "";

        Console.WriteLine($"UI cleanup default candidates={uiDefaultCandidates}, sell={uiDefaultSellCandidates}, protected={uiDefaultProtectedCandidates}, input={uiDefaultInputCount}");
        Console.WriteLine($"UI cleanup default status={uiDefaultStatus}");
        Console.WriteLine($"UI cleanup default scan={uiDefaultScanSummary}");
        Console.WriteLine($"UI cleanup default safety={uiDefaultSafetySummary}");
        Console.WriteLine($"UI cleanup open-bag candidates={uiOpenBagCandidates}, plannedOpenHotkeys={uiOpenBagInputCount}, clicks={uiOpenBagClickCount}");
        Console.WriteLine($"UI cleanup open-bag status={uiOpenBagStatus}");
        Console.WriteLine($"UI cleanup open-bag safety={uiOpenBagSafetySummary}");
        Console.WriteLine($"UI cleanup controlled-open candidates={uiControlledOpenCandidates}, openSend={uiControlledOpenSendCount}, openHotkey={uiControlledOpenHotkey}, cleanupInput={uiControlledOpenCleanupInputCount}");
        Console.WriteLine($"UI cleanup controlled-open status={uiControlledOpenStatus}");
        Console.WriteLine($"UI cleanup controlled-open safety={uiControlledOpenSafetySummary}");
        Console.WriteLine($"UI cleanup autosave loaded={persistedLoaded}, plan={persistedPlanName}, step={persistedStepLabel}/{persistedStepHotkey}");

        var ok = keepCount == 2
                 && loaded
                 && controller.CurrentStateName == nameof(UtilityState.Error)
                 && controller.RunState == RunState.Error
                 && customInput.DefaultDispatchMode == InputDispatchMode.SendInput
                 && input.SendKeyCount == 0
                 && input.SendTextCount == 0
                 && input.ClickCount == 0
                 && customController.CurrentStateName == nameof(UtilityState.Stop)
                 && customController.RunState == RunState.Stopped
                 && customInput.SentHotkeys.Contains("F8", StringComparer.OrdinalIgnoreCase)
                 && customInput.ClickCount == 1
                 && customInput.SentTexts.Contains("utility-text")
                 && uiDefaultCandidates == 3
                 && uiDefaultSellCandidates == 1
                 && uiDefaultProtectedCandidates == 2
                 && uiDefaultInputCount == 0
                 && uiDefaultStatus.Contains("清包分析完成", StringComparison.Ordinal)
                 && uiDefaultScanSummary.Contains("可卖候选 1", StringComparison.Ordinal)
                 && uiDefaultSafetySummary.Contains("只读 是", StringComparison.Ordinal)
                 && uiDefaultSafetySummary.Contains("发输入 否", StringComparison.Ordinal)
                 && uiDefaultSafetySummary.Contains("出售 否", StringComparison.Ordinal)
                 && uiDefaultSafetySummary.Contains("改背包 否", StringComparison.Ordinal)
                 && uiOpenBagCandidates == 3
                 && uiOpenBagInputCount == 0
                 && uiOpenBagClickCount == 0
                 && uiOpenBagStatus.Contains("清包分析完成", StringComparison.Ordinal)
                 && uiOpenBagSafetySummary.Contains("发输入 否", StringComparison.Ordinal)
                 && uiOpenBagSafetySummary.Contains("出售 否", StringComparison.Ordinal)
                 && uiControlledOpenCandidates == 3
                 && uiControlledOpenSendCount == 1
                 && uiControlledOpenHotkey == "B"
                 && uiControlledOpenCleanupInputCount == 0
                 && uiControlledOpenStatus.Contains("清包分析完成", StringComparison.Ordinal)
                 && uiControlledOpenSafetySummary.Contains("只读 是", StringComparison.Ordinal)
                 && uiControlledOpenSafetySummary.Contains("出售 否", StringComparison.Ordinal)
                 && uiControlledOpenSafetySummary.Contains("改背包 否", StringComparison.Ordinal)
                 && persistedLoaded
                 && persistedPlanName == "清包前端自动保存"
                 && persistedStepLabel == "清包队列自动保存"
                 && persistedStepHotkey == "F8";

        if (!ok)
        {
            Console.Error.WriteLine("FAIL: 便捷动作序列、输入通道、配置持久化或清包候选前端链路不符合预期。");
            return false;
        }

        Console.WriteLine("PASS");
        return true;
    }
    finally
    {
        try { File.Delete(keepFile); } catch { }
    }
}

static async Task WaitForStopped(IAutomationController controller, int timeoutMs)
{
    var deadline = Environment.TickCount64 + timeoutMs;
    while (Environment.TickCount64 < deadline)
    {
        if (controller.RunState is RunState.Stopped or RunState.Error)
            return;

        await Task.Delay(20);
    }
}

static bool RunBagCleanupDiagnostics()
{
    Console.WriteLine("BagCleanup diagnostics");
    var log = new RuntimeLogService();
    var input = new CountingInputService();
    var capture = CreateSyntheticBagCapture();
    var cleanup = CreateBagCleanupService(log, input, capture);
    var inventory = new InventoryRecognitionService(new StaticClientCaptureService(capture), log);
    var policy = new ItemPolicyService(log);
    var reportService = new BagCleanupReportService();

    var v3Capture = CreateSyntheticBagV3Capture();
    var v3Input = new CountingInputService();
    var v3CaptureService = new StaticClientCaptureService(v3Capture);
    var v3Inventory = new InventoryRecognitionService(v3CaptureService, log);
    var v3Cleanup = new BagCleanupService(
        v3Inventory,
        policy,
        v3Input,
        log,
        v3CaptureService,
        templates: null,
        vision: null,
        interactionWindows: new SyntheticBagInteractionWindowDetectService(),
        interactionControls: new SyntheticBagInteractionControlCatalogService(runtimeAuthorized: false));

    var config = new BagCleanupConfig
    {
        Mode = BagCleanupExecutionMode.DryRun,
        AllowActualSell = false,
        Grid = new InventoryGridConfig
        {
            Enabled = true,
            X = 20,
            Y = 30,
            Columns = 3,
            Rows = 2,
            CellWidth = 32,
            CellHeight = 32,
            GapX = 4,
            GapY = 4,
            SlotNameOverrides =
            {
                [0] = "血爆技能书",
                [1] = "奇物碎片"
            }
        },
        Policy = new ItemPolicyConfig
        {
            KeepItems = { "血爆技能书" },
            SellKeywords = { "奇物" },
            RequireExplicitSellKeyword = true,
            ProtectUnknownItems = true
        }
    };

    var legacyLoaded = policy.LoadLegacyItemLists((Environment.GetEnvironmentVariable("TLBB_LEGACY_DATA_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "legacy-data")), config.Policy);
    var window = DiagnosticWindow(new nint(8801), "bag-cleanup");
    var v3Config = CloneBagCleanupConfig(config);
    v3Config.Grid.Enabled = false;
    v3Config.Grid.X = 0;
    v3Config.Grid.Y = 0;
    v3Config.Grid.Columns = 1;
    v3Config.Grid.Rows = 1;
    v3Config.Grid.SlotNameOverrides.Clear();
    v3Config.Grid.SlotNameOverrides[0] = "血爆技能书";
    v3Config.Grid.SlotNameOverrides[1] = "奇物碎片";
    v3Config.Grid.SlotNameOverrides[10] = "未识别物品";
    var v3Analysis = v3Cleanup.Analyze(window, v3Config);
    var v3Execute = v3Cleanup.Execute(window, v3Config);
    var calibration = inventory.AutoCalibrate(capture);
    var analysis = cleanup.Analyze(window, config);
    var execute = cleanup.Execute(window, config);
    var dryRunOpenBagConfig = CloneBagCleanupConfig(config);
    dryRunOpenBagConfig.OpenBagBeforeScan = true;
    dryRunOpenBagConfig.OpenBagHotkey = "B";
    var dryRunOpenBagInput = new CountingInputService();
    var dryRunOpenBagCleanup = CreateBagCleanupService(log, dryRunOpenBagInput, capture);
    var dryRunOpenBagAnalysis = dryRunOpenBagCleanup.Analyze(window, dryRunOpenBagConfig);
    var dryRunOpenBagExecute = dryRunOpenBagCleanup.Execute(window, dryRunOpenBagConfig);
    var safetyConfig = CloneBagCleanupConfig(config);
    safetyConfig.Grid.SlotNameOverrides[0] = "绑定奇物碎片";
    safetyConfig.Grid.SlotNameOverrides[1] = "任务奇物碎片";
    safetyConfig.Grid.SlotNameOverrides[3] = "贵重奇物碎片";
    safetyConfig.Policy.SellKeywords.Clear();
    safetyConfig.Policy.SellKeywords.Add("奇物");
    var safetyAnalysis = cleanup.Analyze(window, safetyConfig);
    var boundSafety = safetyAnalysis.Candidates.FirstOrDefault(c => c.Slot.Index == 0);
    var questSafety = safetyAnalysis.Candidates.FirstOrDefault(c => c.Slot.Index == 1);
    var valuableSafety = safetyAnalysis.Candidates.FirstOrDefault(c => c.Slot.Index == 3);
    var legacyTemplateProtected = config.Policy.KeepItems.Any(item => item.Equals("宝图", StringComparison.OrdinalIgnoreCase));
    var legacyTemplateConfig = CloneBagCleanupConfig(config);
    legacyTemplateConfig.Grid.SlotNameOverrides[0] = "宝图";
    legacyTemplateConfig.Policy.SellKeywords.Clear();
    legacyTemplateConfig.Policy.SellKeywords.Add("宝");
    var legacyTemplateAnalysis = cleanup.Analyze(window, legacyTemplateConfig);
    var legacyTemplateDecision = legacyTemplateAnalysis.Candidates.FirstOrDefault(c => c.Slot.Index == 0);
    var templateIndexPath = CreateSyntheticBagTemplateIndex(capture, 21, 67, 30, 30, "模板奇物", "Keep");
    var templateConfig = CloneBagCleanupConfig(config);
    templateConfig.TemplateMatching.Enabled = true;
    templateConfig.TemplateMatching.IndexPath = templateIndexPath;
    templateConfig.TemplateMatching.Threshold = 0.99;
    templateConfig.TemplateMatching.InnerPadding = 1;
    var templateAnalysis = cleanup.Analyze(window, templateConfig);
    var templateCandidate = templateAnalysis.Candidates.FirstOrDefault(c => c.Slot.Index == 3);
    var forceSellConfig = CloneBagCleanupConfig(config);
    forceSellConfig.Mode = BagCleanupExecutionMode.SellCandidates;
    forceSellConfig.AllowActualSell = true;
    forceSellConfig.OpenBagBeforeScan = true;
    forceSellConfig.OpenBagHotkey = "B";
    var blockedInput = new CountingInputService();
