        new StaticNavigationRecognitionService(new NavigationRecognitionResult("", "", null, null)),
        new StaticDeathRecognitionService(new DeathRecognitionResult(false, "", "")),
        new TestGlobalConfigService(),
        new ReturnPointService(new MemoryProfileService(), log),
        utilityConfig,
        cleanup,
        log);
    var snapshot = snapshotProvider.Read(window);

    var keep = analysis.Candidates.FirstOrDefault(c => c.Slot.Index == 0);
    var sell = analysis.Candidates.FirstOrDefault(c => c.Slot.Index == 1);
    var unknown = analysis.Candidates.FirstOrDefault(c => c.Slot.Index == 3);
    var report = reportService.BuildTextReport(analysis, config);

    Console.WriteLine($"Scan success={analysis.Scan.Success}");
    Console.WriteLine($"Auto calibration success={calibration.Success}, grid={calibration.Grid?.X},{calibration.Grid?.Y},{calibration.Grid?.Columns}x{calibration.Grid?.Rows}");
