    Console.WriteLine($"Unknown decision={unknown?.Decision}");
    Console.WriteLine($"Safety decisions bound/quest/valuable={boundSafety?.Decision}/{questSafety?.Decision}/{valuableSafety?.Decision}");
    Console.WriteLine($"Legacy template protected={legacyTemplateProtected}, decision={legacyTemplateDecision?.Decision}");
    Console.WriteLine($"Template match enabled={templateAnalysis.TemplateMatch.Enabled}, matched={templateAnalysis.TemplateMatch.MatchedCount}, applied={templateAnalysis.TemplateMatch.AppliedCount}, decision={templateCandidate?.Decision}, source={templateCandidate?.Slot.Source}");
    Console.WriteLine($"Safety metadata dryRun={analysis.Safety.DryRun}, sendsInput={analysis.Safety.SendsInput}, clicks={analysis.Safety.ClicksMouse}, sells={analysis.Safety.SellsItems}, modifies={analysis.Safety.ModifiesInventory}");
    Console.WriteLine($"DryRun executed={execute.Executed}");
