    Console.WriteLine($"Snapshot inventory candidates={snapshot.Inventory.Candidates.Count}");
    Console.WriteLine($"Report length={report.Length}, hasSellCandidate={report.Contains(nameof(ItemCleanupDecision.SellCandidate), StringComparison.Ordinal)}");
    Console.WriteLine($"V3 bag success={v3Analysis.Success}, total={v3Analysis.Scan.Slots.Count}, occupied={v3Analysis.Scan.OccupiedCount}, authorized={v3Analysis.Message.Contains("runtime_authorized=true", StringComparison.Ordinal)}, executed={v3Execute.Executed}, send={v3Input.SendKeyCount}, click={v3Input.ClickCount}");

    var ok = analysis.Success
             && calibration.Success
             && calibration.Grid is { Enabled: true, Columns: >= 3, Rows: >= 2, CellWidth: >= 24, CellHeight: >= 24 }
             && calibration.PreviewScan is { Success: true, Slots.Count: > 0 }
             && analysis.Scan.OccupiedCount == 3
             && analysis.Scan.EmptyCount == 3
             && legacyLoaded > 0
             && keep?.Decision == ItemCleanupDecision.Keep
             && sell?.Decision == ItemCleanupDecision.SellCandidate
             && unknown?.Decision == ItemCleanupDecision.BlockedUnknown
             && boundSafety?.Decision == ItemCleanupDecision.Keep
             && questSafety?.Decision == ItemCleanupDecision.Keep
             && valuableSafety?.Decision == ItemCleanupDecision.Keep
             && legacyTemplateProtected
             && legacyTemplateDecision?.Decision == ItemCleanupDecision.Keep
             && legacyTemplateAnalysis.SellCandidateCount == 0
             && templateAnalysis.TemplateMatch.Enabled
             && templateAnalysis.TemplateMatch.Success
             && templateAnalysis.TemplateMatch.MatchedCount >= 1
             && templateAnalysis.TemplateMatch.AppliedCount == 1
             && templateCandidate?.Decision == ItemCleanupDecision.Keep
