             && snapshot.Inventory.UsedSlots == 3
             && snapshot.Inventory.TotalSlots == 6
             && snapshot.Inventory.SellCandidateCount == 1
             && snapshot.Inventory.ProtectedCount == 2
             && snapshot.Inventory.Candidates.Any(c => c.SlotIndex == 1 && c.Decision == nameof(ItemCleanupDecision.SellCandidate))
