             && v3Analysis.Scan.OccupiedCount == 3
             && v3Analysis.Scan.EmptyCount == 57
             && v3Analysis.Message.Contains("交互窗口 V3", StringComparison.Ordinal)
             && v3Analysis.Message.Contains("10x6", StringComparison.Ordinal)
