        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunRuntimeFeatureGatesDiagnostics()
{
    Console.WriteLine("Runtime feature gates diagnostics");

    var itemIndexPath = Path.Combine(
        Environment.CurrentDirectory,
        "src",
        "TlbbAgent.Core",
        "data",
        "runtime",
        "item_assets_v1",
        "runtime",
        "runtime_template_index.json");
    var itemIndexHash = File.Exists(itemIndexPath)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(itemIndexPath))).ToLowerInvariant()
        : string.Empty;
    var itemContractValid = false;
    var itemTemplateCount = 0;
    var itemNameCount = 0;
    var itemUnsafeCount = 0;
    var runtimeIdentityCount = 0;
    if (File.Exists(itemIndexPath))
    {
        using var itemJson = JsonDocument.Parse(File.ReadAllText(itemIndexPath));
        var root = itemJson.RootElement;
        var templates = root.GetProperty("templates").EnumerateArray().ToArray();
        itemTemplateCount = templates.Length;
        itemNameCount = templates
            .Select(item => item.GetProperty("itemName").GetString() ?? string.Empty)
            .Where(item => item.Length > 0)
            .Distinct(StringComparer.Ordinal)
            .Count();
        itemUnsafeCount = templates.Count(item =>
            !string.Equals(item.GetProperty("policy").GetString(), "Keep", StringComparison.Ordinal)
            || item.GetProperty("neverSell").GetBoolean() != true);
        runtimeIdentityCount = templates.Count(item =>
            item.GetProperty("runtimeIdentityAuthorized").GetBoolean());
        itemContractValid = root.GetProperty("libraryId").GetString() == "item_assets_v1"
                            && !root.GetProperty("runtimeSellAuthorized").GetBoolean()
                            && root.GetProperty("safetyDefault").GetString() == "unknown_protected"
                            && itemTemplateCount == 41
                            && itemNameCount == 20
                            && itemUnsafeCount == 0;
    }

    var routes = new FourCityTransferRouteService();
    var routeAsset = routes.Load();
    var dryRuns = routes.BuildDryRuns();
    var routeContractValid = routeAsset.IsValid
                             && !routeAsset.RuntimeAuthorized
                             && routeAsset.CityIds.Count == 4
                             && routeAsset.Legs.Count == 12
                             && dryRuns.Count == 12
                             && dryRuns.All(item =>
                                 item.Status == NavigationRouteAuthorizationStatus.RouteNotAuthorized
                                 && !item.RuntimeAuthorized
                                 && item.PlannedInputActions == 0);

    var evidenceRoot = Path.Combine(
        Environment.CurrentDirectory,
        "artifacts",
        "verification",
        "runtime-feature-gates");
    Directory.CreateDirectory(evidenceRoot);
    var evidencePath = Path.Combine(evidenceRoot, "runtime-feature-gates.json");
    var ok = itemContractValid
             && itemIndexHash == "f3f5e70532ef598c6b4c0f202f8a7f06930248a6e6428a9adbde134ddb227b3b"
             && routeContractValid
             && routeAsset.Sha256 == "4d015e7c2bea4414500262517eda625d2fda4dc2e86a142497df024dd6932fe4";
    File.WriteAllText(
        evidencePath,
        JsonSerializer.Serialize(
            new
            {
                generatedAt = DateTimeOffset.Now,
                itemAssets = new
                {
                    path = itemIndexPath,
                    sha256 = itemIndexHash,
                    templates = itemTemplateCount,
                    uniqueItems = itemNameCount,
                    unsafeEntries = itemUnsafeCount,
                    runtimeIdentityEntries = runtimeIdentityCount,
                    runtimeSellAuthorized = false,
                    safetyDefault = "unknown_protected",
                    passed = itemContractValid
                },
                routeAsset,
                dryRuns,
                passed = ok
            },
            new JsonSerializerOptions { WriteIndented = true }),
        new UTF8Encoding(false));

    Console.WriteLine($"ITEM_ASSETS status={(itemContractValid ? "PASS" : "FAIL")} templates={itemTemplateCount}/41 unique={itemNameCount}/20 unsafe={itemUnsafeCount} identity_enabled={runtimeIdentityCount} sell_authorized=false hash={itemIndexHash}");
    Console.WriteLine($"FOUR_CITY_ROUTES status={(routeContractValid ? "PASS" : "FAIL")} cities={routeAsset.CityIds.Count}/4 dry_runs={dryRuns.Count}/12 actions={dryRuns.Sum(item => item.PlannedInputActions)} runtime_authorized={routeAsset.RuntimeAuthorized} hash={routeAsset.Sha256}");
    Console.WriteLine($"EVIDENCE {evidencePath}");
    Console.WriteLine(ok ? "PASS" : "FAIL");
    return ok;
}

static BagCleanupConfig CloneBagCleanupConfig(BagCleanupConfig source)
{
    return new BagCleanupConfig
    {
        Mode = source.Mode,
        OpenBagBeforeScan = source.OpenBagBeforeScan,
        OpenBagHotkey = source.OpenBagHotkey,
        OpenBagHotkeyExplicitlyConfigured = source.OpenBagHotkeyExplicitlyConfigured,
        AllowActualSell = source.AllowActualSell,
        MinFreeSlotsWarning = source.MinFreeSlotsWarning,
        Grid = new InventoryGridConfig
        {
            ScanMode = source.Grid.ScanMode,
            Enabled = source.Grid.Enabled,
            X = source.Grid.X,
            Y = source.Grid.Y,
            Columns = source.Grid.Columns,
            Rows = source.Grid.Rows,
            CellWidth = source.Grid.CellWidth,
            CellHeight = source.Grid.CellHeight,
            GapX = source.Grid.GapX,
            GapY = source.Grid.GapY,
            SlotNameOverrides = new Dictionary<int, string>(source.Grid.SlotNameOverrides),
            SlotNameSources = new Dictionary<int, string>(source.Grid.SlotNameSources)
        },
        Policy = new ItemPolicyConfig
        {
            KeepItems = source.Policy.KeepItems.ToList(),
            StoreItems = source.Policy.StoreItems.ToList(),
            TradeItems = source.Policy.TradeItems.ToList(),
            SellKeywords = source.Policy.SellKeywords.ToList(),
            BlockKeywords = source.Policy.BlockKeywords.ToList(),
            RequireExplicitSellKeyword = source.Policy.RequireExplicitSellKeyword,
            ProtectUnknownItems = source.Policy.ProtectUnknownItems
        },
        TemplateMatching = new BagItemTemplateMatchConfig
        {
            Enabled = source.TemplateMatching.Enabled,
            IndexPath = source.TemplateMatching.IndexPath,
            Threshold = source.TemplateMatching.Threshold,
            InnerPadding = source.TemplateMatching.InnerPadding
        }
    };
}

static BagCleanupService CreateBagCleanupService(ILogService log, IInputService input, CaptureResult capture)
{
    var captureService = new StaticClientCaptureService(capture);
    var inventory = new InventoryRecognitionService(captureService, log);
    var policy = new ItemPolicyService(log);
    var templates = new BagItemTemplateMatchService(inventory, log);
    return new BagCleanupService(inventory, policy, input, log, captureService, templates);
}

static string CreateSyntheticBagTemplateIndex(
    CaptureResult capture,
    int x,
    int y,
    int width,
    int height,
    string itemName,
    string policy)
{
    var icon = CropCaptureRect(capture, x, y, width, height)
               ?? throw new InvalidOperationException("Synthetic bag template crop failed.");
    var dir = Path.Combine(
        Environment.CurrentDirectory,
        "artifacts",
        "bag-cleanup-diagnostics",
        DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture));
    Directory.CreateDirectory(dir);
    var indexPath = Path.Combine(dir, "template-index.json");
    var imageFileName = "synthetic-slot-template.png";
    var imagePath = Path.Combine(dir, imageFileName);
    if (!SaveCapturePng(icon, imagePath))
        throw new InvalidOperationException("Synthetic bag template image save failed.");
    var imageSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(imagePath))).ToLowerInvariant();
    var document = new
    {
        libraryId = "item_assets_v1",
        runtimeSellAuthorized = false,
        safetyDefault = "unknown_protected",
        templates = new[]
        {
            new
            {
                id = "synthetic-slot-template",
                itemName,
                policy,
                image = new
                {
                    path = imageFileName,
                    sha256 = imageSha256,
                    averageHash = ComputeAverageHash64(icon)
                }
            }
        }
    };

    File.WriteAllText(
        indexPath,
        System.Text.Json.JsonSerializer.Serialize(document, JsonOptions()),
        new UTF8Encoding(false));
    return indexPath;
}

static CaptureResult CreateSyntheticBagCapture()
{
    const int width = 180;
    const int height = 140;
    var pixels = new byte[width * height * 4];
    for (var i = 0; i < pixels.Length; i += 4)
    {
        pixels[i] = 18;
        pixels[i + 1] = 18;
        pixels[i + 2] = 18;
        pixels[i + 3] = 255;
    }

    for (var row = 0; row < 2; row++)
    {
        for (var col = 0; col < 3; col++)
        {
            var x = 20 + col * 36;
            var y = 30 + row * 36;
            FillRect(pixels, width, x, y, 32, 32, 24, 22, 18);
            DrawBorder(pixels, width, x, y, 32, 32, 118, 90, 38);
        }
    }

    FillIcon(pixels, width, 20, 30, 32, 32, 150, 40, 190);
    FillIcon(pixels, width, 56, 30, 32, 32, 190, 120, 30);
    FillIcon(pixels, width, 20, 66, 32, 32, 40, 160, 210);
    return new CaptureResult(width, height, pixels);
}

static CaptureResult CreateSyntheticBagV3Capture()
{
    const int width = 460;
    const int height = 340;
    const int gridX = 50;
    const int gridY = 70;
    const int cellSize = 32;
    const int gap = 4;
    var pixels = new byte[width * height * 4];
    for (var i = 0; i < pixels.Length; i += 4)
    {
        pixels[i] = 18;
        pixels[i + 1] = 18;
        pixels[i + 2] = 18;
        pixels[i + 3] = 255;
    }

    for (var row = 0; row < 6; row++)
    {
        for (var col = 0; col < 10; col++)
        {
            var x = gridX + col * (cellSize + gap);
            var y = gridY + row * (cellSize + gap);
            FillRect(pixels, width, x, y, cellSize, cellSize, 24, 22, 18);
            DrawBorder(pixels, width, x, y, cellSize, cellSize, 118, 90, 38);
        }
    }

    FillIcon(pixels, width, gridX, gridY, cellSize, cellSize, 150, 40, 190);
    FillIcon(pixels, width, gridX + cellSize + gap, gridY, cellSize, cellSize, 190, 120, 30);
    FillIcon(pixels, width, gridX, gridY + cellSize + gap, cellSize, cellSize, 40, 160, 210);
    return new CaptureResult(width, height, pixels)
    {
        Sequence = 8801001,
        CaptureSource = "diagnostic-bag-v3"
    };
}

static void FillIcon(byte[] pixels, int imageWidth, int x, int y, int width, int height, byte r, byte g, byte b)
{
    for (var yy = y + 4; yy < y + height - 4; yy++)
    {
        for (var xx = x + 4; xx < x + width - 4; xx++)
        {
            var mix = (byte)((xx + yy) % 60);
            var p = (yy * imageWidth + xx) * 4;
            pixels[p] = (byte)Math.Clamp(b + mix, 0, 255);
            pixels[p + 1] = (byte)Math.Clamp(g + mix / 2, 0, 255);
            pixels[p + 2] = (byte)Math.Clamp(r + mix / 3, 0, 255);
            pixels[p + 3] = 255;
        }
    }
}

static void FillRect(byte[] pixels, int imageWidth, int x, int y, int width, int height, byte r, byte g, byte b)
{
    for (var yy = y; yy < y + height; yy++)
    {
        for (var xx = x; xx < x + width; xx++)
        {
            var p = (yy * imageWidth + xx) * 4;
            pixels[p] = b;
            pixels[p + 1] = g;
            pixels[p + 2] = r;
            pixels[p + 3] = 255;
        }
    }
}

static void DrawBorder(byte[] pixels, int imageWidth, int x, int y, int width, int height, byte r, byte g, byte b)
{
    FillRect(pixels, imageWidth, x, y, width, 1, r, g, b);
    FillRect(pixels, imageWidth, x, y + height - 1, width, 1, r, g, b);
    FillRect(pixels, imageWidth, x, y, 1, height, r, g, b);
    FillRect(pixels, imageWidth, x + width - 1, y, 1, height, r, g, b);
}

static async Task<bool> RunReturnPointDiagnostics()
{
    Console.WriteLine("ReturnPoint diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var returnPoints = new ReturnPointService(profiles, log);

    var routePath = FindImportedHorseRouteFile();
    if (routePath is null)
    {
        Console.Error.WriteLine("FAIL: missing local route file.");
        return false;
    }

    var imported = returnPoints.ImportLegacyIni(routePath, "本地坐标");
    Console.WriteLine($"Imported maps={imported.MapCount}");
    Console.WriteLine($"Imported points={imported.PointCount}");
    Console.WriteLine($"Skipped={imported.SkippedCount}");

    returnPoints.AddPoint(new ReturnPoint
    {
        MapName = "诊断地图",
        X = 50,
        Y = 50,
        Label = "manual-diagnostic",
        Kind = ReturnPointKind.FixedFarm,
        SourceModule = "diagnostic",
        SourcePath = "manual"
    });
    var countBeforeSave = returnPoints.Current.Points.Count;
    returnPoints.Save("return-point-diagnostic");
    returnPoints.Clear();
    var loaded = returnPoints.Load("return-point-diagnostic");
    var persisted = loaded && returnPoints.Current.Points.Count == countBeforeSave;

    Console.WriteLine($"Loaded={loaded}");
    Console.WriteLine($"Persisted points={returnPoints.Current.Points.Count}");

    var sceneStateResult = RunReturnPointSceneStateScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F5";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
        });

    var missingMapResult = RunReturnPointSceneStateScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F5";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
        });

    var missingCoordinateResult = RunReturnPointSceneStateScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "", null, null),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.EnableStuckRecovery = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F5";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
            cfg.StuckRecoveryNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.StuckRecoveryNavigation.Hotkey = "F7";
            cfg.StuckRecoveryNavigation.ActionIntervalMs = 200;
        });

    var unstableCoordinateResult = RunReturnPointSequenceScenario(
        returnPoints,
        log,
        currents:
        [
            new NavigationRecognitionResult("诊断地图", "2,41", 2, 41),
            new NavigationRecognitionResult("诊断地图", "2,41", 2, 41),
            new NavigationRecognitionResult("诊断地图", "41,28", 41, 28)
        ],
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F5";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
        });

    var confirmedMapResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.NavigationRecognition.ConfirmedMapName = "诊断地图";
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F5";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
        });

    var fixedResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
            cfg.ReturnNavigation.Hotkey = "F9";
            cfg.ReturnNavigation.ClickX = 520;
            cfg.ReturnNavigation.ClickY = 360;
            cfg.ReturnNavigation.ActionIntervalMs = 200;
        });

    var recordedResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.RecordedClientClickSequence;
            cfg.ReturnNavigation.DispatchMode = InputDispatchMode.PostMessage;
            cfg.ReturnNavigation.ActionIntervalMs = 200;
            cfg.ReturnNavigation.RecordedSourceEvidencePath = "diagnostic-record.json";
            cfg.ReturnNavigation.RecordedSourceClientSize = "1024x768";
            cfg.ReturnNavigation.RecordedBeforeMap = "诊断地图";
            cfg.ReturnNavigation.RecordedBeforeX = 10;
            cfg.ReturnNavigation.RecordedBeforeY = 10;
            cfg.ReturnNavigation.RecordedAfterMap = "诊断地图";
            cfg.ReturnNavigation.RecordedAfterX = 50;
            cfg.ReturnNavigation.RecordedAfterY = 50;
            cfg.ReturnNavigation.RecordedTargetX = 50;
            cfg.ReturnNavigation.RecordedTargetY = 50;
            cfg.ReturnNavigation.RecordedMovedCloserToTarget = true;
            cfg.ReturnNavigation.RecordedArrivedAtTarget = true;
            cfg.ReturnNavigation.RecordedClicks.Clear();
            cfg.ReturnNavigation.RecordedClicks.Add(new RecordedNavigationClick
            {
                ClientX = 410,
                ClientY = 260,
                Button = InputMouseButton.Left,
                DelayAfterMs = 20,
                SourceEvidencePath = "diagnostic-record.json"
            });
            cfg.ReturnNavigation.RecordedClicks.Add(new RecordedNavigationClick
            {
                ClientX = 430,
                ClientY = 280,
                Button = InputMouseButton.Right,
                DelayAfterMs = 20,
                SourceEvidencePath = "diagnostic-record.json"
            });
        });

    var invalidRecordedResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.RecordedClientClickSequence;
            cfg.ReturnNavigation.DispatchMode = InputDispatchMode.PostMessage;
            cfg.ReturnNavigation.ActionIntervalMs = 200;
            cfg.ReturnNavigation.RecordedClicks.Clear();
            cfg.ReturnNavigation.RecordedClicks.Add(new RecordedNavigationClick
            {
                ClientX = 410,
                ClientY = 260,
                Button = InputMouseButton.Left,
                DelayAfterMs = 20,
                SourceEvidencePath = "diagnostic-unverified-record.json"
            });
        });

    var earthResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableEarthSpiritReturn = true;
