            cfg.DeathReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.DeathReturnNavigation.Hotkey = "F8";
            cfg.DeathReturnNavigation.ActionIntervalMs = 200;
        });

    var deathWithoutPointResult = RunDeathReturnWithoutPointScenario(returnPoints, log);

    var retryStuckResult = RunReturnPointScenario(
        returnPoints,
        log,
        current: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        death: new DeathRecognitionResult(false, "", ""),
        configure: cfg =>
        {
            ResetScenarioConfig(cfg);
            cfg.EnableFixedFarmReturn = true;
            cfg.EnableStuckRecovery = true;
            cfg.ReturnRetryLimit = 1;
            cfg.ReturnNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.ReturnNavigation.Hotkey = "F6";
            cfg.ReturnNavigation.ActionIntervalMs = 200;
            cfg.StuckRecoveryNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
            cfg.StuckRecoveryNavigation.Hotkey = "F7";
            cfg.StuckRecoveryNavigation.ActionIntervalMs = 200;
        });

    var timeoutStuck = await RunReturnPointTimeoutStuckScenario(returnPoints, log);
    var resumeAfterArrival = RunReturnPointResumeAfterArrivalScenario(returnPoints, log);
    var progressHold = RunReturnPointProgressHoldScenario(returnPoints, log);
    var captureConfirmedMap = RunReturnPointCaptureConfirmedMapScenario(log);
    var captureMissingMap = RunReturnPointCaptureMissingMapScenario(log);
    var capturePreview = RunReturnPointCapturePreviewScenario(log);
    var singleMapAutoConfirm = RunReturnPointSingleMapAutoConfirmScenario(log);
    var multiMapAutoConfirmBlocked = RunReturnPointMultiMapAutoConfirmBlockedScenario(log);
    var legacyNormalization = RunReturnPointLegacyNormalizationScenario(log);

    Console.WriteLine($"Scene-state action={sceneStateResult.Result.Action}, calls={sceneStateResult.SceneStateCalls}, hotkeys={string.Join(",", sceneStateResult.Input.SentHotkeys)}");
    Console.WriteLine($"Missing-map action={missingMapResult.Result.Action}, suspend={missingMapResult.Result.ShouldSuspendCombat}, send={missingMapResult.Input.SendKeyCount}, click={missingMapResult.Input.ClickCount}");
    Console.WriteLine($"Missing-coordinate action={missingCoordinateResult.Result.Action}, suspend={missingCoordinateResult.Result.ShouldSuspendCombat}, send={missingCoordinateResult.Input.SendKeyCount}, click={missingCoordinateResult.Input.ClickCount}, message={missingCoordinateResult.Result.Message}");
    Console.WriteLine($"Unstable-coordinate action={unstableCoordinateResult.Result.Action}, calls={unstableCoordinateResult.SceneStateCalls}, send={unstableCoordinateResult.Input.SendKeyCount}, click={unstableCoordinateResult.Input.ClickCount}, message={unstableCoordinateResult.Result.Message}");
    Console.WriteLine($"Confirmed-map action={confirmedMapResult.Result.Action}, send={confirmedMapResult.Input.SendKeyCount}, hotkeys={string.Join(",", confirmedMapResult.Input.SentHotkeys)}");
    Console.WriteLine($"Capture confirmed-map success={captureConfirmedMap.Success}, map={captureConfirmedMap.Point?.MapName ?? "-"}, coord={captureConfirmedMap.Point?.X},{captureConfirmedMap.Point?.Y}");
    Console.WriteLine($"Capture preview success={capturePreview.Preview.Success}, afterPreview={capturePreview.AfterPreviewCount}, captureSuccess={capturePreview.Capture.Success}, afterCapture={capturePreview.AfterCaptureCount}");
