    Console.WriteLine($"Earth action={earthResult.Result.Action}, send={earthResult.Input.SendKeyCount}");
    Console.WriteLine($"Death action={deathResult.Result.Action}, send={deathResult.Input.SendKeyCount}");
    Console.WriteLine($"Death-without-point action={deathWithoutPointResult.Result.Action}, send={deathWithoutPointResult.Input.SendKeyCount}, hotkeys={string.Join(",", deathWithoutPointResult.Input.SentHotkeys)}");
    Console.WriteLine($"Retry stuck action={retryStuckResult.Result.Action}, hotkeys={string.Join(",", retryStuckResult.Input.SentHotkeys)}");
    Console.WriteLine($"Timeout stuck action={timeoutStuck.Result.Action}, hotkeys={string.Join(",", timeoutStuck.Input.SentHotkeys)}");
    Console.WriteLine($"Resume-after-arrival return={resumeAfterArrival.ReturnResult.Action}/{resumeAfterArrival.ReturnResult.ShouldSuspendCombat}, final={resumeAfterArrival.FinalResult.Action}/{resumeAfterArrival.FinalResult.ShouldSuspendCombat}, hotkeys={string.Join(",", resumeAfterArrival.Input.SentHotkeys)}, sceneCalls={resumeAfterArrival.SceneStateCalls}");
    Console.WriteLine($"Progress-hold return={progressHold.ReturnResult.Action}/{progressHold.ReturnResult.ShouldSuspendCombat}, hold={progressHold.HoldResult.Action}/{progressHold.HoldResult.ShouldSuspendCombat}, hotkeys={string.Join(",", progressHold.Input.SentHotkeys)}, sceneCalls={progressHold.SceneStateCalls}, message={progressHold.HoldResult.Message}");
    Console.WriteLine($"Capture missing-map success={captureMissingMap.Success}, point={captureMissingMap.Point?.MapName ?? "-"}, message={captureMissingMap.Message}");
    Console.WriteLine($"Legacy normalization ok={legacyNormalization.Ok}, check={legacyNormalization.CheckIntervalMs}, arrival={legacyNormalization.ArrivalDistance}, stuck={legacyNormalization.StuckTimeoutMs}, retry={legacyNormalization.ReturnRetryLimit}, travelWait={legacyNormalization.ReturnTravelWaitMs}");

    var ok = imported.MapCount > 0
             && imported.PointCount > 0
             && imported.SkippedCount == 0
             && persisted
             && sceneStateResult.Result.Action == ReturnPointRuntimeAction.ReturnToPoint
             && sceneStateResult.SceneStateCalls == 3
             && sceneStateResult.Input.SentHotkeys.Contains("F5", StringComparer.OrdinalIgnoreCase)
             && missingMapResult.Result.Action == ReturnPointRuntimeAction.MissingNavigation
             && !missingMapResult.Result.ShouldSuspendCombat
             && missingMapResult.Input.SendKeyCount == 0
             && missingMapResult.Input.ClickCount == 0
             && missingCoordinateResult.Result.Action == ReturnPointRuntimeAction.MissingNavigation
             && !missingCoordinateResult.Result.ShouldSuspendCombat
             && missingCoordinateResult.Input.SendKeyCount == 0
             && missingCoordinateResult.Input.ClickCount == 0
             && missingCoordinateResult.Result.Message.Contains("禁止触发自动回点", StringComparison.Ordinal)
             && unstableCoordinateResult.Result.Action == ReturnPointRuntimeAction.MissingNavigation
             && !unstableCoordinateResult.Result.ShouldSuspendCombat
             && unstableCoordinateResult.Input.SendKeyCount == 0
             && unstableCoordinateResult.Input.ClickCount == 0
             && (unstableCoordinateResult.Result.Message.Contains("等待稳定", StringComparison.Ordinal)
                 || unstableCoordinateResult.Result.Message.Contains("坐标跳变", StringComparison.Ordinal))
             && confirmedMapResult.Result.Action == ReturnPointRuntimeAction.MissingNavigation
             && confirmedMapResult.Input.SendKeyCount == 0
             && confirmedMapResult.Input.ClickCount == 0
             && captureConfirmedMap is { Success: true, Point.MapName: "诊断地图", Point.X: 15, Point.Y: 25 }
             && capturePreview.Preview is { Success: true, Point.MapName: "诊断地图", Point.X: 18, Point.Y: 28 }
             && capturePreview.AfterPreviewCount == capturePreview.BeforeCount
             && capturePreview.Capture is { Success: true, Point.MapName: "诊断地图", Point.X: 18, Point.Y: 28 }
             && capturePreview.AfterCaptureCount == capturePreview.BeforeCount + 1
             && captureMissingMap is { Success: false, Point: null }
             && captureMissingMap.Message.Contains("未稳定识别到当前地图名", StringComparison.Ordinal)
             && singleMapAutoConfirm.ConfirmedMap == "诊断地图"
             && singleMapAutoConfirm.Result.Action == ReturnPointRuntimeAction.MissingNavigation
             && singleMapAutoConfirm.Input.SendKeyCount == 0
             && singleMapAutoConfirm.Input.ClickCount == 0
             && multiMapAutoConfirmBlocked.Blocked
             && string.IsNullOrWhiteSpace(multiMapAutoConfirmBlocked.ConfirmedMap)
             && fixedResult.Result.Action == ReturnPointRuntimeAction.ReturnToPoint
             && fixedResult.Result.ShouldSuspendCombat
             && fixedResult.Input.SendKeyCount == 1
             && fixedResult.Input.ClickCount == 1
             && recordedResult.Result.Action == ReturnPointRuntimeAction.ReturnToPoint
             && recordedResult.Result.ShouldSuspendCombat
             && recordedResult.Input.SendKeyCount == 0
             && recordedResult.Input.ClickCount == 2
             && recordedResult.Input.Clicks[0] is { X: 410, Y: 260, Button: InputMouseButton.Left }
             && recordedResult.Input.Clicks[1] is { X: 430, Y: 280, Button: InputMouseButton.Right }
             && invalidRecordedResult.Result.Action == ReturnPointRuntimeAction.ReturnToPoint
             && !invalidRecordedResult.Result.ShouldSuspendCombat
             && invalidRecordedResult.Input.SendKeyCount == 0
             && invalidRecordedResult.Input.ClickCount == 0
             && invalidRecordedResult.Result.Message.Contains("没有通过靠近/到达验证", StringComparison.Ordinal)
             && earthResult.Result.Action == ReturnPointRuntimeAction.EarthSpiritReturn
             && earthResult.Input.SentHotkeys.Contains("F10", StringComparer.OrdinalIgnoreCase)
             && deathResult.Result.Action == ReturnPointRuntimeAction.DeathReturn
             && deathResult.Input.SentHotkeys.Contains("F8", StringComparer.OrdinalIgnoreCase)
             && deathWithoutPointResult.Result.Action == ReturnPointRuntimeAction.DeathReturn
             && deathWithoutPointResult.Input.SentHotkeys.Contains("F8", StringComparer.OrdinalIgnoreCase)
             && retryStuckResult.Result.Action == ReturnPointRuntimeAction.StuckRecovery
             && retryStuckResult.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
             && timeoutStuck.Result.Action == ReturnPointRuntimeAction.StuckRecovery
             && timeoutStuck.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
             && resumeAfterArrival.ReturnResult.Action == ReturnPointRuntimeAction.ReturnToPoint
             && resumeAfterArrival.ReturnResult.ShouldSuspendCombat
             && resumeAfterArrival.FinalResult.Action == ReturnPointRuntimeAction.InRange
             && !resumeAfterArrival.FinalResult.ShouldSuspendCombat
             && resumeAfterArrival.Input.SentHotkeys.Count(h => string.Equals(h, "F5", StringComparison.OrdinalIgnoreCase)) == 1
             && progressHold.ReturnResult.Action == ReturnPointRuntimeAction.ReturnToPoint
             && progressHold.ReturnResult.ShouldSuspendCombat
             && progressHold.HoldResult.Action == ReturnPointRuntimeAction.ReturnToPoint
             && progressHold.HoldResult.ShouldSuspendCombat
             && progressHold.HoldResult.Message.Contains("等待", StringComparison.Ordinal)
             && progressHold.Input.SentHotkeys.Count(h => string.Equals(h, "F5", StringComparison.OrdinalIgnoreCase)) == 1
             && legacyNormalization.Ok;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: return-point import/runtime paths did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static (ReturnPointRuntimeResult Result, CountingInputService Input, int SceneStateCalls) RunReturnPointSceneStateScenario(
    ReturnPointService returnPoints,
    ILogService log,
    NavigationRecognitionResult current,
    DeathRecognitionResult death,
    Action<ReturnPointConfig> configure)
{
    ConfigureDiagnosticPoint(returnPoints);
    configure(returnPoints.Current);

    var input = new CountingInputService();
    var sceneState = new StaticSceneStateService(current);
    var runtime = new ReturnPointRuntimeService(
        returnPoints,
        sceneState,
        new StaticDeathRecognitionService(death),
        new ReturnNavigationService(input, log),
        log);

    runtime.Reset();
    var result = EvaluateReturnPointRuntime(runtime, DiagnosticWindow(new nint(4300), "return-point-scene-state-runtime"), death.IsDead ? 1 : 3);
    return (result, input, sceneState.CallCount);
}

static (ReturnPointRuntimeResult Result, CountingInputService Input, int SceneStateCalls) RunReturnPointSequenceScenario(
    ReturnPointService returnPoints,
    ILogService log,
    IReadOnlyList<NavigationRecognitionResult> currents,
    DeathRecognitionResult death,
    Action<ReturnPointConfig> configure)
{
    ConfigureDiagnosticPoint(returnPoints);
    configure(returnPoints.Current);

    var input = new CountingInputService();
    var sceneState = new SequenceSceneStateService(currents);
    var runtime = new ReturnPointRuntimeService(
        returnPoints,
        sceneState,
        new StaticDeathRecognitionService(death),
        new ReturnNavigationService(input, log),
        log);

    runtime.Reset();
    var result = EvaluateReturnPointRuntime(runtime, DiagnosticWindow(new nint(4304), "return-point-sequence-runtime"), currents.Count);
    return (result, input, sceneState.CallCount);
}

static (ReturnPointRuntimeResult Result, CountingInputService Input) RunReturnPointScenario(
    ReturnPointService returnPoints,
    ILogService log,
    NavigationRecognitionResult current,
    DeathRecognitionResult death,
    Action<ReturnPointConfig> configure)
{
    ConfigureDiagnosticPoint(returnPoints);
    configure(returnPoints.Current);

    var input = new CountingInputService();
    var runtime = new ReturnPointRuntimeService(
        returnPoints,
        new NavigationSceneStateService(new StaticNavigationRecognitionService(current)),
        new StaticDeathRecognitionService(death),
        new ReturnNavigationService(input, log),
        log);

    runtime.Reset();
    var result = EvaluateReturnPointRuntime(runtime, DiagnosticWindow(new nint(4301), "return-point-runtime"), death.IsDead ? 1 : 3);
    return (result, input);
}

