static ReturnPointRuntimeResult EvaluateReturnPointRuntime(ReturnPointRuntimeService runtime, BoundGameWindow window, int count)
{
    var result = new ReturnPointRuntimeResult(ReturnPointRuntimeAction.None, false, "not evaluated");
    for (var i = 0; i < Math.Max(1, count); i++)
        result = runtime.Evaluate(window);

    return result;
}

