static (bool Ok, int CheckIntervalMs, int ArrivalDistance, int StuckTimeoutMs, int ReturnRetryLimit, int ReturnTravelWaitMs) RunReturnPointLegacyNormalizationScenario(ILogService log)
{
    var profiles = new MemoryProfileService();
    profiles.Save("return-points-legacy-zero", """
{
  "ProfileName": "legacy-zero",
  "CheckIntervalMs": 0,
  "ArrivalDistance": 0,
  "StuckTimeoutMs": 0,
  "ReturnRetryLimit": 0,
  "ReturnTravelWaitMs": 0,
  "NavigationRecognition": {},
  "DeathRecognition": {},
  "ReturnNavigation": {},
  "EarthSpiritNavigation": {},
  "StuckRecoveryNavigation": {},
  "DeathReturnNavigation": {},
  "Points": []
}
""");

    var returnPoints = new ReturnPointService(profiles, log);
    var loaded = returnPoints.Load("legacy-zero");
    var cfg = returnPoints.Current;
    var ok = loaded
             && cfg.CheckIntervalMs == 1000
             && cfg.ArrivalDistance == 8
             && cfg.StuckTimeoutMs == 15000
             && cfg.ReturnRetryLimit == 3
             && cfg.ReturnTravelWaitMs == 8000
             && cfg.NavigationRecognition.MapName.Width > 0
             && cfg.NavigationRecognition.Coordinate.Width > 0
             && cfg.DeathRecognition.PromptRegion.Width > 0;

    return (ok, cfg.CheckIntervalMs, cfg.ArrivalDistance, cfg.StuckTimeoutMs, cfg.ReturnRetryLimit, cfg.ReturnTravelWaitMs);
}

