static void ResetScenarioConfig(ReturnPointConfig cfg)
{
    cfg.EnableFixedFarmReturn = false;
    cfg.EnableEarthSpiritReturn = false;
    cfg.EnableDeathReturn = false;
    cfg.EnableStuckRecovery = false;
    cfg.CheckIntervalMs = 200;
    cfg.ArrivalDistance = 3;
    cfg.StuckTimeoutMs = 1000;
    cfg.ReturnRetryLimit = 3;
    cfg.ReturnTravelWaitMs = 5000;
    cfg.NavigationRecognition.ConfirmedMapName = "";
    cfg.ReturnNavigation = new ReturnNavigationConfig();
    cfg.EarthSpiritNavigation = new ReturnNavigationConfig();
    cfg.StuckRecoveryNavigation = new ReturnNavigationConfig();
    cfg.DeathReturnNavigation = new ReturnNavigationConfig();
}

static string? FindImportedHorseRouteFile()
{
    var routeDir = Path.Combine(Environment.CurrentDirectory, "data", "imported", "routes");
    if (!Directory.Exists(routeDir))
        return null;

    return Directory.GetFiles(routeDir, "*.ini")
        .FirstOrDefault(path => Path.GetFileName(path).Equals("route-points-a.ini", StringComparison.OrdinalIgnoreCase));
}

static async Task<bool> RunHorseBanditDiagnostics()
{
    Console.WriteLine("HorseBandit diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var global = new TestGlobalConfigService();
    var config = new HorseBanditConfigService(profiles, log);

    var memberConfig = FindImportedLegacyConfigFile("follow-a");
    var horseConfig = FindImportedLegacyConfigFile("horse-a");
    var routePath = FindImportedHorseRouteFile();
    if (memberConfig is null || horseConfig is null || routePath is null)
    {
        Console.Error.WriteLine("FAIL: missing local config or route files.");
        return false;
    }

    var memberImport = config.ImportLegacyConfig(memberConfig, "跟随配置");
    var horseImport = config.ImportLegacyConfig(horseConfig, "找马配置");
    var routeImport = config.ImportLegacyRoutes(routePath, "本地坐标");
    config.Save("horse-bandit-diagnostic");
    var loaded = config.Load("horse-bandit-diagnostic");

    Console.WriteLine($"Member config fields={memberImport.FieldCount}");
    Console.WriteLine($"Horse config fields={horseImport.FieldCount}");
    Console.WriteLine($"Route maps={routeImport.RouteMapCount}");
    Console.WriteLine($"Route points={routeImport.RoutePointCount}");
    Console.WriteLine($"Loaded={loaded}");

    var targetScenario = await RunHorseBanditScenario(
        config,
        global,
        log,
        recognition: new HorseBanditRecognitionResult("", "", "", null, false, false),
        combat: new CombatRecognitionResult("夺宝马贼", "", "", "", "", 50, null, null, null),
        navigation: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        configure: cfg =>
        {
            cfg.EnableAutoFollow = false;
            cfg.EnableTeamCheck = false;
            cfg.Role = HorseBanditRole.Member;
            cfg.TargetKeywords = "马贼;马贼喽啰;夺宝马贼;小丹;天降奇兽";
            cfg.SearchHotkey = "F3";
            cfg.AttackHotkey = "F4";
            cfg.ScanIntervalMs = 200;
            cfg.AttackIntervalMs = 200;
            cfg.UseBuiltInRoutes = false;
            cfg.UseCustomRoutes = false;
        },
        delayMs: 350);

    var playerProtectedScenario = await RunHorseBanditScenario(
        config,
        global,
        log,
        recognition: new HorseBanditRecognitionResult("", "", "", null, false, false),
        combat: new CombatRecognitionResult("夺宝马贼", "", "", "", "", 80, null, null, null)
        {
            TargetLooksLikePlayer = true
        },
        navigation: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        configure: cfg =>
        {
            global.Current.Targeting.BlockPlayerTargets = true;
            cfg.EnableAutoFollow = false;
            cfg.EnableTeamCheck = false;
            cfg.Role = HorseBanditRole.Member;
            cfg.TargetKeywords = "马贼;马贼喽啰;夺宝马贼;小丹;天降奇兽";
            cfg.SearchHotkey = "F3";
            cfg.AttackHotkey = "F4";
            cfg.ScanIntervalMs = 200;
            cfg.AttackIntervalMs = 200;
            cfg.UseBuiltInRoutes = false;
            cfg.UseCustomRoutes = false;
        },
        delayMs: 350);

    var lostFollowScenario = await RunHorseBanditScenario(
        config,
        global,
        log,
        recognition: new HorseBanditRecognitionResult("队伍", "掉队", "90", 90, false, true),
        combat: new CombatRecognitionResult("", "", "", "", "", null, null, null, null),
        navigation: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        configure: cfg =>
        {
            cfg.EnableAutoFollow = true;
            cfg.EnableTeamCheck = true;
            cfg.Role = HorseBanditRole.Member;
            cfg.FollowHotkey = "F5";
            cfg.LostFollowDistance = 60;
            cfg.ScanIntervalMs = 200;
            cfg.RecoverDelayMs = 900;
            cfg.UseBuiltInRoutes = false;
            cfg.UseCustomRoutes = false;
        },
        delayMs: 350);

    var patrolScenario = await RunHorseBanditScenario(
        config,
        global,
        log,
        recognition: new HorseBanditRecognitionResult("", "", "", null, false, false),
        combat: new CombatRecognitionResult("", "", "", "", "", null, null, null, null),
        navigation: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        configure: cfg =>
        {
            cfg.EnableAutoFollow = false;
            cfg.EnableTeamCheck = false;
            cfg.SearchHotkey = "F6";
            cfg.ScanIntervalMs = 200;
            cfg.UseBuiltInRoutes = true;
            cfg.UseCustomRoutes = false;
            cfg.RoutePoints.Clear();
            cfg.RoutePoints.Add(new HorseBanditRoutePoint
            {
                MapName = "诊断地图",
                X = 80,
                Y = 80,
                SourceModule = "diagnostic",
                SourcePath = "runtime"
            });
            cfg.PatrolNavigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
            cfg.PatrolNavigation.Hotkey = "F7";
            cfg.PatrolNavigation.ClickX = 520;
            cfg.PatrolNavigation.ClickY = 360;
            cfg.PatrolNavigation.ActionIntervalMs = 200;
        },
        delayMs: 350);

    Console.WriteLine($"Target state={targetScenario.State}, hotkeys={string.Join(",", targetScenario.Input.SentHotkeys)}");
    Console.WriteLine($"Player-protected state={playerProtectedScenario.State}, hotkeys={string.Join(",", playerProtectedScenario.Input.SentHotkeys)}");
    Console.WriteLine($"Lost-follow state={lostFollowScenario.State}, hotkeys={string.Join(",", lostFollowScenario.Input.SentHotkeys)}");
    Console.WriteLine($"Patrol state={patrolScenario.State}, hotkeys={string.Join(",", patrolScenario.Input.SentHotkeys)}, clicks={patrolScenario.Input.ClickCount}");

    var ok = memberImport.FieldCount > 0
             && horseImport.FieldCount > 0
             && routeImport.RouteMapCount > 0
             && routeImport.RoutePointCount > 0
             && routeImport.SkippedCount == 0
             && loaded
             && targetScenario.State == nameof(HorseBanditState.WaitBattle)
             && targetScenario.Input.SentHotkeys.Contains("F4", StringComparer.OrdinalIgnoreCase)
             && playerProtectedScenario.State == nameof(HorseBanditState.SearchHorseBandit)
             && playerProtectedScenario.Input.SentHotkeys.Contains("F3", StringComparer.OrdinalIgnoreCase)
             && !playerProtectedScenario.Input.SentHotkeys.Contains("F4", StringComparer.OrdinalIgnoreCase)
             && lostFollowScenario.State == nameof(HorseBanditState.ReturnToFollow)
             && lostFollowScenario.Input.SentHotkeys.Contains("F5", StringComparer.OrdinalIgnoreCase)
             && patrolScenario.State == nameof(HorseBanditState.SearchHorseBandit)
             && patrolScenario.Input.SentHotkeys.Contains("F6", StringComparer.OrdinalIgnoreCase)
             && patrolScenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
             && patrolScenario.Input.ClickCount > 0;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: horse-bandit import/runtime paths did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static async Task<(string State, CountingInputService Input)> RunHorseBanditScenario(
    HorseBanditConfigService config,
    IGlobalConfigService global,
    ILogService log,
    HorseBanditRecognitionResult recognition,
    CombatRecognitionResult combat,
    NavigationRecognitionResult navigation,
    Action<HorseBanditConfig> configure,
    int delayMs)
{
    configure(config.Current);
    var input = new CountingInputService();
    var controller = new HorseBanditModeController(
        log,
        config,
        global,
        new StaticHorseBanditRecognitionService(recognition),
        new RecognitionPerceptionHub(new StaticCombatRecognitionService(combat)),
        new StaticNavigationRecognitionService(navigation),
        new ReturnNavigationService(input, log),
        input,
        new StateMachineEngine(log));

    controller.Attach(DiagnosticWindow(new nint(5401), "horse-bandit-runtime"));
    controller.Start();
    await Task.Delay(delayMs);
    var state = controller.CurrentStateName;
    controller.Stop();
    return (state, input);
}

static string? FindImportedLegacyConfigFile(string nameContains)
{
    var configDir = Path.Combine(Environment.CurrentDirectory, "data", "imported", "config-samples");
    if (!Directory.Exists(configDir))
        return null;

    return Directory.GetFiles(configDir, "*.ini")
        .FirstOrDefault(path => Path.GetFileName(path).Contains(nameContains, StringComparison.Ordinal));
}

static async Task<bool> RunNpcGrabDiagnostics()
{
    Console.WriteLine("NpcGrab diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var global = new TestGlobalConfigService();
    var config = new NpcGrabConfigService(profiles, log);

    var defaultTargets = config.Current.Targets.Count;
    var enabledTargets = config.EnabledTargets.Count;
    config.Save("npc-grab-diagnostic");
    config.Current.ScanHotkey = "F9";
    var loaded = config.Load("npc-grab-diagnostic");

    var rebel = SelectNpcTarget(global, log, config.Current, "造反恶贼");
    var small = SelectNpcTarget(global, log, config.Current, "江湖宵小");

    var unsafeConfig = new NpcGrabConfig();
    foreach (var target in unsafeConfig.Targets)
        target.Enabled = false;
    unsafeConfig.Targets.Add(new NpcGrabTargetConfig
    {
        Kind = NpcGrabTargetKind.Small,
        DisplayName = "unsafe-small",
        Enabled = true,
        Keywords = "小;丹",
        Priority = 1
    });
    var unsafeSingleChar = SelectNpcTarget(global, log, unsafeConfig, "小");

    var smallFast = new SmallNpcFastGrabService(log);
    var now = DateTime.Now;
    config.Current.SmallNpcFastGrab.RefreshMinuteMarks = now.Minute.ToString();
    config.Current.SmallNpcFastGrab.RefreshWindowBeforeSeconds = 60;
    config.Current.SmallNpcFastGrab.RefreshWindowAfterSeconds = 60;
    config.Current.SmallNpcFastGrab.BurstScanIntervalMs = 50;
    var burstPlan = smallFast.Plan(config.Current);
    smallFast.ObserveActionResult(small, new NpcActionResult(true, "diagnostic small success"));
    var contextPlan = smallFast.Plan(config.Current);

    var directInput = new CountingInputService();
    var directAction = new NpcActionService(directInput, log);
    config.Current.ScanHotkey = "Tab";
    config.Current.ActionHotkey = "F";
    config.Current.ActionMode = NpcGrabActionMode.HotkeyThenClickClientPoint;
    config.Current.ClickX = 520;
    config.Current.ClickY = 360;
    var scan = directAction.Scan(DiagnosticWindow(new nint(6201), "npc-grab-direct"), config.Current);
    var action = directAction.Execute(DiagnosticWindow(new nint(6202), "npc-grab-direct"), small, config.Current);

    var controllerInput = new CountingInputService();
    var controllerConfig = new NpcGrabConfigService(new MemoryProfileService(), log);
    controllerConfig.Current.ScanIntervalMs = 50;
    controllerConfig.Current.ClickIntervalMs = 1000;
    controllerConfig.Current.ScanHotkey = "Tab";
    controllerConfig.Current.ActionHotkey = "F";
    controllerConfig.Current.ActionMode = NpcGrabActionMode.HotkeyOnly;
    controllerConfig.Current.SmallNpcFastGrab.Strategy = SmallNpcGrabStrategy.AutoRecognizeOnly;
    var controller = new NpcGrabController(
        log,
        controllerConfig,
        new NpcTargetingService(new RecognitionPerceptionHub(new StaticCombatRecognitionService(new CombatRecognitionResult("江湖宵小", "", "", "", "", 100, null, null, null))), global, log),
        new NpcActionService(controllerInput, log),
        new SmallNpcFastGrabService(log),
        new StateMachineEngine(log));

    controller.Attach(DiagnosticWindow(new nint(6203), "npc-grab-controller"));
    controller.Start();
    await Task.Delay(250);
    var controllerState = controller.CurrentStateName;
    controller.Stop();

    Console.WriteLine($"Default targets={defaultTargets}");
    Console.WriteLine($"Enabled targets={enabledTargets}");
    Console.WriteLine($"Loaded={loaded}");
    Console.WriteLine($"Rebel matched={rebel.Found}, target={rebel.DisplayName}, keyword={rebel.MatchedKeyword}");
    Console.WriteLine($"Small matched={small.Found}, target={small.DisplayName}, keyword={small.MatchedKeyword}");
    Console.WriteLine($"Unsafe single-char matched={unsafeSingleChar.Found}");
    Console.WriteLine($"Small burst window={burstPlan.IsRefreshBurstWindow}");
    Console.WriteLine($"Small burst delay={burstPlan.NextScanDelayMs}");
    Console.WriteLine($"Context fast planned={contextPlan.ShouldExecuteContextFastAction}");
    Console.WriteLine($"Context fast target={contextPlan.ContextTarget?.DisplayName}");
    Console.WriteLine($"Scan executed={scan.Executed}");
    Console.WriteLine($"Action executed={action.Executed}");
    Console.WriteLine($"Direct input send-key calls={directInput.SendKeyCount}, clicks={directInput.ClickCount}");
    Console.WriteLine($"Controller state={controllerState}");
    Console.WriteLine($"Controller send-key calls={controllerInput.SendKeyCount}");

    var ok = defaultTargets == 9
             && enabledTargets >= 4
             && loaded
             && rebel is { Found: true, Kind: NpcGrabTargetKind.Rebel }
             && small is { Found: true, Kind: NpcGrabTargetKind.Small }
             && !unsafeSingleChar.Found
             && burstPlan.IsRefreshBurstWindow
             && burstPlan.NextScanDelayMs == 50
             && contextPlan.ShouldExecuteContextFastAction
             && contextPlan.ContextTarget?.Kind == NpcGrabTargetKind.Small2
             && scan.Executed
             && action.Executed
             && directInput.SendKeyCount == 2
             && directInput.ClickCount == 1
             && controllerState == nameof(NpcGrabState.Action)
             && controllerInput.SentHotkeys.Contains("Tab", StringComparer.OrdinalIgnoreCase)
             && controllerInput.SentHotkeys.Contains("F", StringComparer.OrdinalIgnoreCase);

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: npc-grab targeting/action/controller paths did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static NpcTargetingResult SelectNpcTarget(
    IGlobalConfigService global,
    ILogService log,
    NpcGrabConfig config,
    string recognizedTargetName)
{
    var targeting = new NpcTargetingService(
        new RecognitionPerceptionHub(new StaticCombatRecognitionService(new CombatRecognitionResult(recognizedTargetName, "", "", "", "", 100, null, null, null))),
        global,
        log);
    return targeting.SelectTarget(DiagnosticWindow(new nint(6200), "npc-grab-targeting"), config);
}

