static async Task<bool> RunDungeonDiagnostics()
{
    Console.WriteLine("Dungeon diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var global = new TestGlobalConfigService();
    var config = new DungeonConfigService(profiles, log);

    var oldSteps = config.Current.Steps.Count(s => s.Mode == DungeonMode.OldThreeRings);
    var newSteps = config.Current.Steps.Count(s => s.Mode == DungeonMode.NewThreeRings);
    config.Current.Mode = DungeonMode.NewThreeRings;
    config.Current.RunCount = 1;
    config.Current.TeamNumber = 2;
    config.Current.IGoLeftBridge = true;
    config.Current.NewThreeBoss2Position = DungeonBossPosition.Custom;
    config.Current.NewThreeBoss2CustomX = 600;
    config.Current.NewThreeBoss2CustomY = 400;
    config.Current.EnableClearBagAfterFinish = true;
    config.Current.ClearBagHotkey = "F9";
    config.Current.EnableChainNextTask = true;
    config.Current.ChainNextModeKey = "act.rebel";
    config.Current.StepIntervalMs = 50;
    config.Current.BattleCheckIntervalMs = 50;
    config.Current.StageNavigation.Mode = ReturnNavigationMode.HotkeyOnly;
    config.Current.StageNavigation.Hotkey = "F7";
    config.Current.StageNavigation.ActionIntervalMs = 200;
    foreach (var step in config.Current.Steps)
        step.DelayAfterMs = 50;
    var firstNewStep = config.Current.Steps
        .Where(s => s.Mode == DungeonMode.NewThreeRings)
        .OrderBy(s => s.Order)
        .First();
    firstNewStep.MapName = "诊断地图";
    firstNewStep.X = 80;
    firstNewStep.Y = 80;

    config.Save("dungeon-diagnostic");
    config.ResetDefaults();
    var loaded = config.Load("dungeon-diagnostic");

    var scenario = await RunDungeonScenario(
        config,
        global,
        log,
        combat: new CombatRecognitionResult("副本怪", "", "", "", "", 100, null, null, null),
        navigation: new NavigationRecognitionResult("诊断地图", "10,10", 10, 10),
        completionText: "副本结束",
        delayMs: 900);

    var chainLogs = log.Entries.Count(e => e.Module.Contains("三环", StringComparison.Ordinal) && e.Message.Contains("act.rebel", StringComparison.Ordinal));
    var completionLogs = log.Entries.Count(e => e.Message.Contains("副本结束", StringComparison.Ordinal));

    Console.WriteLine($"Old steps={oldSteps}");
    Console.WriteLine($"New steps={newSteps}");
    Console.WriteLine($"Loaded={loaded}");
    Console.WriteLine($"Current steps={config.CurrentSteps.Count}");
    Console.WriteLine($"Controller state={scenario.State}, run={scenario.RunState}");
    Console.WriteLine($"Hotkeys={string.Join(",", scenario.Input.SentHotkeys)}");
    Console.WriteLine($"Clicks={scenario.Input.ClickCount}");
    Console.WriteLine($"Completion logs={completionLogs}");
    Console.WriteLine($"Chain logs={chainLogs}");

    var ok = oldSteps == 3
             && newSteps == 5
             && loaded
             && config.CurrentSteps.Count == 5
             && scenario.State == nameof(DungeonState.Stop)
             && scenario.RunState == RunState.Stopped
             && scenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
             && scenario.Input.SentHotkeys.Contains("F8", StringComparer.OrdinalIgnoreCase)
             && scenario.Input.SentHotkeys.Contains("F1", StringComparer.OrdinalIgnoreCase)
             && scenario.Input.SentHotkeys.Contains("F9", StringComparer.OrdinalIgnoreCase)
             && scenario.Input.ClickCount >= 2
             && completionLogs > 0
             && chainLogs > 0;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: dungeon config/runtime paths did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

