static async Task<bool> RunLifeCollectDiagnostics()
{
    Console.WriteLine("LifeCollect diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var config = new LifeCollectConfigService(profiles, log);

    var routeDir = FindImportedLifeCollectRouteDirectory();
    if (routeDir is null)
    {
        Console.Error.WriteLine("FAIL: missing local route directory.");
        return false;
    }

    var imported = config.ImportLegacyDirectory(routeDir, "本地路线");
    var selectedMap = config.MapNames.FirstOrDefault(m => string.Equals(m, "无量山", StringComparison.Ordinal))
                      ?? config.MapNames.FirstOrDefault();
    if (selectedMap is null)
    {
        Console.Error.WriteLine("FAIL: imported life collect route directory has no usable points.");
        return false;
    }

    config.Current.MapName = selectedMap;
    config.Current.Mode = LifeCollectMode.Mining;
    config.Current.CollectHotkey = "F6";
    config.Current.ScanIntervalMs = 1000;
    config.Current.CollectIntervalMs = 1000;
    config.Current.ArrivalDistance = 6;
    config.Current.MaxPointRetry = 1;
    config.Current.EnableRouteNavigation = true;
    config.Current.ActionMode = LifeCollectActionMode.HotkeyThenClickClientPoint;
    config.Current.ActionClickX = 410;
    config.Current.ActionClickY = 330;
    config.Current.Navigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
    config.Current.Navigation.Hotkey = "F7";
    config.Current.Navigation.ClickX = 520;
    config.Current.Navigation.ClickY = 360;
    config.Current.Navigation.ActionIntervalMs = 200;

    config.Save("life-collect-diagnostic");
    config.Clear();
    var loaded = config.Load("life-collect-diagnostic");
    var route = config.CurrentRoute;
    if (route.Count == 0)
    {
        Console.Error.WriteLine("FAIL: selected life collect map has no route after save/load.");
        return false;
    }

    var firstPoint = route[0];
    var navigationScenario = await RunLifeCollectScenario(
        config,
        log,
        new NavigationRecognitionResult(firstPoint.MapName, $"{firstPoint.X + 100},{firstPoint.Y + 100}", firstPoint.X + 100, firstPoint.Y + 100),
        cfg =>
        {
            cfg.MapName = selectedMap;
            cfg.EnableRouteNavigation = true;
            cfg.ScanIntervalMs = 1000;
            cfg.CollectIntervalMs = 1000;
            cfg.ArrivalDistance = 1;
            cfg.Navigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
            cfg.Navigation.Hotkey = "F7";
            cfg.Navigation.ClickX = 520;
            cfg.Navigation.ClickY = 360;
            cfg.ActionMode = LifeCollectActionMode.HotkeyOnly;
            cfg.CollectHotkey = "F6";
        },
        delayMs: 250);

    var collectScenario = await RunLifeCollectScenario(
        config,
        log,
        new NavigationRecognitionResult(firstPoint.MapName, $"{firstPoint.X},{firstPoint.Y}", firstPoint.X, firstPoint.Y),
        cfg =>
        {
            cfg.MapName = selectedMap;
            cfg.EnableRouteNavigation = true;
            cfg.ScanIntervalMs = 1000;
            cfg.CollectIntervalMs = 1000;
            cfg.ArrivalDistance = 6;
            cfg.ActionMode = LifeCollectActionMode.HotkeyThenClickClientPoint;
            cfg.CollectHotkey = "F6";
            cfg.ActionClickX = 410;
            cfg.ActionClickY = 330;
        },
        delayMs: 250);

    Console.WriteLine($"Route directory found={Directory.Exists(routeDir)}");
    Console.WriteLine($"Imported maps={imported.MapCount}");
    Console.WriteLine($"Imported points={imported.PointCount}");
    Console.WriteLine($"Skipped={imported.Skipped}");
    Console.WriteLine($"Loaded={loaded}");
    Console.WriteLine($"Selected map={selectedMap}");
    Console.WriteLine($"Selected route points={route.Count}");
    Console.WriteLine($"Navigation state={navigationScenario.State}, hotkeys={string.Join(",", navigationScenario.Input.SentHotkeys)}, clicks={navigationScenario.Input.ClickCount}");
    Console.WriteLine($"Collect state={collectScenario.State}, hotkeys={string.Join(",", collectScenario.Input.SentHotkeys)}, clicks={collectScenario.Input.ClickCount}");

    var ok = imported.MapCount > 0
             && imported.PointCount > 0
             && imported.Skipped == 0
             && loaded
             && route.Count > 0
             && navigationScenario.State == nameof(LifeCollectState.NavigatePoint)
             && navigationScenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
             && navigationScenario.Input.ClickCount > 0
             && collectScenario.State == nameof(LifeCollectState.NextPoint)
             && collectScenario.Input.SentHotkeys.Contains("F6", StringComparer.OrdinalIgnoreCase)
             && collectScenario.Input.ClickCount > 0;

    if (!ok)
    {
        Console.Error.WriteLine("FAIL: life collect import/runtime paths did not meet expected behavior.");
        return false;
    }

    Console.WriteLine("PASS");
    return true;
}

static bool RunQuestionBankDiagnostics()
{
    Console.WriteLine("QuestionBank diagnostics");
    var root = Path.Combine(Path.GetTempPath(), "longbanxing-question-bank-" + Guid.NewGuid().ToString("N"));
    var init = new TempAppInitService(root);
    init.Initialize();

    try
    {
        var log = new RuntimeLogService();
        var service = new QuestionBankService(init, log);
        service.Load();

        var textPath = Path.Combine(root, "seed.txt");
        File.WriteAllText(textPath,
            "珍兽快乐度低会怎样=影响出战\n" +
            "洛阳驿站在哪里=洛阳城内\n",
            new UTF8Encoding(false));

        var imported = service.ImportFile(textPath);
        var search = service.Search("快乐度");
        var add = service.AddOrUpdate(new QuestionBankEntry
        {
            Question = "帮会任务每天能做几轮",
            Answer = "以游戏内任务为准",
            Category = "任务",
            Tags = "帮会;任务"
        });
        var secondSearch = service.Search("帮会");

        var exportPath = Path.Combine(root, "export.json");
        service.ExportJson(exportPath);
        var exportedEntries = File.Exists(exportPath)
            ? System.Text.Json.JsonSerializer.Deserialize<List<QuestionBankEntry>>(File.ReadAllText(exportPath)) ?? new()
            : new List<QuestionBankEntry>();
        var exported = exportedEntries.Any(e => e.Question.Contains("珍兽快乐度", StringComparison.Ordinal));

        var importedRoot = Path.Combine(Environment.CurrentDirectory, "data", "imported");
        var encryptedDetected = service.HasEncryptedSample(importedRoot);
        var encryptedPath = Directory.Exists(Path.Combine(importedRoot, "question-bank"))
            ? Directory.EnumerateFiles(Path.Combine(importedRoot, "question-bank"), "*.enc", SearchOption.TopDirectoryOnly).FirstOrDefault()
            : null;
        var encryptedRejected = encryptedPath is null || service.ImportFile(encryptedPath).UnsupportedEncrypted;

        Console.WriteLine($"Imported={imported.Imported}, updated={imported.Updated}, skipped={imported.Skipped}");
        Console.WriteLine($"Search hits={search.Count}, first answer={search.FirstOrDefault()?.Entry.Answer}");
        Console.WriteLine($"Manual id={add.Id}, second hits={secondSearch.Count}");
        Console.WriteLine($"Exported={exported}");
        Console.WriteLine($"Encrypted detected={encryptedDetected}, rejected={encryptedRejected}");

        var ok = imported.Imported == 2
                 && search.Count > 0
                 && search[0].Entry.Answer.Contains("出战", StringComparison.Ordinal)
                 && secondSearch.Count > 0
                 && exported
                 && encryptedDetected
                 && encryptedRejected;

        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }
    finally
    {
        try { Directory.Delete(root, recursive: true); }
        catch { }
    }
}

