}

static async Task<bool> RunMaterialCraftDiagnostics()
{
    Console.WriteLine("MaterialCraft diagnostics");
    var log = new RuntimeLogService();
    var profiles = new MemoryProfileService();
    var config = new MaterialCraftConfigService(profiles, log);
    var planFile = Path.Combine(Path.GetTempPath(), "longbanxing-craft-plan-" + Guid.NewGuid().ToString("N") + ".txt");
    await File.WriteAllTextAsync(planFile,
        "OpenPanel,,,F8,0,0,30\n" +
        "SelectRecipe,cloth,recipe-a,,520,360,30\n" +
        "Process,cloth,recipe-a,F9,540,380,30\n",
        new UTF8Encoding(false));

    try
    {
        var imported = config.ImportPlainPlan(planFile, "local-plan");
        config.Current.PlanName = "craft-diagnostic";
        config.Current.BatchCount = 2;
        config.Current.LoopPlan = false;
        config.Current.StopAfterBatch = true;
        config.Current.StepIntervalMs = 30;
        config.Current.MaxStepRetry = 1;
        config.Current.DispatchMode = InputDispatchMode.SendInput;
        // This branch intentionally verifies imported legacy plans only.
        // Production defaults keep RequireVisualConfirmation enabled.
        config.Current.RequireVisualConfirmation = false;
        config.Current.EnableCleanupAfterBatch = true;
        config.Current.CleanupHotkey = "F10";
        config.Current.CleanupClickX = 560;
        config.Current.CleanupClickY = 420;
        config.Current.CleanupWaitMs = 30;

        config.Save("craft-diagnostic");
        config.Clear();
        var loaded = config.Load("craft-diagnostic");

        var input = new CountingInputService();
        var controller = new MaterialCraftController(
            log,
            config,
            input,
            new StateMachineEngine(log));

        controller.Attach(DiagnosticWindow(new nint(6901), "material-craft-runtime"));
        controller.Start();
        await WaitForStopped(controller, 1500);
        var state = controller.CurrentStateName;
        var runState = controller.RunState;
        if (controller.RunState != RunState.Stopped)
            controller.Stop();

        Console.WriteLine($"Imported steps={imported.StepCount}");
        Console.WriteLine($"Skipped={imported.Skipped}");
        Console.WriteLine($"Loaded={loaded}");
        Console.WriteLine($"Runtime state={state}, run={runState}");
        Console.WriteLine($"Hotkeys={string.Join(",", input.SentHotkeys)}");
        Console.WriteLine($"Clicks={input.ClickCount}");
        Console.WriteLine($"Input mode={input.DefaultDispatchMode}");

        var safeConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        safeConfig.Current.StepIntervalMs = 30;
        safeConfig.Current.MaxStepRetry = 0;
        safeConfig.Current.Steps[0].RetryLimit = 0;
        var safeInput = new CountingInputService();
        var safeController = new MaterialCraftController(
            log,
            safeConfig,
            safeInput,
            new StateMachineEngine(log));
        safeController.Attach(DiagnosticWindow(new nint(6902), "material-craft-safe-runtime"));
        safeController.Start();
        await WaitForStopped(safeController, 800);
        var failClosed = safeInput.SentHotkeys.Count == 0 && safeInput.ClickCount == 0;
        Console.WriteLine($"Visual fail-closed={failClosed}");

        var entryUnavailableConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        entryUnavailableConfig.Current.EnabledIntent = true;
        entryUnavailableConfig.Current.RequireVisualConfirmation = true;
        entryUnavailableConfig.Current.ProcessAllRecipes = false;
        entryUnavailableConfig.Current.Steps.Clear();
        entryUnavailableConfig.Current.Steps.Add(new MaterialCraftStep
        {
            Action = MaterialCraftStepAction.OpenPanel,
            Label = "entry-unavailable"
        });
        var entryUnavailableInput = new CountingInputService();
        var entryUnavailableExecutor = new SyntheticMaterialActionExecutor();
        var entryUnavailableController = new MaterialCraftController(
            log,
            entryUnavailableConfig,
            entryUnavailableInput,
            new StateMachineEngine(log),
            new SyntheticMaterialFrameService(),
            visionExecutor: entryUnavailableExecutor,
            global: new TestGlobalConfigService(),
            interactionWindows: new SyntheticMissingInteractionWindowDetectService(),
            interactionControls: new SyntheticInteractionControlCatalogService(runtimeAuthorized: false));
        entryUnavailableController.Attach(DiagnosticWindow(new nint(6910), "material-craft-entry-unavailable"));
        entryUnavailableController.Start();
        await WaitForStopped(entryUnavailableController, 900);
        var entryUnavailableVerified = entryUnavailableController.RunState == RunState.Stopped
                                       && entryUnavailableController.CurrentStateName == nameof(MaterialCraftState.EntryUnavailable)
                                       && entryUnavailableExecutor.ClickCount == 0
                                       && entryUnavailableInput.SendKeyCount == 0
                                       && entryUnavailableInput.ClickCount == 0;
        Console.WriteLine($"Entry unavailable fail-closed={entryUnavailableVerified}, state={entryUnavailableController.CurrentStateName}, safe clicks={entryUnavailableExecutor.ClickCount}");

        var visionConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        visionConfig.Current.EnabledIntent = true;
        visionConfig.Current.ProcessAllRecipes = false;
        visionConfig.Current.StepIntervalMs = 50;
        visionConfig.Current.Steps[0].WaitMs = 0;
        visionConfig.Current.Steps[0].RetryLimit = 0;
        var visionInput = new CountingInputService();
        var visionExecutor = new SyntheticMaterialActionExecutor();
        var visionFrames = new SyntheticMaterialFrameService();
        var materialGlobal = new TestGlobalConfigService();
        var exhaustedPerception = new SyntheticMaterialPerceptionHub(
            visionFrames,
            _ => SystemFeedbackSemanticKind.MaterialExhausted);
        var visionController = new MaterialCraftController(
            log,
            visionConfig,
            visionInput,
            new StateMachineEngine(log),
            visionFrames,
            new SyntheticMaterialVisionService(),
            new SyntheticMaterialActionPlanner(),
            visionExecutor,
            new SyntheticOpenTextRecognizer("材料不足"),
            global: materialGlobal,
            interactionWindows: new SyntheticInteractionWindowDetectService(),
            interactionControls: new SyntheticInteractionControlCatalogService(runtimeAuthorized: true),
            perception: exhaustedPerception);
        visionController.Attach(DiagnosticWindow(new nint(6903), "material-craft-vision-runtime"));
        visionController.Start();
        await WaitForStopped(visionController, 1200);
        var exhaustedLoopStopped = visionController.RunState == RunState.Stopped
                                   && visionExecutor.ClickCount == 1
                                   && visionInput.SentHotkeys.Count == 0
                                   && visionInput.ClickCount == 0;
        if (visionController.RunState != RunState.Stopped)
            visionController.Stop();
        Console.WriteLine($"Visual exhausted loop stopped={exhaustedLoopStopped}, safe clicks={visionExecutor.ClickCount}");

        var busyConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        busyConfig.Current.EnabledIntent = true;
        busyConfig.Current.ProcessAllRecipes = false;
        busyConfig.Current.StepIntervalMs = 50;
        busyConfig.Current.Steps[0].WaitMs = 0;
        busyConfig.Current.Steps[0].RetryLimit = 0;
        var busyExecutor = new SyntheticMaterialActionExecutor();
        var busyFrames = new SyntheticMaterialFrameService();
        var busyPerception = new SyntheticMaterialPerceptionHub(
            busyFrames,
            observationIndex => observationIndex <= 4
                ? SystemFeedbackSemanticKind.MaterialBusy
                : SystemFeedbackSemanticKind.MaterialExhausted);
        var busyController = new MaterialCraftController(
            log,
            busyConfig,
            new CountingInputService(),
            new StateMachineEngine(log),
            busyFrames,
            new SyntheticMaterialVisionService(),
            new SyntheticMaterialActionPlanner(),
            busyExecutor,
            new SequencedMaterialOpenTextRecognizer(4),
            global: materialGlobal,
            interactionWindows: new SyntheticInteractionWindowDetectService(),
            interactionControls: new SyntheticInteractionControlCatalogService(runtimeAuthorized: true),
            perception: busyPerception);
        busyController.Attach(DiagnosticWindow(new nint(6905), "material-craft-busy-runtime"));
        busyController.Start();
        await WaitForStopped(busyController, 2200);
        var busyWaitVerified = busyController.RunState == RunState.Stopped
                               && busyExecutor.ClickCount == 1;
        if (busyController.RunState != RunState.Stopped)
            busyController.Stop();
        Console.WriteLine($"Visual busy wait verified={busyWaitVerified}, safe clicks={busyExecutor.ClickCount}");

        var exhaustedText = MaterialCraftFeedbackClassifier.Classify("提示：所需 材料不足，无法加工")
                            == MaterialCraftFeedbackKind.Exhausted;
        var busyText = MaterialCraftFeedbackClassifier.Classify("正在制造中，请稍候")
                       == MaterialCraftFeedbackKind.Busy;
        var completedText = MaterialCraftFeedbackClassifier.Classify("你做了一个高级铸铁。")
                            == MaterialCraftFeedbackKind.Completed;
        var unrelatedText = MaterialCraftFeedbackClassifier.Classify("制造数量 10")
                            == MaterialCraftFeedbackKind.Unknown;
        var cooldownText = MaterialCraftFeedbackClassifier.Classify("冷却时间未到")
                           == MaterialCraftFeedbackKind.Cooldown;
        var resourceText = MaterialCraftFeedbackClassifier.Classify("活力不足")
                           == MaterialCraftFeedbackKind.InsufficientResource;
        var invalidText = MaterialCraftFeedbackClassifier.Classify("当前操作未完成，请稍后再试")
                          == MaterialCraftFeedbackKind.InvalidAction;
        Console.WriteLine($"Feedback exhausted={exhaustedText}, busy={busyText}, completed={completedText}, cooldown={cooldownText}, resource={resourceText}, invalid={invalidText}, unrelated={unrelatedText}");

        var entryTemplatePath = Path.Combine((Environment.GetEnvironmentVariable("TLBB_LEGACY_DATA_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "legacy-data")), "生活王1.4.0", "A窗口", "图_pic", "材料加工.bmp");
        var entryFramePath = Path.Combine((Environment.GetEnvironmentVariable("TLBB_VISION_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "vision-workspace")), "datasets", "99_其他杂项", "images", "20260710_065057_355_99_其他杂项_2576x1408_000128.png");
        var entrySmallFramePath = Path.Combine((Environment.GetEnvironmentVariable("TLBB_VISION_ROOT") ?? Path.Combine(Environment.CurrentDirectory, "vision-workspace")), "datasets", "99_其他杂项", "images", "20260709_215902_404_99_其他杂项_800x600_000001.png");
        var entryFrame = File.Exists(entryFramePath) ? LoadCapturePng(entryFramePath) : null;
        var entrySmallFrame = File.Exists(entrySmallFramePath) ? LoadCapturePng(entrySmallFramePath) : null;
        var entryLocator = new MaterialCraftEntryLocator(entryTemplatePath);
        var entryDetection = entryFrame is null
            ? MaterialCraftEntryDetection.Unavailable("diagnostic fixture missing")
            : entryLocator.Locate(entryFrame);
        var entrySmallDetection = entrySmallFrame is null
            ? MaterialCraftEntryDetection.Unavailable("small diagnostic fixture missing")
            : entryLocator.Locate(entrySmallFrame);
        var entryLocatorVerified = entryDetection.Found
                                   && entryDetection.Box == new VisionBox(2531, 578, 30, 30)
                                   && entryDetection.Confidence >= 0.99
                                   && entrySmallDetection.Found
                                   && entrySmallDetection.Box == new VisionBox(763, 228, 30, 30)
                                   && entrySmallDetection.Confidence >= 0.99;
        Console.WriteLine($"Entry locator verified={entryLocatorVerified}, large={entryDetection.Box}@{entryDetection.Confidence:F6}, small={entrySmallDetection.Box}@{entrySmallDetection.Confidence:F6}");

        var panelCrop = entryFrame is null ? null : CropCaptureRect(entryFrame, 1091, 308, 331, 438);
        using var recipeOpenText = new RapidOcrOpenTextRecognizer(log, new ModelArtifactRegistry());
        var recipePage = panelCrop is null
            ? MaterialRecipePage.Unavailable("diagnostic panel crop missing")
            : new OpenTextMaterialRecipeListReader(recipeOpenText).Read(
                panelCrop,
                new VisionBox(1091, 308, 331, 438));
        var recipeReaderVerified = recipePage.IsReliable
                                   && recipePage.Rows.Count == 5
                                   && recipePage.Rows.All(row => row.Name.Contains("配方", StringComparison.Ordinal));
        Console.WriteLine($"Recipe reader verified={recipeReaderVerified}, rows={recipePage.Rows.Count}, names={string.Join('|', recipePage.Rows.Select(row => row.Name))}");

        var allRecipesUnauthorizedConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        allRecipesUnauthorizedConfig.Current.EnabledIntent = true;
        allRecipesUnauthorizedConfig.Current.RequireVisualConfirmation = true;
        allRecipesUnauthorizedConfig.Current.ProcessAllRecipes = true;
        allRecipesUnauthorizedConfig.Current.StepIntervalMs = 50;
        var allRecipesUnauthorizedInput = new CountingInputService();
        var allRecipesUnauthorizedExecutor = new SyntheticMaterialActionExecutor();
        var allRecipesUnauthorizedController = new MaterialCraftController(
            log,
            allRecipesUnauthorizedConfig,
            allRecipesUnauthorizedInput,
            new StateMachineEngine(log),
            frames: new SyntheticMaterialFrameService(),
            visionExecutor: allRecipesUnauthorizedExecutor,
            recipeReader: new SyntheticMaterialRecipeReader(),
            global: materialGlobal,
            interactionWindows: new SyntheticInteractionWindowDetectService(),
            interactionControls: new SyntheticInteractionControlCatalogService(runtimeAuthorized: false));
        allRecipesUnauthorizedController.Attach(DiagnosticWindow(new nint(6911), "material-craft-all-recipes-unauthorized"));
        allRecipesUnauthorizedController.Start();
        await WaitForStopped(allRecipesUnauthorizedController, 900);
        var allRecipesUnauthorizedVerified = allRecipesUnauthorizedController.RunState == RunState.Stopped
                                              && allRecipesUnauthorizedController.CurrentStateName == nameof(MaterialCraftState.EntryUnavailable)
                                              && allRecipesUnauthorizedExecutor.ClickCount == 0
                                              && allRecipesUnauthorizedInput.SendKeyCount == 0
                                              && allRecipesUnauthorizedInput.ClickCount == 0;
        Console.WriteLine($"All recipes unauthorized fail-closed={allRecipesUnauthorizedVerified}, state={allRecipesUnauthorizedController.CurrentStateName}, safe clicks={allRecipesUnauthorizedExecutor.ClickCount}");

        var allRecipesConfig = new MaterialCraftConfigService(new MemoryProfileService(), log);
        allRecipesConfig.Current.EnabledIntent = true;
        allRecipesConfig.Current.StepIntervalMs = 50;
        allRecipesConfig.Current.MaxStepRetry = 1;
        allRecipesConfig.Current.MaxRecipePages = 6;
        var allRecipesExecutor = new SyntheticMaterialActionExecutor();
        var allRecipesFrames = new SyntheticMaterialFrameService();
        var allRecipesPerception = new SyntheticMaterialPerceptionHub(
            allRecipesFrames,
            _ => SystemFeedbackSemanticKind.MaterialExhausted);
        var allRecipesController = new MaterialCraftController(
            log,
            allRecipesConfig,
            new CountingInputService(),
            new StateMachineEngine(log),
            allRecipesFrames,
            new SyntheticMaterialVisionService(),
            new SyntheticMaterialActionPlanner(),
            allRecipesExecutor,
            new SyntheticOpenTextRecognizer("材料不足"),
            null,
            new SyntheticMaterialRecipeReader(),
            materialGlobal,
            interactionWindows: new SyntheticInteractionWindowDetectService(),
            interactionControls: new SyntheticInteractionControlCatalogService(runtimeAuthorized: true),
            perception: allRecipesPerception);
        allRecipesController.Attach(DiagnosticWindow(new nint(6904), "material-craft-all-recipes"));
        allRecipesController.Start();
        await WaitForStopped(allRecipesController, 3500);
        var allRecipesVerified = allRecipesController.RunState == RunState.Stopped
                                 && allRecipesExecutor.ClickCount == 9;
        if (allRecipesController.RunState != RunState.Stopped)
            allRecipesController.Stop();
        Console.WriteLine($"All recipes loop verified={allRecipesVerified}, safe clicks={allRecipesExecutor.ClickCount}");

        var ok = imported.StepCount == 3
                 && imported.Skipped == 0
                 && loaded
                 && config.Current.Steps.Count == 3
                 && runState == RunState.Stopped
                 && input.DefaultDispatchMode == InputDispatchMode.SendInput
                 && input.SentHotkeys.Count(h => h.Equals("F8", StringComparison.OrdinalIgnoreCase)) >= 2
                 && input.SentHotkeys.Count(h => h.Equals("F9", StringComparison.OrdinalIgnoreCase)) >= 2
                  && input.SentHotkeys.Contains("F10", StringComparer.OrdinalIgnoreCase)
                  && input.ClickCount >= 4
                  && failClosed
                  && entryUnavailableVerified
                  && exhaustedLoopStopped
                  && busyWaitVerified
                  && exhaustedText
                  && busyText
                  && completedText
                  && cooldownText
                  && resourceText
                  && invalidText
                  && unrelatedText
                  && entryLocatorVerified
                  && recipeReaderVerified
                  && allRecipesUnauthorizedVerified
                  && allRecipesVerified;

        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }
    finally
    {
        try { File.Delete(planFile); }
        catch { }
    }
}

