        Console.WriteLine($"Navigation state={navigationScenario.State}, hotkeys={string.Join(",", navigationScenario.Input.SentHotkeys)}, clicks={navigationScenario.Input.ClickCount}");
        Console.WriteLine($"Action state={actionScenario.State}, run={actionScenario.RunState}, hotkeys={string.Join(",", actionScenario.Input.SentHotkeys)}, clicks={actionScenario.Input.ClickCount}");

        var ok = imported.PointCount == 2
                 && imported.Skipped == 0
                 && keepCount == 2
                 && loaded
                 && config.Route.Count == 2
                 && navigationScenario.State == nameof(TreasureMapState.NavigatePoint)
                 && navigationScenario.Input.SentHotkeys.Contains("F8", StringComparer.OrdinalIgnoreCase)
                 && navigationScenario.Input.SentHotkeys.Contains("F5", StringComparer.OrdinalIgnoreCase)
                 && navigationScenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
                 && navigationScenario.Input.ClickCount > 0
                 && actionScenario.RunState == RunState.Stopped
                 && actionScenario.State == nameof(TreasureMapState.Stop)
                 && actionScenario.Input.SentHotkeys.Count(h => h.Equals("F9", StringComparison.OrdinalIgnoreCase)) >= 4
                 && actionScenario.Input.SentHotkeys.Contains("F10", StringComparer.OrdinalIgnoreCase)
                 && actionScenario.Input.ClickCount >= 4
                 && actionScenario.Input.DefaultDispatchMode == InputDispatchMode.SendInput;

        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }
    finally
    {
        try { File.Delete(routeFile); } catch { }
        try { File.Delete(keepFile); } catch { }
    }
}

static async Task<(string State, RunState RunState, CountingInputService Input)> RunTreasureMapScenario(
    TreasureMapConfigService config,
    ILogService log,
    NavigationRecognitionResult navigation,
    int delayMs)
{
    var input = new CountingInputService();
    var controller = new TreasureMapController(
        log,
        config,
        new StaticNavigationRecognitionService(navigation),
        new ReturnNavigationService(input, log),
        input,
        new StateMachineEngine(log));

    controller.Attach(DiagnosticWindow(new nint(7101), "treasure-map-runtime"));
    controller.Start();
    await Task.Delay(delayMs);
    var state = controller.CurrentStateName;
    var runState = controller.RunState;
    controller.Stop();
    return (state, runState, input);
}

