        new UTF8Encoding(false));
    await File.WriteAllTextAsync(storeFile, "材料甲\n材料乙\n", new UTF8Encoding(false));
    await File.WriteAllTextAsync(tradeFile, "任务物品甲\n任务物品乙\n", new UTF8Encoding(false));

    try
    {
        var imported = config.ImportPlainPlan(planFile, "local-plan");
        var storeCount = config.LoadItemList(storeFile, tradeItems: false);
        var tradeCount = config.LoadItemList(tradeFile, tradeItems: true);
        config.Current.PlanName = "school-diagnostic";
        config.Current.RoundCount = 2;
        config.Current.StopAfterRounds = true;
        config.Current.LoopPlan = false;
        config.Current.ArrivalDistance = 4;
        config.Current.StepIntervalMs = 40;
        config.Current.ActionIntervalMs = 40;
        config.Current.MaxStepRetry = 1;
        config.Current.DispatchMode = InputDispatchMode.SendInput;
        config.Current.ExecutionMode = SchoolTaskExecutionMode.HotkeyThenClick;
        config.Current.EnableCleanupAfterRound = true;
        config.Current.CleanupHotkey = "F10";
        config.Current.Navigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
        config.Current.Navigation.Hotkey = "F7";
        config.Current.Navigation.ClickX = 500;
        config.Current.Navigation.ClickY = 340;
        config.Current.Navigation.ActionIntervalMs = 40;

        config.Save("school-diagnostic");
        config.ClearSteps();
        var loaded = config.Load("school-diagnostic");

        var first = config.Steps[0];
        var navigationScenario = await RunSchoolTaskScenario(
            config,
            log,
            new NavigationRecognitionResult(first.MapName, $"{first.X + 50},{first.Y + 50}", first.X + 50, first.Y + 50),
            delayMs: 180);

        foreach (var step in config.Current.Steps)
        {
            step.MapName = first.MapName;
            step.X = first.X;
            step.Y = first.Y;
        }

        var actionScenario = await RunSchoolTaskScenario(
            config,
            log,
            new NavigationRecognitionResult(first.MapName, $"{first.X},{first.Y}", first.X, first.Y),
            delayMs: 900);

        Console.WriteLine($"Imported steps={imported.StepCount}");
        Console.WriteLine($"Store items={storeCount}, trade items={tradeCount}");
        Console.WriteLine($"Loaded={loaded}");
        Console.WriteLine($"Navigation state={navigationScenario.State}, hotkeys={string.Join(",", navigationScenario.Input.SentHotkeys)}, clicks={navigationScenario.Input.ClickCount}");
        Console.WriteLine($"Action state={actionScenario.State}, run={actionScenario.RunState}, hotkeys={string.Join(",", actionScenario.Input.SentHotkeys)}, clicks={actionScenario.Input.ClickCount}");

        var ok = imported.StepCount == 3
                 && imported.Skipped == 0
                 && storeCount == 2
                 && tradeCount == 2
                 && loaded
                 && config.Steps.Count == 3
                 && navigationScenario.State == nameof(SchoolTaskState.NavigateStep)
                 && navigationScenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
                 && navigationScenario.Input.ClickCount > 0
                 && actionScenario.RunState == RunState.Stopped
                 && actionScenario.State == nameof(SchoolTaskState.Stop)
                 && actionScenario.Input.SentHotkeys.Count(h => h.Equals("F8", StringComparison.OrdinalIgnoreCase)) >= 4
                 && actionScenario.Input.SentHotkeys.Count(h => h.Equals("F1", StringComparison.OrdinalIgnoreCase)) >= 2
                 && actionScenario.Input.SentHotkeys.Contains("F10", StringComparer.OrdinalIgnoreCase)
                 && actionScenario.Input.ClickCount >= 6;

        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }
    finally
    {
        try { File.Delete(planFile); } catch { }
        try { File.Delete(storeFile); } catch { }
        try { File.Delete(tradeFile); } catch { }
    }
}

