    var profiles = new MemoryProfileService();
    var config = new GuildContributionConfigService(profiles, log);
    var planFile = Path.Combine(Path.GetTempPath(), "longbanxing-guild-plan-" + Guid.NewGuid().ToString("N") + ".txt");
    var itemsFile = Path.Combine(Path.GetTempPath(), "longbanxing-guild-items-" + Guid.NewGuid().ToString("N") + ".txt");

    await File.WriteAllTextAsync(planFile,
        "任务一,帮派,120,220,AcceptTask,帮派NPC,F8,520,360,40\n" +
        "任务一,帮派,120,220,SubmitTask,帮派NPC,F8,520,360,40\n" +
        "任务二,帮派,120,220,AcceptTask,帮派NPC,F8,520,360,40\n" +
        "任务二,帮派,120,220,SubmitTask,帮派NPC,F8,520,360,40\n",
        new UTF8Encoding(false));
    await File.WriteAllTextAsync(itemsFile, "帮贡物品甲\n帮贡物品乙\n", new UTF8Encoding(false));

    try
    {
        var imported = config.ImportPlainPlan(planFile, "local-plan");
        var itemCount = config.LoadItemRules(itemsFile);
        config.Current.PlanName = "guild-diagnostic";
        config.Current.RoundCount = 1;
        config.Current.StopAfterRounds = true;
        config.Current.LoopPlan = false;
        config.Current.ArrivalDistance = 4;
        config.Current.StepIntervalMs = 40;
        config.Current.ActionIntervalMs = 40;
        config.Current.MaxStepRetry = 1;
        config.Current.DispatchMode = InputDispatchMode.SendInput;
        config.Current.ExecutionMode = GuildContributionExecutionMode.HotkeyThenClick;
        config.Current.EnableCleanupAfterTask = true;
        config.Current.CleanupHotkey = "F10";
        config.Current.Navigation.Mode = ReturnNavigationMode.HotkeyThenClickClientPoint;
        config.Current.Navigation.Hotkey = "F7";
        config.Current.Navigation.ClickX = 500;
        config.Current.Navigation.ClickY = 340;
        config.Current.Navigation.ActionIntervalMs = 40;
        foreach (var task in config.Current.TaskTypes)
            task.Enabled = task.Name is "任务一" or "任务二";

        config.Save("guild-diagnostic");
        config.ClearSteps();
        var loaded = config.Load("guild-diagnostic");

        var first = config.Steps[0];
        var navigationScenario = await RunGuildContributionScenario(
            config,
            log,
            new NavigationRecognitionResult(first.MapName, $"{first.X + 50},{first.Y + 50}", first.X + 50, first.Y + 50),
            delayMs: 180);

        foreach (var step in config.Current.Steps)
        {
            step.MapName = first.MapName;
            step.X = first.X;
            step.Y = first.Y;
            step.WaitMs = 40;
        }

        var actionScenario = await RunGuildContributionScenario(
            config,
            log,
            new NavigationRecognitionResult(first.MapName, $"{first.X},{first.Y}", first.X, first.Y),
            delayMs: 1000);

        Console.WriteLine($"Imported steps={imported.StepCount}");
        Console.WriteLine($"Item rules={itemCount}");
        Console.WriteLine($"Loaded={loaded}");
        Console.WriteLine($"Navigation state={navigationScenario.State}, hotkeys={string.Join(",", navigationScenario.Input.SentHotkeys)}, clicks={navigationScenario.Input.ClickCount}");
        Console.WriteLine($"Action state={actionScenario.State}, run={actionScenario.RunState}, hotkeys={string.Join(",", actionScenario.Input.SentHotkeys)}, clicks={actionScenario.Input.ClickCount}");

        var ok = imported.StepCount == 4
                 && imported.Skipped == 0
                 && itemCount == 2
                 && loaded
                 && config.Steps.Count == 4
                 && config.TaskTypes.Count(t => t.Enabled) == 2
                 && navigationScenario.State == nameof(GuildContributionState.NavigateStep)
                 && navigationScenario.Input.SentHotkeys.Contains("F7", StringComparer.OrdinalIgnoreCase)
                 && navigationScenario.Input.ClickCount > 0
                 && actionScenario.RunState == RunState.Stopped
                 && actionScenario.State == nameof(GuildContributionState.Stop)
                 && actionScenario.Input.SentHotkeys.Count(h => h.Equals("F8", StringComparison.OrdinalIgnoreCase)) >= 4
                 && actionScenario.Input.SentHotkeys.Count(h => h.Equals("F10", StringComparison.OrdinalIgnoreCase)) >= 2
                 && actionScenario.Input.ClickCount >= 4
                 && actionScenario.Input.DefaultDispatchMode == InputDispatchMode.SendInput;

        Console.WriteLine(ok ? "PASS" : "FAIL");
        return ok;
    }
    finally
    {
        try { File.Delete(planFile); } catch { }
        try { File.Delete(itemsFile); } catch { }
    }
}

