static IReadOnlyList<ReadOnlyMemorySearchPattern> BuildCoordinateSearchPatterns(int x, int y)
{
    var tokens = new[]
        {
            $"{x},{y}",
            $"{x}, {y}",
            $"{x} {y}",
            $"({x},{y})",
            $"({x}, {y})"
        }
        .Where(t => !string.IsNullOrWhiteSpace(t))
        .Distinct(StringComparer.Ordinal)
        .ToArray();

    var patterns = new List<ReadOnlyMemorySearchPattern>();
    foreach (var token in tokens)
    {
        patterns.Add(new ReadOnlyMemorySearchPattern($"ascii:{token}", token, "ASCII", Encoding.ASCII.GetBytes(token)));
        patterns.Add(new ReadOnlyMemorySearchPattern($"utf16le:{token}", token, "UTF-16LE", Encoding.Unicode.GetBytes(token)));
    }

    return patterns;
}

static ReadOnlyCoordinateMemoryScanResult ScanReadableMemoryForPatterns(
    nint processHandle,
    IReadOnlyList<ReadOnlyMemorySearchPattern> patterns,
    long maxBytesToRead,
    int maxRegionsToVisit,
    int maxHits,
    int maxChunkBytes,
    ulong maxUserAddress)
{
    var hits = new List<ReadOnlyCoordinateMemoryHit>();
    var seen = new HashSet<string>(StringComparer.Ordinal);
    var address = nint.Zero;
    var regionsVisited = 0;
    var readableRegions = 0;
    var readCalls = 0;
    var failedReadCalls = 0;
    long bytesReadTotal = 0;
    var stoppedReason = "address-space-end";
    var mbiSize = (nuint)Marshal.SizeOf<ReadOnlyMemoryNative.MemoryBasicInformation>();
    var maxPatternLength = patterns.Max(p => p.Bytes.Length);

    while ((ulong)address.ToInt64() < maxUserAddress)
    {
        if (regionsVisited >= maxRegionsToVisit)
        {
            stoppedReason = "max-regions";
            break;
        }

        if (bytesReadTotal >= maxBytesToRead)
        {
            stoppedReason = "max-bytes";
            break;
        }

        if (hits.Count >= maxHits)
        {
            stoppedReason = "max-hits";
            break;
        }

        var queryOk = ReadOnlyMemoryNative.VirtualQueryEx(
            processHandle,
            address,
            out var memory,
            mbiSize);
        if (queryOk == 0)
        {
            var nextProbe = AddAddress(address, 0x10000);
            if (nextProbe.ToInt64() <= address.ToInt64())
            {
                stoppedReason = "virtual-query-failed";
                break;
            }

            address = nextProbe;
            continue;
        }

        regionsVisited++;
        var regionBase = memory.BaseAddress;
        var regionSize = (long)Math.Min((ulong)memory.RegionSize, (ulong)long.MaxValue);
        var nextAddress = AddAddress(regionBase, Math.Max(regionSize, 0x1000));

        if (regionSize > 0 && IsReadableCommittedMemory(memory))
        {
            readableRegions++;
            var bytesRemainingInRegion = regionSize;
            var offset = 0L;
            var tail = Array.Empty<byte>();

            while (bytesRemainingInRegion > 0 && bytesReadTotal < maxBytesToRead && hits.Count < maxHits)
            {
                var readSize = (int)Math.Min(
                    Math.Min(bytesRemainingInRegion, maxChunkBytes),
                    maxBytesToRead - bytesReadTotal);
                if (readSize <= 0)
                    break;

                var chunkAddress = AddAddress(regionBase, offset);
                var chunk = new byte[readSize];
                readCalls++;
                if (!ReadOnlyMemoryNative.ReadProcessMemory(processHandle, chunkAddress, chunk, readSize, out var bytesRead) || bytesRead <= 0)
                {
                    failedReadCalls++;
                    offset += readSize;
                    bytesRemainingInRegion -= readSize;
                    tail = Array.Empty<byte>();
                    continue;
                }

                bytesReadTotal += bytesRead;
                var actual = bytesRead == chunk.Length ? chunk : chunk.Take(bytesRead).ToArray();
                var combined = tail.Length == 0 ? actual : tail.Concat(actual).ToArray();
                var combinedBaseAddress = chunkAddress.ToInt64() - tail.Length;

                foreach (var pattern in patterns)
                {
                    foreach (var index in FindPatternIndexes(combined, pattern.Bytes))
                    {
                        var absolute = combinedBaseAddress + index;
                        var key = $"{pattern.Label}@{absolute:X}";
                        if (!seen.Add(key))
                            continue;

                        hits.Add(new ReadOnlyCoordinateMemoryHit(
                            $"0x{absolute:X}",
                            $"0x{regionBase.ToInt64():X}",
                            regionSize,
                            pattern.Label,
                            pattern.Token,
                            pattern.EncodingName,
                            absolute - regionBase.ToInt64()));

                        if (hits.Count >= maxHits)
                            break;
                    }

                    if (hits.Count >= maxHits)
                        break;
                }

                var tailLength = Math.Min(actual.Length, Math.Max(0, maxPatternLength - 1));
                tail = tailLength <= 0 ? Array.Empty<byte>() : actual.Skip(actual.Length - tailLength).ToArray();
                offset += bytesRead;
                bytesRemainingInRegion -= bytesRead;
                if (bytesRead < readSize)
                    break;
            }
        }

        if (nextAddress.ToInt64() <= address.ToInt64())
        {
            stoppedReason = "address-overflow";
            break;
        }

        address = nextAddress;
    }

    if (hits.Count >= maxHits)
        stoppedReason = "max-hits";
    else if (bytesReadTotal >= maxBytesToRead)
        stoppedReason = "max-bytes";
    else if (regionsVisited >= maxRegionsToVisit)
        stoppedReason = "max-regions";

    return new ReadOnlyCoordinateMemoryScanResult(
        regionsVisited,
        readableRegions,
        readCalls,
        failedReadCalls,
        bytesReadTotal,
        hits.Count,
        stoppedReason,
        hits);
}

static IEnumerable<int> FindPatternIndexes(byte[] buffer, byte[] pattern)
{
    if (buffer.Length == 0 || pattern.Length == 0 || pattern.Length > buffer.Length)
        yield break;

    for (var i = 0; i <= buffer.Length - pattern.Length; i++)
    {
        var matched = true;
        for (var j = 0; j < pattern.Length; j++)
        {
            if (buffer[i + j] == pattern[j])
                continue;

            matched = false;
            break;
        }

        if (matched)
            yield return i;
    }
}

static bool IsReadableCommittedMemory(ReadOnlyMemoryNative.MemoryBasicInformation memory)
{
    const uint MEM_COMMIT = 0x1000;
    const uint PAGE_NOACCESS = 0x01;
    const uint PAGE_GUARD = 0x100;
    const uint PAGE_READONLY = 0x02;
    const uint PAGE_READWRITE = 0x04;
    const uint PAGE_WRITECOPY = 0x08;
    const uint PAGE_EXECUTE_READ = 0x20;
    const uint PAGE_EXECUTE_READWRITE = 0x40;
    const uint PAGE_EXECUTE_WRITECOPY = 0x80;

    if (memory.State != MEM_COMMIT)
        return false;

    if ((memory.Protect & PAGE_NOACCESS) != 0 || (memory.Protect & PAGE_GUARD) != 0)
        return false;

    return (memory.Protect & (PAGE_READONLY
                              | PAGE_READWRITE
                              | PAGE_WRITECOPY
                              | PAGE_EXECUTE_READ
                              | PAGE_EXECUTE_READWRITE
                              | PAGE_EXECUTE_WRITECOPY)) != 0;
}

static nint AddAddress(nint address, long offset) => new(address.ToInt64() + offset);

static ReadOnlyCoordinateKnownChainResult TryReadExternalCoordinateReferenceChain(
    nint processHandle,
    nint moduleBase,
    int baseOffset,
    int xOffset,
    int yOffset,
    int anchorX,
    int anchorY)
{
    var readCalls = 0;
    var failedReadCalls = 0;
    var lastError = 0;
    var pointerAddress = moduleBase == 0 ? nint.Zero : AddAddress(moduleBase, baseOffset);
    var pointerValue = 0;
    float? xValue = null;
    float? yValue = null;
    var matchMode = "none";
    var readSucceeded = false;

    if (moduleBase == 0)
    {
        return new ReadOnlyCoordinateKnownChainResult(
            false,
            readCalls,
            failedReadCalls,
            0,
            "-",
            "-",
            "-",
            null,
            null,
            matchMode,
            false,
            "main-module-base-unavailable");
    }

    readCalls++;
    if (!TryReadInt32(processHandle, pointerAddress, out pointerValue, out lastError))
    {
        failedReadCalls++;
        return new ReadOnlyCoordinateKnownChainResult(
            false,
            readCalls,
            failedReadCalls,
            lastError,
            $"0x{pointerAddress.ToInt64():X}",
            "-",
            "-",
            null,
            null,
            matchMode,
            false,
            "base-pointer-read-failed");
    }

    if (pointerValue <= 0)
    {
        return new ReadOnlyCoordinateKnownChainResult(
            false,
            readCalls,
            failedReadCalls,
            lastError,
            $"0x{pointerAddress.ToInt64():X}",
            $"0x{pointerValue:X8}",
            "-",
            null,
            null,
            matchMode,
            false,
            "base-pointer-null-or-invalid");
    }

    var xAddress = new nint(pointerValue + xOffset);
    var yAddress = new nint(pointerValue + yOffset);

    readCalls++;
    if (!TryReadFloat(processHandle, xAddress, out var x, out lastError))
    {
        failedReadCalls++;
        return new ReadOnlyCoordinateKnownChainResult(
            false,
            readCalls,
            failedReadCalls,
            lastError,
            $"0x{pointerAddress.ToInt64():X}",
            $"0x{pointerValue:X8}",
            $"0x{xAddress.ToInt64():X}/0x{yAddress.ToInt64():X}",
            null,
            null,
            matchMode,
            false,
            "x-float-read-failed");
    }

    readCalls++;
    if (!TryReadFloat(processHandle, yAddress, out var y, out lastError))
    {
        failedReadCalls++;
        return new ReadOnlyCoordinateKnownChainResult(
            false,
            readCalls,
            failedReadCalls,
            lastError,
            $"0x{pointerAddress.ToInt64():X}",
            $"0x{pointerValue:X8}",
            $"0x{xAddress.ToInt64():X}/0x{yAddress.ToInt64():X}",
            x,
            null,
            matchMode,
            false,
            "y-float-read-failed");
    }

    xValue = x;
    yValue = y;
    readSucceeded = true;
    var looksPlausible = TryClassifyCoordinateFloatPair(x, y, anchorX, anchorY, out matchMode);

    return new ReadOnlyCoordinateKnownChainResult(
        readSucceeded,
        readCalls,
        failedReadCalls,
        lastError,
        $"0x{pointerAddress.ToInt64():X}",
        $"0x{pointerValue:X8}",
        $"0x{xAddress.ToInt64():X}/0x{yAddress.ToInt64():X}",
        xValue,
        yValue,
        matchMode,
        looksPlausible,
        looksPlausible ? "candidate-matches-anchor-transform" : "candidate-read-but-anchor-transform-not-matched");
}

static ReadOnlyCoordinateFloatPairScanResult ScanReadableMemoryForCoordinateFloatPairs(
    nint processHandle,
    int anchorX,
    int anchorY,
    long maxBytesToRead,
    int maxRegionsToVisit,
    int maxHits,
    int maxChunkBytes,
    ulong maxUserAddress)
{
    var hits = new List<ReadOnlyCoordinateFloatPairHit>();
    var seen = new HashSet<string>(StringComparer.Ordinal);
    var address = nint.Zero;
    var regionsVisited = 0;
    var readableRegions = 0;
    var readCalls = 0;
    var failedReadCalls = 0;
    long bytesReadTotal = 0;
    var stoppedReason = "address-space-end";
    var mbiSize = (nuint)Marshal.SizeOf<ReadOnlyMemoryNative.MemoryBasicInformation>();
    var pairGaps = new[] { 4, 8, 12, 16 };
    var maxGap = pairGaps.Max();

    while ((ulong)address.ToInt64() < maxUserAddress)
    {
        if (regionsVisited >= maxRegionsToVisit)
        {
            stoppedReason = "max-regions";
            break;
        }

        if (bytesReadTotal >= maxBytesToRead)
        {
            stoppedReason = "max-bytes";
            break;
        }

        if (hits.Count >= maxHits)
        {
            stoppedReason = "max-hits";
            break;
        }

        var queryOk = ReadOnlyMemoryNative.VirtualQueryEx(
            processHandle,
            address,
            out var memory,
            mbiSize);
        if (queryOk == 0)
        {
            var nextProbe = AddAddress(address, 0x10000);
            if (nextProbe.ToInt64() <= address.ToInt64())
            {
                stoppedReason = "virtual-query-failed";
                break;
            }

            address = nextProbe;
            continue;
        }

        regionsVisited++;
        var regionBase = memory.BaseAddress;
        var regionSize = (long)Math.Min((ulong)memory.RegionSize, (ulong)long.MaxValue);
        var nextAddress = AddAddress(regionBase, Math.Max(regionSize, 0x1000));

        if (regionSize > 0 && IsReadableCommittedMemory(memory))
        {
            readableRegions++;
            var bytesRemainingInRegion = regionSize;
            var offset = 0L;
            var tail = Array.Empty<byte>();

            while (bytesRemainingInRegion > 0 && bytesReadTotal < maxBytesToRead && hits.Count < maxHits)
            {
                var readSize = (int)Math.Min(
                    Math.Min(bytesRemainingInRegion, maxChunkBytes),
                    maxBytesToRead - bytesReadTotal);
                if (readSize <= 0)
                    break;

                var chunkAddress = AddAddress(regionBase, offset);
                var chunk = new byte[readSize];
                readCalls++;
                if (!ReadOnlyMemoryNative.ReadProcessMemory(processHandle, chunkAddress, chunk, readSize, out var bytesRead) || bytesRead <= 0)
                {
                    failedReadCalls++;
                    offset += readSize;
                    bytesRemainingInRegion -= readSize;
                    tail = Array.Empty<byte>();
                    continue;
                }

                bytesReadTotal += bytesRead;
                var actual = bytesRead == chunk.Length ? chunk : chunk.Take(bytesRead).ToArray();
                var combined = tail.Length == 0 ? actual : tail.Concat(actual).ToArray();
                var combinedBaseAddress = chunkAddress.ToInt64() - tail.Length;

                for (var i = 0; i + sizeof(float) + maxGap <= combined.Length; i += sizeof(float))
                {
                    var x = BitConverter.ToSingle(combined, i);
                    if (!IsPlausibleCoordinateFloat(x))
                        continue;

                    foreach (var gap in pairGaps)
                    {
                        var yIndex = i + gap;
                        if (yIndex + sizeof(float) > combined.Length)
                            continue;

                        var y = BitConverter.ToSingle(combined, yIndex);
                        if (!IsPlausibleCoordinateFloat(y))
                            continue;

                        if (!TryClassifyCoordinateFloatPair(x, y, anchorX, anchorY, out var matchMode))
                            continue;

                        var absoluteX = combinedBaseAddress + i;
                        var absoluteY = combinedBaseAddress + yIndex;
                        var key = $"{absoluteX:X}:{absoluteY:X}:{matchMode}";
                        if (!seen.Add(key))
                            continue;

                        hits.Add(new ReadOnlyCoordinateFloatPairHit(
                            $"0x{absoluteX:X}",
                            $"0x{absoluteY:X}",
                            $"0x{regionBase.ToInt64():X}",
                            regionSize,
                            absoluteX - regionBase.ToInt64(),
                            gap,
                            x,
                            y,
                            matchMode));

                        if (hits.Count >= maxHits)
                            break;
                    }

                    if (hits.Count >= maxHits)
                        break;
                }

                var tailLength = Math.Min(actual.Length, maxGap + sizeof(float));
                tail = tailLength <= 0 ? Array.Empty<byte>() : actual.Skip(actual.Length - tailLength).ToArray();
                offset += bytesRead;
                bytesRemainingInRegion -= bytesRead;
                if (bytesRead < readSize)
                    break;
            }
        }

        if (nextAddress.ToInt64() <= address.ToInt64())
        {
            stoppedReason = "address-overflow";
            break;
        }

        address = nextAddress;
    }

    if (hits.Count >= maxHits)
        stoppedReason = "max-hits";
    else if (bytesReadTotal >= maxBytesToRead)
        stoppedReason = "max-bytes";
    else if (regionsVisited >= maxRegionsToVisit)
        stoppedReason = "max-regions";

    return new ReadOnlyCoordinateFloatPairScanResult(
        regionsVisited,
        readableRegions,
        readCalls,
        failedReadCalls,
        bytesReadTotal,
        hits.Count,
        stoppedReason,
        hits);
}

static bool TryReadInt32(nint processHandle, nint address, out int value, out int lastError)
{
    var buffer = new byte[4];
    if (!ReadOnlyMemoryNative.ReadProcessMemory(processHandle, address, buffer, buffer.Length, out var bytesRead) || bytesRead != buffer.Length)
    {
        value = 0;
        lastError = Marshal.GetLastWin32Error();
        return false;
    }

    value = BitConverter.ToInt32(buffer, 0);
    lastError = 0;
    return true;
}

static bool TryReadFloat(nint processHandle, nint address, out float value, out int lastError)
{
    var buffer = new byte[4];
    if (!ReadOnlyMemoryNative.ReadProcessMemory(processHandle, address, buffer, buffer.Length, out var bytesRead) || bytesRead != buffer.Length)
    {
        value = 0;
        lastError = Marshal.GetLastWin32Error();
        return false;
    }

    value = BitConverter.ToSingle(buffer, 0);
    lastError = 0;
    return true;
}

static bool TryClassifyCoordinateFloatPair(float xValue, float yValue, int anchorX, int anchorY, out string matchMode)
{
    matchMode = "none";
    if (!IsPlausibleCoordinateFloat(xValue) || !IsPlausibleCoordinateFloat(yValue))
        return false;

    if ((int)MathF.Round(xValue) == anchorX && (int)MathF.Round(yValue) == anchorY)
    {
        matchMode = "direct-round";
        return true;
    }

    if ((int)MathF.Floor(xValue) == anchorX && (int)MathF.Floor(yValue) == anchorY)
    {
        matchMode = "direct-floor";
        return true;
    }

    if ((int)MathF.Round(xValue / 10f) == anchorX && (int)MathF.Round(yValue / 10f) == anchorY)
    {
        matchMode = "scaled10-round";
        return true;
    }

    if ((int)MathF.Floor(xValue / 10f) == anchorX && (int)MathF.Floor(yValue / 10f) == anchorY)
    {
        matchMode = "scaled10-floor";
        return true;
    }

    return false;
}

static bool IsPlausibleCoordinateFloat(float value)
{
    return float.IsFinite(value) && value >= 0 && value <= 10000;
}

static int ParsePositiveIntArg(string[] args, int index, int fallback, int min, int max)
{
    if (index < 0 || index >= args.Length)
        return fallback;

    if (!int.TryParse(args[index], out var value))
        return fallback;

    return Math.Clamp(value, min, max);
}

static IEnumerable<ReadOnlyCoordinateNumericStabilityValue> ReadTrackedCoordinateCandidates(
    nint processHandle,
    IReadOnlyList<ReadOnlyCoordinateFloatPairHit> tracked,
    NavigationRecognitionResult navigation)
{
    foreach (var candidate in tracked)
    {
        var readAttempted = false;
        var readSucceeded = false;
        var lastError = 0;
        float? xValue = null;
        float? yValue = null;
        var matchMode = "none";
        var matchesAnchor = false;

        if (TryParseHexAddress(candidate.AddressX, out var xAddress)
            && TryParseHexAddress(candidate.AddressY, out var yAddress))
        {
            readAttempted = true;
            var xOk = TryReadFloat(processHandle, xAddress, out var x, out lastError);
            var yOk = TryReadFloat(processHandle, yAddress, out var y, out var yLastError);
            if (!yOk)
                lastError = yLastError;

            if (xOk && yOk)
            {
                readSucceeded = true;
                xValue = x;
                yValue = y;
                matchesAnchor = navigation is { X: not null, Y: not null }
                                && TryClassifyCoordinateFloatPair(x, y, navigation.X.Value, navigation.Y.Value, out matchMode);
            }
        }

        yield return new ReadOnlyCoordinateNumericStabilityValue(
            candidate.AddressX,
            candidate.AddressY,
            readAttempted,
            readSucceeded,
            lastError,
            xValue,
            yValue,
            matchMode,
            matchesAnchor);
    }
}

static bool TryParseHexAddress(string value, out nint address)
{
    address = nint.Zero;
    if (string.IsNullOrWhiteSpace(value))
        return false;

    var text = value.Trim();
    if (text.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
        text = text[2..];

    try
    {
        var parsed = Convert.ToInt64(text, 16);
        address = new nint(parsed);
        return true;
    }
    catch
    {
        return false;
    }
}

