internal sealed class FakeWindowBindingService : IWindowBindingService
{
    public BoundGameWindow? Current { get; private set; }
    public event EventHandler<BoundGameWindow?>? CurrentChanged;
    public int BindPointCalls { get; private set; }
    public int BindHandleCalls { get; private set; }
    public string? TitleOverride { get; set; }
    public string? ProcessPathOverride { get; set; }

    public BoundGameWindow? BindByScreenPoint(double screenX, double screenY)
    {
        BindPointCalls++;
        Current = Create(new nint(0x4444), TitleOverride ?? "fake-point-bind", ProcessPathOverride);
        CurrentChanged?.Invoke(this, Current);
        return Current;
    }

    public BoundGameWindow? BindByHandle(nint hwnd)
    {
        BindHandleCalls++;
        Current = Create(hwnd, TitleOverride ?? "fake-handle-bind", ProcessPathOverride);
        CurrentChanged?.Invoke(this, Current);
        return Current;
    }

    public BoundGameWindow? InspectByHandle(nint hwnd) =>
        Create(hwnd, TitleOverride ?? "fake-handle-inspect", ProcessPathOverride);

    public BoundGameWindow? BindFirstGameWindow()
    {
        BindHandleCalls++;
        Current = Create(new nint(0x4445), TitleOverride ?? "fake-game-bind", ProcessPathOverride);
        CurrentChanged?.Invoke(this, Current);
        return Current;
    }

    public void Unbind()
    {
        Current = null;
        CurrentChanged?.Invoke(this, null);
    }

    public bool TryScreenToClient(BoundGameWindow window, double screenX, double screenY, out int clientX, out int clientY, out string error)
    {
        clientX = (int)Math.Round(screenX);
        clientY = (int)Math.Round(screenY);
        error = string.Empty;
        return true;
    }

    private static BoundGameWindow Create(nint hwnd, string title, string? processPath) => new()
    {
        Hwnd = hwnd,
        Pid = 0,
        Title = title,
        ProcessName = "diagnostic",
        ProcessPath = processPath ?? "-",
        Bitness = ClientBitness.X86,
        ClientType = ClientType.Tlbb32,
        ClientWidth = 1024,
        ClientHeight = 768,
        RunState = RunState.Ready
    };
}

internal sealed class FakeClientProcessService : IClientProcessService
{
    public HashSet<nint> AliveWindows { get; } = new();
    public bool ProcessAlive { get; set; } = true;
    public nint WaitWindowHandle { get; set; }
    public int StartedPid { get; set; } = 1000;
    public int WaitCalls { get; private set; }
    public int StartCalls { get; private set; }
    public string LastStartPath { get; private set; } = "";

    public bool IsWindowAlive(nint hwnd) => AliveWindows.Contains(hwnd);
    public bool IsProcessAlive(int pid) => ProcessAlive;

    public nint WaitForMainWindow(int pid, int timeoutMs, int pollIntervalMs = 250)
    {
        WaitCalls++;
        if (WaitWindowHandle != nint.Zero)
            AliveWindows.Add(WaitWindowHandle);
        return WaitWindowHandle;
    }

    public ClientLaunchResult StartClient(string processPath)
    {
        StartCalls++;
        LastStartPath = processPath;
        ProcessAlive = true;
        return new ClientLaunchResult(true, StartedPid, "started");
    }
}

internal sealed class MemoryProfileService : IProfileService
{
    private readonly Dictionary<string, string> _store = new(StringComparer.Ordinal);

    public string? CurrentProfileName { get; private set; }

    public IReadOnlyList<string> ListProfileNames() =>
        _store.Keys.OrderBy(k => k, StringComparer.Ordinal).ToList();

    public void Save(string name, string jsonPayload)
    {
        _store[name] = jsonPayload;
        CurrentProfileName = name;
    }

    public string? Load(string name)
    {
        CurrentProfileName = name;
        return _store.TryGetValue(name, out var value) ? value : null;
    }

    public void Delete(string name)
    {
        _store.Remove(name);
        if (CurrentProfileName == name)
            CurrentProfileName = null;
    }
}

