internal sealed class RecognitionPerceptionHub(ICombatRecognitionService recognition) : IPerceptionHub
{
    public RuntimePerceptionSnapshot Read(BoundGameWindow window, GlobalConfig config, bool includeOpenText = false)
    {
        var combat = recognition.Recognize(window, config.CombatRecognition);
        var identity = combat.TargetLooksLikePlayer
            ? TargetIdentity.Player
            : combat.TargetLooksLikePet
                ? TargetIdentity.Pet
                : combat.TargetSampleKind.ToLowerInvariant() switch
                {
                    "monster" => TargetIdentity.Monster,
                    "boss" => TargetIdentity.Boss,
                    "elite" => TargetIdentity.Elite,
                    "npc" => TargetIdentity.Npc,
                    _ => TargetIdentity.Unknown
                };
        var presence = combat.HasTarget ? TargetPresence.Present : TargetPresence.None;
        var life = combat.TargetHpPercent switch
        {
            0 => TargetLifeState.DeadByHpBottom,
            <= 25 and > 0 => TargetLifeState.Weak,
            > 25 => TargetLifeState.Live,
            _ => presence == TargetPresence.Present ? TargetLifeState.Ambiguous : TargetLifeState.NoTarget
        };
        var protectedTarget = combat.TargetLooksLikePlayer || combat.TargetLooksLikePet || combat.TargetIsAttackable == false;
        var detections = presence == TargetPresence.Present
            ? new[] { new LayoutDetectionItem(LayoutClass.TargetPanel, new VisionBox(0, 0, 260, 82), 1, "diagnostic") }
            : Array.Empty<LayoutDetectionItem>();

        return new RuntimePerceptionSnapshot
        {
            FrameSequence = Environment.TickCount64,
            Width = Math.Max(1, window.ClientWidth),
            Height = Math.Max(1, window.ClientHeight),
            Layout = new LayoutSnapshot(
                Math.Max(1, window.ClientWidth),
                Math.Max(1, window.ClientHeight),
                PerceptionSourceKind.OnnxLayout,
                DateTimeOffset.UtcNow,
                detections,
                "diagnostic"),
            Target = new TargetPerception
            {
                Presence = presence,
                Identity = identity,
                Life = life,
                HpPercent = combat.TargetHpPercent,
                NameText = combat.TargetNameText,
                IsProtectedTarget = protectedTarget,
                IsActionableTarget = presence == TargetPresence.Present && !protectedTarget && life is TargetLifeState.Live or TargetLifeState.Weak,
                ShouldAcquireTarget = presence != TargetPresence.Present || protectedTarget || life == TargetLifeState.DeadByHpBottom,
                ShouldSwitchTarget = protectedTarget || life == TargetLifeState.DeadByHpBottom,
                Confidence = Math.Max(0.9, combat.TargetSampleScore),
                Source = PerceptionSourceKind.Fused
            },
            TargetIdentity = new TargetIdentityEvidence(identity, 0.9, PerceptionSourceKind.Fused, "diagnostic"),
            SelfBars = new SelfBarsPerception
            {
                PlayerHpPercent = combat.PlayerHpPercent,
                PlayerMpPercent = combat.PlayerMpPercent,
                PetHpPercent = combat.PetHpPercent,
                Source = PerceptionSourceKind.Fused
            },
            TargetNameOpenText = new OpenTextResult(
                combat.TargetNameText,
                string.IsNullOrWhiteSpace(combat.TargetNameText) ? 0 : 0.9,
                OpenTextSlot.TargetName,
                string.IsNullOrWhiteSpace(combat.TargetNameText) ? PerceptionSourceKind.Unavailable : PerceptionSourceKind.OpenText,
                "diagnostic")
        };
    }
}

internal sealed class QueuedCombatRecognitionService(params CombatRecognitionResult[] results) : ICombatRecognitionService
