internal static class DiagnosticWindowNative
{
    private const int GwlExStyle = -20;
    private const int WsExTopmost = 0x00000008;
    private const uint GaRoot = 2;
    private const uint SwpNoSize = 0x0001;
    private const uint SwpNoMove = 0x0002;
    private const uint SwpNoActivate = 0x0010;
    private static readonly nint HwndTopmost = new(-1);
    private static readonly nint HwndNoTopmost = new(-2);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool IsWindow(nint hWnd);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool IsWindowVisible(nint hWnd);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool IsIconic(nint hWnd);

    [DllImport("user32.dll")]
    public static extern uint GetWindowThreadProcessId(nint hWnd, out uint processId);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetClientRect(nint hWnd, out NativeRect rect);

    public static nint CurrentForegroundWindowHandle() => GetForegroundWindow();

    public static bool TryRestoreForegroundWindow(nint hwnd)
    {
        if (hwnd == nint.Zero)
            return false;
        if (GetForegroundWindow() == hwnd)
            return true;
        _ = BringWindowToTop(hwnd);
        return SetForegroundWindow(hwnd) && GetForegroundWindow() == hwnd;
    }

    public static DiagnosticPointOwnership VerifyBackgroundClientPointOwnership(
        nint hwnd,
        int clientX,
        int clientY,
        uint expectedPid)
    {
        var foregroundBefore = GetForegroundWindow();
        var targetRoot = IsWindow(hwnd) ? GetAncestor(hwnd, GaRoot) : nint.Zero;
        uint targetPid = 0;
        if (targetRoot != nint.Zero)
            _ = GetWindowThreadProcessId(targetRoot, out targetPid);

        var hasClientRect = GetClientRect(hwnd, out var clientRect);
        var inClientBounds = hasClientRect
                             && clientX >= clientRect.Left
                             && clientY >= clientRect.Top
                             && clientX < clientRect.Right
                             && clientY < clientRect.Bottom;
        var point = new NativePoint { X = clientX, Y = clientY };
        var converted = ClientToScreen(hwnd, ref point);
        var foregroundAfter = GetForegroundWindow();
        var foregroundUnchanged = foregroundAfter == foregroundBefore;
        var owned = targetRoot != nint.Zero
                    && targetPid == expectedPid
                    && inClientBounds
                    && converted
                    && foregroundUnchanged;

        return new DiagnosticPointOwnership(
            owned,
            clientX,
            clientY,
            point.X,
            point.Y,
            "0x0",
            $"0x{targetRoot:X}",
            $"0x{targetRoot:X}",
            targetPid,
            expectedPid,
            WasTopmost: false,
            TemporarilyRaised: false,
            Restored: true,
            ForegroundBefore: $"0x{foregroundBefore:X}",
            ForegroundRaised: false,
            ForegroundRestored: foregroundUnchanged,
            Reason: owned
                ? "background target hwnd/pid/client bounds owned; screen hit-test intentionally skipped"
                : $"background target rejected: pid={targetPid}, inBounds={inClientBounds}, converted={converted}, foregroundUnchanged={foregroundUnchanged}");
    }

    public static DiagnosticPointOwnership VerifyClientPointOwnership(
        nint hwnd,
        int clientX,
        int clientY,
        uint expectedPid)
    {
        var wasTopmost = (GetWindowLong(hwnd, GwlExStyle) & WsExTopmost) != 0;
        var temporarilyRaised = false;
        var restored = true;
        var converted = false;
        var point = new NativePoint { X = clientX, Y = clientY };
        var hit = nint.Zero;
        var root = nint.Zero;
        var targetRoot = nint.Zero;
        uint hitPid = 0;
        var foregroundBefore = GetForegroundWindow();
        var foregroundRaised = false;
        var foregroundRestored = true;
        try
        {
            if (!wasTopmost)
            {
                temporarilyRaised = SetWindowPos(
                    hwnd,
                    HwndTopmost,
                    0,
                    0,
                    0,
                    0,
                    SwpNoMove | SwpNoSize | SwpNoActivate);
                if (temporarilyRaised)
                    Thread.Sleep(60);
            }

            converted = ClientToScreen(hwnd, ref point);
            hit = converted ? WindowFromPoint(point) : nint.Zero;
            root = hit == nint.Zero ? nint.Zero : GetAncestor(hit, GaRoot);
            targetRoot = GetAncestor(hwnd, GaRoot);
            if (root != nint.Zero)
                _ = GetWindowThreadProcessId(root, out hitPid);

            if (root != targetRoot || hitPid != expectedPid)
            {
                foregroundRaised = SetForegroundWindow(hwnd);
                _ = BringWindowToTop(hwnd);
                Thread.Sleep(100);
                point = new NativePoint { X = clientX, Y = clientY };
                converted = ClientToScreen(hwnd, ref point);
                hit = converted ? WindowFromPoint(point) : nint.Zero;
                root = hit == nint.Zero ? nint.Zero : GetAncestor(hit, GaRoot);
                hitPid = 0;
                if (root != nint.Zero)
                    _ = GetWindowThreadProcessId(root, out hitPid);
            }
        }
        finally
        {
            if (temporarilyRaised && !wasTopmost)
            {
                restored = SetWindowPos(
                    hwnd,
                    HwndNoTopmost,
                    0,
                    0,
                    0,
                    0,
                    SwpNoMove | SwpNoSize | SwpNoActivate);
            }
            if (foregroundRaised && foregroundBefore != nint.Zero && foregroundBefore != hwnd)
            {
                _ = BringWindowToTop(foregroundBefore);
                foregroundRestored = SetForegroundWindow(foregroundBefore);
            }
        }

        var owned = converted
                    && root != nint.Zero
                    && targetRoot != nint.Zero
                    && root == targetRoot
                    && hitPid == expectedPid;
        return new DiagnosticPointOwnership(
            owned,
            clientX,
            clientY,
            point.X,
            point.Y,
            $"0x{hit:X}",
            $"0x{root:X}",
            $"0x{targetRoot:X}",
            hitPid,
            expectedPid,
            wasTopmost,
            temporarilyRaised,
            restored,
            $"0x{foregroundBefore:X}",
            foregroundRaised,
            foregroundRestored,
            converted ? (owned ? "owned" : "point belongs to another root window") : "ClientToScreen failed");
    }

    public static bool ActivateWindowForDiagnostic(nint hwnd)
    {
        if (!IsWindow(hwnd) || IsIconic(hwnd))
            return false;
        _ = BringWindowToTop(hwnd);
        var activated = SetForegroundWindow(hwnd);
        Thread.Sleep(60);
        return activated && GetForegroundWindow() == hwnd;
    }

    [DllImport("user32.dll", EntryPoint = "GetWindowLongW")]
    private static extern int GetWindowLong(nint hWnd, int index);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
