internal static class DiagnosticBackgroundMouseProbe
{
    private const uint WM_ACTIVATE = 0x0006;
    private const uint WM_SETFOCUS = 0x0007;
    private const uint WM_KILLFOCUS = 0x0008;
    private const uint WM_ACTIVATEAPP = 0x001C;
    private const uint WM_NCACTIVATE = 0x0086;
    private const uint WM_MOUSEMOVE = 0x0200;
    private const uint WM_LBUTTONDOWN = 0x0201;
    private const uint WM_LBUTTONUP = 0x0202;
    private const uint WA_INACTIVE = 0;
    private const uint WA_ACTIVE = 1;
    private const uint MK_LBUTTON = 0x0001;
    private const uint SMTO_ABORTIFHUNG = 0x0002;

    public static bool TryClick(
        nint hwnd,
        int x,
        int y,
        string strategy,
        int holdMs,
        Func<CaptureResult?> capturePressed,
        out CaptureResult? pressed,
        out string detail)
    {
        pressed = null;
        var foregroundBefore = GetForegroundWindow();
        var lParam = new nint((y << 16) | (x & 0xFFFF));
        var activated = strategy is "activate-post" or "activate-send";
        var moved = false;
        var down = false;
        var up = false;

        bool Dispatch(uint message, nint wParam) => strategy switch
        {
            "post-message" or "activate-post" => PostMessage(hwnd, message, wParam, lParam),
            "send-message" or "activate-send" => Send(hwnd, message, wParam, lParam),
            _ => false
        };

        try
        {
            if (activated)
            {
                _ = Send(hwnd, WM_ACTIVATEAPP, new nint(1), nint.Zero);
                _ = Send(hwnd, WM_NCACTIVATE, new nint(1), nint.Zero);
                _ = Send(hwnd, WM_ACTIVATE, new nint(WA_ACTIVE), nint.Zero);
                _ = Send(hwnd, WM_SETFOCUS, nint.Zero, nint.Zero);
            }

            moved = Dispatch(WM_MOUSEMOVE, nint.Zero);
            down = moved && Dispatch(WM_LBUTTONDOWN, new nint(MK_LBUTTON));
            if (down)
            {
                Thread.Sleep(holdMs);
                pressed = capturePressed();
            }
        }
        finally
        {
            if (down)
                up = Dispatch(WM_LBUTTONUP, nint.Zero);

            if (activated)
            {
                _ = Send(hwnd, WM_KILLFOCUS, foregroundBefore, nint.Zero);
                _ = Send(hwnd, WM_ACTIVATE, new nint(WA_INACTIVE), nint.Zero);
                _ = Send(hwnd, WM_NCACTIVATE, nint.Zero, nint.Zero);
                _ = Send(hwnd, WM_ACTIVATEAPP, nint.Zero, nint.Zero);
            }
        }

        var foregroundAfter = GetForegroundWindow();
        detail = $"strategy={strategy}, move={moved}, down={down}, up={up}, " +
                 $"pressedCaptured={pressed is not null}, foreground=0x{foregroundBefore:X}->0x{foregroundAfter:X}";
        return moved && down && up && foregroundBefore == foregroundAfter;
    }

    private static bool Send(nint hwnd, uint message, nint wParam, nint lParam) =>
        SendMessageTimeout(hwnd, message, wParam, lParam, SMTO_ABORTIFHUNG, 250, out _) != nint.Zero;

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool PostMessage(nint hwnd, uint message, nint wParam, nint lParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern nint SendMessageTimeout(
        nint hwnd,
        uint message,
        nint wParam,
        nint lParam,
        uint flags,
        uint timeout,
        out nint result);

    [DllImport("user32.dll")]
    private static extern nint GetForegroundWindow();
}

internal static class DiagnosticBackgroundKeyProbe
{
    private const uint WM_ACTIVATE = 0x0006;
    private const uint WM_SETFOCUS = 0x0007;
    private const uint WM_KILLFOCUS = 0x0008;
    private const uint WM_ACTIVATEAPP = 0x001C;
    private const uint WM_NCACTIVATE = 0x0086;
    private const uint WM_KEYDOWN = 0x0100;
    private const uint WM_KEYUP = 0x0101;
    private const uint WA_INACTIVE = 0;
    private const uint WA_ACTIVE = 1;
    private const uint MAPVK_VK_TO_VSC = 0;
    private const uint SMTO_ABORTIFHUNG = 0x0002;

    public static bool TrySend(nint hwnd, string hotkey, string strategy, out string detail)
    {
        if (!TryParseSingleKey(hotkey, out var vk))
        {
            detail = "诊断原生策略仅支持单键 F1-F24、A-Z、0-9。";
            return false;
        }

        var scan = MapVirtualKey(vk, MAPVK_VK_TO_VSC);
        var downParam = new nint(1L | ((long)scan << 16));
        var upParam = new nint(1L | ((long)scan << 16) | (1L << 30) | (1L << 31));
        var foregroundBefore = GetForegroundWindow();
        bool downOk;
        bool upOk;

        switch (strategy)
        {
            case "post-hold":
                downOk = PostMessage(hwnd, WM_KEYDOWN, new nint(vk), downParam);
                Thread.Sleep(50);
                upOk = PostMessage(hwnd, WM_KEYUP, new nint(vk), upParam);
                break;
            case "send-message":
                downOk = Send(hwnd, WM_KEYDOWN, new nint(vk), downParam);
                upOk = Send(hwnd, WM_KEYUP, new nint(vk), upParam);
                break;
            case "post-thread":
                var threadId = GetWindowThreadProcessId(hwnd, out _);
                downOk = threadId != 0 && PostThreadMessage(threadId, WM_KEYDOWN, new nint(vk), downParam);
                upOk = threadId != 0 && PostThreadMessage(threadId, WM_KEYUP, new nint(vk), upParam);
                break;
            case "activate-post":
                _ = Send(hwnd, WM_ACTIVATEAPP, new nint(1), nint.Zero);
                _ = Send(hwnd, WM_NCACTIVATE, new nint(1), nint.Zero);
                _ = Send(hwnd, WM_ACTIVATE, new nint(WA_ACTIVE), nint.Zero);
                _ = Send(hwnd, WM_SETFOCUS, nint.Zero, nint.Zero);
                downOk = PostMessage(hwnd, WM_KEYDOWN, new nint(vk), downParam);
                Thread.Sleep(50);
                upOk = PostMessage(hwnd, WM_KEYUP, new nint(vk), upParam);
                Thread.Sleep(100);
                _ = Send(hwnd, WM_KILLFOCUS, foregroundBefore, nint.Zero);
                _ = Send(hwnd, WM_ACTIVATE, new nint(WA_INACTIVE), nint.Zero);
                _ = Send(hwnd, WM_NCACTIVATE, nint.Zero, nint.Zero);
                _ = Send(hwnd, WM_ACTIVATEAPP, nint.Zero, nint.Zero);
                break;
            case "attach-focus-input":
                return TrySendWithAttachedFocus(hwnd, vk, foregroundBefore, out detail);
            default:
                detail = $"未知后台策略：{strategy}。";
                return false;
        }

        var foregroundAfter = GetForegroundWindow();
        detail = $"down={downOk}, up={upOk}, foreground=0x{foregroundBefore:X}->0x{foregroundAfter:X}";
        return downOk && upOk && foregroundBefore == foregroundAfter;
    }

    private static bool TrySendWithAttachedFocus(nint hwnd, uint vk, nint foregroundBefore, out string detail)
    {
        var currentThread = GetCurrentThreadId();
        var targetThread = GetWindowThreadProcessId(hwnd, out _);
        var foregroundThread = foregroundBefore == nint.Zero
            ? 0
            : GetWindowThreadProcessId(foregroundBefore, out _);
        var attachedTarget = false;
        var attachedForeground = false;
        nint previousFocus = nint.Zero;
        nint previousActive = nint.Zero;
        nint focusResult = nint.Zero;
        nint activeResult = nint.Zero;

        try
        {
            if (targetThread != 0 && targetThread != currentThread)
                attachedTarget = AttachThreadInput(currentThread, targetThread, true);
            if (foregroundThread != 0 && foregroundThread != currentThread && foregroundThread != targetThread)
                attachedForeground = AttachThreadInput(currentThread, foregroundThread, true);

            previousFocus = GetFocus();
            previousActive = GetActiveWindow();
            activeResult = SetActiveWindow(hwnd);
            focusResult = SetFocus(hwnd);
            Thread.Sleep(15);
            keybd_event((byte)vk, (byte)MapVirtualKey(vk, MAPVK_VK_TO_VSC), 0, UIntPtr.Zero);
            keybd_event((byte)vk, (byte)MapVirtualKey(vk, MAPVK_VK_TO_VSC), 0x0002, UIntPtr.Zero);
            Thread.Sleep(15);

            if (previousFocus != nint.Zero)
                _ = SetFocus(previousFocus);
            if (previousActive != nint.Zero)
                _ = SetActiveWindow(previousActive);
        }
        finally
        {
            if (attachedForeground)
                _ = AttachThreadInput(currentThread, foregroundThread, false);
            if (attachedTarget)
                _ = AttachThreadInput(currentThread, targetThread, false);
        }

        var foregroundAfter = GetForegroundWindow();
        detail = $"attachTarget={attachedTarget}, attachForeground={attachedForeground}, active=0x{activeResult:X}, focus=0x{focusResult:X}, foreground=0x{foregroundBefore:X}->0x{foregroundAfter:X}";
        return attachedTarget && foregroundBefore == foregroundAfter;
    }

    private static bool TryParseSingleKey(string value, out uint vk)
    {
        var key = value.Trim().ToUpperInvariant();
        if (key.Length == 1 && key[0] is >= 'A' and <= 'Z' or >= '0' and <= '9')
        {
            vk = key[0];
            return true;
        }

        if (key.StartsWith('F') && int.TryParse(key[1..], out var f) && f is >= 1 and <= 24)
        {
            vk = (uint)(0x70 + f - 1);
            return true;
        }

        vk = 0;
        return false;
    }

    private static bool Send(nint hwnd, uint message, nint wParam, nint lParam) =>
        SendMessageTimeout(hwnd, message, wParam, lParam, SMTO_ABORTIFHUNG, 250, out _) != nint.Zero;

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool PostMessage(nint hwnd, uint message, nint wParam, nint lParam);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool PostThreadMessage(uint threadId, uint message, nint wParam, nint lParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern nint SendMessageTimeout(
        nint hwnd,
        uint message,
        nint wParam,
        nint lParam,
        uint flags,
        uint timeout,
        out nint result);

    [DllImport("user32.dll")]
    private static extern uint GetWindowThreadProcessId(nint hwnd, out uint processId);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool AttachThreadInput(uint attachThreadId, uint attachToThreadId, bool attach);

    [DllImport("kernel32.dll")]
    private static extern uint GetCurrentThreadId();

    [DllImport("user32.dll")]
    private static extern nint SetFocus(nint hwnd);

    [DllImport("user32.dll")]
    private static extern nint GetFocus();

    [DllImport("user32.dll")]
    private static extern nint SetActiveWindow(nint hwnd);

    [DllImport("user32.dll")]
    private static extern nint GetActiveWindow();

    [DllImport("user32.dll")]
    private static extern void keybd_event(byte virtualKey, byte scanCode, uint flags, UIntPtr extraInfo);

    [DllImport("user32.dll")]
    private static extern uint MapVirtualKey(uint code, uint mapType);

    [DllImport("user32.dll")]
    private static extern nint GetForegroundWindow();
}

