internal sealed class AuditedInputService : IInputService
{
    private readonly IInputService _inner;
    private readonly object _gate = new();
    private readonly List<string> _sentHotkeys = new();
    private readonly List<ClientClick> _clicks = new();

    public AuditedInputService(IInputService inner)
    {
        _inner = inner;
    }

    public int SendKeyCount { get; private set; }
    public int SendTextCount { get; private set; }
    public int ClickCount { get; private set; }

    public InputDispatchMode DefaultDispatchMode
    {
        get => _inner.DefaultDispatchMode;
        set => _inner.DefaultDispatchMode = value;
    }

    public bool YieldToUserInput
    {
        get => _inner.YieldToUserInput;
        set => _inner.YieldToUserInput = value;
    }

    public int UserInputYieldMs
    {
        get => _inner.UserInputYieldMs;
        set => _inner.UserInputYieldMs = value;
    }

    public InputYieldStatus GetYieldStatus(nint hwnd, InputDispatchMode mode) =>
        _inner.GetYieldStatus(hwnd, mode);

    public bool TryParseHotkey(string hotkey, out string error) => _inner.TryParseHotkey(hotkey, out error);

    public bool SendKey(nint hwnd, string hotkey)
    {
        var ok = _inner.SendKey(hwnd, hotkey);
        RecordKey(hotkey);
        return ok;
    }

    public bool SendKey(nint hwnd, string hotkey, InputDispatchMode mode)
    {
        var ok = _inner.SendKey(hwnd, hotkey, mode);
        RecordKey(hotkey);
        return ok;
    }

    public bool SendText(nint hwnd, string text)
    {
        var ok = _inner.SendText(hwnd, text);
        RecordText();
        return ok;
    }

    public bool SendText(nint hwnd, string text, InputDispatchMode mode)
    {
        var ok = _inner.SendText(hwnd, text, mode);
        RecordText();
        return ok;
    }

    public bool Click(nint hwnd, int x, int y)
    {
        var ok = _inner.Click(hwnd, x, y);
        RecordClick(x, y, InputMouseButton.Left);
        return ok;
    }

    public bool Click(nint hwnd, int x, int y, InputDispatchMode mode)
    {
        var ok = _inner.Click(hwnd, x, y, mode);
        RecordClick(x, y, InputMouseButton.Left);
        return ok;
    }

    public bool Click(nint hwnd, int x, int y, InputDispatchMode mode, InputMouseButton button)
    {
        var ok = _inner.Click(hwnd, x, y, mode, button);
        RecordClick(x, y, button);
        return ok;
    }

    public bool TryConsumeGlobalCooldown(int cooldownMs) => _inner.TryConsumeGlobalCooldown(cooldownMs);

    public InputAudit Snapshot()
    {
        lock (_gate)
            return new InputAudit(SendKeyCount, SendTextCount, ClickCount, _sentHotkeys.ToArray(), _clicks.ToArray());
    }

    private void RecordKey(string hotkey)
    {
        lock (_gate)
        {
            SendKeyCount++;
            _sentHotkeys.Add(hotkey);
        }
    }

    private void RecordText()
    {
        lock (_gate)
            SendTextCount++;
    }

    private void RecordClick(int x, int y, InputMouseButton button)
    {
        lock (_gate)
        {
            ClickCount++;
            _clicks.Add(new ClientClick(x, y, button.ToString()));
        }
    }
}

internal sealed class CountingInputService : IInputService
{
    private readonly object _gate = new();
    private readonly List<string> _sentHotkeys = new();
    private readonly List<string> _sentTexts = new();
    private readonly List<(int X, int Y, InputMouseButton Button)> _clicks = new();

    public int SendKeyCount { get; private set; }
    public int SendTextCount { get; private set; }
    public int ClickCount { get; private set; }
    public bool GlobalCooldownAvailable { get; set; } = true;
    public int GlobalCooldownRequests { get; private set; }
    public IReadOnlyList<string> SentHotkeys { get { lock (_gate) return _sentHotkeys.ToArray(); } }
    public IReadOnlyList<string> SentTexts { get { lock (_gate) return _sentTexts.ToArray(); } }
    public IReadOnlyList<(int X, int Y, InputMouseButton Button)> Clicks { get { lock (_gate) return _clicks.ToArray(); } }
    public InputDispatchMode DefaultDispatchMode { get; set; }
    public bool YieldToUserInput { get; set; }
    public int UserInputYieldMs { get; set; } = 1500;
    public InputYieldStatus GetYieldStatus(nint hwnd, InputDispatchMode mode) =>
        new(
            Enabled: YieldToUserInput,
            CanReadLastInput: false,
            ShouldYield: false,
            YieldMs: UserInputYieldMs,
            LastInputAgeMs: -1,
            RemainingYieldMs: 0,
            OwnRecentAutomationInput: false,
            TargetForeground: false,
            CursorInsideClient: false,
            TargetActive: false,
            Scope: "counting-input",
            Reason: "计数输入服务不读取 Windows 最近输入状态。");

    public bool TryParseHotkey(string hotkey, out string error)
    {
        error = string.Empty;
        return !string.IsNullOrWhiteSpace(hotkey);
    }

    public bool SendKey(nint hwnd, string hotkey)
    {
        lock (_gate)
        {
            _sentHotkeys.Add(hotkey);
            SendKeyCount++;
        }
        return true;
    }

    public bool SendKey(nint hwnd, string hotkey, InputDispatchMode mode)
    {
        DefaultDispatchMode = mode;
        lock (_gate)
        {
            _sentHotkeys.Add(hotkey);
            SendKeyCount++;
        }
        return true;
    }

    public bool SendText(nint hwnd, string text)
    {
        lock (_gate)
        {
            _sentTexts.Add(text);
            SendTextCount++;
        }
        return true;
    }

    public bool SendText(nint hwnd, string text, InputDispatchMode mode)
    {
        DefaultDispatchMode = mode;
        lock (_gate)
        {
            _sentTexts.Add(text);
            SendTextCount++;
        }
        return true;
    }

    public bool Click(nint hwnd, int x, int y)
    {
        lock (_gate)
        {
            _clicks.Add((x, y, InputMouseButton.Left));
            ClickCount++;
        }
        return true;
    }

    public bool Click(nint hwnd, int x, int y, InputDispatchMode mode)
        => Click(hwnd, x, y, mode, InputMouseButton.Left);

    public bool Click(nint hwnd, int x, int y, InputDispatchMode mode, InputMouseButton button)
    {
        DefaultDispatchMode = mode;
        lock (_gate)
        {
            _clicks.Add((x, y, button));
            ClickCount++;
        }
        return true;
    }

    public bool TryConsumeGlobalCooldown(int cooldownMs)
    {
        lock (_gate)
        {
            GlobalCooldownRequests++;
        }
        return GlobalCooldownAvailable;
    }
}

