    public RuntimePerceptionSnapshot Read(
        BoundGameWindow window,
        GlobalConfig config,
        bool includeOpenText = false)
    {
        var sequence = frames.CurrentSequence;
        var semantic = semanticAtObservation(Interlocked.Increment(ref _observationCount));
        return new RuntimePerceptionSnapshot
        {
            FrameSequence = sequence,
            Width = Math.Max(1, window.ClientWidth),
            Height = Math.Max(1, window.ClientHeight),
            SystemFeedback = new SystemFeedbackPerception
            {
                FrameSequence = sequence,
                Available = true,
                Observations = new[]
                {
                    new SystemFeedbackObservation(
                        sequence,
                        new VisionBox(160, 20, 80, 20),
                        1,
                        new OpenTextResult(
                            semantic.ToString(),
                            1,
                            OpenTextSlot.Toast,
                            PerceptionSourceKind.OpenText,
                            "synthetic"),
                        semantic.ToString(),
                        semantic,
                        DateTimeOffset.UtcNow)
                },
                ModelVersion = "synthetic-system-feedback-l1-v2",
                Source = PerceptionSourceKind.Fused,
                Message = "synthetic current-frame feedback"
            }
        };
    }
}

