internal sealed class SyntheticBagInteractionControlCatalogService : IInteractionControlCatalogService
{
    public SyntheticBagInteractionControlCatalogService(bool runtimeAuthorized)
    {
        RuntimeAuthorized = runtimeAuthorized;
    }

    public bool IsAvailable => true;
    public bool RuntimeAuthorized { get; }
    public string AssetVersion => "synthetic-bag-controls-v3";
    public string Message => RuntimeAuthorized ? "authorized diagnostic catalog" : "observation only";

    public InteractionPanelControlLayout Map(long frameSequence, InteractionWindowDetection panel)
    {
        const int gridX = 50;
        const int gridY = 70;
        const int cellSize = 32;
        const int gap = 4;
        var cells = Enumerable.Range(0, 60)
            .Select(index =>
            {
                var row = index / 10;
                var column = index % 10;
                var box = new VisionBox(
                    gridX + column * (cellSize + gap),
                    gridY + row * (cellSize + gap),
                    cellSize,
                    cellSize);
                return new InteractionGridCellCandidate
                {
                    RegionId = "bag_cells",
                    Row = row,
                    Column = column,
                    CellBox = box,
                    SafeClickBox = new VisionBox(box.X + 5, box.Y + 5, box.Width - 10, box.Height - 10),
                    ClickX = box.X + box.Width / 2,
                    ClickY = box.Y + box.Height / 2,
                    IsDisabled = !RuntimeAuthorized
                };
            })
            .ToArray();
        return new InteractionPanelControlLayout
        {
            FrameSequence = frameSequence,
            PanelClass = panel.ClassName,
            PanelBox = panel.Box,
            PanelConfidence = panel.Confidence,
            Regions = new[]
            {
                new InteractionRegionCandidate
                {
                    RegionId = "bag_cells",
                    DisplayName = "背包格子",
                    Kind = "regular_grid",
                    Box = new VisionBox(gridX, gridY, 356, 212),
                    Rows = 6,
                    Columns = 10,
                    Cells = cells,
                    FailurePolicy = "unknown_blocks_action"
                }
            },
            RuntimeAuthorized = RuntimeAuthorized,
            AssetVersion = AssetVersion,
            Message = Message
        };
    }

    public bool TryRenderDebugOverlay(
        CaptureResult frame,
        IReadOnlyList<InteractionPanelControlLayout> layouts,
        string outputPath,
        out string error)
    {
        error = "synthetic catalog does not render overlays";
        return false;
    }
}

