internal sealed class SyntheticWindowCaptureService : IWindowCaptureService
{
    private readonly CaptureResult _client;

    public SyntheticWindowCaptureService(
        int width,
        int height,
        CombatRecognitionConfig config,
        int targetHpPercent = 63,
        int playerHpPercent = 80,
        int playerMpPercent = 70,
        int petHpPercent = 55,
        bool useMismatchedStatusColors = false)
    {
        var pixels = new byte[width * height * 4];
        _client = new CaptureResult(width, height, pixels);
        if (useMismatchedStatusColors)
        {
            FillStatusBar(config.TargetHp, targetHpPercent, r: 40, g: 80, b: 190);
            FillStatusBar(config.PlayerHp, playerHpPercent, r: 190, g: 40, b: 35);
            FillStatusBar(config.PlayerMp, playerMpPercent, r: 190, g: 40, b: 35);
            FillStatusBar(config.PetHp, petHpPercent, r: 190, g: 40, b: 35);
            return;
        }

        FillStatusBar(config.TargetHp, targetHpPercent, r: 190, g: 40, b: 35);
        FillStatusBar(config.PlayerHp, playerHpPercent, r: 190, g: 40, b: 35);
        FillStatusBar(config.PlayerMp, playerMpPercent, r: 40, g: 80, b: 190);
        FillStatusBar(config.PetHp, petHpPercent, r: 190, g: 40, b: 35);
    }

    public CaptureResult? CaptureClient(nint hwnd) => _client;
    public CaptureResult? CaptureRegion(nint hwnd, int x, int y, int w, int h) => null;
    public CaptureResult? CaptureAvatar(nint hwnd) => null;

    private void FillStatusBar(OcrRegionConfig region, int percent, byte r, byte g, byte b)
    {
        var resolved = OcrRegionProjection.Resolve(region, _client.Width, _client.Height);
        if (resolved.IsEmpty)
            return;

        var fillWidth = Math.Clamp((int)Math.Round(resolved.Width * percent / 100.0), 0, resolved.Width);
        for (var y = resolved.Y; y < resolved.Y + resolved.Height; y++)
        {
            for (var x = resolved.X; x < resolved.X + fillWidth; x++)
            {
                var p = (y * _client.Width + x) * 4;
                _client.Pixels[p] = b;
                _client.Pixels[p + 1] = g;
                _client.Pixels[p + 2] = r;
                _client.Pixels[p + 3] = 255;
            }
        }
    }
}

